    fn run_static_prn_dc_plan(
        &self,
        deck: &XyceDeck,
        plan: XyceExecutionPlan,
        start: Instant,
    ) -> XyceTestResult {
        let contract = if !plan.reference_path.is_file()
            && (!plan.measurement_reference_paths.is_empty()
                || !plan.continuous_measurement_reference_paths.is_empty())
        {
            "wrapper_scalar_measure_dc"
        } else {
            plan.contract.result_contract(false)
        };
        let netlist = match Self::parse_netlist_with_expression_dialect_and_execution_dir(
            &plan.source,
            &plan.deck_path,
            plan.expression_dialect,
            plan.execution_dir.as_deref(),
        ) {
            Ok(netlist) => netlist,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("parse failed after contract validation: {err}"),
                    Vec::new(),
                );
            }
        };

        let reference = if !plan.reference_path.is_file()
            || matches!(
                plan.contract,
                XyceStaticDcContract::WrapperFilePrn | XyceStaticDcContract::WrapperNoOutput
            ) {
            None
        } else {
            match Self::parse_dc_reference_file(plan.contract, &plan.reference_path) {
                Ok(reference) => Some(reference),
                Err(err) if Self::is_parameter_sweep_summary_reference(&plan.reference_path) => {
                    return self.expected_unsupported_result(
                        deck,
                        start,
                        "unsupported_xyce_oracle",
                        &format!(
                            "checked-in Xyce sidecar is a parameter-sweep summary, not a numeric .PRINT table: {err}"
                        ),
                    );
                }
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("failed to parse Xyce reference oracle: {err}"),
                        Vec::new(),
                    );
                }
            }
        };

        if !plan.steps.is_empty() {
            return if let Some(reference) = reference {
                self.run_static_prn_step_dc_plan(deck, plan, netlist, reference, start)
            } else if !plan.measurement_reference_paths.is_empty() {
                self.run_static_step_dc_measurement_plan(deck, plan, netlist, start)
            } else {
                self.failure_result(
                    deck,
                    start,
                    contract,
                    "file-output-only .STEP DC comparison is not implemented".to_string(),
                    Vec::new(),
                )
            };
        }

        if let Some(dc_data) = &plan.dc_data {
            let results = match self.run_static_dc_data_results(&netlist, dc_data, start) {
                Ok(results) => results,
                Err(SimulationError::Aborted) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!(
                            "simulation exceeded timeout ({}ms)",
                            self.config.max_time_per_test_ms
                        ),
                        Vec::new(),
                    );
                }
                Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                    return self.expected_unsupported_result(
                        deck,
                        start,
                        "unsupported_xyce_runtime",
                        &format!("RSpice runtime does not yet support this deck: {err}"),
                    );
                }
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("simulation error: {err}"),
                        Vec::new(),
                    );
                }
            };
            let mut mismatches = if let Some(reference) = reference.as_ref() {
                match self.compare_dc_data_prn_reference(
                    reference,
                    &plan.print,
                    &plan.source,
                    &plan.dc,
                    &results,
                ) {
                    Ok(mismatches) => mismatches,
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            contract,
                            format!("reference comparison error: {err}"),
                            Vec::new(),
                        );
                    }
                }
            } else {
                Vec::new()
            };
            if mismatches.is_empty() && !plan.measurement_reference_paths.is_empty() {
                let measurement_sweep = results
                    .iter()
                    .map(|row| (row.point.sweep_value, row.point.result.clone()))
                    .collect::<Vec<_>>();
                let point_params = results
                    .iter()
                    .map(|row| row.netlist.params.clone())
                    .collect::<Vec<_>>();
                let measurements =
                    crate::analysis::advanced::evaluate_dc_measurements_with_parameter_contexts(
                        &netlist,
                        &measurement_sweep,
                        &point_params,
                    );
                match self.compare_measurement_references(
                    &plan.measurement_reference_paths,
                    &measurements,
                    plan.measurement_tolerance,
                    netlist.options.measure_fail_output,
                    netlist.options.measure_default_value,
                    "DC",
                    &netlist.measurements,
                ) {
                    Ok(measurement_mismatches) => mismatches.extend(measurement_mismatches),
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            contract,
                            format!("DC DATA measurement reference comparison error: {err}"),
                            Vec::new(),
                        );
                    }
                }
            }
            return if mismatches.is_empty() {
                self.passed_result(deck, start, contract)
            } else {
                self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("{} Xyce reference mismatch(es)", mismatches.len()),
                    mismatches,
                )
            };
        }

        let engine = self.create_dc_engine();
        let abort = DeadlineAbort::new(start, self.config.max_time_per_test_ms.max(1));
        let results = match engine.run_dc_sweep2_spec_with_report_and_abort(
            &netlist,
            &plan.dc.source,
            &plan.dc.primary_spec(),
            plan.dc.sweep2.as_ref(),
            &abort,
        ) {
            Ok(results) => results,
            Err(SimulationError::Aborted) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        "simulation exceeded timeout ({}ms)",
                        self.config.max_time_per_test_ms
                    ),
                    Vec::new(),
                );
            }
            Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                return self.expected_unsupported_result(
                    deck,
                    start,
                    "unsupported_xyce_runtime",
                    &format!("RSpice runtime does not yet support this deck: {err}"),
                );
            }
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("simulation error: {err}"),
                    Vec::new(),
                );
            }
        };

        let mismatches = if let Some(reference) = &reference {
            match self.compare_dc_prn_reference(
                reference,
                &plan.print,
                &netlist,
                &plan.source,
                &plan.dc,
                &results,
            ) {
                Ok(mismatches) => mismatches,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("reference comparison error: {err}"),
                        Vec::new(),
                    );
                }
            }
        } else {
            Vec::new()
        };

        if mismatches.is_empty()
            && (!plan.measurement_reference_paths.is_empty()
                || !plan.continuous_measurement_reference_paths.is_empty())
        {
            let measurement_sweep = results
                .iter()
                .map(|point| (point.sweep_value, point.result.clone()))
                .collect::<Vec<_>>();
            let measurements = if netlist
                .analyses
                .iter()
                .any(|analysis| matches!(analysis, AnalysisCommand::Dc { .. }))
            {
                crate::analysis::advanced::evaluate_dc_measurements(&netlist, &measurement_sweep)
            } else {
                crate::analysis::advanced::unevaluated_measurements(
                    &netlist,
                    "DC",
                    "DC measurement requires an explicit .DC analysis",
                )
            };
            let continuous = crate::analysis::advanced::evaluate_dc_continuous_measurements(
                &netlist,
                &measurement_sweep,
            );
            let measurement_mismatches = match self.compare_analysis_measurement_outputs(
                &plan.measurement_reference_paths,
                &plan.continuous_measurement_reference_paths,
                &measurements,
                &continuous,
                plan.measurement_tolerance,
                netlist.options.measure_fail_output,
                netlist.options.measure_default_value,
                netlist.options.measure_use_cont_files(),
                &netlist.measurements,
                "DC",
                "DC_CONT",
            ) {
                Ok(mismatches) => mismatches,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("DC measurement reference comparison error: {err}"),
                        Vec::new(),
                    );
                }
            };
            if !measurement_mismatches.is_empty() {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        "{} Xyce DC measurement mismatch(es)",
                        measurement_mismatches.len()
                    ),
                    measurement_mismatches,
                );
            }
        }

        if mismatches.is_empty()
            && matches!(plan.contract, XyceStaticDcContract::WrapperGnuplotSplot)
        {
            let batches = [XyceDcResultBatch {
                netlist: netlist.clone(),
                results: results.clone(),
            }];
            let side_mismatches =
                match self.compare_gnuplot_splot_side_output_batches(&plan, &batches) {
                    Ok(mismatches) => mismatches,
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            contract,
                            format!("GNUPLOT/SPLOT side-output comparison error: {err}"),
                            Vec::new(),
                        );
                    }
                };
            if !side_mismatches.is_empty() {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        "{} Xyce GNUPLOT/SPLOT side-output mismatch(es)",
                        side_mismatches.len()
                    ),
                    side_mismatches,
                );
            }
        }

        if mismatches.is_empty()
            && !matches!(plan.contract, XyceStaticDcContract::WrapperGnuplotSplot)
        {
            let batches = [XyceDcResultBatch {
                netlist: netlist.clone(),
                results: results.clone(),
            }];
            let side_mismatches =
                match self.compare_prn_compatible_side_output_batches(&plan, &batches) {
                    Ok(mismatches) => mismatches,
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            contract,
                            format!("PRN-compatible side-output comparison error: {err}"),
                            Vec::new(),
                        );
                    }
                };
            if !side_mismatches.is_empty() {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        "{} Xyce PRN-compatible side-output mismatch(es)",
                        side_mismatches.len()
                    ),
                    side_mismatches,
                );
            }
        }

        if mismatches.is_empty() {
            self.passed_result(deck, start, contract)
        } else {
            self.failure_result(
                deck,
                start,
                contract,
                format!("{} Xyce reference mismatch(es)", mismatches.len()),
                mismatches,
            )
        }
    }

    fn run_noindex_header_tran_wrapper_plan(
        &self,
        deck: &XyceDeck,
        plan: &XyceStaticTranPlan,
        start: Instant,
    ) -> XyceTestResult {
        let contract = plan.result_contract();
        if !plan.steps.is_empty() {
            return self.failure_result(
                deck,
                start,
                contract,
                "NOINDEX header-only transient wrapper contract does not cover .STEP output"
                    .to_string(),
                Vec::new(),
            );
        }

        // The authoritative wrapper still requires a successful simulator run,
        // but deliberately ignores every numeric output row.
        match self.run_transient_family_plan(plan, start, None) {
            Ok((_netlist, _result)) => {}
            Err(SimulationError::Aborted) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        "simulation exceeded timeout ({}ms)",
                        self.config.max_time_per_test_ms
                    ),
                    Vec::new(),
                );
            }
            Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                return self.expected_unsupported_result(
                    deck,
                    start,
                    "unsupported_xyce_runtime",
                    &format!("RSpice runtime does not yet support this transient deck: {err}"),
                );
            }
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("simulation error: {err}"),
                    Vec::new(),
                );
            }
        }

        let header = Self::transient_prn_header_columns(&plan.print, false).join("   ");
        if let Err(err) = Self::validate_noindex_tran_prn_header(&header) {
            return self.failure_result(
                deck,
                start,
                contract,
                format!("NOINDEX transient output header error: {err}"),
                Vec::new(),
            );
        }

        self.passed_result(deck, start, contract)
    }

    fn run_static_prn_tran_plan(
        &self,
        deck: &XyceDeck,
        plan: XyceStaticTranPlan,
        start: Instant,
    ) -> XyceTestResult {
        let contract = plan.result_contract();
        if matches!(plan.contract, XyceStaticTranContract::WrapperNoIndexHeader) {
            return self.run_noindex_header_tran_wrapper_plan(deck, &plan, start);
        }
        let netlist = match Self::parse_xyce_netlist(&plan.source, &plan.deck_path) {
            Ok(netlist) => netlist,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("parse failed after contract validation: {err}"),
                    Vec::new(),
                );
            }
        };

        let reference_result = match plan.comparison_mode {
            XyceStaticTranComparisonMode::Release710IntegratedRms { .. }
            | XyceStaticTranComparisonMode::Release710IntegratedRmsComp { .. } => {
                Self::parse_xyce_verify_tran_reference_file(&plan.reference_path)
            }
            XyceStaticTranComparisonMode::Pointwise => {
                Self::parse_tran_reference_file(plan.contract, &plan.reference_path)
            }
        };
        let reference = match reference_result {
            Ok(reference) => reference,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("failed to parse Xyce transient oracle: {err}"),
                    Vec::new(),
                );
            }
        };
        if !plan.steps.is_empty() {
            return self.run_static_prn_step_tran_plan(deck, plan, netlist, reference, start);
        }
        let reference_time_grid = match Self::reference_time_grid(&reference) {
            Ok(grid) => grid,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("reference time-grid error: {err}"),
                    Vec::new(),
                );
            }
        };
        let tran = Self::tran_analysis_for_reference_stop(
            plan.contract,
            plan.tran,
            reference_time_grid.as_slice(),
        );

        let max_step =
            match Self::transient_max_step_for_static_plan(&plan, &netlist, &tran, &reference) {
                Ok(max_step) => max_step,
                Err(err)
                    if !plan.comparison_mode.uses_adaptive_grid_only()
                        && err.contains("transient harness execution envelope") =>
                {
                    return self.expected_unsupported_result(
                        deck,
                        start,
                        "unsupported_xyce_contract",
                        &err,
                    );
                }
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("transient maximum-step or execution-envelope error: {err}"),
                        Vec::new(),
                    );
                }
            };

        let initial_step = Self::xyce_initial_timestep_for_tran(&plan.tran);
        let engine = self.create_xyce_static_tran_engine(None, initial_step);
        let abort = DeadlineAbort::new(start, self.config.max_time_per_test_ms.max(1));
        let mut best_mismatches = None;
        let mut simulation_error = None;
        match engine.run_tran_with_abort(&netlist, tran.stop, max_step, &abort) {
            Ok(result) => {
                let mismatches = match self
                    .compare_static_tran_primary_reference(&reference, &plan, &netlist, &result)
                {
                    Ok(mismatches) => mismatches,
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            contract,
                            format!("reference comparison error: {err}"),
                            Vec::new(),
                        );
                    }
                };

                if mismatches.is_empty() {
                    return self.passed_or_tran_side_output_failure(
                        deck, start, contract, &plan, &netlist, &result,
                    );
                }

                if plan.comparison_mode.uses_adaptive_grid_only() {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!(
                            "{} Xyce integrated-RMS transient reference mismatch(es)",
                            mismatches.len()
                        ),
                        mismatches,
                    );
                }

                best_mismatches = Some(mismatches);
            }
            Err(SimulationError::Aborted) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        "simulation exceeded timeout ({}ms)",
                        self.config.max_time_per_test_ms
                    ),
                    Vec::new(),
                );
            }
            Err(err)
                if !plan.comparison_mode.uses_adaptive_grid_only()
                    && Self::is_expected_unsupported_runtime_error(&err) =>
            {
                return self.expected_unsupported_result(
                    deck,
                    start,
                    "unsupported_xyce_runtime",
                    &format!("RSpice runtime does not yet support this transient deck: {err}"),
                );
            }
            Err(err) => {
                simulation_error = Some(format!("simulation error: {err}"));
            }
        }

        if plan.comparison_mode.uses_adaptive_grid_only() {
            return self.failure_result(
                deck,
                start,
                contract,
                simulation_error.unwrap_or_else(|| {
                    "adaptive integrated-RMS transient execution produced no comparable result"
                        .to_string()
                }),
                Vec::new(),
            );
        }

        let capacitor_branch_print =
            Self::transient_print_requests_linear_capacitor_branch_quantity(&netlist, &plan.print);
        let mut fallback_errors = Vec::new();

        let locked_engine =
            self.create_xyce_static_tran_engine(Some(reference_time_grid.clone()), initial_step);
        match locked_engine.run_tran_with_abort(&netlist, tran.stop, max_step, &abort) {
            Ok(locked_result) => {
                match self.compare_tran_prn_reference(
                    &reference,
                    &plan.print,
                    &netlist,
                    &plan.source,
                    &locked_result,
                    plan.wrapper_tolerance,
                ) {
                    Ok(locked_mismatches) => {
                        if locked_mismatches.is_empty() {
                            return self.passed_or_tran_side_output_failure(
                                deck,
                                start,
                                contract,
                                &plan,
                                &netlist,
                                &locked_result,
                            );
                        }
                        if Self::candidate_mismatches_are_better(
                            best_mismatches.as_deref(),
                            &locked_mismatches,
                        ) {
                            best_mismatches = Some(locked_mismatches);
                        }
                    }
                    Err(err) => {
                        fallback_errors.push(format!(
                            "locked time-grid reference comparison error: {err}"
                        ));
                    }
                }
            }
            Err(SimulationError::Aborted) => {
                fallback_errors.push(format!(
                    "locked time-grid simulation exceeded timeout ({}ms)",
                    self.config.max_time_per_test_ms
                ));
            }
            Err(err) => {
                fallback_errors.push(format!("locked time-grid simulation error: {err}"));
            }
        }

        if !capacitor_branch_print {
            let backward_euler_engine = self
                .create_xyce_static_tran_engine_with_integration_method(
                    Some(reference_time_grid.clone()),
                    crate::analysis::IntegrationMethod::BackwardEuler,
                    initial_step,
                );
            match backward_euler_engine.run_tran_with_abort(&netlist, tran.stop, max_step, &abort) {
                Ok(backward_euler_result) => {
                    match self.compare_tran_prn_reference(
                        &reference,
                        &plan.print,
                        &netlist,
                        &plan.source,
                        &backward_euler_result,
                        plan.wrapper_tolerance,
                    ) {
                        Ok(backward_euler_mismatches) => {
                            if backward_euler_mismatches.is_empty() {
                                return self.passed_or_tran_side_output_failure(
                                    deck,
                                    start,
                                    contract,
                                    &plan,
                                    &netlist,
                                    &backward_euler_result,
                                );
                            }
                            if Self::candidate_mismatches_are_better(
                                best_mismatches.as_deref(),
                                &backward_euler_mismatches,
                            ) {
                                best_mismatches = Some(backward_euler_mismatches);
                            }
                        }
                        Err(err) => {
                            fallback_errors
                                .push(format!("backward-Euler reference comparison error: {err}"));
                        }
                    }
                }
                Err(SimulationError::Aborted) => {
                    fallback_errors.push(format!(
                        "backward-Euler simulation exceeded timeout ({}ms)",
                        self.config.max_time_per_test_ms
                    ));
                }
                Err(err) => {
                    fallback_errors.push(format!("backward-Euler simulation error: {err}"));
                }
            }
        }

        if plan.timeint_conststep && !capacitor_branch_print {
            let gear12_engine = self.create_xyce_static_tran_engine_with_integration_method(
                Some(reference_time_grid),
                crate::analysis::IntegrationMethod::Gear2,
                initial_step,
            );
            match gear12_engine.run_tran_with_abort(&netlist, tran.stop, max_step, &abort) {
                Ok(gear12_result) => {
                    match self.compare_tran_prn_reference(
                        &reference,
                        &plan.print,
                        &netlist,
                        &plan.source,
                        &gear12_result,
                        plan.wrapper_tolerance,
                    ) {
                        Ok(gear12_mismatches) => {
                            if gear12_mismatches.is_empty() {
                                return self.passed_or_tran_side_output_failure(
                                    deck,
                                    start,
                                    contract,
                                    &plan,
                                    &netlist,
                                    &gear12_result,
                                );
                            }
                            if Self::candidate_mismatches_are_better(
                                best_mismatches.as_deref(),
                                &gear12_mismatches,
                            ) {
                                best_mismatches = Some(gear12_mismatches);
                            }
                        }
                        Err(err) => {
                            fallback_errors
                                .push(format!("Xyce Gear12 reference comparison error: {err}"));
                        }
                    }
                }
                Err(SimulationError::Aborted) => {
                    fallback_errors.push(format!(
                        "Xyce Gear12 simulation exceeded timeout ({}ms)",
                        self.config.max_time_per_test_ms
                    ));
                }
                Err(err) => {
                    fallback_errors.push(format!("Xyce Gear12 simulation error: {err}"));
                }
            }
        }

        if let Some(best_mismatches) = best_mismatches {
            self.failure_result(
                deck,
                start,
                contract,
                format!(
                    "{} Xyce transient reference mismatch(es)",
                    best_mismatches.len()
                ),
                best_mismatches,
            )
        } else {
            let mut message = simulation_error.unwrap_or_else(|| {
                "transient simulation produced no comparable result".to_string()
            });
            if !fallback_errors.is_empty() {
                message.push_str("; ");
                message.push_str(&fallback_errors.join("; "));
            }
            self.failure_result(deck, start, contract, message, Vec::new())
        }
    }

    fn run_static_prn_step_tran_plan(
        &self,
        deck: &XyceDeck,
        plan: XyceStaticTranPlan,
        netlist: Netlist,
        reference: XycePrnTable,
        start: Instant,
    ) -> XyceTestResult {
        let contract = plan.result_contract();
        let expansion_engine = self.create_xyce_engine();
        let step_runs =
            match Self::nested_step_runs_for_commands(&expansion_engine, &netlist, &plan.steps) {
                Ok(runs) => runs,
                Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                    return self.expected_unsupported_result(
                        deck,
                        start,
                        "unsupported_xyce_runtime",
                        &format!("RSpice runtime does not yet support this .STEP TRAN deck: {err}"),
                    );
                }
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!(".STEP expansion error: {err}"),
                        Vec::new(),
                    );
                }
            };

        let step_references =
            match Self::split_transient_step_reference(&reference, step_runs.len()) {
                Ok(references) => references,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("stepped transient oracle error: {err}"),
                        Vec::new(),
                    );
                }
            };

        let abort = DeadlineAbort::new(start, self.config.max_time_per_test_ms.max(1));
        let mismatches =
            match self.compare_step_tran_runs(&plan, &step_runs, &step_references, &abort, false) {
                Ok(mismatches) => {
                    if mismatches.is_empty() {
                        return self.passed_or_step_tran_side_output_failure(
                            deck, start, contract, &plan, &step_runs, &abort, false,
                        );
                    }
                    Some(mismatches)
                }
                Err(err) if err.starts_with("UNSUPPORTED:") => {
                    return self.expected_unsupported_result(
                        deck,
                        start,
                        "unsupported_xyce_runtime",
                        err.trim_start_matches("UNSUPPORTED:").trim(),
                    );
                }
                Err(err) => {
                    let locked_result = self.compare_step_tran_runs(
                        &plan,
                        &step_runs,
                        &step_references,
                        &abort,
                        true,
                    );
                    return match locked_result {
                        Ok(locked_mismatches) if locked_mismatches.is_empty() => self
                            .passed_or_step_tran_side_output_failure(
                                deck, start, contract, &plan, &step_runs, &abort, true,
                            ),
                        Ok(locked_mismatches) => self.failure_result(
                            deck,
                            start,
                            contract,
                            format!(
                                "{} Xyce stepped transient reference mismatch(es)",
                                locked_mismatches.len()
                            ),
                            locked_mismatches,
                        ),
                        Err(locked_err) => self.failure_result(
                            deck,
                            start,
                            contract,
                            format!("{err}; locked time-grid retry failed: {locked_err}"),
                            Vec::new(),
                        ),
                    };
                }
            };

        let mismatches = mismatches.expect("non-empty adaptive mismatches");

        if let Ok(locked_mismatches) =
            self.compare_step_tran_runs(&plan, &step_runs, &step_references, &abort, true)
        {
            if locked_mismatches.is_empty() {
                return self.passed_or_step_tran_side_output_failure(
                    deck, start, contract, &plan, &step_runs, &abort, true,
                );
            }
            if Self::candidate_mismatches_are_better(Some(&mismatches), &locked_mismatches) {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        "{} Xyce stepped transient reference mismatch(es)",
                        locked_mismatches.len()
                    ),
                    locked_mismatches,
                );
            }
        }

        self.failure_result(
            deck,
            start,
            contract,
            format!(
                "{} Xyce stepped transient reference mismatch(es)",
                mismatches.len()
            ),
            mismatches,
        )
    }

    fn candidate_mismatches_are_better(
        current_best: Option<&[XyceValueMismatch]>,
        candidate: &[XyceValueMismatch],
    ) -> bool {
        let Some(best) = current_best else {
            return true;
        };
        if candidate.len() != best.len() {
            return candidate.len() < best.len();
        }

        let candidate_max = Self::mismatch_max_relative_error(candidate);
        let best_max = Self::mismatch_max_relative_error(best);
        if candidate_max != best_max {
            return candidate_max < best_max;
        }

        Self::mismatch_relative_error_sum(candidate) < Self::mismatch_relative_error_sum(best)
    }

    fn mismatch_max_relative_error(mismatches: &[XyceValueMismatch]) -> f64 {
        mismatches
            .iter()
            .map(|mismatch| mismatch.relative_error)
            .filter(|value| value.is_finite())
            .fold(0.0, f64::max)
    }

    fn mismatch_relative_error_sum(mismatches: &[XyceValueMismatch]) -> f64 {
        mismatches
            .iter()
            .map(|mismatch| mismatch.relative_error)
            .filter(|value| value.is_finite())
            .sum()
    }

    fn compare_step_tran_runs(
        &self,
        plan: &XyceStaticTranPlan,
        step_runs: &[XyceStepRun],
        step_references: &[XycePrnTable],
        abort: &dyn AbortSignal,
        locked_time_grid: bool,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        self.compare_step_tran_runs_with_print(
            plan,
            &plan.print,
            step_runs,
            step_references,
            abort,
            locked_time_grid,
        )
    }

    fn compare_step_tran_runs_with_print(
        &self,
        plan: &XyceStaticTranPlan,
        print: &XycePrintRequest,
        step_runs: &[XyceStepRun],
        step_references: &[XycePrnTable],
        abort: &dyn AbortSignal,
        locked_time_grid: bool,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        let mut mismatches = Vec::new();
        let mut row_offset = 0usize;
        for (step_index, (run, reference)) in
            step_runs.iter().zip(step_references.iter()).enumerate()
        {
            let max_step =
                Self::transient_max_step_for_reference(&run.netlist, &plan.tran, reference)
                    .map_err(|err| {
                        if err.contains("transient harness execution envelope") {
                            format!("UNSUPPORTED: {err}")
                        } else {
                            format!("reference time-grid error: step {}: {err}", step_index + 1)
                        }
                    })?;
            let engine = if locked_time_grid {
                self.create_xyce_engine_with_locked_time_grid(Some(Self::reference_time_grid(
                    reference,
                )?))
            } else {
                self.create_xyce_engine()
            };
            let result = match engine.run_tran_with_abort(
                &run.netlist,
                plan.tran.stop,
                max_step,
                abort,
            ) {
                Ok(result) => result,
                Err(SimulationError::Aborted) => {
                    return Err(format!(
                        "simulation exceeded timeout ({}ms)",
                        self.config.max_time_per_test_ms
                    ));
                }
                Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                    return Err(format!(
                        "UNSUPPORTED: RSpice runtime does not yet support this .STEP TRAN deck: {err}"
                    ));
                }
                Err(err) => {
                    return Err(format!("simulation error: step {}: {err}", step_index + 1));
                }
            };

            let mut step_mismatches = self
                .compare_tran_prn_reference(
                    reference,
                    print,
                    &run.netlist,
                    &plan.source,
                    &result,
                    plan.wrapper_tolerance,
                )
                .map_err(|err| {
                    format!("reference comparison error: step {}: {err}", step_index + 1)
                })?;
            for mismatch in &mut step_mismatches {
                mismatch.row += row_offset;
            }
            mismatches.extend(step_mismatches);
            if mismatches.len() >= self.config.max_mismatches {
                mismatches.truncate(self.config.max_mismatches);
                return Ok(mismatches);
            }
            row_offset += reference.rows.len();
        }
        Ok(mismatches)
    }

    fn passed_or_tran_side_output_failure(
        &self,
        deck: &XyceDeck,
        start: Instant,
        contract: &str,
        plan: &XyceStaticTranPlan,
        netlist: &Netlist,
        result: &TransientResult,
    ) -> XyceTestResult {
        match self.compare_tran_side_outputs(plan, netlist, result) {
            Ok(mismatches) if mismatches.is_empty() => self.passed_result(deck, start, contract),
            Ok(mismatches) => self.failure_result(
                deck,
                start,
                contract,
                format!(
                    "{} Xyce transient side-output mismatch(es)",
                    mismatches.len()
                ),
                mismatches,
            ),
            Err(err) => self.failure_result(
                deck,
                start,
                contract,
                format!("transient side-output comparison error: {err}"),
                Vec::new(),
            ),
        }
    }

    fn passed_or_step_tran_side_output_failure(
        &self,
        deck: &XyceDeck,
        start: Instant,
        contract: &str,
        plan: &XyceStaticTranPlan,
        step_runs: &[XyceStepRun],
        abort: &dyn AbortSignal,
        locked_time_grid: bool,
    ) -> XyceTestResult {
        match self.compare_step_tran_side_outputs(plan, step_runs, abort, locked_time_grid) {
            Ok(mismatches) if mismatches.is_empty() => self.passed_result(deck, start, contract),
            Ok(mismatches) => self.failure_result(
                deck,
                start,
                contract,
                format!(
                    "{} Xyce stepped transient side-output mismatch(es)",
                    mismatches.len()
                ),
                mismatches,
            ),
            Err(err) => self.failure_result(
                deck,
                start,
                contract,
                format!("stepped transient side-output comparison error: {err}"),
                Vec::new(),
            ),
        }
    }

    fn compare_tran_side_outputs(
        &self,
        plan: &XyceStaticTranPlan,
        netlist: &Netlist,
        result: &TransientResult,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        if plan.output_override {
            return Ok(Vec::new());
        }
        let side_outputs = Self::prn_compatible_tran_side_output_requests(&plan.source)?;
        let mut all_mismatches = Vec::new();
        for request in side_outputs {
            let file = request
                .file
                .as_deref()
                .expect("side output request has FILE= set");
            let reference_path = Self::side_output_reference_path(&plan.reference_path, file)?;
            let reference = Self::parse_prn_file(&reference_path).map_err(|err| {
                format!(
                    "failed to parse transient side-output oracle {}: {err}",
                    self.display_path(&reference_path)
                )
            })?;
            let print = XycePrintRequest {
                probes: request.probes,
            };
            let mut mismatches = self.compare_tran_prn_reference(
                &reference,
                &print,
                netlist,
                &plan.source,
                result,
                plan.wrapper_tolerance,
            )?;
            for mismatch in &mut mismatches {
                mismatch.probe = format!("{file}:{}", mismatch.probe);
            }
            all_mismatches.extend(mismatches);
            if all_mismatches.len() >= self.config.max_mismatches {
                all_mismatches.truncate(self.config.max_mismatches);
                break;
            }
        }
        Ok(all_mismatches)
    }

    fn compare_step_tran_side_outputs(
        &self,
        plan: &XyceStaticTranPlan,
        step_runs: &[XyceStepRun],
        abort: &dyn AbortSignal,
        locked_time_grid: bool,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        if plan.output_override {
            return Ok(Vec::new());
        }
        let side_outputs = Self::prn_compatible_tran_side_output_requests(&plan.source)?;
        let mut all_mismatches = Vec::new();
        for request in side_outputs {
            let file = request
                .file
                .as_deref()
                .expect("side output request has FILE= set");
            let reference_path = Self::side_output_reference_path(&plan.reference_path, file)?;
            let reference = Self::parse_prn_file(&reference_path).map_err(|err| {
                format!(
                    "failed to parse transient side-output oracle {}: {err}",
                    self.display_path(&reference_path)
                )
            })?;
            let step_references = Self::split_transient_step_reference(&reference, step_runs.len())
                .map_err(|err| format!("{file}: {err}"))?;
            let print = XycePrintRequest {
                probes: request.probes,
            };
            let mut mismatches = self.compare_step_tran_runs_with_print(
                plan,
                &print,
                step_runs,
                &step_references,
                abort,
                locked_time_grid,
            )?;
            for mismatch in &mut mismatches {
                mismatch.probe = format!("{file}:{}", mismatch.probe);
            }
            all_mismatches.extend(mismatches);
            if all_mismatches.len() >= self.config.max_mismatches {
                all_mismatches.truncate(self.config.max_mismatches);
                break;
            }
        }
        Ok(all_mismatches)
    }

    fn split_transient_step_reference(
        reference: &XycePrnTable,
        expected_steps: usize,
    ) -> Result<Vec<XycePrnTable>, String> {
        if expected_steps == 0 {
            return Err(".STEP expansion produced no runs".to_string());
        }
        if expected_steps == 1 {
            return Ok(vec![reference.clone()]);
        }
        let time_column = Self::reference_time_column_index(reference)
            .ok_or_else(|| "stepped transient reference table has no TIME column".to_string())?;
        let mut starts = vec![0usize];
        let mut previous_time = None;
        for (row_index, row) in reference.rows.iter().enumerate() {
            let time = *row.get(time_column).ok_or_else(|| {
                format!("row {row_index} has no TIME column at index {time_column}")
            })?;
            if !time.is_finite() {
                return Err(format!("row {row_index} has non-finite TIME value {time}"));
            }
            if let Some(previous) = previous_time
                && time < previous
            {
                starts.push(row_index);
            }
            previous_time = Some(time);
        }
        starts.push(reference.rows.len());
        let actual_steps = starts.len().saturating_sub(1);
        if actual_steps != expected_steps {
            return Err(format!(
                "reference contains {actual_steps} transient step table(s), but .STEP expansion produced {expected_steps} run(s)"
            ));
        }

        let mut references = Vec::with_capacity(expected_steps);
        for range in starts.windows(2) {
            let start = range[0];
            let end = range[1];
            if start == end {
                return Err("stepped transient reference contains an empty step table".to_string());
            }
            let reference = XycePrnTable {
                columns: reference.columns.clone(),
                rows: reference.rows[start..end].to_vec(),
            };
            Self::validate_transient_stepnum_column(&reference, references.len())?;
            references.push(reference);
        }
        Ok(references)
    }

    fn split_ac_step_reference(
        reference: &XycePrnTable,
        expected_steps: usize,
        points_per_step: usize,
    ) -> Result<Vec<XycePrnTable>, String> {
        if expected_steps == 0 {
            return Err(".STEP expansion produced no runs".to_string());
        }
        if points_per_step == 0 {
            return Err("AC analysis produced no frequency points".to_string());
        }
        if expected_steps == 1 {
            return Ok(vec![reference.clone()]);
        }
        let expected_rows = expected_steps
            .checked_mul(points_per_step)
            .ok_or_else(|| "stepped AC row count overflow".to_string())?;
        if reference.rows.len() != expected_rows {
            return Err(format!(
                "reference contains {} AC row(s), but .STEP expansion produced {expected_steps} run(s) with {points_per_step} frequency point(s) each",
                reference.rows.len()
            ));
        }

        let mut references = Vec::with_capacity(expected_steps);
        for step_index in 0..expected_steps {
            let start = step_index * points_per_step;
            let end = start + points_per_step;
            references.push(XycePrnTable {
                columns: reference.columns.clone(),
                rows: reference.rows[start..end].to_vec(),
            });
        }
        Ok(references)
    }

    fn validate_transient_stepnum_column(
        reference: &XycePrnTable,
        expected_step_index: usize,
    ) -> Result<(), String> {
        let layout = Self::transient_reference_layout(reference)?;
        let Some(stepnum_column) = layout.stepnum_column else {
            return Ok(());
        };
        let expected_step_index = expected_step_index as Value;
        for (row_index, row) in reference.rows.iter().enumerate() {
            let stepnum = *row.get(stepnum_column).ok_or_else(|| {
                format!("row {row_index} has no STEPNUM column at index {stepnum_column}")
            })?;
            if !stepnum.is_finite() {
                return Err(format!(
                    "row {row_index} has non-finite STEPNUM value {stepnum}"
                ));
            }
            if (stepnum - expected_step_index).abs() > f64::EPSILON {
                return Err(format!(
                    "row {row_index} has STEPNUM {stepnum}, expected {expected_step_index}"
                ));
            }
        }
        Ok(())
    }

    fn compare_gnuplot_splot_side_output_batches(
        &self,
        plan: &XyceExecutionPlan,
        batches: &[XyceDcResultBatch],
    ) -> Result<Vec<XyceValueMismatch>, String> {
        let (_, side) = Self::gnuplot_splot_print_pair(&plan.source)?;
        if side.probes != plan.print.probes {
            return Err("SPLOT side-output probes differ from primary GNUPLOT probes".to_string());
        }
        let file = side
            .file
            .as_deref()
            .ok_or_else(|| "SPLOT side-output request has no FILE= target".to_string())?;
        let side_reference_path =
            Self::side_output_reference_candidate(&plan.reference_path, file)?;
        let reference_path = if side_reference_path.is_file() {
            side_reference_path
        } else {
            plan.reference_path.clone()
        };
        let reference = Self::parse_prn_file(&reference_path).map_err(|err| {
            format!(
                "failed to parse SPLOT side-output oracle {}: {err}",
                self.display_path(&reference_path)
            )
        })?;
        let side_print = XycePrintRequest {
            probes: side.probes,
        };
        let mut mismatches = self.compare_dc_prn_reference_batches(
            &reference,
            &side_print,
            &plan.source,
            &plan.dc,
            batches,
        )?;
        for mismatch in &mut mismatches {
            mismatch.probe = format!("{file}:{}", mismatch.probe);
        }
        Ok(mismatches)
    }

    fn compare_prn_compatible_side_output_batches(
        &self,
        plan: &XyceExecutionPlan,
        batches: &[XyceDcResultBatch],
    ) -> Result<Vec<XyceValueMismatch>, String> {
        let side_outputs = Self::prn_compatible_side_output_requests(&plan.source)?;
        let mut all_mismatches = Vec::new();
        for request in side_outputs {
            let file = request
                .file
                .as_deref()
                .expect("side output request has FILE= set");
            let reference_path = Self::side_output_reference_path(&plan.reference_path, file)?;
            let reference = Self::parse_prn_file(&reference_path).map_err(|err| {
                format!(
                    "failed to parse side-output oracle {}: {err}",
                    self.display_path(&reference_path)
                )
            })?;
            let print = XycePrintRequest {
                probes: request.probes,
            };
            let mut mismatches = self.compare_dc_prn_reference_batches(
                &reference,
                &print,
                &plan.source,
                &plan.dc,
                batches,
            )?;
            for mismatch in &mut mismatches {
                mismatch.probe = format!("{file}:{}", mismatch.probe);
            }
            all_mismatches.extend(mismatches);
            if all_mismatches.len() >= self.config.max_mismatches {
                all_mismatches.truncate(self.config.max_mismatches);
                break;
            }
        }
        Ok(all_mismatches)
    }

    fn prn_compatible_side_output_requests(
        source: &str,
    ) -> Result<Vec<XycePrintOutputRequest>, String> {
        Ok(Self::dc_print_output_requests(source)?
            .into_iter()
            .filter(|request| {
                request.file.is_some()
                    && Self::dc_print_format_is_prn_compatible(
                        request.format.as_deref().unwrap_or("STD"),
                    )
            })
            .collect())
    }

    fn prn_compatible_tran_side_output_requests(
        source: &str,
    ) -> Result<Vec<XycePrintOutputRequest>, String> {
        Ok(Self::aggregate_print_output_requests(
            Self::print_output_requests(source, "TRAN")?,
            "TRAN",
        )?
        .into_iter()
        .filter(|request| {
            request.file.is_some()
                && Self::tran_print_format_is_prn_compatible(
                    request.format.as_deref().unwrap_or("STD"),
                )
        })
        .collect())
    }

    fn prn_compatible_ac_side_output_requests(
        source: &str,
    ) -> Result<Vec<XycePrintOutputRequest>, String> {
        Ok(
            Self::aggregate_print_output_requests(
                Self::print_output_requests(source, "AC")?,
                "AC",
            )?
            .into_iter()
            .filter(|request| {
                request.file.is_some()
                    && Self::ac_print_format_is_prn_compatible(
                        request.format.as_deref().unwrap_or("STD"),
                    )
            })
            .collect(),
        )
    }

    fn side_output_reference_path(reference_path: &Path, file: &str) -> Result<PathBuf, String> {
        let candidate = Self::side_output_reference_candidate(reference_path, file)?;
        if !candidate.is_file() {
            return Err(format!(
                "missing checked-in side-output oracle {}",
                candidate.display()
            ));
        }
        Ok(candidate)
    }

    fn side_output_reference_path_for_deck(
        &self,
        deck_path: &Path,
        file: &str,
    ) -> Result<PathBuf, String> {
        let anchor = self
            .static_output_reference_path(deck_path, "anchor")
            .ok_or_else(|| "deck is not under tests/xyce/Netlists".to_string())?;
        Self::side_output_reference_path(&anchor, file)
    }

    fn ac_side_output_reference_path(
        reference_path: &Path,
        request: &XycePrintOutputRequest,
        file: &str,
    ) -> Result<PathBuf, String> {
        let candidate = Self::side_output_reference_candidate(reference_path, file)?;
        if candidate.is_file() {
            return Ok(candidate);
        }
        let format = request.format.as_deref().unwrap_or("STD");
        if format.eq_ignore_ascii_case("GNUPLOT") || format.eq_ignore_ascii_case("SPLOT") {
            return Ok(reference_path.to_path_buf());
        }
        Err(format!(
            "missing checked-in side-output oracle {}",
            candidate.display()
        ))
    }

    fn side_output_reference_candidate(
        reference_path: &Path,
        file: &str,
    ) -> Result<PathBuf, String> {
        let side_path = Path::new(file);
        if side_path.is_absolute() {
            return Err(format!(
                "absolute FILE= side-output path '{}' cannot be mapped into the vendored OutputData tree",
                file
            ));
        }
        let parent = reference_path
            .parent()
            .ok_or_else(|| "primary reference path has no parent directory".to_string())?;
        Ok(parent.join(side_path))
    }

    fn run_static_prn_step_dc_plan(
        &self,
        deck: &XyceDeck,
        plan: XyceExecutionPlan,
        netlist: Netlist,
        reference: XycePrnTable,
        start: Instant,
    ) -> XyceTestResult {
        let contract = plan.contract.result_contract(true);
        let engine = self.create_dc_engine();
        let step_runs = match Self::nested_step_runs_for_commands(&engine, &netlist, &plan.steps) {
            Ok(runs) => runs,
            Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                return self.expected_unsupported_result(
                    deck,
                    start,
                    "unsupported_xyce_runtime",
                    &format!("RSpice runtime does not yet support this .STEP deck: {err}"),
                );
            }
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(".STEP expansion error: {err}"),
                    Vec::new(),
                );
            }
        };

        if plan.contract.compares_step_res_reference() {
            if let Some(res_reference_path) =
                Self::step_res_reference_path(&plan.deck_path, &plan.reference_path)
            {
                if let Err(err) = self.compare_step_res_reference(
                    &res_reference_path,
                    &netlist,
                    &plan.steps,
                    &step_runs,
                ) {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("Xyce .STEP result summary comparison error: {err}"),
                        Vec::new(),
                    );
                }
            }
        }

        let abort = DeadlineAbort::new(start, self.config.max_time_per_test_ms.max(1));
        let mut batches = Vec::with_capacity(step_runs.len());
        for run in step_runs {
            let results = match engine.run_dc_sweep2_spec_with_report_and_abort(
                &run.netlist,
                &plan.dc.source,
                &plan.dc.primary_spec(),
                plan.dc.sweep2.as_ref(),
                &abort,
            ) {
                Ok(results) => results,
                Err(SimulationError::Aborted) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!(
                            "simulation exceeded timeout ({}ms)",
                            self.config.max_time_per_test_ms
                        ),
                        Vec::new(),
                    );
                }
                Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                    return self.expected_unsupported_result(
                        deck,
                        start,
                        "unsupported_xyce_runtime",
                        &format!("RSpice runtime does not yet support this .STEP deck: {err}"),
                    );
                }
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!("simulation error: {err}"),
                        Vec::new(),
                    );
                }
            };
            batches.push(XyceDcResultBatch {
                netlist: run.netlist,
                results,
            });
        }

        let mismatches = match self.compare_dc_prn_reference_batches(
            &reference,
            &plan.print,
            &plan.source,
            &plan.dc,
            &batches,
        ) {
            Ok(mismatches) => mismatches,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!("reference comparison error: {err}"),
                    Vec::new(),
                );
            }
        };

        if mismatches.is_empty()
            && matches!(plan.contract, XyceStaticDcContract::WrapperGnuplotSplot)
        {
            let side_mismatches =
                match self.compare_gnuplot_splot_side_output_batches(&plan, &batches) {
                    Ok(mismatches) => mismatches,
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            contract,
                            format!("GNUPLOT/SPLOT side-output comparison error: {err}"),
                            Vec::new(),
                        );
                    }
                };
            if !side_mismatches.is_empty() {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(
                        "{} Xyce GNUPLOT/SPLOT side-output mismatch(es)",
                        side_mismatches.len()
                    ),
                    side_mismatches,
                );
            }
        }

        if mismatches.is_empty() {
            if !matches!(plan.contract, XyceStaticDcContract::WrapperGnuplotSplot) {
                let side_mismatches =
                    match self.compare_prn_compatible_side_output_batches(&plan, &batches) {
                        Ok(mismatches) => mismatches,
                        Err(err) => {
                            return self.failure_result(
                                deck,
                                start,
                                contract,
                                format!("PRN-compatible side-output comparison error: {err}"),
                                Vec::new(),
                            );
                        }
                    };
                if !side_mismatches.is_empty() {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!(
                            "{} Xyce PRN-compatible side-output mismatch(es)",
                            side_mismatches.len()
                        ),
                        side_mismatches,
                    );
                }
            }
            return self.passed_result(deck, start, contract);
        }

        self.failure_result(
            deck,
            start,
            contract,
            format!("{} Xyce reference mismatch(es)", mismatches.len()),
            mismatches,
        )
    }

    fn run_static_step_dc_measurement_plan(
        &self,
        deck: &XyceDeck,
        plan: XyceExecutionPlan,
        netlist: Netlist,
        start: Instant,
    ) -> XyceTestResult {
        let contract = "wrapper_scalar_measure_step_dc";
        let engine = self.create_dc_engine();
        let step_runs = match Self::nested_step_runs_for_commands(&engine, &netlist, &plan.steps) {
            Ok(runs) => runs,
            Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                return self.expected_unsupported_result(
                    deck,
                    start,
                    "unsupported_xyce_runtime",
                    &format!("RSpice runtime does not yet support this .STEP DC deck: {err}"),
                );
            }
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    contract,
                    format!(".STEP expansion error: {err}"),
                    Vec::new(),
                );
            }
        };
        if step_runs.len() != plan.measurement_reference_paths.len() {
            return self.failure_result(
                deck,
                start,
                contract,
                format!(
                    ".STEP expansion produced {} batches but {} contiguous measurement artifacts exist",
                    step_runs.len(),
                    plan.measurement_reference_paths.len()
                ),
                Vec::new(),
            );
        }

        let abort = DeadlineAbort::new(start, self.config.max_time_per_test_ms.max(1));
        let mut all_mismatches = Vec::new();
        for (step_index, (run, reference_path)) in step_runs
            .iter()
            .zip(&plan.measurement_reference_paths)
            .enumerate()
        {
            let (measurement_sweep, point_params) = if let Some(dc_data) = &plan.dc_data {
                match self.run_static_dc_data_results(&run.netlist, dc_data, start) {
                    Ok(results) => (
                        results
                            .iter()
                            .map(|row| (row.point.sweep_value, row.point.result.clone()))
                            .collect::<Vec<_>>(),
                        results
                            .iter()
                            .map(|row| row.netlist.params.clone())
                            .collect::<Vec<_>>(),
                    ),
                    Err(SimulationError::Aborted) => {
                        return self.failure_result(
                            deck,
                            start,
                            contract,
                            format!(
                                "simulation exceeded timeout ({}ms)",
                                self.config.max_time_per_test_ms
                            ),
                            Vec::new(),
                        );
                    }
                    Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                        return self.expected_unsupported_result(
                            deck,
                            start,
                            "unsupported_xyce_runtime",
                            &format!(
                                "RSpice runtime does not yet support DC DATA step {}: {err}",
                                step_index + 1
                            ),
                        );
                    }
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            contract,
                            format!("simulation error in DC DATA step {}: {err}", step_index + 1),
                            Vec::new(),
                        );
                    }
                }
            } else {
                match engine.run_dc_sweep2_spec_with_report_and_abort(
                    &run.netlist,
                    &plan.dc.source,
                    &plan.dc.primary_spec(),
                    plan.dc.sweep2.as_ref(),
                    &abort,
                ) {
                    Ok(results) => (
                        results
                            .iter()
                            .map(|point| (point.sweep_value, point.result.clone()))
                            .collect::<Vec<_>>(),
                        Vec::new(),
                    ),
                    Err(SimulationError::Aborted) => {
                        return self.failure_result(
                            deck,
                            start,
                            contract,
                            format!(
                                "simulation exceeded timeout ({}ms)",
                                self.config.max_time_per_test_ms
                            ),
                            Vec::new(),
                        );
                    }
                    Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                        return self.expected_unsupported_result(
                            deck,
                            start,
                            "unsupported_xyce_runtime",
                            &format!(
                                "RSpice runtime does not yet support DC step {}: {err}",
                                step_index + 1
                            ),
                        );
                    }
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            contract,
                            format!("simulation error in DC step {}: {err}", step_index + 1),
                            Vec::new(),
                        );
                    }
                }
            };
            let measurements = if plan.dc_data.is_some()
                || run
                    .netlist
                    .analyses
                    .iter()
                    .any(|analysis| matches!(analysis, AnalysisCommand::Dc { .. }))
            {
                if point_params.is_empty() {
                    crate::analysis::advanced::evaluate_dc_measurements(
                        &run.netlist,
                        &measurement_sweep,
                    )
                } else {
                    crate::analysis::advanced::evaluate_dc_measurements_with_parameter_contexts(
                        &run.netlist,
                        &measurement_sweep,
                        &point_params,
                    )
                }
            } else {
                crate::analysis::advanced::unevaluated_measurements(
                    &run.netlist,
                    "DC",
                    "DC measurement requires an explicit .DC analysis",
                )
            };
            let continuous = if point_params.is_empty() {
                crate::analysis::advanced::evaluate_dc_continuous_measurements(
                    &run.netlist,
                    &measurement_sweep,
                )
            } else {
                crate::analysis::advanced::evaluate_dc_continuous_measurements_with_parameter_contexts(
                    &run.netlist,
                    &measurement_sweep,
                    &point_params,
                )
            };
            let mut mismatches = match self.compare_analysis_measurement_outputs(
                std::slice::from_ref(reference_path),
                &[],
                &measurements,
                &continuous,
                plan.measurement_tolerance,
                run.netlist.options.measure_fail_output,
                run.netlist.options.measure_default_value,
                run.netlist.options.measure_use_cont_files(),
                &run.netlist.measurements,
                "DC",
                "DC_CONT",
            ) {
                Ok(mismatches) => mismatches,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        contract,
                        format!(
                            "DC measurement comparison error in step {}: {err}",
                            step_index + 1
                        ),
                        Vec::new(),
                    );
                }
            };
            for mismatch in &mut mismatches {
                mismatch.probe = format!("step[{}]:{}", step_index + 1, mismatch.probe);
            }
            all_mismatches.extend(mismatches);
            if all_mismatches.len() >= self.config.max_mismatches {
                all_mismatches.truncate(self.config.max_mismatches);
                break;
            }
        }

        if all_mismatches.is_empty() {
            self.passed_result(deck, start, contract)
        } else {
            self.failure_result(
                deck,
                start,
                contract,
                format!(
                    "{} Xyce stepped DC measurement mismatch(es)",
                    all_mismatches.len()
                ),
                all_mismatches,
            )
        }
    }

    fn nested_step_runs_for_commands(
        engine: &Engine,
        netlist: &Netlist,
        steps: &[StepCommand],
    ) -> Result<Vec<XyceStepRun>, SimulationError> {
        let mut runs = vec![XyceStepRunBuilder {
            step_values: Vec::new(),
            bindings: Vec::new(),
        }];

        for step in steps {
            let values = Self::step_values_for_expansion(netlist, step)?;
            if values.is_empty() {
                return Err(SimulationError::Circuit(
                    ".STEP produced no sweep values".to_string(),
                ));
            }

            let mut next_runs = Vec::with_capacity(runs.len() * values.len());
            for value in values {
                for run in &runs {
                    let mut step_values = run.step_values.clone();
                    step_values.push(value);
                    let mut bindings = run.bindings.clone();
                    bindings.push(XyceStepBinding {
                        step: step.clone(),
                        value,
                    });
                    next_runs.push(XyceStepRunBuilder {
                        step_values,
                        bindings,
                    });
                }
            }
            runs = next_runs;
        }

        runs.into_iter()
            .map(|run| {
                let netlist = Self::materialize_nested_step_run(engine, netlist, &run.bindings)?;
                Ok(XyceStepRun {
                    step_values: run.step_values,
                    netlist,
                })
            })
            .collect()
    }

    fn step_values_for_expansion(
        netlist: &Netlist,
        step: &StepCommand,
    ) -> Result<Vec<Value>, SimulationError> {
        match &step.sweep {
            StepSweep::Data { table_name } => {
                let table = netlist
                    .data_tables
                    .iter()
                    .find(|table| table.name.eq_ignore_ascii_case(table_name))
                    .ok_or_else(|| {
                        SimulationError::Circuit(format!(
                            ".STEP DATA table '{table_name}' not found"
                        ))
                    })?;
                if table.params.is_empty() {
                    return Err(SimulationError::Circuit(format!(
                        ".STEP DATA table '{}' has no parameter columns",
                        table.name
                    )));
                }
                if table.rows.is_empty() {
                    return Err(SimulationError::Circuit(format!(
                        ".STEP DATA table '{}' has no rows",
                        table.name
                    )));
                }
                Ok((0..table.rows.len()).map(|idx| idx as Value).collect())
            }
            _ => Ok(step.sweep.values()),
        }
    }

    fn materialize_nested_step_run(
        engine: &Engine,
        netlist: &Netlist,
        bindings: &[XyceStepBinding],
    ) -> Result<Netlist, SimulationError> {
        let param_overrides = bindings
            .iter()
            .filter(|binding| {
                binding.step.target == StepTarget::Param
                    && !matches!(binding.step.sweep, StepSweep::Data { .. })
            })
            .map(|binding| (binding.step.name.clone(), binding.value))
            .collect::<Vec<_>>();

        let mut run_netlist = if param_overrides.is_empty() {
            netlist.clone()
        } else {
            Engine::create_perturbed_netlist_multi(netlist, &param_overrides)?.0
        };

        for binding in bindings {
            if binding.step.target == StepTarget::Param
                && !matches!(binding.step.sweep, StepSweep::Data { .. })
            {
                continue;
            }
            run_netlist = Self::materialize_nonparam_step_binding(engine, &run_netlist, binding)?;
        }

        Ok(run_netlist)
    }

    fn materialize_nonparam_step_binding(
        engine: &Engine,
        netlist: &Netlist,
        binding: &XyceStepBinding,
    ) -> Result<Netlist, SimulationError> {
        let expanded = if matches!(binding.step.sweep, StepSweep::Data { .. }) {
            engine.step_netlists_for_command(netlist, &binding.step, &[])?
        } else {
            engine.step_netlists_for_command(netlist, &binding.step, &[binding.value])?
        };

        if let Some((_, stepped_netlist)) = expanded
            .into_iter()
            .find(|(value, _)| (*value - binding.value).abs() <= Value::EPSILON)
        {
            return Ok(stepped_netlist);
        }

        Err(SimulationError::Circuit(format!(
            ".STEP expansion for {} did not produce requested value {}",
            Self::step_res_variable_name(&binding.step),
            binding.value
        )))
    }

    fn baseline_family_analysis_for_path(
        &self,
        baseline_path: &Path,
    ) -> Result<XyceBaselineFamilyAnalysis, String> {
        let source = fs::read_to_string(baseline_path)
            .map_err(|err| format!("failed to read baseline deck: {err}"))?;
        let ac_outputs = Self::print_output_requests(&source, "AC")?
            .into_iter()
            .filter(|request| request.file.is_none())
            .count();
        let dc_outputs = Self::print_output_requests(&source, "DC")?
            .into_iter()
            .filter(|request| request.file.is_none())
            .count();
        let tran_outputs = Self::print_output_requests(&source, "TRAN")?
            .into_iter()
            .filter(|request| request.file.is_none())
            .count();

        match (ac_outputs, dc_outputs, tran_outputs) {
            (1, 0, 0) => Ok(XyceBaselineFamilyAnalysis::Ac),
            (0, 1, 0) => Ok(XyceBaselineFamilyAnalysis::Dc),
            (0, 0, 1) => Ok(XyceBaselineFamilyAnalysis::Tran),
            (0, 0, 0) => Err(
                "deck has neither one primary .PRINT AC, one primary .PRINT DC, nor one primary .PRINT TRAN output"
                    .to_string(),
            ),
            (ac, dc, tran) => Err(format!(
                "deck has {ac} primary .PRINT AC output(s), {dc} primary .PRINT DC output(s), and {tran} primary .PRINT TRAN output(s); family analysis selection requires exactly one unambiguous primary output"
            )),
        }
    }

    fn baseline_family_targets(contract: &XyceBaselineFamilyContract) -> (Vec<PathBuf>, bool) {
        let baseline_record = contract
            .target_path
            .as_ref()
            .is_some_and(|target| Self::same_path(target, &contract.baseline_path));
        let targets = if let Some(target_path) = contract.target_path.as_ref()
            && !baseline_record
        {
            vec![target_path.clone()]
        } else {
            contract
                .member_paths
                .iter()
                .filter(|path| !Self::same_path(path, &contract.baseline_path))
                .cloned()
                .collect()
        };
        (targets, baseline_record)
    }

    fn transient_family_plan_purpose_for_path(
        &self,
        kind: XyceBaselineFamilyKind,
        path: &Path,
    ) -> XyceStaticTranPlanPurpose {
        if kind == XyceBaselineFamilyKind::TransientAnalysisExpression
            && self.requires_upstream_wrapper(&self.relative_key(path))
        {
            XyceStaticTranPlanPurpose::GeneratedReferenceRelationalFamily
        } else {
            kind.transient_plan_purpose()
        }
    }

    fn baseline_family_tran_contracts_compatible(
        kind: XyceBaselineFamilyKind,
        baseline: XyceStaticTranContract,
        target: XyceStaticTranContract,
    ) -> bool {
        match kind {
            XyceBaselineFamilyKind::ScopedModel => matches!(
                (baseline, target),
                (
                    XyceStaticTranContract::PlainStatic,
                    XyceStaticTranContract::WrapperStatic
                )
            ),
            XyceBaselineFamilyKind::AcAnalysisExpression
            | XyceBaselineFamilyKind::BjtExternalNode
            | XyceBaselineFamilyKind::DcAnalysisExpression
            | XyceBaselineFamilyKind::DelimitedExpression
            | XyceBaselineFamilyKind::PassiveResPrimaryValue
            | XyceBaselineFamilyKind::SubcktParameterPrecedence
            | XyceBaselineFamilyKind::SubcktParameterResolution => false,
            XyceBaselineFamilyKind::SinExpression
            | XyceBaselineFamilyKind::ParamExpression
            | XyceBaselineFamilyKind::PassiveCapPrimaryValue
            | XyceBaselineFamilyKind::PassiveTemperatureOverride
            | XyceBaselineFamilyKind::Subckt
            | XyceBaselineFamilyKind::Supernode => baseline == target,
            XyceBaselineFamilyKind::TransientAnalysisExpression => matches!(
                (baseline, target),
                (
                    XyceStaticTranContract::PlainStatic,
                    XyceStaticTranContract::WrapperStatic
                )
            ),
        }
    }

    fn tran_analyses_match_exactly(baseline: &XyceTranAnalysis, target: &XyceTranAnalysis) -> bool {
        baseline.step.to_bits() == target.step.to_bits()
            && baseline.stop.to_bits() == target.stop.to_bits()
            && baseline.start.map(Value::to_bits) == target.start.map(Value::to_bits)
            && baseline.max_step.map(Value::to_bits) == target.max_step.map(Value::to_bits)
            && baseline.uic == target.uic
    }

    fn ac_analyses_match_exactly(baseline: &Netlist, target: &Netlist) -> bool {
        match (baseline.analyses.as_slice(), target.analyses.as_slice()) {
            (
                [
                    AnalysisCommand::Ac {
                        variation: baseline_variation,
                        points: baseline_points,
                        start_freq: baseline_start,
                        stop_freq: baseline_stop,
                    },
                ],
                [
                    AnalysisCommand::Ac {
                        variation: target_variation,
                        points: target_points,
                        start_freq: target_start,
                        stop_freq: target_stop,
                    },
                ],
            ) => {
                baseline_variation == target_variation
                    && baseline_points == target_points
                    && baseline_start.is_finite()
                    && baseline_stop.is_finite()
                    && target_start.is_finite()
                    && target_stop.is_finite()
                    && baseline_start.to_bits() == target_start.to_bits()
                    && baseline_stop.to_bits() == target_stop.to_bits()
            }
            _ => false,
        }
    }

    fn baseline_family_qualification_result(
        &self,
        deck: &XyceDeck,
        start: Instant,
        result_contract: &str,
        comparison: XyceBaselineFamilyComparison,
        reason: String,
    ) -> XyceTestResult {
        if comparison.strict_qualification() {
            self.failure_result(deck, start, result_contract, reason, Vec::new())
        } else {
            self.expected_unsupported_result(deck, start, result_contract, &reason)
        }
    }

    fn run_passive_primary_value_composite_contract(
        &self,
        deck: &XyceDeck,
        contract: XycePassivePrimaryCompositeContract,
        start: Instant,
    ) -> XyceTestResult {
        const COMPOSITE_CONTRACT: &str = "passive_primary_value_composite_wrapper";

        if let Some(target_path) = contract.target_path.as_ref() {
            let pair = if contract
                .capacitor_tran
                .member_paths
                .iter()
                .any(|path| Self::same_path(path, target_path))
            {
                contract.capacitor_tran
            } else if contract
                .resistor_dc
                .member_paths
                .iter()
                .any(|path| Self::same_path(path, target_path))
            {
                contract.resistor_dc
            } else {
                return self.failure_result(
                    deck,
                    start,
                    COMPOSITE_CONTRACT,
                    format!(
                        "passive primary-value family '{}' target {} is not one of its four qualified members",
                        contract.family,
                        self.display_path(target_path)
                    ),
                    Vec::new(),
                );
            };
            return self.run_baseline_family_contract(deck, pair, start);
        }

        if !Self::same_path(&deck.path, &contract.owner_path) {
            return self.failure_result(
                deck,
                start,
                COMPOSITE_CONTRACT,
                format!(
                    "passive primary-value family '{}' owner routing does not match {}",
                    contract.family,
                    self.display_path(&contract.owner_path)
                ),
                Vec::new(),
            );
        }

        for pair in [contract.capacitor_tran, contract.resistor_dc] {
            let result = self.run_baseline_family_contract(deck, pair, start);
            if result.expected_unsupported {
                return self.failure_result(
                    deck,
                    start,
                    COMPOSITE_CONTRACT,
                    format!(
                        "passive primary-value composite family '{}' did not execute a required pair: {}",
                        contract.family,
                        result
                            .error
                            .as_deref()
                            .unwrap_or("pair returned expected-unsupported without a reason")
                    ),
                    result.mismatches,
                );
            }
            if !result.passed {
                return XyceTestResult {
                    contract: COMPOSITE_CONTRACT.to_string(),
                    error: result.error.map(|error| {
                        format!(
                            "passive primary-value composite family '{}' failed: {error}",
                            contract.family
                        )
                    }),
                    ..result
                };
            }
        }

        self.passed_result(deck, start, COMPOSITE_CONTRACT)
    }

    fn analytic_rc_reference_table(
        actual: &XycePrnTable,
        specification: &XyceAnalyticRcSpecification,
    ) -> Result<XycePrnTable, String> {
        const LABEL: &str = "analytic first-order RC";
        if !specification.source_value.is_finite()
            || !specification.initial_voltage.is_finite()
            || !specification.resistance.is_finite()
            || specification.resistance <= 0.0
            || !specification.capacitance.is_finite()
            || specification.capacitance <= 0.0
            || !specification.time_constant.is_finite()
            || specification.time_constant <= 0.0
            || (specification.resistance * specification.capacitance).to_bits()
                != specification.time_constant.to_bits()
        {
            return Err(format!(
                "{LABEL} specification is nonfinite or inconsistent"
            ));
        }
        if actual.columns.len() != 3
            || actual.columns[0] != "Index"
            || actual.columns[1] != "TIME"
            || Self::normalize_probe(&actual.columns[2])
                != format!("v({})", specification.output_node).to_ascii_lowercase()
        {
            return Err(format!(
                "{LABEL} generator requires Index, TIME, and V(output), got {:?}",
                actual.columns
            ));
        }
        if actual.rows.is_empty() {
            return Err(format!("{LABEL} simulator output contains no rows"));
        }

        let mut rows = Vec::with_capacity(actual.rows.len());
        for (row_index, row) in actual.rows.iter().enumerate() {
            if row.len() != actual.columns.len()
                || row[0].to_bits() != (row_index as Value).to_bits()
                || row.iter().any(|value| !value.is_finite())
            {
                return Err(format!(
                    "{LABEL} simulator row {row_index} is malformed, nonfinite, or has a noncanonical index"
                ));
            }
            // Release 7.10's Perl generator consumes the TIME token from the
            // already-written default PRN, not the simulator's raw f64 time.
            let printed_time = Self::xyce_default_prn_roundtrip(row[1])?;
            if printed_time < 0.0 {
                return Err(format!(
                    "{LABEL} simulator row {row_index} has negative printed time {printed_time}"
                ));
            }
            let decay = (-printed_time / specification.time_constant).exp();
            let analytic_value = specification.source_value
                + (specification.initial_voltage - specification.source_value) * decay;
            if !analytic_value.is_finite() {
                return Err(format!(
                    "{LABEL} produced nonfinite value at printed time {printed_time}"
                ));
            }
            rows.push(vec![row[0], printed_time, analytic_value]);
        }
        Ok(XycePrnTable {
            columns: actual.columns.clone(),
            rows,
        })
    }

    fn validate_analytic_rc_initial_sample(
        actual: &XycePrnTable,
        specification: &XyceAnalyticRcSpecification,
    ) -> Result<(), String> {
        const LABEL: &str = "analytic first-order RC";
        let first = actual
            .rows
            .first()
            .ok_or_else(|| format!("{LABEL} simulator output contains no initial sample"))?;
        if actual.columns.len() != 3 || first.len() != actual.columns.len() {
            return Err(format!(
                "{LABEL} initial-sample validation requires one Index/TIME/probe row"
            ));
        }
        if first[0].to_bits() != 0.0f64.to_bits() {
            return Err(format!(
                "{LABEL} first sample has noncanonical index {}",
                first[0]
            ));
        }
        let printed_time = Self::xyce_default_prn_roundtrip(first[1])?;
        let printed_value = Self::xyce_default_prn_roundtrip(first[2])?;
        let printed_initial = Self::xyce_default_prn_roundtrip(specification.initial_voltage)?;
        let normalized_error =
            Self::xyce_verify_normalized_error(printed_initial, printed_value).abs();
        if printed_time != 0.0 || !normalized_error.is_finite() || normalized_error > 1.0 {
            return Err(format!(
                "{LABEL} requires the first serialized sample to be TIME=0 and V(output) within the default xyce_verify bound around {printed_initial}; got TIME={printed_time}, V(output)={printed_value}, normalized error={normalized_error}"
            ));
        }
        Ok(())
    }

    fn validate_analytic_rc_complete_time_domain(
        actual: &XycePrnTable,
        stop_time: Value,
    ) -> Result<(), String> {
        const LABEL: &str = "analytic first-order RC";
        if !stop_time.is_finite() || stop_time <= 0.0 {
            return Err(format!("{LABEL} has invalid planned stop time {stop_time}"));
        }
        if actual.columns.len() != 3 || actual.rows.len() < 2 {
            return Err(format!(
                "{LABEL} output domain requires at least two Index/TIME/probe rows"
            ));
        }
        let first = actual.rows.first().expect("row count was checked");
        let last = actual.rows.last().expect("row count was checked");
        if first.len() != actual.columns.len() || last.len() != actual.columns.len() {
            return Err(format!(
                "{LABEL} output domain boundary rows do not match the output columns"
            ));
        }
        let printed_first = Self::xyce_default_prn_roundtrip(first[1])?;
        let printed_last = Self::xyce_default_prn_roundtrip(last[1])?;
        let printed_stop = Self::xyce_default_prn_roundtrip(stop_time)?;
        if printed_first != 0.0 || printed_last.to_bits() != printed_stop.to_bits() {
            return Err(format!(
                "{LABEL} output domain must span serialized TIME=0 through .TRAN stop {printed_stop}, got {printed_first} through {printed_last}"
            ));
        }
        Ok(())
    }

    fn run_analytic_rc_wrapper_contract(
        &self,
        deck: &XyceDeck,
        contract: XyceAnalyticRcContract,
        start: Instant,
    ) -> XyceTestResult {
        const RESULT_CONTRACT: &str = "analytic_first_order_rc_tran_wrapper";
        let (netlist, result) = match self.run_transient_family_plan(&contract.plan, start, None) {
            Ok(result) => result,
            Err(SimulationError::Aborted) => {
                return self.failure_result(
                    deck,
                    start,
                    RESULT_CONTRACT,
                    format!(
                        "analytic first-order RC execution exceeded timeout ({}ms)",
                        self.config.max_time_per_test_ms
                    ),
                    Vec::new(),
                );
            }
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    RESULT_CONTRACT,
                    format!("analytic first-order RC execution failed: {err}"),
                    Vec::new(),
                );
            }
        };
        let actual =
            match Self::transient_family_result_to_prn_table(&contract.plan, &netlist, &result) {
                Ok(table) => table,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        RESULT_CONTRACT,
                        format!("analytic first-order RC output conversion failed: {err}"),
                        Vec::new(),
                    );
                }
            };
        if let Err(err) =
            Self::validate_analytic_rc_initial_sample(&actual, &contract.specification)
        {
            return self.failure_result(
                deck,
                start,
                RESULT_CONTRACT,
                format!("analytic first-order RC initial-condition validation failed: {err}"),
                Vec::new(),
            );
        }
        if let Err(err) =
            Self::validate_analytic_rc_complete_time_domain(&actual, contract.plan.tran.stop)
        {
            return self.failure_result(
                deck,
                start,
                RESULT_CONTRACT,
                format!("analytic first-order RC output-domain validation failed: {err}"),
                Vec::new(),
            );
        }
        let reference = match Self::analytic_rc_reference_table(&actual, &contract.specification) {
            Ok(table) => table,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    RESULT_CONTRACT,
                    format!("analytic first-order RC reference generation failed: {err}"),
                    Vec::new(),
                );
            }
        };
        let mismatches = match self.compare_xyce_verify_transient_tables(&reference, &actual) {
            Ok(mismatches) => mismatches,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    RESULT_CONTRACT,
                    format!("analytic first-order RC xyce_verify comparison failed: {err}"),
                    Vec::new(),
                );
            }
        };
        if mismatches.is_empty() {
            self.passed_result(deck, start, RESULT_CONTRACT)
        } else {
            self.failure_result(
                deck,
                start,
                RESULT_CONTRACT,
                format!(
                    "{} analytic first-order RC xyce_verify mismatch(es)",
                    mismatches.len()
                ),
                mismatches,
            )
        }
    }

    fn analytic_sinusoidal_rc_reference_table(
        actual: &XycePrnTable,
        specification: &XyceAnalyticSinusoidalRcSpecification,
    ) -> Result<XycePrnTable, String> {
        const LABEL: &str = "analytic sinusoidal first-order RC";
        let (expression_node, expression_offset) =
            Self::analytic_sinusoidal_rc_print_expression(&specification.print_expression)?;
        if !specification.resistance.is_finite()
            || specification.resistance <= 0.0
            || !specification.capacitance.is_finite()
            || specification.capacitance <= 0.0
            || !specification.source_frequency.is_finite()
            || specification.source_frequency <= 0.0
            || !specification.print_offset.is_finite()
            || specification.resistance.to_bits()
                != XYCE_ANALYTIC_SINUSOIDAL_RC_ORACLE_RESISTANCE.to_bits()
            || specification.capacitance.to_bits()
                != XYCE_ANALYTIC_SINUSOIDAL_RC_ORACLE_CAPACITANCE.to_bits()
            || specification.source_frequency.to_bits()
                != XYCE_ANALYTIC_SINUSOIDAL_RC_ORACLE_FREQUENCY.to_bits()
            || specification.print_offset.to_bits()
                != XYCE_ANALYTIC_SINUSOIDAL_RC_ORACLE_PRINT_OFFSET.to_bits()
            || expression_node != specification.output_node
            || expression_offset.to_bits() != specification.print_offset.to_bits()
        {
            return Err(format!(
                "{LABEL} specification is nonfinite or differs from the fixed Release 7.10 generator"
            ));
        }
        if actual.columns.len() != 3
            || actual.columns[0] != "Index"
            || actual.columns[1] != "TIME"
            || Self::normalize_probe(&actual.columns[2])
                != Self::normalize_probe(&specification.print_expression)
        {
            return Err(format!(
                "{LABEL} generator requires Index, TIME, and the qualified expression, got {:?}",
                actual.columns
            ));
        }
        if actual.rows.is_empty() {
            return Err(format!("{LABEL} simulator output contains no rows"));
        }

        let a = -1.0 / (specification.resistance * specification.capacitance);
        let s = 2.0 * XYCE_ANALYTIC_SINUSOIDAL_RC_ORACLE_PI * specification.source_frequency;
        let denominator = a * a + s * s;
        let initial_coefficient = -a * s / denominator;
        if !a.is_finite()
            || !s.is_finite()
            || !denominator.is_finite()
            || denominator <= 0.0
            || !initial_coefficient.is_finite()
        {
            return Err(format!("{LABEL} generator coefficients are invalid"));
        }

        let mut rows = Vec::with_capacity(actual.rows.len());
        for (row_index, row) in actual.rows.iter().enumerate() {
            if row.len() != actual.columns.len()
                || row[0].to_bits() != (row_index as Value).to_bits()
                || row.iter().any(|value| !value.is_finite())
            {
                return Err(format!(
                    "{LABEL} simulator row {row_index} is malformed, nonfinite, or has a noncanonical index"
                ));
            }
            // The Perl sidecar consumes the TIME token from the simulator's
            // already-written default PRN before evaluating its fixed formula.
            let printed_time = Self::xyce_default_prn_roundtrip(row[1])?;
            if printed_time < 0.0 {
                return Err(format!(
                    "{LABEL} simulator row {row_index} has negative printed time {printed_time}"
                ));
            }
            let analytic_value = specification.print_offset
                + initial_coefficient * (a * printed_time).exp()
                + a * (a * (s * printed_time).sin() + s * (s * printed_time).cos()) / denominator;
            if !analytic_value.is_finite() {
                return Err(format!(
                    "{LABEL} produced nonfinite value at printed time {printed_time}"
                ));
            }
            rows.push(vec![row[0], printed_time, analytic_value]);
        }
        Ok(XycePrnTable {
            columns: actual.columns.clone(),
            rows,
        })
    }

    fn validate_analytic_sinusoidal_rc_output_domain(
        actual: &XycePrnTable,
        specification: &XyceAnalyticSinusoidalRcSpecification,
        stop_time: Value,
        tolerance: XyceVerifyTransientTolerance,
    ) -> Result<(), String> {
        const LABEL: &str = "analytic sinusoidal first-order RC";
        let tolerance = tolerance.validate()?;
        if !stop_time.is_finite() || stop_time <= 0.0 {
            return Err(format!("{LABEL} has invalid planned stop time {stop_time}"));
        }
        if actual.columns.len() != 3
            || Self::normalize_probe(&actual.columns[2])
                != Self::normalize_probe(&specification.print_expression)
            || actual.rows.len() < 2
        {
            return Err(format!(
                "{LABEL} output domain requires Index/TIME/expression and at least two rows"
            ));
        }
        let first = actual.rows.first().expect("row count was checked");
        let last = actual.rows.last().expect("row count was checked");
        if first.len() != actual.columns.len() || last.len() != actual.columns.len() {
            return Err(format!(
                "{LABEL} output boundary rows do not match the output columns"
            ));
        }
        let printed_first_time = Self::xyce_default_prn_roundtrip(first[1])?;
        let printed_last_time = Self::xyce_default_prn_roundtrip(last[1])?;
        let printed_stop = Self::xyce_default_prn_roundtrip(stop_time)?;
        let printed_first_value = Self::xyce_default_prn_roundtrip(first[2])?;
        let printed_initial = Self::xyce_default_prn_roundtrip(specification.print_offset)?;
        let initial_error = Self::xyce_verify_normalized_error_with_tolerance(
            printed_initial,
            printed_first_value,
            tolerance,
        )
        .abs();
        if first[0].to_bits() != 0.0f64.to_bits()
            || printed_first_time != 0.0
            || printed_last_time.to_bits() != printed_stop.to_bits()
            || !initial_error.is_finite()
            || initial_error > 1.0
        {
            return Err(format!(
                "{LABEL} output must start at Index=0/TIME=0/value within the qualified xyce_verify bound around {printed_initial} and end at .TRAN stop {printed_stop}; got Index={}, TIME/value={printed_first_time}/{printed_first_value}, normalized initial error={initial_error}, final TIME={printed_last_time}",
                first[0]
            ));
        }
        Ok(())
    }

    fn run_analytic_sinusoidal_rc_wrapper_contract(
        &self,
        deck: &XyceDeck,
        contract: XyceAnalyticSinusoidalRcContract,
        start: Instant,
    ) -> XyceTestResult {
        const RESULT_CONTRACT: &str = "analytic_sinusoidal_first_order_rc_tran_wrapper";
        let (netlist, result) = match self.run_transient_family_plan(&contract.plan, start, None) {
            Ok(result) => result,
            Err(SimulationError::Aborted) => {
                return self.failure_result(
                    deck,
                    start,
                    RESULT_CONTRACT,
                    format!(
                        "analytic sinusoidal first-order RC execution exceeded timeout ({}ms)",
                        self.config.max_time_per_test_ms
                    ),
                    Vec::new(),
                );
            }
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    RESULT_CONTRACT,
                    format!("analytic sinusoidal first-order RC execution failed: {err}"),
                    Vec::new(),
                );
            }
        };
        let actual =
            match Self::transient_family_result_to_prn_table(&contract.plan, &netlist, &result) {
                Ok(table) => table,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        RESULT_CONTRACT,
                        format!(
                            "analytic sinusoidal first-order RC output conversion failed: {err}"
                        ),
                        Vec::new(),
                    );
                }
            };
        if let Err(err) = Self::validate_analytic_sinusoidal_rc_output_domain(
            &actual,
            &contract.specification,
            contract.plan.tran.stop,
            contract.tolerance,
        ) {
            return self.failure_result(
                deck,
                start,
                RESULT_CONTRACT,
                format!(
                    "analytic sinusoidal first-order RC output-domain validation failed: {err}"
                ),
                Vec::new(),
            );
        }
        let reference =
            match Self::analytic_sinusoidal_rc_reference_table(&actual, &contract.specification) {
                Ok(table) => table,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        RESULT_CONTRACT,
                        format!(
                            "analytic sinusoidal first-order RC reference generation failed: {err}"
                        ),
                        Vec::new(),
                    );
                }
            };
        let mismatches = match self.compare_xyce_verify_transient_tables_with_tolerance(
            &reference,
            &actual,
            contract.tolerance,
        ) {
            Ok(mismatches) => mismatches,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    RESULT_CONTRACT,
                    format!(
                        "analytic sinusoidal first-order RC xyce_verify comparison failed: {err}"
                    ),
                    Vec::new(),
                );
            }
        };
        if mismatches.is_empty() {
            self.passed_result(deck, start, RESULT_CONTRACT)
        } else {
            self.failure_result(
                deck,
                start,
                RESULT_CONTRACT,
                format!(
                    "{} analytic sinusoidal first-order RC xyce_verify mismatch(es)",
                    mismatches.len()
                ),
                mismatches,
            )
        }
    }

    fn run_stepped_ic_reference_contract(
        &self,
        deck: &XyceDeck,
        contract: XyceSteppedIcReferenceContract,
        start: Instant,
    ) -> XyceTestResult {
        const WRAPPER_CONTRACT: &str = "stepped_ic_reference_wrapper";
        const BASELINE_CONTRACT: &str = "stepped_ic_reference_baseline";

        let result_contract = if Self::same_path(&contract.target_path, &contract.owner_path) {
            WRAPPER_CONTRACT
        } else {
            BASELINE_CONTRACT
        };
        let qualification = (|| {
            let owner_plan = self.static_tran_family_plan_for_path(
                &contract.owner_path,
                XyceStaticTranPlanPurpose::GeneratedReferenceRelationalFamily,
            )?;
            if owner_plan.output_override || owner_plan.timeint_conststep {
                return Err(
                    "stepped-IC generated-reference wrapper requires ordinary default transient output"
                        .to_string(),
                );
            }
            let [step] = owner_plan.steps.as_slice() else {
                return Err(format!(
                    "stepped-IC generated-reference wrapper requires exactly one .STEP command, found {}",
                    owner_plan.steps.len()
                ));
            };
            if step.target != StepTarget::Device
                || step
                    .param_name
                    .as_deref()
                    .is_none_or(|name| !name.eq_ignore_ascii_case("c"))
                || !matches!(
                    step.sweep,
                    StepSweep::Decade {
                        points_per_decade: 1..,
                        start,
                        stop,
                    } if start.is_finite() && stop.is_finite() && start > 0.0 && stop >= start
                )
            {
                return Err(
                    "stepped-IC generated-reference wrapper requires a finite positive DEC device-parameter sweep of capacitor parameter C"
                        .to_string(),
                );
            }
            let owner_options = Self::stepped_ic_option_signature(&owner_plan.source)?;
            let owner_netlist = Self::parse_xyce_netlist(&owner_plan.source, &owner_plan.deck_path)
                .map_err(|err| format!("owner netlist parse failed: {err}"))?;
            let step_runs = Self::nested_step_runs_for_commands(
                &self.create_xyce_engine(),
                &owner_netlist,
                &owner_plan.steps,
            )
            .map_err(|err| format!("owner .STEP expansion failed: {err}"))?;
            if step_runs.len() != contract.member_paths.len() {
                return Err(format!(
                    "owner .STEP expands to {} run(s), but the family contains {} independent baseline deck(s)",
                    step_runs.len(),
                    contract.member_paths.len()
                ));
            }

            let mut members = Vec::with_capacity(contract.member_paths.len());
            for (index, (member_path, step_run)) in contract
                .member_paths
                .iter()
                .zip(step_runs.iter())
                .enumerate()
            {
                let member_plan = self.static_tran_family_plan_for_path(
                    member_path,
                    XyceStaticTranPlanPurpose::RelationalFamily,
                )?;
                if !member_plan.steps.is_empty()
                    || member_plan.output_override
                    || member_plan.timeint_conststep
                {
                    return Err(format!(
                        "independent baseline {} must use one ordinary non-stepped transient output",
                        self.display_path(member_path)
                    ));
                }
                if member_plan.print.probes != owner_plan.print.probes {
                    return Err(format!(
                        "independent baseline {} changes the ordered .PRINT TRAN probes",
                        self.display_path(member_path)
                    ));
                }
                if !Self::tran_analyses_match_exactly(&owner_plan.tran, &member_plan.tran) {
                    return Err(format!(
                        "independent baseline {} changes the .TRAN analysis tuple",
                        self.display_path(member_path)
                    ));
                }
                let member_options = Self::stepped_ic_option_signature(&member_plan.source)?;
                if member_options != owner_options {
                    return Err(format!(
                        "independent baseline {} changes the .OPTIONS contract",
                        self.display_path(member_path)
                    ));
                }
                let owner_scale = Self::tran_print_time_scale_factor(&owner_plan.source)?;
                let member_scale = Self::tran_print_time_scale_factor(&member_plan.source)?;
                if owner_scale.to_bits() != member_scale.to_bits() {
                    return Err(format!(
                        "independent baseline {} changes transient output time units",
                        self.display_path(member_path)
                    ));
                }
                let member_netlist =
                    Self::parse_xyce_netlist(&member_plan.source, &member_plan.deck_path).map_err(
                        |err| {
                            format!(
                                "independent baseline {} parse failed: {err}",
                                self.display_path(member_path)
                            )
                        },
                    )?;
                let stepped_snapshot = Self::stepped_ic_snapshot(&step_run.netlist)?;
                let member_snapshot = Self::stepped_ic_snapshot(&member_netlist)?;
                if !step
                    .name
                    .eq_ignore_ascii_case(&stepped_snapshot.capacitor_name)
                {
                    return Err(format!(
                        "owner step targets '{}', but the materialized circuit's qualified capacitor is '{}'",
                        step.name, stepped_snapshot.capacitor_name
                    ));
                }
                if !Self::stepped_ic_snapshots_match(&stepped_snapshot, &member_snapshot) {
                    return Err(format!(
                        "owner step {} is not structurally and numerically identical to independent baseline {}",
                        index,
                        self.display_path(member_path)
                    ));
                }
                let step_value = step_run.step_values.first().copied().ok_or_else(|| {
                    format!(
                        "owner step {index} did not retain its swept {}:C value",
                        step.name
                    )
                })?;
                let member_capacitance = Value::from_bits(member_snapshot.capacitor_value_bits);
                if step_run.step_values.len() != 1
                    || (step_value - member_capacitance).abs() > 1.0e-12
                {
                    return Err(format!(
                        "owner step {index} {}:C value {step_value} does not match independent baseline {} within the Release 7.10 sweep-result tolerance",
                        step.name,
                        self.display_path(member_path)
                    ));
                }
                if !step
                    .name
                    .eq_ignore_ascii_case(&member_snapshot.capacitor_name)
                {
                    return Err(format!(
                        "owner step targets '{}', but independent baseline {} names its qualified capacitor '{}'",
                        step.name,
                        self.display_path(member_path),
                        member_snapshot.capacitor_name
                    ));
                }
                members.push((member_plan, member_netlist));
            }
            Ok((owner_plan, step_runs, members))
        })();

        let (owner_plan, step_runs, members) = match qualification {
            Ok(qualified) => qualified,
            Err(reason) => {
                return self.failure_result(
                    deck,
                    start,
                    result_contract,
                    format!(
                        "stepped-IC generated-reference family '{}' qualification failed: {reason}",
                        contract.family
                    ),
                    Vec::new(),
                );
            }
        };

        let mut mismatches = Vec::new();
        let mut row_offset = 0usize;
        for (index, ((member_plan, member_netlist), step_run)) in
            members.iter().zip(step_runs.iter()).enumerate()
        {
            let member_result = match self.run_transient_family_netlist(
                member_plan,
                member_netlist,
                start,
                None,
            ) {
                Ok(result) => result,
                Err(SimulationError::Aborted) => {
                    return self.failure_result(
                        deck,
                        start,
                        result_contract,
                        format!(
                            "independent baseline step {index} exceeded timeout ({}ms)",
                            self.config.max_time_per_test_ms
                        ),
                        Vec::new(),
                    );
                }
                Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                    return self.expected_unsupported_result(
                        deck,
                        start,
                        "unsupported_xyce_runtime",
                        &format!(
                            "RSpice runtime does not yet support stepped-IC baseline step {index}: {err}"
                        ),
                    );
                }
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        result_contract,
                        format!("independent baseline step {index} simulation failed: {err}"),
                        Vec::new(),
                    );
                }
            };
            let stepped_result = match self.run_transient_family_netlist(
                &owner_plan,
                &step_run.netlist,
                start,
                None,
            ) {
                Ok(result) => result,
                Err(SimulationError::Aborted) => {
                    return self.failure_result(
                        deck,
                        start,
                        result_contract,
                        format!(
                            "owner step {index} exceeded timeout ({}ms)",
                            self.config.max_time_per_test_ms
                        ),
                        Vec::new(),
                    );
                }
                Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                    return self.expected_unsupported_result(
                        deck,
                        start,
                        "unsupported_xyce_runtime",
                        &format!(
                            "RSpice runtime does not yet support stepped-IC owner step {index}: {err}"
                        ),
                    );
                }
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        result_contract,
                        format!("owner step {index} simulation failed: {err}"),
                        Vec::new(),
                    );
                }
            };
            let baseline_table = match Self::transient_family_result_to_prn_table(
                member_plan,
                member_netlist,
                &member_result,
            ) {
                Ok(table) => table,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        result_contract,
                        format!("independent baseline step {index} output failed: {err}"),
                        Vec::new(),
                    );
                }
            };
            let stepped_table = match Self::transient_family_result_to_prn_table(
                &owner_plan,
                &step_run.netlist,
                &stepped_result,
            ) {
                Ok(table) => table,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        result_contract,
                        format!("owner step {index} output failed: {err}"),
                        Vec::new(),
                    );
                }
            };
            let mut step_mismatches =
                match self.compare_xyce_verify_transient_tables(&baseline_table, &stepped_table) {
                    Ok(found) => found,
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            result_contract,
                            format!(
                                "Release 7.10 xyce_verify comparison failed for step {index}: {err}"
                            ),
                            Vec::new(),
                        );
                    }
                };
            for mismatch in &mut step_mismatches {
                mismatch.row += row_offset;
                mismatch.probe = format!("step {index}: {}", mismatch.probe);
            }
            row_offset += stepped_table.rows.len();
            mismatches.extend(step_mismatches);
            if mismatches.len() >= self.config.max_mismatches {
                mismatches.truncate(self.config.max_mismatches);
                break;
            }
        }

        if mismatches.is_empty() {
            self.passed_result(deck, start, result_contract)
        } else {
            self.failure_result(
                deck,
                start,
                result_contract,
                format!(
                    "{} stepped-IC Release 7.10 xyce_verify mismatch(es)",
                    mismatches.len()
                ),
                mismatches,
            )
        }
    }

    fn stepped_ic_option_signature(source: &str) -> Result<Vec<String>, String> {
        let statements = Self::logical_netlist_lines(source)
            .into_iter()
            .map(|line| Self::strip_netlist_comment(&line).trim().to_string())
            .filter(|line| {
                line.split_whitespace()
                    .next()
                    .is_some_and(|command| command.eq_ignore_ascii_case(".options"))
            })
            .map(|line| {
                line.chars()
                    .filter(|ch| !ch.is_whitespace())
                    .collect::<String>()
                    .to_ascii_lowercase()
            })
            .collect::<Vec<_>>();
        if statements.len() != 1 {
            return Err(format!(
                "stepped-IC family requires exactly one .OPTIONS statement, found {}",
                statements.len()
            ));
        }
        Ok(statements)
    }

    fn stepped_ic_snapshot(netlist: &Netlist) -> Result<XyceSteppedIcSnapshot, String> {
        if !netlist.models.is_empty()
            || !netlist.subcircuits.is_empty()
            || !netlist.data_tables.is_empty()
            || !netlist.node_sets.is_empty()
            || !netlist.global_nodes.is_empty()
            || !netlist.measurements.is_empty()
            || !netlist.veriloga_includes.is_empty()
            || !netlist.spef_includes.is_empty()
            || !netlist.diagnostics.is_empty()
        {
            return Err(
                "stepped-IC family must be a diagnostic-free flat RC circuit without models, data, node sets, measurements, globals, or external model data"
                    .to_string(),
            );
        }
        if netlist.elements.len() != 3 {
            return Err(format!(
                "stepped-IC family requires exactly three circuit elements, found {}",
                netlist.elements.len()
            ));
        }

        let mut capacitor = None;
        let mut resistor_nodes = None;
        let mut source_nodes = None;
        let mut elements = BTreeMap::new();
        for element in &netlist.elements {
            match &element.kind {
                ElementKind::Capacitor {
                    value,
                    value_expr,
                    initial_voltage,
                    model,
                    instance_params,
                    deferred_params,
                } if element.nodes.len() == 2
                    && value.is_finite()
                    && *value > 0.0
                    && value_expr.is_none()
                    && initial_voltage.is_none()
                    && model.is_none()
                    && instance_params.len() <= 1
                    && instance_params.iter().all(|(name, parameter_value)| {
                        name.eq_ignore_ascii_case("c")
                            && parameter_value.to_bits() == value.to_bits()
                    })
                    && deferred_params.is_empty() =>
                {
                    if capacitor
                        .replace((element.name.clone(), element.nodes.clone(), *value))
                        .is_some()
                    {
                        return Err(
                            "stepped-IC family contains more than one qualified capacitor"
                                .to_string(),
                        );
                    }
                }
                ElementKind::Resistor {
                    value,
                    value_expr,
                    model,
                    instance_params,
                    deferred_params,
                } if element.nodes.len() == 2
                    && value.is_finite()
                    && *value > 0.0
                    && value_expr.is_none()
                    && model.is_none()
                    && instance_params.is_empty()
                    && deferred_params.is_empty() =>
                {
                    if resistor_nodes.replace(element.nodes.clone()).is_some() {
                        return Err(
                            "stepped-IC family contains more than one qualified resistor"
                                .to_string(),
                        );
                    }
                }
                ElementKind::VoltageSource(crate::netlist::SourceSpec::Dc(value))
                    if element.nodes.len() == 2
                        && value.is_finite()
                        && value.to_bits() == 0.0f64.to_bits() =>
                {
                    if source_nodes.replace(element.nodes.clone()).is_some() {
                        return Err(
                            "stepped-IC family contains more than one qualified zero-volt source"
                                .to_string(),
                        );
                    }
                }
                _ => {
                    return Err(format!(
                        "stepped-IC family contains unqualified element '{}'",
                        element.name
                    ));
                }
            }
            let name = element.name.trim().to_ascii_lowercase();
            if name.is_empty()
                || elements
                    .insert(
                        name,
                        Self::scoped_model_element_fingerprint(element, &netlist.params)?,
                    )
                    .is_some()
            {
                return Err(
                    "stepped-IC family contains an empty or duplicate element name".to_string(),
                );
            }
        }

        let (capacitor_name, capacitor_nodes, capacitance) =
            capacitor.ok_or_else(|| "stepped-IC family has no qualified capacitor".to_string())?;
        let resistor_nodes = resistor_nodes
            .ok_or_else(|| "stepped-IC family has no qualified resistor".to_string())?;
        let source_nodes = source_nodes
            .ok_or_else(|| "stepped-IC family has no qualified zero-volt source".to_string())?;
        let capacitor_signal = capacitor_nodes
            .iter()
            .find(|node| !Self::node_name_is_ground(node))
            .ok_or_else(|| "stepped-IC capacitor has no non-ground signal node".to_string())?;
        if capacitor_nodes
            .iter()
            .filter(|node| Self::node_name_is_ground(node))
            .count()
            != 1
        {
            return Err("stepped-IC capacitor must connect one signal node to ground".to_string());
        }
        let source_signal = source_nodes
            .iter()
            .find(|node| !Self::node_name_is_ground(node))
            .ok_or_else(|| "stepped-IC zero-volt source has no non-ground node".to_string())?;
        if source_nodes
            .iter()
            .filter(|node| Self::node_name_is_ground(node))
            .count()
            != 1
            || !resistor_nodes
                .iter()
                .any(|node| node.eq_ignore_ascii_case(capacitor_signal))
            || !resistor_nodes
                .iter()
                .any(|node| node.eq_ignore_ascii_case(source_signal))
        {
            return Err(
                "stepped-IC topology must be grounded C -> R -> grounded zero-volt source"
                    .to_string(),
            );
        }

        let [initial_condition] = netlist.initial_conditions.as_slice() else {
            return Err(format!(
                "stepped-IC family requires exactly one .IC voltage, found {}",
                netlist.initial_conditions.len()
            ));
        };
        if initial_condition.voltage_expr.is_some()
            || !initial_condition.voltage.is_finite()
            || !initial_condition
                .node
                .eq_ignore_ascii_case(capacitor_signal)
        {
            return Err(
                "stepped-IC .IC must be one finite direct voltage on the capacitor signal node"
                    .to_string(),
            );
        }
        let initial_conditions = vec![(
            initial_condition.node.trim().to_ascii_lowercase(),
            initial_condition.voltage.to_bits(),
        )];

        Ok(XyceSteppedIcSnapshot {
            elements,
            initial_conditions,
            capacitor_name,
            capacitor_value_bits: capacitance.to_bits(),
        })
    }

    fn stepped_ic_snapshots_match(
        stepped: &XyceSteppedIcSnapshot,
        independent: &XyceSteppedIcSnapshot,
    ) -> bool {
        if !stepped
            .capacitor_name
            .eq_ignore_ascii_case(&independent.capacitor_name)
            || stepped.initial_conditions != independent.initial_conditions
        {
            return false;
        }
        let capacitor_key = stepped.capacitor_name.trim().to_ascii_lowercase();
        let mut stepped_elements = stepped.elements.clone();
        let mut independent_elements = independent.elements.clone();
        let Some(mut stepped_capacitor) = stepped_elements.remove(&capacitor_key) else {
            return false;
        };
        let Some(mut independent_capacitor) = independent_elements.remove(&capacitor_key) else {
            return false;
        };
        let Some(stepped_bits) = stepped_capacitor.numeric_bits.first_mut() else {
            return false;
        };
        let Some(independent_bits) = independent_capacitor.numeric_bits.first_mut() else {
            return false;
        };
        *stepped_bits = 0.0f64.to_bits();
        *independent_bits = 0.0f64.to_bits();
        let stepped_value = Value::from_bits(stepped.capacitor_value_bits);
        let independent_value = Value::from_bits(independent.capacitor_value_bits);
        stepped_elements == independent_elements
            && stepped_capacitor == independent_capacitor
            && stepped_value.is_finite()
            && independent_value.is_finite()
            && (stepped_value - independent_value).abs() <= 1.0e-12
    }

    fn run_subckt_parameter_resolution_family_contract(
        &self,
        deck: &XyceDeck,
        contract: XyceSubcktParameterResolutionFamilyContract,
        start: Instant,
    ) -> XyceTestResult {
        const MEMBER_CONTRACT: &str = "subckt_parameter_resolution_family_member";
        const ERROR_CONTRACT: &str = "subckt_parameter_resolution_expected_error";
        if !contract
            .valid_paths
            .iter()
            .any(|path| Self::same_path(path, &contract.baseline_path))
            || !contract.anchor_path.is_file()
            || !contract.error_path.is_file()
        {
            return self.failure_result(
                deck,
                start,
                XyceBaselineFamilyKind::SubcktParameterResolution.wrapper_contract(),
                format!(
                    "subcircuit-parameter resolution family '{}' lost a qualified anchor, error member, or baseline",
                    contract.family
                ),
                Vec::new(),
            );
        }
        let target_path = match contract.role {
            XyceSubcktParameterResolutionRole::Baseline
            | XyceSubcktParameterResolutionRole::Member => Some(contract.target_path.clone()),
            XyceSubcktParameterResolutionRole::Anchor
            | XyceSubcktParameterResolutionRole::ExpectedError => None,
        };
        let relational = XyceBaselineFamilyContract {
            kind: XyceBaselineFamilyKind::SubcktParameterResolution,
            comparison: XyceBaselineFamilyComparison::ExactPrn,
            family: contract.family,
            baseline_path: contract.baseline_path,
            member_paths: contract.valid_paths,
            target_path,
        };
        let mut result = self.run_baseline_family_contract(deck, relational, start);
        if result.passed && !result.expected_unsupported {
            result.contract = match contract.role {
                XyceSubcktParameterResolutionRole::Anchor => {
                    XyceBaselineFamilyKind::SubcktParameterResolution.wrapper_contract()
                }
                XyceSubcktParameterResolutionRole::Baseline => {
                    XyceBaselineFamilyKind::SubcktParameterResolution.baseline_contract()
                }
                XyceSubcktParameterResolutionRole::Member => MEMBER_CONTRACT,
                XyceSubcktParameterResolutionRole::ExpectedError => ERROR_CONTRACT,
            }
            .to_string();
        }
        result
    }

    fn run_baseline_family_contract(
        &self,
        deck: &XyceDeck,
        contract: XyceBaselineFamilyContract,
        start: Instant,
    ) -> XyceTestResult {
        let kind_name = contract.kind.name();
        let wrapper_contract = contract.kind.wrapper_contract();
        let baseline_contract = contract.kind.baseline_contract();
        let analysis = match self.baseline_family_analysis_for_path(&contract.baseline_path) {
            Ok(analysis) => analysis,
            Err(reason) => {
                return self.baseline_family_qualification_result(
                    deck,
                    start,
                    wrapper_contract,
                    contract.comparison,
                    format!(
                        "{kind_name} family '{}' baseline analysis is ambiguous or unsupported: {reason}",
                        contract.family
                    ),
                );
            }
        };
        if contract.kind == XyceBaselineFamilyKind::AcAnalysisExpression
            && analysis != XyceBaselineFamilyAnalysis::Ac
        {
            return self.failure_result(
                deck,
                start,
                wrapper_contract,
                format!(
                    "{kind_name} family '{}' requires an AC analysis",
                    contract.family
                ),
                Vec::new(),
            );
        }
        if matches!(
            contract.kind,
            XyceBaselineFamilyKind::BjtExternalNode
                | XyceBaselineFamilyKind::DcAnalysisExpression
                | XyceBaselineFamilyKind::DelimitedExpression
                | XyceBaselineFamilyKind::PassiveResPrimaryValue
                | XyceBaselineFamilyKind::SubcktParameterResolution
        ) && analysis != XyceBaselineFamilyAnalysis::Dc
        {
            return self.failure_result(
                deck,
                start,
                wrapper_contract,
                format!(
                    "{kind_name} family '{}' requires a DC analysis",
                    contract.family
                ),
                Vec::new(),
            );
        }
        if matches!(
            contract.kind,
            XyceBaselineFamilyKind::SinExpression
                | XyceBaselineFamilyKind::ParamExpression
                | XyceBaselineFamilyKind::PassiveCapPrimaryValue
                | XyceBaselineFamilyKind::PassiveTemperatureOverride
                | XyceBaselineFamilyKind::TransientAnalysisExpression
        ) && analysis != XyceBaselineFamilyAnalysis::Tran
        {
            return self.failure_result(
                deck,
                start,
                wrapper_contract,
                format!(
                    "{kind_name} family '{}' requires a transient analysis",
                    contract.family
                ),
                Vec::new(),
            );
        }
        if analysis == XyceBaselineFamilyAnalysis::Ac {
            return self.run_ac_baseline_family_contract(deck, contract, start);
        }
        if analysis == XyceBaselineFamilyAnalysis::Tran {
            let baseline_plan = match self.static_tran_family_plan_for_path(
                &contract.baseline_path,
                self.transient_family_plan_purpose_for_path(contract.kind, &contract.baseline_path),
            ) {
                Ok(plan) => plan,
                Err(reason) => {
                    return self.baseline_family_qualification_result(
                        deck,
                        start,
                        wrapper_contract,
                        contract.comparison,
                        format!(
                            "{kind_name} family '{}' baseline is not supported by the static TRAN adapter: {reason}",
                            contract.family
                        ),
                    );
                }
            };
            return self.run_transient_baseline_family_contract(
                deck,
                contract,
                baseline_plan,
                start,
            );
        }
        let baseline_plan = match self
            .static_dc_plan_for_path(&contract.baseline_path, ExpressionDialect::Xyce)
        {
            Ok(plan) => plan,
            Err(reason) => {
                return self.baseline_family_qualification_result(
                    deck,
                    start,
                    wrapper_contract,
                    contract.comparison,
                    format!(
                        "{kind_name} family '{}' baseline is not supported by the static DC adapter: {reason}",
                        contract.family
                    ),
                );
            }
        };
        if contract.comparison.compares_waveforms_exactly() {
            return self.run_exact_dc_baseline_family_contract(
                deck,
                contract,
                baseline_plan,
                start,
            );
        }
        let baseline_run = self.run_static_dc_results(&baseline_plan, start);
        let (baseline_netlist, baseline_results) = match baseline_run {
            Ok(results) => results,
            Err(SimulationError::Aborted) => {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' baseline exceeded timeout ({}ms)",
                        contract.family, self.config.max_time_per_test_ms
                    ),
                    Vec::new(),
                );
            }
            Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                return self.expected_unsupported_result(
                    deck,
                    start,
                    wrapper_contract,
                    &format!(
                        "{kind_name} family '{}' baseline is not supported by RSpice yet: {err}",
                        contract.family
                    ),
                );
            }
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' baseline error: {err}",
                        contract.family
                    ),
                    Vec::new(),
                );
            }
        };
        if contract.kind.compares_baseline_oracle()
            && let Some(reference_path) = self.static_prn_reference_path(&contract.baseline_path)
            && reference_path.is_file()
        {
            let reference = match Self::parse_prn_file(&reference_path) {
                Ok(reference) => reference,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        wrapper_contract,
                        format!(
                            "{kind_name} family '{}' baseline oracle parse error: {err}",
                            contract.family
                        ),
                        Vec::new(),
                    );
                }
            };
            let mismatches = match self.compare_dc_prn_reference(
                &reference,
                &baseline_plan.print,
                &baseline_netlist,
                &baseline_plan.source,
                &baseline_plan.dc,
                &baseline_results,
            ) {
                Ok(mismatches) => mismatches,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        wrapper_contract,
                        format!(
                            "{kind_name} family '{}' baseline oracle comparison error: {err}",
                            contract.family
                        ),
                        Vec::new(),
                    );
                }
            };
            if !mismatches.is_empty() {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{} {kind_name} family '{}' baseline oracle mismatch(es)",
                        mismatches.len(),
                        contract.family
                    ),
                    mismatches,
                );
            }
        }
        let baseline_table = match self.dc_results_to_prn_table(
            &baseline_plan,
            &baseline_netlist,
            &baseline_results,
        ) {
            Ok(table) => table,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' baseline output conversion failed: {err}",
                        contract.family
                    ),
                    Vec::new(),
                );
            }
        };

        let (targets, baseline_record) = Self::baseline_family_targets(&contract);
        if targets.is_empty() {
            return self.expected_unsupported_result(
                deck,
                start,
                wrapper_contract,
                &format!(
                    "{kind_name} family '{}' has no non-baseline member to compare",
                    contract.family
                ),
            );
        }

        let mut all_mismatches = Vec::new();
        for target_path in targets {
            let target_plan = match self
                .static_dc_plan_for_path(&target_path, ExpressionDialect::Xyce)
            {
                Ok(plan) => plan,
                Err(reason) => {
                    return self.expected_unsupported_result(
                        deck,
                        start,
                        wrapper_contract,
                        &format!(
                            "{kind_name} family '{}' member {} is not supported by the static DC adapter: {reason}",
                            contract.family,
                            self.display_path(&target_path)
                        ),
                    );
                }
            };
            let (target_netlist, target_results) = match self
                .run_static_dc_results(&target_plan, start)
            {
                Ok(results) => results,
                Err(SimulationError::Aborted) => {
                    return self.failure_result(
                        deck,
                        start,
                        wrapper_contract,
                        format!(
                            "{kind_name} family '{}' member {} exceeded timeout ({}ms)",
                            contract.family,
                            self.display_path(&target_path),
                            self.config.max_time_per_test_ms
                        ),
                        Vec::new(),
                    );
                }
                Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                    return self.expected_unsupported_result(
                        deck,
                        start,
                        wrapper_contract,
                        &format!(
                            "{kind_name} family '{}' member {} is not supported by RSpice yet: {err}",
                            contract.family,
                            self.display_path(&target_path)
                        ),
                    );
                }
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        wrapper_contract,
                        format!(
                            "{kind_name} family '{}' member {} error: {err}",
                            contract.family,
                            self.display_path(&target_path)
                        ),
                        Vec::new(),
                    );
                }
            };

            let mut mismatches = match self.compare_dc_prn_reference(
                &baseline_table,
                &target_plan.print,
                &target_netlist,
                &baseline_plan.source,
                &target_plan.dc,
                &target_results,
            ) {
                Ok(mismatches) => mismatches,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        wrapper_contract,
                        format!(
                            "{kind_name} family '{}' member {} comparison error: {err}",
                            contract.family,
                            self.display_path(&target_path)
                        ),
                        Vec::new(),
                    );
                }
            };
            for mismatch in &mut mismatches {
                mismatch.probe = format!("{} {}", self.display_path(&target_path), mismatch.probe);
            }
            all_mismatches.extend(mismatches);
            if all_mismatches.len() >= self.config.max_mismatches {
                all_mismatches.truncate(self.config.max_mismatches);
                break;
            }
        }

        if all_mismatches.is_empty() {
            let result_contract = if baseline_record {
                baseline_contract
            } else {
                wrapper_contract
            };
            self.passed_result(deck, start, result_contract)
        } else {
            self.failure_result(
                deck,
                start,
                wrapper_contract,
                format!(
                    "{} {kind_name} family '{}' mismatch(es)",
                    all_mismatches.len(),
                    contract.family
                ),
                all_mismatches,
            )
        }
    }

    fn strict_ac_family_snapshot(
        kind: XyceBaselineFamilyKind,
        netlist: &Netlist,
    ) -> Result<XyceStrictAcFamilySnapshot, String> {
        match kind {
            XyceBaselineFamilyKind::AcAnalysisExpression => {
                Self::ac_analysis_expression_snapshot(netlist)
                    .map(XyceStrictAcFamilySnapshot::AcAnalysisExpression)
            }
            other => Err(format!(
                "family kind {} has no qualified AC semantic snapshot",
                other.name()
            )),
        }
    }

    fn compare_strict_ac_family_snapshots(
        baseline: &XyceStrictAcFamilySnapshot,
        target: &XyceStrictAcFamilySnapshot,
    ) -> Result<(), String> {
        match (baseline, target) {
            (
                XyceStrictAcFamilySnapshot::AcAnalysisExpression(baseline),
                XyceStrictAcFamilySnapshot::AcAnalysisExpression(target),
            ) => Self::compare_ac_analysis_expression_snapshots(baseline, target),
        }
    }

    fn ac_family_result_to_prn_table(
        print: &XycePrintRequest,
        netlist: &Netlist,
        results: &[AcResult],
    ) -> Result<XycePrnTable, String> {
        let first = results
            .first()
            .ok_or_else(|| "relational AC simulation produced no points".to_string())?;
        let mut expansions = Vec::with_capacity(print.probes.len());
        let mut columns = vec!["Index".to_string(), "FREQ".to_string()];
        for probe in &print.probes {
            let normalized = Self::normalize_ac_expression_probe_key(probe);
            let is_direct_complex = Self::parse_ac_voltage_probe(&normalized)
                .is_some_and(|probe| probe.accessor == XyceVoltageAccessor::Value)
                || Self::parse_ac_current_probe(&normalized)
                    .is_some_and(|probe| probe.accessor == XyceCurrentAccessor::Value);
            if is_direct_complex {
                let value = Self::evaluate_ac_complex_probe(probe, netlist, first)?;
                if !value.re.is_finite() || !value.im.is_finite() {
                    return Err(format!(
                        "relational AC probe '{probe}' produced a non-finite complex value"
                    ));
                }
                expansions.push(XyceAcCsdColumnExpansion::Complex);
                columns.push(format!("Re({probe})"));
                columns.push(format!("Im({probe})"));
                continue;
            }
            match Self::evaluate_ac_probe(probe, netlist, first, false) {
                Ok(value) if value.is_finite() => {
                    expansions.push(XyceAcCsdColumnExpansion::Scalar);
                    columns.push(probe.clone());
                }
                Ok(value) => {
                    return Err(format!(
                        "relational AC probe '{probe}' produced non-finite scalar value {value}"
                    ));
                }
                Err(_) => {
                    let value = Self::evaluate_ac_complex_probe(probe, netlist, first)?;
                    if !value.re.is_finite() || !value.im.is_finite() {
                        return Err(format!(
                            "relational AC probe '{probe}' produced a non-finite complex value"
                        ));
                    }
                    expansions.push(XyceAcCsdColumnExpansion::Complex);
                    columns.push(format!("Re({probe})"));
                    columns.push(format!("Im({probe})"));
                }
            }
        }

        let mut rows = Vec::with_capacity(results.len());
        for (row_index, result) in results.iter().enumerate() {
            let mut row = Vec::with_capacity(columns.len());
            row.push(row_index as Value);
            row.push(
                Self::xyce_default_prn_roundtrip(result.frequency).map_err(|err| {
                    format!("could not serialize relational AC frequency at row {row_index}: {err}")
                })?,
            );
            for (probe, expansion) in print.probes.iter().zip(&expansions) {
                match expansion {
                    XyceAcCsdColumnExpansion::Scalar => {
                        let value = Self::evaluate_ac_probe(probe, netlist, result, false)?;
                        row.push(Self::xyce_default_prn_roundtrip(value).map_err(|err| {
                            format!(
                                "could not serialize relational AC probe '{probe}' at row {row_index}: {err}"
                            )
                        })?);
                    }
                    XyceAcCsdColumnExpansion::Complex => {
                        let value = Self::evaluate_ac_complex_probe(probe, netlist, result)?;
                        row.push(Self::xyce_default_prn_roundtrip(value.re).map_err(|err| {
                            format!(
                                "could not serialize real relational AC probe '{probe}' at row {row_index}: {err}"
                            )
                        })?);
                        row.push(Self::xyce_default_prn_roundtrip(value.im).map_err(|err| {
                            format!(
                                "could not serialize imaginary relational AC probe '{probe}' at row {row_index}: {err}"
                            )
                        })?);
                    }
                }
            }
            rows.push(row);
        }
        Ok(XycePrnTable { columns, rows })
    }

    fn run_ac_baseline_family_contract(
        &self,
        deck: &XyceDeck,
        contract: XyceBaselineFamilyContract,
        start: Instant,
    ) -> XyceTestResult {
        let kind_name = contract.kind.name();
        let wrapper_contract = contract.kind.wrapper_contract();
        let baseline_contract = contract.kind.baseline_contract();
        let Some(tolerance) = contract.comparison.ac_comparator_tolerance() else {
            return self.failure_result(
                deck,
                start,
                wrapper_contract,
                format!(
                    "{kind_name} family '{}' has no ACComparator tolerance contract",
                    contract.family
                ),
                Vec::new(),
            );
        };
        let baseline_plan = match self.relational_ac_plan_for_path(&contract.baseline_path) {
            Ok(plan) => plan,
            Err(reason) => {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' baseline is not supported by the relational AC adapter: {reason}",
                        contract.family
                    ),
                    Vec::new(),
                );
            }
        };
        if let Err(reason) = Self::validate_ac_analysis_expression_plan(&baseline_plan) {
            return self.failure_result(
                deck,
                start,
                wrapper_contract,
                format!(
                    "{kind_name} family '{}' baseline AC qualification failed: {reason}",
                    contract.family
                ),
                Vec::new(),
            );
        }
        let baseline_netlist =
            match Self::parse_xyce_netlist(&baseline_plan.source, &baseline_plan.deck_path) {
                Ok(netlist) => netlist,
                Err(err) => {
                    return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' baseline parse failed after qualification: {err}",
                        contract.family
                    ),
                    Vec::new(),
                );
                }
            };
        let baseline_snapshot =
            match Self::strict_ac_family_snapshot(contract.kind, &baseline_netlist) {
                Ok(snapshot) => snapshot,
                Err(reason) => {
                    return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' baseline semantic qualification failed: {reason}",
                        contract.family
                    ),
                    Vec::new(),
                );
                }
            };
        let engine = self.create_xyce_engine();
        let baseline_results = match engine.run_ac(&baseline_netlist, &baseline_plan.ac.frequencies)
        {
            Ok(results) => results,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' baseline error: {err}",
                        contract.family
                    ),
                    Vec::new(),
                );
            }
        };
        let baseline_table = match Self::ac_family_result_to_prn_table(
            &baseline_plan.print,
            &baseline_netlist,
            &baseline_results,
        ) {
            Ok(table) => table,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' baseline output conversion failed: {err}",
                        contract.family
                    ),
                    Vec::new(),
                );
            }
        };

        let (targets, baseline_record) = Self::baseline_family_targets(&contract);
        if targets.is_empty() {
            return self.failure_result(
                deck,
                start,
                wrapper_contract,
                format!(
                    "{kind_name} family '{}' has no non-baseline member to compare",
                    contract.family
                ),
                Vec::new(),
            );
        }
        let mut all_mismatches = Vec::new();
        for target_path in targets {
            let target_plan = match self.relational_ac_plan_for_path(&target_path) {
                Ok(plan) => plan,
                Err(reason) => {
                    return self.failure_result(
                        deck,
                        start,
                        wrapper_contract,
                        format!(
                            "{kind_name} family '{}' member {} is not supported by the relational AC adapter: {reason}",
                            contract.family,
                            self.display_path(&target_path)
                        ),
                        Vec::new(),
                    );
                }
            };
            if let Err(reason) = Self::validate_ac_analysis_expression_plan(&target_plan) {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' member {} AC qualification failed: {reason}",
                        contract.family,
                        self.display_path(&target_path)
                    ),
                    Vec::new(),
                );
            }
            if target_plan.print.probes != baseline_plan.print.probes
                || target_plan.ac.frequencies.len() != baseline_plan.ac.frequencies.len()
                || !target_plan
                    .ac
                    .frequencies
                    .iter()
                    .zip(&baseline_plan.ac.frequencies)
                    .all(|(target, baseline)| target.to_bits() == baseline.to_bits())
            {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' member {} changes the ordered .PRINT AC probes or resolved frequency grid",
                        contract.family,
                        self.display_path(&target_path)
                    ),
                    Vec::new(),
                );
            }
            let target_netlist = match Self::parse_xyce_netlist(
                &target_plan.source,
                &target_plan.deck_path,
            ) {
                Ok(netlist) => netlist,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        wrapper_contract,
                        format!(
                            "{kind_name} family '{}' member {} parse failed after qualification: {err}",
                            contract.family,
                            self.display_path(&target_path)
                        ),
                        Vec::new(),
                    );
                }
            };
            if !Self::ac_analyses_match_exactly(&baseline_netlist, &target_netlist) {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' member {} changes the .AC analysis tuple",
                        contract.family,
                        self.display_path(&target_path)
                    ),
                    Vec::new(),
                );
            }
            let target_snapshot = match Self::strict_ac_family_snapshot(
                contract.kind,
                &target_netlist,
            ) {
                Ok(snapshot) => snapshot,
                Err(reason) => {
                    return self.failure_result(
                        deck,
                        start,
                        wrapper_contract,
                        format!(
                            "{kind_name} family '{}' member {} semantic qualification failed: {reason}",
                            contract.family,
                            self.display_path(&target_path)
                        ),
                        Vec::new(),
                    );
                }
            };
            if let Err(reason) =
                Self::compare_strict_ac_family_snapshots(&baseline_snapshot, &target_snapshot)
            {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' member {} changes semantics outside its qualified representation pair: {reason}",
                        contract.family,
                        self.display_path(&target_path)
                    ),
                    Vec::new(),
                );
            }
            let target_results = match engine.run_ac(&target_netlist, &target_plan.ac.frequencies) {
                Ok(results) => results,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        wrapper_contract,
                        format!(
                            "{kind_name} family '{}' member {} error: {err}",
                            contract.family,
                            self.display_path(&target_path)
                        ),
                        Vec::new(),
                    );
                }
            };
            let target_table = match Self::ac_family_result_to_prn_table(
                &target_plan.print,
                &target_netlist,
                &target_results,
            ) {
                Ok(table) => table,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        wrapper_contract,
                        format!(
                            "{kind_name} family '{}' member {} output conversion failed: {err}",
                            contract.family,
                            self.display_path(&target_path)
                        ),
                        Vec::new(),
                    );
                }
            };
            let mut mismatches = match self.compare_ac_comparator_tables_with_tolerance(
                &baseline_table,
                &target_table,
                tolerance,
            ) {
                Ok(mismatches) => mismatches,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        wrapper_contract,
                        format!(
                            "{kind_name} family '{}' member {} ACComparator error: {err}",
                            contract.family,
                            self.display_path(&target_path)
                        ),
                        Vec::new(),
                    );
                }
            };
            for mismatch in &mut mismatches {
                mismatch.probe = format!("{} {}", self.display_path(&target_path), mismatch.probe);
            }
            all_mismatches.extend(mismatches);
            if all_mismatches.len() >= self.config.max_mismatches {
                all_mismatches.truncate(self.config.max_mismatches);
                break;
            }
        }

        if all_mismatches.is_empty() {
            self.passed_result(
                deck,
                start,
                if baseline_record {
                    baseline_contract
                } else {
                    wrapper_contract
                },
            )
        } else {
            self.failure_result(
                deck,
                start,
                wrapper_contract,
                format!(
                    "{} {kind_name} family '{}' ACComparator mismatch(es)",
                    all_mismatches.len(),
                    contract.family
                ),
                all_mismatches,
            )
        }
    }

    fn validate_exact_dc_family_plan(
        kind: XyceBaselineFamilyKind,
        plan: &XyceStaticDcPlan,
    ) -> Result<(), String> {
        match kind {
            XyceBaselineFamilyKind::BjtExternalNode => {
                Self::validate_bjt_external_node_dc_plan(plan)
            }
            XyceBaselineFamilyKind::DcAnalysisExpression => {
                Self::validate_dc_analysis_expression_plan(plan)
            }
            XyceBaselineFamilyKind::DelimitedExpression => {
                Self::validate_delimited_expression_plan(plan)
            }
            XyceBaselineFamilyKind::PassiveResPrimaryValue => {
                Self::validate_passive_res_primary_dc_plan(plan)
            }
            XyceBaselineFamilyKind::SubcktParameterPrecedence => {
                Self::validate_subckt_parameter_precedence_dc_plan(plan)
            }
            XyceBaselineFamilyKind::SubcktParameterResolution => {
                Self::validate_subckt_parameter_resolution_dc_plan(plan)
            }
            other => Err(format!(
                "family kind {} has no qualified exact-DC plan contract",
                other.name()
            )),
        }
    }

    fn strict_dc_family_snapshot(
        kind: XyceBaselineFamilyKind,
        netlist: &Netlist,
        plan: &XyceStaticDcPlan,
    ) -> Result<XyceStrictDcFamilySnapshot, String> {
        match kind {
            XyceBaselineFamilyKind::BjtExternalNode => {
                Self::bjt_external_node_family_snapshot(netlist, &plan.print)
                    .map(XyceStrictDcFamilySnapshot::BjtExternalNode)
            }
            XyceBaselineFamilyKind::DcAnalysisExpression => {
                Self::dc_analysis_expression_snapshot(netlist)
                    .map(XyceStrictDcFamilySnapshot::DcAnalysisExpression)
            }
            XyceBaselineFamilyKind::DelimitedExpression => {
                Self::delimited_expression_family_snapshot(plan, netlist)
                    .map(XyceStrictDcFamilySnapshot::DelimitedExpression)
            }
            XyceBaselineFamilyKind::PassiveResPrimaryValue => {
                Self::passive_res_primary_snapshot(netlist, &plan.print, &plan.dc.source)
                    .map(XyceStrictDcFamilySnapshot::PassivePrimaryValue)
            }
            XyceBaselineFamilyKind::SubcktParameterPrecedence => {
                Self::subckt_parameter_precedence_snapshot(netlist, &plan.print, &plan.dc.source)
                    .map(XyceStrictDcFamilySnapshot::SubcktParameterPrecedence)
            }
            XyceBaselineFamilyKind::SubcktParameterResolution => {
                Self::subckt_parameter_resolution_snapshot(netlist, &plan.print, &plan.dc.source)
                    .map(XyceStrictDcFamilySnapshot::SubcktParameterResolution)
            }
            other => Err(format!(
                "family kind {} has no qualified exact-DC semantic snapshot",
                other.name()
            )),
        }
    }

    fn compare_strict_dc_family_snapshots(
        baseline: &XyceStrictDcFamilySnapshot,
        target: &XyceStrictDcFamilySnapshot,
    ) -> Result<(), String> {
        match (baseline, target) {
            (
                XyceStrictDcFamilySnapshot::BjtExternalNode(baseline),
                XyceStrictDcFamilySnapshot::BjtExternalNode(target),
            ) => Self::compare_bjt_external_node_family_snapshots(baseline, target),
            (
                XyceStrictDcFamilySnapshot::DcAnalysisExpression(baseline),
                XyceStrictDcFamilySnapshot::DcAnalysisExpression(target),
            ) => Self::compare_dc_analysis_expression_snapshots(baseline, target),
            (
                XyceStrictDcFamilySnapshot::DelimitedExpression(baseline),
                XyceStrictDcFamilySnapshot::DelimitedExpression(target),
            ) => Self::compare_delimited_expression_snapshots(baseline, target),
            (
                XyceStrictDcFamilySnapshot::PassivePrimaryValue(baseline),
                XyceStrictDcFamilySnapshot::PassivePrimaryValue(target),
            ) => Self::compare_passive_primary_snapshots(baseline, target),
            (
                XyceStrictDcFamilySnapshot::SubcktParameterPrecedence(baseline),
                XyceStrictDcFamilySnapshot::SubcktParameterPrecedence(target),
            ) => {
                if baseline == target {
                    Ok(())
                } else {
                    Err("flattened resistor-divider semantics differ".to_string())
                }
            }
            (
                XyceStrictDcFamilySnapshot::SubcktParameterResolution(baseline),
                XyceStrictDcFamilySnapshot::SubcktParameterResolution(target),
            ) => {
                if baseline.representation
                    != XyceSubcktParameterResolutionRepresentation::FormalDefaultAndInstanceOverride
                    || target.representation
                        == XyceSubcktParameterResolutionRepresentation::UndefinedBinding
                    || !baseline
                        .parameter_name
                        .eq_ignore_ascii_case(&target.parameter_name)
                {
                    Err(
                        "subcircuit parameter-resolution roles or parameter identity differ"
                            .to_string(),
                    )
                } else if baseline.flattened_elements == target.flattened_elements {
                    Ok(())
                } else {
                    Err("flattened subcircuit parameter-resolution semantics differ".to_string())
                }
            }
            _ => Err("baseline and target use different exact-DC snapshot kinds".to_string()),
        }
    }

    fn run_exact_dc_baseline_family_contract(
        &self,
        deck: &XyceDeck,
        contract: XyceBaselineFamilyContract,
        baseline_plan: XyceStaticDcPlan,
        start: Instant,
    ) -> XyceTestResult {
        let kind_name = contract.kind.name();
        let wrapper_contract = contract.kind.wrapper_contract();
        let baseline_contract = contract.kind.baseline_contract();
        if let Err(reason) = Self::validate_exact_dc_family_plan(contract.kind, &baseline_plan) {
            return self.failure_result(
                deck,
                start,
                wrapper_contract,
                format!(
                    "{kind_name} family '{}' baseline exact-DC qualification failed: {reason}",
                    contract.family
                ),
                Vec::new(),
            );
        }

        let (baseline_netlist, baseline_results) =
            match self.run_static_dc_results(&baseline_plan, start) {
                Ok(results) => results,
                Err(SimulationError::Aborted) => {
                    return self.failure_result(
                        deck,
                        start,
                        wrapper_contract,
                        format!(
                            "{kind_name} family '{}' baseline exceeded timeout ({}ms)",
                            contract.family, self.config.max_time_per_test_ms
                        ),
                        Vec::new(),
                    );
                }
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        wrapper_contract,
                        format!(
                            "{kind_name} family '{}' baseline error: {err}",
                            contract.family
                        ),
                        Vec::new(),
                    );
                }
            };
        let baseline_snapshot =
            match Self::strict_dc_family_snapshot(contract.kind, &baseline_netlist, &baseline_plan)
            {
                Ok(snapshot) => snapshot,
                Err(reason) => {
                    return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' baseline semantic qualification failed: {reason}",
                        contract.family
                    ),
                    Vec::new(),
                );
                }
            };
        let baseline_table = match self.dc_results_to_prn_table(
            &baseline_plan,
            &baseline_netlist,
            &baseline_results,
        ) {
            Ok(table) => table,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' baseline exact output conversion failed: {err}",
                        contract.family
                    ),
                    Vec::new(),
                );
            }
        };
        let baseline_sweep = baseline_results
            .iter()
            .map(|point| point.sweep_value)
            .collect::<Vec<_>>();

        let (targets, baseline_record) = Self::baseline_family_targets(&contract);
        if targets.is_empty() {
            return self.failure_result(
                deck,
                start,
                wrapper_contract,
                format!(
                    "{kind_name} family '{}' has no non-baseline member to compare",
                    contract.family
                ),
                Vec::new(),
            );
        }

        for target_path in targets {
            let target_plan = match self
                .static_dc_plan_for_path(&target_path, ExpressionDialect::Xyce)
            {
                Ok(plan) => plan,
                Err(reason) => {
                    return self.failure_result(
                        deck,
                        start,
                        wrapper_contract,
                        format!(
                            "{kind_name} family '{}' member {} is not supported by the static DC adapter: {reason}",
                            contract.family,
                            self.display_path(&target_path)
                        ),
                        Vec::new(),
                    );
                }
            };
            if let Err(reason) = Self::validate_exact_dc_family_plan(contract.kind, &target_plan) {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' member {} exact-DC qualification failed: {reason}",
                        contract.family,
                        self.display_path(&target_path)
                    ),
                    Vec::new(),
                );
            }
            if target_plan.print.probes != baseline_plan.print.probes {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' exact member {} changes ordered .PRINT DC probes",
                        contract.family,
                        self.display_path(&target_path)
                    ),
                    Vec::new(),
                );
            }
            if !Self::dc_sweeps_match_exactly(&baseline_plan.dc, &target_plan.dc) {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' exact member {} changes the .DC analysis tuple",
                        contract.family,
                        self.display_path(&target_path)
                    ),
                    Vec::new(),
                );
            }

            let (target_netlist, target_results) =
                match self.run_static_dc_results(&target_plan, start) {
                    Ok(results) => results,
                    Err(SimulationError::Aborted) => {
                        return self.failure_result(
                            deck,
                            start,
                            wrapper_contract,
                            format!(
                                "{kind_name} family '{}' member {} exceeded timeout ({}ms)",
                                contract.family,
                                self.display_path(&target_path),
                                self.config.max_time_per_test_ms
                            ),
                            Vec::new(),
                        );
                    }
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            wrapper_contract,
                            format!(
                                "{kind_name} family '{}' member {} error: {err}",
                                contract.family,
                                self.display_path(&target_path)
                            ),
                            Vec::new(),
                        );
                    }
                };
            let target_snapshot = match Self::strict_dc_family_snapshot(
                contract.kind,
                &target_netlist,
                &target_plan,
            ) {
                Ok(snapshot) => snapshot,
                Err(reason) => {
                    return self.failure_result(
                            deck,
                            start,
                            wrapper_contract,
                            format!(
                                "{kind_name} family '{}' member {} semantic qualification failed: {reason}",
                                contract.family,
                                self.display_path(&target_path)
                            ),
                            Vec::new(),
                        );
                }
            };
            if let Err(reason) =
                Self::compare_strict_dc_family_snapshots(&baseline_snapshot, &target_snapshot)
            {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' member {} changes semantics outside its qualified representation pair: {reason}",
                        contract.family,
                        self.display_path(&target_path)
                    ),
                    Vec::new(),
                );
            }

            let target_table = match self.dc_results_to_prn_table(
                &target_plan,
                &target_netlist,
                &target_results,
            ) {
                Ok(table) => table,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        wrapper_contract,
                        format!(
                            "{kind_name} family '{}' member {} exact output conversion failed: {err}",
                            contract.family,
                            self.display_path(&target_path)
                        ),
                        Vec::new(),
                    );
                }
            };
            let target_sweep = target_results
                .iter()
                .map(|point| point.sweep_value)
                .collect::<Vec<_>>();
            let comparison = if contract.comparison.compares_prn_case_insensitively() {
                self.compare_serialized_default_prn_tables_case_insensitive(
                    &baseline_table,
                    &target_table,
                )
            } else if contract.comparison.compares_serialized_prn_exactly() {
                self.compare_serialized_default_prn_tables(&baseline_table, &target_table)
            } else {
                self.compare_exact_dc_prn_tables(
                    &baseline_table,
                    &target_table,
                    &baseline_sweep,
                    &target_sweep,
                )
            };
            let mut mismatches = match comparison {
                Ok(mismatches) => mismatches,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        wrapper_contract,
                        format!(
                            "{kind_name} family '{}' member {} exact comparison error: {err}",
                            contract.family,
                            self.display_path(&target_path)
                        ),
                        Vec::new(),
                    );
                }
            };
            if !mismatches.is_empty() {
                for mismatch in &mut mismatches {
                    mismatch.probe =
                        format!("{} {}", self.display_path(&target_path), mismatch.probe);
                }
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{} {kind_name} family '{}' member {} exact DC mismatch(es)",
                        mismatches.len(),
                        contract.family,
                        self.display_path(&target_path)
                    ),
                    mismatches,
                );
            }
        }

        let result_contract = if baseline_record {
            baseline_contract
        } else {
            wrapper_contract
        };
        self.passed_result(deck, start, result_contract)
    }

    fn run_transient_baseline_family_contract(
        &self,
        deck: &XyceDeck,
        contract: XyceBaselineFamilyContract,
        baseline_plan: XyceStaticTranPlan,
        start: Instant,
    ) -> XyceTestResult {
        let kind_name = contract.kind.name();
        let wrapper_contract = contract.kind.wrapper_contract();
        let baseline_contract = contract.kind.baseline_contract();
        if !baseline_plan.steps.is_empty() {
            return self.baseline_family_qualification_result(
                deck,
                start,
                wrapper_contract,
                contract.comparison,
                format!(
                    "{kind_name} family '{}' transient relational contract does not yet support .STEP output",
                    contract.family
                ),
            );
        }
        if baseline_plan.output_override {
            return self.baseline_family_qualification_result(
                deck,
                start,
                wrapper_contract,
                contract.comparison,
                format!(
                    "{kind_name} family '{}' transient relational contract does not support wrapper output overrides",
                    contract.family
                ),
            );
        }
        if contract.kind == XyceBaselineFamilyKind::SinExpression
            && let Err(err) = Self::validate_sin_expression_transient_plan(&baseline_plan)
        {
            return self.failure_result(
                deck,
                start,
                wrapper_contract,
                format!(
                    "{kind_name} family '{}' baseline qualification failed: {err}",
                    contract.family
                ),
                Vec::new(),
            );
        }
        if contract.kind == XyceBaselineFamilyKind::ParamExpression
            && let Err(err) = Self::validate_param_expression_transient_plan(&baseline_plan)
        {
            return self.failure_result(
                deck,
                start,
                wrapper_contract,
                format!(
                    "{kind_name} family '{}' baseline qualification failed: {err}",
                    contract.family
                ),
                Vec::new(),
            );
        }
        if contract.kind == XyceBaselineFamilyKind::PassiveCapPrimaryValue
            && let Err(err) = Self::validate_passive_cap_primary_transient_plan(&baseline_plan)
        {
            return self.failure_result(
                deck,
                start,
                wrapper_contract,
                format!(
                    "{kind_name} family '{}' baseline qualification failed: {err}",
                    contract.family
                ),
                Vec::new(),
            );
        }
        if contract.kind == XyceBaselineFamilyKind::PassiveTemperatureOverride
            && let Err(err) =
                Self::validate_passive_temperature_override_transient_plan(&baseline_plan)
        {
            return self.failure_result(
                deck,
                start,
                wrapper_contract,
                format!(
                    "{kind_name} family '{}' baseline qualification failed: {err}",
                    contract.family
                ),
                Vec::new(),
            );
        }
        if contract.kind == XyceBaselineFamilyKind::TransientAnalysisExpression
            && let Err(err) = Self::validate_transient_analysis_expression_plan(&baseline_plan)
        {
            return self.failure_result(
                deck,
                start,
                wrapper_contract,
                format!(
                    "{kind_name} family '{}' baseline qualification failed: {err}",
                    contract.family
                ),
                Vec::new(),
            );
        }

        let (baseline_netlist, baseline_result) = match self.run_transient_family_plan(
            &baseline_plan,
            start,
            None,
        ) {
            Ok(result) => result,
            Err(SimulationError::Aborted) => {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' transient baseline exceeded timeout ({}ms)",
                        contract.family, self.config.max_time_per_test_ms
                    ),
                    Vec::new(),
                );
            }
            Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                return self.baseline_family_qualification_result(
                    deck,
                    start,
                    wrapper_contract,
                    contract.comparison,
                    format!(
                        "{kind_name} family '{}' transient baseline is not supported by RSpice yet: {err}",
                        contract.family
                    ),
                );
            }
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' transient baseline error: {err}",
                        contract.family
                    ),
                    Vec::new(),
                );
            }
        };
        let baseline_snapshot = if contract.comparison.requires_semantic_snapshot() {
            match Self::strict_transient_family_snapshot(
                &contract,
                &baseline_netlist,
                &baseline_plan.print,
            ) {
                Ok(snapshot) => Some(snapshot),
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        wrapper_contract,
                        format!(
                            "{kind_name} family '{}' baseline semantic qualification failed: {err}",
                            contract.family
                        ),
                        Vec::new(),
                    );
                }
            }
        } else {
            None
        };
        let baseline_table = match Self::transient_family_result_to_prn_table(
            &baseline_plan,
            &baseline_netlist,
            &baseline_result,
        ) {
            Ok(table) => table,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' transient baseline output conversion failed: {err}",
                        contract.family
                    ),
                    Vec::new(),
                );
            }
        };
        if contract.kind.compares_transient_baseline_oracle() {
            let Some(reference_path) = self.static_prn_reference_path(&contract.baseline_path)
            else {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' baseline has no canonical .prn oracle path",
                        contract.family
                    ),
                    Vec::new(),
                );
            };
            if !reference_path.is_file() {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' canonical baseline oracle {} is missing",
                        contract.family,
                        self.display_path(&reference_path)
                    ),
                    Vec::new(),
                );
            }
            let reference = match Self::parse_prn_file(&reference_path) {
                Ok(reference) => reference,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        wrapper_contract,
                        format!(
                            "{kind_name} family '{}' baseline oracle parse error: {err}",
                            contract.family
                        ),
                        Vec::new(),
                    );
                }
            };
            let mismatches = match self.compare_static_tran_primary_reference(
                &reference,
                &baseline_plan,
                &baseline_netlist,
                &baseline_result,
            ) {
                Ok(mismatches) => mismatches,
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        wrapper_contract,
                        format!(
                            "{kind_name} family '{}' baseline oracle comparison error: {err}",
                            contract.family
                        ),
                        Vec::new(),
                    );
                }
            };
            if !mismatches.is_empty() {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{} {kind_name} family '{}' baseline oracle mismatch(es)",
                        mismatches.len(),
                        contract.family
                    ),
                    mismatches,
                );
            }
        }
        let baseline_time_scale = match Self::tran_print_time_scale_factor(&baseline_plan.source) {
            Ok(scale) => scale,
            Err(err) => {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' transient baseline time-scale error: {err}",
                        contract.family
                    ),
                    Vec::new(),
                );
            }
        };

        let (targets, baseline_record) = Self::baseline_family_targets(&contract);
        if targets.is_empty() {
            return self.baseline_family_qualification_result(
                deck,
                start,
                wrapper_contract,
                contract.comparison,
                format!(
                    "{kind_name} family '{}' has no non-baseline member to compare",
                    contract.family
                ),
            );
        }

        for target_path in targets {
            let target_plan = match self.static_tran_family_plan_for_path(
                &target_path,
                self.transient_family_plan_purpose_for_path(contract.kind, &target_path),
            ) {
                Ok(plan) => plan,
                Err(reason) => {
                    return self.baseline_family_qualification_result(
                        deck,
                        start,
                        wrapper_contract,
                        contract.comparison,
                        format!(
                            "{kind_name} family '{}' member {} is not supported by the static TRAN adapter: {reason}",
                            contract.family,
                            self.display_path(&target_path)
                        ),
                    );
                }
            };
            if !target_plan.steps.is_empty() || target_plan.output_override {
                return self.baseline_family_qualification_result(
                    deck,
                    start,
                    wrapper_contract,
                    contract.comparison,
                    format!(
                        "{kind_name} family '{}' member {} uses stepped or overridden transient output, which the relational contract does not yet support",
                        contract.family,
                        self.display_path(&target_path)
                    ),
                );
            }
            if contract.kind == XyceBaselineFamilyKind::SinExpression
                && let Err(err) = Self::validate_sin_expression_transient_plan(&target_plan)
            {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' member {} qualification failed: {err}",
                        contract.family,
                        self.display_path(&target_path)
                    ),
                    Vec::new(),
                );
            }
            if contract.kind == XyceBaselineFamilyKind::ParamExpression
                && let Err(err) = Self::validate_param_expression_transient_plan(&target_plan)
            {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' member {} qualification failed: {err}",
                        contract.family,
                        self.display_path(&target_path)
                    ),
                    Vec::new(),
                );
            }
            if contract.kind == XyceBaselineFamilyKind::PassiveCapPrimaryValue
                && let Err(err) = Self::validate_passive_cap_primary_transient_plan(&target_plan)
            {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' member {} qualification failed: {err}",
                        contract.family,
                        self.display_path(&target_path)
                    ),
                    Vec::new(),
                );
            }
            if contract.kind == XyceBaselineFamilyKind::PassiveTemperatureOverride
                && let Err(err) =
                    Self::validate_passive_temperature_override_transient_plan(&target_plan)
            {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' member {} qualification failed: {err}",
                        contract.family,
                        self.display_path(&target_path)
                    ),
                    Vec::new(),
                );
            }
            if contract.kind == XyceBaselineFamilyKind::TransientAnalysisExpression
                && let Err(err) = Self::validate_transient_analysis_expression_plan(&target_plan)
            {
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{kind_name} family '{}' member {} qualification failed: {err}",
                        contract.family,
                        self.display_path(&target_path)
                    ),
                    Vec::new(),
                );
            }
            if !Self::baseline_family_tran_contracts_compatible(
                contract.kind,
                baseline_plan.contract,
                target_plan.contract,
            ) {
                return self.baseline_family_qualification_result(
                    deck,
                    start,
                    wrapper_contract,
                    contract.comparison,
                    format!(
                        "{kind_name} family '{}' member {} uses {:?} transient output, but the baseline uses {:?}; relational formats must match",
                        contract.family,
                        self.display_path(&target_path),
                        target_plan.contract,
                        baseline_plan.contract
                    ),
                );
            }
            if contract.comparison.requires_exact_plan_equivalence() {
                if target_plan.print.probes != baseline_plan.print.probes {
                    return self.failure_result(
                        deck,
                        start,
                        wrapper_contract,
                        format!(
                            "{kind_name} family '{}' exact member {} changes ordered .PRINT TRAN probes",
                            contract.family,
                            self.display_path(&target_path)
                        ),
                        Vec::new(),
                    );
                }
                if !Self::tran_analyses_match_exactly(&baseline_plan.tran, &target_plan.tran) {
                    return self.failure_result(
                        deck,
                        start,
                        wrapper_contract,
                        format!(
                            "{kind_name} family '{}' exact member {} changes the .TRAN analysis tuple",
                            contract.family,
                            self.display_path(&target_path)
                        ),
                        Vec::new(),
                    );
                }
                if target_plan.timeint_conststep != baseline_plan.timeint_conststep {
                    return self.failure_result(
                        deck,
                        start,
                        wrapper_contract,
                        format!(
                            "{kind_name} family '{}' exact member {} changes constant-step output semantics",
                            contract.family,
                            self.display_path(&target_path)
                        ),
                        Vec::new(),
                    );
                }
            }
            let target_time_scale = match Self::tran_print_time_scale_factor(&target_plan.source) {
                Ok(scale) => scale,
                Err(err) => {
                    return self.baseline_family_qualification_result(
                        deck,
                        start,
                        wrapper_contract,
                        contract.comparison,
                        format!(
                            "{kind_name} family '{}' member {} has an unsupported transient time scale: {err}",
                            contract.family,
                            self.display_path(&target_path)
                        ),
                    );
                }
            };
            let time_scale_differs = if contract.comparison.requires_exact_plan_equivalence() {
                target_time_scale.to_bits() != baseline_time_scale.to_bits()
            } else {
                let scale = baseline_time_scale
                    .abs()
                    .max(target_time_scale.abs())
                    .max(1.0);
                (target_time_scale - baseline_time_scale).abs() > Value::EPSILON * scale
            };
            if time_scale_differs {
                let reason = format!(
                    "{kind_name} family '{}' member {} uses transient time scale {}, but the baseline uses {}",
                    contract.family,
                    self.display_path(&target_path),
                    target_time_scale,
                    baseline_time_scale
                );
                return self.baseline_family_qualification_result(
                    deck,
                    start,
                    wrapper_contract,
                    contract.comparison,
                    reason,
                );
            }

            let (target_netlist, target_result) = match self.run_transient_family_plan(
                &target_plan,
                start,
                None,
            ) {
                Ok(result) => result,
                Err(SimulationError::Aborted) => {
                    return self.failure_result(
                        deck,
                        start,
                        wrapper_contract,
                        format!(
                            "{kind_name} family '{}' member {} exceeded timeout ({}ms)",
                            contract.family,
                            self.display_path(&target_path),
                            self.config.max_time_per_test_ms
                        ),
                        Vec::new(),
                    );
                }
                Err(err) if Self::is_expected_unsupported_runtime_error(&err) => {
                    return self.baseline_family_qualification_result(
                        deck,
                        start,
                        wrapper_contract,
                        contract.comparison,
                        format!(
                            "{kind_name} family '{}' member {} is not supported by RSpice yet: {err}",
                            contract.family,
                            self.display_path(&target_path)
                        ),
                    );
                }
                Err(err) => {
                    return self.failure_result(
                        deck,
                        start,
                        wrapper_contract,
                        format!(
                            "{kind_name} family '{}' member {} error: {err}",
                            contract.family,
                            self.display_path(&target_path)
                        ),
                        Vec::new(),
                    );
                }
            };
            if let Some(baseline_snapshot) = baseline_snapshot.as_ref() {
                let target_snapshot = match Self::strict_transient_family_snapshot(
                    &contract,
                    &target_netlist,
                    &target_plan.print,
                ) {
                    Ok(snapshot) => snapshot,
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            wrapper_contract,
                            format!(
                                "{kind_name} family '{}' member {} semantic qualification failed: {err}",
                                contract.family,
                                self.display_path(&target_path)
                            ),
                            Vec::new(),
                        );
                    }
                };
                if let Err(err) = Self::compare_strict_transient_family_snapshots(
                    baseline_snapshot,
                    &target_snapshot,
                ) {
                    return self.failure_result(
                        deck,
                        start,
                        wrapper_contract,
                        format!(
                            "{kind_name} family '{}' member {} changes qualified semantic state: {err}",
                            contract.family,
                            self.display_path(&target_path)
                        ),
                        Vec::new(),
                    );
                }
            }

            let mut mismatches = if contract.comparison.compares_waveforms_exactly() {
                let target_table = match Self::transient_family_result_to_prn_table(
                    &target_plan,
                    &target_netlist,
                    &target_result,
                ) {
                    Ok(table) => table,
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            wrapper_contract,
                            format!(
                                "{kind_name} family '{}' member {} exact output conversion failed: {err}",
                                contract.family,
                                self.display_path(&target_path)
                            ),
                            Vec::new(),
                        );
                    }
                };
                let comparison = if contract.comparison.compares_serialized_prn_exactly() {
                    self.compare_serialized_default_prn_tables(&baseline_table, &target_table)
                } else {
                    self.compare_exact_prn_tables(
                        &baseline_table,
                        &target_table,
                        &baseline_result.time,
                        &target_result.time,
                    )
                };
                match comparison {
                    Ok(mismatches) => mismatches,
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            wrapper_contract,
                            format!(
                                "{kind_name} family '{}' member {} exact comparison error: {err}",
                                contract.family,
                                self.display_path(&target_path)
                            ),
                            Vec::new(),
                        );
                    }
                }
            } else if contract.comparison.uses_xyce_verify_transient_oracle() {
                let target_table = match Self::transient_family_result_to_prn_table(
                    &target_plan,
                    &target_netlist,
                    &target_result,
                ) {
                    Ok(table) => table,
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            wrapper_contract,
                            format!(
                                "{kind_name} family '{}' member {} xyce_verify output conversion failed: {err}",
                                contract.family,
                                self.display_path(&target_path)
                            ),
                            Vec::new(),
                        );
                    }
                };
                match self.compare_xyce_verify_transient_tables(&baseline_table, &target_table) {
                    Ok(mismatches) => mismatches,
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            wrapper_contract,
                            format!(
                                "{kind_name} family '{}' member {} xyce_verify comparison error: {err}",
                                contract.family,
                                self.display_path(&target_path)
                            ),
                            Vec::new(),
                        );
                    }
                }
            } else {
                match self.compare_tran_prn_reference(
                    &baseline_table,
                    &target_plan.print,
                    &target_netlist,
                    &baseline_plan.source,
                    &target_result,
                    None,
                ) {
                    Ok(mismatches) => mismatches,
                    Err(err) => {
                        return self.failure_result(
                            deck,
                            start,
                            wrapper_contract,
                            format!(
                                "{kind_name} family '{}' member {} comparison error: {err}",
                                contract.family,
                                self.display_path(&target_path)
                            ),
                            Vec::new(),
                        );
                    }
                }
            };
            if contract.comparison.permits_locked_time_retry() && !mismatches.is_empty() {
                let locked_run = self.run_transient_family_plan(
                    &target_plan,
                    start,
                    Some(baseline_result.time.clone()),
                );
                if let Ok((locked_netlist, locked_result)) = locked_run
                    && let Ok(locked_mismatches) = self.compare_tran_prn_reference(
                        &baseline_table,
                        &target_plan.print,
                        &locked_netlist,
                        &baseline_plan.source,
                        &locked_result,
                        None,
                    )
                    && Self::candidate_mismatches_are_better(Some(&mismatches), &locked_mismatches)
                {
                    mismatches = locked_mismatches;
                }
            }
            if !mismatches.is_empty() {
                for mismatch in &mut mismatches {
                    mismatch.probe =
                        format!("{} {}", self.display_path(&target_path), mismatch.probe);
                }
                return self.failure_result(
                    deck,
                    start,
                    wrapper_contract,
                    format!(
                        "{} {kind_name} family '{}' member {} transient baseline mismatch(es)",
                        mismatches.len(),
                        contract.family,
                        self.display_path(&target_path)
                    ),
                    mismatches,
                );
            }
        }

        let result_contract = if baseline_record {
            baseline_contract
        } else {
            wrapper_contract
        };
        self.passed_result(deck, start, result_contract)
    }

    fn run_transient_family_plan(
        &self,
        plan: &XyceStaticTranPlan,
        start: Instant,
        locked_time_grid: Option<Vec<Value>>,
    ) -> Result<(Netlist, TransientResult), SimulationError> {
        let netlist = Self::parse_xyce_netlist(&plan.source, &plan.deck_path)
            .map_err(|err| SimulationError::Netlist(format!("{err}")))?;
        let result = self.run_transient_family_netlist(plan, &netlist, start, locked_time_grid)?;
        Ok((netlist, result))
    }

    fn run_transient_family_netlist(
        &self,
        plan: &XyceStaticTranPlan,
        netlist: &Netlist,
        start: Instant,
        locked_time_grid: Option<Vec<Value>>,
    ) -> Result<TransientResult, SimulationError> {
        let max_step = Self::transient_family_max_step(netlist, &plan.tran)
            .map_err(SimulationError::Netlist)?;
        let initial_step = Self::xyce_initial_timestep_for_tran(&plan.tran);
        let engine = self.create_xyce_static_tran_engine(locked_time_grid, initial_step);
        let abort = DeadlineAbort::new(start, self.config.max_time_per_test_ms.max(1));
        engine.run_tran_with_abort(netlist, plan.tran.stop, max_step, &abort)
    }

    fn transient_family_max_step(
        netlist: &Netlist,
        tran: &XyceTranAnalysis,
    ) -> Result<Value, String> {
        let requested = tran.max_step.or_else(|| {
            (tran.step > 0.0)
                .then_some(tran.step)
                .and_then(|step| Self::feasible_oracle_limited_step(tran, step))
        });
        let source_step = Self::source_transient_max_step(netlist, tran)
            .and_then(|step| Self::feasible_oracle_limited_step(tran, step));
        let fallback = (tran.stop / 1000.0).max(f64::MIN_POSITIVE);
        let max_step = [requested, source_step, Some(fallback)]
            .into_iter()
            .flatten()
            .filter(|value| value.is_finite() && *value > 0.0)
            .reduce(Value::min)
            .unwrap_or(fallback);
        if !max_step.is_finite() || max_step <= 0.0 {
            return Err(format!(
                "resolved transient family maximum step must be finite and positive, got {max_step}"
            ));
        }
        let estimated_steps = (tran.stop / max_step).ceil();
        if estimated_steps > MAX_NATIVE_TRAN_ORACLE_STEPS {
            return Err(format!(
                "transient family execution envelope supports at most {:.0} native step(s), but this deck requires about {:.0}",
                MAX_NATIVE_TRAN_ORACLE_STEPS, estimated_steps
            ));
        }
        Self::validate_transient_execution_envelope(netlist, estimated_steps)?;
        Ok(max_step)
    }

    fn transient_family_result_to_prn_table(
        plan: &XyceStaticTranPlan,
        netlist: &Netlist,
        result: &TransientResult,
    ) -> Result<XycePrnTable, String> {
        Self::validate_transient_result_time_grid(result)?;
        let time_scale = Self::tran_print_time_scale_factor(&plan.source)?;
        let output_times = Self::xyce_verify_transient_output_times(plan, result)?;
        let columns = Self::transient_prn_header_columns(&plan.print, true);
        let mut stateful_expressions = plan
            .print
            .probes
            .iter()
            .map(|probe| Self::stateful_tran_print_expression(probe, netlist))
            .collect::<Result<Vec<_>, _>>()?;

        let mut rows = Vec::with_capacity(output_times.len());
        for (index, time) in output_times.into_iter().enumerate() {
            let mut row = Vec::with_capacity(columns.len());
            row.push(index as Value);
            row.push(time * time_scale);
            for (probe, stateful) in plan.print.probes.iter().zip(&mut stateful_expressions) {
                let value = match stateful {
                    Some(runtime) => Self::evaluate_stateful_tran_print_expression(
                        runtime, netlist, result, time,
                    )?,
                    None => Self::evaluate_tran_probe(probe, netlist, result, time)?,
                };
                if !value.is_finite() {
                    return Err(format!(
                        "baseline probe '{probe}' produced non-finite value {value} at time {time}"
                    ));
                }
                row.push(value);
            }
            rows.push(row);
        }

        Ok(XycePrnTable { columns, rows })
    }

    fn xyce_verify_transient_output_times(
        plan: &XyceStaticTranPlan,
        result: &TransientResult,
    ) -> Result<Vec<Value>, String> {
        let output_start = plan.tran.start.unwrap_or(0.0).max(0.0);
        let time_epsilon = 16.0 * Value::EPSILON * plan.tran.stop.abs().max(1.0);
        if let Some((initial_interval, transitions)) = Self::output_interval_schedule(&plan.source)?
        {
            let mut times = Vec::new();
            let mut next_time = 0.0;
            let mut interval = initial_interval;
            let mut boundaries = transitions;
            boundaries.push((plan.tran.stop, interval));
            for (boundary, next_interval) in boundaries {
                let segment_end = boundary.min(plan.tran.stop);
                while next_time < segment_end - time_epsilon {
                    if next_time + time_epsilon >= output_start {
                        times.push(next_time);
                        if times.len() > MAX_NATIVE_TRAN_ORACLE_STEPS as usize {
                            return Err(format!(
                                "OUTPUT schedule requests more than {:.0} serialized transient rows",
                                MAX_NATIVE_TRAN_ORACLE_STEPS
                            ));
                        }
                    }
                    next_time += interval;
                }
                if boundary > plan.tran.stop + time_epsilon {
                    break;
                }
                if boundary + time_epsilon >= output_start
                    && times
                        .last()
                        .is_none_or(|last| (boundary - *last).abs() > time_epsilon)
                {
                    times.push(boundary);
                }
                interval = next_interval;
                next_time = boundary + interval;
            }
            if times
                .last()
                .is_none_or(|last| (plan.tran.stop - *last).abs() > time_epsilon)
            {
                times.push(plan.tran.stop);
            }
            if times.is_empty() {
                return Err("transient output schedule produced no times".to_string());
            }
            return Ok(times);
        }

        let times = result
            .time
            .iter()
            .copied()
            .filter(|time| *time + time_epsilon >= output_start)
            .collect::<Vec<_>>();
        if times.is_empty() {
            return Err(format!(
                "transient result has no serialized sample at or after TSTART={output_start}"
            ));
        }
        Ok(times)
    }

    fn transient_prn_header_columns(print: &XycePrintRequest, include_index: bool) -> Vec<String> {
        let mut columns = Vec::with_capacity(print.probes.len() + usize::from(include_index) + 1);
        if include_index {
            columns.push("Index".to_string());
        }
        columns.push("TIME".to_string());
        columns.extend(print.probes.iter().cloned());
        columns
    }

    fn validate_noindex_tran_prn_header(first_line: &str) -> Result<(), String> {
        if first_line.trim().is_empty() {
            return Err("generated .prn output is empty".to_string());
        }
        let normalized = first_line.to_ascii_lowercase();
        if normalized.contains("index") {
            return Err(format!(
                "first output line contains forbidden Index text: {first_line}"
            ));
        }
        if !normalized.contains("time") {
            return Err(format!(
                "first output line does not contain required TIME text: {first_line}"
            ));
        }
        Ok(())
    }

    fn scoped_model_source_fingerprint(
        spec: &crate::netlist::SourceSpec,
    ) -> Result<(String, Vec<u64>), String> {
        match spec {
            crate::netlist::SourceSpec::Dc(value) => Ok(("DC".to_string(), vec![value.to_bits()])),
            crate::netlist::SourceSpec::Pulse {
                v1,
                v2,
                delay,
                rise,
                fall,
                width,
                period,
                phase,
                width_defaults_to_zero,
            } => Ok((
                "PULSE".to_string(),
                vec![
                    v1.to_bits(),
                    v2.to_bits(),
                    delay.to_bits(),
                    rise.to_bits(),
                    fall.to_bits(),
                    width.to_bits(),
                    period.to_bits(),
                    phase.to_bits(),
                    u64::from(*width_defaults_to_zero),
                ],
            )),
            _ => Err("unqualified scoped-model source waveform".to_string()),
        }
    }

    fn scoped_model_element_fingerprint(
        element: &crate::netlist::Element,
        params: &crate::netlist::expr::ParamContext,
    ) -> Result<XyceRelationalElementFingerprint, String> {
        let nodes = element
            .nodes
            .iter()
            .map(|node| node.trim().to_ascii_lowercase())
            .collect::<Vec<_>>();
        let (kind, numeric_bits, text) = match &element.kind {
            ElementKind::Resistor { value, .. } => {
                ("R".to_string(), vec![value.to_bits()], Vec::new())
            }
            ElementKind::Capacitor { value, .. } => {
                ("C".to_string(), vec![value.to_bits()], Vec::new())
            }
            ElementKind::VoltageSource(spec) => {
                let (waveform, numeric_bits) = Self::scoped_model_source_fingerprint(spec)?;
                (format!("V:{waveform}"), numeric_bits, Vec::new())
            }
            ElementKind::CurrentSource(spec) => {
                let (waveform, numeric_bits) = Self::scoped_model_source_fingerprint(spec)?;
                (format!("I:{waveform}"), numeric_bits, Vec::new())
            }
            ElementKind::Vccs {
                transconductance,
                control_nodes,
                ..
            } => (
                "G".to_string(),
                vec![transconductance.to_bits()],
                vec![
                    control_nodes.0.trim().to_ascii_lowercase(),
                    control_nodes.1.trim().to_ascii_lowercase(),
                ],
            ),
            ElementKind::BehavioralVoltage {
                expression,
                tc1,
                tc2,
            }
            | ElementKind::BehavioralCurrent {
                expression,
                tc1,
                tc2,
            } => {
                let kind = if matches!(&element.kind, ElementKind::BehavioralVoltage { .. }) {
                    "BV"
                } else {
                    "BI"
                };
                let prepared =
                    crate::netlist::expr::prepare_behavioral_expression(expression, params)
                        .map_err(|err| {
                            format!(
                                "could not canonicalize behavioral expression for '{}': {err}",
                                element.name
                            )
                        })?;
                (
                    kind.to_string(),
                    vec![tc1.to_bits(), tc2.to_bits()],
                    vec![prepared.trim().to_ascii_lowercase()],
                )
            }
            ElementKind::Bjt { .. } => ("Q".to_string(), Vec::new(), Vec::new()),
            ElementKind::Diode { .. } => ("D".to_string(), Vec::new(), Vec::new()),
            _ => {
                return Err(format!(
                    "flattened scoped-model family contains unqualified element '{}'",
                    element.name
                ));
            }
        };
        Ok(XyceRelationalElementFingerprint {
            kind,
            nodes,
            numeric_bits,
            text,
        })
    }

    fn single_spice_numeric_literal_value(field: &str) -> Result<Value, String> {
        if !Self::is_single_spice_numeric_literal(field) {
            return Err(format!(
                "'{field}' is not one direct finite SPICE numeric literal"
            ));
        }
        crate::netlist::lexer::parse_spice_value(field.trim())
            .map_err(|err| format!("could not parse direct numeric literal '{field}': {err}"))
    }

    fn is_single_spice_identifier(field: &str) -> bool {
        let Ok(tokens) = crate::netlist::lexer::tokenize(field.trim()) else {
            return false;
        };
        matches!(
            tokens
                .iter()
                .map(|token| &token.kind)
                .collect::<Vec<_>>()
                .as_slice(),
            [
                crate::netlist::lexer::TokenKind::Ident(_),
                crate::netlist::lexer::TokenKind::Eof
            ]
        )
    }

    fn is_single_spice_node_token(field: &str) -> bool {
        let Ok(tokens) = crate::netlist::lexer::tokenize(field.trim()) else {
            return false;
        };
        matches!(
            tokens
                .iter()
                .map(|token| &token.kind)
                .collect::<Vec<_>>()
                .as_slice(),
            [
                crate::netlist::lexer::TokenKind::Ident(_)
                    | crate::netlist::lexer::TokenKind::Number(_),
                crate::netlist::lexer::TokenKind::Eof
            ]
        )
    }

    fn is_analytic_rc_wrapper_candidate(source: &str) -> bool {
        let lines = Self::logical_netlist_lines(source);
        let Some(title) = lines.first() else {
            return false;
        };
        let title = Self::strip_netlist_comment(title).trim();
        if title.is_empty() || title.starts_with('.') {
            return false;
        }

        let mut capacitor_count = 0usize;
        let mut resistor_count = 0usize;
        let mut voltage_source_count = 0usize;
        let mut print_count = 0usize;
        let mut tran_count = 0usize;
        let mut options_count = 0usize;
        let mut end_count = 0usize;

        for line in lines.iter().skip(1) {
            let stripped = Self::strip_netlist_comment(line).trim();
            let Ok(fields) = Self::split_grouped_whitespace_fields(
                stripped,
                "analytic first-order RC candidate statement",
            ) else {
                return false;
            };
            let Some(command) = fields.first() else {
                continue;
            };
            if command.starts_with('.') {
                match command.to_ascii_lowercase().as_str() {
                    ".print"
                        if fields.len() == 3
                            && fields[1].eq_ignore_ascii_case("TRAN")
                            && Self::parse_voltage_probe(&fields[2]).is_some() =>
                    {
                        print_count += 1;
                    }
                    ".tran" if fields.len() == 3 => tran_count += 1,
                    ".options" if matches!(fields.len(), 4 | 5) => {
                        let keys = fields[1..]
                            .iter()
                            .map(|field| {
                                field
                                    .split_once('=')
                                    .map_or(field.as_str(), |(name, _)| name)
                                    .to_ascii_lowercase()
                            })
                            .collect::<BTreeSet<_>>();
                        let base_keys = ["timeint", "reltol", "abstol"]
                            .into_iter()
                            .map(str::to_string)
                            .collect::<BTreeSet<_>>();
                        let newlte_keys = ["timeint", "reltol", "abstol", "newlte"]
                            .into_iter()
                            .map(str::to_string)
                            .collect::<BTreeSet<_>>();
                        if keys != base_keys && keys != newlte_keys {
                            return false;
                        }
                        options_count += 1;
                    }
                    ".end" => end_count += 1,
                    _ => return false,
                }
                continue;
            }

            match command.chars().next().map(|ch| ch.to_ascii_uppercase()) {
                Some('C') => capacitor_count += 1,
                Some('R') => resistor_count += 1,
                Some('V') => voltage_source_count += 1,
                _ => return false,
            }
        }

        capacitor_count == 1
            && resistor_count == 1
            && voltage_source_count == 1
            && print_count == 1
            && tran_count == 1
            && options_count == 1
            && end_count == 1
    }

    fn analytic_rc_source_contract(source: &str) -> Result<XyceAnalyticRcSourceContract, String> {
        const LABEL: &str = "analytic first-order RC";
        if source.lines().any(|line| {
            line.split_whitespace()
                .next()
                .is_some_and(|field| field.eq_ignore_ascii_case("*COMP"))
        }) {
            return Err(format!(
                "{LABEL} uses the unmodified Release 7.10 xyce_verify defaults and does not admit *COMP directives"
            ));
        }

        let lines = Self::logical_netlist_lines(source);
        let Some(title) = lines.first() else {
            return Err(format!("{LABEL} requires a circuit title"));
        };
        let title = Self::strip_netlist_comment(title).trim();
        if title.is_empty() || title.starts_with('.') {
            return Err(format!("{LABEL} requires an ordinary circuit title"));
        }

        let mut capacitor = None;
        let mut resistor = None;
        let mut voltage_source = None;
        let mut print_probe = None;
        let mut tran_values = None;
        let mut option_values = None;
        let mut end_count = 0usize;
        let mut element_names = BTreeSet::new();

        for line in lines.iter().skip(1) {
            let stripped = Self::strip_netlist_comment(line).trim();
            let fields = Self::split_grouped_whitespace_fields(
                stripped,
                "analytic first-order RC source statement",
            )?;
            let Some(command) = fields.first() else {
                continue;
            };
            if command.starts_with('.') {
                match command.to_ascii_lowercase().as_str() {
                    ".print" => {
                        if print_probe.is_some()
                            || fields.len() != 3
                            || !fields[1].eq_ignore_ascii_case("TRAN")
                        {
                            return Err(format!(
                                "{LABEL} requires one canonical '.PRINT TRAN V(node)' statement"
                            ));
                        }
                        let probe = Self::parse_voltage_probe(&fields[2]).ok_or_else(|| {
                            format!("{LABEL} print token '{}' is not a voltage probe", fields[2])
                        })?;
                        if probe.accessor != XyceVoltageAccessor::Value
                            || probe.node_neg.is_some()
                            || !Self::is_single_spice_node_token(&probe.node_pos)
                        {
                            return Err(format!(
                                "{LABEL} requires one ordinary single-ended voltage probe"
                            ));
                        }
                        print_probe =
                            Some(Self::canonical_passive_primary_node_name(&probe.node_pos));
                    }
                    ".tran" => {
                        if tran_values.is_some() || fields.len() != 3 {
                            return Err(format!(
                                "{LABEL} requires one canonical '.TRAN step stop' statement"
                            ));
                        }
                        let step = Self::single_spice_numeric_literal_value(&fields[1])?;
                        let stop = Self::single_spice_numeric_literal_value(&fields[2])?;
                        if step < 0.0 || stop <= 0.0 {
                            return Err(format!(
                                "{LABEL} requires a finite nonnegative print step and positive stop time"
                            ));
                        }
                        tran_values = Some((step.to_bits(), stop.to_bits()));
                    }
                    ".options" => {
                        if option_values.is_some() || !matches!(fields.len(), 4 | 5) {
                            return Err(format!(
                                "{LABEL} requires exactly '.OPTIONS TIMEINT RELTOL=<numeric> ABSTOL=<numeric> [NEWLTE=<0..3>]'"
                            ));
                        }
                        let mut timeint = false;
                        let mut reltol = None;
                        let mut abstol = None;
                        let mut transient_lte_reference = None;
                        for option in &fields[1..] {
                            if option.eq_ignore_ascii_case("TIMEINT") {
                                if timeint {
                                    return Err(format!(
                                        "{LABEL} contains duplicate TIMEINT options"
                                    ));
                                }
                                timeint = true;
                                continue;
                            }
                            let Some((name, value)) = option.split_once('=') else {
                                return Err(format!(
                                    "{LABEL} option '{option}' is not a direct assignment"
                                ));
                            };
                            if value.contains('=') {
                                return Err(format!(
                                    "{LABEL} option '{option}' contains multiple assignments"
                                ));
                            }
                            let value = Self::single_spice_numeric_literal_value(value)?;
                            if name.eq_ignore_ascii_case("RELTOL") {
                                if value <= 0.0 {
                                    return Err(format!(
                                        "{LABEL} option '{name}' must be finite and positive"
                                    ));
                                }
                                if reltol.replace(value.to_bits()).is_some() {
                                    return Err(format!(
                                        "{LABEL} contains duplicate RELTOL options"
                                    ));
                                }
                            } else if name.eq_ignore_ascii_case("ABSTOL") {
                                if value <= 0.0 {
                                    return Err(format!(
                                        "{LABEL} option '{name}' must be finite and positive"
                                    ));
                                }
                                if abstol.replace(value.to_bits()).is_some() {
                                    return Err(format!(
                                        "{LABEL} contains duplicate ABSTOL options"
                                    ));
                                }
                            } else if name.eq_ignore_ascii_case("NEWLTE") {
                                let rounded = value.round();
                                if value != rounded || !(0.0..=3.0).contains(&rounded) {
                                    return Err(format!(
                                        "{LABEL} NEWLTE must be an integer from 0 to 3, found {value}"
                                    ));
                                }
                                let reference =
                                    TransientLteReference::from_xyce_selector(rounded as u8)
                                        .expect("range was checked above");
                                if transient_lte_reference.replace(reference).is_some() {
                                    return Err(format!(
                                        "{LABEL} contains duplicate NEWLTE options"
                                    ));
                                }
                            } else {
                                return Err(format!(
                                    "{LABEL} does not admit option assignment '{name}'"
                                ));
                            }
                        }
                        if !timeint || reltol.is_none() || abstol.is_none() {
                            return Err(format!(
                                "{LABEL} requires TIMEINT plus one RELTOL and one ABSTOL assignment"
                            ));
                        }
                        option_values = Some((
                            reltol.expect("checked above"),
                            abstol.expect("checked above"),
                            transient_lte_reference,
                        ));
                    }
                    ".end" if fields.len() == 1 => end_count += 1,
                    other => {
                        return Err(format!("{LABEL} does not admit directive '{other}'"));
                    }
                }
                continue;
            }

            if fields.len() < 4
                || !Self::is_single_spice_identifier(&fields[0])
                || !Self::is_single_spice_node_token(&fields[1])
                || !Self::is_single_spice_node_token(&fields[2])
            {
                return Err(format!(
                    "{LABEL} element '{command}' does not use direct name/node fields"
                ));
            }
            let element_name = Self::normalize_device_instance_name(&fields[0]);
            if !element_names.insert(element_name.clone()) {
                return Err(format!(
                    "{LABEL} contains duplicate element name '{element_name}'"
                ));
            }
            let nodes = [
                Self::canonical_passive_primary_node_name(&fields[1]),
                Self::canonical_passive_primary_node_name(&fields[2]),
            ];
            match fields[0].chars().next().map(|ch| ch.to_ascii_uppercase()) {
                Some('C') => {
                    if capacitor.is_some() || fields.len() != 5 {
                        return Err(format!(
                            "{LABEL} requires one 'Cname n+ n- value IC=<numeric>' element"
                        ));
                    }
                    let capacitance = Self::single_spice_numeric_literal_value(&fields[3])?;
                    let Some((name, value)) = fields[4].split_once('=') else {
                        return Err(format!("{LABEL} capacitor must contain IC=<numeric>"));
                    };
                    if value.contains('=') || !name.eq_ignore_ascii_case("IC") {
                        return Err(format!("{LABEL} capacitor must contain only IC=<numeric>"));
                    }
                    let initial_voltage = Self::single_spice_numeric_literal_value(value)?;
                    if capacitance <= 0.0 {
                        return Err(format!("{LABEL} capacitance must be positive"));
                    }
                    capacitor = Some((
                        element_name,
                        nodes,
                        capacitance.to_bits(),
                        initial_voltage.to_bits(),
                    ));
                }
                Some('R') => {
                    if resistor.is_some() || fields.len() != 4 {
                        return Err(format!(
                            "{LABEL} requires one direct 'Rname n+ n- value' element"
                        ));
                    }
                    let resistance = Self::single_spice_numeric_literal_value(&fields[3])?;
                    if resistance <= 0.0 {
                        return Err(format!("{LABEL} resistance must be positive"));
                    }
                    resistor = Some((element_name, nodes, resistance.to_bits()));
                }
                Some('V') => {
                    if voltage_source.is_some() || fields.len() != 4 {
                        return Err(format!("{LABEL} requires one direct DC voltage source"));
                    }
                    let value = Self::single_spice_numeric_literal_value(&fields[3])?;
                    voltage_source = Some((element_name, nodes, value.to_bits()));
                }
                _ => {
                    return Err(format!("{LABEL} does not admit element '{command}'"));
                }
            }
        }

        if end_count != 1 {
            return Err(format!(
                "{LABEL} requires exactly one .END statement, found {end_count}"
            ));
        }
        let (capacitor_name, capacitor_nodes, capacitance_bits, initial_voltage_bits) =
            capacitor.ok_or_else(|| format!("{LABEL} contains no qualified capacitor"))?;
        let (resistor_name, resistor_nodes, resistance_bits) =
            resistor.ok_or_else(|| format!("{LABEL} contains no qualified resistor"))?;
        let (source_name, source_nodes, source_value_bits) = voltage_source
            .ok_or_else(|| format!("{LABEL} contains no qualified voltage source"))?;
        let probe_node =
            print_probe.ok_or_else(|| format!("{LABEL} contains no qualified print probe"))?;
        let (tran_step_bits, tran_stop_bits) =
            tran_values.ok_or_else(|| format!("{LABEL} contains no qualified .TRAN"))?;
        let (reltol_bits, abstol_bits, transient_lte_reference) =
            option_values.ok_or_else(|| format!("{LABEL} contains no qualified .OPTIONS"))?;

        Ok(XyceAnalyticRcSourceContract {
            capacitor_name,
            capacitor_nodes,
            capacitance_bits,
            initial_voltage_bits,
            resistor_name,
            resistor_nodes,
            resistance_bits,
            source_name,
            source_nodes,
            source_value_bits,
            probe_node,
            tran_step_bits,
            tran_stop_bits,
            reltol_bits,
            abstol_bits,
            transient_lte_reference,
        })
    }

    fn analytic_timeint_only_options_match(
        options: &crate::netlist::SimulationOptions,
        reltol_bits: u64,
        abstol_bits: u64,
        method_selector: Option<&str>,
        lte_reference: Option<TransientLteReference>,
    ) -> bool {
        let crate::netlist::SimulationOptions {
            measure_fail_output: _,
            measure_default_value: _,
            measure_use_cont_files: _,
            reltol,
            abstol,
            vntol,
            iabstol,
            residual_reltol,
            gmin,
            method,
            trtol,
            timeint_reltol,
            timeint_abstol,
            transient_lte_reference,
            transient_new_bp_stepping,
            ramptime,
            digital_delay_type,
            xspice_event_trace_save,
            itl1,
            itl2,
            itl4,
            itl6,
            chgtol,
            pivtol,
            temp,
            tnom,
            seed,
            allow_simplified_mos,
            auto_bridge,
            auto_bridge_show_generated,
            auto_bridge_family,
            auto_bridge_templates,
            auto_bridge_param_names,
            topology_supernode,
            device_zero_resistance_tol,
            b3soi_gmin_scaling,
            hb_num_frequencies,
            nonlinear_continuation,
        } = options;
        reltol.is_none()
            && abstol.is_none()
            && timeint_reltol.is_some_and(|value| value.to_bits() == reltol_bits)
            && timeint_abstol.is_some_and(|value| value.to_bits() == abstol_bits)
            && *transient_lte_reference == lte_reference
            && transient_new_bp_stepping.is_none()
            && vntol.is_none()
            && iabstol.is_none()
            && residual_reltol.is_none()
            && gmin.is_none()
            && method.as_deref() == method_selector
            && trtol.is_none()
            && ramptime.is_none()
            && digital_delay_type.is_none()
            && xspice_event_trace_save.is_none()
            && itl1.is_none()
            && itl2.is_none()
            && itl4.is_none()
            && itl6.is_none()
            && chgtol.is_none()
            && pivtol.is_none()
            && temp.is_none()
            && tnom.is_none()
            && seed.is_none()
            && allow_simplified_mos.is_none()
            && auto_bridge.is_none()
            && auto_bridge_show_generated.is_none()
            && auto_bridge_family.is_none()
            && auto_bridge_templates.is_empty()
            && auto_bridge_param_names.is_empty()
            && topology_supernode.is_none()
            && device_zero_resistance_tol.is_none()
            && b3soi_gmin_scaling.is_none()
            && nonlinear_continuation.is_none()
            && hb_num_frequencies.is_empty()
    }

    fn analytic_rc_options_match(
        options: &crate::netlist::SimulationOptions,
        source: &XyceAnalyticRcSourceContract,
    ) -> bool {
        Self::analytic_timeint_only_options_match(
            options,
            source.reltol_bits,
            source.abstol_bits,
            None,
            source.transient_lte_reference,
        )
    }

    fn validate_analytic_rc_plan(
        plan: &XyceStaticTranPlan,
        source: &XyceAnalyticRcSourceContract,
    ) -> Result<(), String> {
        const LABEL: &str = "analytic first-order RC";
        if plan.contract != XyceStaticTranContract::WrapperStatic
            || !plan.steps.is_empty()
            || plan.output_override
            || plan.timeint_conststep
            || plan.wrapper_tolerance.is_some()
            || plan.reference_path.is_file()
        {
            return Err(format!(
                "{LABEL} requires one unstepped default-PRN wrapper output with a generated oracle"
            ));
        }
        if !plan.tran.step.is_finite()
            || !plan.tran.stop.is_finite()
            || plan.tran.step < 0.0
            || plan.tran.stop <= 0.0
            || plan.tran.start.is_some()
            || plan.tran.max_step.is_some()
            || plan.tran.uic
            || plan.tran.step.to_bits() != source.tran_step_bits
            || plan.tran.stop.to_bits() != source.tran_stop_bits
        {
            return Err(format!(
                "{LABEL} requires the direct finite '.TRAN step stop' tuple and no START, MAXSTEP, or UIC"
            ));
        }
        let [probe_text] = plan.print.probes.as_slice() else {
            return Err(format!("{LABEL} requires exactly one voltage probe"));
        };
        let probe = Self::parse_voltage_probe(probe_text)
            .ok_or_else(|| format!("{LABEL} probe '{probe_text}' is not a voltage probe"))?;
        if probe.accessor != XyceVoltageAccessor::Value
            || probe.node_neg.is_some()
            || Self::canonical_passive_primary_node_name(&probe.node_pos) != source.probe_node
        {
            return Err(format!(
                "{LABEL} requires the source-qualified single-ended voltage probe"
            ));
        }
        if Self::tran_print_time_scale_factor(&plan.source)?.to_bits() != 1.0f64.to_bits() {
            return Err(format!(
                "{LABEL} generator consumes physical TIME and does not admit output time scaling"
            ));
        }
        if Self::analytic_rc_source_contract(&plan.source)? != *source {
            return Err(format!(
                "{LABEL} plan source changed after source-form qualification"
            ));
        }
        Ok(())
    }

    fn analytic_rc_specification(
        netlist: &Netlist,
        plan: &XyceStaticTranPlan,
        source: &XyceAnalyticRcSourceContract,
    ) -> Result<XyceAnalyticRcSpecification, String> {
        const LABEL: &str = "analytic first-order RC";
        if netlist.title.trim().is_empty()
            || !netlist.models.is_empty()
            || !netlist.data_tables.is_empty()
            || !netlist.subcircuits.is_empty()
            || !netlist.initial_conditions.is_empty()
            || !netlist.node_sets.is_empty()
            || !netlist.global_nodes.is_empty()
            || !netlist.measurements.is_empty()
            || !netlist.veriloga_includes.is_empty()
            || !netlist.spef_includes.is_empty()
            || !netlist.diagnostics.is_empty()
        {
            return Err(format!(
                "{LABEL} contains model, auxiliary analysis, hierarchy, external-model, or diagnostic state"
            ));
        }
        if !netlist.params.all_params().is_empty()
            || !netlist.params.all_string_params().is_empty()
            || !netlist.params.all_functions().is_empty()
        {
            return Err(format!("{LABEL} does not admit parameters or functions"));
        }
        if !matches!(netlist.analyses.as_slice(), [AnalysisCommand::Tran { .. }]) {
            return Err(format!("{LABEL} requires exactly one transient analysis"));
        }
        if !Self::analytic_rc_options_match(&netlist.options, source) {
            return Err(format!(
                "{LABEL} parsed options differ from the bounded TIMEINT/RELTOL/ABSTOL source contract"
            ));
        }
        if netlist.elements.len() != 3 {
            return Err(format!(
                "{LABEL} requires exactly three elements, found {}",
                netlist.elements.len()
            ));
        }

        let mut elements = BTreeMap::new();
        for element in &netlist.elements {
            if let Some(alias) = element.nodes.iter().find(|node| {
                crate::compat::ground::is_spice_ground_name(node)
                    && !Self::passive_primary_name_is_literal_ground(node)
            }) {
                return Err(format!(
                    "element '{}' uses ground alias '{}'; {LABEL} requires literal node 0",
                    element.name, alias
                ));
            }
            let name = Self::normalize_device_instance_name(&element.name);
            if elements.insert(name.clone(), element).is_some() {
                return Err(format!("{LABEL} contains duplicate element name '{name}'"));
            }
        }
        let expected_names = [
            source.capacitor_name.clone(),
            source.resistor_name.clone(),
            source.source_name.clone(),
        ]
        .into_iter()
        .collect::<BTreeSet<_>>();
        if elements.keys().cloned().collect::<BTreeSet<_>>() != expected_names {
            return Err(format!(
                "{LABEL} parsed element inventory differs from direct source provenance"
            ));
        }

        let capacitor = elements
            .get(&source.capacitor_name)
            .expect("element inventory was checked");
        let capacitor_nodes = capacitor
            .nodes
            .iter()
            .map(|node| Self::canonical_passive_primary_node_name(node))
            .collect::<Vec<_>>();
        let ElementKind::Capacitor {
            value: capacitance,
            value_expr,
            initial_voltage,
            model,
            instance_params,
            deferred_params,
        } = &capacitor.kind
        else {
            return Err(format!(
                "source-qualified capacitor '{}' parsed as another element kind",
                capacitor.name
            ));
        };
        if capacitor_nodes.as_slice() != source.capacitor_nodes
            || !capacitance.is_finite()
            || capacitance.to_bits() != source.capacitance_bits
            || value_expr.is_some()
            || initial_voltage.map(Value::to_bits) != Some(source.initial_voltage_bits)
            || model.is_some()
            || !instance_params.is_empty()
            || !deferred_params.is_empty()
        {
            return Err(format!(
                "capacitor '{}' differs from the direct finite value/IC source contract",
                capacitor.name
            ));
        }
        let effective_capacitance = Self::effective_capacitor_value(netlist, &capacitor.name)
            .filter(|value| value.is_finite() && *value > 0.0)
            .ok_or_else(|| format!("{LABEL} capacitance did not resolve"))?;
        if effective_capacitance.to_bits() != source.capacitance_bits {
            return Err(format!(
                "{LABEL} explicit and effective capacitance values differ"
            ));
        }

        let resistor = elements
            .get(&source.resistor_name)
            .expect("element inventory was checked");
        let resistor_nodes = resistor
            .nodes
            .iter()
            .map(|node| Self::canonical_passive_primary_node_name(node))
            .collect::<Vec<_>>();
        let ElementKind::Resistor {
            value: resistance,
            value_expr,
            model,
            instance_params,
            deferred_params,
        } = &resistor.kind
        else {
            return Err(format!(
                "source-qualified resistor '{}' parsed as another element kind",
                resistor.name
            ));
        };
        if resistor_nodes.as_slice() != source.resistor_nodes
            || !resistance.is_finite()
            || resistance.to_bits() != source.resistance_bits
            || value_expr.is_some()
            || model.is_some()
            || !instance_params.is_empty()
            || !deferred_params.is_empty()
        {
            return Err(format!(
                "resistor '{}' differs from the direct finite source contract",
                resistor.name
            ));
        }
        let effective_resistance = Self::effective_resistor_value(netlist, &resistor.name)
            .filter(|value| value.is_finite() && *value > 0.0)
            .ok_or_else(|| format!("{LABEL} resistance did not resolve"))?;
        if effective_resistance.to_bits() != source.resistance_bits {
            return Err(format!(
                "{LABEL} explicit and effective resistance values differ"
            ));
        }

        let voltage_source = elements
            .get(&source.source_name)
            .expect("element inventory was checked");
        let source_nodes = voltage_source
            .nodes
            .iter()
            .map(|node| Self::canonical_passive_primary_node_name(node))
            .collect::<Vec<_>>();
        let ElementKind::VoltageSource(crate::netlist::SourceSpec::Dc(source_value)) =
            &voltage_source.kind
        else {
            return Err(format!(
                "source-qualified voltage source '{}' is not direct DC",
                voltage_source.name
            ));
        };
        if source_nodes.as_slice() != source.source_nodes
            || !source_value.is_finite()
            || source_value.to_bits() != source.source_value_bits
        {
            return Err(format!(
                "voltage source '{}' differs from direct source provenance",
                voltage_source.name
            ));
        }

        let [capacitor_node, capacitor_ground] = &source.capacitor_nodes;
        let [source_node, source_ground] = &source.source_nodes;
        let [resistor_a, resistor_b] = &source.resistor_nodes;
        if capacitor_ground != "0"
            || source_ground != "0"
            || capacitor_node == "0"
            || source_node == "0"
            || capacitor_node == source_node
            || source.probe_node != *capacitor_node
            || !((resistor_a == capacitor_node && resistor_b == source_node)
                || (resistor_b == capacitor_node && resistor_a == source_node))
        {
            return Err(format!(
                "{LABEL} topology must be modeled as C(output,0), R(output,source), and V(source,0)"
            ));
        }
        let initial_voltage = Value::from_bits(source.initial_voltage_bits);
        let initial_delta = initial_voltage - *source_value;
        if !initial_voltage.is_finite() || !initial_delta.is_finite() || initial_delta == 0.0 {
            return Err(format!(
                "{LABEL} requires a finite nontrivial initial-to-source voltage transition"
            ));
        }
        if plan.tran.stop.to_bits() != source.tran_stop_bits
            || plan.tran.step.to_bits() != source.tran_step_bits
        {
            return Err(format!("{LABEL} parsed and planned .TRAN tuples differ"));
        }
        let time_constant = effective_resistance * effective_capacitance;
        if !time_constant.is_finite() || time_constant <= 0.0 {
            return Err(format!(
                "{LABEL} RC time constant is not finite and positive"
            ));
        }
        if *source_value != XYCE_ANALYTIC_RC_ORACLE_FINAL_VALUE
            || initial_voltage.to_bits() != XYCE_ANALYTIC_RC_ORACLE_INITIAL_VALUE.to_bits()
            || time_constant.to_bits() != XYCE_ANALYTIC_RC_ORACLE_TIME_CONSTANT.to_bits()
        {
            return Err(format!(
                "{LABEL} deck must reproduce the generated Release 7.10 oracle with final value {}, initial value {}, and time constant {}",
                XYCE_ANALYTIC_RC_ORACLE_FINAL_VALUE,
                XYCE_ANALYTIC_RC_ORACLE_INITIAL_VALUE,
                XYCE_ANALYTIC_RC_ORACLE_TIME_CONSTANT,
            ));
        }

        Ok(XyceAnalyticRcSpecification {
            output_node: capacitor_node.clone(),
            source_value: *source_value,
            initial_voltage,
            resistance: effective_resistance,
            capacitance: effective_capacitance,
            time_constant,
        })
    }

    fn analytic_sinusoidal_rc_print_expression(probe: &str) -> Result<(String, Value), String> {
        let expression = Self::print_expression_inner(probe).ok_or_else(|| {
            "analytic sinusoidal RC print probe must be one braced expression".to_string()
        })?;
        if expression.chars().any(char::is_whitespace) {
            return Err(
                "analytic sinusoidal RC expression must remain one whitespace-free wrapper token"
                    .to_string(),
            );
        }
        let ast = parse_expression_strict(expression)
            .map_err(|err| format!("could not parse analytic sinusoidal RC expression: {err}"))?;
        let Expr::Binary {
            op: crate::expr::BinaryOp::Add,
            left,
            right,
        } = ast
        else {
            return Err(
                "analytic sinusoidal RC expression must directly add V(output) and an offset"
                    .to_string(),
            );
        };
        let Expr::NodeVoltage(node) = left.as_ref() else {
            return Err(
                "analytic sinusoidal RC expression left operand must be one direct V(output) probe"
                    .to_string(),
            );
        };
        if !Self::is_single_spice_node_token(node) {
            return Err(
                "analytic sinusoidal RC expression voltage node must be one direct node token"
                    .to_string(),
            );
        }
        let Expr::Const(offset) = right.as_ref() else {
            return Err(
                "analytic sinusoidal RC expression offset must be one direct numeric literal"
                    .to_string(),
            );
        };
        if !offset.is_finite() {
            return Err("analytic sinusoidal RC expression offset must be finite".to_string());
        }
        Ok((Self::canonical_passive_primary_node_name(node), *offset))
    }

    fn is_analytic_sinusoidal_rc_wrapper_candidate(source: &str) -> bool {
        let lines = Self::logical_netlist_lines(source);
        let Some(title) = lines.first() else {
            return false;
        };
        let title = Self::strip_netlist_comment(title).trim();
        if title.is_empty() || title.starts_with('.') {
            return false;
        }

        let mut capacitor_count = 0usize;
        let mut resistor_count = 0usize;
        let mut sinusoidal_voltage_count = 0usize;
        let mut print_count = 0usize;
        let mut tran_count = 0usize;
        let mut options_count = 0usize;
        let mut end_count = 0usize;
        for line in lines.iter().skip(1) {
            let stripped = Self::strip_netlist_comment(line).trim();
            let Ok(fields) = Self::split_grouped_whitespace_fields(
                stripped,
                "analytic sinusoidal RC candidate statement",
            ) else {
                return false;
            };
            let Some(command) = fields.first() else {
                continue;
            };
            if command.starts_with('.') {
                match command.to_ascii_lowercase().as_str() {
                    ".print"
                        if fields.len() == 3
                            && fields[1].eq_ignore_ascii_case("TRAN")
                            && Self::print_expression_inner(&fields[2]).is_some() =>
                    {
                        print_count += 1;
                    }
                    ".tran" if fields.len() == 3 => tran_count += 1,
                    ".options" if fields.len() == 5 => {
                        let keys = fields[1..]
                            .iter()
                            .map(|field| {
                                field
                                    .split_once('=')
                                    .map_or(field.as_str(), |(name, _)| name)
                                    .to_ascii_lowercase()
                            })
                            .collect::<BTreeSet<_>>();
                        let expected = ["timeint", "reltol", "abstol", "method"]
                            .into_iter()
                            .map(str::to_string)
                            .collect::<BTreeSet<_>>();
                        if keys != expected {
                            return false;
                        }
                        options_count += 1;
                    }
                    ".end" if fields.len() == 1 => end_count += 1,
                    _ => return false,
                }
                continue;
            }

            match command.chars().next().map(|ch| ch.to_ascii_uppercase()) {
                Some('C') => capacitor_count += 1,
                Some('R') => resistor_count += 1,
                Some('V')
                    if fields
                        .get(3)
                        .is_some_and(|field| field.eq_ignore_ascii_case("SIN")) =>
                {
                    sinusoidal_voltage_count += 1;
                }
                _ => return false,
            }
        }

        capacitor_count == 1
            && resistor_count == 1
            && sinusoidal_voltage_count == 1
            && print_count == 1
            && tran_count == 1
            && options_count == 1
            && end_count == 1
    }

    fn analytic_sinusoidal_rc_source_contract(
        source: &str,
    ) -> Result<XyceAnalyticSinusoidalRcSourceContract, String> {
        const LABEL: &str = "analytic sinusoidal first-order RC";

        let comp_lines = source
            .lines()
            .filter(|line| {
                line.split_whitespace()
                    .next()
                    .is_some_and(|token| token.eq_ignore_ascii_case("*COMP"))
            })
            .collect::<Vec<_>>();
        let [comp_line] = comp_lines.as_slice() else {
            return Err(format!(
                "{LABEL} requires exactly one *COMP directive, found {}",
                comp_lines.len()
            ));
        };
        let comp_fields = Self::split_grouped_whitespace_fields(
            comp_line.trim(),
            "analytic sinusoidal RC *COMP directive",
        )?;
        let [
            comp_command,
            comp_probe,
            first_comp_option,
            second_comp_option,
        ] = comp_fields.as_slice()
        else {
            return Err(format!(
                "{LABEL} requires exactly '*COMP {{expression}} RELTOL=<numeric> ABSTOL=<numeric>'"
            ));
        };
        if !comp_command.eq_ignore_ascii_case("*COMP") {
            return Err(format!("{LABEL} comparison directive opcode changed"));
        }
        let mut verify_reltol = None;
        let mut verify_abstol = None;
        for option in [first_comp_option, second_comp_option] {
            let Some((name, value)) = option.split_once('=') else {
                return Err(format!(
                    "{LABEL} *COMP option '{option}' is not an assignment"
                ));
            };
            if value.contains('=') {
                return Err(format!("{LABEL} *COMP option '{option}' is malformed"));
            }
            let value = Self::single_spice_numeric_literal_value(value)?;
            if value <= 0.0 {
                return Err(format!("{LABEL} *COMP {name} must be finite and positive"));
            }
            if name.eq_ignore_ascii_case("RELTOL") {
                if verify_reltol.replace(value.to_bits()).is_some() {
                    return Err(format!("{LABEL} contains duplicate *COMP RELTOL"));
                }
            } else if name.eq_ignore_ascii_case("ABSTOL") {
                if verify_abstol.replace(value.to_bits()).is_some() {
                    return Err(format!("{LABEL} contains duplicate *COMP ABSTOL"));
                }
            } else {
                return Err(format!("{LABEL} does not admit *COMP option '{name}'"));
            }
        }
        let verify_reltol_bits =
            verify_reltol.ok_or_else(|| format!("{LABEL} *COMP has no RELTOL"))?;
        let verify_abstol_bits =
            verify_abstol.ok_or_else(|| format!("{LABEL} *COMP has no ABSTOL"))?;

        let lines = Self::logical_netlist_lines(source);
        let Some(title) = lines.first() else {
            return Err(format!("{LABEL} requires a circuit title"));
        };
        let title = Self::strip_netlist_comment(title).trim();
        if title.is_empty() || title.starts_with('.') {
            return Err(format!("{LABEL} requires an ordinary circuit title"));
        }

        let mut capacitor = None;
        let mut resistor = None;
        let mut voltage_source = None;
        let mut print_probe = None;
        let mut tran_values = None;
        let mut option_values = None;
        let mut end_count = 0usize;
        let mut element_names = BTreeSet::new();
        for line in lines.iter().skip(1) {
            let stripped = Self::strip_netlist_comment(line).trim();
            let fields = Self::split_grouped_whitespace_fields(
                stripped,
                "analytic sinusoidal RC source statement",
            )?;
            let Some(command) = fields.first() else {
                continue;
            };
            if command.starts_with('.') {
                match command.to_ascii_lowercase().as_str() {
                    ".print" => {
                        if print_probe.is_some()
                            || fields.len() != 3
                            || !fields[1].eq_ignore_ascii_case("TRAN")
                        {
                            return Err(format!(
                                "{LABEL} requires one canonical '.PRINT TRAN {{V(node)+offset}}'"
                            ));
                        }
                        let (node, offset) =
                            Self::analytic_sinusoidal_rc_print_expression(&fields[2])?;
                        print_probe = Some((node, fields[2].clone(), offset.to_bits()));
                    }
                    ".tran" => {
                        if tran_values.is_some() || fields.len() != 3 {
                            return Err(format!(
                                "{LABEL} requires one canonical '.TRAN step stop'"
                            ));
                        }
                        let step = Self::single_spice_numeric_literal_value(&fields[1])?;
                        let stop = Self::single_spice_numeric_literal_value(&fields[2])?;
                        if step < 0.0 || stop <= 0.0 {
                            return Err(format!(
                                "{LABEL} requires a nonnegative print step and positive stop time"
                            ));
                        }
                        tran_values = Some((step.to_bits(), stop.to_bits()));
                    }
                    ".options" => {
                        if option_values.is_some() || fields.len() != 5 {
                            return Err(format!(
                                "{LABEL} requires exactly '.OPTIONS TIMEINT RELTOL=<numeric> ABSTOL=<numeric> METHOD=7'"
                            ));
                        }
                        let mut timeint = false;
                        let mut reltol = None;
                        let mut abstol = None;
                        let mut method = None;
                        for option in &fields[1..] {
                            if option.eq_ignore_ascii_case("TIMEINT") {
                                if timeint {
                                    return Err(format!("{LABEL} contains duplicate TIMEINT"));
                                }
                                timeint = true;
                                continue;
                            }
                            let Some((name, value)) = option.split_once('=') else {
                                return Err(format!(
                                    "{LABEL} option '{option}' is not a direct assignment"
                                ));
                            };
                            if value.contains('=') {
                                return Err(format!("{LABEL} option '{option}' is malformed"));
                            }
                            let value = Self::single_spice_numeric_literal_value(value)?;
                            if name.eq_ignore_ascii_case("RELTOL") {
                                if value <= 0.0 || reltol.replace(value.to_bits()).is_some() {
                                    return Err(format!(
                                        "{LABEL} requires one positive TIMEINT RELTOL"
                                    ));
                                }
                            } else if name.eq_ignore_ascii_case("ABSTOL") {
                                if value <= 0.0 || abstol.replace(value.to_bits()).is_some() {
                                    return Err(format!(
                                        "{LABEL} requires one positive TIMEINT ABSTOL"
                                    ));
                                }
                            } else if name.eq_ignore_ascii_case("METHOD") {
                                if value != 7.0 || method.replace("7".to_string()).is_some() {
                                    return Err(format!(
                                        "{LABEL} requires the direct Xyce ONESTEP selector METHOD=7"
                                    ));
                                }
                            } else {
                                return Err(format!("{LABEL} does not admit option '{name}'"));
                            }
                        }
                        if !timeint || reltol.is_none() || abstol.is_none() || method.is_none() {
                            return Err(format!(
                                "{LABEL} requires TIMEINT, RELTOL, ABSTOL, and METHOD=7 exactly once"
                            ));
                        }
                        option_values = Some((
                            reltol.expect("checked above"),
                            abstol.expect("checked above"),
                            method.expect("checked above"),
                        ));
                    }
                    ".end" if fields.len() == 1 => end_count += 1,
                    other => return Err(format!("{LABEL} does not admit directive '{other}'")),
                }
                continue;
            }

            if fields.len() < 4
                || !Self::is_single_spice_identifier(&fields[0])
                || !Self::is_single_spice_node_token(&fields[1])
                || !Self::is_single_spice_node_token(&fields[2])
            {
                return Err(format!(
                    "{LABEL} element '{command}' does not use direct name/node fields"
                ));
            }
            let element_name = Self::normalize_device_instance_name(&fields[0]);
            if !element_names.insert(element_name.clone()) {
                return Err(format!(
                    "{LABEL} contains duplicate element '{element_name}'"
                ));
            }
            let nodes = [
                Self::canonical_passive_primary_node_name(&fields[1]),
                Self::canonical_passive_primary_node_name(&fields[2]),
            ];
            match fields[0].chars().next().map(|ch| ch.to_ascii_uppercase()) {
                Some('C') => {
                    if capacitor.is_some() || fields.len() != 4 {
                        return Err(format!(
                            "{LABEL} requires one direct capacitor without model or IC fields"
                        ));
                    }
                    let value = Self::single_spice_numeric_literal_value(&fields[3])?;
                    if value <= 0.0 {
                        return Err(format!("{LABEL} capacitance must be positive"));
                    }
                    capacitor = Some((element_name, nodes, value.to_bits()));
                }
                Some('R') => {
                    if resistor.is_some() || fields.len() != 4 {
                        return Err(format!("{LABEL} requires one direct resistor"));
                    }
                    let value = Self::single_spice_numeric_literal_value(&fields[3])?;
                    if value <= 0.0 {
                        return Err(format!("{LABEL} resistance must be positive"));
                    }
                    resistor = Some((element_name, nodes, value.to_bits()));
                }
                Some('V') => {
                    if voltage_source.is_some()
                        || fields.len() != 9
                        || !fields[3].eq_ignore_ascii_case("SIN")
                    {
                        return Err(format!(
                            "{LABEL} requires one direct 'Vname n+ n- SIN vo va freq td theta' source"
                        ));
                    }
                    let values = fields[4..]
                        .iter()
                        .map(|field| Self::single_spice_numeric_literal_value(field))
                        .collect::<Result<Vec<_>, _>>()?;
                    let [offset, amplitude, frequency, delay, damping] = values.as_slice() else {
                        unreachable!("source arity was checked");
                    };
                    if *amplitude == 0.0 || *frequency <= 0.0 || *delay < 0.0 {
                        return Err(format!(
                            "{LABEL} source requires nonzero amplitude, positive frequency, and nonnegative delay"
                        ));
                    }
                    voltage_source = Some((
                        element_name,
                        nodes,
                        offset.to_bits(),
                        amplitude.to_bits(),
                        frequency.to_bits(),
                        delay.to_bits(),
                        damping.to_bits(),
                    ));
                }
                _ => return Err(format!("{LABEL} does not admit element '{command}'")),
            }
        }

        if end_count != 1 {
            return Err(format!(
                "{LABEL} requires exactly one .END statement, found {end_count}"
            ));
        }
        let (capacitor_name, capacitor_nodes, capacitance_bits) =
            capacitor.ok_or_else(|| format!("{LABEL} contains no qualified capacitor"))?;
        let (resistor_name, resistor_nodes, resistance_bits) =
            resistor.ok_or_else(|| format!("{LABEL} contains no qualified resistor"))?;
        let (
            source_name,
            source_nodes,
            source_offset_bits,
            source_amplitude_bits,
            source_frequency_bits,
            source_delay_bits,
            source_damping_bits,
        ) = voltage_source.ok_or_else(|| format!("{LABEL} contains no qualified SIN source"))?;
        let (probe_node, print_expression, print_offset_bits) =
            print_probe.ok_or_else(|| format!("{LABEL} contains no qualified print expression"))?;
        let (tran_step_bits, tran_stop_bits) =
            tran_values.ok_or_else(|| format!("{LABEL} contains no qualified .TRAN"))?;
        let (timeint_reltol_bits, timeint_abstol_bits, method_selector) =
            option_values.ok_or_else(|| format!("{LABEL} contains no qualified .OPTIONS"))?;

        if Self::normalize_probe(comp_probe) != Self::normalize_probe(&print_expression) {
            return Err(format!(
                "{LABEL} *COMP probe must exactly match the printed expression"
            ));
        }
        let fixed_values = [
            (
                "resistance",
                resistance_bits,
                XYCE_ANALYTIC_SINUSOIDAL_RC_ORACLE_RESISTANCE.to_bits(),
            ),
            (
                "capacitance",
                capacitance_bits,
                XYCE_ANALYTIC_SINUSOIDAL_RC_ORACLE_CAPACITANCE.to_bits(),
            ),
            (
                "source offset",
                source_offset_bits,
                XYCE_ANALYTIC_SINUSOIDAL_RC_ORACLE_SOURCE_OFFSET.to_bits(),
            ),
            (
                "source amplitude",
                source_amplitude_bits,
                XYCE_ANALYTIC_SINUSOIDAL_RC_ORACLE_SOURCE_AMPLITUDE.to_bits(),
            ),
            (
                "source frequency",
                source_frequency_bits,
                XYCE_ANALYTIC_SINUSOIDAL_RC_ORACLE_FREQUENCY.to_bits(),
            ),
            ("source delay", source_delay_bits, 0.0f64.to_bits()),
            ("source damping", source_damping_bits, 0.0f64.to_bits()),
            (
                "print offset",
                print_offset_bits,
                XYCE_ANALYTIC_SINUSOIDAL_RC_ORACLE_PRINT_OFFSET.to_bits(),
            ),
            (".TRAN print step", tran_step_bits, 0.0f64.to_bits()),
            (
                ".TRAN stop",
                tran_stop_bits,
                XYCE_ANALYTIC_SINUSOIDAL_RC_ORACLE_STOP.to_bits(),
            ),
            (
                "TIMEINT RELTOL",
                timeint_reltol_bits,
                XYCE_ANALYTIC_SINUSOIDAL_RC_TIMEINT_TOLERANCE.to_bits(),
            ),
            (
                "TIMEINT ABSTOL",
                timeint_abstol_bits,
                XYCE_ANALYTIC_SINUSOIDAL_RC_TIMEINT_TOLERANCE.to_bits(),
            ),
            (
                "*COMP RELTOL",
                verify_reltol_bits,
                XYCE_ANALYTIC_SINUSOIDAL_RC_VERIFY_TOLERANCE.to_bits(),
            ),
            (
                "*COMP ABSTOL",
                verify_abstol_bits,
                XYCE_ANALYTIC_SINUSOIDAL_RC_VERIFY_TOLERANCE.to_bits(),
            ),
        ];
        if let Some((name, actual, expected)) = fixed_values
            .into_iter()
            .find(|(_, actual, expected)| actual != expected)
        {
            return Err(format!(
                "{LABEL} {name} differs from the fixed Release 7.10 generator: actual={}, expected={}",
                Value::from_bits(actual),
                Value::from_bits(expected)
            ));
        }

        Ok(XyceAnalyticSinusoidalRcSourceContract {
            capacitor_name,
            capacitor_nodes,
            capacitance_bits,
            resistor_name,
            resistor_nodes,
            resistance_bits,
            source_name,
            source_nodes,
            source_offset_bits,
            source_amplitude_bits,
            source_frequency_bits,
            source_delay_bits,
            source_damping_bits,
            probe_node,
            print_expression,
            print_offset_bits,
            tran_step_bits,
            tran_stop_bits,
            timeint_reltol_bits,
            timeint_abstol_bits,
            method_selector,
            verify_reltol_bits,
            verify_abstol_bits,
        })
    }

    fn analytic_sinusoidal_rc_options_match(
        options: &crate::netlist::SimulationOptions,
        source: &XyceAnalyticSinusoidalRcSourceContract,
    ) -> bool {
        Self::analytic_timeint_only_options_match(
            options,
            source.timeint_reltol_bits,
            source.timeint_abstol_bits,
            Some(source.method_selector.as_str()),
            None,
        )
    }

    fn validate_analytic_sinusoidal_rc_plan(
        plan: &XyceStaticTranPlan,
        source: &XyceAnalyticSinusoidalRcSourceContract,
    ) -> Result<(), String> {
        const LABEL: &str = "analytic sinusoidal first-order RC";
        if plan.contract != XyceStaticTranContract::WrapperStatic
            || !plan.steps.is_empty()
            || plan.output_override
            || plan.timeint_conststep
            || plan.wrapper_tolerance.is_some()
            || plan.reference_path.is_file()
        {
            return Err(format!(
                "{LABEL} requires one unstepped default-PRN wrapper output with a generated oracle"
            ));
        }
        if !plan.tran.step.is_finite()
            || !plan.tran.stop.is_finite()
            || plan.tran.step < 0.0
            || plan.tran.stop <= 0.0
            || plan.tran.start.is_some()
            || plan.tran.max_step.is_some()
            || plan.tran.uic
            || plan.tran.step.to_bits() != source.tran_step_bits
            || plan.tran.stop.to_bits() != source.tran_stop_bits
        {
            return Err(format!(
                "{LABEL} requires the direct '.TRAN 0 2e-4' tuple and no START, MAXSTEP, or UIC"
            ));
        }
        let [probe] = plan.print.probes.as_slice() else {
            return Err(format!("{LABEL} requires exactly one print expression"));
        };
        if Self::normalize_probe(probe) != Self::normalize_probe(&source.print_expression) {
            return Err(format!(
                "{LABEL} planned probe differs from direct source provenance"
            ));
        }
        let (probe_node, offset) = Self::analytic_sinusoidal_rc_print_expression(probe)?;
        if probe_node != source.probe_node || offset.to_bits() != source.print_offset_bits {
            return Err(format!(
                "{LABEL} planned print expression changed its node or offset"
            ));
        }
        if Self::tran_print_time_scale_factor(&plan.source)?.to_bits() != 1.0f64.to_bits() {
            return Err(format!(
                "{LABEL} generator consumes physical TIME and does not admit output time scaling"
            ));
        }
        if Self::analytic_sinusoidal_rc_source_contract(&plan.source)? != *source {
            return Err(format!(
                "{LABEL} plan source changed after source-form qualification"
            ));
        }
        Ok(())
    }

    fn analytic_sinusoidal_rc_specification(
        netlist: &Netlist,
        plan: &XyceStaticTranPlan,
        source: &XyceAnalyticSinusoidalRcSourceContract,
    ) -> Result<XyceAnalyticSinusoidalRcSpecification, String> {
        const LABEL: &str = "analytic sinusoidal first-order RC";
        if netlist.title.trim().is_empty()
            || !netlist.models.is_empty()
            || !netlist.data_tables.is_empty()
            || !netlist.subcircuits.is_empty()
            || !netlist.initial_conditions.is_empty()
            || !netlist.node_sets.is_empty()
            || !netlist.global_nodes.is_empty()
            || !netlist.measurements.is_empty()
            || !netlist.veriloga_includes.is_empty()
            || !netlist.spef_includes.is_empty()
            || !netlist.diagnostics.is_empty()
        {
            return Err(format!(
                "{LABEL} contains model, hierarchy, auxiliary-analysis, external-model, or diagnostic state"
            ));
        }
        if !netlist.params.all_params().is_empty()
            || !netlist.params.all_string_params().is_empty()
            || !netlist.params.all_functions().is_empty()
        {
            return Err(format!("{LABEL} does not admit parameters or functions"));
        }
        if !matches!(netlist.analyses.as_slice(), [AnalysisCommand::Tran { .. }]) {
            return Err(format!("{LABEL} requires exactly one transient analysis"));
        }
        if !Self::analytic_sinusoidal_rc_options_match(&netlist.options, source) {
            return Err(format!(
                "{LABEL} parsed options differ from the qualified TIMEINT source contract"
            ));
        }
        if netlist.elements.len() != 3 {
            return Err(format!(
                "{LABEL} requires exactly three elements, found {}",
                netlist.elements.len()
            ));
        }

        let mut elements = BTreeMap::new();
        for element in &netlist.elements {
            if let Some(alias) = element.nodes.iter().find(|node| {
                crate::compat::ground::is_spice_ground_name(node)
                    && !Self::passive_primary_name_is_literal_ground(node)
            }) {
                return Err(format!(
                    "element '{}' uses ground alias '{}'; {LABEL} requires literal node 0",
                    element.name, alias
                ));
            }
            let name = Self::normalize_device_instance_name(&element.name);
            if elements.insert(name.clone(), element).is_some() {
                return Err(format!("{LABEL} contains duplicate element '{name}'"));
            }
        }
        let expected_names = [
            source.capacitor_name.clone(),
            source.resistor_name.clone(),
            source.source_name.clone(),
        ]
        .into_iter()
        .collect::<BTreeSet<_>>();
        if elements.keys().cloned().collect::<BTreeSet<_>>() != expected_names {
            return Err(format!(
                "{LABEL} parsed element inventory differs from source provenance"
            ));
        }

        let capacitor = elements
            .get(&source.capacitor_name)
            .expect("element inventory was checked");
        let capacitor_nodes = capacitor
            .nodes
            .iter()
            .map(|node| Self::canonical_passive_primary_node_name(node))
            .collect::<Vec<_>>();
        let ElementKind::Capacitor {
            value: capacitance,
            value_expr,
            initial_voltage,
            model,
            instance_params,
            deferred_params,
        } = &capacitor.kind
        else {
            return Err(format!(
                "source-qualified capacitor '{}' parsed as another element kind",
                capacitor.name
            ));
        };
        if capacitor_nodes.as_slice() != source.capacitor_nodes
            || !capacitance.is_finite()
            || capacitance.to_bits() != source.capacitance_bits
            || value_expr.is_some()
            || initial_voltage.is_some()
            || model.is_some()
            || !instance_params.is_empty()
            || !deferred_params.is_empty()
        {
            return Err(format!(
                "capacitor '{}' differs from the direct value/no-IC source contract",
                capacitor.name
            ));
        }
        let effective_capacitance = Self::effective_capacitor_value(netlist, &capacitor.name)
            .filter(|value| value.is_finite() && *value > 0.0)
            .ok_or_else(|| format!("{LABEL} capacitance did not resolve"))?;
        if effective_capacitance.to_bits() != source.capacitance_bits {
            return Err(format!(
                "{LABEL} explicit and effective capacitance values differ"
            ));
        }

        let resistor = elements
            .get(&source.resistor_name)
            .expect("element inventory was checked");
        let resistor_nodes = resistor
            .nodes
            .iter()
            .map(|node| Self::canonical_passive_primary_node_name(node))
            .collect::<Vec<_>>();
        let ElementKind::Resistor {
            value: resistance,
            value_expr,
            model,
            instance_params,
            deferred_params,
        } = &resistor.kind
        else {
            return Err(format!(
                "source-qualified resistor '{}' parsed as another element kind",
                resistor.name
            ));
        };
        if resistor_nodes.as_slice() != source.resistor_nodes
            || !resistance.is_finite()
            || resistance.to_bits() != source.resistance_bits
            || value_expr.is_some()
            || model.is_some()
            || !instance_params.is_empty()
            || !deferred_params.is_empty()
        {
            return Err(format!(
                "resistor '{}' differs from the direct source contract",
                resistor.name
            ));
        }
        let effective_resistance = Self::effective_resistor_value(netlist, &resistor.name)
            .filter(|value| value.is_finite() && *value > 0.0)
            .ok_or_else(|| format!("{LABEL} resistance did not resolve"))?;
        if effective_resistance.to_bits() != source.resistance_bits {
            return Err(format!(
                "{LABEL} explicit and effective resistance values differ"
            ));
        }

        let voltage_source = elements
            .get(&source.source_name)
            .expect("element inventory was checked");
        let source_nodes = voltage_source
            .nodes
            .iter()
            .map(|node| Self::canonical_passive_primary_node_name(node))
            .collect::<Vec<_>>();
        let ElementKind::VoltageSource(crate::netlist::SourceSpec::Sin {
            offset,
            amplitude,
            frequency,
            delay,
            damping,
            phase,
        }) = &voltage_source.kind
        else {
            return Err(format!(
                "source-qualified voltage source '{}' is not direct SIN",
                voltage_source.name
            ));
        };
        if source_nodes.as_slice() != source.source_nodes
            || offset.to_bits() != source.source_offset_bits
            || amplitude.to_bits() != source.source_amplitude_bits
            || frequency.to_bits() != source.source_frequency_bits
            || delay.to_bits() != source.source_delay_bits
            || damping.to_bits() != source.source_damping_bits
            || phase.to_bits() != 0.0f64.to_bits()
        {
            return Err(format!(
                "voltage source '{}' differs from direct SIN source provenance",
                voltage_source.name
            ));
        }

        let [capacitor_node, capacitor_ground] = &source.capacitor_nodes;
        let [source_node, source_ground] = &source.source_nodes;
        let [resistor_a, resistor_b] = &source.resistor_nodes;
        if capacitor_ground != "0"
            || source_ground != "0"
            || capacitor_node == "0"
            || source_node == "0"
            || capacitor_node == source_node
            || source.probe_node != *capacitor_node
            || !((resistor_a == capacitor_node && resistor_b == source_node)
                || (resistor_b == capacitor_node && resistor_a == source_node))
        {
            return Err(format!(
                "{LABEL} topology must be C(output,0), R(output,source), and SIN V(source,0)"
            ));
        }

        let expression = Self::print_expression_inner(&source.print_expression)
            .ok_or_else(|| format!("{LABEL} print expression lost its braces"))?;
        let prepared = prepare_behavioral_expression(expression, &netlist.params)
            .map_err(|err| format!("could not prepare {LABEL} print expression: {err}"))?;
        let ast = parse_expression_strict(&prepared)
            .map_err(|err| format!("could not parse prepared {LABEL} print expression: {err}"))?;
        let Expr::Binary {
            op: crate::expr::BinaryOp::Add,
            left,
            right,
        } = ast
        else {
            return Err(format!(
                "{LABEL} prepared expression must directly add voltage and offset"
            ));
        };
        let Expr::NodeVoltage(node) = left.as_ref() else {
            return Err(format!(
                "{LABEL} prepared expression left operand is not node voltage"
            ));
        };
        let Expr::Const(print_offset) = right.as_ref() else {
            return Err(format!(
                "{LABEL} prepared expression right operand is not a constant"
            ));
        };
        if Self::canonical_passive_primary_node_name(node) != source.probe_node
            || print_offset.to_bits() != source.print_offset_bits
        {
            return Err(format!(
                "{LABEL} prepared expression changed its voltage node or offset"
            ));
        }
        if plan.tran.step.to_bits() != source.tran_step_bits
            || plan.tran.stop.to_bits() != source.tran_stop_bits
        {
            return Err(format!("{LABEL} parsed and planned .TRAN tuples differ"));
        }

        Ok(XyceAnalyticSinusoidalRcSpecification {
            output_node: capacitor_node.clone(),
            print_expression: source.print_expression.clone(),
            resistance: effective_resistance,
            capacitance: effective_capacitance,
            source_frequency: *frequency,
            print_offset: *print_offset,
        })
    }

    fn direct_numeric_function_arguments(
        field: &str,
        function_name: &str,
        arity: usize,
    ) -> Result<Vec<Value>, String> {
        let field = field.trim();
        let Some(open) = field.find('(') else {
            return Err(format!("expected {function_name}(...) source form"));
        };
        if !field[..open].eq_ignore_ascii_case(function_name)
            || !field.ends_with(')')
            || field[open + 1..field.len() - 1]
                .chars()
                .any(|ch| matches!(ch, ',' | '=' | '{' | '}' | '\'' | '"' | '(' | ')'))
        {
            return Err(format!(
                "expected one direct whitespace-separated {function_name}(...) source field"
            ));
        }
        let arguments = Self::split_grouped_whitespace_fields(
            &field[open + 1..field.len() - 1],
            &format!("{function_name} argument list"),
        )?;
        if arguments.len() != arity {
            return Err(format!(
                "{function_name} requires exactly {arity} direct numeric arguments, found {}",
                arguments.len()
            ));
        }
        arguments
            .iter()
            .map(|argument| Self::single_spice_numeric_literal_value(argument))
            .collect()
    }

    fn passive_primary_source_contract(
        source: &str,
        element_name: &str,
        model_name: &str,
        kind: XycePassivePrimaryKind,
    ) -> Result<(XycePassivePrimaryRepresentation, u64, Vec<String>), String> {
        let mut representation = None;
        let mut value_bits = None;
        let mut fingerprint = Vec::new();
        let lines = Self::logical_netlist_lines(source);
        let Some(title) = lines.first() else {
            return Err("passive primary-value parity requires a circuit title".to_string());
        };
        fingerprint.push(Self::strip_netlist_comment(title).trim().to_string());
        for line in lines.iter().skip(1) {
            let stripped = Self::strip_netlist_comment(line).trim();
            let mut fields = Self::split_grouped_whitespace_fields(
                stripped,
                "passive primary-value source statement",
            )?;
            if fields
                .first()
                .is_some_and(|name| name.eq_ignore_ascii_case(element_name))
            {
                if representation.is_some() {
                    return Err(format!(
                        "passive primary-value parity requires exactly one active statement for '{element_name}'"
                    ));
                }
                if fields.len() != 5
                    || !Self::is_single_spice_identifier(&fields[3])
                    || !fields[3].eq_ignore_ascii_case(model_name)
                {
                    return Err(format!(
                        "primary device '{element_name}' must use exactly 'name n+ n- model primary-value'"
                    ));
                }
                let token = &fields[4];
                let (form, numeric) = if let Some((parameter, numeric)) = token.split_once('=') {
                    if numeric.contains('=')
                        || !parameter.eq_ignore_ascii_case(kind.primary_parameter())
                    {
                        return Err(format!(
                            "named primary token for '{element_name}' must be exactly {}=<numeric>",
                            kind.primary_parameter()
                        ));
                    }
                    (XycePassivePrimaryRepresentation::Named, numeric)
                } else {
                    (XycePassivePrimaryRepresentation::Positional, token.as_str())
                };
                let value = Self::single_spice_numeric_literal_value(numeric)?;
                representation = Some(form);
                value_bits = Some(value.to_bits());
                fields[4] = "<PRIMARY_VALUE>".to_string();
            }
            fingerprint.push(fields.join("\u{1f}"));
        }
        Ok((
            representation.ok_or_else(|| {
                format!("no active primary device statement found for '{element_name}'")
            })?,
            value_bits.expect("representation and value bits are set together"),
            fingerprint,
        ))
    }

    fn validate_passive_primary_source_forms(
        source: &str,
        kind: XycePassivePrimaryKind,
    ) -> Result<(), String> {
        let lines = Self::logical_netlist_lines(source);
        let Some(title) = lines.first() else {
            return Err("passive primary-value parity requires a circuit title".to_string());
        };
        let title = Self::strip_netlist_comment(title).trim();
        if title.is_empty() || title.starts_with('.') {
            return Err(
                "passive primary-value parity requires an ordinary circuit title".to_string(),
            );
        }

        let mut element_counts = BTreeMap::<char, usize>::new();
        let mut directive_counts = BTreeMap::<String, usize>::new();
        let mut pulse_count = 0usize;
        let mut direct_voltage_count = 0usize;
        for line in lines.iter().skip(1) {
            let stripped = Self::strip_netlist_comment(line).trim();
            let fields = Self::split_grouped_whitespace_fields(
                stripped,
                "passive primary-value source statement",
            )?;
            let Some(command) = fields.first() else {
                continue;
            };
            if command.starts_with('.') {
                let directive = command.to_ascii_lowercase();
                *directive_counts.entry(directive.clone()).or_default() += 1;
                match (kind, directive.as_str()) {
                    (XycePassivePrimaryKind::CapacitorTran, ".model") => {
                        if fields.len() != 4
                            || !Self::is_single_spice_identifier(&fields[1])
                            || !fields[2].eq_ignore_ascii_case("C")
                            || fields[3] != "()"
                        {
                            return Err("capacitor primary-value parity requires exactly '.MODEL name C ()'".to_string());
                        }
                    }
                    (XycePassivePrimaryKind::ResistorDc, ".model") => {
                        if fields.len() != 4
                            || !Self::is_single_spice_identifier(&fields[1])
                            || !fields[2].eq_ignore_ascii_case("R")
                        {
                            return Err("resistor primary-value parity requires exactly '.MODEL name R (RSH=<numeric>)'".to_string());
                        }
                        let parameter = fields[3]
                            .strip_prefix('(')
                            .and_then(|inner| inner.strip_suffix(')'))
                            .ok_or_else(|| "resistor model parameters must use one parenthesized RSH assignment".to_string())?;
                        let Some((name, value)) = parameter.split_once('=') else {
                            return Err("resistor model must contain one RSH=<numeric> assignment"
                                .to_string());
                        };
                        if value.contains('=')
                            || !name.eq_ignore_ascii_case("RSH")
                            || Self::single_spice_numeric_literal_value(value)? <= 0.0
                        {
                            return Err("resistor model must contain exactly one finite positive RSH=<numeric> assignment".to_string());
                        }
                    }
                    (XycePassivePrimaryKind::CapacitorTran, ".tran") => {
                        if fields.len() != 3 {
                            return Err(
                                "capacitor primary-value parity requires '.TRAN step stop'"
                                    .to_string(),
                            );
                        }
                        Self::single_spice_numeric_literal_value(&fields[1])?;
                        Self::single_spice_numeric_literal_value(&fields[2])?;
                    }
                    (XycePassivePrimaryKind::ResistorDc, ".dc") => {
                        if fields.len() != 5 || !Self::is_single_spice_identifier(&fields[1]) {
                            return Err("resistor primary-value parity requires '.DC source start stop step'".to_string());
                        }
                        for value in &fields[2..] {
                            Self::single_spice_numeric_literal_value(value)?;
                        }
                    }
                    (XycePassivePrimaryKind::CapacitorTran, ".print") => {
                        if fields.len() != 4 || !fields[1].eq_ignore_ascii_case("TRAN") {
                            return Err("capacitor primary-value parity requires one canonical two-probe '.PRINT TRAN' statement".to_string());
                        }
                    }
                    (XycePassivePrimaryKind::ResistorDc, ".print") => {
                        if fields.len() != 4 || !fields[1].eq_ignore_ascii_case("DC") {
                            return Err("resistor primary-value parity requires one canonical two-probe '.PRINT DC' statement".to_string());
                        }
                    }
                    (_, ".end") if fields.len() == 1 => {}
                    _ => {
                        return Err(format!(
                            "passive primary-value parity does not admit directive '{command}'"
                        ));
                    }
                }
                continue;
            }

            let designator = command
                .chars()
                .next()
                .map(|ch| ch.to_ascii_uppercase())
                .ok_or_else(|| {
                    "passive primary-value parity contains an empty element name".to_string()
                })?;
            *element_counts.entry(designator).or_default() += 1;
            match (kind, designator) {
                (XycePassivePrimaryKind::CapacitorTran, 'C')
                | (XycePassivePrimaryKind::ResistorDc, 'R') => {
                    if fields.len() != 5 {
                        return Err(format!(
                            "primary device '{command}' must contain exactly one model and one primary-value token"
                        ));
                    }
                }
                (XycePassivePrimaryKind::CapacitorTran, 'R') => {
                    if fields.len() != 4 {
                        return Err(
                            "capacitor parity resistor must use 'Rname n+ n- value'".to_string()
                        );
                    }
                    Self::single_spice_numeric_literal_value(&fields[3])?;
                }
                (_, 'V') => {
                    if fields.len() != 4 {
                        return Err("passive primary-value voltage sources require exactly one source field".to_string());
                    }
                    if kind == XycePassivePrimaryKind::CapacitorTran
                        && fields[3]
                            .get(..5)
                            .is_some_and(|prefix| prefix.eq_ignore_ascii_case("PULSE"))
                    {
                        Self::direct_numeric_function_arguments(&fields[3], "PULSE", 6)?;
                        pulse_count += 1;
                    } else {
                        Self::single_spice_numeric_literal_value(&fields[3])?;
                        direct_voltage_count += 1;
                    }
                }
                _ => {
                    return Err(format!(
                        "passive primary-value parity does not admit element '{command}'"
                    ));
                }
            }
        }

        let model_count = directive_counts.get(".model").copied().unwrap_or(0);
        let print_count = directive_counts.get(".print").copied().unwrap_or(0);
        let end_count = directive_counts.get(".end").copied().unwrap_or(0);
        match kind {
            XycePassivePrimaryKind::CapacitorTran
                if element_counts.get(&'C') == Some(&1)
                    && element_counts.get(&'R') == Some(&1)
                    && element_counts.get(&'V') == Some(&2)
                    && pulse_count == 1
                    && direct_voltage_count == 1
                    && model_count == 1
                    && directive_counts.get(".tran") == Some(&1)
                    && print_count == 1
                    && end_count == 1
                    && directive_counts.len() == 4 => {}
            XycePassivePrimaryKind::ResistorDc
                if element_counts.get(&'R') == Some(&1)
                    && element_counts.get(&'V') == Some(&2)
                    && direct_voltage_count == 2
                    && model_count == 1
                    && directive_counts.get(".dc") == Some(&1)
                    && print_count == 1
                    && end_count == 1
                    && directive_counts.len() == 4 => {}
            _ => {
                return Err(format!(
                    "passive primary-value {:?} source does not have the required bounded element and directive inventory",
                    kind
                ));
            }
        }
        Ok(())
    }

    fn validate_passive_cap_primary_transient_plan(
        plan: &XyceStaticTranPlan,
    ) -> Result<(), String> {
        if plan.contract != XyceStaticTranContract::PlainStatic
            || !plan.steps.is_empty()
            || plan.output_override
            || plan.timeint_conststep
        {
            return Err("capacitor primary-value parity requires one ordinary unstepped default .prn transient output".to_string());
        }
        if !plan.tran.step.is_finite()
            || !plan.tran.stop.is_finite()
            || plan.tran.step <= 0.0
            || plan.tran.stop <= 0.0
            || plan.tran.step > plan.tran.stop
            || plan.tran.start.is_some()
            || plan.tran.max_step.is_some()
            || plan.tran.uic
        {
            return Err("capacitor primary-value parity requires finite '.TRAN step stop' values and no START, MAXSTEP, or UIC".to_string());
        }
        if plan.print.probes.len() != 2 {
            return Err(
                "capacitor primary-value parity requires exactly two ordered probes".to_string(),
            );
        }
        Self::validate_passive_primary_source_forms(
            &plan.source,
            XycePassivePrimaryKind::CapacitorTran,
        )
    }

    fn validate_passive_res_primary_dc_plan(plan: &XyceStaticDcPlan) -> Result<(), String> {
        if !plan.steps.is_empty()
            || plan.dc_data.is_some()
            || plan.print_format.is_some()
            || plan.dc.sweep2.is_some()
            || !matches!(plan.dc.mode, crate::netlist::DcSweepMode::Linear)
        {
            return Err(
                "resistor primary-value parity requires one unstepped linear default .prn DC sweep"
                    .to_string(),
            );
        }
        let span = plan.dc.stop - plan.dc.start;
        if !plan.dc.start.is_finite()
            || !plan.dc.stop.is_finite()
            || !plan.dc.step.is_finite()
            || plan.dc.step == 0.0
            || span == 0.0
            || span.signum() != plan.dc.step.signum()
            || (span / plan.dc.step).abs() < 1.0
        {
            return Err("resistor primary-value parity requires a finite directed DC sweep with at least two points".to_string());
        }
        if plan.print.probes.len() != 2 || !plan.diagnostics.is_empty() {
            return Err("resistor primary-value parity requires exactly two ordered probes and a diagnostic-free parse".to_string());
        }
        Self::validate_passive_primary_source_forms(
            &plan.source,
            XycePassivePrimaryKind::ResistorDc,
        )
    }

    fn validate_subckt_parameter_precedence_dc_plan(plan: &XyceStaticDcPlan) -> Result<(), String> {
        if !plan.steps.is_empty()
            || plan.dc_data.is_some()
            || plan.print_format.is_some()
            || plan.dc.sweep2.is_some()
            || !matches!(plan.dc.mode, crate::netlist::DcSweepMode::Linear)
            || !plan.diagnostics.is_empty()
        {
            return Err(
                "subcircuit-parameter precedence requires one diagnostic-free, unstepped, linear default .prn DC analysis"
                    .to_string(),
            );
        }
        if plan.dc.primary_spec().points().len() != 1 {
            return Err(
                "subcircuit-parameter precedence requires exactly one DC sweep point".to_string(),
            );
        }
        if plan.print.probes.len() != 2
            || plan
                .print
                .probes
                .iter()
                .any(|probe| Self::parse_voltage_probe(probe).is_none())
        {
            return Err(
                "subcircuit-parameter precedence requires exactly two ordered voltage probes"
                    .to_string(),
            );
        }
        Ok(())
    }

    fn subckt_parameter_precedence_snapshot(
        netlist: &Netlist,
        print: &XycePrintRequest,
        sweep_source: &str,
    ) -> Result<XyceSubcktParameterPrecedenceSnapshot, String> {
        if print.probes.len() != 2
            || !netlist.models.is_empty()
            || !netlist.diagnostics.is_empty()
            || !netlist.data_tables.is_empty()
            || !netlist.initial_conditions.is_empty()
            || !netlist.node_sets.is_empty()
        {
            return Err(
                "subcircuit-parameter precedence snapshot requires two probes and no model, diagnostic, data, IC, or NODESET state"
                    .to_string(),
            );
        }
        let flattened = crate::netlist::flatten_netlist_with_models(netlist)
            .map_err(|error| format!("could not flatten sibling-reference deck: {error}"))?;
        if flattened.elements.len() != 3 {
            return Err(format!(
                "subcircuit-parameter precedence snapshot requires a three-element divider, found {} flattened elements",
                flattened.elements.len()
            ));
        }
        let voltage_sources = flattened
            .elements
            .iter()
            .filter(|element| matches!(element.kind, ElementKind::VoltageSource(_)))
            .collect::<Vec<_>>();
        let resistor_count = flattened
            .elements
            .iter()
            .filter(|element| matches!(element.kind, ElementKind::Resistor { .. }))
            .count();
        if voltage_sources.len() != 1
            || resistor_count != 2
            || !voltage_sources[0].name.eq_ignore_ascii_case(sweep_source)
        {
            return Err(
                "subcircuit-parameter precedence snapshot requires two resistors and the swept independent voltage source"
                    .to_string(),
            );
        }

        let mut elements = flattened
            .elements
            .iter()
            .map(|element| {
                let mut fingerprint =
                    Self::scoped_model_element_fingerprint(element, &netlist.params)?;
                for node in &mut fingerprint.nodes {
                    *node = node.replace(':', ".");
                }
                Ok(fingerprint)
            })
            .collect::<Result<Vec<_>, String>>()?;
        elements.sort();
        Ok(XyceSubcktParameterPrecedenceSnapshot { elements })
    }

    fn validate_subckt_parameter_resolution_dc_plan(plan: &XyceStaticDcPlan) -> Result<(), String> {
        const LABEL: &str = "subcircuit-parameter resolution";
        if !matches!(plan.expression_dialect, ExpressionDialect::Xyce)
            || plan.execution_dir.is_some()
            || plan.dc_data.is_some()
            || !plan.steps.is_empty()
            || !plan.diagnostics.is_empty()
            || plan.print_format.is_some()
            || plan.dc.sweep2.is_some()
            || !matches!(plan.dc.mode, crate::netlist::DcSweepMode::Linear)
        {
            return Err(format!(
                "{LABEL} requires one diagnostic-free, unstepped, one-dimensional linear .DC analysis with default indexed PRN output"
            ));
        }
        let span = plan.dc.stop - plan.dc.start;
        let estimated_intervals = span / plan.dc.step;
        if !plan.dc.start.is_finite()
            || !plan.dc.stop.is_finite()
            || !plan.dc.step.is_finite()
            || plan.dc.step == 0.0
            || !span.is_finite()
            || span == 0.0
            || span.signum() != plan.dc.step.signum()
            || !estimated_intervals.is_finite()
            || !(1.0..=1_000_000.0).contains(&estimated_intervals.abs())
        {
            return Err(format!(
                "{LABEL} requires finite directed sweep bounds with at most 1,000,001 points"
            ));
        }
        let points = plan.dc.primary_spec().points();
        if points.len() < 2 || points.iter().any(|point| !point.is_finite()) {
            return Err(format!(
                "{LABEL} requires a finite DC grid with at least two points"
            ));
        }
        let [voltage_text, current_text] = plan.print.probes.as_slice() else {
            return Err(format!(
                "{LABEL} requires exactly one ordered voltage probe and one ordered branch-current probe"
            ));
        };
        let voltage = Self::parse_voltage_probe(voltage_text)
            .ok_or_else(|| format!("{LABEL} first output must be an ordinary voltage probe"))?;
        if voltage.accessor != XyceVoltageAccessor::Value
            || voltage.node_pos.trim().is_empty()
            || voltage.node_neg.is_some()
            || Self::parse_current_probe(current_text).is_none()
        {
            return Err(format!(
                "{LABEL} requires '.PRINT DC V(node) I(source)' in that order"
            ));
        }
        Self::validate_subckt_parameter_resolution_source_directives(&plan.source)
    }

    fn validate_subckt_parameter_resolution_source_directives(source: &str) -> Result<(), String> {
        const LABEL: &str = "subcircuit-parameter resolution";
        if source.trim().is_empty()
            || Self::source_has_comp_directive(source)
            || source
                .lines()
                .find(|line| !line.trim().is_empty())
                .is_none_or(|line| !line.trim_start().starts_with('*'))
        {
            return Err(format!(
                "{LABEL} requires a nonempty comment-titled source without *COMP"
            ));
        }
        let mut directive_counts = BTreeMap::<String, usize>::new();
        let mut element_counts = BTreeMap::<char, usize>::new();
        for line in Self::logical_netlist_lines(source) {
            let stripped = Self::strip_netlist_comment(&line).trim();
            let command = stripped.split_whitespace().next().unwrap_or_default();
            if command.starts_with('.') {
                let normalized = command.to_ascii_lowercase();
                if !matches!(
                    normalized.as_str(),
                    ".param" | ".dc" | ".print" | ".subckt" | ".ends" | ".end"
                ) {
                    return Err(format!("{LABEL} does not admit directive '{command}'"));
                }
                *directive_counts.entry(normalized).or_default() += 1;
                continue;
            }
            let designator = command
                .chars()
                .next()
                .map(|value| value.to_ascii_uppercase())
                .ok_or_else(|| format!("{LABEL} contains an empty statement"))?;
            if !matches!(designator, 'X' | 'V' | 'R') {
                return Err(format!(
                    "{LABEL} admits only one subcircuit instance, one independent voltage source, and one resistor body; got '{command}'"
                ));
            }
            *element_counts.entry(designator).or_default() += 1;
        }
        for directive in [".dc", ".print", ".subckt", ".ends", ".end"] {
            if directive_counts.get(directive).copied() != Some(1) {
                return Err(format!(
                    "{LABEL} requires exactly one {directive} statement"
                ));
            }
        }
        if directive_counts.get(".param").copied().unwrap_or(0) > 1
            || element_counts.get(&'X').copied() != Some(1)
            || element_counts.get(&'V').copied() != Some(1)
            || element_counts.get(&'R').copied() != Some(1)
            || element_counts.len() != 3
        {
            return Err(format!(
                "{LABEL} requires at most one global .PARAM and exactly one X/V/R statement"
            ));
        }
        Ok(())
    }

    fn bare_subckt_parameter_expression_name(expression: &str) -> Option<String> {
        let trimmed = expression.trim();
        let inner = trimmed
            .strip_prefix('{')
            .and_then(|value| value.strip_suffix('}'))
            .unwrap_or(trimmed)
            .trim();
        match crate::netlist::expr::parse_expression(inner).ok()? {
            crate::netlist::expr::Expr::Param(name) if Self::is_single_spice_identifier(&name) => {
                Some(name.to_ascii_lowercase())
            }
            _ => None,
        }
    }

    fn subckt_parameter_resolution_qualification(
        netlist: &Netlist,
        print: &XycePrintRequest,
        sweep_source: &str,
    ) -> Result<
        (
            XyceSubcktParameterResolutionRepresentation,
            String,
            Option<XyceSubcktParameterResolutionSnapshot>,
        ),
        String,
    > {
        const LABEL: &str = "subcircuit-parameter resolution";
        let source = netlist
            .source_text
            .as_deref()
            .ok_or_else(|| format!("{LABEL} requires original source text"))?;
        Self::validate_subckt_parameter_resolution_source_directives(source)?;
        if !netlist.models.is_empty()
            || !netlist.diagnostics.is_empty()
            || !matches!(netlist.analyses.as_slice(), [AnalysisCommand::Dc { .. }])
            || !netlist.fft_analyses.is_empty()
            || !netlist.data_tables.is_empty()
            || netlist.subcircuits.len() != 1
            || !netlist.initial_conditions.is_empty()
            || !netlist.node_sets.is_empty()
            || !netlist.global_nodes.is_empty()
            || !netlist.measurements.is_empty()
            || !netlist.veriloga_includes.is_empty()
            || !netlist.spef_includes.is_empty()
            || !netlist.params.all_string_params().is_empty()
            || !netlist.params.all_functions().is_empty()
        {
            return Err(format!(
                "{LABEL} requires one flat top-level DC harness, one subcircuit definition, and no auxiliary or external model state"
            ));
        }

        let globals = netlist.params.numeric_parameters();
        if globals.len() > 1 || globals.iter().any(|(_, value)| !value.is_finite()) {
            return Err(format!(
                "{LABEL} admits at most one finite global scalar parameter"
            ));
        }
        let global = globals
            .first()
            .map(|(name, value)| (name.to_ascii_lowercase(), *value));

        let [subcircuit] = netlist.subcircuits.as_slice() else {
            return Err(format!("{LABEL} requires exactly one subcircuit"));
        };
        if subcircuit.ports.len() != 2
            || subcircuit.elements.len() != 1
            || subcircuit.params.len() > 1
            || subcircuit
                .params
                .iter()
                .any(|(_, value)| !value.is_finite())
            || !subcircuit.expr_params.is_empty()
            || !subcircuit.string_params.is_empty()
            || !subcircuit.body_params.is_empty()
            || !subcircuit.body_expr_params.is_empty()
            || !subcircuit.body_string_params.is_empty()
            || !subcircuit.body_functions.is_empty()
            || !subcircuit.local_options.is_empty()
            || !subcircuit.initial_conditions.is_empty()
            || !subcircuit.node_sets.is_empty()
            || !subcircuit.nested_subcircuits.is_empty()
        {
            return Err(format!(
                "{LABEL} requires one two-port, one-resistor subcircuit with at most one finite formal parameter and no nested state"
            ));
        }
        let formal = subcircuit
            .params
            .first()
            .map(|(name, value)| (name.to_ascii_lowercase(), *value));

        let mut top_instance = None;
        let mut voltage_source = None;
        for element in &netlist.elements {
            if element.nodes.len() != 2
                || element.nodes.iter().any(|node| node.trim().is_empty())
                || element.nodes.iter().any(|node| {
                    crate::compat::ground::is_spice_ground_name(node) && node.trim() != "0"
                })
            {
                return Err(format!(
                    "{LABEL} top-level element '{}' must use two explicit nodes and literal ground",
                    element.name
                ));
            }
            match &element.kind {
                ElementKind::Subcircuit {
                    subckt_name,
                    params,
                } if top_instance.is_none()
                    && subckt_name.eq_ignore_ascii_case(&subcircuit.name)
                    && params.len() <= 1 =>
                {
                    top_instance = Some((element, params));
                }
                ElementKind::VoltageSource(crate::netlist::SourceSpec::Dc(value))
                    if voltage_source.is_none() && value.is_finite() =>
                {
                    voltage_source = Some(element);
                }
                _ => {
                    return Err(format!(
                        "{LABEL} contains unqualified top-level element '{}'",
                        element.name
                    ));
                }
            }
        }
        let (instance_element, instance_params) = top_instance
            .ok_or_else(|| format!("{LABEL} contains no qualified subcircuit instance"))?;
        let voltage_source = voltage_source
            .ok_or_else(|| format!("{LABEL} contains no qualified independent DC source"))?;
        if netlist.elements.len() != 2
            || instance_element.nodes != voltage_source.nodes
            || instance_element.nodes[1].trim() != "0"
            || !voltage_source.name.eq_ignore_ascii_case(sweep_source)
        {
            return Err(format!(
                "{LABEL} requires the swept source directly across the two-port instance"
            ));
        }
        let instance = match instance_params.as_slice() {
            [] => None,
            [(name, ParametricValue::Resolved(value))] if value.is_finite() => {
                Some((name.to_ascii_lowercase(), *value))
            }
            _ => {
                return Err(format!(
                    "{LABEL} instance parameter must be absent or one direct finite scalar"
                ));
            }
        };

        let [resistor] = subcircuit.elements.as_slice() else {
            return Err(format!("{LABEL} subcircuit must contain one resistor"));
        };
        if resistor.nodes != subcircuit.ports
            || resistor.nodes.iter().any(|node| node.trim().is_empty())
        {
            return Err(format!(
                "{LABEL} resistor must connect the two formal ports in order"
            ));
        }
        let (expression_name, literal_value) = match &resistor.kind {
            ElementKind::Resistor {
                value,
                value_expr,
                model,
                instance_params,
                deferred_params,
            } if model.is_none() && instance_params.is_empty() && deferred_params.is_empty() => {
                match value_expr {
                    Some(expression) => (
                        Some(
                            Self::bare_subckt_parameter_expression_name(expression).ok_or_else(
                                || {
                                    format!(
                                        "{LABEL} parameterized resistor must use one bare scalar reference"
                                    )
                                },
                            )?,
                        ),
                        None,
                    ),
                    None if value.is_finite() && *value > 0.0 => (None, Some(*value)),
                    _ => {
                        return Err(format!(
                            "{LABEL} resistor value must be one bare parameter reference or one positive finite literal"
                        ));
                    }
                }
            }
            _ => {
                return Err(format!(
                    "{LABEL} subcircuit body contains an unqualified resistor"
                ));
            }
        };

        let mut binding_names = Vec::new();
        binding_names.extend(global.as_ref().map(|(name, _)| name.as_str()));
        binding_names.extend(formal.as_ref().map(|(name, _)| name.as_str()));
        binding_names.extend(instance.as_ref().map(|(name, _)| name.as_str()));
        binding_names.extend(expression_name.as_deref());
        let parameter_name = binding_names
            .first()
            .ok_or_else(|| format!("{LABEL} contains no parameter binding or reference"))?
            .to_string();
        if binding_names
            .iter()
            .any(|name| !name.eq_ignore_ascii_case(&parameter_name))
        {
            return Err(format!(
                "{LABEL} formal, global, instance, and resistor names must identify one scalar parameter"
            ));
        }

        let representation = match (
            global.as_ref(),
            formal.as_ref(),
            instance.as_ref(),
            expression_name.as_ref(),
            literal_value,
        ) {
            (None, Some((_, default)), Some((_, override_value)), Some(_), None)
                if default.to_bits() != override_value.to_bits() =>
            {
                XyceSubcktParameterResolutionRepresentation::FormalDefaultAndInstanceOverride
            }
            (None, None, Some(_), Some(_), None) => {
                XyceSubcktParameterResolutionRepresentation::ImplicitInstanceBinding
            }
            (Some(_), None, None, Some(_), None) => {
                XyceSubcktParameterResolutionRepresentation::GlobalBinding
            }
            (Some((_, global_value)), None, Some((_, instance_value)), Some(_), None)
                if global_value.to_bits() != instance_value.to_bits() =>
            {
                XyceSubcktParameterResolutionRepresentation::InstanceOverridesGlobal
            }
            (Some((_, global_value)), None, Some((_, instance_value)), None, Some(literal))
                if global_value.to_bits() != instance_value.to_bits()
                    && literal.to_bits() == instance_value.to_bits() =>
            {
                XyceSubcktParameterResolutionRepresentation::UnusedInstanceBinding
            }
            (None, None, None, Some(_), None) => {
                XyceSubcktParameterResolutionRepresentation::UndefinedBinding
            }
            _ => {
                return Err(format!(
                    "{LABEL} source does not exercise one recognized parameter-resolution precedence mode"
                ));
            }
        };

        let [voltage_probe_text, current_probe_text] = print.probes.as_slice() else {
            return Err(format!("{LABEL} requires exactly two ordered probes"));
        };
        let voltage_probe = Self::parse_voltage_probe(voltage_probe_text)
            .ok_or_else(|| format!("{LABEL} first output is not a voltage probe"))?;
        let current_probe = Self::parse_current_probe(current_probe_text)
            .ok_or_else(|| format!("{LABEL} second output is not a branch-current probe"))?;
        if voltage_probe.accessor != XyceVoltageAccessor::Value
            || voltage_probe.node_neg.is_some()
            || !voltage_probe
                .node_pos
                .eq_ignore_ascii_case(&instance_element.nodes[0])
            || !current_probe.eq_ignore_ascii_case(&voltage_source.name)
        {
            return Err(format!(
                "{LABEL} outputs must observe the driven two-port node and swept-source current"
            ));
        }

        let flattened = crate::netlist::flatten_netlist_with_models(netlist);
        if representation == XyceSubcktParameterResolutionRepresentation::UndefinedBinding {
            match flattened {
                Err(ParseError::UndefinedParameter(name))
                    if name.eq_ignore_ascii_case(&parameter_name) => {}
                Err(other) => {
                    return Err(format!(
                        "{LABEL} undefined binding must fail with typed undefined parameter '{parameter_name}', got {other}"
                    ));
                }
                Ok(_) => {
                    return Err(format!(
                        "{LABEL} undefined binding unexpectedly flattened without an error"
                    ));
                }
            }
            return Ok((representation, parameter_name, None));
        }

        let flattened = flattened.map_err(|error| {
            format!("{LABEL} valid representation failed during flattening: {error}")
        })?;
        if !flattened.scoped_models.is_empty()
            || !flattened.scoped_initial_conditions.is_empty()
            || !flattened.scoped_node_sets.is_empty()
            || !flattened.xspice_auto_bridge_node_hints.is_empty()
            || flattened.elements.len() != 2
        {
            return Err(format!(
                "{LABEL} valid representation must flatten to exactly one resistor and one source without scoped auxiliary state"
            ));
        }
        let mut resistor_count = 0usize;
        let mut source_count = 0usize;
        let mut fingerprints = Vec::new();
        for element in &flattened.elements {
            if element.nodes.len() != 2
                || element.nodes.iter().any(|node| node.trim().is_empty())
                || element.nodes.iter().any(|node| {
                    crate::compat::ground::is_spice_ground_name(node) && node.trim() != "0"
                })
            {
                return Err(format!(
                    "{LABEL} flattened element '{}' has unqualified nodes",
                    element.name
                ));
            }
            match &element.kind {
                ElementKind::Resistor {
                    value,
                    value_expr,
                    model,
                    instance_params,
                    deferred_params,
                } if value.is_finite()
                    && *value > 0.0
                    && value_expr.is_none()
                    && model.is_none()
                    && instance_params.is_empty()
                    && deferred_params.is_empty() =>
                {
                    resistor_count += 1;
                }
                ElementKind::VoltageSource(crate::netlist::SourceSpec::Dc(value))
                    if value.is_finite() =>
                {
                    source_count += 1;
                }
                _ => {
                    return Err(format!(
                        "{LABEL} flattened element '{}' is not a direct native resistor/source",
                        element.name
                    ));
                }
            }
            let fingerprint = Self::scoped_model_element_fingerprint(element, &netlist.params)?;
            fingerprints.push(fingerprint);
        }
        if resistor_count != 1 || source_count != 1 {
            return Err(format!(
                "{LABEL} must flatten to one resistor and one independent source"
            ));
        }
        fingerprints.sort();
        Ok((
            representation,
            parameter_name.clone(),
            Some(XyceSubcktParameterResolutionSnapshot {
                representation,
                parameter_name,
                flattened_elements: fingerprints,
            }),
        ))
    }

    fn subckt_parameter_resolution_snapshot(
        netlist: &Netlist,
        print: &XycePrintRequest,
        sweep_source: &str,
    ) -> Result<XyceSubcktParameterResolutionSnapshot, String> {
        let (representation, _, snapshot) =
            Self::subckt_parameter_resolution_qualification(netlist, print, sweep_source)?;
        if representation == XyceSubcktParameterResolutionRepresentation::UndefinedBinding {
            return Err(
                "undefined-binding member cannot serve as a numeric family member".to_string(),
            );
        }
        snapshot.ok_or_else(|| {
            "numeric subcircuit-parameter member produced no semantic snapshot".to_string()
        })
    }

    fn passive_primary_name_is_literal_ground(node: &str) -> bool {
        node.trim() == "0"
    }

    fn canonical_passive_primary_node_name(node: &str) -> String {
        if Self::passive_primary_name_is_literal_ground(node) {
            "0".to_string()
        } else {
            node.trim().to_ascii_lowercase()
        }
    }

    fn validate_passive_primary_common_netlist(
        netlist: &Netlist,
        kind: XycePassivePrimaryKind,
    ) -> Result<(), String> {
        if netlist.title.trim().is_empty() {
            return Err("passive primary-value parity requires a nonempty title".to_string());
        }
        if !netlist.data_tables.is_empty()
            || !netlist.subcircuits.is_empty()
            || !netlist.initial_conditions.is_empty()
            || !netlist.node_sets.is_empty()
            || !netlist.global_nodes.is_empty()
            || !netlist.measurements.is_empty()
            || !netlist.veriloga_includes.is_empty()
            || !netlist.spef_includes.is_empty()
            || !netlist.diagnostics.is_empty()
        {
            return Err("passive primary-value parity contains auxiliary analysis, hierarchy, external-model, or diagnostic state".to_string());
        }
        if !netlist.params.all_params().is_empty()
            || !netlist.params.all_string_params().is_empty()
            || !netlist.params.all_functions().is_empty()
        {
            return Err(
                "passive primary-value parity does not admit parameters or user functions"
                    .to_string(),
            );
        }
        if netlist.models.len() != 1 {
            return Err(format!(
                "passive primary-value parity requires exactly one model, found {}",
                netlist.models.len()
            ));
        }
        let analysis_matches = matches!(
            (kind, netlist.analyses.as_slice()),
            (
                XycePassivePrimaryKind::CapacitorTran,
                [AnalysisCommand::Tran { .. }]
            ) | (
                XycePassivePrimaryKind::ResistorDc,
                [AnalysisCommand::Dc { .. }]
            )
        );
        if !analysis_matches {
            return Err(format!(
                "passive primary-value {:?} parity requires exactly one matching analysis command",
                kind
            ));
        }
        for element in &netlist.elements {
            if let Some(alias) = element.nodes.iter().find(|node| {
                crate::compat::ground::is_spice_ground_name(node)
                    && !Self::passive_primary_name_is_literal_ground(node)
            }) {
                return Err(format!(
                    "element '{}' uses ground alias '{}'; passive primary-value parity requires literal node 0",
                    element.name, alias
                ));
            }
        }
        Ok(())
    }

    fn passive_model_has_no_deferred_state(model: &crate::netlist::ModelDef) -> bool {
        model.expr_params.is_empty()
            && model.string_params.is_empty()
            && model.string_vector_params.is_empty()
            && model.real_vector_params.is_empty()
            && model.real_vector_expr_params.is_empty()
            && model.integer_vector_params.is_empty()
    }

    fn passive_cap_primary_snapshot(
        netlist: &Netlist,
        print: &XycePrintRequest,
    ) -> Result<XycePassivePrimaryValueSnapshot, String> {
        let kind = XycePassivePrimaryKind::CapacitorTran;
        Self::validate_passive_primary_common_netlist(netlist, kind)?;
        let model = &netlist.models[0];
        if !model.model_type.eq_ignore_ascii_case("C")
            || !model.params.is_empty()
            || !Self::passive_model_has_no_deferred_state(model)
        {
            return Err(format!(
                "capacitor primary-value model '{}' must be a parameter-free C model",
                model.name
            ));
        }

        let mut capacitor = None;
        let mut resistor = None;
        let mut pulse = None;
        let mut monitor = None;
        let mut elements = BTreeMap::new();
        for element in &netlist.elements {
            let key = Self::normalize_device_instance_name(&element.name);
            let nodes = element
                .nodes
                .iter()
                .map(|node| Self::canonical_passive_primary_node_name(node))
                .collect::<Vec<_>>();
            let fingerprint = match &element.kind {
                ElementKind::Capacitor {
                    value,
                    value_expr,
                    initial_voltage,
                    model: element_model,
                    instance_params,
                    deferred_params,
                } => {
                    if capacitor.is_some()
                        || element.nodes.len() != 2
                        || !value.is_finite()
                        || *value <= 0.0
                        || value_expr.is_some()
                        || initial_voltage.is_some()
                        || !instance_params.is_empty()
                        || !deferred_params.is_empty()
                    {
                        return Err(format!(
                            "capacitor '{}' is outside the explicit finite modeled primary-value envelope",
                            element.name
                        ));
                    }
                    let element_model = element_model.as_ref().ok_or_else(|| {
                        format!(
                            "capacitor '{}' must reference the unique model",
                            element.name
                        )
                    })?;
                    if !element_model.eq_ignore_ascii_case(&model.name) {
                        return Err(format!(
                            "capacitor '{}' does not reference model '{}'",
                            element.name, model.name
                        ));
                    }
                    capacitor = Some((
                        element.name.clone(),
                        nodes.clone(),
                        element_model.clone(),
                        *value,
                    ));
                    XyceRelationalElementFingerprint {
                        kind: "C:MODEL".to_string(),
                        nodes,
                        numeric_bits: vec![value.to_bits()],
                        text: vec![element_model.to_ascii_lowercase()],
                    }
                }
                ElementKind::Resistor {
                    value,
                    value_expr,
                    model,
                    instance_params,
                    deferred_params,
                } => {
                    if resistor.is_some()
                        || element.nodes.len() != 2
                        || !value.is_finite()
                        || *value <= 0.0
                        || value_expr.is_some()
                        || model.is_some()
                        || !instance_params.is_empty()
                        || !deferred_params.is_empty()
                    {
                        return Err(format!(
                            "resistor '{}' is outside the direct finite two-terminal envelope",
                            element.name
                        ));
                    }
                    resistor = Some((element.name.clone(), nodes.clone(), *value));
                    XyceRelationalElementFingerprint {
                        kind: "R".to_string(),
                        nodes,
                        numeric_bits: vec![value.to_bits()],
                        text: Vec::new(),
                    }
                }
                ElementKind::VoltageSource(crate::netlist::SourceSpec::Pulse {
                    v1,
                    v2,
                    delay,
                    rise,
                    fall,
                    width,
                    period,
                    phase,
                    width_defaults_to_zero,
                }) => {
                    if pulse.is_some()
                        || element.nodes.len() != 2
                        || !v1.is_finite()
                        || !v2.is_finite()
                        || v1 == v2
                        || !delay.is_finite()
                        || *delay < 0.0
                        || !rise.is_finite()
                        || *rise <= 0.0
                        || !fall.is_finite()
                        || *fall <= 0.0
                        || !width.is_finite()
                        || *width <= 0.0
                        || !period.is_nan()
                        || phase.to_bits() != 0.0f64.to_bits()
                        || *width_defaults_to_zero
                    {
                        return Err(format!(
                            "pulse source '{}' is outside the direct six-argument nontrivial waveform envelope",
                            element.name
                        ));
                    }
                    let numeric_bits = vec![
                        v1.to_bits(),
                        v2.to_bits(),
                        delay.to_bits(),
                        rise.to_bits(),
                        fall.to_bits(),
                        width.to_bits(),
                        period.to_bits(),
                        phase.to_bits(),
                        u64::from(*width_defaults_to_zero),
                    ];
                    pulse = Some((element.name.clone(), nodes.clone()));
                    XyceRelationalElementFingerprint {
                        kind: "V:PULSE6".to_string(),
                        nodes,
                        numeric_bits,
                        text: Vec::new(),
                    }
                }
                ElementKind::VoltageSource(crate::netlist::SourceSpec::Dc(value)) => {
                    if monitor.is_some()
                        || element.nodes.len() != 2
                        || value.to_bits() != 0.0f64.to_bits()
                    {
                        return Err(format!(
                            "monitor source '{}' must be the unique direct positive-zero DC source",
                            element.name
                        ));
                    }
                    monitor = Some((element.name.clone(), nodes.clone()));
                    XyceRelationalElementFingerprint {
                        kind: "V:DC".to_string(),
                        nodes,
                        numeric_bits: vec![value.to_bits()],
                        text: Vec::new(),
                    }
                }
                _ => {
                    return Err(format!(
                        "element '{}' is outside the qualified capacitor primary-value topology",
                        element.name
                    ));
                }
            };
            if elements.insert(key.clone(), fingerprint).is_some() {
                return Err(format!(
                    "capacitor primary-value parity contains duplicate element name '{key}'"
                ));
            }
        }
        if elements.len() != 4 {
            return Err(format!(
                "capacitor primary-value parity requires exactly four elements, found {}",
                elements.len()
            ));
        }
        let (capacitor_name, capacitor_nodes, capacitor_model, capacitor_value) =
            capacitor.ok_or_else(|| "no qualified modeled capacitor found".to_string())?;
        let (_, resistor_nodes, _) =
            resistor.ok_or_else(|| "no qualified ordinary resistor found".to_string())?;
        let (_, pulse_nodes) =
            pulse.ok_or_else(|| "no qualified six-argument pulse source found".to_string())?;
        let (monitor_name, monitor_nodes) =
            monitor.ok_or_else(|| "no qualified zero-volt monitor found".to_string())?;
        let [drive, ground] = pulse_nodes.as_slice() else {
            return Err("pulse source must have two terminals".to_string());
        };
        let [resistor_drive, monitor_input] = resistor_nodes.as_slice() else {
            return Err("ordinary resistor must have two terminals".to_string());
        };
        let [monitor_input_again, capacitor_node] = monitor_nodes.as_slice() else {
            return Err("monitor source must have two terminals".to_string());
        };
        let [capacitor_node_again, capacitor_ground] = capacitor_nodes.as_slice() else {
            return Err("capacitor must have two terminals".to_string());
        };
        if ground != "0"
            || capacitor_ground != "0"
            || drive == "0"
            || monitor_input == "0"
            || capacitor_node == "0"
            || drive == monitor_input
            || drive == capacitor_node
            || monitor_input == capacitor_node
            || resistor_drive != drive
            || monitor_input_again != monitor_input
            || capacitor_node_again != capacitor_node
        {
            return Err("capacitor primary-value topology must be Pulse -> R -> +0 V monitor -> modeled C with three distinct non-ground nodes".to_string());
        }
        let [voltage_text, current_text] = print.probes.as_slice() else {
            return Err(
                "capacitor primary-value parity requires exactly two ordered probes".to_string(),
            );
        };
        let voltage = Self::parse_voltage_probe(voltage_text)
            .ok_or_else(|| format!("'{voltage_text}' is not an atomic voltage probe"))?;
        let current = Self::parse_current_probe(current_text)
            .ok_or_else(|| format!("'{current_text}' is not an atomic current probe"))?;
        if voltage.accessor != XyceVoltageAccessor::Value
            || voltage.node_neg.is_some()
            || Self::canonical_passive_primary_node_name(&voltage.node_pos) != *capacitor_node
            || !Self::device_instance_names_match(&current, &monitor_name)
        {
            return Err("capacitor primary-value probes must be ordered V(capacitor-node), I(monitor-source)".to_string());
        }

        let source = netlist.source_text.as_deref().ok_or_else(|| {
            "capacitor primary-value parity requires original source text".to_string()
        })?;
        let (representation, literal_bits, active_source_fingerprint) =
            Self::passive_primary_source_contract(source, &capacitor_name, &capacitor_model, kind)?;
        if literal_bits != capacitor_value.to_bits() {
            return Err("capacitor source literal and parsed primary value differ".to_string());
        }
        let effective = Self::effective_capacitor_value(netlist, &capacitor_name)
            .filter(|value| value.is_finite() && *value > 0.0)
            .ok_or_else(|| "capacitor effective primary value did not resolve".to_string())?;
        if effective.to_bits() != capacitor_value.to_bits() {
            return Err("capacitor parsed and effective primary values differ".to_string());
        }
        Ok(XycePassivePrimaryValueSnapshot {
            title: netlist.title.trim().to_string(),
            device_kind: kind,
            representation,
            active_source_fingerprint,
            model_name: model.name.to_ascii_lowercase(),
            model_type: model.model_type.to_ascii_lowercase(),
            model_numeric_bits: Vec::new(),
            elements,
            effective_primary_bits: effective.to_bits(),
        })
    }

    fn passive_res_primary_snapshot(
        netlist: &Netlist,
        print: &XycePrintRequest,
        sweep_source: &str,
    ) -> Result<XycePassivePrimaryValueSnapshot, String> {
        let kind = XycePassivePrimaryKind::ResistorDc;
        Self::validate_passive_primary_common_netlist(netlist, kind)?;
        let model = &netlist.models[0];
        if !model.model_type.eq_ignore_ascii_case("R")
            || model.params.len() != 1
            || !model.params[0].0.eq_ignore_ascii_case("RSH")
            || !model.params[0].1.is_finite()
            || model.params[0].1 <= 0.0
            || !Self::passive_model_has_no_deferred_state(model)
        {
            return Err(format!(
                "resistor primary-value model '{}' must be an R model with exactly one finite positive RSH",
                model.name
            ));
        }

        let mut resistor = None;
        let mut swept_source = None;
        let mut monitor = None;
        let mut elements = BTreeMap::new();
        for element in &netlist.elements {
            let key = Self::normalize_device_instance_name(&element.name);
            let nodes = element
                .nodes
                .iter()
                .map(|node| Self::canonical_passive_primary_node_name(node))
                .collect::<Vec<_>>();
            let fingerprint = match &element.kind {
                ElementKind::Resistor {
                    value,
                    value_expr,
                    model: element_model,
                    instance_params,
                    deferred_params,
                } => {
                    if resistor.is_some()
                        || element.nodes.len() != 2
                        || !value.is_finite()
                        || *value <= 0.0
                        || value_expr.is_some()
                        || !deferred_params.is_empty()
                    {
                        return Err(format!(
                            "resistor '{}' is outside the explicit finite modeled primary-value envelope",
                            element.name
                        ));
                    }
                    let element_model = element_model.as_ref().ok_or_else(|| {
                        format!(
                            "resistor '{}' must reference the unique model",
                            element.name
                        )
                    })?;
                    if !element_model.eq_ignore_ascii_case(&model.name) {
                        return Err(format!(
                            "resistor '{}' does not reference model '{}'",
                            element.name, model.name
                        ));
                    }
                    resistor = Some((
                        element.name.clone(),
                        nodes.clone(),
                        element_model.clone(),
                        *value,
                        instance_params.clone(),
                    ));
                    XyceRelationalElementFingerprint {
                        kind: "R:MODEL".to_string(),
                        nodes,
                        numeric_bits: vec![value.to_bits()],
                        text: vec![element_model.to_ascii_lowercase()],
                    }
                }
                ElementKind::VoltageSource(crate::netlist::SourceSpec::Dc(value)) => {
                    if element.nodes.len() != 2 || !value.is_finite() {
                        return Err(format!(
                            "voltage source '{}' must be a finite direct DC source",
                            element.name
                        ));
                    }
                    if Self::device_instance_names_match(&element.name, sweep_source) {
                        if swept_source.is_some() || *value == 0.0 {
                            return Err("resistor primary-value sweep requires one nonzero source"
                                .to_string());
                        }
                        swept_source = Some((element.name.clone(), nodes.clone(), *value));
                    } else {
                        if monitor.is_some() || value.to_bits() != 0.0f64.to_bits() {
                            return Err("resistor primary-value monitor must be the unique positive-zero source".to_string());
                        }
                        monitor = Some((element.name.clone(), nodes.clone()));
                    }
                    XyceRelationalElementFingerprint {
                        kind: "V:DC".to_string(),
                        nodes,
                        numeric_bits: vec![value.to_bits()],
                        text: Vec::new(),
                    }
                }
                _ => {
                    return Err(format!(
                        "element '{}' is outside the qualified resistor primary-value topology",
                        element.name
                    ));
                }
            };
            if elements.insert(key.clone(), fingerprint).is_some() {
                return Err(format!(
                    "resistor primary-value parity contains duplicate element name '{key}'"
                ));
            }
        }
        if elements.len() != 3 {
            return Err(format!(
                "resistor primary-value parity requires exactly three elements, found {}",
                elements.len()
            ));
        }
        let (resistor_name, resistor_nodes, resistor_model, resistor_value, instance_params) =
            resistor.ok_or_else(|| "no qualified modeled resistor found".to_string())?;
        let (_, sweep_nodes, _) =
            swept_source.ok_or_else(|| "qualified swept voltage source not found".to_string())?;
        let (monitor_name, monitor_nodes) =
            monitor.ok_or_else(|| "qualified zero-volt monitor not found".to_string())?;
        let [drive, ground] = sweep_nodes.as_slice() else {
            return Err("swept source must have two terminals".to_string());
        };
        let [monitor_drive, resistor_node] = monitor_nodes.as_slice() else {
            return Err("monitor source must have two terminals".to_string());
        };
        let [resistor_node_again, resistor_ground] = resistor_nodes.as_slice() else {
            return Err("resistor must have two terminals".to_string());
        };
        if ground != "0"
            || resistor_ground != "0"
            || drive == "0"
            || resistor_node == "0"
            || drive == resistor_node
            || monitor_drive != drive
            || resistor_node_again != resistor_node
        {
            return Err("resistor primary-value topology must be swept source -> +0 V monitor -> modeled R with two distinct non-ground nodes".to_string());
        }
        let [voltage_text, current_text] = print.probes.as_slice() else {
            return Err(
                "resistor primary-value parity requires exactly two ordered probes".to_string(),
            );
        };
        let voltage = Self::parse_voltage_probe(voltage_text)
            .ok_or_else(|| format!("'{voltage_text}' is not an atomic voltage probe"))?;
        let current = Self::parse_current_probe(current_text)
            .ok_or_else(|| format!("'{current_text}' is not an atomic current probe"))?;
        if voltage.accessor != XyceVoltageAccessor::Value
            || voltage.node_neg.is_some()
            || Self::canonical_passive_primary_node_name(&voltage.node_pos) != *drive
            || !Self::device_instance_names_match(&current, &monitor_name)
        {
            return Err(
                "resistor primary-value probes must be ordered V(drive), I(monitor-source)"
                    .to_string(),
            );
        }

        let source = netlist.source_text.as_deref().ok_or_else(|| {
            "resistor primary-value parity requires original source text".to_string()
        })?;
        let (representation, literal_bits, active_source_fingerprint) =
            Self::passive_primary_source_contract(source, &resistor_name, &resistor_model, kind)?;
        let instance_form_matches = match representation {
            XycePassivePrimaryRepresentation::Named => {
                matches!(
                    instance_params.as_slice(),
                    [(name, value)]
                        if name.eq_ignore_ascii_case("R")
                            && value.to_bits() == resistor_value.to_bits()
                )
            }
            XycePassivePrimaryRepresentation::Positional => instance_params.is_empty(),
        };
        if !instance_form_matches || literal_bits != resistor_value.to_bits() {
            return Err("resistor source representation, parsed primary value, or normalized R instance parameter differs".to_string());
        }
        let effective = Self::effective_resistor_value(netlist, &resistor_name)
            .filter(|value| value.is_finite() && *value > 0.0)
            .ok_or_else(|| "resistor effective primary value did not resolve".to_string())?;
        if effective.to_bits() != resistor_value.to_bits() {
            return Err("resistor parsed and effective primary values differ".to_string());
        }
        Ok(XycePassivePrimaryValueSnapshot {
            title: netlist.title.trim().to_string(),
            device_kind: kind,
            representation,
            active_source_fingerprint,
            model_name: model.name.to_ascii_lowercase(),
            model_type: model.model_type.to_ascii_lowercase(),
            model_numeric_bits: vec![(
                model.params[0].0.to_ascii_lowercase(),
                model.params[0].1.to_bits(),
            )],
            elements,
            effective_primary_bits: effective.to_bits(),
        })
    }

    fn compare_passive_primary_snapshots(
        baseline: &XycePassivePrimaryValueSnapshot,
        target: &XycePassivePrimaryValueSnapshot,
    ) -> Result<(), String> {
        if baseline.representation != XycePassivePrimaryRepresentation::Named
            || target.representation != XycePassivePrimaryRepresentation::Positional
        {
            return Err("passive primary-value parity requires named baseline -> positional target representation order".to_string());
        }
        if baseline.device_kind != target.device_kind {
            return Err("passive primary-value device kinds differ".to_string());
        }
        if baseline.title != target.title {
            return Err("circuit titles differ".to_string());
        }
        if baseline.active_source_fingerprint != target.active_source_fingerprint {
            return Err(
                "active source differs outside the admitted primary-value token".to_string(),
            );
        }
        if baseline.model_name != target.model_name
            || baseline.model_type != target.model_type
            || baseline.model_numeric_bits != target.model_numeric_bits
        {
            return Err("passive model identity, type, or numeric state differs".to_string());
        }
        if baseline.elements != target.elements {
            return Err(
                "element topology, waveform, or non-representation values differ".to_string(),
            );
        }
        if baseline.effective_primary_bits != target.effective_primary_bits {
            return Err("effective passive primary values differ".to_string());
        }
        Ok(())
    }

    fn strict_transient_family_snapshot(
        contract: &XyceBaselineFamilyContract,
        netlist: &Netlist,
        print: &XycePrintRequest,
    ) -> Result<XyceStrictTransientFamilySnapshot, String> {
        match contract.kind {
            XyceBaselineFamilyKind::ScopedModel => {
                Self::scoped_model_family_snapshot(contract, netlist)?
                    .map(XyceStrictTransientFamilySnapshot::ScopedModel)
                    .ok_or_else(|| {
                        "scoped-model strict family produced no semantic snapshot".to_string()
                    })
            }
            XyceBaselineFamilyKind::SinExpression => {
                Self::sin_expression_family_snapshot(netlist, print)
                    .map(XyceStrictTransientFamilySnapshot::SinExpression)
            }
            XyceBaselineFamilyKind::ParamExpression => {
                Self::param_expression_family_snapshot(netlist, print)
                    .map(XyceStrictTransientFamilySnapshot::ParamExpression)
            }
            XyceBaselineFamilyKind::PassiveCapPrimaryValue => {
                Self::passive_cap_primary_snapshot(netlist, print)
                    .map(XyceStrictTransientFamilySnapshot::PassivePrimaryValue)
            }
            XyceBaselineFamilyKind::PassiveTemperatureOverride => {
                Self::passive_temperature_override_snapshot(netlist, print)
                    .map(XyceStrictTransientFamilySnapshot::PassiveTemperatureOverride)
            }
            XyceBaselineFamilyKind::TransientAnalysisExpression => {
                Self::transient_analysis_expression_snapshot(netlist, print)
                    .map(XyceStrictTransientFamilySnapshot::TransientAnalysisExpression)
            }
            other => Err(format!(
                "strict transient family kind {} has no semantic snapshot contract",
                other.name()
            )),
        }
    }

    fn validate_passive_temperature_override_transient_plan(
        plan: &XyceStaticTranPlan,
    ) -> Result<(), String> {
        const LABEL: &str = "passive temperature-coefficient override parity";
        if plan.contract != XyceStaticTranContract::PlainStatic {
            return Err(format!(
                "{LABEL} requires ordinary primary .prn output, got {:?}",
                plan.contract
            ));
        }
        if !plan.steps.is_empty() || plan.output_override || plan.timeint_conststep {
            return Err(format!(
                "{LABEL} does not admit .STEP, output overrides, or constant-step output"
            ));
        }
        if plan.wrapper_tolerance.is_some() || Self::source_has_comp_directive(&plan.source) {
            return Err(format!(
                "{LABEL} uses the canonical default xyce_verify tolerance and does not admit wrapper or *COMP overrides"
            ));
        }
        if !plan.tran.step.is_finite()
            || !plan.tran.stop.is_finite()
            || plan.tran.step < 0.0
            || plan.tran.stop <= 0.0
            || plan.tran.step > plan.tran.stop
            || plan.tran.uic
        {
            return Err(format!(
                "{LABEL} requires a finite ordinary transient tuple with 0 <= step <= stop, positive stop, and no UIC"
            ));
        }
        if plan.print.probes.is_empty() {
            return Err(format!(
                "{LABEL} requires at least one ordered .PRINT TRAN probe"
            ));
        }

        let mut model_count = 0usize;
        let mut tran_count = 0usize;
        let mut print_count = 0usize;
        let mut end_count = 0usize;
        for line in Self::logical_netlist_lines(&plan.source) {
            let stripped = Self::strip_netlist_comment(&line);
            let Some(command) = stripped.split_whitespace().next() else {
                continue;
            };
            if !command.starts_with('.') {
                continue;
            }
            match command.to_ascii_lowercase().as_str() {
                ".model" => model_count += 1,
                ".tran" => tran_count += 1,
                ".print" => print_count += 1,
                ".options" => {}
                ".end" => end_count += 1,
                other => {
                    return Err(format!("{LABEL} does not admit directive '{other}'"));
                }
            }
        }
        if (model_count, tran_count, print_count, end_count) != (1, 1, 1, 1) {
            return Err(format!(
                "{LABEL} requires exactly one .MODEL, .TRAN, .PRINT, and .END; found ({model_count}, {tran_count}, {print_count}, {end_count})"
            ));
        }
        Ok(())
    }

    fn passive_temperature_override_snapshot(
        netlist: &Netlist,
        print: &XycePrintRequest,
    ) -> Result<XycePassiveTemperatureOverrideSnapshot, String> {
        const LABEL: &str = "passive temperature-coefficient override parity";
        let source = netlist
            .source_text
            .as_deref()
            .ok_or_else(|| format!("{LABEL} requires original source text"))?;
        if print.probes.is_empty()
            || !netlist.diagnostics.is_empty()
            || !matches!(netlist.analyses.as_slice(), [AnalysisCommand::Tran { .. }])
            || !netlist.fft_analyses.is_empty()
            || !netlist.data_tables.is_empty()
            || !netlist.subcircuits.is_empty()
            || !netlist.initial_conditions.is_empty()
            || !netlist.node_sets.is_empty()
            || !netlist.global_nodes.is_empty()
            || !netlist.measurements.is_empty()
            || !netlist.veriloga_includes.is_empty()
            || !netlist.spef_includes.is_empty()
            || !netlist.params.all_params().is_empty()
            || !netlist.params.all_string_params().is_empty()
            || !netlist.params.all_functions().is_empty()
        {
            return Err(format!(
                "{LABEL} requires one diagnostic-free transient analysis without hierarchy, parameters, auxiliary analysis state, or external models"
            ));
        }
        let [model] = netlist.models.as_slice() else {
            return Err(format!(
                "{LABEL} requires exactly one passive model, found {}",
                netlist.models.len()
            ));
        };
        if !model.expr_params.is_empty()
            || !model.string_params.is_empty()
            || !model.string_vector_params.is_empty()
            || !model.real_vector_params.is_empty()
            || !model.real_vector_expr_params.is_empty()
            || !model.integer_vector_params.is_empty()
        {
            return Err(format!(
                "{LABEL} model '{}' must use only direct scalar numeric parameters",
                model.name
            ));
        }
        let model_tc = Self::passive_temperature_coefficient_pair(&model.params, "model")?;

        let mut passive = None;
        let mut elements = BTreeMap::new();
        for element in &netlist.elements {
            let name = Self::normalize_device_instance_name(&element.name);
            if name.is_empty() || elements.contains_key(&name) {
                return Err(format!(
                    "{LABEL} contains an empty or duplicate element name '{}'",
                    element.name
                ));
            }
            let nodes = element
                .nodes
                .iter()
                .map(|node| node.trim().to_ascii_lowercase())
                .collect::<Vec<_>>();
            if nodes.iter().any(String::is_empty) {
                return Err(format!(
                    "{LABEL} element '{name}' contains an empty node name"
                ));
            }
            let fingerprint = match &element.kind {
                ElementKind::Capacitor {
                    value,
                    value_expr,
                    initial_voltage,
                    model: element_model,
                    instance_params,
                    deferred_params,
                } => {
                    let details = XycePassiveTemperatureDeviceKind::Capacitor;
                    if passive.is_some()
                        || nodes.len() != 2
                        || !value.is_finite()
                        || *value <= 0.0
                        || value_expr.is_some()
                        || initial_voltage.is_some_and(|value| !value.is_finite())
                        || !deferred_params.is_empty()
                        || !matches!(
                            model.model_type.to_ascii_uppercase().as_str(),
                            "C" | "CAP" | "CAPACITOR"
                        )
                    {
                        return Err(format!(
                            "{LABEL} requires one direct finite positive two-terminal capacitor with no deferred state"
                        ));
                    }
                    let effective = Self::effective_capacitor_value(netlist, &element.name)
                        .ok_or_else(|| {
                            format!("{LABEL} could not resolve capacitor '{}'", element.name)
                        })?;
                    let (representation, winning_tc, temperature) =
                        Self::passive_temperature_instance_state(instance_params, model_tc)?;
                    Self::validate_passive_temperature_model_binding(
                        element_model.as_deref(),
                        model,
                    )?;
                    if !effective.is_finite() || effective <= 0.0 {
                        return Err(format!(
                            "{LABEL} capacitor '{}' resolved to invalid capacitance {effective}",
                            element.name
                        ));
                    }
                    let mut numeric_bits = vec![value.to_bits(), temperature.to_bits()];
                    let initial_marker = if let Some(initial) = initial_voltage {
                        numeric_bits.push(initial.to_bits());
                        "IC"
                    } else {
                        "NO_IC"
                    };
                    numeric_bits.extend(winning_tc.map(Value::to_bits));
                    numeric_bits.push(effective.to_bits());
                    passive = Some((details, representation, winning_tc, effective));
                    XyceRelationalElementFingerprint {
                        kind: "C:TEMP_OVERRIDE".to_string(),
                        nodes,
                        numeric_bits,
                        text: vec![model.name.to_ascii_lowercase(), initial_marker.to_string()],
                    }
                }
                ElementKind::Inductor {
                    value,
                    value_expr,
                    initial_current,
                    model: element_model,
                    instance_params,
                    deferred_params,
                } => {
                    let details = XycePassiveTemperatureDeviceKind::Inductor;
                    if passive.is_some()
                        || nodes.len() != 2
                        || !value.is_finite()
                        || *value <= 0.0
                        || value_expr.is_some()
                        || initial_current.is_some_and(|value| !value.is_finite())
                        || !deferred_params.is_empty()
                        || !matches!(
                            model.model_type.to_ascii_uppercase().as_str(),
                            "L" | "IND" | "INDUCTOR"
                        )
                    {
                        return Err(format!(
                            "{LABEL} requires one direct finite positive two-terminal inductor with no deferred state"
                        ));
                    }
                    let effective = Self::effective_inductor_value(netlist, &element.name)
                        .ok_or_else(|| {
                            format!("{LABEL} could not resolve inductor '{}'", element.name)
                        })?;
                    let (representation, winning_tc, temperature) =
                        Self::passive_temperature_instance_state(instance_params, model_tc)?;
                    Self::validate_passive_temperature_model_binding(
                        element_model.as_deref(),
                        model,
                    )?;
                    if !effective.is_finite() || effective <= 0.0 {
                        return Err(format!(
                            "{LABEL} inductor '{}' resolved to invalid inductance {effective}",
                            element.name
                        ));
                    }
                    let mut numeric_bits = vec![value.to_bits(), temperature.to_bits()];
                    let initial_marker = if let Some(initial) = initial_current {
                        numeric_bits.push(initial.to_bits());
                        "IC"
                    } else {
                        "NO_IC"
                    };
                    numeric_bits.extend(winning_tc.map(Value::to_bits));
                    numeric_bits.push(effective.to_bits());
                    passive = Some((details, representation, winning_tc, effective));
                    XyceRelationalElementFingerprint {
                        kind: "L:TEMP_OVERRIDE".to_string(),
                        nodes,
                        numeric_bits,
                        text: vec![model.name.to_ascii_lowercase(), initial_marker.to_string()],
                    }
                }
                _ => Self::passive_temperature_nonpassive_fingerprint(element, nodes)?,
            };
            elements.insert(name, fingerprint);
        }
        let Some((device_kind, representation, winning_tc, effective_primary)) = passive else {
            return Err(format!("{LABEL} contains no qualified passive device"));
        };
        if representation == XycePassiveTemperatureRepresentation::InstanceCoefficients
            && model_tc == winning_tc
        {
            return Err(format!(
                "{LABEL} instance representation must shadow a different model TC1/TC2 pair"
            ));
        }

        let option_directives = Self::logical_netlist_lines(source)
            .into_iter()
            .map(|line| Self::strip_netlist_comment(&line).trim().to_string())
            .filter(|line| {
                line.split_whitespace()
                    .next()
                    .is_some_and(|command| command.eq_ignore_ascii_case(".options"))
            })
            .map(|line| {
                line.split_whitespace()
                    .map(str::to_ascii_lowercase)
                    .collect::<Vec<_>>()
                    .join(" ")
            })
            .collect();

        Ok(XycePassiveTemperatureOverrideSnapshot {
            title: netlist.title.trim().to_string(),
            device_kind,
            representation,
            elements,
            model_name: model.name.trim().to_ascii_lowercase(),
            model_type: model.model_type.trim().to_ascii_lowercase(),
            winning_tc_bits: winning_tc.map(Value::to_bits),
            effective_primary_bits: effective_primary.to_bits(),
            option_directives,
        })
    }

    fn passive_temperature_coefficient_pair(
        params: &[(String, Value)],
        owner: &str,
    ) -> Result<[Value; 2], String> {
        if params.len() != 2 {
            return Err(format!(
                "passive temperature-coefficient override {owner} requires exactly TC1 and TC2"
            ));
        }
        let tc1 = Self::instance_param(params, &["TC1"]);
        let tc2 = Self::instance_param(params, &["TC2"]);
        if tc1.is_none()
            || tc2.is_none()
            || params
                .iter()
                .filter(|(name, _)| name.eq_ignore_ascii_case("TC1"))
                .count()
                != 1
            || params
                .iter()
                .filter(|(name, _)| name.eq_ignore_ascii_case("TC2"))
                .count()
                != 1
        {
            return Err(format!(
                "passive temperature-coefficient override {owner} requires unique scalar TC1 and TC2"
            ));
        }
        let pair = [tc1.unwrap(), tc2.unwrap()];
        if pair.iter().any(|value| !value.is_finite()) {
            return Err(format!(
                "passive temperature-coefficient override {owner} TC1/TC2 must be finite"
            ));
        }
        Ok(pair)
    }

    fn passive_temperature_instance_state(
        params: &[(String, Value)],
        model_tc: [Value; 2],
    ) -> Result<(XycePassiveTemperatureRepresentation, [Value; 2], Value), String> {
        let temperature_values = params
            .iter()
            .filter(|(name, _)| name.eq_ignore_ascii_case("TEMP"))
            .map(|(_, value)| *value)
            .collect::<Vec<_>>();
        let [temperature] = temperature_values.as_slice() else {
            return Err(
                "passive temperature-coefficient override requires exactly one instance TEMP"
                    .to_string(),
            );
        };
        if !temperature.is_finite() {
            return Err(
                "passive temperature-coefficient override requires finite instance TEMP"
                    .to_string(),
            );
        }
        let tc_params = params
            .iter()
            .filter(|(name, _)| {
                name.eq_ignore_ascii_case("TC1") || name.eq_ignore_ascii_case("TC2")
            })
            .cloned()
            .collect::<Vec<_>>();
        if params.len() == 1 && tc_params.is_empty() {
            return Ok((
                XycePassiveTemperatureRepresentation::ModelCoefficients,
                model_tc,
                *temperature,
            ));
        }
        if params.len() == 3 && tc_params.len() == 2 {
            let instance_tc = Self::passive_temperature_coefficient_pair(&tc_params, "instance")?;
            return Ok((
                XycePassiveTemperatureRepresentation::InstanceCoefficients,
                instance_tc,
                *temperature,
            ));
        }
        Err(
            "passive temperature-coefficient override instance admits only TEMP or TEMP plus scalar TC1 and TC2"
                .to_string(),
        )
    }

    fn validate_passive_temperature_model_binding(
        element_model: Option<&str>,
        model: &crate::netlist::ModelDef,
    ) -> Result<(), String> {
        if element_model.is_none_or(|name| !name.eq_ignore_ascii_case(&model.name)) {
            return Err(format!(
                "passive temperature-coefficient override device must bind the unique model '{}'",
                model.name
            ));
        }
        Ok(())
    }

    fn passive_temperature_nonpassive_fingerprint(
        element: &crate::netlist::Element,
        nodes: Vec<String>,
    ) -> Result<XyceRelationalElementFingerprint, String> {
        let (kind, numeric_bits, text) = match &element.kind {
            ElementKind::Resistor {
                value,
                value_expr,
                model,
                instance_params,
                deferred_params,
            } if nodes.len() == 2
                && value.is_finite()
                && *value > 0.0
                && value_expr.is_none()
                && model.is_none()
                && instance_params.is_empty()
                && deferred_params.is_empty() =>
            {
                ("R".to_string(), vec![value.to_bits()], Vec::new())
            }
            ElementKind::VoltageSource(spec) | ElementKind::CurrentSource(spec)
                if nodes.len() == 2 =>
            {
                let (waveform, values) = Self::scoped_model_source_fingerprint(spec)?;
                let prefix = if matches!(&element.kind, ElementKind::VoltageSource(_)) {
                    "V"
                } else {
                    "I"
                };
                (format!("{prefix}:{waveform}"), values, Vec::new())
            }
            ElementKind::BehavioralVoltage {
                expression,
                tc1,
                tc2,
            }
            | ElementKind::BehavioralCurrent {
                expression,
                tc1,
                tc2,
            } if nodes.len() == 2
                && tc1.to_bits() == 0.0f64.to_bits()
                && tc2.to_bits() == 0.0f64.to_bits() =>
            {
                let prepared = crate::netlist::expr::prepare_behavioral_expression(
                    expression,
                    &crate::netlist::expr::ParamContext::new(),
                )
                .map_err(|err| {
                    format!(
                        "could not canonicalize passive temperature family source '{}': {err}",
                        element.name
                    )
                })?;
                let kind = if matches!(&element.kind, ElementKind::BehavioralVoltage { .. }) {
                    "BV"
                } else {
                    "BI"
                };
                (
                    kind.to_string(),
                    vec![tc1.to_bits(), tc2.to_bits()],
                    vec![prepared.trim().to_ascii_lowercase()],
                )
            }
            _ => {
                return Err(format!(
                    "passive temperature-coefficient override family contains unqualified non-passive element '{}'",
                    element.name
                ));
            }
        };
        Ok(XyceRelationalElementFingerprint {
            kind,
            nodes,
            numeric_bits,
            text,
        })
    }

    fn compare_passive_temperature_override_snapshots(
        baseline: &XycePassiveTemperatureOverrideSnapshot,
        target: &XycePassiveTemperatureOverrideSnapshot,
    ) -> Result<(), String> {
        if baseline.representation != XycePassiveTemperatureRepresentation::ModelCoefficients
            || target.representation != XycePassiveTemperatureRepresentation::InstanceCoefficients
        {
            return Err(
                "family must compare model TC1/TC2 with scalar instance TC1/TC2 precedence"
                    .to_string(),
            );
        }
        if baseline.title != target.title
            || baseline.device_kind != target.device_kind
            || baseline.elements != target.elements
            || baseline.model_name != target.model_name
            || baseline.model_type != target.model_type
            || baseline.option_directives != target.option_directives
        {
            return Err(
                "circuit identity, topology, non-overridden values, model binding, or options differ"
                    .to_string(),
            );
        }
        if baseline.winning_tc_bits != target.winning_tc_bits {
            return Err("winning scalar TC1/TC2 coefficients differ".to_string());
        }
        if baseline.effective_primary_bits != target.effective_primary_bits {
            return Err("effective temperature-scaled passive values differ".to_string());
        }
        Ok(())
    }

    fn ac_analysis_value_fields(statement: &str) -> Result<Vec<String>, String> {
        const LABEL: &str = "AC-analysis expression parity";
        let fields = Self::split_grouped_whitespace_fields(statement, ".AC statement")?;
        if fields.len() != 5
            || fields
                .first()
                .is_none_or(|field| !field.eq_ignore_ascii_case(".AC"))
            || fields.get(1).is_none_or(|field| {
                !matches!(field.to_ascii_uppercase().as_str(), "DEC" | "OCT" | "LIN")
            })
        {
            return Err(format!(
                "{LABEL} requires '.AC DEC|OCT|LIN points start stop'"
            ));
        }
        Ok(fields[2..].to_vec())
    }

    fn ac_analysis_output_option_is_footer_suppression(statement: &str) -> Result<bool, String> {
        let fields = Self::split_grouped_whitespace_fields(statement, ".OPTIONS OUTPUT statement")?;
        if fields.len() != 3
            || !fields[0].eq_ignore_ascii_case(".OPTIONS")
            || !fields[1].eq_ignore_ascii_case("OUTPUT")
        {
            return Ok(false);
        }
        let Some((name, value)) = fields[2].split_once('=') else {
            return Ok(false);
        };
        Ok(name.eq_ignore_ascii_case("PRINTFOOTER")
            && matches!(
                value.to_ascii_lowercase().as_str(),
                "false" | "0" | "no" | "off"
            ))
    }

    fn ac_analysis_source_qualification(
        source: &str,
    ) -> Result<(XyceAcAnalysisRepresentation, BTreeMap<String, u64>), String> {
        const LABEL: &str = "AC-analysis expression parity";
        if Self::source_has_comp_directive(source) {
            return Err(format!("{LABEL} does not admit *COMP directives"));
        }
        let lines = Self::logical_netlist_lines(source);
        if lines.is_empty() {
            return Err(format!("{LABEL} requires a nonempty source"));
        }
        let mut parameter_bits = BTreeMap::new();
        let mut ac_fields = None;
        let mut print_count = 0usize;
        let mut option_count = 0usize;
        let mut end_count = 0usize;
        let mut element_count = 0usize;
        for line in lines.iter().skip(1) {
            let stripped = Self::strip_netlist_comment(line).trim();
            let Some(command) = stripped.split_whitespace().next() else {
                continue;
            };
            if command.starts_with('.') {
                match command.to_ascii_lowercase().as_str() {
                    ".param" => {
                        let fields = Self::split_grouped_whitespace_fields(
                            stripped,
                            "AC-analysis .PARAM statement",
                        )?;
                        let [_, assignment] = fields.as_slice() else {
                            return Err(format!(
                                "{LABEL} requires one direct '.PARAM name=value' assignment per statement"
                            ));
                        };
                        let Some((name, value)) = assignment.split_once('=') else {
                            return Err(format!(
                                "{LABEL} requires canonical '.PARAM name=value' syntax"
                            ));
                        };
                        let name = name.trim().to_ascii_lowercase();
                        if name.is_empty()
                            || value.trim().is_empty()
                            || value.contains('=')
                            || !name.chars().enumerate().all(|(index, ch)| {
                                ch.is_ascii_alphanumeric()
                                    || ch == '_'
                                    || (index > 0 && matches!(ch, '.' | '$'))
                            })
                            || name.chars().next().is_some_and(|ch| ch.is_ascii_digit())
                        {
                            return Err(format!(
                                "{LABEL} contains invalid parameter assignment '{assignment}'"
                            ));
                        }
                        let value = Self::single_spice_numeric_literal_value(value)?;
                        if !value.is_finite()
                            || parameter_bits
                                .insert(name.clone(), value.to_bits())
                                .is_some()
                        {
                            return Err(format!(
                                "{LABEL} parameter '{name}' must be unique and finite"
                            ));
                        }
                    }
                    ".ac" => {
                        if ac_fields.is_some() {
                            return Err(format!("{LABEL} requires exactly one .AC"));
                        }
                        ac_fields = Some(Self::ac_analysis_value_fields(stripped)?);
                    }
                    ".print" => {
                        let fields = Self::split_grouped_whitespace_fields(
                            stripped,
                            "AC-analysis .PRINT statement",
                        )?;
                        if fields.len() < 3
                            || !fields[0].eq_ignore_ascii_case(".PRINT")
                            || !fields[1].eq_ignore_ascii_case("AC")
                        {
                            return Err(format!(
                                "{LABEL} requires one nonempty '.PRINT AC probe ...' statement"
                            ));
                        }
                        if fields.iter().skip(2).any(|field| {
                            field.contains('=') || field.eq_ignore_ascii_case("NOINDEX")
                        }) {
                            return Err(format!(
                                "{LABEL} requires default indexed AC PRN formatting without .PRINT options"
                            ));
                        }
                        print_count += 1;
                    }
                    ".options" => {
                        option_count += 1;
                        if !Self::ac_analysis_output_option_is_footer_suppression(stripped)? {
                            return Err(format!(
                                "{LABEL} admits only the data-neutral '.OPTIONS OUTPUT PRINTFOOTER=false' setting"
                            ));
                        }
                    }
                    ".end" => {
                        end_count += 1;
                        if !stripped.eq_ignore_ascii_case(".end") {
                            return Err(format!("{LABEL} requires a bare .END statement"));
                        }
                    }
                    other => return Err(format!("{LABEL} does not admit directive '{other}'")),
                }
                continue;
            }

            element_count += 1;
            if stripped.contains('{') || stripped.contains('}') {
                return Err(format!(
                    "{LABEL} element statements must not consume analysis parameters"
                ));
            }
            let fields =
                Self::split_grouped_whitespace_fields(stripped, "AC-analysis element statement")?;
            let designator = fields
                .first()
                .and_then(|field| field.chars().next())
                .map(|ch| ch.to_ascii_uppercase())
                .ok_or_else(|| format!("{LABEL} contains an empty element statement"))?;
            match designator {
                'R' | 'C'
                    if fields.len() == 4 && Self::is_single_spice_numeric_literal(&fields[3]) => {}
                'V' | 'I' if fields.len() >= 4 => {}
                _ => {
                    return Err(format!(
                        "{LABEL} admits only direct R/C passives and independent V/I sources; got '{command}'"
                    ));
                }
            }
        }
        if print_count != 1 || option_count > 1 || end_count != 1 || element_count == 0 {
            return Err(format!(
                "{LABEL} requires one .PRINT, at most one footer-only .OPTIONS, one .END, and at least one element; found ({print_count}, {option_count}, {end_count}, {element_count})"
            ));
        }
        let ac_fields = ac_fields.ok_or_else(|| format!("{LABEL} contains no .AC"))?;
        if parameter_bits.is_empty() {
            if ac_fields
                .iter()
                .all(|field| Self::is_single_spice_numeric_literal(field))
            {
                return Ok((XyceAcAnalysisRepresentation::DirectNumeric, parameter_bits));
            }
            return Err(format!(
                "{LABEL} numeric baseline requires only direct finite .AC literals"
            ));
        }

        for line in lines.iter().skip(1) {
            let stripped = Self::strip_netlist_comment(line).trim();
            let command = stripped.split_whitespace().next().unwrap_or_default();
            if command.eq_ignore_ascii_case(".param") || command.eq_ignore_ascii_case(".ac") {
                continue;
            }
            let identifiers = stripped
                .split(|ch: char| !(ch.is_ascii_alphanumeric() || matches!(ch, '_' | '.' | '$')))
                .filter(|field| {
                    field
                        .chars()
                        .next()
                        .is_some_and(|ch| ch.is_ascii_alphabetic() || ch == '_')
                });
            if identifiers.into_iter().any(|identifier| {
                parameter_bits
                    .keys()
                    .any(|name| identifier.eq_ignore_ascii_case(name))
            }) {
                return Err(format!(
                    "{LABEL} analysis parameters may be referenced only by .AC fields"
                ));
            }
        }
        if ac_fields.len() != parameter_bits.len() {
            return Err(format!(
                "{LABEL} requires one unique scalar parameter per .AC value field"
            ));
        }
        let mut field_parameters = BTreeSet::new();
        for field in &ac_fields {
            let Some(expression) = field
                .strip_prefix('{')
                .and_then(|value| value.strip_suffix('}'))
            else {
                return Err(format!(
                    "{LABEL} parameterized .AC fields must each be one braced expression"
                ));
            };
            let expression = crate::netlist::expr::parse_expression(expression)
                .map_err(|err| format!("{LABEL} could not parse '{field}': {err}"))?;
            let mut references = BTreeMap::new();
            Self::collect_analysis_parameter_references(
                &expression,
                &parameter_bits,
                &mut references,
                ".AC",
            )?;
            let reference_entries = references.into_iter().collect::<Vec<_>>();
            let [(reference, count)] = reference_entries.as_slice() else {
                return Err(format!(
                    "{LABEL} each .AC expression must exercise exactly one scalar parameter"
                ));
            };
            if *count != 1 || !field_parameters.insert(reference.clone()) {
                return Err(format!(
                    "{LABEL} each scalar parameter must occur exactly once in exactly one .AC field"
                ));
            }
        }
        if field_parameters != parameter_bits.keys().cloned().collect() {
            return Err(format!(
                "{LABEL} every declared scalar parameter must feed exactly one .AC field"
            ));
        }
        Ok((
            XyceAcAnalysisRepresentation::ParameterExpression,
            parameter_bits,
        ))
    }

    fn validate_ac_analysis_expression_plan(plan: &XyceRelationalAcPlan) -> Result<(), String> {
        const LABEL: &str = "AC-analysis expression parity";
        if plan.print.probes.is_empty()
            || plan.ac.frequencies.is_empty()
            || plan
                .ac
                .frequencies
                .iter()
                .any(|frequency| !frequency.is_finite() || *frequency < 0.0)
            || plan.ac.data_points().is_some()
        {
            return Err(format!(
                "{LABEL} requires a finite nonempty ordinary AC sweep and at least one probe"
            ));
        }
        let netlist = Self::parse_xyce_netlist(&plan.source, &plan.deck_path)
            .map_err(|err| format!("{LABEL} parse failed during plan validation: {err}"))?;
        Self::validate_ac_analysis_expression_probes(&netlist, &plan.print)?;
        Self::ac_analysis_source_qualification(&plan.source).map(|_| ())
    }

    fn validate_ac_analysis_expression_probes(
        netlist: &Netlist,
        print: &XycePrintRequest,
    ) -> Result<(), String> {
        const LABEL: &str = "AC-analysis expression parity";
        let mut probes = BTreeSet::new();
        for probe in &print.probes {
            if Self::print_expression_inner(probe).is_some() {
                return Err(format!(
                    "{LABEL} admits only direct atomic AC voltage/current probes, not braced expressions"
                ));
            }
            let normalized = Self::normalize_probe(probe);
            let atomic = Self::parse_ac_voltage_probe(&normalized)
                .is_some_and(|_| Self::probe_call_covers_entire_expression(&normalized))
                || Self::parse_ac_current_probe(&normalized)
                    .is_some_and(|_| Self::probe_call_covers_entire_expression(&normalized));
            if !atomic || !probes.insert(normalized.clone()) {
                return Err(format!(
                    "{LABEL} probe '{probe}' is not a unique direct atomic AC voltage/current probe"
                ));
            }
            Self::validate_ac_probe(&normalized, netlist)?;
        }
        Ok(())
    }

    fn ac_analysis_expression_snapshot(
        netlist: &Netlist,
    ) -> Result<XyceAcAnalysisExpressionSnapshot, String> {
        const LABEL: &str = "AC-analysis expression parity";
        let source = netlist
            .source_text
            .as_deref()
            .ok_or_else(|| format!("{LABEL} requires original source text"))?;
        let (representation, parameter_bits) = Self::ac_analysis_source_qualification(source)?;
        let footer_suppressed = Self::logical_netlist_lines(source)
            .into_iter()
            .skip(1)
            .map(|line| Self::strip_netlist_comment(&line).trim().to_string())
            .any(|line| {
                line.split_whitespace()
                    .next()
                    .is_some_and(|command| command.eq_ignore_ascii_case(".options"))
                    && Self::ac_analysis_output_option_is_footer_suppression(&line).unwrap_or(false)
            });
        let parsed_parameter_bits = netlist
            .params
            .numeric_parameters()
            .into_iter()
            .map(|(name, value)| (name.to_ascii_lowercase(), value.to_bits()))
            .collect::<BTreeMap<_, _>>();
        if parsed_parameter_bits != parameter_bits
            || !netlist.params.all_string_params().is_empty()
            || !netlist.params.all_functions().is_empty()
        {
            return Err(format!(
                "{LABEL} parsed scalar parameter state differs from the qualified direct assignments"
            ));
        }
        let diagnostics_are_canonical_footer_only = footer_suppressed
            && representation == XyceAcAnalysisRepresentation::DirectNumeric
            && netlist.diagnostics.len() == 1;
        if netlist.title.trim().is_empty()
            || netlist.title.trim_start().starts_with('.')
            || !netlist.models.is_empty()
            || (!netlist.diagnostics.is_empty() && !diagnostics_are_canonical_footer_only)
            || !matches!(netlist.analyses.as_slice(), [AnalysisCommand::Ac { .. }])
            || !netlist.fft_analyses.is_empty()
            || !netlist.data_tables.is_empty()
            || !netlist.subcircuits.is_empty()
            || !netlist.initial_conditions.is_empty()
            || !netlist.node_sets.is_empty()
            || !netlist.global_nodes.is_empty()
            || !netlist.measurements.is_empty()
            || !netlist.veriloga_includes.is_empty()
            || !netlist.spef_includes.is_empty()
        {
            return Err(format!(
                "{LABEL} requires one flat diagnostic-free ordinary AC analysis without models, hierarchy, auxiliary state, or external devices (models={}, diagnostics={}, analyses={}, fft={}, data={}, subckts={}, ic={}, nodesets={}, globals={}, measures={}, veriloga={}, spef={})",
                netlist.models.len(),
                netlist.diagnostics.len(),
                netlist.analyses.len(),
                netlist.fft_analyses.len(),
                netlist.data_tables.len(),
                netlist.subcircuits.len(),
                netlist.initial_conditions.len(),
                netlist.node_sets.len(),
                netlist.global_nodes.len(),
                netlist.measurements.len(),
                netlist.veriloga_includes.len(),
                netlist.spef_includes.len(),
            ));
        }
        for element in &netlist.elements {
            if element
                .nodes
                .iter()
                .any(|node| crate::compat::ground::is_spice_ground_name(node) && node.trim() != "0")
            {
                return Err(format!(
                    "{LABEL} element '{}' uses a ground alias; literal node 0 is required",
                    element.name
                ));
            }
            let valid = match &element.kind {
                ElementKind::Resistor {
                    value,
                    value_expr,
                    model,
                    instance_params,
                    deferred_params,
                } => {
                    element.nodes.len() == 2
                        && value.is_finite()
                        && *value > 0.0
                        && value_expr.is_none()
                        && model.is_none()
                        && instance_params.is_empty()
                        && deferred_params.is_empty()
                }
                ElementKind::Capacitor {
                    value,
                    value_expr,
                    initial_voltage,
                    model,
                    instance_params,
                    deferred_params,
                } => {
                    element.nodes.len() == 2
                        && value.is_finite()
                        && *value > 0.0
                        && value_expr.is_none()
                        && initial_voltage.is_none()
                        && model.is_none()
                        && instance_params.is_empty()
                        && deferred_params.is_empty()
                }
                ElementKind::VoltageSource(spec) | ElementKind::CurrentSource(spec) => {
                    let (magnitude, phase) = extract_ac_value(spec);
                    element.nodes.len() == 2 && magnitude.is_finite() && phase.is_finite()
                }
                _ => false,
            };
            if !valid {
                return Err(format!(
                    "{LABEL} contains unqualified element '{}'",
                    element.name
                ));
            }
        }

        let mut nonrepresentation_source = Vec::new();
        for line in Self::logical_netlist_lines(source).into_iter().skip(1) {
            let stripped = Self::strip_netlist_comment(&line).trim();
            let command = stripped.split_whitespace().next().unwrap_or_default();
            if command.eq_ignore_ascii_case(".param")
                || (command.eq_ignore_ascii_case(".options")
                    && Self::ac_analysis_output_option_is_footer_suppression(stripped)?)
            {
                continue;
            }
            if command.eq_ignore_ascii_case(".ac") {
                nonrepresentation_source.push(".ac <analysis-expression>".to_string());
            } else {
                nonrepresentation_source.push(
                    stripped
                        .split_whitespace()
                        .collect::<Vec<_>>()
                        .join(" ")
                        .to_ascii_lowercase(),
                );
            }
        }
        Ok(XyceAcAnalysisExpressionSnapshot {
            representation,
            parameter_bits,
            nonrepresentation_source,
            footer_suppressed,
        })
    }

    fn compare_ac_analysis_expression_snapshots(
        baseline: &XyceAcAnalysisExpressionSnapshot,
        target: &XyceAcAnalysisExpressionSnapshot,
    ) -> Result<(), String> {
        if baseline.representation != XyceAcAnalysisRepresentation::DirectNumeric
            || target.representation != XyceAcAnalysisRepresentation::ParameterExpression
            || !baseline.parameter_bits.is_empty()
            || target.parameter_bits.is_empty()
            || !baseline.footer_suppressed
            || target.footer_suppressed
        {
            return Err(
                "family must compare a direct numeric .AC baseline with a parameter-expression .AC representation"
                    .to_string(),
            );
        }
        if baseline.nonrepresentation_source != target.nonrepresentation_source {
            return Err(
                "circuit, source, output, or non-analysis directive semantics differ".to_string(),
            );
        }
        Ok(())
    }

    fn delimited_expression_token(
        token: &str,
    ) -> Result<(XyceDelimitedExpressionRepresentation, &str), String> {
        const LABEL: &str = "delimited-expression parity";
        let trimmed = token.trim();
        let (representation, inner) = if let Some(inner) = trimmed
            .strip_prefix('{')
            .and_then(|value| value.strip_suffix('}'))
        {
            (XyceDelimitedExpressionRepresentation::Braced, inner)
        } else if let Some(inner) = trimmed
            .strip_prefix('\'')
            .and_then(|value| value.strip_suffix('\''))
        {
            (XyceDelimitedExpressionRepresentation::SingleQuoted, inner)
        } else {
            return Err(format!(
                "{LABEL} expression must occupy one whole braced or single-quoted token: '{token}'"
            ));
        };
        let inner = inner.trim();
        if inner.is_empty() || inner.contains('{') || inner.contains('}') || inner.contains('\'') {
            return Err(format!(
                "{LABEL} expression must be nonempty and use one pure outer delimiter dialect: '{token}'"
            ));
        }
        Ok((representation, inner))
    }

    fn expression_ast_fingerprint(
        expression: &crate::netlist::expr::Expr,
    ) -> XyceExpressionAstFingerprint {
        use crate::netlist::expr::Expr as NetlistExpr;
        match expression {
            NetlistExpr::Number(value) => XyceExpressionAstFingerprint::Number(value.to_bits()),
            NetlistExpr::ComplexNumber(value) => {
                XyceExpressionAstFingerprint::Complex(value.re.to_bits(), value.im.to_bits())
            }
            NetlistExpr::Param(name) => {
                XyceExpressionAstFingerprint::Parameter(name.trim().to_ascii_lowercase())
            }
            NetlistExpr::BinOp { op, left, right } => XyceExpressionAstFingerprint::Binary(
                *op,
                Box::new(Self::expression_ast_fingerprint(left)),
                Box::new(Self::expression_ast_fingerprint(right)),
            ),
            NetlistExpr::UnaryOp { op, operand } => XyceExpressionAstFingerprint::Unary(
                *op,
                Box::new(Self::expression_ast_fingerprint(operand)),
            ),
            NetlistExpr::FnCall { name, args } => XyceExpressionAstFingerprint::Function(
                name.trim().to_ascii_lowercase(),
                args.iter().map(Self::expression_ast_fingerprint).collect(),
            ),
        }
    }

    fn parse_expression_fingerprint(
        expression: &str,
    ) -> Result<XyceExpressionAstFingerprint, String> {
        let ast = crate::netlist::expr::parse_expression(expression)
            .map_err(|err| format!("invalid delimited expression '{expression}': {err}"))?;
        Ok(Self::expression_ast_fingerprint(&ast))
    }

    fn delimited_expression_source_qualification(
        source: &str,
    ) -> Result<
        (
            XyceDelimitedExpressionRepresentation,
            BTreeMap<String, XyceExpressionAstFingerprint>,
        ),
        String,
    > {
        const LABEL: &str = "delimited-expression parity";
        if Self::source_has_comp_directive(source) {
            return Err(format!("{LABEL} does not admit *COMP"));
        }
        let lines = Self::logical_netlist_lines(source);
        if lines.is_empty() || lines[0].trim().is_empty() {
            return Err(format!("{LABEL} requires one nonempty title line"));
        }
        let mut representation = None;
        let mut sites = BTreeMap::new();
        let mut param_count = 0usize;
        let mut resistor_count = 0usize;
        let mut voltage_count = 0usize;
        let mut dc_count = 0usize;
        let mut print_count = 0usize;
        let mut print_expression_count = 0usize;
        let mut end_count = 0usize;

        let mut record_site = |key: String, token: &str| -> Result<(), String> {
            let (site_representation, inner) = Self::delimited_expression_token(token)?;
            if representation
                .replace(site_representation)
                .is_some_and(|current| current != site_representation)
            {
                return Err(format!(
                    "{LABEL} member mixes braced and single-quoted expression sites"
                ));
            }
            let fingerprint = Self::parse_expression_fingerprint(inner)?;
            if sites.insert(key.clone(), fingerprint).is_some() {
                return Err(format!(
                    "{LABEL} contains duplicate expression site '{key}'"
                ));
            }
            Ok(())
        };

        for line in lines.iter().skip(1) {
            let stripped = Self::strip_netlist_comment(line).trim();
            if stripped.is_empty() {
                continue;
            }
            let command = stripped.split_whitespace().next().unwrap_or_default();
            if command.starts_with('.') {
                match command.to_ascii_lowercase().as_str() {
                    ".param" => {
                        param_count += 1;
                        let rest = stripped[command.len()..].trim();
                        let Some((name, value)) = rest.split_once('=') else {
                            return Err(format!(
                                "{LABEL} requires canonical '.PARAM name = expression' syntax"
                            ));
                        };
                        let name = name.trim().to_ascii_lowercase();
                        if name.is_empty()
                            || value.contains('=')
                            || !Self::is_single_spice_identifier(&name)
                        {
                            return Err(format!("{LABEL} contains an invalid .PARAM assignment"));
                        }
                        record_site(format!("param:{name}"), value.trim())?;
                    }
                    ".dc" => {
                        dc_count += 1;
                        let fields = Self::split_grouped_whitespace_fields(
                            stripped,
                            "delimited-expression .DC statement",
                        )?;
                        if fields.len() != 5
                            || fields[1..]
                                .iter()
                                .any(|field| field.contains(['{', '}', '\'']))
                        {
                            return Err(format!(
                                "{LABEL} requires one direct linear '.DC source start stop step'"
                            ));
                        }
                    }
                    ".print" => {
                        print_count += 1;
                        let fields = Self::split_grouped_whitespace_fields(
                            stripped,
                            "delimited-expression .PRINT statement",
                        )?;
                        if fields.len() != 6
                            || !fields[1].eq_ignore_ascii_case("DC")
                            || fields[2..].iter().any(|field| field.contains('='))
                        {
                            return Err(format!(
                                "{LABEL} requires one default '.PRINT DC' with four probes"
                            ));
                        }
                        for (index, field) in fields[2..].iter().enumerate() {
                            if field.starts_with(['{', '\'']) || field.ends_with(['}', '\'']) {
                                record_site(format!("print:{index}"), field)?;
                                print_expression_count += 1;
                            } else if field.contains(['{', '}', '\'']) {
                                return Err(format!(
                                    "{LABEL} contains a malformed .PRINT expression token"
                                ));
                            }
                        }
                    }
                    ".end" => {
                        end_count += 1;
                        if !stripped.eq_ignore_ascii_case(".end") {
                            return Err(format!("{LABEL} requires a bare .END"));
                        }
                    }
                    other => {
                        return Err(format!("{LABEL} does not admit directive '{other}'"));
                    }
                }
                continue;
            }

            let fields = Self::split_grouped_whitespace_fields(
                stripped,
                "delimited-expression element statement",
            )?;
            if fields.len() != 4 {
                return Err(format!(
                    "{LABEL} admits only canonical two-terminal resistor and voltage-source lines"
                ));
            }
            let name = fields[0].trim().to_ascii_lowercase();
            match name.chars().next().map(|ch| ch.to_ascii_uppercase()) {
                Some('R') => {
                    resistor_count += 1;
                    record_site(format!("element:{name}:value"), &fields[3])?;
                }
                Some('V') => {
                    voltage_count += 1;
                    if fields[3].contains(['{', '}', '\'']) {
                        return Err(format!(
                            "{LABEL} voltage source must use a direct finite DC value"
                        ));
                    }
                }
                _ => {
                    return Err(format!(
                        "{LABEL} admits only one native resistor and one independent voltage source"
                    ));
                }
            }
        }

        if param_count != 1
            || resistor_count != 1
            || voltage_count != 1
            || dc_count != 1
            || print_count != 1
            || print_expression_count != 2
            || end_count != 1
            || sites.len() != 4
        {
            return Err(format!(
                "{LABEL} requires exactly one parameter, resistor, voltage source, DC, PRINT, END and four expression sites"
            ));
        }
        Ok((
            representation.ok_or_else(|| format!("{LABEL} contains no expression sites"))?,
            sites,
        ))
    }

    fn validate_delimited_expression_plan(plan: &XyceStaticDcPlan) -> Result<(), String> {
        const LABEL: &str = "delimited-expression parity";
        if !matches!(plan.expression_dialect, ExpressionDialect::Xyce)
            || plan.execution_dir.is_some()
            || plan.dc_data.is_some()
            || !plan.steps.is_empty()
            || !plan.diagnostics.is_empty()
            || plan.print_format.is_some()
            || plan.print.probes.len() != 4
            || plan.dc.sweep2.is_some()
            || plan.dc.primary_spec().points().is_empty()
        {
            return Err(format!(
                "{LABEL} requires one diagnostic-free native linear DC sweep with default indexed PRN output and no extra execution state"
            ));
        }
        let netlist = Self::parse_xyce_netlist(&plan.source, &plan.deck_path)
            .map_err(|err| format!("{LABEL} netlist parse failed: {err}"))?;
        for probe in &plan.print.probes {
            if let Some(expression) = Self::print_expression_inner(probe) {
                Self::validate_dc_probe_expression(expression, &netlist)?;
            } else {
                Self::validate_atomic_dc_probe(&Self::normalize_probe(probe), probe, &netlist)?;
            }
        }
        Self::delimited_expression_source_qualification(&plan.source).map(|_| ())
    }

    fn delimited_expression_family_snapshot(
        plan: &XyceStaticDcPlan,
        netlist: &Netlist,
    ) -> Result<XyceDelimitedExpressionFamilySnapshot, String> {
        const LABEL: &str = "delimited-expression parity";
        let (representation, expression_sites) =
            Self::delimited_expression_source_qualification(&plan.source)?;
        if netlist.elements.len() != 2
            || netlist.analyses.len() != 1
            || !matches!(netlist.analyses[0], AnalysisCommand::Dc { .. })
            || !netlist.models.is_empty()
            || !netlist.subcircuits.is_empty()
            || !netlist.fft_analyses.is_empty()
            || !netlist.data_tables.is_empty()
            || !netlist.initial_conditions.is_empty()
            || !netlist.node_sets.is_empty()
            || !netlist.global_nodes.is_empty()
            || !netlist.measurements.is_empty()
            || !netlist.veriloga_includes.is_empty()
            || !netlist.spef_includes.is_empty()
            || !netlist.diagnostics.is_empty()
        {
            return Err(format!(
                "{LABEL} parsed netlist contains state outside the qualified R/V/DC surface"
            ));
        }
        let parameter_bits = netlist
            .params
            .all_params()
            .into_iter()
            .map(|(name, value)| {
                if !value.is_finite() {
                    return Err(format!("{LABEL} parameter '{name}' is non-finite"));
                }
                Ok((name.to_ascii_lowercase(), value.to_bits()))
            })
            .collect::<Result<BTreeMap<_, _>, _>>()?;
        if parameter_bits.len() != 1 {
            return Err(format!("{LABEL} requires exactly one resolved parameter"));
        }

        let mut elements = BTreeMap::new();
        for element in &netlist.elements {
            let nodes = element
                .nodes
                .iter()
                .map(|node| node.trim().to_ascii_lowercase())
                .collect::<Vec<_>>();
            if nodes.len() != 2 || nodes[0].is_empty() || nodes[0] == "0" || nodes[1] != "0" {
                return Err(format!(
                    "{LABEL} requires each R/V element from one literal non-ground node to literal node 0"
                ));
            }
            let fingerprint = match &element.kind {
                ElementKind::Resistor { .. } => {
                    let value = Self::effective_resistor_value(netlist, &element.name)
                        .ok_or_else(|| format!("{LABEL} could not resolve resistor value"))?;
                    if !value.is_finite() || value <= 0.0 {
                        return Err(format!(
                            "{LABEL} resistor value must be finite and strictly positive"
                        ));
                    }
                    XyceRelationalElementFingerprint {
                        kind: "r".to_string(),
                        nodes,
                        numeric_bits: vec![value.to_bits()],
                        text: Vec::new(),
                    }
                }
                ElementKind::VoltageSource(crate::netlist::SourceSpec::Dc(value)) => {
                    let value = *value;
                    if !value.is_finite() {
                        return Err(format!("{LABEL} voltage-source value is non-finite"));
                    }
                    XyceRelationalElementFingerprint {
                        kind: "v".to_string(),
                        nodes,
                        numeric_bits: vec![value.to_bits()],
                        text: Vec::new(),
                    }
                }
                ElementKind::VoltageSource(_) => {
                    return Err(format!(
                        "{LABEL} voltage source must be one direct SourceSpec::Dc"
                    ));
                }
                _ => return Err(format!("{LABEL} contains a non-R/V element")),
            };
            if elements
                .insert(element.name.trim().to_ascii_lowercase(), fingerprint)
                .is_some()
            {
                return Err(format!("{LABEL} contains duplicate element identity"));
            }
        }
        let mut signal_nodes = elements
            .values()
            .map(|element| element.nodes[0].as_str())
            .collect::<BTreeSet<_>>();
        if signal_nodes.len() != 1 {
            return Err(format!(
                "{LABEL} resistor and voltage source must share one non-ground node"
            ));
        }
        let _ = signal_nodes.pop_first();
        if !elements.iter().any(|(name, element)| {
            element.kind == "v" && Self::device_instance_names_match(name, &plan.dc.source)
        }) {
            return Err(format!(
                "{LABEL} .DC sweep source must be the qualified voltage source"
            ));
        }

        let print_probes = plan
            .print
            .probes
            .iter()
            .map(|probe| {
                if let Some(expression) = Self::print_expression_inner(probe) {
                    Self::parse_expression_fingerprint(expression)
                        .map(XycePrintSemanticFingerprint::Expression)
                } else {
                    Ok(XycePrintSemanticFingerprint::Atomic(Self::normalize_probe(
                        probe,
                    )))
                }
            })
            .collect::<Result<Vec<_>, _>>()?;
        Ok(XyceDelimitedExpressionFamilySnapshot {
            representation,
            expression_sites,
            parameter_bits,
            elements,
            print_probes,
        })
    }

    fn compare_delimited_expression_snapshots(
        baseline: &XyceDelimitedExpressionFamilySnapshot,
        target: &XyceDelimitedExpressionFamilySnapshot,
    ) -> Result<(), String> {
        if baseline.representation != XyceDelimitedExpressionRepresentation::Braced
            || target.representation != XyceDelimitedExpressionRepresentation::SingleQuoted
        {
            return Err(
                "family must compare one pure braced baseline with one pure single-quoted wrapper"
                    .to_string(),
            );
        }
        if baseline.expression_sites != target.expression_sites {
            return Err("expression-site AST bijection differs".to_string());
        }
        if baseline.parameter_bits != target.parameter_bits
            || baseline.elements != target.elements
            || baseline.print_probes != target.print_probes
        {
            return Err("resolved circuit, parameter, or print semantics differ".to_string());
        }
        Ok(())
    }

    fn validate_dc_analysis_expression_plan(plan: &XyceStaticDcPlan) -> Result<(), String> {
        const LABEL: &str = "DC-analysis expression parity";
        if !matches!(plan.expression_dialect, ExpressionDialect::Xyce)
            || plan.execution_dir.is_some()
            || plan.dc_data.is_some()
            || !plan.steps.is_empty()
            || !plan.diagnostics.is_empty()
            || plan.print_format.is_some()
            || plan.print.probes.is_empty()
        {
            return Err(format!(
                "{LABEL} requires one diagnostic-free native Xyce .DC sweep with default indexed PRN output, no execution-directory override, no .DATA, and no .STEP"
            ));
        }
        if plan.dc.primary_spec().points().is_empty()
            || plan
                .dc
                .sweep2
                .as_ref()
                .is_some_and(|sweep| sweep.spec().points().is_empty())
        {
            return Err(format!("{LABEL} requires finite nonempty DC sweep grids"));
        }
        Self::dc_analysis_source_qualification(&plan.source).map(|_| ())
    }

    fn dc_analysis_value_fields(statement: &str) -> Result<Vec<String>, String> {
        const LABEL: &str = "DC-analysis expression parity";
        let fields = Self::split_grouped_whitespace_fields(statement, ".DC statement")?;
        if fields
            .first()
            .is_none_or(|field| !field.eq_ignore_ascii_case(".DC"))
        {
            return Err(format!("{LABEL} requires a .DC statement"));
        }
        if fields.get(1).is_some_and(|field| {
            field.eq_ignore_ascii_case("DEC") || field.eq_ignore_ascii_case("OCT")
        }) {
            if fields.len() != 6 || !Self::is_single_spice_identifier(&fields[2]) {
                return Err(format!(
                    "{LABEL} DEC/OCT sweeps require '.DC mode source start stop points'"
                ));
            }
            return Ok(fields[3..].to_vec());
        }
        if fields
            .get(2)
            .is_some_and(|field| field.eq_ignore_ascii_case("LIST"))
        {
            if fields.len() < 4 || !Self::is_single_spice_identifier(&fields[1]) {
                return Err(format!(
                    "{LABEL} LIST sweeps require '.DC source LIST value ...'"
                ));
            }
            return Ok(fields[3..].to_vec());
        }
        if !matches!(fields.len(), 5 | 9)
            || !Self::is_single_spice_identifier(&fields[1])
            || (fields.len() == 9 && !Self::is_single_spice_identifier(&fields[5]))
        {
            return Err(format!(
                "{LABEL} linear sweeps require one or two 'source start stop step' dimensions"
            ));
        }
        let mut values = fields[2..5].to_vec();
        if fields.len() == 9 {
            values.extend_from_slice(&fields[6..9]);
        }
        Ok(values)
    }

    fn dc_analysis_source_qualification(
        source: &str,
    ) -> Result<(XyceDcAnalysisRepresentation, BTreeMap<String, u64>), String> {
        const LABEL: &str = "DC-analysis expression parity";
        if Self::source_has_comp_directive(source) {
            return Err(format!(
                "{LABEL} uses the canonical default verifier and does not admit *COMP"
            ));
        }
        let lines = Self::logical_netlist_lines(source);
        if lines.is_empty() {
            return Err(format!("{LABEL} requires a nonempty source"));
        }
        let mut parameter_bits = BTreeMap::new();
        let mut dc_fields = None;
        let mut print_count = 0usize;
        let mut end_count = 0usize;
        let mut model_count = 0usize;
        let mut element_count = 0usize;
        for line in lines.iter().skip(1) {
            let stripped = Self::strip_netlist_comment(line).trim();
            let Some(command) = stripped.split_whitespace().next() else {
                continue;
            };
            if command.starts_with('.') {
                match command.to_ascii_lowercase().as_str() {
                    ".param" => {
                        let fields = Self::split_grouped_whitespace_fields(
                            stripped,
                            "DC-analysis .PARAM statement",
                        )?;
                        let [_, assignment] = fields.as_slice() else {
                            return Err(format!(
                                "{LABEL} requires one direct '.PARAM name=value' assignment per statement"
                            ));
                        };
                        let Some((name, value)) = assignment.split_once('=') else {
                            return Err(format!(
                                "{LABEL} requires canonical '.PARAM name=value' syntax"
                            ));
                        };
                        let name = name.trim().to_ascii_lowercase();
                        if name.is_empty()
                            || value.trim().is_empty()
                            || value.contains('=')
                            || !name.chars().enumerate().all(|(index, ch)| {
                                ch.is_ascii_alphanumeric()
                                    || ch == '_'
                                    || (index > 0 && matches!(ch, '.' | '$'))
                            })
                            || name.chars().next().is_some_and(|ch| ch.is_ascii_digit())
                        {
                            return Err(format!(
                                "{LABEL} contains invalid parameter assignment '{assignment}'"
                            ));
                        }
                        let value = Self::single_spice_numeric_literal_value(value)?;
                        if !value.is_finite()
                            || parameter_bits
                                .insert(name.clone(), value.to_bits())
                                .is_some()
                        {
                            return Err(format!(
                                "{LABEL} parameter '{name}' must be unique and finite"
                            ));
                        }
                    }
                    ".dc" => {
                        if dc_fields.is_some() {
                            return Err(format!("{LABEL} requires exactly one .DC"));
                        }
                        dc_fields = Some(Self::dc_analysis_value_fields(stripped)?);
                    }
                    ".print" => {
                        let fields = Self::split_grouped_whitespace_fields(
                            stripped,
                            "DC-analysis .PRINT statement",
                        )?;
                        if fields.len() < 3
                            || !fields[0].eq_ignore_ascii_case(".PRINT")
                            || !fields[1].eq_ignore_ascii_case("DC")
                        {
                            return Err(format!(
                                "{LABEL} requires a nonempty '.PRINT DC probe ...' statement"
                            ));
                        }
                        print_count += 1;
                    }
                    ".model" => model_count += 1,
                    ".end" => {
                        end_count += 1;
                        if !stripped.eq_ignore_ascii_case(".end") {
                            return Err(format!("{LABEL} requires a bare .END statement"));
                        }
                    }
                    other => {
                        return Err(format!("{LABEL} does not admit directive '{other}'"));
                    }
                }
                continue;
            }

            element_count += 1;
            if stripped.contains('{') || stripped.contains('}') {
                return Err(format!(
                    "{LABEL} element statements must not consume analysis parameters"
                ));
            }
            let designator = command
                .chars()
                .next()
                .map(|ch| ch.to_ascii_uppercase())
                .ok_or_else(|| format!("{LABEL} contains an empty element statement"))?;
            if !matches!(designator, 'R' | 'V' | 'M') {
                return Err(format!(
                    "{LABEL} admits only native resistors, independent voltage sources, and classic MOS elements; got '{command}'"
                ));
            }
        }
        if print_count != 1 || end_count != 1 || element_count == 0 || model_count > 1 {
            return Err(format!(
                "{LABEL} requires one .PRINT, one .END, at least one element, and at most one model; found ({print_count}, {end_count}, {element_count}, {model_count})"
            ));
        }
        let dc_fields = dc_fields.ok_or_else(|| format!("{LABEL} contains no .DC"))?;

        if parameter_bits.is_empty() {
            if dc_fields
                .iter()
                .all(|field| Self::is_single_spice_numeric_literal(field))
            {
                return Ok((XyceDcAnalysisRepresentation::DirectNumeric, parameter_bits));
            }
            return Err(format!(
                "{LABEL} numeric baseline requires only direct finite .DC literals"
            ));
        }

        for line in lines.iter().skip(1) {
            let stripped = Self::strip_netlist_comment(line).trim();
            let command = stripped.split_whitespace().next().unwrap_or_default();
            if command.eq_ignore_ascii_case(".param") || command.eq_ignore_ascii_case(".dc") {
                continue;
            }
            let identifiers = stripped
                .split(|ch: char| !(ch.is_ascii_alphanumeric() || matches!(ch, '_' | '.' | '$')))
                .filter(|field| {
                    field
                        .chars()
                        .next()
                        .is_some_and(|ch| ch.is_ascii_alphabetic() || ch == '_')
                });
            if identifiers.into_iter().any(|identifier| {
                parameter_bits
                    .keys()
                    .any(|name| identifier.eq_ignore_ascii_case(name))
            }) {
                return Err(format!(
                    "{LABEL} analysis parameters may be referenced only by .DC fields"
                ));
            }
        }

        if dc_fields.len() != parameter_bits.len() {
            return Err(format!(
                "{LABEL} requires one unique scalar parameter per .DC value field"
            ));
        }
        let mut field_parameters = BTreeSet::new();
        for field in &dc_fields {
            let Some(expression) = field
                .strip_prefix('{')
                .and_then(|value| value.strip_suffix('}'))
            else {
                return Err(format!(
                    "{LABEL} parameterized .DC fields must each be one braced expression"
                ));
            };
            let expression = crate::netlist::expr::parse_expression(expression)
                .map_err(|err| format!("{LABEL} could not parse '{field}': {err}"))?;
            let mut references = BTreeMap::new();
            Self::collect_analysis_parameter_references(
                &expression,
                &parameter_bits,
                &mut references,
                ".DC",
            )?;
            let reference_entries = references.into_iter().collect::<Vec<_>>();
            let [(reference, count)] = reference_entries.as_slice() else {
                return Err(format!(
                    "{LABEL} each .DC expression must exercise exactly one scalar parameter"
                ));
            };
            if *count != 1 || !field_parameters.insert(reference.clone()) {
                return Err(format!(
                    "{LABEL} each scalar parameter must occur exactly once in exactly one .DC field"
                ));
            }
        }
        if field_parameters != parameter_bits.keys().cloned().collect() {
            return Err(format!(
                "{LABEL} every declared scalar parameter must feed exactly one .DC field"
            ));
        }
        Ok((
            XyceDcAnalysisRepresentation::ParameterExpression,
            parameter_bits,
        ))
    }

    fn dc_analysis_expression_snapshot(
        netlist: &Netlist,
    ) -> Result<XyceDcAnalysisExpressionSnapshot, String> {
        const LABEL: &str = "DC-analysis expression parity";
        let source = netlist
            .source_text
            .as_deref()
            .ok_or_else(|| format!("{LABEL} requires original source text"))?;
        let (representation, parameter_bits) = Self::dc_analysis_source_qualification(source)?;
        let parsed_parameter_bits = netlist
            .params
            .numeric_parameters()
            .into_iter()
            .map(|(name, value)| (name.to_ascii_lowercase(), value.to_bits()))
            .collect::<BTreeMap<_, _>>();
        if parsed_parameter_bits != parameter_bits
            || !netlist.params.all_string_params().is_empty()
            || !netlist.params.all_functions().is_empty()
        {
            return Err(format!(
                "{LABEL} parsed scalar parameter state differs from the qualified direct assignments"
            ));
        }
        if !netlist.diagnostics.is_empty()
            || !matches!(netlist.analyses.as_slice(), [AnalysisCommand::Dc { .. }])
            || !netlist.fft_analyses.is_empty()
            || !netlist.data_tables.is_empty()
            || !netlist.subcircuits.is_empty()
            || !netlist.initial_conditions.is_empty()
            || !netlist.node_sets.is_empty()
            || !netlist.global_nodes.is_empty()
            || !netlist.measurements.is_empty()
            || !netlist.veriloga_includes.is_empty()
            || !netlist.spef_includes.is_empty()
        {
            return Err(format!(
                "{LABEL} requires a flat diagnostic-free DC deck without auxiliary analyses or external model state"
            ));
        }
        for model in &netlist.models {
            if !Self::model_is_native_dc_analysis_expression_mos1(model) {
                return Err(format!(
                    "{LABEL} admits only direct native classic MOS LEVEL=1 models"
                ));
            }
        }
        for element in &netlist.elements {
            if element
                .nodes
                .iter()
                .any(|node| crate::compat::ground::is_spice_ground_name(node) && node.trim() != "0")
            {
                return Err(format!(
                    "{LABEL} element '{}' uses a ground alias; literal node 0 is required",
                    element.name
                ));
            }
            let valid = match &element.kind {
                ElementKind::Resistor {
                    value,
                    value_expr,
                    model,
                    instance_params,
                    deferred_params,
                } => {
                    element.nodes.len() == 2
                        && value.is_finite()
                        && *value > 0.0
                        && value_expr.is_none()
                        && model.is_none()
                        && instance_params.is_empty()
                        && deferred_params.is_empty()
                }
                ElementKind::VoltageSource(crate::netlist::SourceSpec::Dc(value)) => {
                    element.nodes.len() == 2 && value.is_finite()
                }
                ElementKind::Mosfet {
                    model,
                    compact_syntax,
                    instance_params,
                    deferred_params,
                    ..
                } => {
                    element.nodes.len() == 4
                        && !compact_syntax
                        && instance_params.is_empty()
                        && deferred_params.is_empty()
                        && netlist.models.iter().any(|candidate| {
                            candidate.name.eq_ignore_ascii_case(model)
                                && matches!(
                                    candidate.model_type.to_ascii_uppercase().as_str(),
                                    "NMOS" | "PMOS"
                                )
                        })
                }
                _ => false,
            };
            if !valid {
                return Err(format!(
                    "{LABEL} contains unqualified element '{}'",
                    element.name
                ));
            }
        }

        let mut nonrepresentation_source = Vec::new();
        for line in Self::logical_netlist_lines(source).into_iter().skip(1) {
            let stripped = Self::strip_netlist_comment(&line).trim();
            let command = stripped.split_whitespace().next().unwrap_or_default();
            if command.eq_ignore_ascii_case(".param") {
                continue;
            }
            if command.eq_ignore_ascii_case(".dc") {
                nonrepresentation_source.push(".dc <analysis-expression>".to_string());
            } else {
                nonrepresentation_source.push(
                    stripped
                        .split_whitespace()
                        .collect::<Vec<_>>()
                        .join(" ")
                        .to_ascii_lowercase(),
                );
            }
        }
        Ok(XyceDcAnalysisExpressionSnapshot {
            representation,
            parameter_bits,
            nonrepresentation_source,
        })
    }

    fn model_is_native_dc_analysis_expression_mos1(model: &crate::netlist::ModelDef) -> bool {
        if !matches!(
            model.model_type.to_ascii_uppercase().as_str(),
            "NMOS" | "PMOS"
        ) || !model.expr_params.is_empty()
            || !model.string_params.is_empty()
            || !model.string_vector_params.is_empty()
            || !model.real_vector_params.is_empty()
            || !model.real_vector_expr_params.is_empty()
            || !model.integer_vector_params.is_empty()
        {
            return false;
        }
        let mut names = BTreeSet::new();
        model.params.iter().all(|(name, value)| {
            let normalized = name.to_ascii_uppercase();
            names.insert(normalized.clone())
                && Self::native_dc_analysis_expression_mos1_model_param(&normalized, *value)
        })
    }

    fn native_dc_analysis_expression_mos1_model_param(name: &str, value: Value) -> bool {
        if !value.is_finite() {
            return false;
        }
        match name {
            "LEVEL" => value.to_bits() == 1.0f64.to_bits(),
            "VTO" | "VT0" | "VTH0" | "XTI" => true,
            "KP" | "PHI" | "U0" | "UO" | "TOX" | "NSUB" | "L" | "W" | "PB" | "AF" => value > 0.0,
            "GAMMA" | "LAMBDA" | "NSS" | "NFS" | "IS" | "JS" | "LD" | "RD" | "RS" | "RSH"
            | "CBD" | "CAPBD" | "CBS" | "CAPBS" | "CJ" | "CJ0" | "CJSW" | "CGSO" | "CGDO"
            | "CGBO" | "KF" => value >= 0.0,
            "TPG" | "GATE" => matches!(value, -1.0 | 0.0 | 1.0),
            "MJ" | "MJSW" => (0.0..=1.0).contains(&value),
            "FC" => (0.0..1.0).contains(&value),
            "TNOM" => value > -273.15,
            _ => false,
        }
    }

    fn compare_dc_analysis_expression_snapshots(
        baseline: &XyceDcAnalysisExpressionSnapshot,
        target: &XyceDcAnalysisExpressionSnapshot,
    ) -> Result<(), String> {
        if baseline.representation != XyceDcAnalysisRepresentation::DirectNumeric
            || target.representation != XyceDcAnalysisRepresentation::ParameterExpression
            || !baseline.parameter_bits.is_empty()
            || target.parameter_bits.is_empty()
        {
            return Err(
                "family must compare a direct numeric .DC baseline with a parameter-expression .DC representation"
                    .to_string(),
            );
        }
        if baseline.nonrepresentation_source != target.nonrepresentation_source {
            return Err(
                "circuit, model, output, or non-analysis directive semantics differ".to_string(),
            );
        }
        Ok(())
    }

    fn validate_transient_analysis_expression_plan(
        plan: &XyceStaticTranPlan,
    ) -> Result<(), String> {
        const LABEL: &str = "transient-analysis expression parity";
        if !matches!(
            plan.contract,
            XyceStaticTranContract::PlainStatic | XyceStaticTranContract::WrapperStatic
        ) {
            return Err(format!(
                "{LABEL} requires ordinary default .prn output, got {:?}",
                plan.contract
            ));
        }
        if !plan.steps.is_empty() || plan.output_override || plan.timeint_conststep {
            return Err(format!(
                "{LABEL} does not admit .STEP, output overrides, or constant-step output"
            ));
        }
        if plan.wrapper_tolerance.is_some() {
            return Err(format!(
                "{LABEL} uses the canonical default xyce_verify tolerance and does not admit wrapper overrides"
            ));
        }
        if !plan.tran.step.is_finite()
            || !plan.tran.stop.is_finite()
            || plan.tran.step < 0.0
            || plan.tran.stop <= 0.0
            || plan.tran.step > plan.tran.stop
            || plan
                .tran
                .start
                .is_some_and(|value| !value.is_finite() || value < 0.0 || value > plan.tran.stop)
            || plan
                .tran
                .max_step
                .is_some_and(|value| !value.is_finite() || value <= 0.0)
            || plan.tran.uic
        {
            return Err(format!(
                "{LABEL} requires a finite nonnegative TSTEP, positive TSTOP, bounded optional TSTART, positive optional DTMAX, and no UIC"
            ));
        }
        if plan.print.probes.is_empty() {
            return Err(format!(
                "{LABEL} requires at least one ordered .PRINT TRAN probe"
            ));
        }
        Self::transient_analysis_source_qualification(&plan.source).map(|_| ())
    }

    fn transient_analysis_source_qualification(
        source: &str,
    ) -> Result<(XyceTransientAnalysisRepresentation, BTreeMap<String, u64>), String> {
        const LABEL: &str = "transient-analysis expression parity";
        if Self::source_has_comp_directive(source) {
            return Err(format!(
                "{LABEL} uses canonical default xyce_verify tolerances and does not admit *COMP"
            ));
        }
        let lines = Self::logical_netlist_lines(source);
        if lines.is_empty() {
            return Err(format!("{LABEL} requires a nonempty source"));
        }
        let mut parameter_bits = BTreeMap::new();
        let mut tran_fields = None;
        let mut print_count = 0usize;
        let mut end_count = 0usize;
        let mut element_count = 0usize;
        for line in lines.iter().skip(1) {
            let stripped = Self::strip_netlist_comment(line).trim();
            let Some(command) = stripped.split_whitespace().next() else {
                continue;
            };
            if command.starts_with('.') {
                match command.to_ascii_lowercase().as_str() {
                    ".param" => {
                        let fields = Self::split_grouped_whitespace_fields(
                            stripped,
                            "transient-analysis .PARAM statement",
                        )?;
                        let [_, assignment] = fields.as_slice() else {
                            return Err(format!(
                                "{LABEL} requires one direct '.PARAM name=value' assignment per statement"
                            ));
                        };
                        let Some((name, value)) = assignment.split_once('=') else {
                            return Err(format!(
                                "{LABEL} requires canonical '.PARAM name=value' syntax"
                            ));
                        };
                        let name = name.trim().to_ascii_lowercase();
                        if name.is_empty()
                            || value.trim().is_empty()
                            || value.contains('=')
                            || !name.chars().enumerate().all(|(index, ch)| {
                                ch.is_ascii_alphanumeric()
                                    || ch == '_'
                                    || (index > 0 && matches!(ch, '.' | '$'))
                            })
                            || name.chars().next().is_some_and(|ch| ch.is_ascii_digit())
                        {
                            return Err(format!(
                                "{LABEL} contains invalid parameter assignment '{assignment}'"
                            ));
                        }
                        let value = Self::single_spice_numeric_literal_value(value)?;
                        if !value.is_finite()
                            || parameter_bits
                                .insert(name.clone(), value.to_bits())
                                .is_some()
                        {
                            return Err(format!(
                                "{LABEL} parameter '{name}' must be unique and finite"
                            ));
                        }
                    }
                    ".tran" => {
                        if tran_fields.is_some() {
                            return Err(format!("{LABEL} requires exactly one .TRAN"));
                        }
                        let fields = Self::split_grouped_whitespace_fields(
                            stripped,
                            "transient-analysis .TRAN statement",
                        )?;
                        if !(3..=5).contains(&fields.len()) {
                            return Err(format!("{LABEL} requires two to four .TRAN value fields"));
                        }
                        tran_fields = Some(fields.into_iter().skip(1).collect::<Vec<_>>());
                    }
                    ".print" => print_count += 1,
                    ".options" => {}
                    ".end" => {
                        end_count += 1;
                        if !stripped.eq_ignore_ascii_case(".end") {
                            return Err(format!("{LABEL} requires a bare .END statement"));
                        }
                    }
                    other => {
                        return Err(format!("{LABEL} does not admit directive '{other}'"));
                    }
                }
                continue;
            }

            element_count += 1;
            if stripped.contains('{') || stripped.contains('}') {
                return Err(format!(
                    "{LABEL} element statements must not consume analysis parameters"
                ));
            }
            let fields = Self::split_grouped_whitespace_fields(
                stripped,
                "transient-analysis element statement",
            )?;
            let designator = fields
                .first()
                .and_then(|field| field.chars().next())
                .map(|ch| ch.to_ascii_uppercase())
                .ok_or_else(|| format!("{LABEL} contains an empty element statement"))?;
            match designator {
                'R' if fields.len() == 4 && Self::is_single_spice_numeric_literal(&fields[3]) => {}
                'C' if (4..=5).contains(&fields.len())
                    && Self::is_single_spice_numeric_literal(&fields[3]) =>
                {
                    if let Some(initial) = fields.get(4) {
                        let Some((name, value)) = initial.split_once('=') else {
                            return Err(format!(
                                "{LABEL} capacitor optional field must be direct IC=value"
                            ));
                        };
                        if !name.eq_ignore_ascii_case("IC")
                            || !Self::is_single_spice_numeric_literal(value)
                        {
                            return Err(format!(
                                "{LABEL} capacitor optional field must be direct finite IC=value"
                            ));
                        }
                    }
                }
                'V' | 'I' if fields.len() == 4 => {}
                _ => {
                    return Err(format!(
                        "{LABEL} admits only direct R/C and independent V/I element statements; got '{command}'"
                    ));
                }
            }
        }
        if print_count != 1 || end_count != 1 || element_count == 0 {
            return Err(format!(
                "{LABEL} requires one .PRINT, one .END, and at least one element; found ({print_count}, {end_count}, {element_count})"
            ));
        }
        let tran_fields = tran_fields.ok_or_else(|| format!("{LABEL} contains no .TRAN"))?;

        if parameter_bits.is_empty() {
            if tran_fields
                .iter()
                .all(|field| Self::is_single_spice_numeric_literal(field))
            {
                return Ok((
                    XyceTransientAnalysisRepresentation::DirectNumeric,
                    parameter_bits,
                ));
            }
            return Err(format!(
                "{LABEL} numeric baseline requires only direct finite .TRAN literals"
            ));
        }

        for line in lines.iter().skip(1) {
            let stripped = Self::strip_netlist_comment(line).trim();
            let command = stripped.split_whitespace().next().unwrap_or_default();
            if command.eq_ignore_ascii_case(".param") || command.eq_ignore_ascii_case(".tran") {
                continue;
            }
            let identifiers = stripped
                .split(|ch: char| !(ch.is_ascii_alphanumeric() || matches!(ch, '_' | '.' | '$')))
                .filter(|field| {
                    field
                        .chars()
                        .next()
                        .is_some_and(|ch| ch.is_ascii_alphabetic() || ch == '_')
                });
            if identifiers.into_iter().any(|identifier| {
                parameter_bits
                    .keys()
                    .any(|name| identifier.eq_ignore_ascii_case(name))
            }) {
                return Err(format!(
                    "{LABEL} analysis parameters may be referenced only by .TRAN fields"
                ));
            }
        }

        if tran_fields.len() != parameter_bits.len() {
            return Err(format!(
                "{LABEL} requires one unique scalar parameter per .TRAN field"
            ));
        }
        let mut field_parameters = BTreeSet::new();
        for field in &tran_fields {
            let Some(expression) = field
                .strip_prefix('{')
                .and_then(|value| value.strip_suffix('}'))
            else {
                return Err(format!(
                    "{LABEL} parameterized .TRAN fields must each be one braced expression"
                ));
            };
            let expression = crate::netlist::expr::parse_expression(expression)
                .map_err(|err| format!("{LABEL} could not parse '{field}': {err}"))?;
            let mut references = BTreeMap::new();
            Self::collect_analysis_parameter_references(
                &expression,
                &parameter_bits,
                &mut references,
                ".TRAN",
            )?;
            let reference_entries = references.into_iter().collect::<Vec<_>>();
            let [(reference, count)] = reference_entries.as_slice() else {
                return Err(format!(
                    "{LABEL} each .TRAN expression must exercise exactly one scalar parameter"
                ));
            };
            if *count != 1 {
                return Err(format!(
                    "{LABEL} each scalar parameter must occur exactly once in its .TRAN field"
                ));
            }
            if !field_parameters.insert(reference.clone()) {
                return Err(format!(
                    "{LABEL} each scalar parameter must belong to exactly one .TRAN field"
                ));
            }
        }
        if field_parameters != parameter_bits.keys().cloned().collect() {
            return Err(format!(
                "{LABEL} every declared scalar parameter must feed exactly one .TRAN field"
            ));
        }
        Ok((
            XyceTransientAnalysisRepresentation::ParameterExpression,
            parameter_bits,
        ))
    }

    fn collect_analysis_parameter_references(
        expression: &crate::netlist::expr::Expr,
        declared: &BTreeMap<String, u64>,
        references: &mut BTreeMap<String, usize>,
        directive: &str,
    ) -> Result<(), String> {
        use crate::netlist::expr::{BinOpKind, Expr as NetExpr, UnaryOpKind};

        match expression {
            NetExpr::Number(value) if value.is_finite() => Ok(()),
            NetExpr::Param(name) => {
                let name = name.to_ascii_lowercase();
                if !declared.contains_key(&name) {
                    return Err(format!(
                        "undeclared or runtime identifier '{name}' in {directive} expression"
                    ));
                }
                *references.entry(name).or_default() += 1;
                Ok(())
            }
            NetExpr::BinOp { op, left, right }
                if matches!(
                    op,
                    BinOpKind::Add
                        | BinOpKind::Sub
                        | BinOpKind::Mul
                        | BinOpKind::Div
                        | BinOpKind::Pow
                ) =>
            {
                Self::collect_analysis_parameter_references(left, declared, references, directive)?;
                Self::collect_analysis_parameter_references(right, declared, references, directive)
            }
            NetExpr::UnaryOp { op, operand }
                if matches!(op, UnaryOpKind::Neg | UnaryOpKind::Pos) =>
            {
                Self::collect_analysis_parameter_references(
                    operand, declared, references, directive,
                )
            }
            _ => Err(format!(
                "only finite real arithmetic over direct scalar parameters is admitted in {directive} expressions"
            )),
        }
    }

    fn transient_analysis_expression_snapshot(
        netlist: &Netlist,
        print: &XycePrintRequest,
    ) -> Result<XyceTransientAnalysisExpressionSnapshot, String> {
        const LABEL: &str = "transient-analysis expression parity";
        let source = netlist
            .source_text
            .as_deref()
            .ok_or_else(|| format!("{LABEL} requires original source text"))?;
        let (representation, parameter_bits) =
            Self::transient_analysis_source_qualification(source)?;
        if netlist.title.trim().is_empty()
            || netlist.title.trim_start().starts_with('.')
            || print.probes.is_empty()
            || !netlist.models.is_empty()
            || !netlist.diagnostics.is_empty()
            || !matches!(netlist.analyses.as_slice(), [AnalysisCommand::Tran { .. }])
            || !netlist.fft_analyses.is_empty()
            || !netlist.data_tables.is_empty()
            || !netlist.subcircuits.is_empty()
            || !netlist.initial_conditions.is_empty()
            || !netlist.node_sets.is_empty()
            || !netlist.global_nodes.is_empty()
            || !netlist.measurements.is_empty()
            || !netlist.veriloga_includes.is_empty()
            || !netlist.spef_includes.is_empty()
            || !netlist.params.all_string_params().is_empty()
            || !netlist.params.all_functions().is_empty()
        {
            return Err(format!(
                "{LABEL} requires one flat diagnostic-free transient analysis without models, hierarchy, auxiliary state, or external devices"
            ));
        }
        let parsed_parameter_bits = netlist
            .params
            .all_params()
            .into_iter()
            .map(|(name, value)| (name.to_ascii_lowercase(), value.to_bits()))
            .collect::<BTreeMap<_, _>>();
        if parsed_parameter_bits != parameter_bits {
            return Err(format!(
                "{LABEL} parsed parameters differ from the direct source qualification"
            ));
        }

        let mut elements = BTreeMap::new();
        for element in &netlist.elements {
            let key = Self::normalize_device_instance_name(&element.name);
            if key.is_empty() || elements.contains_key(&key) {
                return Err(format!(
                    "{LABEL} contains an empty or duplicate element name"
                ));
            }
            let nodes = element
                .nodes
                .iter()
                .map(|node| node.trim().to_ascii_lowercase())
                .collect::<Vec<_>>();
            if nodes.len() != 2
                || nodes.iter().any(String::is_empty)
                || nodes
                    .iter()
                    .any(|node| crate::compat::ground::is_spice_ground_name(node) && node != "0")
            {
                return Err(format!(
                    "{LABEL} element '{}' must have two explicit nodes and literal ground",
                    element.name
                ));
            }
            let fingerprint = match &element.kind {
                ElementKind::Resistor {
                    value,
                    value_expr,
                    model,
                    instance_params,
                    deferred_params,
                } if value.is_finite()
                    && *value > 0.0
                    && value_expr.is_none()
                    && model.is_none()
                    && instance_params.is_empty()
                    && deferred_params.is_empty() =>
                {
                    XyceRelationalElementFingerprint {
                        kind: "R".to_string(),
                        nodes,
                        numeric_bits: vec![value.to_bits()],
                        text: Vec::new(),
                    }
                }
                ElementKind::Capacitor {
                    value,
                    value_expr,
                    initial_voltage,
                    model,
                    instance_params,
                    deferred_params,
                } if value.is_finite()
                    && *value > 0.0
                    && value_expr.is_none()
                    && initial_voltage.is_none_or(Value::is_finite)
                    && model.is_none()
                    && instance_params.is_empty()
                    && deferred_params.is_empty() =>
                {
                    let mut numeric_bits = vec![value.to_bits()];
                    let marker = if let Some(initial) = initial_voltage {
                        numeric_bits.push(initial.to_bits());
                        "IC"
                    } else {
                        "NO_IC"
                    };
                    XyceRelationalElementFingerprint {
                        kind: "C".to_string(),
                        nodes,
                        numeric_bits,
                        text: vec![marker.to_string()],
                    }
                }
                ElementKind::VoltageSource(spec) | ElementKind::CurrentSource(spec) => {
                    Self::transient_analysis_source_fingerprint(element, spec, nodes)?
                }
                _ => {
                    return Err(format!(
                        "{LABEL} contains unqualified element '{}'",
                        element.name
                    ));
                }
            };
            elements.insert(key, fingerprint);
        }
        if elements.is_empty() {
            return Err(format!("{LABEL} requires at least one qualified element"));
        }

        let option_directives = Self::logical_netlist_lines(source)
            .into_iter()
            .map(|line| Self::strip_netlist_comment(&line).trim().to_string())
            .filter(|line| {
                line.split_whitespace()
                    .next()
                    .is_some_and(|command| command.eq_ignore_ascii_case(".options"))
            })
            .map(|line| {
                line.split_whitespace()
                    .map(str::to_ascii_lowercase)
                    .collect::<Vec<_>>()
                    .join(" ")
            })
            .collect();
        let mut nonrepresentation_source = Vec::new();
        for line in Self::logical_netlist_lines(source).into_iter().skip(1) {
            let stripped = Self::strip_netlist_comment(&line).trim();
            let Some(command) = stripped.split_whitespace().next() else {
                continue;
            };
            if command.eq_ignore_ascii_case(".param") {
                continue;
            }
            if command.eq_ignore_ascii_case(".tran") {
                let arity = Self::split_grouped_whitespace_fields(
                    stripped,
                    "transient-analysis .TRAN source signature",
                )?
                .len()
                .saturating_sub(1);
                nonrepresentation_source.push(format!(".tran$arity={arity}"));
                continue;
            }
            nonrepresentation_source.push(
                Self::split_grouped_whitespace_fields(
                    stripped,
                    "transient-analysis source signature",
                )?
                .into_iter()
                .map(|field| field.to_ascii_lowercase())
                .collect::<Vec<_>>()
                .join(" "),
            );
        }

        Ok(XyceTransientAnalysisExpressionSnapshot {
            title: netlist.title.trim().to_string(),
            representation,
            elements,
            option_directives,
            parameter_bits,
            nonrepresentation_source,
        })
    }

    fn transient_analysis_source_fingerprint(
        element: &crate::netlist::Element,
        spec: &crate::netlist::SourceSpec,
        nodes: Vec<String>,
    ) -> Result<XyceRelationalElementFingerprint, String> {
        let (waveform, numeric_bits) = match spec {
            crate::netlist::SourceSpec::Dc(value) if value.is_finite() => {
                ("DC", vec![value.to_bits()])
            }
            crate::netlist::SourceSpec::Pulse {
                v1,
                v2,
                delay,
                rise,
                fall,
                width,
                period,
                phase,
                width_defaults_to_zero,
            } if [*v1, *v2, *delay, *rise, *fall, *width, *period, *phase]
                .into_iter()
                .all(Value::is_finite)
                && *delay >= 0.0
                && *rise >= 0.0
                && *fall >= 0.0
                && *width >= 0.0
                && *period > 0.0 =>
            {
                (
                    "PULSE",
                    vec![
                        v1.to_bits(),
                        v2.to_bits(),
                        delay.to_bits(),
                        rise.to_bits(),
                        fall.to_bits(),
                        width.to_bits(),
                        period.to_bits(),
                        phase.to_bits(),
                        u64::from(*width_defaults_to_zero),
                    ],
                )
            }
            crate::netlist::SourceSpec::Sin {
                offset,
                amplitude,
                frequency,
                delay,
                damping,
                phase,
            } if [*offset, *amplitude, *frequency, *delay, *damping, *phase]
                .into_iter()
                .all(Value::is_finite)
                && *frequency > 0.0
                && *delay >= 0.0 =>
            {
                (
                    "SIN",
                    vec![
                        offset.to_bits(),
                        amplitude.to_bits(),
                        frequency.to_bits(),
                        delay.to_bits(),
                        damping.to_bits(),
                        phase.to_bits(),
                    ],
                )
            }
            _ => {
                return Err(format!(
                    "transient-analysis expression source '{}' must be a finite direct DC, PULSE, or SIN source",
                    element.name
                ));
            }
        };
        let prefix = if matches!(&element.kind, ElementKind::VoltageSource(_)) {
            "V"
        } else {
            "I"
        };
        Ok(XyceRelationalElementFingerprint {
            kind: format!("{prefix}:{waveform}"),
            nodes,
            numeric_bits,
            text: Vec::new(),
        })
    }

    fn compare_transient_analysis_expression_snapshots(
        baseline: &XyceTransientAnalysisExpressionSnapshot,
        target: &XyceTransientAnalysisExpressionSnapshot,
    ) -> Result<(), String> {
        if baseline.representation != XyceTransientAnalysisRepresentation::DirectNumeric
            || target.representation != XyceTransientAnalysisRepresentation::ParameterExpression
            || !baseline.parameter_bits.is_empty()
            || target.parameter_bits.is_empty()
        {
            return Err(
                "family must compare a parameter-free numeric .TRAN baseline with a scalar parameter-expression .TRAN target"
                    .to_string(),
            );
        }
        if baseline.title != target.title
            || baseline.elements != target.elements
            || baseline.option_directives != target.option_directives
            || baseline.nonrepresentation_source != target.nonrepresentation_source
        {
            return Err(
                "circuit title, element identity/topology/state, source waveforms, or options differ"
                    .to_string(),
            );
        }
        Ok(())
    }

    fn compare_strict_transient_family_snapshots(
        baseline: &XyceStrictTransientFamilySnapshot,
        target: &XyceStrictTransientFamilySnapshot,
    ) -> Result<(), String> {
        match (baseline, target) {
            (
                XyceStrictTransientFamilySnapshot::ScopedModel(baseline),
                XyceStrictTransientFamilySnapshot::ScopedModel(target),
            ) if baseline == target => Ok(()),
            (
                XyceStrictTransientFamilySnapshot::ScopedModel(_),
                XyceStrictTransientFamilySnapshot::ScopedModel(_),
            ) => {
                Err("flattened elements or effective nonlinear model parameters differ".to_string())
            }
            (
                XyceStrictTransientFamilySnapshot::SinExpression(baseline),
                XyceStrictTransientFamilySnapshot::SinExpression(target),
            ) => Self::compare_sin_expression_family_snapshots(baseline, target),
            (
                XyceStrictTransientFamilySnapshot::ParamExpression(baseline),
                XyceStrictTransientFamilySnapshot::ParamExpression(target),
            ) => Self::compare_param_expression_family_snapshots(baseline, target),
            (
                XyceStrictTransientFamilySnapshot::PassivePrimaryValue(baseline),
                XyceStrictTransientFamilySnapshot::PassivePrimaryValue(target),
            ) => Self::compare_passive_primary_snapshots(baseline, target),
            (
                XyceStrictTransientFamilySnapshot::PassiveTemperatureOverride(baseline),
                XyceStrictTransientFamilySnapshot::PassiveTemperatureOverride(target),
            ) => Self::compare_passive_temperature_override_snapshots(baseline, target),
            (
                XyceStrictTransientFamilySnapshot::TransientAnalysisExpression(baseline),
                XyceStrictTransientFamilySnapshot::TransientAnalysisExpression(target),
            ) => Self::compare_transient_analysis_expression_snapshots(baseline, target),
            _ => Err("baseline and target use different strict family snapshot kinds".to_string()),
        }
    }

    fn validate_sin_expression_transient_plan(plan: &XyceStaticTranPlan) -> Result<(), String> {
        if plan.contract != XyceStaticTranContract::PlainStatic {
            return Err(format!(
                "exact SIN/SPICE_SIN parity requires ordinary primary .prn output, got {:?}",
                plan.contract
            ));
        }
        if !plan.steps.is_empty() {
            return Err("exact SIN/SPICE_SIN parity does not admit .STEP".to_string());
        }
        if plan.output_override {
            return Err("exact SIN/SPICE_SIN parity does not admit an output override".to_string());
        }
        if plan.timeint_conststep {
            return Err(
                "exact SIN/SPICE_SIN parity requires ordinary adaptive transient output"
                    .to_string(),
            );
        }
        if !plan.tran.step.is_finite()
            || !plan.tran.stop.is_finite()
            || plan.tran.step <= 0.0
            || plan.tran.stop <= 0.0
            || plan.tran.step > plan.tran.stop
            || plan.tran.start.is_some()
            || plan.tran.max_step.is_some()
            || plan.tran.uic
        {
            return Err(format!(
                "exact SIN/SPICE_SIN parity requires finite '.TRAN step stop' values with 0 < step <= stop and no START, MAXSTEP, or UIC; got step={}, stop={}, start={:?}, max_step={:?}, uic={}",
                plan.tran.step, plan.tran.stop, plan.tran.start, plan.tran.max_step, plan.tran.uic
            ));
        }
        let [probe] = plan.print.probes.as_slice() else {
            return Err(format!(
                "exact SIN/SPICE_SIN parity requires exactly one voltage probe, found {}",
                plan.print.probes.len()
            ));
        };
        let voltage_probe = Self::parse_voltage_probe(probe).ok_or_else(|| {
            format!("exact SIN/SPICE_SIN probe '{probe}' is not an atomic voltage probe")
        })?;
        if voltage_probe.accessor != XyceVoltageAccessor::Value || voltage_probe.node_neg.is_some()
        {
            return Err(format!(
                "exact SIN/SPICE_SIN probe '{probe}' must be one ordinary single-ended voltage"
            ));
        }

        let mut tran_count = 0usize;
        let mut print_count = 0usize;
        let mut end_count = 0usize;
        for line in Self::logical_netlist_lines(&plan.source) {
            let stripped = Self::strip_netlist_comment(&line).trim();
            let Some(command) = stripped.split_whitespace().next() else {
                continue;
            };
            if !command.starts_with('.') {
                continue;
            }
            match command.to_ascii_lowercase().as_str() {
                ".tran" => {
                    tran_count += 1;
                    if stripped.split_whitespace().count() != 3 {
                        return Err(
                            "exact SIN/SPICE_SIN parity requires the canonical '.TRAN step stop' form"
                                .to_string(),
                        );
                    }
                }
                ".print" => {
                    print_count += 1;
                    let fields = Self::split_print_fields(stripped)?;
                    if fields.len() != 3
                        || !fields[1].eq_ignore_ascii_case("TRAN")
                        || Self::normalize_probe(&fields[2]) != Self::normalize_probe(probe)
                    {
                        return Err(
                            "exact SIN/SPICE_SIN parity requires one canonical '.PRINT TRAN <voltage>' statement without destination or formatting assignments"
                                .to_string(),
                        );
                    }
                }
                ".end" => {
                    end_count += 1;
                    if !stripped.eq_ignore_ascii_case(".end") {
                        return Err(
                            "exact SIN/SPICE_SIN parity requires an ordinary '.END' statement"
                                .to_string(),
                        );
                    }
                }
                other => {
                    return Err(format!(
                        "exact SIN/SPICE_SIN parity does not admit directive '{other}'"
                    ));
                }
            }
        }
        if (tran_count, print_count, end_count) != (1, 1, 1) {
            return Err(format!(
                "exact SIN/SPICE_SIN parity requires exactly one .TRAN, .PRINT, and .END; found ({tran_count}, {print_count}, {end_count})"
            ));
        }
        Ok(())
    }

    fn validate_param_expression_direct_source_forms(source: &str) -> Result<(), String> {
        const LABEL: &str = "parameter-expression parity";
        let lines = Self::logical_netlist_lines(source);
        let Some(title) = source.lines().find(|line| !line.trim().is_empty()) else {
            return Err(format!("{LABEL} requires a circuit title"));
        };
        let title = title
            .split_once(';')
            .map(|(head, _)| head)
            .unwrap_or(title)
            .trim();
        if title.is_empty() || title.starts_with('.') {
            return Err(format!("{LABEL} requires an ordinary circuit title"));
        }
        let logical_title_count = usize::from(
            !Self::strip_netlist_comment(title).trim().is_empty()
                && lines.first().is_some_and(|line| line.trim() == title),
        );

        let mut behavioral_count = 0usize;
        let mut resistor_count = 0usize;
        let mut voltage_count = 0usize;
        let mut instance_count = 0usize;
        for line in lines.iter().skip(logical_title_count) {
            let stripped = Self::strip_netlist_comment(line).trim();
            let Some(command) = stripped.split_whitespace().next() else {
                continue;
            };
            if command.starts_with('.') {
                if command.eq_ignore_ascii_case(".TRAN") {
                    let fields = Self::split_grouped_whitespace_fields(
                        stripped,
                        "parameter-expression .TRAN statement",
                    )?;
                    if fields.len() != 3
                        || !Self::is_single_spice_numeric_literal(&fields[1])
                        || !Self::is_single_spice_numeric_literal(&fields[2])
                    {
                        return Err(format!(
                            "{LABEL} requires direct numeric '.TRAN step stop' tokens"
                        ));
                    }
                }
                continue;
            }

            let fields = Self::split_grouped_whitespace_fields(
                stripped,
                "parameter-expression element statement",
            )?;
            let Some(designator) = fields[0].chars().next().map(|ch| ch.to_ascii_uppercase())
            else {
                return Err(format!("{LABEL} contains an empty element name"));
            };
            match designator {
                'B' => {
                    behavioral_count += 1;
                    if fields.len() != 4 || !Self::is_single_braced_voltage_assignment(&fields[3]) {
                        return Err(format!(
                            "{LABEL} behavioral source must use exactly 'Bname n+ n- V={{expression}}'"
                        ));
                    }
                }
                'R' => {
                    resistor_count += 1;
                    if fields.len() != 4 || !Self::is_single_spice_numeric_literal(&fields[3]) {
                        return Err(format!(
                            "{LABEL} resistors must use direct numeric 'Rname n+ n- value' form"
                        ));
                    }
                }
                'V' => {
                    voltage_count += 1;
                    if fields.len() != 4 || !Self::is_single_spice_numeric_literal(&fields[3]) {
                        return Err(format!(
                            "{LABEL} voltage source must use direct numeric 'Vname n+ n- value' form"
                        ));
                    }
                }
                'X' => {
                    instance_count += 1;
                    if fields.len() != 8 {
                        return Err(format!(
                            "{LABEL} subcircuit instance must bind exactly six nodes without parameter fields"
                        ));
                    }
                }
                _ => {
                    return Err(format!(
                        "{LABEL} does not admit element statement '{command}'"
                    ));
                }
            }
        }
        if (
            behavioral_count,
            resistor_count,
            voltage_count,
            instance_count,
        ) != (1, 2, 1, 1)
        {
            return Err(format!(
                "{LABEL} requires exactly one behavioral source, two resistors, one direct DC source, and one subcircuit instance; found ({behavioral_count}, {resistor_count}, {voltage_count}, {instance_count})"
            ));
        }
        Ok(())
    }

    fn validate_param_expression_transient_plan(plan: &XyceStaticTranPlan) -> Result<(), String> {
        const LABEL: &str = "parameter-expression parity";
        if plan.contract != XyceStaticTranContract::PlainStatic {
            return Err(format!(
                "{LABEL} requires ordinary primary .prn output, got {:?}",
                plan.contract
            ));
        }
        if !plan.steps.is_empty() {
            return Err(format!("{LABEL} does not admit .STEP"));
        }
        if plan.output_override {
            return Err(format!("{LABEL} does not admit an output override"));
        }
        if plan.timeint_conststep {
            return Err(format!(
                "{LABEL} requires ordinary adaptive transient output"
            ));
        }
        if !plan.tran.step.is_finite()
            || !plan.tran.stop.is_finite()
            || plan.tran.step <= 0.0
            || plan.tran.stop <= 0.0
            || plan.tran.step > plan.tran.stop
            || plan.tran.start.is_some()
            || plan.tran.max_step.is_some()
            || plan.tran.uic
        {
            return Err(format!(
                "{LABEL} requires finite '.TRAN step stop' values with 0 < step <= stop and no START, MAXSTEP, or UIC; got step={}, stop={}, start={:?}, max_step={:?}, uic={}",
                plan.tran.step, plan.tran.stop, plan.tran.start, plan.tran.max_step, plan.tran.uic
            ));
        }
        let [probe] = plan.print.probes.as_slice() else {
            return Err(format!(
                "{LABEL} requires exactly one voltage probe, found {}",
                plan.print.probes.len()
            ));
        };
        let voltage_probe = Self::parse_voltage_probe(probe)
            .ok_or_else(|| format!("{LABEL} probe '{probe}' is not an atomic voltage probe"))?;
        if voltage_probe.accessor != XyceVoltageAccessor::Value || voltage_probe.node_neg.is_some()
        {
            return Err(format!(
                "{LABEL} probe '{probe}' must be one ordinary single-ended voltage"
            ));
        }
        Self::validate_param_expression_direct_source_forms(&plan.source)?;

        if plan.source.lines().any(|line| {
            line.split_whitespace()
                .next()
                .is_some_and(|field| field.eq_ignore_ascii_case("*COMP"))
        }) {
            return Err(format!(
                "{LABEL} uses the unmodified xyce_verify default tolerances and does not admit *COMP directives"
            ));
        }

        let mut param_count = 0usize;
        let mut subckt_count = 0usize;
        let mut ends_count = 0usize;
        let mut print_count = 0usize;
        let mut tran_count = 0usize;
        let mut end_count = 0usize;
        for line in Self::logical_netlist_lines(&plan.source) {
            let stripped = Self::strip_netlist_comment(&line).trim();
            let Some(command) = stripped.split_whitespace().next() else {
                continue;
            };
            if !command.starts_with('.') {
                continue;
            }
            match command.to_ascii_lowercase().as_str() {
                ".param" => {
                    param_count += 1;
                    let fields = Self::split_grouped_whitespace_fields(
                        stripped,
                        "parameter-expression .PARAM statement",
                    )?;
                    let [_, assignment] = fields.as_slice() else {
                        return Err(format!(
                            "{LABEL} requires one canonical '.PARAM name=value' assignment"
                        ));
                    };
                    let Some((name, value)) = assignment.split_once('=') else {
                        return Err(format!(
                            "{LABEL} requires one canonical '.PARAM name=value' assignment"
                        ));
                    };
                    if name.trim().is_empty()
                        || value.trim().is_empty()
                        || value.contains('=')
                        || !Self::is_single_spice_numeric_literal(value)
                    {
                        return Err(format!(
                            "{LABEL} requires one direct finite numeric .PARAM value"
                        ));
                    }
                }
                ".subckt" => {
                    subckt_count += 1;
                    let fields = Self::split_grouped_whitespace_fields(
                        stripped,
                        "parameter-expression .SUBCKT statement",
                    )?;
                    if fields.len() != 8 {
                        return Err(format!(
                            "{LABEL} requires '.SUBCKT name' followed by exactly six ports and no defaults"
                        ));
                    }
                }
                ".ends" => {
                    ends_count += 1;
                    if !stripped.eq_ignore_ascii_case(".ends") {
                        return Err(format!("{LABEL} requires a bare '.ENDS' statement"));
                    }
                }
                ".print" => {
                    print_count += 1;
                    let fields = Self::split_print_fields(stripped)?;
                    if fields.len() != 3
                        || !fields[1].eq_ignore_ascii_case("TRAN")
                        || Self::normalize_probe(&fields[2]) != Self::normalize_probe(probe)
                    {
                        return Err(format!(
                            "{LABEL} requires one canonical '.PRINT TRAN <voltage>' statement without destination or formatting assignments"
                        ));
                    }
                }
                ".tran" => {
                    tran_count += 1;
                    if stripped.split_whitespace().count() != 3 {
                        return Err(format!(
                            "{LABEL} requires the canonical '.TRAN step stop' form"
                        ));
                    }
                }
                ".end" => {
                    end_count += 1;
                    if !stripped.eq_ignore_ascii_case(".end") {
                        return Err(format!("{LABEL} requires an ordinary '.END' statement"));
                    }
                }
                other => {
                    return Err(format!("{LABEL} does not admit directive '{other}'"));
                }
            }
        }
        if (
            param_count,
            subckt_count,
            ends_count,
            print_count,
            tran_count,
            end_count,
        ) != (1, 1, 1, 1, 1, 1)
        {
            return Err(format!(
                "{LABEL} requires exactly one .PARAM, .SUBCKT, .ENDS, .PRINT, .TRAN, and .END; found ({param_count}, {subckt_count}, {ends_count}, {print_count}, {tran_count}, {end_count})"
            ));
        }
        Ok(())
    }

    fn param_expression_name_is_literal_ground(node: &str) -> bool {
        node.trim() == "0"
    }

    fn canonical_param_expression_node_name(node: &str) -> String {
        if Self::param_expression_name_is_literal_ground(node) {
            "0".to_string()
        } else {
            node.trim().to_ascii_lowercase()
        }
    }

    fn raw_param_expression_voltage_node(expression: &crate::netlist::expr::Expr) -> Option<&str> {
        let crate::netlist::expr::Expr::FnCall { name, args } = expression else {
            return None;
        };
        let [crate::netlist::expr::Expr::Param(node)] = args.as_slice() else {
            return None;
        };
        name.eq_ignore_ascii_case("V").then_some(node.as_str())
    }

    fn raw_param_expression_squared_voltage_difference_matches(
        expression: &crate::netlist::expr::Expr,
        positive_node: &str,
        negative_node: &str,
    ) -> bool {
        use crate::netlist::expr::{BinOpKind, Expr as NetExpr};
        let NetExpr::BinOp {
            op: BinOpKind::Pow,
            left,
            right,
        } = expression
        else {
            return false;
        };
        let NetExpr::Number(exponent) = right.as_ref() else {
            return false;
        };
        let NetExpr::BinOp {
            op: BinOpKind::Sub,
            left,
            right,
        } = left.as_ref()
        else {
            return false;
        };
        exponent.to_bits() == 2.0f64.to_bits()
            && Self::raw_param_expression_voltage_node(left)
                .is_some_and(|node| node.eq_ignore_ascii_case(positive_node))
            && Self::raw_param_expression_voltage_node(right)
                .is_some_and(|node| node.eq_ignore_ascii_case(negative_node))
    }

    fn qualify_raw_param_expression(
        expression: &str,
        parameter_name: &str,
        parameter_value: Value,
        ports: &[String],
    ) -> Result<XyceParamExpressionRepresentation, String> {
        use crate::netlist::expr::{BinOpKind, Expr as NetExpr};
        let ast = crate::netlist::expr::parse_expression(expression)
            .map_err(|err| format!("could not parse the behavioral expression: {err}"))?;
        let NetExpr::BinOp {
            op: BinOpKind::Mul,
            left: coefficient,
            right: magnitude,
        } = ast
        else {
            return Err(
                "behavioral expression must directly multiply its coefficient by sqrt(...)"
                    .to_string(),
            );
        };
        let representation = match coefficient.as_ref() {
            NetExpr::Param(name) if name.eq_ignore_ascii_case(parameter_name) => {
                XyceParamExpressionRepresentation::ParameterCoefficient
            }
            NetExpr::Number(value) if value.to_bits() == parameter_value.to_bits() => {
                XyceParamExpressionRepresentation::LiteralCoefficient
            }
            NetExpr::Param(_) => {
                return Err(
                    "behavioral coefficient must reference the unique global parameter directly"
                        .to_string(),
                );
            }
            NetExpr::Number(value) => {
                return Err(format!(
                    "literal behavioral coefficient {value} does not exactly equal the global parameter value {parameter_value}"
                ));
            }
            _ => {
                return Err(
                    "behavioral coefficient must be one direct parameter reference or numeric literal"
                        .to_string(),
                );
            }
        };
        let NetExpr::FnCall { name, args } = magnitude.as_ref() else {
            return Err("behavioral magnitude must be one direct sqrt(...) call".to_string());
        };
        if !name.eq_ignore_ascii_case("sqrt") {
            return Err("behavioral magnitude function must be sqrt".to_string());
        }
        let [
            NetExpr::BinOp {
                op: BinOpKind::Add,
                left: first,
                right: second,
            },
        ] = args.as_slice()
        else {
            return Err(
                "sqrt must contain one direct sum of two squared voltage differences".to_string(),
            );
        };
        if ports.len() != 6
            || !Self::raw_param_expression_squared_voltage_difference_matches(
                first, &ports[2], &ports[3],
            )
            || !Self::raw_param_expression_squared_voltage_difference_matches(
                second, &ports[4], &ports[5],
            )
        {
            return Err(
                "behavioral expression must preserve the ordered squared voltage differences for subcircuit ports 2/3 and 4/5"
                    .to_string(),
            );
        }
        Ok(representation)
    }

    fn strict_param_expression_voltage_node_matches(expression: &Expr, expected: &str) -> bool {
        matches!(
            expression,
            Expr::NodeVoltage(node)
                if Self::canonical_param_expression_node_name(node) == expected
        )
    }

    fn strict_param_expression_squared_voltage_difference_matches(
        expression: &Expr,
        positive_node: &str,
        negative_node: &str,
    ) -> bool {
        let Expr::Binary {
            op: crate::expr::BinaryOp::Pow,
            left,
            right,
        } = expression
        else {
            return false;
        };
        let Expr::Const(exponent) = right.as_ref() else {
            return false;
        };
        let Expr::Binary {
            op: crate::expr::BinaryOp::Sub,
            left,
            right,
        } = left.as_ref()
        else {
            return false;
        };
        exponent.to_bits() == 2.0f64.to_bits()
            && Self::strict_param_expression_voltage_node_matches(left, positive_node)
            && Self::strict_param_expression_voltage_node_matches(right, negative_node)
    }

    fn qualify_prepared_param_expression(
        expression: &str,
        params: &crate::netlist::expr::ParamContext,
        coefficient: Value,
        first_positive: &str,
        first_negative: &str,
        second_positive: &str,
        second_negative: &str,
    ) -> Result<(), String> {
        let prepared = prepare_behavioral_expression(expression, params)
            .map_err(|err| format!("could not prepare the flattened expression: {err}"))?;
        let ast = parse_expression_strict(&prepared)
            .map_err(|err| format!("could not parse the prepared flattened expression: {err}"))?;
        let Expr::Binary {
            op: crate::expr::BinaryOp::Mul,
            left,
            right,
        } = ast
        else {
            return Err(
                "prepared expression must directly multiply a constant by sqrt(...)".to_string(),
            );
        };
        let Expr::Const(prepared_coefficient) = left.as_ref() else {
            return Err("prepared behavioral coefficient must be constant".to_string());
        };
        if prepared_coefficient.to_bits() != coefficient.to_bits() {
            return Err(format!(
                "prepared behavioral coefficient {prepared_coefficient} does not exactly equal {coefficient}"
            ));
        }
        let Expr::Function {
            func: crate::expr::Function::Sqrt,
            args,
        } = right.as_ref()
        else {
            return Err("prepared behavioral magnitude must be sqrt".to_string());
        };
        let [
            Expr::Binary {
                op: crate::expr::BinaryOp::Add,
                left: first,
                right: second,
            },
        ] = args.as_slice()
        else {
            return Err(
                "prepared sqrt must contain one direct sum of squared voltage differences"
                    .to_string(),
            );
        };
        if !Self::strict_param_expression_squared_voltage_difference_matches(
            first,
            first_positive,
            first_negative,
        ) || !Self::strict_param_expression_squared_voltage_difference_matches(
            second,
            second_positive,
            second_negative,
        ) {
            return Err(
                "prepared expression changed the ordered squared voltage-difference topology"
                    .to_string(),
            );
        }
        Ok(())
    }

    fn sin_expression_name_is_literal_ground(node: &str) -> bool {
        node.trim() == "0"
    }

    fn canonical_sin_expression_node_name(node: &str) -> String {
        if Self::sin_expression_name_is_literal_ground(node) {
            "0".to_string()
        } else {
            node.trim().to_ascii_lowercase()
        }
    }

    fn qualified_sin_expression_waveform_bits(
        offset: Value,
        amplitude: Value,
        frequency: Value,
    ) -> Result<[u64; 6], String> {
        if !offset.is_finite()
            || !amplitude.is_finite()
            || amplitude == 0.0
            || !frequency.is_finite()
            || frequency <= 0.0
        {
            return Err(format!(
                "qualified SIN/SPICE_SIN values require finite offset, finite nonzero amplitude, and finite positive frequency; got offset={offset}, amplitude={amplitude}, frequency={frequency}"
            ));
        }
        Ok([
            offset.to_bits(),
            amplitude.to_bits(),
            frequency.to_bits(),
            0.0f64.to_bits(),
            0.0f64.to_bits(),
            0.0f64.to_bits(),
        ])
    }

    fn validate_sin_expression_source_form(
        netlist: &Netlist,
        source_name: &str,
        representation: XyceSinExpressionRepresentation,
    ) -> Result<(), String> {
        let source = netlist.source_text.as_deref().ok_or_else(|| {
            "exact SIN/SPICE_SIN parity requires original source text for arity qualification"
                .to_string()
        })?;
        let mut matching_lines = Vec::new();
        for line in Self::logical_netlist_lines(source) {
            let stripped = Self::strip_netlist_comment(&line).trim();
            if stripped
                .split_whitespace()
                .next()
                .is_some_and(|name| name.eq_ignore_ascii_case(source_name))
            {
                matching_lines.push(stripped.to_string());
            }
        }
        let [source_line] = matching_lines.as_slice() else {
            return Err(format!(
                "exact SIN/SPICE_SIN parity requires exactly one source line for '{source_name}', found {}",
                matching_lines.len()
            ));
        };
        let fields = Self::split_grouped_whitespace_fields(
            source_line,
            "exact SIN/SPICE_SIN source statement",
        )?;
        match representation {
            XyceSinExpressionRepresentation::IndependentSin => {
                if fields.len() != 7
                    || !fields[3].eq_ignore_ascii_case("SIN")
                    || !fields[4..]
                        .iter()
                        .all(|field| Self::is_single_spice_numeric_literal(field))
                {
                    return Err(format!(
                        "independent source '{source_name}' must use exactly three standalone numeric tokens in 'SIN offset amplitude frequency' form"
                    ));
                }
            }
            XyceSinExpressionRepresentation::BehavioralSpiceSin => {
                if fields.len() != 4 || !Self::is_single_braced_voltage_assignment(&fields[3]) {
                    return Err(format!(
                        "behavioral source '{source_name}' must use one complete braced V={{SPICE_SIN(...)}} assignment without adjacent or trailing fields"
                    ));
                }
            }
        }
        Ok(())
    }

    fn is_single_spice_numeric_literal(field: &str) -> bool {
        let Ok(tokens) = crate::netlist::lexer::tokenize(field) else {
            return false;
        };
        if !crate::netlist::lexer::parse_spice_value(field.trim()).is_ok_and(Value::is_finite) {
            return false;
        }
        let kinds = tokens.iter().map(|token| &token.kind).collect::<Vec<_>>();
        matches!(
            kinds.as_slice(),
            [
                crate::netlist::lexer::TokenKind::Number(_)
                    | crate::netlist::lexer::TokenKind::Ident(_),
                crate::netlist::lexer::TokenKind::Eof
            ] | [
                crate::netlist::lexer::TokenKind::Plus | crate::netlist::lexer::TokenKind::Minus,
                crate::netlist::lexer::TokenKind::Number(_)
                    | crate::netlist::lexer::TokenKind::Ident(_),
                crate::netlist::lexer::TokenKind::Eof
            ]
        )
    }

    fn is_single_braced_voltage_assignment(field: &str) -> bool {
        let Some((key, expression)) = field.split_once('=') else {
            return false;
        };
        if !key.trim().eq_ignore_ascii_case("V") {
            return false;
        }
        let expression = expression.trim();
        let chars = expression.chars().collect::<Vec<_>>();
        if chars.first() != Some(&'{') || chars.last() != Some(&'}') {
            return false;
        }

        let mut depth = 0usize;
        for (index, ch) in chars.iter().enumerate() {
            match ch {
                '{' => depth += 1,
                '}' => {
                    let Some(next_depth) = depth.checked_sub(1) else {
                        return false;
                    };
                    depth = next_depth;
                    if depth == 0 && index + 1 != chars.len() {
                        return false;
                    }
                }
                _ => {}
            }
        }
        depth == 0
    }

    fn sin_expression_family_snapshot(
        netlist: &Netlist,
        print: &XycePrintRequest,
    ) -> Result<XyceSinExpressionFamilySnapshot, String> {
        if !netlist.models.is_empty()
            || !netlist.data_tables.is_empty()
            || !netlist.subcircuits.is_empty()
            || !netlist.initial_conditions.is_empty()
            || !netlist.node_sets.is_empty()
            || !netlist.global_nodes.is_empty()
            || !netlist.measurements.is_empty()
            || !netlist.veriloga_includes.is_empty()
            || !netlist.spef_includes.is_empty()
        {
            return Err(
                "exact SIN/SPICE_SIN parity contains models, hierarchy, auxiliary analysis state, or external-model state"
                    .to_string(),
            );
        }
        if !netlist.params.all_params().is_empty()
            || !netlist.params.all_string_params().is_empty()
            || !netlist.params.all_functions().is_empty()
        {
            return Err(
                "exact SIN/SPICE_SIN parity does not admit parameters or user functions"
                    .to_string(),
            );
        }
        if !netlist.diagnostics.is_empty() {
            return Err(format!(
                "exact SIN/SPICE_SIN parity requires a diagnostic-free parse, found {} diagnostic(s)",
                netlist.diagnostics.len()
            ));
        }
        if !matches!(netlist.analyses.as_slice(), [AnalysisCommand::Tran { .. }]) {
            return Err(format!(
                "exact SIN/SPICE_SIN parity requires exactly one transient analysis, found {} analysis command(s)",
                netlist.analyses.len()
            ));
        }
        if netlist.elements.len() != 2 {
            return Err(format!(
                "exact SIN/SPICE_SIN parity requires exactly one excitation and one resistor, found {} elements",
                netlist.elements.len()
            ));
        }

        let mut resistor = None;
        let mut source = None;
        for element in &netlist.elements {
            if let Some(alias) = element.nodes.iter().find(|node| {
                crate::compat::ground::is_spice_ground_name(node)
                    && !Self::sin_expression_name_is_literal_ground(node)
            }) {
                return Err(format!(
                    "element '{}' uses ground alias '{}'; exact Xyce parity requires literal node 0 without .PREPROCESS REPLACEGND",
                    element.name, alias
                ));
            }
            let nodes = element
                .nodes
                .iter()
                .map(|node| Self::canonical_sin_expression_node_name(node))
                .collect::<Vec<_>>();
            match &element.kind {
                ElementKind::Resistor {
                    value,
                    value_expr,
                    model,
                    instance_params,
                    deferred_params,
                } => {
                    if resistor.is_some() {
                        return Err(
                            "exact SIN/SPICE_SIN parity requires exactly one resistor".to_string()
                        );
                    }
                    if nodes.len() != 2
                        || !value.is_finite()
                        || *value <= 0.0
                        || value_expr.is_some()
                        || model.is_some()
                        || !instance_params.is_empty()
                        || !deferred_params.is_empty()
                    {
                        return Err(format!(
                            "resistor '{}' is outside the finite positive numeric two-terminal envelope",
                            element.name
                        ));
                    }
                    resistor = Some((
                        Self::normalize_device_instance_name(&element.name),
                        XyceRelationalElementFingerprint {
                            kind: "R".to_string(),
                            nodes,
                            numeric_bits: vec![value.to_bits()],
                            text: Vec::new(),
                        },
                    ));
                }
                ElementKind::VoltageSource(crate::netlist::SourceSpec::Sin {
                    offset,
                    amplitude,
                    frequency,
                    delay,
                    damping,
                    phase,
                }) => {
                    if source.is_some() {
                        return Err("exact SIN/SPICE_SIN parity requires exactly one excitation"
                            .to_string());
                    }
                    if nodes.len() != 2
                        || delay.to_bits() != 0.0f64.to_bits()
                        || damping.to_bits() != 0.0f64.to_bits()
                        || phase.to_bits() != 0.0f64.to_bits()
                    {
                        return Err(format!(
                            "independent source '{}' must be a two-terminal three-argument SIN with exact +0 delay, damping, and phase",
                            element.name
                        ));
                    }
                    let waveform_bits = Self::qualified_sin_expression_waveform_bits(
                        *offset, *amplitude, *frequency,
                    )?;
                    source = Some((
                        element.name.clone(),
                        nodes,
                        waveform_bits,
                        XyceSinExpressionRepresentation::IndependentSin,
                    ));
                }
                ElementKind::BehavioralVoltage {
                    expression,
                    tc1,
                    tc2,
                } => {
                    if source.is_some() {
                        return Err("exact SIN/SPICE_SIN parity requires exactly one excitation"
                            .to_string());
                    }
                    if nodes.len() != 2
                        || tc1.to_bits() != 0.0f64.to_bits()
                        || tc2.to_bits() != 0.0f64.to_bits()
                    {
                        return Err(format!(
                            "behavioral source '{}' must be two-terminal with exact +0 TC1 and TC2",
                            element.name
                        ));
                    }
                    let prepared = prepare_behavioral_expression(expression, &netlist.params)
                        .map_err(|err| {
                            format!(
                                "could not canonicalize behavioral expression for '{}': {err}",
                                element.name
                            )
                        })?;
                    let ast = parse_expression_strict(&prepared).map_err(|err| {
                        format!(
                            "could not parse behavioral expression for '{}': {err}",
                            element.name
                        )
                    })?;
                    let Expr::Function {
                        func: crate::expr::Function::SpiceSin,
                        args,
                    } = ast
                    else {
                        return Err(format!(
                            "behavioral source '{}' is not a direct SPICE_SIN expression",
                            element.name
                        ));
                    };
                    let [
                        Expr::Const(offset),
                        Expr::Const(amplitude),
                        Expr::Const(frequency),
                    ] = args.as_slice()
                    else {
                        return Err(format!(
                            "behavioral source '{}' must use exactly three constant SPICE_SIN arguments",
                            element.name
                        ));
                    };
                    let waveform_bits = Self::qualified_sin_expression_waveform_bits(
                        *offset, *amplitude, *frequency,
                    )?;
                    source = Some((
                        element.name.clone(),
                        nodes,
                        waveform_bits,
                        XyceSinExpressionRepresentation::BehavioralSpiceSin,
                    ));
                }
                _ => {
                    return Err(format!(
                        "element '{}' is outside the resistor/SIN/SPICE_SIN envelope",
                        element.name
                    ));
                }
            }
        }

        let (resistor_name, resistor) = resistor
            .ok_or_else(|| "exact SIN/SPICE_SIN parity contains no resistor".to_string())?;
        let (source_name, source_nodes, waveform_bits, representation) = source
            .ok_or_else(|| "exact SIN/SPICE_SIN parity contains no excitation".to_string())?;
        Self::validate_sin_expression_source_form(netlist, &source_name, representation)?;
        if source_nodes[0] == "0" || source_nodes[1] != "0" {
            return Err(
                "exact SIN/SPICE_SIN excitation requires one non-ground output node and literal node 0"
                    .to_string(),
            );
        }
        if resistor.nodes != source_nodes {
            return Err(
                "exact SIN/SPICE_SIN resistor must connect across the same ordered node pair as the excitation"
                    .to_string(),
            );
        }
        let [probe] = print.probes.as_slice() else {
            return Err("exact SIN/SPICE_SIN parity requires exactly one probe".to_string());
        };
        let probe = Self::parse_voltage_probe(probe).ok_or_else(|| {
            "exact SIN/SPICE_SIN parity requires an atomic voltage probe".to_string()
        })?;
        if probe.accessor != XyceVoltageAccessor::Value
            || probe.node_neg.is_some()
            || Self::canonical_sin_expression_node_name(&probe.node_pos) != source_nodes[0]
        {
            return Err(
                "exact SIN/SPICE_SIN voltage probe must observe the excitation output node"
                    .to_string(),
            );
        }

        Ok(XyceSinExpressionFamilySnapshot {
            resistor,
            resistor_name,
            source_nodes,
            waveform_bits,
            representation,
        })
    }

    fn compare_sin_expression_family_snapshots(
        baseline: &XyceSinExpressionFamilySnapshot,
        target: &XyceSinExpressionFamilySnapshot,
    ) -> Result<(), String> {
        if baseline.representation != XyceSinExpressionRepresentation::IndependentSin
            || target.representation != XyceSinExpressionRepresentation::BehavioralSpiceSin
        {
            return Err(
                "family must compare an independent SIN baseline with a behavioral SPICE_SIN target"
                    .to_string(),
            );
        }
        if baseline.resistor_name != target.resistor_name || baseline.resistor != target.resistor {
            return Err("resistor identity, topology, or value differs".to_string());
        }
        if baseline.source_nodes != target.source_nodes {
            return Err("excitation topology differs".to_string());
        }
        if baseline.waveform_bits != target.waveform_bits {
            return Err("canonical sinusoidal waveform values differ".to_string());
        }
        Ok(())
    }

    fn param_expression_family_snapshot(
        netlist: &Netlist,
        print: &XycePrintRequest,
    ) -> Result<XyceParamExpressionFamilySnapshot, String> {
        const LABEL: &str = "parameter-expression parity";
        let source = netlist.source_text.as_deref().ok_or_else(|| {
            format!("{LABEL} requires original source text for representation qualification")
        })?;
        Self::validate_param_expression_direct_source_forms(source)?;
        if !netlist.models.is_empty()
            || !netlist.data_tables.is_empty()
            || !netlist.initial_conditions.is_empty()
            || !netlist.node_sets.is_empty()
            || !netlist.global_nodes.is_empty()
            || !netlist.measurements.is_empty()
            || !netlist.veriloga_includes.is_empty()
            || !netlist.spef_includes.is_empty()
        {
            return Err(format!(
                "{LABEL} contains models, top-level auxiliary analysis state, or external-model state"
            ));
        }
        if !netlist.params.all_string_params().is_empty()
            || !netlist.params.all_functions().is_empty()
        {
            return Err(format!(
                "{LABEL} does not admit string parameters or user functions"
            ));
        }
        let parameters = netlist.params.all_params();
        let [(parameter_name, parameter_value)] = parameters.as_slice() else {
            return Err(format!(
                "{LABEL} requires exactly one explicit numeric global parameter, found {}",
                parameters.len()
            ));
        };
        let complex_parameter = netlist
            .params
            .get_complex(parameter_name)
            .ok_or_else(|| format!("{LABEL} could not resolve its unique global parameter"))?;
        if !complex_parameter.is_real()
            || complex_parameter.re.to_bits() != parameter_value.to_bits()
            || !parameter_value.is_finite()
            || *parameter_value <= 0.0
        {
            return Err(format!(
                "{LABEL} requires one finite positive real global parameter, got {complex_parameter:?}"
            ));
        }
        if !netlist.diagnostics.is_empty() {
            return Err(format!(
                "{LABEL} requires a diagnostic-free parse, found {} diagnostic(s)",
                netlist.diagnostics.len()
            ));
        }
        if !matches!(netlist.analyses.as_slice(), [AnalysisCommand::Tran { .. }]) {
            return Err(format!(
                "{LABEL} requires exactly one transient analysis, found {} analysis command(s)",
                netlist.analyses.len()
            ));
        }
        let [subcircuit] = netlist.subcircuits.as_slice() else {
            return Err(format!(
                "{LABEL} requires exactly one subcircuit definition, found {}",
                netlist.subcircuits.len()
            ));
        };
        if !subcircuit.params.is_empty()
            || !subcircuit.expr_params.is_empty()
            || !subcircuit.string_params.is_empty()
            || !subcircuit.body_params.is_empty()
            || !subcircuit.body_expr_params.is_empty()
            || !subcircuit.body_string_params.is_empty()
            || !subcircuit.body_functions.is_empty()
            || !subcircuit.local_options.is_empty()
            || subcircuit.library_ref.is_some()
            || !subcircuit.nested_subcircuits.is_empty()
            || !subcircuit.initial_conditions.is_empty()
            || !subcircuit.node_sets.is_empty()
        {
            return Err(format!(
                "{LABEL} subcircuit must not contain defaults, body parameters/functions, local options, nested hierarchy, startup state, or a library reference"
            ));
        }
        if subcircuit.ports.len() != 6 {
            return Err(format!(
                "{LABEL} subcircuit requires exactly six ports, found {}",
                subcircuit.ports.len()
            ));
        }
        let subcircuit_ports = subcircuit
            .ports
            .iter()
            .map(|port| Self::canonical_param_expression_node_name(port))
            .collect::<Vec<_>>();
        let distinct_ports = subcircuit_ports.iter().cloned().collect::<BTreeSet<_>>();
        if distinct_ports.len() != 6
            || subcircuit.ports.iter().any(|port| {
                crate::compat::ground::is_spice_ground_name(port) || port.trim().is_empty()
            })
        {
            return Err(format!(
                "{LABEL} subcircuit ports must be six distinct non-ground names"
            ));
        }
        let [behavioral] = subcircuit.elements.as_slice() else {
            return Err(format!(
                "{LABEL} subcircuit requires exactly one behavioral voltage source, found {} elements",
                subcircuit.elements.len()
            ));
        };
        let behavioral_nodes = behavioral
            .nodes
            .iter()
            .map(|node| Self::canonical_param_expression_node_name(node))
            .collect::<Vec<_>>();
        if behavioral_nodes != subcircuit_ports[..2] {
            return Err(format!(
                "{LABEL} behavioral source must connect across subcircuit ports 0 and 1"
            ));
        }
        let representation = match &behavioral.kind {
            ElementKind::BehavioralVoltage {
                expression,
                tc1,
                tc2,
            } if tc1.to_bits() == 0.0f64.to_bits() && tc2.to_bits() == 0.0f64.to_bits() => {
                Self::qualify_raw_param_expression(
                    expression,
                    parameter_name,
                    *parameter_value,
                    &subcircuit.ports,
                )?
            }
            ElementKind::BehavioralVoltage { .. } => {
                return Err(format!(
                    "{LABEL} behavioral source requires exact +0 TC1 and TC2"
                ));
            }
            _ => {
                return Err(format!(
                    "{LABEL} subcircuit element must be a behavioral voltage source"
                ));
            }
        };

        if netlist.elements.len() != 4 {
            return Err(format!(
                "{LABEL} requires one subcircuit instance, two resistors, and one DC voltage source, found {} top-level elements",
                netlist.elements.len()
            ));
        }
        let mut instance = None;
        let mut resistors = Vec::new();
        let mut voltage_source = None;
        for element in &netlist.elements {
            if let Some(alias) = element.nodes.iter().find(|node| {
                crate::compat::ground::is_spice_ground_name(node)
                    && !Self::param_expression_name_is_literal_ground(node)
            }) {
                return Err(format!(
                    "element '{}' uses ground alias '{}'; {LABEL} requires literal node 0",
                    element.name, alias
                ));
            }
            match &element.kind {
                ElementKind::Subcircuit {
                    subckt_name,
                    params,
                } => {
                    if instance.is_some() {
                        return Err(format!("{LABEL} requires exactly one subcircuit instance"));
                    }
                    if !subckt_name.eq_ignore_ascii_case(&subcircuit.name)
                        || !params.is_empty()
                        || element.nodes.len() != 6
                    {
                        return Err(format!(
                            "subcircuit instance '{}' must bind all six ports without parameter overrides",
                            element.name
                        ));
                    }
                    instance = Some(element);
                }
                ElementKind::Resistor { .. } => resistors.push(element),
                ElementKind::VoltageSource(_) => {
                    if voltage_source.replace(element).is_some() {
                        return Err(format!("{LABEL} requires exactly one voltage source"));
                    }
                }
                _ => {
                    return Err(format!(
                        "top-level element '{}' is outside the subcircuit/resistor/DC-source envelope",
                        element.name
                    ));
                }
            }
        }
        let instance =
            instance.ok_or_else(|| format!("{LABEL} contains no subcircuit instance"))?;
        if resistors.len() != 2 {
            return Err(format!(
                "{LABEL} requires exactly two resistors, found {}",
                resistors.len()
            ));
        }
        let voltage_source =
            voltage_source.ok_or_else(|| format!("{LABEL} contains no voltage source"))?;
        if !instance
            .nodes
            .iter()
            .skip(1)
            .step_by(2)
            .all(|node| Self::param_expression_name_is_literal_ground(node))
        {
            return Err(format!(
                "subcircuit instance '{}' must bind ports 1, 3, and 5 to literal node 0",
                instance.name
            ));
        }
        let signal_nodes = [
            Self::canonical_param_expression_node_name(&instance.nodes[0]),
            Self::canonical_param_expression_node_name(&instance.nodes[2]),
            Self::canonical_param_expression_node_name(&instance.nodes[4]),
        ];
        if signal_nodes
            .iter()
            .any(|node| node == "0" || crate::compat::ground::is_spice_ground_name(node))
            || signal_nodes.iter().cloned().collect::<BTreeSet<_>>().len() != 3
        {
            return Err(format!(
                "subcircuit instance signal bindings must be three distinct non-ground nodes"
            ));
        }

        let mut resistor_signal_nodes = BTreeSet::new();
        for resistor in resistors {
            let nodes = resistor
                .nodes
                .iter()
                .map(|node| Self::canonical_param_expression_node_name(node))
                .collect::<Vec<_>>();
            let ElementKind::Resistor {
                value,
                value_expr,
                model,
                instance_params,
                deferred_params,
            } = &resistor.kind
            else {
                unreachable!("resistor collection is type-checked above")
            };
            if nodes.len() != 2
                || nodes[1] != "0"
                || !value.is_finite()
                || *value <= 0.0
                || value_expr.is_some()
                || model.is_some()
                || !instance_params.is_empty()
                || !deferred_params.is_empty()
                || !matches!(nodes[0].as_str(), node if node == signal_nodes[0] || node == signal_nodes[1])
                || !resistor_signal_nodes.insert(nodes[0].clone())
            {
                return Err(format!(
                    "resistor '{}' must be one unique finite positive numeric connection from instance signal 0 or 2 to literal ground",
                    resistor.name
                ));
            }
        }
        if resistor_signal_nodes
            != [signal_nodes[0].clone(), signal_nodes[1].clone()]
                .into_iter()
                .collect()
        {
            return Err(format!(
                "{LABEL} resistors must terminate instance signal nodes 0 and 2"
            ));
        }

        let voltage_nodes = voltage_source
            .nodes
            .iter()
            .map(|node| Self::canonical_param_expression_node_name(node))
            .collect::<Vec<_>>();
        let ElementKind::VoltageSource(crate::netlist::SourceSpec::Dc(source_value)) =
            &voltage_source.kind
        else {
            return Err(format!(
                "voltage source '{}' must be a direct DC source",
                voltage_source.name
            ));
        };
        if voltage_nodes != [signal_nodes[2].clone(), "0".to_string()]
            || !source_value.is_finite()
            || *source_value == 0.0
        {
            return Err(format!(
                "voltage source '{}' must drive instance signal node 4 from literal ground with a finite nonzero DC value",
                voltage_source.name
            ));
        }

        let [probe] = print.probes.as_slice() else {
            return Err(format!("{LABEL} requires exactly one output probe"));
        };
        let probe = Self::parse_voltage_probe(probe)
            .ok_or_else(|| format!("{LABEL} requires an atomic voltage probe"))?;
        if probe.accessor != XyceVoltageAccessor::Value
            || probe.node_neg.is_some()
            || Self::canonical_param_expression_node_name(&probe.node_pos) != signal_nodes[0]
        {
            return Err(format!(
                "{LABEL} output probe must observe instance signal node 0"
            ));
        }

        let flattened = crate::netlist::flatten_netlist_with_models(netlist)
            .map_err(|err| format!("could not flatten {LABEL} member: {err}"))?;
        if !flattened.scoped_models.is_empty()
            || !flattened.scoped_initial_conditions.is_empty()
            || !flattened.scoped_node_sets.is_empty()
            || !flattened.xspice_auto_bridge_node_hints.is_empty()
            || flattened.elements.len() != 4
        {
            return Err(format!(
                "flattened {LABEL} member contains scoped state, bridge hints, or an unexpected element count"
            ));
        }
        let mut flattened_elements = BTreeMap::new();
        let mut flattened_resistor_nodes = BTreeSet::new();
        let mut flattened_voltage_count = 0usize;
        let mut flattened_behavioral_count = 0usize;
        for element in &flattened.elements {
            if let Some(alias) = element.nodes.iter().find(|node| {
                crate::compat::ground::is_spice_ground_name(node)
                    && !Self::param_expression_name_is_literal_ground(node)
            }) {
                return Err(format!(
                    "flattened element '{}' uses unqualified ground alias '{}'",
                    element.name, alias
                ));
            }
            let nodes = element
                .nodes
                .iter()
                .map(|node| Self::canonical_param_expression_node_name(node))
                .collect::<Vec<_>>();
            let fingerprint = match &element.kind {
                ElementKind::Resistor {
                    value,
                    value_expr,
                    model,
                    instance_params,
                    deferred_params,
                } if nodes.len() == 2
                    && nodes[1] == "0"
                    && value.is_finite()
                    && *value > 0.0
                    && value_expr.is_none()
                    && model.is_none()
                    && instance_params.is_empty()
                    && deferred_params.is_empty()
                    && matches!(nodes[0].as_str(), node if node == signal_nodes[0] || node == signal_nodes[1])
                    && flattened_resistor_nodes.insert(nodes[0].clone()) =>
                {
                    XyceRelationalElementFingerprint {
                        kind: "R".to_string(),
                        nodes,
                        numeric_bits: vec![value.to_bits()],
                        text: Vec::new(),
                    }
                }
                ElementKind::VoltageSource(crate::netlist::SourceSpec::Dc(value))
                    if nodes == [signal_nodes[2].clone(), "0".to_string()]
                        && value.is_finite()
                        && *value != 0.0
                        && flattened_voltage_count == 0 =>
                {
                    flattened_voltage_count += 1;
                    XyceRelationalElementFingerprint {
                        kind: "V:DC".to_string(),
                        nodes,
                        numeric_bits: vec![value.to_bits()],
                        text: Vec::new(),
                    }
                }
                ElementKind::BehavioralVoltage {
                    expression,
                    tc1,
                    tc2,
                } if nodes == [signal_nodes[0].clone(), "0".to_string()]
                    && tc1.to_bits() == 0.0f64.to_bits()
                    && tc2.to_bits() == 0.0f64.to_bits()
                    && flattened_behavioral_count == 0 =>
                {
                    Self::qualify_prepared_param_expression(
                        expression,
                        &netlist.params,
                        *parameter_value,
                        &signal_nodes[1],
                        "0",
                        &signal_nodes[2],
                        "0",
                    )?;
                    flattened_behavioral_count += 1;
                    XyceRelationalElementFingerprint {
                        kind: "BV".to_string(),
                        nodes,
                        numeric_bits: vec![tc1.to_bits(), tc2.to_bits(), parameter_value.to_bits()],
                        text: vec![
                            signal_nodes[1].clone(),
                            "0".to_string(),
                            signal_nodes[2].clone(),
                            "0".to_string(),
                        ],
                    }
                }
                _ => {
                    return Err(format!(
                        "flattened element '{}' is outside the qualified parameter-expression topology",
                        element.name
                    ));
                }
            };
            let key = Self::normalize_device_instance_name(&element.name);
            if flattened_elements
                .insert(key.clone(), fingerprint)
                .is_some()
            {
                return Err(format!(
                    "flattened {LABEL} member contains duplicate element name '{key}'"
                ));
            }
        }
        if flattened_resistor_nodes
            != [signal_nodes[0].clone(), signal_nodes[1].clone()]
                .into_iter()
                .collect()
            || flattened_voltage_count != 1
            || flattened_behavioral_count != 1
        {
            return Err(format!(
                "flattened {LABEL} member does not contain the exact two-resistor/one-DC-source/one-behavioral-source topology"
            ));
        }

        Ok(XyceParamExpressionFamilySnapshot {
            title: netlist.title.trim().to_string(),
            parameter_name: parameter_name.to_ascii_lowercase(),
            parameter_bits: parameter_value.to_bits(),
            subcircuit_name: subcircuit.name.trim().to_ascii_lowercase(),
            subcircuit_ports,
            flattened_elements,
            representation,
        })
    }

    fn compare_param_expression_family_snapshots(
        baseline: &XyceParamExpressionFamilySnapshot,
        target: &XyceParamExpressionFamilySnapshot,
    ) -> Result<(), String> {
        if baseline.representation != XyceParamExpressionRepresentation::ParameterCoefficient
            || target.representation != XyceParamExpressionRepresentation::LiteralCoefficient
        {
            return Err(
                "family must compare a direct parameter-coefficient baseline with a direct literal-coefficient target"
                    .to_string(),
            );
        }
        if baseline.title != target.title {
            return Err("circuit titles differ".to_string());
        }
        if baseline.parameter_name != target.parameter_name
            || baseline.parameter_bits != target.parameter_bits
        {
            return Err("global parameter identity or value differs".to_string());
        }
        if baseline.subcircuit_name != target.subcircuit_name
            || baseline.subcircuit_ports != target.subcircuit_ports
        {
            return Err("subcircuit identity or ordered ports differ".to_string());
        }
        if baseline.flattened_elements != target.flattened_elements {
            return Err(
                "flattened element identity, topology, or numeric state differs".to_string(),
            );
        }
        Ok(())
    }

    fn scoped_model_family_snapshot(
        contract: &XyceBaselineFamilyContract,
        netlist: &Netlist,
    ) -> Result<Option<XyceScopedModelFamilySnapshot>, String> {
        if contract.kind != XyceBaselineFamilyKind::ScopedModel {
            return Ok(None);
        }

        let flattened = crate::netlist::flatten_netlist_with_models(netlist)
            .map_err(|err| format!("could not flatten scoped-model family member: {err}"))?;

        let mut elements = BTreeMap::new();
        let mut bjt_model_bits = BTreeMap::new();
        let mut diode_model_bits = BTreeMap::new();
        for element in &flattened.elements {
            let key = Self::normalize_device_instance_name(&element.name);
            let fingerprint = Self::scoped_model_element_fingerprint(element, &netlist.params)?;
            if elements.insert(key.clone(), fingerprint).is_some() {
                return Err(format!(
                    "flattened scoped-model family contains duplicate element name '{key}'"
                ));
            }

            match &element.kind {
                ElementKind::Bjt { model, .. } => {
                    let effective_model = Self::find_unique_model_in(
                        flattened
                            .scoped_models
                            .iter()
                            .chain(netlist.models.iter()),
                        model,
                    )
                    .ok_or_else(|| {
                        format!(
                            "scoped-model BJT '{key}' must reference exactly one effective model '{model}'"
                        )
                    })?;
                    if !Self::model_is_native_scoped_model_relational_bjt(effective_model) {
                        return Err(format!(
                            "scoped-model BJT '{key}' references an unresolved or unqualified effective model '{model}'"
                        ));
                    }
                    let bf = Self::numeric_param_value(&effective_model.params, "BF")
                        .expect("qualified scoped-model BJT has exactly one BF");
                    let saturation_current =
                        Self::numeric_param_value(&effective_model.params, "IS")
                            .expect("qualified scoped-model BJT has exactly one IS");
                    bjt_model_bits.insert(key, (bf.to_bits(), saturation_current.to_bits()));
                }
                ElementKind::Diode { model, .. } => {
                    let effective_model = Self::find_unique_model_in(
                        flattened
                            .scoped_models
                            .iter()
                            .chain(netlist.models.iter()),
                        model,
                    )
                    .ok_or_else(|| {
                        format!(
                            "scoped-model diode '{key}' must reference exactly one effective model '{model}'"
                        )
                    })?;
                    if !Self::model_is_native_exact_is_diode(effective_model) {
                        return Err(format!(
                            "scoped-model diode '{key}' references an unresolved or unqualified effective model '{model}'"
                        ));
                    }
                    let saturation_current =
                        Self::numeric_param_value(&effective_model.params, "IS")
                            .expect("qualified scoped-model diode has exactly one IS");
                    diode_model_bits.insert(key, saturation_current.to_bits());
                }
                _ => {}
            }
        }

        if bjt_model_bits.is_empty() && diode_model_bits.is_empty() {
            return Err(format!(
                "scoped-model family '{}' does not exercise a qualified nonlinear model",
                contract.family
            ));
        }

        Ok(Some(XyceScopedModelFamilySnapshot {
            elements,
            bjt_model_bits,
            diode_model_bits,
        }))
    }

    fn validate_bjt_external_node_dc_plan(plan: &XyceStaticDcPlan) -> Result<(), String> {
        if !plan.steps.is_empty() {
            return Err("exact BJT external-node DC does not admit .STEP".to_string());
        }
        if plan.dc_data.is_some() {
            return Err("exact BJT external-node DC does not admit .DC DATA".to_string());
        }
        if plan.print_format.is_some() {
            return Err(
                "exact BJT external-node DC requires ordinary primary .prn output without a format override"
                    .to_string(),
            );
        }
        if plan.dc.sweep2.is_some() {
            return Err("exact BJT external-node DC requires one sweep dimension".to_string());
        }
        if !matches!(plan.dc.mode, crate::netlist::DcSweepMode::Linear) {
            return Err("exact BJT external-node DC requires a linear sweep".to_string());
        }
        if !plan.dc.start.is_finite()
            || !plan.dc.stop.is_finite()
            || !plan.dc.step.is_finite()
            || plan.dc.step <= 0.0
            || plan.dc.stop < plan.dc.start
        {
            return Err(format!(
                "exact BJT external-node DC requires a finite ascending sweep, got start={}, stop={}, step={}",
                plan.dc.start, plan.dc.stop, plan.dc.step
            ));
        }
        if plan.print.probes.is_empty() {
            return Err("exact BJT external-node DC requires at least one probe".to_string());
        }
        let mut probes = BTreeSet::new();
        for probe in &plan.print.probes {
            let normalized = Self::normalize_probe(probe);
            if !probes.insert(normalized) {
                return Err(format!(
                    "exact BJT external-node DC does not admit duplicate probe '{probe}'"
                ));
            }
        }
        if !plan.diagnostics.is_empty() {
            return Err(format!(
                "exact BJT external-node DC requires a diagnostic-free parse, found {} diagnostic(s)",
                plan.diagnostics.len()
            ));
        }

        let mut model_count = 0usize;
        let mut dc_count = 0usize;
        let mut print_count = 0usize;
        let mut end_count = 0usize;
        for line in Self::logical_netlist_lines(&plan.source) {
            let stripped = Self::strip_netlist_comment(&line);
            let Some(command) = stripped.split_whitespace().next() else {
                continue;
            };
            if !command.starts_with('.') {
                continue;
            }
            match command.to_ascii_lowercase().as_str() {
                ".model" => model_count += 1,
                ".dc" => dc_count += 1,
                ".print" => print_count += 1,
                ".end" => end_count += 1,
                other => {
                    return Err(format!(
                        "exact BJT external-node DC does not admit directive '{other}'"
                    ));
                }
            }
        }
        if (model_count, dc_count, print_count, end_count) != (1, 1, 1, 1) {
            return Err(format!(
                "exact BJT external-node DC requires exactly one .MODEL, .DC, .PRINT, and .END; found ({model_count}, {dc_count}, {print_count}, {end_count})"
            ));
        }
        Self::validate_bjt_external_node_print_contract(&plan.source)?;
        Ok(())
    }

    fn validate_bjt_external_node_print_contract(source: &str) -> Result<(), String> {
        for line in Self::logical_netlist_lines(source) {
            let trimmed = Self::strip_netlist_comment(&line).trim();
            if !trimmed
                .split_whitespace()
                .next()
                .is_some_and(|command| command.eq_ignore_ascii_case(".print"))
            {
                continue;
            }
            let tokens = Self::split_print_fields(trimmed)?;
            if !tokens
                .get(1)
                .is_some_and(|analysis| analysis.eq_ignore_ascii_case("DC"))
            {
                continue;
            }
            let token_refs = tokens.iter().map(String::as_str).collect::<Vec<_>>();
            let mut index = 2usize;
            while index < token_refs.len() {
                if let Some((raw_key, _, _)) = Self::print_option_assignment(&token_refs, index) {
                    return Err(format!(
                        "exact BJT external-node DC requires default primary .prn formatting and does not admit .PRINT assignment {raw_key}"
                    ));
                }
                if token_refs[index].eq_ignore_ascii_case("noindex") {
                    return Err(
                        "exact BJT external-node DC requires the default indexed .prn layout and does not admit .PRINT NOINDEX"
                            .to_string(),
                    );
                }
                index += 1;
            }
        }
        Ok(())
    }

    fn dc_sweep_modes_match_exactly(
        baseline: &crate::netlist::DcSweepMode,
        target: &crate::netlist::DcSweepMode,
    ) -> bool {
        match (baseline, target) {
            (crate::netlist::DcSweepMode::Linear, crate::netlist::DcSweepMode::Linear) => true,
            (
                crate::netlist::DcSweepMode::List(baseline),
                crate::netlist::DcSweepMode::List(target),
            ) => {
                baseline.len() == target.len()
                    && baseline.iter().all(|value| value.is_finite())
                    && target.iter().all(|value| value.is_finite())
                    && baseline
                        .iter()
                        .zip(target)
                        .all(|(baseline, target)| baseline.to_bits() == target.to_bits())
            }
            (
                crate::netlist::DcSweepMode::Decade {
                    points_per_decade: baseline,
                },
                crate::netlist::DcSweepMode::Decade {
                    points_per_decade: target,
                },
            ) => baseline == target,
            (
                crate::netlist::DcSweepMode::Octave {
                    points_per_octave: baseline,
                },
                crate::netlist::DcSweepMode::Octave {
                    points_per_octave: target,
                },
            ) => baseline == target,
            _ => false,
        }
    }

    fn dc_second_sweeps_match_exactly(
        baseline: Option<&DcSecondSweep>,
        target: Option<&DcSecondSweep>,
    ) -> bool {
        match (baseline, target) {
            (None, None) => true,
            (Some(baseline), Some(target)) => {
                baseline.start.is_finite()
                    && baseline.stop.is_finite()
                    && baseline.step.is_finite()
                    && target.start.is_finite()
                    && target.stop.is_finite()
                    && target.step.is_finite()
                    && baseline.source == target.source
                    && baseline.start.to_bits() == target.start.to_bits()
                    && baseline.stop.to_bits() == target.stop.to_bits()
                    && baseline.step.to_bits() == target.step.to_bits()
                    && Self::dc_sweep_modes_match_exactly(&baseline.mode, &target.mode)
            }
            _ => false,
        }
    }

    fn dc_sweeps_match_exactly(baseline: &XyceDcSweep, target: &XyceDcSweep) -> bool {
        baseline.start.is_finite()
            && baseline.stop.is_finite()
            && baseline.step.is_finite()
            && target.start.is_finite()
            && target.stop.is_finite()
            && target.step.is_finite()
            && baseline.source == target.source
            && baseline.start.to_bits() == target.start.to_bits()
            && baseline.stop.to_bits() == target.stop.to_bits()
            && baseline.step.to_bits() == target.step.to_bits()
            && Self::dc_sweep_modes_match_exactly(&baseline.mode, &target.mode)
            && Self::dc_second_sweeps_match_exactly(
                baseline.sweep2.as_ref(),
                target.sweep2.as_ref(),
            )
    }

    fn bjt_external_node_name_is_literal_ground(node: &str) -> bool {
        node.trim() == "0"
    }

    fn canonical_bjt_external_node_name(node: &str) -> String {
        if Self::bjt_external_node_name_is_literal_ground(node) {
            "0".to_string()
        } else {
            node.trim().to_ascii_lowercase()
        }
    }

    fn model_is_native_bjt_external_node_level1_npn(model: &crate::netlist::ModelDef) -> bool {
        model.model_type.eq_ignore_ascii_case("NPN")
            && model.expr_params.is_empty()
            && model.string_params.is_empty()
            && model.string_vector_params.is_empty()
            && model.real_vector_params.is_empty()
            && model.real_vector_expr_params.is_empty()
            && model.integer_vector_params.is_empty()
            && model.params.len() == 1
            && model.params[0].0.eq_ignore_ascii_case("BF")
            && model.params[0].1.is_finite()
            && model.params[0].1 > 0.0
    }

    fn validate_bjt_external_node_dc_probes(
        print: &XycePrintRequest,
        netlist: &Netlist,
    ) -> Result<(), String> {
        for probe in &print.probes {
            if Self::parse_voltage_probe(probe)
                .is_some_and(|probe| probe.accessor == XyceVoltageAccessor::Value)
            {
                continue;
            }
            if Self::parse_current_probe(probe)
                .is_some_and(|source| Self::source_is_voltage_source(netlist, &source))
            {
                continue;
            }
            return Err(format!(
                "exact BJT external-node DC probe '{probe}' is not an atomic voltage or independent voltage-source current"
            ));
        }
        Ok(())
    }

    fn bjt_external_node_family_snapshot(
        netlist: &Netlist,
        print: &XycePrintRequest,
    ) -> Result<XyceBjtExternalNodeFamilySnapshot, String> {
        Self::validate_bjt_external_node_dc_probes(print, netlist)?;
        if !netlist.data_tables.is_empty()
            || !netlist.subcircuits.is_empty()
            || !netlist.initial_conditions.is_empty()
            || !netlist.node_sets.is_empty()
            || !netlist.global_nodes.is_empty()
            || !netlist.measurements.is_empty()
            || !netlist.veriloga_includes.is_empty()
            || !netlist.spef_includes.is_empty()
        {
            return Err(
                "exact BJT external-node DC contains auxiliary analysis, hierarchy, or external-model state"
                    .to_string(),
            );
        }
        if !netlist.params.all_params().is_empty()
            || !netlist.params.all_string_params().is_empty()
            || !netlist.params.all_functions().is_empty()
        {
            return Err(
                "exact BJT external-node DC does not admit parameters or user functions"
                    .to_string(),
            );
        }
        if netlist.models.len() != 1 {
            return Err(format!(
                "exact BJT external-node DC requires exactly one model, found {}",
                netlist.models.len()
            ));
        }
        let effective_model = &netlist.models[0];
        if !Self::model_is_native_bjt_external_node_level1_npn(effective_model) {
            return Err(format!(
                "model '{}' is not the qualified implicit-Level-1 NPN with one finite positive BF",
                effective_model.name
            ));
        }

        let mut elements = BTreeMap::new();
        let mut bjt_model_bits = BTreeMap::new();
        let mut representation = None;
        for element in &netlist.elements {
            let key = Self::normalize_device_instance_name(&element.name);
            if let Some(alias) = element.nodes.iter().find(|node| {
                crate::compat::ground::is_spice_ground_name(node)
                    && !Self::bjt_external_node_name_is_literal_ground(node)
            }) {
                return Err(format!(
                    "element '{}' uses ground alias '{}'; exact Xyce parity requires literal node 0 without .PREPROCESS REPLACEGND",
                    element.name, alias
                ));
            }
            let mut nodes = element
                .nodes
                .iter()
                .map(|node| Self::canonical_bjt_external_node_name(node))
                .collect::<Vec<_>>();
            let (kind, numeric_bits, text) = match &element.kind {
                ElementKind::Resistor {
                    value,
                    value_expr,
                    model,
                    instance_params,
                    deferred_params,
                } => {
                    if element.nodes.len() != 2
                        || !value.is_finite()
                        || *value <= 0.0
                        || value_expr.is_some()
                        || model.is_some()
                        || !instance_params.is_empty()
                        || !deferred_params.is_empty()
                    {
                        return Err(format!(
                            "resistor '{}' is outside the finite numeric two-terminal envelope",
                            element.name
                        ));
                    }
                    ("R".to_string(), vec![value.to_bits()], Vec::new())
                }
                ElementKind::VoltageSource(crate::netlist::SourceSpec::Dc(value)) => {
                    if element.nodes.len() != 2 || !value.is_finite() {
                        return Err(format!(
                            "voltage source '{}' is outside the finite two-terminal DC envelope",
                            element.name
                        ));
                    }
                    ("V:DC".to_string(), vec![value.to_bits()], Vec::new())
                }
                ElementKind::Bjt {
                    model,
                    instance_params,
                    deferred_params,
                    ..
                } => {
                    if representation.is_some() {
                        return Err(
                            "exact BJT external-node DC requires exactly one BJT".to_string()
                        );
                    }
                    if !instance_params.is_empty() || !deferred_params.is_empty() {
                        return Err(format!(
                            "BJT '{}' has unqualified instance parameters",
                            element.name
                        ));
                    }
                    if !model.eq_ignore_ascii_case(&effective_model.name) {
                        return Err(format!(
                            "BJT '{}' does not reference the unique effective model '{}'",
                            element.name, effective_model.name
                        ));
                    }
                    if !element.nodes.get(2).is_some_and(|emitter| {
                        Self::bjt_external_node_name_is_literal_ground(emitter)
                    }) {
                        return Err(format!(
                            "BJT '{}' emitter must be ground in the qualified external-node envelope",
                            element.name
                        ));
                    }
                    let form = match element.nodes.as_slice() {
                        [_, _, _] => {
                            nodes.push("0".to_string());
                            XyceBjtExternalNodeRepresentation::OmittedGround
                        }
                        [_, _, _, substrate]
                            if Self::bjt_external_node_name_is_literal_ground(substrate) =>
                        {
                            XyceBjtExternalNodeRepresentation::ExplicitGround
                        }
                        [_, _, _, _] => {
                            return Err(format!(
                                "BJT '{}' explicit substrate must be ground",
                                element.name
                            ));
                        }
                        _ => {
                            return Err(format!(
                                "BJT '{}' must have exactly three or four terminals",
                                element.name
                            ));
                        }
                    };
                    representation = Some(form);
                    bjt_model_bits.insert(
                        effective_model.name.to_ascii_lowercase(),
                        effective_model.params[0].1.to_bits(),
                    );
                    (
                        "Q:NPN:L1".to_string(),
                        Vec::new(),
                        vec![model.to_ascii_lowercase()],
                    )
                }
                _ => {
                    return Err(format!(
                        "element '{}' is outside the resistor/DC-voltage-source/Level-1-NPN envelope",
                        element.name
                    ));
                }
            };
            let fingerprint = XyceRelationalElementFingerprint {
                kind,
                nodes,
                numeric_bits,
                text,
            };
            if elements.insert(key.clone(), fingerprint).is_some() {
                return Err(format!(
                    "exact BJT external-node DC contains duplicate element name '{key}'"
                ));
            }
        }
        let representation = representation
            .ok_or_else(|| "exact BJT external-node DC contains no qualified BJT".to_string())?;
        if bjt_model_bits.len() != 1 {
            return Err(
                "exact BJT external-node DC did not resolve exactly one BJT model".to_string(),
            );
        }
        Ok(XyceBjtExternalNodeFamilySnapshot {
            title: netlist.title.trim().to_string(),
            elements,
            bjt_model_bits,
            representation,
        })
    }

    fn compare_bjt_external_node_family_snapshots(
        baseline: &XyceBjtExternalNodeFamilySnapshot,
        target: &XyceBjtExternalNodeFamilySnapshot,
    ) -> Result<(), String> {
        if baseline.representation == target.representation {
            return Err(
                "both members use the same BJT substrate representation instead of an omitted/explicit pair"
                    .to_string(),
            );
        }
        if baseline.title != target.title {
            return Err("circuit titles differ".to_string());
        }
        if baseline.elements != target.elements {
            return Err("element topology or values differ".to_string());
        }
        if baseline.bjt_model_bits != target.bjt_model_bits {
            return Err("explicit BJT model fields differ".to_string());
        }
        Ok(())
    }

    fn normalized_xyce_verify_transient_rows(
        table: &XycePrnTable,
        role: &str,
        tolerances: &[XyceVerifyTransientTolerance],
        scientific_precision: usize,
    ) -> Result<Vec<(Value, Vec<Value>)>, String> {
        if table.columns.len() < 3
            || !table.columns[0].eq_ignore_ascii_case("Index")
            || !table.columns[1].eq_ignore_ascii_case("TIME")
        {
            return Err(format!(
                "{role} table must contain Index, TIME, and at least one output column"
            ));
        }
        if table.rows.is_empty() {
            return Err(format!("{role} table contains no transient rows"));
        }
        if tolerances.len() != table.columns.len() - 2 {
            return Err(format!(
                "{role} table has {} output column(s), but {} xyce_verify tolerance(s) were supplied",
                table.columns.len() - 2,
                tolerances.len()
            ));
        }

        let mut normalized = Vec::with_capacity(table.rows.len());
        for (row_index, row) in table.rows.iter().enumerate() {
            if row.len() != table.columns.len() {
                return Err(format!(
                    "{role} row {row_index} has {} values, expected {}",
                    row.len(),
                    table.columns.len()
                ));
            }
            if row.iter().any(|value| !value.is_finite()) {
                return Err(format!(
                    "{role} row {row_index} contains a non-finite value"
                ));
            }

            let zero_small = |value: Value, zero_tolerance: Value| {
                if value.abs() <= zero_tolerance {
                    0.0
                } else {
                    value
                }
            };
            // rc_osc overrides only its expression's *COMP tolerance. TIME
            // retains Release 7.10's independent default zero threshold.
            let time = zero_small(
                Self::xyce_prn_scientific_roundtrip(row[1], scientific_precision).map_err(
                    |err| format!("could not serialize {role} TIME at row {row_index}: {err}"),
                )?,
                XYCE_VERIFY_DEFAULT_ZERO_TOLERANCE,
            );
            let mut values = Vec::with_capacity(row.len() - 2);
            for (column_index, &value) in row[2..].iter().enumerate() {
                values.push(zero_small(
                    Self::xyce_prn_scientific_roundtrip(value, scientific_precision).map_err(
                        |err| {
                            format!(
                                "could not serialize {role} {} at row {row_index}: {err}",
                                table.columns[column_index + 2]
                            )
                        },
                    )?,
                    tolerances[column_index].zero,
                ));
            }
            if normalized
                .last()
                .is_some_and(|(previous_time, _)| *previous_time == time)
            {
                // Release 7.10's ReadDataFile keeps the first printed row at
                // a time and discards immediately following duplicates before
                // interpolation.
                continue;
            }
            if normalized
                .last()
                .is_some_and(|(previous_time, _)| *previous_time > time)
            {
                return Err(format!(
                    "{role} transient times are not monotonically increasing at row {row_index}"
                ));
            }
            normalized.push((time, values));
        }
        if normalized.is_empty() {
            return Err(format!(
                "{role} table has no rows after duplicate-time normalization"
            ));
        }
        Ok(normalized)
    }

    fn xyce_default_prn_roundtrip(value: Value) -> Result<Value, String> {
        Self::xyce_prn_scientific_roundtrip(value, XYCE_DEFAULT_PRN_SCIENTIFIC_PRECISION)
    }

    fn xyce_prn_scientific_roundtrip(
        value: Value,
        scientific_precision: usize,
    ) -> Result<Value, String> {
        let printed = Self::xyce_prn_scientific_text(value, scientific_precision)?;
        printed
            .parse::<Value>()
            .map_err(|err| format!("could not parse scientific .prn value '{printed}': {err}"))
    }

    fn xyce_default_prn_text(value: Value) -> Result<String, String> {
        Self::xyce_prn_scientific_text(value, XYCE_DEFAULT_PRN_SCIENTIFIC_PRECISION)
    }

    fn xyce_prn_scientific_text(
        value: Value,
        scientific_precision: usize,
    ) -> Result<String, String> {
        if !value.is_finite() {
            return Err(format!("scientific .prn output cannot serialize {value}"));
        }
        if !(1..=XYCE_MAX_IEEE754_PRN_SCIENTIFIC_PRECISION).contains(&scientific_precision) {
            return Err(format!(
                "scientific .prn precision must be between 1 and {XYCE_MAX_IEEE754_PRN_SCIENTIFIC_PRECISION}, got {scientific_precision}"
            ));
        }
        Ok(format!(
            "{value:.precision$e}",
            precision = scientific_precision
        ))
    }

    fn xyce_verify_linear_interpolate(
        low_time: Value,
        high_time: Value,
        test_time: Value,
        low_value: Value,
        high_value: Value,
    ) -> Value {
        (high_value - low_value) / (high_time - low_time) * (test_time - low_time) + low_value
    }

    fn xyce_verify_normalized_error(expected: Value, actual: Value) -> Value {
        Self::xyce_verify_normalized_error_with_tolerance(
            expected,
            actual,
            XyceVerifyTransientTolerance::release_7_10_default(),
        )
    }

    fn xyce_verify_normalized_error_with_tolerance(
        expected: Value,
        actual: Value,
        tolerance: XyceVerifyTransientTolerance,
    ) -> Value {
        let difference = expected - actual;
        if difference.abs() < tolerance.absolute_difference {
            0.0
        } else {
            difference / (tolerance.relative * expected.abs() + tolerance.absolute)
        }
    }

    fn compare_xyce_verify_transient_tables(
        &self,
        good: &XycePrnTable,
        test: &XycePrnTable,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        self.compare_xyce_verify_transient_tables_with_uniform_tolerance(
            good,
            test,
            XyceVerifyTransientTolerance::release_7_10_default(),
            XYCE_DEFAULT_PRN_SCIENTIFIC_PRECISION,
        )
    }

    fn compare_xyce_verify_transient_tables_with_tolerance(
        &self,
        good: &XycePrnTable,
        test: &XycePrnTable,
        tolerance: XyceVerifyTransientTolerance,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        if good.columns.len() != 3 || test.columns.len() != 3 {
            return Err(format!(
                "custom xyce_verify transient tolerance requires exactly one output column, got good={:?}, test={:?}",
                good.columns, test.columns
            ));
        }
        self.compare_xyce_verify_transient_tables_with_uniform_tolerance(
            good,
            test,
            tolerance,
            XYCE_DEFAULT_PRN_SCIENTIFIC_PRECISION,
        )
    }

    fn compare_xyce_verify_transient_tables_with_uniform_tolerance(
        &self,
        good: &XycePrnTable,
        test: &XycePrnTable,
        tolerance: XyceVerifyTransientTolerance,
        scientific_precision: usize,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        let tolerance = tolerance.validate()?;
        let probe_count = good.columns.len().saturating_sub(2);
        self.compare_xyce_verify_transient_tables_with_probe_tolerances(
            good,
            test,
            &vec![tolerance; probe_count],
            scientific_precision,
        )
    }

    fn compare_xyce_verify_transient_tables_with_probe_tolerances(
        &self,
        good: &XycePrnTable,
        test: &XycePrnTable,
        tolerances: &[XyceVerifyTransientTolerance],
        scientific_precision: usize,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        Self::xyce_prn_scientific_text(0.0, scientific_precision)?;
        if good.columns.len() != test.columns.len()
            || !good
                .columns
                .iter()
                .zip(&test.columns)
                .all(|(left, right)| left.eq_ignore_ascii_case(right))
        {
            return Err(format!(
                "xyce_verify transient columns differ: good={:?}, test={:?}",
                good.columns, test.columns
            ));
        }
        if tolerances.len() != good.columns.len().saturating_sub(2) {
            return Err(format!(
                "xyce_verify transient comparison has {} output column(s), but {} tolerance(s) were supplied",
                good.columns.len().saturating_sub(2),
                tolerances.len()
            ));
        }
        let tolerances = tolerances
            .iter()
            .copied()
            .map(XyceVerifyTransientTolerance::validate)
            .collect::<Result<Vec<_>, _>>()?;
        let quotient_operand_indices =
            Self::xyce_verify_quotient_operand_indices(&good.columns[2..]);
        let serialization_relative_tolerance = 4.0 * 10.0f64.powi(-(scientific_precision as i32));
        for (row_index, row) in test.rows.iter().enumerate() {
            for (probe_index, operands) in quotient_operand_indices.iter().enumerate() {
                let Some((numerator_index, divisor_index)) = *operands else {
                    continue;
                };
                let Some((&actual, &numerator, &divisor)) = row
                    .get(probe_index + 2)
                    .zip(row.get(numerator_index + 2))
                    .zip(row.get(divisor_index + 2))
                    .map(|((actual, numerator), divisor)| (actual, numerator, divisor))
                else {
                    return Err(format!(
                        "xyce_verify test row {row_index} is missing quotient or operand columns"
                    ));
                };
                let recomputed = numerator / divisor;
                if !recomputed.is_finite() {
                    continue;
                }
                let consistency_scale = actual
                    .abs()
                    .max(recomputed.abs())
                    .max(tolerances[probe_index].absolute);
                let consistency_error = (actual - recomputed).abs() / consistency_scale;
                if !consistency_error.is_finite()
                    || consistency_error > serialization_relative_tolerance
                {
                    return Err(format!(
                        "printed quotient {} is not algebraically consistent at test row {row_index}: printed={actual} numerator={numerator} divisor={divisor}",
                        good.columns[probe_index + 2]
                    ));
                }
            }
        }

        let good_rows = Self::normalized_xyce_verify_transient_rows(
            good,
            "good",
            &tolerances,
            scientific_precision,
        )?;
        let test_rows = Self::normalized_xyce_verify_transient_rows(
            test,
            "test",
            &tolerances,
            scientific_precision,
        )?;
        if good_rows.len() < 2 || test_rows.len() < 2 {
            return Err(format!(
                "xyce_verify transient RMS requires at least two distinct printed times in both series, found good={} and test={}",
                good_rows.len(),
                test_rows.len()
            ));
        }
        let good_first = good_rows[0].0;
        let good_last = good_rows[good_rows.len() - 1].0;
        let test_first = test_rows[0].0;
        let test_last = test_rows[test_rows.len() - 1].0;
        if good_first > test_first {
            return Err(format!(
                "good transient series starts at {good_first}, after test series start {test_first}"
            ));
        }
        if good_last < test_last {
            return Err(format!(
                "good transient series ends at {good_last}, before test series end {test_last}"
            ));
        }

        let probe_count = good.columns.len() - 2;
        let mut interpolated = Vec::with_capacity(test_rows.len());
        let mut good_high = 0usize;
        for (test_time, _) in &test_rows {
            while good_high + 1 < good_rows.len() && good_rows[good_high].0 < *test_time {
                good_high += 1;
            }
            if good_rows[good_high].0 < *test_time {
                return Err(format!(
                    "could not bracket test time {test_time} in the good transient series"
                ));
            }
            if good_rows[good_high].0 == *test_time {
                interpolated.push(good_rows[good_high].1.clone());
                continue;
            }
            let Some(good_low) = good_high.checked_sub(1) else {
                return Err(format!(
                    "could not find a good transient sample below test time {test_time}"
                ));
            };
            let low_time = good_rows[good_low].0;
            let high_time = good_rows[good_high].0;
            let width = high_time - low_time;
            if !width.is_finite() || width <= 0.0 {
                return Err(format!(
                    "good transient interpolation interval [{low_time}, {high_time}] is invalid"
                ));
            }
            let values = (0..probe_count)
                .map(|probe_index| {
                    Self::xyce_verify_linear_interpolate(
                        low_time,
                        high_time,
                        *test_time,
                        good_rows[good_low].1[probe_index],
                        good_rows[good_high].1[probe_index],
                    )
                })
                .collect::<Vec<_>>();
            if values.iter().any(|value| !value.is_finite()) {
                return Err(format!(
                    "good transient interpolation produced a non-finite value at time {test_time}"
                ));
            }
            interpolated.push(values);
        }

        let mut squared_errors = vec![vec![0.0; probe_count]; test_rows.len()];
        let mut worst_rows = vec![0usize; probe_count];
        let mut worst_errors = vec![0.0; probe_count];
        for (row_index, ((_, test_values), good_values)) in
            test_rows.iter().zip(&interpolated).enumerate()
        {
            for probe_index in 0..probe_count {
                let expected = good_values[probe_index];
                let actual = test_values[probe_index];
                let probe_tolerance = tolerances[probe_index];
                let normalized_error = if let Some((numerator_index, divisor_index)) =
                    quotient_operand_indices[probe_index]
                {
                    let numerator_tolerance = tolerances[numerator_index];
                    let divisor_tolerance = tolerances[divisor_index];
                    let numerator_error = Self::xyce_verify_normalized_error_with_tolerance(
                        good_values[numerator_index],
                        test_values[numerator_index],
                        numerator_tolerance,
                    );
                    let divisor_error = Self::xyce_verify_normalized_error_with_tolerance(
                        good_values[divisor_index],
                        test_values[divisor_index],
                        divisor_tolerance,
                    );
                    let operand_error = numerator_error.abs().max(divisor_error.abs());
                    let one_sided_conditioning_floor = (divisor_tolerance.absolute
                        / divisor_tolerance.relative)
                        .min(Value::MAX / 2.0);
                    let divisor_conditioning_floor = divisor_tolerance
                        .zero
                        .max(2.0 * one_sided_conditioning_floor);
                    let divisor_is_conditioned = test_values[divisor_index]
                        .abs()
                        .min(good_values[divisor_index].abs())
                        > divisor_conditioning_floor;
                    let interpolated_reference_quotient =
                        good_values[numerator_index] / good_values[divisor_index];
                    let reference_consistency_scale = expected
                        .abs()
                        .max(interpolated_reference_quotient.abs())
                        .max(probe_tolerance.absolute);
                    let reference_consistency_error = (expected - interpolated_reference_quotient)
                        .abs()
                        / reference_consistency_scale;
                    let reference_quotient_is_consistent = interpolated_reference_quotient
                        .is_finite()
                        && reference_consistency_error.is_finite()
                        && reference_consistency_error <= serialization_relative_tolerance;
                    if divisor_is_conditioned && reference_quotient_is_consistent {
                        Self::xyce_verify_normalized_error_with_tolerance(
                            expected,
                            actual,
                            probe_tolerance,
                        )
                    } else {
                        operand_error
                    }
                } else {
                    Self::xyce_verify_normalized_error_with_tolerance(
                        expected,
                        actual,
                        probe_tolerance,
                    )
                };
                if !normalized_error.is_finite() {
                    return Err(format!(
                        "normalized xyce_verify error is non-finite at test row {row_index}, probe {}",
                        good.columns[probe_index + 2]
                    ));
                }
                if normalized_error.abs() > worst_errors[probe_index] {
                    worst_errors[probe_index] = normalized_error.abs();
                    worst_rows[probe_index] = row_index;
                }
                squared_errors[row_index][probe_index] = normalized_error * normalized_error;
            }
        }

        let mut rms_errors = vec![0.0; probe_count];
        let duration = (test_last - test_first).abs();
        if !duration.is_finite() || duration <= 0.0 {
            return Err(format!(
                "test transient integration interval [{test_first}, {test_last}] is invalid"
            ));
        }
        for row_index in 1..test_rows.len() {
            let width = (test_rows[row_index].0 - test_rows[row_index - 1].0).abs();
            for probe_index in 0..probe_count {
                rms_errors[probe_index] += 0.5
                    * (squared_errors[row_index][probe_index]
                        + squared_errors[row_index - 1][probe_index])
                    * width;
            }
        }
        for error in &mut rms_errors {
            *error = (*error / duration).sqrt();
        }

        let mut mismatches = Vec::new();
        for (probe_index, rms_error) in rms_errors.into_iter().enumerate() {
            if !rms_error.is_finite() {
                return Err(format!(
                    "xyce_verify RMS error is non-finite for probe {}",
                    good.columns[probe_index + 2]
                ));
            }
            if rms_error > 1.0 {
                let row = worst_rows[probe_index];
                mismatches.push(XyceValueMismatch {
                    row,
                    probe: good.columns[probe_index + 2].clone(),
                    expected: interpolated[row][probe_index],
                    actual: test_rows[row].1[probe_index],
                    relative_error: rms_error,
                });
                if mismatches.len() >= self.config.max_mismatches {
                    break;
                }
            }
        }
        Ok(mismatches)
    }

    fn xyce_verify_quotient_operand_indices(columns: &[String]) -> Vec<Option<(usize, usize)>> {
        let normalized_columns = columns
            .iter()
            .map(|column| Self::normalize_probe(column))
            .collect::<Vec<_>>();
        columns
            .iter()
            .map(|column| {
                let expression = Self::print_expression_inner(column)?;
                let ast = parse_expression_strict(expression).ok()?;
                let (numerator_probe, divisor_probe) =
                    Self::xyce_verify_direct_quotient_probes(&ast)?;
                let normalized_numerator = Self::normalize_probe(&numerator_probe);
                let normalized_divisor = Self::normalize_probe(&divisor_probe);
                let numerator_index = normalized_columns
                    .iter()
                    .position(|candidate| *candidate == normalized_numerator)?;
                let divisor_index = normalized_columns
                    .iter()
                    .position(|candidate| *candidate == normalized_divisor)?;
                Some((numerator_index, divisor_index))
            })
            .collect()
    }

    fn xyce_verify_direct_quotient_probes(expression: &Expr) -> Option<(String, String)> {
        let Expr::Binary {
            op: BinaryOp::Div,
            left,
            right,
            ..
        } = expression
        else {
            return None;
        };
        Some((
            Self::xyce_verify_direct_probe(left)?,
            Self::xyce_verify_direct_probe(right)?,
        ))
    }

    fn xyce_verify_direct_probe(expression: &Expr) -> Option<String> {
        match expression {
            Expr::NodeVoltage(node) => Some(format!("V({node})")),
            Expr::BranchCurrent(element) => Some(format!("I({element})")),
            _ => None,
        }
    }

    fn compare_exact_prn_tables(
        &self,
        expected: &XycePrnTable,
        actual: &XycePrnTable,
        expected_raw_time: &[Value],
        actual_raw_time: &[Value],
    ) -> Result<Vec<XyceValueMismatch>, String> {
        self.compare_exact_prn_tables_with_axis(
            expected,
            actual,
            expected_raw_time,
            actual_raw_time,
            "TIME",
        )
    }

    fn compare_serialized_default_prn_tables(
        &self,
        expected: &XycePrnTable,
        actual: &XycePrnTable,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        self.compare_serialized_default_prn_tables_with_column_case(expected, actual, false)
    }

    fn compare_serialized_default_prn_tables_case_insensitive(
        &self,
        expected: &XycePrnTable,
        actual: &XycePrnTable,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        self.compare_serialized_default_prn_tables_with_column_case(expected, actual, true)
    }

    fn compare_serialized_default_prn_tables_with_column_case(
        &self,
        expected: &XycePrnTable,
        actual: &XycePrnTable,
        case_insensitive_columns: bool,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        let columns_match = expected.columns.len() == actual.columns.len()
            && expected
                .columns
                .iter()
                .zip(&actual.columns)
                .all(|(expected, actual)| {
                    if case_insensitive_columns {
                        expected.eq_ignore_ascii_case(actual)
                    } else {
                        expected == actual
                    }
                });
        if !columns_match {
            return Err(format!(
                "default .prn columns differ: expected {:?}, actual {:?}",
                expected.columns, actual.columns
            ));
        }
        if expected.columns.len() < 2 || !expected.columns[0].eq_ignore_ascii_case("Index") {
            return Err(format!(
                "default .prn relational output requires an indexed table, got columns {:?}",
                expected.columns
            ));
        }
        if expected.rows.is_empty() || actual.rows.is_empty() {
            return Err(format!(
                "default .prn relational output must be nonempty, got {} baseline row(s) and {} target row(s)",
                expected.rows.len(),
                actual.rows.len()
            ));
        }
        if expected.rows.len() != actual.rows.len() {
            return Err(format!(
                "default .prn row count differs: expected {}, actual {}",
                expected.rows.len(),
                actual.rows.len()
            ));
        }

        let mut mismatches = Vec::new();
        for (row_index, (expected_row, actual_row)) in
            expected.rows.iter().zip(&actual.rows).enumerate()
        {
            if expected_row.len() != expected.columns.len()
                || actual_row.len() != actual.columns.len()
            {
                return Err(format!(
                    "default .prn row {row_index} width differs from its column layout"
                ));
            }
            let canonical_index = row_index as Value;
            if expected_row[0].to_bits() != canonical_index.to_bits()
                || actual_row[0].to_bits() != canonical_index.to_bits()
            {
                return Err(format!(
                    "default .prn row {row_index} does not preserve the canonical Index sequence: expected table {}, actual table {}",
                    expected_row[0], actual_row[0]
                ));
            }
            for column_index in 1..expected.columns.len() {
                let expected_value = expected_row[column_index];
                let actual_value = actual_row[column_index];
                let expected_text = Self::xyce_default_prn_text(expected_value).map_err(|err| {
                    format!(
                        "could not serialize baseline row {row_index} column '{}': {err}",
                        expected.columns[column_index]
                    )
                })?;
                let actual_text = Self::xyce_default_prn_text(actual_value).map_err(|err| {
                    format!(
                        "could not serialize target row {row_index} column '{}': {err}",
                        actual.columns[column_index]
                    )
                })?;
                if expected_text == actual_text {
                    continue;
                }
                let scale = expected_value
                    .abs()
                    .max(actual_value.abs())
                    .max(Value::MIN_POSITIVE);
                mismatches.push(XyceValueMismatch {
                    row: row_index,
                    probe: expected.columns[column_index].clone(),
                    expected: expected_value,
                    actual: actual_value,
                    relative_error: (expected_value - actual_value).abs() / scale,
                });
                if mismatches.len() >= self.config.max_mismatches {
                    return Ok(mismatches);
                }
            }
        }
        Ok(mismatches)
    }

    fn compare_exact_dc_prn_tables(
        &self,
        expected: &XycePrnTable,
        actual: &XycePrnTable,
        expected_raw_sweep: &[Value],
        actual_raw_sweep: &[Value],
    ) -> Result<Vec<XyceValueMismatch>, String> {
        self.compare_exact_prn_tables_with_axis(
            expected,
            actual,
            expected_raw_sweep,
            actual_raw_sweep,
            "DC_SWEEP",
        )
    }

    fn compare_exact_prn_tables_with_axis(
        &self,
        expected: &XycePrnTable,
        actual: &XycePrnTable,
        expected_raw_axis: &[Value],
        actual_raw_axis: &[Value],
        axis_name: &str,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        if expected_raw_axis.len() != expected.rows.len()
            || actual_raw_axis.len() != actual.rows.len()
        {
            return Err(format!(
                "exact relational raw {axis_name} lengths ({}, {}) do not match table row counts ({}, {})",
                expected_raw_axis.len(),
                actual_raw_axis.len(),
                expected.rows.len(),
                actual.rows.len()
            ));
        }
        if expected_raw_axis.len() != actual_raw_axis.len() {
            return Err(format!(
                "exact relational raw {axis_name} count differs: expected {}, actual {}",
                expected_raw_axis.len(),
                actual_raw_axis.len()
            ));
        }
        let mut axis_mismatches = Vec::new();
        for (row, (&expected, &actual)) in expected_raw_axis.iter().zip(actual_raw_axis).enumerate()
        {
            if !expected.is_finite() || !actual.is_finite() {
                return Err(format!(
                    "exact relational raw {axis_name} row {row} contains non-finite value(s): expected {expected}, actual {actual}"
                ));
            }
            if expected.to_bits() != actual.to_bits() {
                axis_mismatches.push(XyceValueMismatch {
                    row,
                    probe: axis_name.to_string(),
                    expected,
                    actual,
                    relative_error: (expected - actual).abs()
                        / expected.abs().max(actual.abs()).max(Value::MIN_POSITIVE),
                });
                if axis_mismatches.len() >= self.config.max_mismatches {
                    return Ok(axis_mismatches);
                }
            }
        }
        if !axis_mismatches.is_empty() {
            return Ok(axis_mismatches);
        }

        if expected.columns != actual.columns {
            return Err(format!(
                "exact relational columns differ: expected {:?}, actual {:?}",
                expected.columns, actual.columns
            ));
        }
        if expected.rows.len() != actual.rows.len() {
            return Err(format!(
                "exact relational row count differs: expected {}, actual {}",
                expected.rows.len(),
                actual.rows.len()
            ));
        }

        let mut mismatches = Vec::new();
        for (row_index, (expected_row, actual_row)) in
            expected.rows.iter().zip(&actual.rows).enumerate()
        {
            if expected_row.len() != expected.columns.len()
                || actual_row.len() != actual.columns.len()
            {
                return Err(format!(
                    "exact relational row {row_index} width differs from its column layout"
                ));
            }
            for (column_index, (&expected_value, &actual_value)) in
                expected_row.iter().zip(actual_row).enumerate()
            {
                if !expected_value.is_finite() || !actual_value.is_finite() {
                    return Err(format!(
                        "exact relational row {row_index} column '{}' contains non-finite value(s): expected {expected_value}, actual {actual_value}",
                        expected.columns[column_index]
                    ));
                }
                if expected_value.to_bits() == actual_value.to_bits() {
                    continue;
                }
                let scale = expected_value
                    .abs()
                    .max(actual_value.abs())
                    .max(f64::MIN_POSITIVE);
                let relative_error = (expected_value - actual_value).abs() / scale;
                mismatches.push(XyceValueMismatch {
                    row: row_index,
                    probe: expected.columns[column_index].clone(),
                    expected: expected_value,
                    actual: actual_value,
                    relative_error,
                });
                if mismatches.len() >= self.config.max_mismatches {
                    return Ok(mismatches);
                }
            }
        }
        Ok(mismatches)
    }

    fn run_static_dc_results(
        &self,
        plan: &XyceStaticDcPlan,
        start: Instant,
    ) -> Result<(Netlist, Vec<DcSweepPointResult>), SimulationError> {
        if !plan.steps.is_empty() {
            return Err(SimulationError::Netlist(
                ".STEP static DC execution requires the stepped .prn contract".to_string(),
            ));
        }
        let netlist = Self::parse_netlist_with_expression_dialect(
            &plan.source,
            &plan.deck_path,
            plan.expression_dialect,
        )
        .map_err(|err| SimulationError::Netlist(format!("{err}")))?;
        let engine = self.create_dc_engine();
        let abort = DeadlineAbort::new(start, self.config.max_time_per_test_ms.max(1));
        let results = engine.run_dc_sweep2_spec_with_report_and_abort(
            &netlist,
            &plan.dc.source,
            &plan.dc.primary_spec(),
            plan.dc.sweep2.as_ref(),
            &abort,
        )?;
        Ok((netlist, results))
    }

    fn run_static_dc_data_results(
        &self,
        base_netlist: &Netlist,
        dc_data: &XyceDcDataSweep,
        start: Instant,
    ) -> Result<Vec<XyceDcDataPointResult>, SimulationError> {
        let engine = self.create_dc_engine();
        let abort = DeadlineAbort::new(start, self.config.max_time_per_test_ms.max(1));
        let mut results = Vec::with_capacity(dc_data.rows.len());

        for (row_index, row) in dc_data.rows.iter().enumerate() {
            if abort.is_aborted() {
                return Err(SimulationError::Aborted);
            }
            let row_netlist = Self::materialize_dc_data_row_netlist(&engine, base_netlist, row)?;
            let (result, device_op_report) =
                engine.run_dc_op_with_report(&row_netlist).map_err(|err| {
                    SimulationError::Circuit(format!(
                        ".DC DATA row {} operating point failed: {}",
                        row_index + 1,
                        err
                    ))
                })?;
            results.push(XyceDcDataPointResult {
                netlist: row_netlist,
                point: DcSweepPointResult {
                    // Xyce exposes .DC DATA's synthetic independent variable
                    // as the one-based table-row ordinal. This axis drives
                    // measurement windows and point-event interpolation.
                    sweep_value: (row_index + 1) as Value,
                    result,
                    device_op_report,
                },
            });
        }

        Ok(results)
    }

    fn materialize_dc_data_row_netlist(
        engine: &Engine,
        base_netlist: &Netlist,
        row: &XyceDcDataRow,
    ) -> Result<Netlist, SimulationError> {
        let param_overrides = row
            .overrides
            .iter()
            .filter_map(|override_| match override_ {
                XyceDcDataOverride::Parameter { name, value } => Some((name.clone(), *value)),
                XyceDcDataOverride::Device { .. } => None,
            })
            .collect::<Vec<_>>();
        let (mut row_netlist, param_bindings) = if param_overrides.is_empty() {
            (base_netlist.clone(), 0)
        } else {
            Engine::create_perturbed_netlist_multi(base_netlist, &param_overrides)?
        };
        if !param_overrides.is_empty() && base_netlist.source_text.is_some() && param_bindings == 0
        {
            let names = param_overrides
                .iter()
                .map(|(name, _)| name.as_str())
                .collect::<Vec<_>>()
                .join(", ");
            return Err(SimulationError::Circuit(format!(
                ".DC DATA parameter override(s) {names} are not bound to any netlist expression"
            )));
        }

        for override_ in &row.overrides {
            let XyceDcDataOverride::Device {
                name,
                param_name,
                value,
            } = override_
            else {
                continue;
            };
            let step = StepCommand {
                target: StepTarget::Device,
                name: name.clone(),
                param_name: param_name.clone(),
                sweep: StepSweep::List(vec![*value]),
            };
            let mut stepped = engine.step_netlists_for_command(&row_netlist, &step, &[*value])?;
            let Some((_, next_netlist)) = stepped.pop() else {
                return Err(SimulationError::Circuit(format!(
                    ".DC DATA device override '{}' produced no stepped netlist",
                    name
                )));
            };
            row_netlist = next_netlist;
        }

        Ok(row_netlist)
    }

    fn dc_results_to_prn_table(
        &self,
        plan: &XyceStaticDcPlan,
        netlist: &Netlist,
        results: &[DcSweepPointResult],
    ) -> Result<XycePrnTable, String> {
        if !plan.steps.is_empty() {
            return Err(".STEP static DC results require the stepped .prn contract".to_string());
        }
        let mut columns = Vec::with_capacity(plan.print.probes.len() + 1);
        columns.push("Index".to_string());
        columns.extend(plan.print.probes.iter().cloned());

        let primary_points = plan.dc.primary_spec().points();
        if primary_points.is_empty() {
            return Err("primary DC sweep has no points".to_string());
        }
        let secondary_points = plan.dc.sweep2.as_ref().map(|sweep| sweep.spec().points());
        if secondary_points.as_ref().is_some_and(Vec::is_empty) {
            return Err("secondary DC sweep has no points".to_string());
        }

        let mut rows = Vec::with_capacity(results.len());
        for (row_index, point) in results.iter().enumerate() {
            let sweep_point = XyceDcSweepPoint {
                primary: point.sweep_value,
                secondary: if let Some(points) = secondary_points.as_ref() {
                    let outer_index = row_index / primary_points.len();
                    Some(*points.get(outer_index).ok_or_else(|| {
                        format!(
                            "row {row_index} maps outside secondary DC sweep point count ({})",
                            points.len()
                        )
                    })?)
                } else {
                    None
                },
            };

            let mut row = Vec::with_capacity(columns.len());
            row.push(row_index as f64);
            for probe in &plan.print.probes {
                row.push(Self::evaluate_dc_probe(
                    probe,
                    netlist,
                    &plan.dc,
                    sweep_point,
                    &point.result,
                    &point.device_op_report,
                )?);
            }
            rows.push(row);
        }

        Ok(XycePrnTable { columns, rows })
    }

    fn create_dc_engine(&self) -> Engine {
        self.create_xyce_engine()
    }

    fn create_xyce_engine(&self) -> Engine {
        self.create_xyce_engine_with_locked_time_grid(None)
    }

    fn create_xyce_engine_with_locked_time_grid(
        &self,
        locked_time_grid: Option<Vec<Value>>,
    ) -> Engine {
        Engine::new(self.xyce_engine_config(locked_time_grid))
    }

    fn create_xyce_static_tran_engine(
        &self,
        locked_time_grid: Option<Vec<Value>>,
        initial_timestep: Option<Value>,
    ) -> Engine {
        let mut config = self.xyce_engine_config(locked_time_grid);
        config.transient_initial_timestep = initial_timestep;
        config.integration_method = crate::analysis::IntegrationMethod::Trapezoidal;
        Engine::new(config)
    }

    fn create_xyce_static_tran_engine_with_integration_method(
        &self,
        locked_time_grid: Option<Vec<Value>>,
        integration_method: crate::analysis::IntegrationMethod,
        initial_timestep: Option<Value>,
    ) -> Engine {
        let mut config = self.xyce_engine_config(locked_time_grid);
        config.transient_initial_timestep = initial_timestep;
        config.integration_method = integration_method;
        Engine::new(config)
    }

    fn xyce_engine_config(&self, locked_time_grid: Option<Vec<Value>>) -> SimulationConfig {
        let defaults = SimulationConfig::default();
        let mut convergence_config = ConvergenceConfig::robust();
        // Xyce 7.10 DeviceOptions uses an independent RELTOL=1e-4 for
        // device-current/voltage convergence.  Its nonlinear-solver residual
        // status test remains at 1e-3, so do not replace the whole convergence
        // tolerance set with the device default.
        convergence_config.voltage_reltol = 1.0e-4;
        SimulationConfig {
            max_iterations: defaults.max_iterations.max(1200),
            convergence_config,
            spice_dialect: SpiceDialect::Xyce,
            // Xyce and ngspice regression decks use 27 C unless overridden.
            temperature: 300.15,
            locked_time_grid: locked_time_grid.map(Arc::new),
            ..defaults
        }
    }

    fn transient_print_requests_linear_capacitor_branch_quantity(
        netlist: &Netlist,
        print: &XycePrintRequest,
    ) -> bool {
        print.probes.iter().any(|probe| {
            Self::transient_probe_requests_linear_capacitor_branch_quantity(netlist, probe)
        })
    }

    fn transient_probe_requests_linear_capacitor_branch_quantity(
        netlist: &Netlist,
        probe: &str,
    ) -> bool {
        let normalized = Self::normalize_probe(probe);
        if Self::normalized_probe_requests_linear_capacitor_branch_quantity(netlist, &normalized) {
            return true;
        }

        let Some(expression) = Self::print_expression_inner(probe) else {
            return false;
        };
        let normalized_expression = Self::normalize_probe(expression);
        if Self::braced_expression_is_atomic_real_probe(&normalized_expression, netlist) {
            return Self::normalized_probe_requests_linear_capacitor_branch_quantity(
                netlist,
                &normalized_expression,
            );
        }

        let mut found = false;
        let mut call_value = |call: &str| {
            if Self::normalized_probe_requests_linear_capacitor_branch_quantity(
                netlist,
                &Self::normalize_probe(call),
            ) {
                found = true;
            }
            Ok(1.0)
        };
        let _ = Self::evaluate_print_expression_with_probe_calls(
            expression,
            netlist.params.clone(),
            &mut call_value,
        );
        found
    }

    fn normalized_probe_requests_linear_capacitor_branch_quantity(
        netlist: &Netlist,
        normalized: &str,
    ) -> bool {
        if let Some(element_name) = Self::parse_current_probe(normalized)
            && Self::find_capacitor_element(netlist, &element_name).is_some()
        {
            return true;
        }
        if let Some(element_name) = Self::parse_power_probe(normalized)
            && Self::find_capacitor_element(netlist, &element_name).is_some()
        {
            return true;
        }
        false
    }

    fn compare_dc_prn_reference(
        &self,
        reference: &XycePrnTable,
        print: &XycePrintRequest,
        netlist: &Netlist,
        source: &str,
        dc: &XyceDcSweep,
        results: &[DcSweepPointResult],
    ) -> Result<Vec<XyceValueMismatch>, String> {
        let batches = [XyceDcResultBatch {
            netlist: netlist.clone(),
            results: results.to_vec(),
        }];
        self.compare_dc_prn_reference_batches(reference, print, source, dc, &batches)
    }

    fn compare_dc_data_prn_reference(
        &self,
        reference: &XycePrnTable,
        print: &XycePrintRequest,
        source: &str,
        dc: &XyceDcSweep,
        points: &[XyceDcDataPointResult],
    ) -> Result<Vec<XyceValueMismatch>, String> {
        if reference.columns.is_empty() {
            return Err("reference table has no columns".to_string());
        }
        let has_stepnum_column = reference.columns[0].eq_ignore_ascii_case("STEPNUM");
        let index_column = usize::from(has_stepnum_column);
        let has_index_column = reference
            .columns
            .get(index_column)
            .is_some_and(|column| column.eq_ignore_ascii_case("Index"));
        let data_column_offset = usize::from(has_stepnum_column) + usize::from(has_index_column);
        if data_column_offset == 0 && !Self::reference_columns_are_compact_probe_table(reference) {
            return Err(format!(
                "expected first Xyce .prn column to be Index, STEPNUM, or a compact probe label, got '{}'",
                reference.columns[0]
            ));
        }
        if reference.rows.len() != points.len() {
            return Err(format!(
                "reference row count ({}) does not match .DC DATA row count ({})",
                reference.rows.len(),
                points.len()
            ));
        }

        let mapping_netlist = points
            .first()
            .map(|point| &point.netlist)
            .ok_or_else(|| ".DC DATA comparison has no result rows".to_string())?;
        let data_columns = self.reference_data_columns(
            reference,
            print,
            mapping_netlist,
            data_column_offset,
            has_index_column,
        )?;
        let comp_tolerances = self.comp_tolerances(source, &data_columns)?;

        let mut mismatches = Vec::new();
        for (row_index, point) in points.iter().enumerate() {
            let row = reference
                .rows
                .get(row_index)
                .ok_or_else(|| format!("missing reference row for .DC DATA row {row_index}"))?;
            if row.len() != reference.columns.len() {
                return Err(format!(
                    "row {} has {} values, expected {}",
                    row_index,
                    row.len(),
                    reference.columns.len()
                ));
            }
            if has_stepnum_column {
                let expected_stepnum = row[0];
                if (expected_stepnum - 0.0).abs() > self.config.absolute_tolerance {
                    mismatches.push(XyceValueMismatch {
                        row: row_index,
                        probe: "STEPNUM".to_string(),
                        expected: expected_stepnum,
                        actual: 0.0,
                        relative_error: 1.0,
                    });
                    if mismatches.len() >= self.config.max_mismatches {
                        return Ok(mismatches);
                    }
                }
            }
            if has_index_column {
                let expected_index = row[index_column];
                let actual_index = row_index as Value;
                if (expected_index - actual_index).abs() > self.config.absolute_tolerance {
                    mismatches.push(XyceValueMismatch {
                        row: row_index,
                        probe: "Index".to_string(),
                        expected: expected_index,
                        actual: actual_index,
                        relative_error: 1.0,
                    });
                    if mismatches.len() >= self.config.max_mismatches {
                        return Ok(mismatches);
                    }
                }
            }

            let sweep_point = XyceDcSweepPoint {
                primary: point.point.sweep_value,
                secondary: None,
            };
            for (column_index, column) in data_columns.iter().enumerate() {
                let expected = row[column_index + data_column_offset];
                let (probe, actual) = match column {
                    XyceReferenceColumn::PrimarySweep { name } => {
                        (name.as_str(), sweep_point.primary)
                    }
                    XyceReferenceColumn::Probe { name } => (
                        name.as_str(),
                        Self::evaluate_dc_probe(
                            name,
                            &point.netlist,
                            dc,
                            sweep_point,
                            &point.point.result,
                            &point.point.device_op_report,
                        )?,
                    ),
                };
                let normalized_probe = Self::normalize_probe(probe);
                let tolerance = comp_tolerances
                    .get(&normalized_probe)
                    .copied()
                    .unwrap_or_else(|| self.default_comparison_tolerance(&normalized_probe));
                if let Some(relative_error) = self.value_mismatch(expected, actual, tolerance) {
                    mismatches.push(XyceValueMismatch {
                        row: row_index,
                        probe: probe.to_string(),
                        expected,
                        actual,
                        relative_error,
                    });
                    if mismatches.len() >= self.config.max_mismatches {
                        return Ok(mismatches);
                    }
                }
            }
        }

        Ok(mismatches)
    }

    fn compare_dc_prn_reference_batches(
        &self,
        reference: &XycePrnTable,
        print: &XycePrintRequest,
        source: &str,
        dc: &XyceDcSweep,
        batches: &[XyceDcResultBatch],
    ) -> Result<Vec<XyceValueMismatch>, String> {
        if reference.columns.is_empty() {
            return Err("reference table has no columns".to_string());
        }
        let has_stepnum_column = reference.columns[0].eq_ignore_ascii_case("STEPNUM");
        let index_column = usize::from(has_stepnum_column);
        let has_index_column = reference
            .columns
            .get(index_column)
            .is_some_and(|column| column.eq_ignore_ascii_case("Index"));
        let data_column_offset = usize::from(has_stepnum_column) + usize::from(has_index_column);
        if data_column_offset == 0 && !Self::reference_columns_are_compact_probe_table(reference) {
            return Err(format!(
                "expected first Xyce .prn column to be Index, STEPNUM, or a compact probe label, got '{}'",
                reference.columns[0]
            ));
        }
        let result_count = batches
            .iter()
            .map(|batch| batch.results.len())
            .sum::<usize>();
        if reference.rows.len() != result_count {
            return Err(format!(
                "reference row count ({}) does not match simulation point count ({})",
                reference.rows.len(),
                result_count
            ));
        }

        let mapping_netlist = batches
            .first()
            .map(|batch| &batch.netlist)
            .ok_or_else(|| "DC comparison has no result batches".to_string())?;
        let data_columns = self.reference_data_columns(
            reference,
            print,
            mapping_netlist,
            data_column_offset,
            has_index_column,
        )?;
        let comp_tolerances = self.comp_tolerances(source, &data_columns)?;
        let primary_points = dc.primary_spec().points();
        if primary_points.is_empty() {
            return Err("primary DC sweep has no points".to_string());
        }
        let secondary_points = dc.sweep2.as_ref().map(|sweep| sweep.spec().points());
        if secondary_points.as_ref().is_some_and(Vec::is_empty) {
            return Err("secondary DC sweep has no points".to_string());
        }
        let mut mismatches = Vec::new();
        let mut global_row_index = 0usize;
        for (batch_index, batch) in batches.iter().enumerate() {
            let equation_sweep = batch
                .results
                .iter()
                .map(|point| (point.sweep_value, point.result.clone()))
                .collect::<Vec<_>>();
            let equation_traces = crate::analysis::advanced::evaluate_dc_equation_measurements(
                &batch.netlist,
                &equation_sweep,
            )?;
            let accepted_axis = batch
                .results
                .iter()
                .map(|point| point.sweep_value)
                .collect::<Vec<_>>();
            let segment_starts = secondary_points
                .as_ref()
                .map(|_| {
                    (primary_points.len()..accepted_axis.len())
                        .step_by(primary_points.len())
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default();
            let measurement_output_traces = Self::measurement_output_traces(
                &batch.netlist,
                &accepted_axis,
                data_columns.iter().filter_map(|column| match column {
                    XyceReferenceColumn::Probe { name } => Some(name.as_str()),
                    XyceReferenceColumn::PrimarySweep { .. } => None,
                }),
                "DC",
                "DC_CONT",
                &segment_starts,
                |trace_netlist| {
                    crate::analysis::advanced::evaluate_dc_continuous_measurements(
                        trace_netlist,
                        &equation_sweep,
                    )
                },
            )?;
            for (local_row_index, point) in batch.results.iter().enumerate() {
                let row = reference.rows.get(global_row_index).ok_or_else(|| {
                    format!("missing reference row for simulation row {global_row_index}")
                })?;
                if row.len() != reference.columns.len() {
                    return Err(format!(
                        "row {} has {} values, expected {}",
                        global_row_index,
                        row.len(),
                        reference.columns.len()
                    ));
                }
                if has_stepnum_column {
                    let expected_stepnum = row[0];
                    let actual_stepnum = batch_index as f64;
                    if (expected_stepnum - actual_stepnum).abs() > self.config.absolute_tolerance {
                        mismatches.push(XyceValueMismatch {
                            row: global_row_index,
                            probe: "STEPNUM".to_string(),
                            expected: expected_stepnum,
                            actual: actual_stepnum,
                            relative_error: 1.0,
                        });
                        if mismatches.len() >= self.config.max_mismatches {
                            return Ok(mismatches);
                        }
                    }
                }
                if has_index_column {
                    let expected_index = row[index_column];
                    let actual_index = local_row_index as f64;
                    if (expected_index - actual_index).abs() > self.config.absolute_tolerance {
                        mismatches.push(XyceValueMismatch {
                            row: global_row_index,
                            probe: "Index".to_string(),
                            expected: expected_index,
                            actual: actual_index,
                            relative_error: 1.0,
                        });
                        if mismatches.len() >= self.config.max_mismatches {
                            return Ok(mismatches);
                        }
                    }
                }
                let value_offset = data_column_offset;

                let sweep_point = XyceDcSweepPoint {
                    primary: point.sweep_value,
                    secondary: if let Some(points) = secondary_points.as_ref() {
                        let outer_index = local_row_index / primary_points.len();
                        Some(*points.get(outer_index).ok_or_else(|| {
                            format!(
                                "row {global_row_index} maps outside secondary DC sweep point count ({})",
                                points.len()
                            )
                        })?)
                    } else {
                        None
                    },
                };
                let point_netlist = Self::dc_sweep_point_netlist(&batch.netlist, dc, sweep_point)?;
                let probe_netlist = point_netlist.as_ref().unwrap_or(&batch.netlist);
                for (column_index, column) in data_columns.iter().enumerate() {
                    let expected = row[column_index + value_offset];
                    let (probe, actual) = match column {
                        XyceReferenceColumn::PrimarySweep { name } => {
                            (name.as_str(), sweep_point.primary)
                        }
                        XyceReferenceColumn::Probe { name } => (
                            name.as_str(),
                            if let Some(trace) = equation_traces
                                .iter()
                                .find(|trace| trace.name.eq_ignore_ascii_case(name))
                            {
                                *trace.values.get(local_row_index).ok_or_else(|| {
                                    format!(
                                        "DC equation measure '{}' has no value for row {}",
                                        trace.name, local_row_index
                                    )
                                })?
                            } else if let Some(trace) =
                                measurement_output_traces.get(&name.to_ascii_uppercase())
                            {
                                trace
                                    .iter()
                                    .filter(|(activation_index, _)| {
                                        local_row_index >= *activation_index
                                    })
                                    .map(|(_, value)| *value)
                                    .next_back()
                                    .unwrap_or(0.0)
                            } else {
                                Self::evaluate_dc_probe(
                                    name,
                                    probe_netlist,
                                    dc,
                                    sweep_point,
                                    &point.result,
                                    &point.device_op_report,
                                )?
                            },
                        ),
                    };
                    let normalized_probe = Self::normalize_probe(probe);
                    let tolerance = comp_tolerances
                        .get(&normalized_probe)
                        .copied()
                        .unwrap_or_else(|| self.default_comparison_tolerance(&normalized_probe));
                    if let Some(relative_error) = self.value_mismatch(expected, actual, tolerance) {
                        mismatches.push(XyceValueMismatch {
                            row: global_row_index,
                            probe: probe.to_string(),
                            expected,
                            actual,
                            relative_error,
                        });
                        if mismatches.len() >= self.config.max_mismatches {
                            return Ok(mismatches);
                        }
                    }
                }
                global_row_index += 1;
            }
        }

        Ok(mismatches)
    }

    fn compare_ac_prn_reference(
        &self,
        reference: &XycePrnTable,
        print: &XycePrintRequest,
        netlist: &Netlist,
        source: &str,
        results: &[AcResult],
    ) -> Result<Vec<XyceValueMismatch>, String> {
        self.compare_ac_prn_reference_with_step(reference, print, netlist, source, results, None)
    }

    fn noise_reference_signal_probe(column: &XyceAcReferenceColumn) -> Result<String, String> {
        let probe = column.probe_name();
        let component_prefix = match column.component() {
            XyceAcProbeComponent::Scalar => return Ok(probe.to_string()),
            XyceAcProbeComponent::Real => 'R',
            XyceAcProbeComponent::Imaginary => 'I',
        };
        let normalized = Self::normalize_probe(probe);
        let Some(quantity) = normalized.chars().next() else {
            return Err("empty complex NOISE reference probe".to_string());
        };
        if !matches!(quantity, 'v' | 'i') || !normalized[quantity.len_utf8()..].starts_with('(') {
            return Err(format!(
                "complex NOISE reference probe '{probe}' is not a node voltage or branch current"
            ));
        }
        Ok(format!(
            "{}{component_prefix}{}",
            quantity.to_ascii_uppercase(),
            &normalized[quantity.len_utf8()..]
        ))
    }

    fn compare_noise_prn_reference(
        &self,
        reference: &XycePrnTable,
        print: &XycePrintRequest,
        netlist: &Netlist,
        source: &str,
        results: &[crate::analysis::NoiseResult],
    ) -> Result<Vec<XyceValueMismatch>, String> {
        if reference.columns.is_empty() {
            return Err("reference table has no columns".to_string());
        }
        let mut data_column_offset = 0usize;
        let index_column = reference
            .columns
            .first()
            .is_some_and(|column| column.eq_ignore_ascii_case("Index"))
            .then_some(0usize);
        if index_column.is_some() {
            data_column_offset += 1;
        }
        let frequency_column = reference
            .columns
            .get(data_column_offset)
            .filter(|column| Self::is_ac_frequency_reference_column(column))
            .map(|_| data_column_offset)
            .ok_or_else(|| {
                format!(
                    "expected Xyce NOISE frequency column at position {}, got '{}'",
                    data_column_offset,
                    reference
                        .columns
                        .get(data_column_offset)
                        .map(String::as_str)
                        .unwrap_or("<missing>")
                )
            })?;
        data_column_offset += 1;
        if reference.rows.len() != results.len() {
            return Err(format!(
                "reference row count ({}) does not match NOISE simulation point count ({})",
                reference.rows.len(),
                results.len()
            ));
        }

        let data_columns = Self::reference_ac_data_columns(reference, print, data_column_offset)?;
        let series = crate::analysis::advanced::NoiseSweepSeries::from_sweep(results)
            .ok_or_else(|| "NOISE simulation produced no points".to_string())?;
        let signals = series.signal_map();
        let equation_traces =
            crate::analysis::advanced::evaluate_noise_equation_measurements(netlist, results)?;
        let measurement_output_traces =
            Self::noise_measurement_output_traces(netlist, results, &data_columns)?;
        let comp_columns = data_columns
            .iter()
            .map(|column| XyceReferenceColumn::Probe {
                name: column.probe_name().to_string(),
            })
            .collect::<Vec<_>>();
        let comp_tolerances = self.comp_tolerances(source, &comp_columns)?;
        let frequency_tolerance = XyceComparisonTolerance::from_config(&self.config);

        let mut mismatches = Vec::new();
        for (row_index, (row, result)) in reference.rows.iter().zip(results).enumerate() {
            if row.len() != reference.columns.len() {
                return Err(format!(
                    "row {} has {} values, expected {}",
                    row_index,
                    row.len(),
                    reference.columns.len()
                ));
            }
            if let Some(index_column) = index_column {
                let expected = row[index_column];
                let actual = row_index as Value;
                if (expected - actual).abs() > self.config.absolute_tolerance {
                    mismatches.push(XyceValueMismatch {
                        row: row_index,
                        probe: "Index".to_string(),
                        expected,
                        actual,
                        relative_error: 1.0,
                    });
                }
            }
            let expected_frequency = row[frequency_column];
            if let Some(relative_error) =
                self.value_mismatch(expected_frequency, result.frequency, frequency_tolerance)
            {
                mismatches.push(XyceValueMismatch {
                    row: row_index,
                    probe: reference.columns[frequency_column].clone(),
                    expected: expected_frequency,
                    actual: result.frequency,
                    relative_error,
                });
            }
            for (column_index, column) in data_columns.iter().enumerate() {
                let probe = column.probe_name();
                let signal_probe = Self::noise_reference_signal_probe(column)?;
                let expected = row[column_index + data_column_offset];
                let actual = if column.component() == XyceAcProbeComponent::Scalar
                    && let Some(trace) = equation_traces
                        .iter()
                        .find(|trace| trace.name.eq_ignore_ascii_case(probe))
                {
                    *trace.values.get(row_index).ok_or_else(|| {
                        format!(
                            "NOISE equation measure '{}' has no value for row {}",
                            trace.name, row_index
                        )
                    })?
                } else if column.component() == XyceAcProbeComponent::Scalar
                    && let Some(trace) = measurement_output_traces.get(&probe.to_ascii_uppercase())
                {
                    trace
                        .iter()
                        .filter(|(activation_axis, _)| result.frequency >= *activation_axis)
                        .map(|(_, value)| *value)
                        .next_back()
                        .unwrap_or(0.0)
                } else if let Some(waveform) = signals.iter().find_map(|(name, values)| {
                    name.eq_ignore_ascii_case(&signal_probe).then_some(*values)
                }) {
                    *waveform.get(row_index).ok_or_else(|| {
                        format!("NOISE probe '{probe}' has no value for row {row_index}")
                    })?
                } else if column.component() == XyceAcProbeComponent::Scalar
                    && let Some(expression) = Self::print_expression_inner(probe)
                {
                    let mut context = netlist.params.clone();
                    context.set("FREQ", result.frequency);
                    context.set("FREQUENCY", result.frequency);
                    context.set("HERTZ", result.frequency);
                    for (name, values) in &signals {
                        if let Some(value) = values.get(row_index) {
                            context.set(name, *value);
                        }
                    }
                    let mut call_value = |call: &str| {
                        if call.get(..3).is_some_and(|prefix| {
                            prefix.eq_ignore_ascii_case("dno") || prefix.eq_ignore_ascii_case("dni")
                        }) {
                            let probe = crate::analysis::NoiseContributionProbe::parse(call)
                                .map_err(|err| err.to_string())?;
                            return result.contribution(&probe).map_err(|err| err.to_string());
                        }
                        let normalized = Self::normalize_probe(call);
                        signals
                            .iter()
                            .find_map(|(name, values)| {
                                Self::normalize_probe(name)
                                    .eq_ignore_ascii_case(&normalized)
                                    .then_some(*values)
                            })
                            .and_then(|values| values.get(row_index).copied())
                            .ok_or_else(|| {
                                format!(
                                    "NOISE expression probe '{call}' is unavailable at row {row_index}"
                                )
                            })
                    };
                    Self::evaluate_print_expression_with_probe_calls(
                        expression,
                        context,
                        &mut call_value,
                    )
                    .map_err(|err| {
                        format!("NOISE print expression '{probe}' failed at row {row_index}: {err}")
                    })?
                } else {
                    return Err(format!("NOISE probe '{probe}' is not available"));
                };
                let normalized_probe = Self::normalize_probe(probe);
                let tolerance = comp_tolerances
                    .get(&normalized_probe)
                    .copied()
                    .unwrap_or_else(|| self.default_comparison_tolerance(&normalized_probe));
                if let Some(relative_error) = self.value_mismatch(expected, actual, tolerance) {
                    mismatches.push(XyceValueMismatch {
                        row: row_index,
                        probe: reference.columns[column_index + data_column_offset].clone(),
                        expected,
                        actual,
                        relative_error,
                    });
                }
                if mismatches.len() >= self.config.max_mismatches {
                    mismatches.truncate(self.config.max_mismatches);
                    return Ok(mismatches);
                }
            }
        }
        Ok(mismatches)
    }

    fn noise_measurement_output_traces(
        netlist: &Netlist,
        results: &[crate::analysis::NoiseResult],
        columns: &[XyceAcReferenceColumn],
    ) -> Result<BTreeMap<String, Vec<(Value, Value)>>, String> {
        let requested = columns
            .iter()
            .filter(|column| column.component() == XyceAcProbeComponent::Scalar)
            .map(|column| column.probe_name().to_ascii_uppercase())
            .collect::<BTreeSet<_>>();
        let mut traces = BTreeMap::new();
        for (statement_index, statement) in netlist.measurements.iter().enumerate() {
            let normalized_name = statement.name.to_ascii_uppercase();
            if !requested.contains(&normalized_name)
                || !(statement.analysis.eq_ignore_ascii_case("NOISE")
                    || statement.analysis.eq_ignore_ascii_case("NOISE_CONT"))
            {
                continue;
            }
            let mut trace_netlist = netlist.clone();
            let trace_statement = &mut trace_netlist.measurements[statement_index];
            trace_statement.analysis = "NOISE_CONT".to_string();
            // A negative qualifier is a rolling "Nth event from the end" in
            // Xyce's live output state.  Evaluate the complete event stream,
            // then lag its values below; evaluating the final scalar result
            // would discard the earlier states printed during the sweep.
            let occurrence = match &mut trace_statement.measure_type {
                crate::analysis::MeasureType::When { condition, .. }
                | crate::analysis::MeasureType::Find {
                    when: Some(condition),
                    ..
                }
                | crate::analysis::MeasureType::Derivative {
                    when: Some(condition),
                    ..
                } => {
                    let number = condition.occurrence.number;
                    if number < 0 {
                        condition.occurrence.number = 1;
                    }
                    Some(number)
                }
                _ => None,
            };
            let result_index = trace_netlist.measurements[..=statement_index]
                .iter()
                .filter(|candidate| candidate.analysis.eq_ignore_ascii_case("NOISE_CONT"))
                .count()
                - 1;
            let evaluated = crate::analysis::advanced::evaluate_noise_continuous_measurements(
                &trace_netlist,
                results,
            );
            let measurement = evaluated.get(result_index).ok_or_else(|| {
                format!(
                    "NOISE measurement trace evaluator omitted declaration '{}'",
                    statement.name
                )
            })?;
            if let Some(failure) = &measurement.failure {
                // Failed Xyce measures remain printable and retain their
                // initialized zero value throughout the analysis.
                if measurement.records.is_empty() {
                    traces.insert(normalized_name, Vec::new());
                    continue;
                }
                return Err(format!(
                    "NOISE measurement trace '{}' failed after producing records: {failure}",
                    statement.name
                ));
            }
            let events = measurement
                .records
                .iter()
                .map(|record| {
                    let activation_axis = record.event_axis.or_else(|| {
                        match (record.trigger_axis, record.target_axis) {
                            (Some(trigger), Some(target)) => Some(trigger.max(target)),
                            (None, Some(target)) => Some(target),
                            (Some(trigger), None) => Some(trigger),
                            (None, None) => None,
                        }
                    });
                    activation_axis
                        .map(|axis| (axis, record.value))
                        .ok_or_else(|| {
                            format!(
                                "NOISE measurement trace '{}' has no activation-axis metadata",
                                statement.name
                            )
                        })
                })
                .collect::<Result<Vec<_>, _>>()?;
            let trace = if occurrence.is_some_and(|number| number < 0) {
                let number = occurrence.expect("negative occurrence was checked");
                let lag = number
                    .checked_abs()
                    .and_then(|number| usize::try_from(number - 1).ok())
                    .ok_or_else(|| {
                        format!(
                            "NOISE measurement '{}' has an unrepresentable occurrence {number}",
                            statement.name
                        )
                    })?;
                events
                    .iter()
                    .skip(lag)
                    .zip(&events)
                    .map(|((activation_axis, _), (_, value))| (*activation_axis, *value))
                    .collect()
            } else if statement.analysis.eq_ignore_ascii_case("NOISE") {
                events.into_iter().take(1).collect()
            } else {
                events
            };
            traces.insert(normalized_name, trace);
        }
        Ok(traces)
    }

    fn measurement_output_traces<'a, F>(
        netlist: &Netlist,
        accepted_axis: &[Value],
        requested_names: impl IntoIterator<Item = &'a str>,
        scalar_analysis: &str,
        continuous_analysis: &str,
        segment_starts: &[usize],
        mut evaluate_continuous: F,
    ) -> Result<BTreeMap<String, Vec<(usize, Value)>>, String>
    where
        F: FnMut(&Netlist) -> Vec<crate::analysis::ContinuousMeasureResult>,
    {
        let requested = requested_names
            .into_iter()
            .map(str::to_ascii_uppercase)
            .collect::<BTreeSet<_>>();
        let mut traces = BTreeMap::new();

        for (statement_index, statement) in netlist.measurements.iter().enumerate() {
            let normalized_name = statement.name.to_ascii_uppercase();
            if !requested.contains(&normalized_name)
                || !(statement.analysis.eq_ignore_ascii_case(scalar_analysis)
                    || statement.analysis.eq_ignore_ascii_case(continuous_analysis))
            {
                continue;
            }

            let mut trace_netlist = netlist.clone();
            let trace_statement = &mut trace_netlist.measurements[statement_index];
            trace_statement.analysis = continuous_analysis.to_string();
            // Xyce's live state for a negative occurrence is a rolling Nth
            // event from the end of the events accepted so far.  Ask the
            // continuous evaluator for the complete stream and apply that
            // lag after mapping events to accepted-point traversal order.
            let occurrence = match &mut trace_statement.measure_type {
                crate::analysis::MeasureType::When { condition, .. }
                | crate::analysis::MeasureType::Find {
                    when: Some(condition),
                    ..
                }
                | crate::analysis::MeasureType::Derivative {
                    when: Some(condition),
                    ..
                } => {
                    let number = condition.occurrence.number;
                    if number < 0 {
                        condition.occurrence.number = 1;
                    }
                    Some(number)
                }
                _ => None,
            };
            let result_index = trace_netlist.measurements[..=statement_index]
                .iter()
                .filter(|candidate| candidate.analysis.eq_ignore_ascii_case(continuous_analysis))
                .count()
                - 1;
            let evaluated = evaluate_continuous(&trace_netlist);
            let measurement = evaluated.get(result_index).ok_or_else(|| {
                format!(
                    "{scalar_analysis} measurement trace evaluator omitted declaration '{}'",
                    statement.name
                )
            })?;
            if let Some(failure) = &measurement.failure {
                // A failed measure remains a valid printed column initialized
                // to zero until and unless it produces an event.
                if measurement.records.is_empty() {
                    traces.insert(normalized_name, Vec::new());
                    continue;
                }
                return Err(format!(
                    "{scalar_analysis} measurement trace '{}' failed after producing records: {failure}",
                    statement.name
                ));
            }

            let mut minimum_index = 0usize;
            let mut events = Vec::with_capacity(measurement.records.len());
            for record in &measurement.records {
                let activation_index = Self::continuous_record_activation_index(
                    accepted_axis,
                    segment_starts,
                    record,
                    minimum_index,
                )
                .ok_or_else(|| {
                    format!(
                        "{scalar_analysis} measurement trace '{}' event metadata does not map to the accepted-point traversal",
                        statement.name
                    )
                })?;
                events.push((activation_index, record.value));
                minimum_index = activation_index.saturating_add(1);
            }

            let trace = if occurrence.is_some_and(|number| number < 0) {
                let number = occurrence.expect("negative occurrence was checked");
                let lag = number
                    .checked_abs()
                    .and_then(|number| usize::try_from(number - 1).ok())
                    .ok_or_else(|| {
                        format!(
                            "{scalar_analysis} measurement '{}' has an unrepresentable occurrence {number}",
                            statement.name
                        )
                    })?;
                events
                    .iter()
                    .skip(lag)
                    .zip(&events)
                    .map(|((activation_index, _), (_, value))| (*activation_index, *value))
                    .collect()
            } else if statement.analysis.eq_ignore_ascii_case(scalar_analysis) {
                events.into_iter().take(1).collect()
            } else {
                events
            };
            traces.insert(normalized_name, trace);
        }

        Ok(traces)
    }

    fn continuous_record_activation_index(
        accepted_axis: &[Value],
        segment_starts: &[usize],
        record: &crate::analysis::ContinuousMeasureRecord,
        minimum_index: usize,
    ) -> Option<usize> {
        let locate = |event_axis| {
            Self::accepted_point_activation_index(
                accepted_axis,
                segment_starts,
                event_axis,
                minimum_index,
            )
        };
        if let Some(event_axis) = record.event_axis {
            return locate(event_axis);
        }
        match (record.trigger_axis, record.target_axis) {
            (Some(trigger), Some(target)) => Some(locate(trigger)?.max(locate(target)?)),
            (Some(trigger), None) => locate(trigger),
            (None, Some(target)) => locate(target),
            (None, None) => None,
        }
    }

    fn accepted_point_activation_index(
        accepted_axis: &[Value],
        segment_starts: &[usize],
        event_axis: Value,
        minimum_index: usize,
    ) -> Option<usize> {
        if !event_axis.is_finite() || minimum_index >= accepted_axis.len() {
            return None;
        }
        let segment_starts = segment_starts.iter().copied().collect::<BTreeSet<_>>();
        for index in minimum_index..accepted_axis.len() {
            let axis = accepted_axis[index];
            let scale = axis.abs().max(event_axis.abs()).max(1.0);
            if (axis - event_axis).abs() <= 32.0 * f64::EPSILON * scale {
                return Some(index);
            }
            if index == 0 || segment_starts.contains(&index) {
                continue;
            }
            let previous = accepted_axis[index - 1];
            if event_axis >= previous.min(axis) && event_axis <= previous.max(axis) {
                return Some(index);
            }
        }
        None
    }

    fn compare_ac_data_prn_reference(
        &self,
        reference: &XycePrnTable,
        print: &XycePrintRequest,
        source: &str,
        points: &[XyceAcDataPointResult],
    ) -> Result<Vec<XyceValueMismatch>, String> {
        if reference.columns.is_empty() {
            return Err("reference table has no columns".to_string());
        }

        let mut data_column_offset = 0usize;
        let stepnum_column = reference
            .columns
            .first()
            .is_some_and(|column| column.eq_ignore_ascii_case("STEPNUM"))
            .then_some(0usize);
        if stepnum_column.is_some() {
            data_column_offset += 1;
        }

        let index_column = reference
            .columns
            .get(data_column_offset)
            .is_some_and(|column| column.eq_ignore_ascii_case("Index"))
            .then_some(data_column_offset);
        if index_column.is_some() {
            data_column_offset += 1;
        }

        let frequency_column = reference
            .columns
            .get(data_column_offset)
            .filter(|column| Self::is_ac_frequency_reference_column(column))
            .map(|_| data_column_offset)
            .ok_or_else(|| {
                format!(
                    "expected Xyce .FD.prn frequency column at position {}, got '{}'",
                    data_column_offset,
                    reference
                        .columns
                        .get(data_column_offset)
                        .map(String::as_str)
                        .unwrap_or("<missing>")
                )
            })?;
        data_column_offset += 1;

        if reference.rows.len() != points.len() {
            return Err(format!(
                "reference row count ({}) does not match AC point count ({})",
                reference.rows.len(),
                points.len()
            ));
        }

        let data_columns = Self::reference_ac_data_columns(reference, print, data_column_offset)?;
        let phase_output_radians = Self::source_requests_ac_phase_output_radians(source);
        let comp_columns = data_columns
            .iter()
            .map(|column| XyceReferenceColumn::Probe {
                name: column.probe_name().to_string(),
            })
            .collect::<Vec<_>>();
        let comp_tolerances = self.comp_tolerances(source, &comp_columns)?;
        let frequency_tolerance = XyceComparisonTolerance::from_config(&self.config);

        let mut mismatches = Vec::new();
        for (row_index, (row, point)) in reference.rows.iter().zip(points).enumerate() {
            if row.len() != reference.columns.len() {
                return Err(format!(
                    "row {} has {} values, expected {}",
                    row_index,
                    row.len(),
                    reference.columns.len()
                ));
            }
            if let Some(stepnum_column) = stepnum_column {
                let expected_stepnum = row[stepnum_column];
                if (expected_stepnum - 0.0).abs() > self.config.absolute_tolerance {
                    mismatches.push(XyceValueMismatch {
                        row: row_index,
                        probe: "STEPNUM".to_string(),
                        expected: expected_stepnum,
                        actual: 0.0,
                        relative_error: 1.0,
                    });
                    if mismatches.len() >= self.config.max_mismatches {
                        return Ok(mismatches);
                    }
                }
            }
            if let Some(index_column) = index_column {
                let expected_index = row[index_column];
                let actual_index = row_index as Value;
                if (expected_index - actual_index).abs() > self.config.absolute_tolerance {
                    mismatches.push(XyceValueMismatch {
                        row: row_index,
                        probe: "Index".to_string(),
                        expected: expected_index,
                        actual: actual_index,
                        relative_error: 1.0,
                    });
                    if mismatches.len() >= self.config.max_mismatches {
                        return Ok(mismatches);
                    }
                }
            }

            let expected_frequency = row[frequency_column];
            if let Some(relative_error) = self.value_mismatch(
                expected_frequency,
                point.result.frequency,
                frequency_tolerance,
            ) {
                mismatches.push(XyceValueMismatch {
                    row: row_index,
                    probe: reference.columns[frequency_column].clone(),
                    expected: expected_frequency,
                    actual: point.result.frequency,
                    relative_error,
                });
                if mismatches.len() >= self.config.max_mismatches {
                    return Ok(mismatches);
                }
            }

            for (column_index, column) in data_columns.iter().enumerate() {
                let expected = row[column_index + data_column_offset];
                let actual = Self::evaluate_ac_reference_column(
                    column,
                    &point.netlist,
                    &point.result,
                    phase_output_radians,
                )?;
                let normalized_probe = Self::normalize_probe(column.probe_name());
                let tolerance = comp_tolerances
                    .get(&normalized_probe)
                    .copied()
                    .unwrap_or_else(|| self.default_comparison_tolerance(&normalized_probe));
                if let Some(relative_error) = self.value_mismatch(expected, actual, tolerance) {
                    mismatches.push(XyceValueMismatch {
                        row: row_index,
                        probe: reference.columns[column_index + data_column_offset].clone(),
                        expected,
                        actual,
                        relative_error,
                    });
                    if mismatches.len() >= self.config.max_mismatches {
                        return Ok(mismatches);
                    }
                }
            }
        }

        Ok(mismatches)
    }

    fn compare_ac_prn_reference_with_step(
        &self,
        reference: &XycePrnTable,
        print: &XycePrintRequest,
        netlist: &Netlist,
        source: &str,
        results: &[AcResult],
        expected_step_index: Option<usize>,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        if reference.columns.is_empty() {
            return Err("reference table has no columns".to_string());
        }

        let mut data_column_offset = 0usize;
        let stepnum_column = reference
            .columns
            .first()
            .is_some_and(|column| column.eq_ignore_ascii_case("STEPNUM"))
            .then_some(0usize);
        if stepnum_column.is_some() {
            data_column_offset += 1;
        }

        let index_column = reference
            .columns
            .get(data_column_offset)
            .is_some_and(|column| column.eq_ignore_ascii_case("Index"))
            .then_some(data_column_offset);
        if index_column.is_some() {
            data_column_offset += 1;
        }

        let frequency_column = reference
            .columns
            .get(data_column_offset)
            .filter(|column| Self::is_ac_frequency_reference_column(column))
            .map(|_| data_column_offset)
            .ok_or_else(|| {
                format!(
                    "expected Xyce .FD.prn frequency column at position {}, got '{}'",
                    data_column_offset,
                    reference
                        .columns
                        .get(data_column_offset)
                        .map(String::as_str)
                        .unwrap_or("<missing>")
                )
            })?;
        data_column_offset += 1;

        if reference.rows.len() != results.len() {
            return Err(format!(
                "reference row count ({}) does not match AC simulation point count ({})",
                reference.rows.len(),
                results.len()
            ));
        }

        let data_columns = Self::reference_ac_data_columns(reference, print, data_column_offset)?;
        let equation_traces =
            crate::analysis::advanced::evaluate_ac_equation_measurements(netlist, results)?;
        let measurement_output_traces = Self::measurement_output_traces(
            netlist,
            &results
                .iter()
                .map(|result| result.frequency)
                .collect::<Vec<_>>(),
            data_columns.iter().filter_map(|column| {
                (column.component() == XyceAcProbeComponent::Scalar).then_some(column.probe_name())
            }),
            "AC",
            "AC_CONT",
            &[],
            |trace_netlist| {
                crate::analysis::advanced::evaluate_ac_continuous_measurements(
                    trace_netlist,
                    results,
                )
            },
        )?;
        let phase_output_radians = Self::source_requests_ac_phase_output_radians(source);
        let comp_columns = data_columns
            .iter()
            .map(|column| XyceReferenceColumn::Probe {
                name: column.probe_name().to_string(),
            })
            .collect::<Vec<_>>();
        let comp_tolerances = self.comp_tolerances(source, &comp_columns)?;
        let frequency_tolerance = XyceComparisonTolerance::from_config(&self.config);

        let mut mismatches = Vec::new();
        for (row_index, (row, result)) in reference.rows.iter().zip(results).enumerate() {
            if row.len() != reference.columns.len() {
                return Err(format!(
                    "row {} has {} values, expected {}",
                    row_index,
                    row.len(),
                    reference.columns.len()
                ));
            }
            if let Some(stepnum_column) = stepnum_column {
                let expected_stepnum = row[stepnum_column];
                let actual_stepnum = expected_step_index.unwrap_or(0) as f64;
                if (expected_stepnum - actual_stepnum).abs() > self.config.absolute_tolerance {
                    mismatches.push(XyceValueMismatch {
                        row: row_index,
                        probe: "STEPNUM".to_string(),
                        expected: expected_stepnum,
                        actual: actual_stepnum,
                        relative_error: 1.0,
                    });
                    if mismatches.len() >= self.config.max_mismatches {
                        return Ok(mismatches);
                    }
                }
            }
            if let Some(index_column) = index_column {
                let expected_index = row[index_column];
                let actual_index = row_index as f64;
                if (expected_index - actual_index).abs() > self.config.absolute_tolerance {
                    mismatches.push(XyceValueMismatch {
                        row: row_index,
                        probe: "Index".to_string(),
                        expected: expected_index,
                        actual: actual_index,
                        relative_error: 1.0,
                    });
                    if mismatches.len() >= self.config.max_mismatches {
                        return Ok(mismatches);
                    }
                }
            }

            let expected_frequency = row[frequency_column];
            if let Some(relative_error) =
                self.value_mismatch(expected_frequency, result.frequency, frequency_tolerance)
            {
                mismatches.push(XyceValueMismatch {
                    row: row_index,
                    probe: reference.columns[frequency_column].clone(),
                    expected: expected_frequency,
                    actual: result.frequency,
                    relative_error,
                });
                if mismatches.len() >= self.config.max_mismatches {
                    return Ok(mismatches);
                }
            }

            for (column_index, column) in data_columns.iter().enumerate() {
                let expected = row[column_index + data_column_offset];
                let actual = if let Some(trace) = equation_traces
                    .iter()
                    .find(|trace| trace.name.eq_ignore_ascii_case(column.probe_name()))
                {
                    *trace.values.get(row_index).ok_or_else(|| {
                        format!(
                            "AC equation measure '{}' has no value for row {}",
                            trace.name, row_index
                        )
                    })?
                } else if column.component() == XyceAcProbeComponent::Scalar
                    && let Some(trace) =
                        measurement_output_traces.get(&column.probe_name().to_ascii_uppercase())
                {
                    trace
                        .iter()
                        .filter(|(activation_index, _)| row_index >= *activation_index)
                        .map(|(_, value)| *value)
                        .next_back()
                        .unwrap_or(0.0)
                } else {
                    Self::evaluate_ac_reference_column(
                        column,
                        netlist,
                        result,
                        phase_output_radians,
                    )?
                };
                let normalized_probe = Self::normalize_probe(column.probe_name());
                let tolerance = comp_tolerances
                    .get(&normalized_probe)
                    .copied()
                    .unwrap_or_else(|| self.default_comparison_tolerance(&normalized_probe));
                if let Some(relative_error) = self.value_mismatch(expected, actual, tolerance) {
                    mismatches.push(XyceValueMismatch {
                        row: row_index,
                        probe: reference.columns[column_index + data_column_offset].clone(),
                        expected,
                        actual,
                        relative_error,
                    });
                    if mismatches.len() >= self.config.max_mismatches {
                        return Ok(mismatches);
                    }
                }
            }
        }

        Ok(mismatches)
    }

    fn compare_static_tran_primary_reference(
        &self,
        reference: &XycePrnTable,
        plan: &XyceStaticTranPlan,
        netlist: &Netlist,
        result: &TransientResult,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        match plan.comparison_mode {
            XyceStaticTranComparisonMode::Pointwise => self.compare_tran_prn_reference(
                reference,
                &plan.print,
                netlist,
                &plan.source,
                result,
                plan.wrapper_tolerance,
            ),
            XyceStaticTranComparisonMode::Release710IntegratedRms {
                scientific_precision,
            } => {
                let actual = Self::transient_family_result_to_prn_table(plan, netlist, result)?;
                self.compare_xyce_verify_transient_tables_with_uniform_tolerance(
                    reference,
                    &actual,
                    XyceVerifyTransientTolerance::release_7_10_default(),
                    scientific_precision,
                )
            }
            XyceStaticTranComparisonMode::Release710IntegratedRmsComp {
                scientific_precision,
            } => {
                let actual = Self::transient_family_result_to_prn_table(plan, netlist, result)?;
                let tolerances =
                    Self::xyce_verify_comp_tolerances(&plan.source, &reference.columns[2..])?;
                self.compare_xyce_verify_transient_tables_with_probe_tolerances(
                    reference,
                    &actual,
                    &tolerances,
                    scientific_precision,
                )
            }
        }
    }

    fn compare_tran_prn_reference(
        &self,
        reference: &XycePrnTable,
        print: &XycePrintRequest,
        netlist: &Netlist,
        source: &str,
        result: &TransientResult,
        wrapper_tolerance: Option<XyceComparisonTolerance>,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        let layout = Self::transient_reference_layout(reference)?;
        let data_columns =
            Self::reference_tran_data_columns(reference, print, layout.data_column_offset)?;
        let comp_columns = data_columns
            .iter()
            .map(|probe| XyceReferenceColumn::Probe {
                name: probe.clone(),
            })
            .collect::<Vec<_>>();
        let comp_tolerances = self.comp_tolerances(source, &comp_columns)?;
        let output_initial_interval = Self::output_initial_interval(source)?;
        let tran_time_scale_factor = Self::tran_print_time_scale_factor(source)?;
        Self::validate_transient_result_time_grid(result)?;
        let stateful_waveforms = data_columns
            .iter()
            .map(|probe| Self::derived_tran_probe_waveform(probe, netlist, result))
            .collect::<Result<Vec<_>, _>>()?;

        let mut mismatches = Vec::new();
        for (row_index, row) in reference.rows.iter().enumerate() {
            if row.len() != reference.columns.len() {
                return Err(format!(
                    "row {} has {} values, expected {}",
                    row_index,
                    row.len(),
                    reference.columns.len()
                ));
            }
            if let Some(index_column) = layout.index_column {
                let expected_index = row[index_column];
                let actual_index = row_index as f64;
                if (expected_index - actual_index).abs() > self.config.absolute_tolerance {
                    mismatches.push(XyceValueMismatch {
                        row: row_index,
                        probe: "Index".to_string(),
                        expected: expected_index,
                        actual: actual_index,
                        relative_error: 1.0,
                    });
                    if mismatches.len() >= self.config.max_mismatches {
                        return Ok(mismatches);
                    }
                }
            }

            let reference_time = row[layout.time_column];
            if !reference_time.is_finite() {
                return Err(format!(
                    "row {row_index} has non-finite TIME value {reference_time}"
                ));
            }
            let time = reference_time / tran_time_scale_factor;

            for (column_index, probe) in data_columns.iter().enumerate() {
                let expected = row[column_index + layout.data_column_offset];
                let actual = match &stateful_waveforms[column_index] {
                    Some(values) => {
                        Self::interpolate_transient_waveform_at(&result.time, values, time)?
                    }
                    None => Self::evaluate_tran_probe(probe, netlist, result, time)?,
                };
                let normalized_probe = Self::normalize_probe(probe);
                let tolerance = comp_tolerances
                    .get(&normalized_probe)
                    .copied()
                    .or(wrapper_tolerance)
                    .unwrap_or_else(|| self.default_comparison_tolerance(&normalized_probe));
                if let Some(relative_error) = self.value_mismatch(expected, actual, tolerance) {
                    let time_tolerance = Self::default_prn_time_quantization_tolerance(time);
                    if stateful_waveforms[column_index].is_none()
                        && time_tolerance > 0.0
                        && self.transient_probe_matches_within_time_quantization(
                            probe,
                            netlist,
                            result,
                            time,
                            expected,
                            actual,
                            tolerance,
                            time_tolerance,
                        )?
                    {
                        continue;
                    }
                    if stateful_waveforms[column_index].is_none()
                        && self.transient_probe_matches_reference_time_neighborhood(
                            reference,
                            layout.time_column,
                            row_index,
                            column_index + layout.data_column_offset,
                            actual,
                            tolerance,
                            time_tolerance,
                            tran_time_scale_factor,
                        )
                    {
                        continue;
                    }
                    if stateful_waveforms[column_index].is_none()
                        && let Some(output_interval) = output_initial_interval
                        && self.transient_probe_matches_output_interval_corridor(
                            probe,
                            netlist,
                            result,
                            reference,
                            layout.time_column,
                            row_index,
                            expected,
                            tolerance,
                            output_interval,
                            tran_time_scale_factor,
                        )?
                    {
                        continue;
                    }
                    mismatches.push(XyceValueMismatch {
                        row: row_index,
                        probe: probe.clone(),
                        expected,
                        actual,
                        relative_error,
                    });
                    if mismatches.len() >= self.config.max_mismatches {
                        return Ok(mismatches);
                    }
                }
            }
        }

        Ok(mismatches)
    }

    fn transient_probe_matches_reference_time_neighborhood(
        &self,
        reference: &XycePrnTable,
        time_column: usize,
        row_index: usize,
        data_column: usize,
        actual: Value,
        tolerance: XyceComparisonTolerance,
        time_tolerance: Value,
        time_scale_factor: Value,
    ) -> bool {
        if !actual.is_finite()
            || !time_tolerance.is_finite()
            || time_tolerance < 0.0
            || !time_scale_factor.is_finite()
            || time_scale_factor <= 0.0
        {
            return false;
        }
        let Some(row) = reference.rows.get(row_index) else {
            return false;
        };
        let Some(time) = row
            .get(time_column)
            .copied()
            .map(|reference_time| reference_time / time_scale_factor)
        else {
            return false;
        };
        if !time.is_finite() {
            return false;
        }

        let mut first_row = row_index;
        while first_row > 0
            && Self::reference_time_is_in_prn_neighborhood(
                time,
                reference.rows[first_row - 1]
                    .get(time_column)
                    .copied()
                    .map(|reference_time| reference_time / time_scale_factor),
                time_tolerance,
            )
        {
            first_row -= 1;
        }

        let mut last_row = row_index;
        while last_row + 1 < reference.rows.len()
            && Self::reference_time_is_in_prn_neighborhood(
                time,
                reference.rows[last_row + 1]
                    .get(time_column)
                    .copied()
                    .map(|reference_time| reference_time / time_scale_factor),
                time_tolerance,
            )
        {
            last_row += 1;
        }

        if first_row == last_row {
            return false;
        }

        let mut min_reference = Value::INFINITY;
        let mut max_reference = Value::NEG_INFINITY;
        let mut finite_values = 0usize;
        for row in &reference.rows[first_row..=last_row] {
            let Some(&value) = row.get(data_column) else {
                continue;
            };
            if value.is_finite() {
                finite_values += 1;
                min_reference = min_reference.min(value);
                max_reference = max_reference.max(value);
            }
        }

        finite_values >= 2
            && min_reference.is_finite()
            && max_reference.is_finite()
            && (actual >= min_reference && actual <= max_reference
                || self
                    .value_mismatch(min_reference, actual, tolerance)
                    .is_none()
                || self
                    .value_mismatch(max_reference, actual, tolerance)
                    .is_none())
    }

    fn reference_time_is_in_prn_neighborhood(
        anchor_time: Value,
        candidate_time: Option<Value>,
        time_tolerance: Value,
    ) -> bool {
        let Some(candidate_time) = candidate_time else {
            return false;
        };
        if !anchor_time.is_finite() || !candidate_time.is_finite() {
            return false;
        }
        if candidate_time == anchor_time {
            return true;
        }
        let candidate_tolerance = Self::default_prn_time_quantization_tolerance(candidate_time);
        let neighborhood = time_tolerance.max(candidate_tolerance) * PRN_TIME_NEIGHBOR_HALF_ULPS;
        let binary_roundoff = Value::EPSILON * anchor_time.abs().max(candidate_time.abs());
        neighborhood > 0.0 && (candidate_time - anchor_time).abs() <= neighborhood + binary_roundoff
    }

    fn transient_probe_matches_output_interval_corridor(
        &self,
        probe: &str,
        netlist: &Netlist,
        result: &TransientResult,
        reference: &XycePrnTable,
        time_column: usize,
        row_index: usize,
        expected: Value,
        tolerance: XyceComparisonTolerance,
        output_interval: Value,
        time_scale_factor: Value,
    ) -> Result<bool, String> {
        if !expected.is_finite()
            || !output_interval.is_finite()
            || output_interval <= 0.0
            || !time_scale_factor.is_finite()
            || time_scale_factor <= 0.0
        {
            return Ok(false);
        }
        let Some(row) = reference.rows.get(row_index) else {
            return Ok(false);
        };
        let Some(time) = row
            .get(time_column)
            .copied()
            .map(|reference_time| reference_time / time_scale_factor)
        else {
            return Ok(false);
        };
        if !time.is_finite() {
            return Ok(false);
        }

        let lower_time = reference.rows[..row_index]
            .iter()
            .rev()
            .filter_map(|row| row.get(time_column).copied())
            .map(|reference_time| reference_time / time_scale_factor)
            .find(|candidate| candidate.is_finite() && *candidate < time);
        let upper_time = reference.rows[row_index + 1..]
            .iter()
            .filter_map(|row| row.get(time_column).copied())
            .map(|reference_time| reference_time / time_scale_factor)
            .find(|candidate| candidate.is_finite() && *candidate > time);
        let (Some(lower_time), Some(upper_time)) = (lower_time, upper_time) else {
            return Ok(false);
        };
        let window = upper_time - lower_time;
        if !window.is_finite() || window <= 0.0 || window > 2.5 * output_interval {
            return Ok(false);
        }

        let lower_value = Self::evaluate_tran_probe(probe, netlist, result, lower_time)?;
        let center_value = Self::evaluate_tran_probe(probe, netlist, result, time)?;
        let upper_value = Self::evaluate_tran_probe(probe, netlist, result, upper_time)?;
        if [lower_value, center_value, upper_value]
            .into_iter()
            .any(|candidate| {
                candidate.is_finite()
                    && self
                        .value_mismatch(expected, candidate, tolerance)
                        .is_none()
            })
        {
            return Ok(true);
        }

        let mut min_value = lower_value.min(center_value).min(upper_value);
        let mut max_value = lower_value.max(center_value).max(upper_value);
        for &sample_time in result.time.iter() {
            if sample_time <= lower_time || sample_time >= upper_time {
                continue;
            }
            let sample_value = Self::evaluate_tran_probe(probe, netlist, result, sample_time)?;
            if sample_value.is_finite() {
                min_value = min_value.min(sample_value);
                max_value = max_value.max(sample_value);
            }
        }

        Ok(min_value.is_finite()
            && max_value.is_finite()
            && expected >= min_value.min(max_value)
            && expected <= min_value.max(max_value))
    }

    fn transient_probe_matches_within_time_quantization(
        &self,
        probe: &str,
        netlist: &Netlist,
        result: &TransientResult,
        time: Value,
        expected: Value,
        actual: Value,
        tolerance: XyceComparisonTolerance,
        time_tolerance: Value,
    ) -> Result<bool, String> {
        let Some((&first_time, &last_time)) = result.time.first().zip(result.time.last()) else {
            return Ok(false);
        };
        let mut min_actual = actual;
        let mut max_actual = actual;
        for candidate_time in [time - time_tolerance, time + time_tolerance] {
            if candidate_time < first_time || candidate_time > last_time {
                continue;
            }
            let candidate = Self::evaluate_tran_probe(probe, netlist, result, candidate_time)?;
            if self
                .value_mismatch(expected, candidate, tolerance)
                .is_none()
            {
                return Ok(true);
            }
            if candidate.is_finite() {
                min_actual = min_actual.min(candidate);
                max_actual = max_actual.max(candidate);
            }
        }

        // A Xyce PRN timestamp is already rounded text. Around very steep
        // transitions, the oracle value can belong to the same printed-time
        // neighborhood while the closest simulator samples sit on adjacent
        // printed ticks. Bound the comparison with those immediate local
        // samples without accepting coarse-grid timing drift.
        let sample_window = time_tolerance * PRN_TIME_NEIGHBOR_HALF_ULPS;
        let lower_time = time - sample_window;
        let upper_time = time + sample_window;
        let first_sample = result.time.partition_point(|sample| *sample < lower_time);
        for &sample_time in result.time.iter().skip(first_sample) {
            if sample_time > upper_time {
                break;
            }
            let candidate = Self::evaluate_tran_probe(probe, netlist, result, sample_time)?;
            if self
                .value_mismatch(expected, candidate, tolerance)
                .is_none()
            {
                return Ok(true);
            }
            if candidate.is_finite() {
                min_actual = min_actual.min(candidate);
                max_actual = max_actual.max(candidate);
            }
        }

        Ok(expected.is_finite()
            && min_actual.is_finite()
            && max_actual.is_finite()
            && expected >= min_actual.min(max_actual)
            && expected <= min_actual.max(max_actual))
    }

    fn output_initial_interval(source: &str) -> Result<Option<Value>, String> {
        let mut interval: Option<Value> = None;
        for line in Self::logical_netlist_lines(source) {
            let trimmed = Self::strip_netlist_comment(&line).trim().to_string();
            if trimmed.is_empty() {
                continue;
            }
            let Some(command) = trimmed.split_whitespace().next() else {
                continue;
            };
            if !command.eq_ignore_ascii_case(".options") {
                continue;
            }

            let tokens = Self::split_grouped_whitespace_fields(&trimmed, ".OPTIONS statement")?;
            let token_refs = tokens.iter().map(String::as_str).collect::<Vec<_>>();
            let has_output_package = token_refs
                .iter()
                .skip(1)
                .any(|token| token.eq_ignore_ascii_case("output"));
            if !has_output_package {
                continue;
            }

            let mut index = 1usize;
            while index < token_refs.len() {
                if let Some((raw_key, raw_value, consumed)) =
                    Self::print_option_assignment(&token_refs, index)
                {
                    if raw_key.trim().eq_ignore_ascii_case("initial_interval") {
                        let parsed = crate::netlist::lexer::parse_spice_value(
                            raw_value.trim().trim_matches(['"', '\'']),
                        )
                        .map_err(|err| {
                            format!(
                                "failed to parse OUTPUT INITIAL_INTERVAL value '{}': {err}",
                                raw_value.trim()
                            )
                        })?;
                        if !parsed.is_finite() || parsed <= 0.0 {
                            return Err(format!(
                                "OUTPUT INITIAL_INTERVAL must be positive and finite, got {parsed}"
                            ));
                        }
                        if let Some(existing) = interval {
                            let scale = existing.abs().max(parsed.abs()).max(1.0);
                            if (existing - parsed).abs() > 1.0e-12 * scale {
                                return Err(
                                    "conflicting OUTPUT INITIAL_INTERVAL options are not supported"
                                        .to_string(),
                                );
                            }
                        } else {
                            interval = Some(parsed);
                        }
                    }
                    index += consumed;
                } else {
                    index += 1;
                }
            }
        }

        Ok(interval)
    }

    fn output_interval_schedule(
        source: &str,
    ) -> Result<Option<(Value, Vec<(Value, Value)>)>, String> {
        let Some(initial_interval) = Self::output_initial_interval(source)? else {
            return Ok(None);
        };
        let mut values = Vec::new();
        for line in Self::logical_netlist_lines(source) {
            let trimmed = Self::strip_netlist_comment(&line).trim();
            let tokens = Self::split_grouped_whitespace_fields(trimmed, ".OPTIONS statement")?;
            let token_refs = tokens.iter().map(String::as_str).collect::<Vec<_>>();
            if !token_refs
                .first()
                .is_some_and(|command| command.eq_ignore_ascii_case(".options"))
                || !token_refs
                    .iter()
                    .skip(1)
                    .any(|token| token.eq_ignore_ascii_case("output"))
            {
                continue;
            }
            let mut index = 1usize;
            while index < token_refs.len() {
                if let Some((_key, _value, consumed)) =
                    Self::print_option_assignment(&token_refs, index)
                {
                    index += consumed;
                    continue;
                }
                let token = token_refs[index].trim().trim_matches(['"', '\'']);
                if !token.eq_ignore_ascii_case("output")
                    && let Ok(value) = crate::netlist::lexer::parse_spice_value(token)
                {
                    values.push(value);
                }
                index += 1;
            }
        }
        if values.len() % 2 != 0 {
            return Err(format!(
                "OUTPUT INITIAL_INTERVAL schedule requires time/interval pairs, found {} trailing numeric value(s)",
                values.len()
            ));
        }
        let mut transitions = Vec::with_capacity(values.len() / 2);
        let mut previous_time = Value::NEG_INFINITY;
        for pair in values.chunks_exact(2) {
            let time = pair[0];
            let interval = pair[1];
            if !time.is_finite() || time < 0.0 || time <= previous_time {
                return Err(format!(
                    "OUTPUT interval transition times must be finite, nonnegative, and strictly increasing, got {time} after {previous_time}"
                ));
            }
            if !interval.is_finite() || interval <= 0.0 {
                return Err(format!(
                    "OUTPUT interval after time {time} must be positive and finite, got {interval}"
                ));
            }
            transitions.push((time, interval));
            previous_time = time;
        }
        Ok(Some((initial_interval, transitions)))
    }

    fn tran_print_time_scale_factor(source: &str) -> Result<Value, String> {
        let mut factor: Option<Value> = None;
        for line in Self::logical_netlist_lines(source) {
            let trimmed = Self::strip_netlist_comment(&line).trim().to_string();
            if trimmed.is_empty() {
                continue;
            }
            let Some(command) = trimmed.split_whitespace().next() else {
                continue;
            };
            if !command.eq_ignore_ascii_case(".print") {
                continue;
            }

            let tokens = Self::split_print_fields(&trimmed)?;
            let token_refs = tokens.iter().map(String::as_str).collect::<Vec<_>>();
            if token_refs
                .get(1)
                .is_none_or(|analysis| !analysis.eq_ignore_ascii_case("TRAN"))
            {
                continue;
            }

            let mut index = 2usize;
            let mut line_factor = None;
            while index < token_refs.len() {
                if let Some((raw_key, raw_value, consumed)) =
                    Self::print_option_assignment(&token_refs, index)
                {
                    if raw_key.trim().eq_ignore_ascii_case("TIMESCALEFACTOR") {
                        line_factor = Some(raw_value.trim().trim_matches(['"', '\'']).to_string());
                    }
                    index += consumed;
                } else {
                    break;
                }
            }
            let parsed = match line_factor {
                Some(raw_factor) => crate::netlist::lexer::parse_spice_value(&raw_factor).map_err(
                    |err| {
                        format!(
                            "failed to parse .PRINT TRAN TIMESCALEFACTOR value '{raw_factor}': {err}"
                        )
                    },
                )?,
                None => 1.0,
            };
            if !parsed.is_finite() || parsed <= 0.0 {
                return Err(format!(
                    ".PRINT TRAN TIMESCALEFACTOR must be positive and finite, got {parsed}"
                ));
            }
            if let Some(existing) = factor {
                if existing.to_bits() != parsed.to_bits() {
                    return Err(
                        "different .PRINT TRAN output blocks use conflicting TIMESCALEFACTOR values"
                            .to_string(),
                    );
                }
            } else {
                factor = Some(parsed);
            }
        }

        Ok(factor.unwrap_or(1.0))
    }

    #[cfg(test)]
    fn line_declares_output_snapshots(line: &str) -> Result<bool, String> {
        let tokens = Self::split_grouped_whitespace_fields(line, ".OPTIONS statement")?;
        let token_refs = tokens.iter().map(String::as_str).collect::<Vec<_>>();
        if !token_refs
            .iter()
            .skip(1)
            .any(|token| token.eq_ignore_ascii_case("output"))
        {
            return Ok(false);
        }

        let mut index = 1usize;
        while index < token_refs.len() {
            if let Some((raw_key, raw_value, consumed)) =
                Self::print_option_assignment(&token_refs, index)
            {
                if raw_key.trim().eq_ignore_ascii_case("snapshots") {
                    let value = raw_value.trim().trim_matches(['"', '\'']);
                    return Ok(!matches!(
                        value.to_ascii_lowercase().as_str(),
                        "0" | "false" | "no" | "off"
                    ));
                }
                index += consumed;
            } else {
                index += 1;
            }
        }

        Ok(false)
    }

    fn reference_tran_data_columns(
        reference: &XycePrnTable,
        print: &XycePrintRequest,
        first_data_column: usize,
    ) -> Result<Vec<String>, String> {
        let mut data_columns =
            Vec::with_capacity(reference.columns.len().saturating_sub(first_data_column));
        let mut probe_index = 0usize;
        for column in reference.columns.iter().skip(first_data_column) {
            if let Some(probe) = print.probes.get(probe_index)
                && Self::reference_column_matches_probe(column, probe)
            {
                data_columns.push(probe.clone());
                probe_index += 1;
                continue;
            }

            data_columns.push(column.clone());
        }
        if probe_index != print.probes.len() {
            return Err(format!(
                "reference table matched {} .PRINT TRAN probe(s), but deck requested {}",
                probe_index,
                print.probes.len()
            ));
        }
        Ok(data_columns)
    }

    fn transient_max_step_for_static_plan(
        plan: &XyceStaticTranPlan,
        netlist: &Netlist,
        tran: &XyceTranAnalysis,
        reference: &XycePrnTable,
    ) -> Result<Value, String> {
        match plan.comparison_mode {
            XyceStaticTranComparisonMode::Release710IntegratedRms { .. }
            | XyceStaticTranComparisonMode::Release710IntegratedRmsComp { .. } => {
                Self::transient_max_step_with_optional_reference(netlist, tran, None)
            }
            XyceStaticTranComparisonMode::Pointwise => {
                Self::transient_max_step_for_reference(netlist, tran, reference)
            }
        }
    }

    fn transient_max_step_for_reference(
        netlist: &Netlist,
        tran: &XyceTranAnalysis,
        reference: &XycePrnTable,
    ) -> Result<Value, String> {
        let reference_step = Self::reference_min_positive_time_step(reference)?;
        Self::transient_max_step_with_optional_reference(netlist, tran, reference_step)
    }

    fn transient_max_step_with_optional_reference(
        netlist: &Netlist,
        tran: &XyceTranAnalysis,
        reference_step: Option<Value>,
    ) -> Result<Value, String> {
        let requested = tran.max_step.or_else(|| {
            (tran.step > 0.0)
                .then_some(tran.step)
                .and_then(|step| Self::feasible_oracle_limited_step(tran, step))
        });
        let source_step = Self::source_transient_max_step(netlist, tran)
            .and_then(|step| Self::feasible_oracle_limited_step(tran, step));
        let fallback = (tran.stop / 1000.0).max(f64::MIN_POSITIVE);
        let reference_limited_step = Self::feasible_reference_limited_step(tran, reference_step);
        let fallback_limit = reference_limited_step.is_none().then_some(fallback);
        let mut max_step = [
            requested,
            reference_limited_step,
            source_step,
            fallback_limit,
        ]
        .into_iter()
        .flatten()
        .filter(|value| value.is_finite() && *value > 0.0)
        .reduce(Value::min)
        .unwrap_or(fallback);
        let unconstrained_estimated_steps = (tran.stop / max_step).ceil();
        if unconstrained_estimated_steps > MAX_NATIVE_TRAN_ORACLE_STEPS {
            return Err(format!(
                "transient harness execution envelope supports at most {:.0} native step(s), but this deck requires about {:.0}",
                MAX_NATIVE_TRAN_ORACLE_STEPS, unconstrained_estimated_steps
            ));
        }
        Self::validate_transient_execution_envelope(netlist, unconstrained_estimated_steps)?;
        if let Some(work_limited_step) = Self::compact_device_work_limited_step(netlist, tran)? {
            max_step = max_step.max(work_limited_step);
        }
        if !max_step.is_finite() || max_step <= 0.0 {
            return Err(format!(
                "resolved transient maximum step must be finite and positive, got {max_step}"
            ));
        }
        Ok(max_step)
    }

    fn compact_device_work_limited_step(
        netlist: &Netlist,
        tran: &XyceTranAnalysis,
    ) -> Result<Option<Value>, String> {
        if tran.max_step.is_some() {
            return Ok(None);
        }
        let compact_device_count =
            Self::transient_flattened_problem_size(netlist)?.compact_device_count;
        if compact_device_count == 0 {
            return Ok(None);
        }

        // The harness compares by interpolation. Do not turn one tiny oracle
        // or source-resolution target into hundreds of thousands of globally
        // capped nonlinear solves. This relaxes only the harness-imposed cap;
        // engine LTE control and source breakpoints may still accept smaller
        // steps, and an explicit deck TMAX always wins.
        Ok(Some(
            tran.stop * compact_device_count as Value / MAX_NATIVE_TRAN_TARGET_COMPACT_DEVICE_STEPS,
        ))
    }

    fn validate_transient_execution_envelope(
        netlist: &Netlist,
        estimated_steps: Value,
    ) -> Result<(), String> {
        let size = Self::transient_flattened_problem_size(netlist)?;
        Self::validate_transient_problem_size_envelope(size, estimated_steps)
    }

    fn validate_transient_preflight_execution_envelope(
        netlist: &Netlist,
        tran: &XyceTranAnalysis,
    ) -> Result<(), String> {
        let estimated_steps = Self::preflight_transient_estimated_steps(netlist, tran);
        let size = Self::transient_hierarchy_problem_size_estimate(netlist)?;
        Self::validate_transient_problem_size_envelope(size, estimated_steps)
    }

    fn validate_transient_problem_size_envelope(
        size: XyceTransientProblemSize,
        estimated_steps: Value,
    ) -> Result<(), String> {
        let estimated_element_steps = estimated_steps * size.element_count as Value;
        if estimated_element_steps > MAX_NATIVE_TRAN_ELEMENT_STEPS {
            return Err(format!(
                "transient harness execution envelope supports at most {:.0} native element-step unit(s), but this deck requires about {:.0} ({} flattened element(s) across about {:.0} step(s))",
                MAX_NATIVE_TRAN_ELEMENT_STEPS,
                estimated_element_steps,
                size.element_count,
                estimated_steps
            ));
        }
        let estimated_compact_device_steps = estimated_steps * size.compact_device_count as Value;
        if estimated_compact_device_steps > MAX_NATIVE_TRAN_COMPACT_DEVICE_STEPS {
            return Err(format!(
                "transient harness execution envelope supports at most {:.0} native compact-device step unit(s), but this deck requires about {:.0} ({} flattened compact device(s) across about {:.0} step(s))",
                MAX_NATIVE_TRAN_COMPACT_DEVICE_STEPS,
                estimated_compact_device_steps,
                size.compact_device_count,
                estimated_steps
            ));
        }
        let estimated_node_solve_steps =
            estimated_steps * (size.node_count as Value) * (size.node_count as Value);
        if estimated_node_solve_steps > MAX_NATIVE_TRAN_NODE_SOLVE_STEPS {
            return Err(format!(
                "transient harness execution envelope supports at most {:.0} native node-solve step unit(s), but this deck requires about {:.0} ({} flattened node(s) across about {:.0} step(s))",
                MAX_NATIVE_TRAN_NODE_SOLVE_STEPS,
                estimated_node_solve_steps,
                size.node_count,
                estimated_steps
            ));
        }
        Ok(())
    }

    fn preflight_transient_estimated_steps(netlist: &Netlist, tran: &XyceTranAnalysis) -> Value {
        let requested = tran.max_step.or_else(|| {
            (tran.step > 0.0)
                .then_some(tran.step)
                .and_then(|step| Self::feasible_oracle_limited_step(tran, step))
        });
        let source_step = Self::source_transient_max_step(netlist, tran)
            .and_then(|step| Self::feasible_oracle_limited_step(tran, step));
        let fallback = (tran.stop / 1000.0).max(f64::MIN_POSITIVE);
        let max_step = [requested, source_step, Some(fallback)]
            .into_iter()
            .flatten()
            .filter(|value| value.is_finite() && *value > 0.0)
            .reduce(Value::min)
            .unwrap_or(fallback);
        (tran.stop / max_step).ceil()
    }

    fn transient_flattened_problem_size(
        netlist: &Netlist,
    ) -> Result<XyceTransientProblemSize, String> {
        let elements = if netlist
            .elements
            .iter()
            .any(|element| matches!(element.kind, ElementKind::Subcircuit { .. }))
        {
            crate::netlist::flatten_netlist_with_models(netlist)
                .map(|flattened| flattened.elements)
                .map_err(|err| {
                format!("transient harness execution envelope could not flatten subcircuits for native problem-size estimation: {err}")
            })?
        } else {
            netlist.elements.clone()
        };

        let mut nodes = BTreeSet::new();
        for element in &elements {
            for node in &element.nodes {
                if !Self::node_name_is_ground(node) {
                    nodes.insert(node.to_ascii_lowercase());
                }
            }
        }

        Ok(XyceTransientProblemSize {
            element_count: elements.len(),
            compact_device_count: Self::transient_compact_device_count(&elements),
            node_count: nodes.len(),
        })
    }

    fn transient_hierarchy_problem_size_estimate(
        netlist: &Netlist,
    ) -> Result<XyceTransientProblemSize, String> {
        let mut subcircuits = BTreeMap::new();
        for subcircuit in &netlist.subcircuits {
            Self::collect_subcircuit_defs(subcircuit, &mut subcircuits);
        }

        let mut top_nodes = BTreeSet::new();
        let mut element_count = 0usize;
        let mut compact_device_count = 0usize;
        let mut internal_node_count = 0usize;
        let mut stack = BTreeSet::new();

        for element in &netlist.elements {
            for node in &element.nodes {
                if !Self::node_name_is_ground(node) {
                    top_nodes.insert(node.to_ascii_lowercase());
                }
            }
            if let ElementKind::Subcircuit { subckt_name, .. } = &element.kind {
                let subcircuit =
                    subcircuits
                        .get(&subckt_name.to_ascii_lowercase())
                        .ok_or_else(|| {
                            format!(
                                "transient harness execution envelope cannot estimate unresolved subcircuit '{}'",
                                subckt_name
                            )
                        })?;
                let size =
                    Self::subcircuit_problem_size_estimate(subcircuit, &subcircuits, &mut stack)?;
                element_count += size.element_count;
                compact_device_count += size.compact_device_count;
                internal_node_count += size.node_count;
            } else {
                element_count += 1;
                compact_device_count += Self::transient_element_compact_device_count(element);
            }
        }

        Ok(XyceTransientProblemSize {
            element_count,
            compact_device_count,
            node_count: top_nodes.len() + internal_node_count,
        })
    }

    fn collect_subcircuit_defs<'a>(
        subcircuit: &'a SubcircuitDef,
        defs: &mut BTreeMap<String, &'a SubcircuitDef>,
    ) {
        defs.insert(subcircuit.name.to_ascii_lowercase(), subcircuit);
        for nested in &subcircuit.nested_subcircuits {
            Self::collect_subcircuit_defs(nested, defs);
        }
    }

    fn subcircuit_problem_size_estimate(
        subcircuit: &SubcircuitDef,
        defs: &BTreeMap<String, &SubcircuitDef>,
        stack: &mut BTreeSet<String>,
    ) -> Result<XyceTransientProblemSize, String> {
        let key = subcircuit.name.to_ascii_lowercase();
        if !stack.insert(key.clone()) {
            return Err(format!(
                "transient harness execution envelope cannot estimate recursive subcircuit '{}'",
                subcircuit.name
            ));
        }

        let ports = subcircuit
            .ports
            .iter()
            .map(|port| port.to_ascii_lowercase())
            .collect::<BTreeSet<_>>();
        let mut local_nodes = BTreeSet::new();
        let mut element_count = 0usize;
        let mut compact_device_count = 0usize;
        let mut internal_node_count = 0usize;

        for element in &subcircuit.elements {
            for node in &element.nodes {
                let normalized = node.to_ascii_lowercase();
                if !Self::node_name_is_ground(node) && !ports.contains(&normalized) {
                    local_nodes.insert(normalized);
                }
            }
            if let ElementKind::Subcircuit { subckt_name, .. } = &element.kind {
                let child = defs.get(&subckt_name.to_ascii_lowercase()).ok_or_else(|| {
                    format!(
                        "transient harness execution envelope cannot estimate unresolved subcircuit '{}'",
                        subckt_name
                    )
                })?;
                let size = Self::subcircuit_problem_size_estimate(child, defs, stack)?;
                element_count += size.element_count;
                compact_device_count += size.compact_device_count;
                internal_node_count += size.node_count;
            } else {
                element_count += 1;
                compact_device_count += Self::transient_element_compact_device_count(element);
            }
        }

        stack.remove(&key);
        Ok(XyceTransientProblemSize {
            element_count,
            compact_device_count,
            node_count: local_nodes.len() + internal_node_count,
        })
    }

    fn transient_compact_device_count(elements: &[crate::netlist::Element]) -> usize {
        elements
            .iter()
            .map(Self::transient_element_compact_device_count)
            .sum()
    }

    fn transient_element_compact_device_count(element: &crate::netlist::Element) -> usize {
        matches!(
            element.kind,
            ElementKind::Diode { .. }
                | ElementKind::Bjt { .. }
                | ElementKind::Mosfet { .. }
                | ElementKind::Jfet { .. }
                | ElementKind::Mesfet { .. }
        ) as usize
    }

    fn node_name_is_ground(node: &str) -> bool {
        let normalized = node.trim();
        normalized == "0"
            || normalized.eq_ignore_ascii_case("gnd")
            || normalized.eq_ignore_ascii_case("ground")
    }

    fn xyce_initial_timestep_for_tran(tran: &XyceTranAnalysis) -> Option<Value> {
        let step = if tran.step.is_finite() && tran.step > 0.0 {
            tran.step
        } else {
            1.0e-10
        };
        Some(step.max(1.0e-30))
    }

    fn feasible_reference_limited_step(
        tran: &XyceTranAnalysis,
        reference_step: Option<Value>,
    ) -> Option<Value> {
        let reference_step =
            reference_step.filter(|step| step.is_finite() && *step > f64::MIN_POSITIVE)?;

        // The Xyce accepted cadence can be part of the oracle for dynamic
        // decks, so use the reference minimum spacing when it is affordable.
        // Some Xyce references contain a tiny adaptive gap in an otherwise
        // coarse table; those must fall back to source/requested/final-time
        // limits and be compared by interpolation instead of forcing millions
        // of native steps.
        Self::feasible_oracle_limited_step(tran, reference_step)
    }

    fn feasible_oracle_limited_step(tran: &XyceTranAnalysis, step: Value) -> Option<Value> {
        let step = (step.is_finite() && step > f64::MIN_POSITIVE).then_some(step)?;
        let estimated_steps = (tran.stop / step).ceil();
        (estimated_steps <= MAX_NATIVE_TRAN_ORACLE_STEPS).then_some(step)
    }

    fn source_transient_max_step(netlist: &Netlist, tran: &XyceTranAnalysis) -> Option<Value> {
        netlist
            .elements
            .iter()
            .filter_map(|element| match &element.kind {
                ElementKind::VoltageSource(spec) | ElementKind::CurrentSource(spec) => {
                    Self::source_spec_transient_max_step(spec, tran)
                }
                _ => None,
            })
            .filter(|step| step.is_finite() && *step > 0.0)
            .reduce(Value::min)
    }

    fn source_spec_transient_max_step(
        spec: &crate::netlist::SourceSpec,
        tran: &XyceTranAnalysis,
    ) -> Option<Value> {
        match spec {
            crate::netlist::SourceSpec::Distortion { inner, .. } => {
                Self::source_spec_transient_max_step(inner, tran)
            }
            crate::netlist::SourceSpec::RfPort { inner, .. } => {
                Self::source_spec_transient_max_step(inner, tran)
            }
            crate::netlist::SourceSpec::Dc(_)
            | crate::netlist::SourceSpec::Ac { .. }
            | crate::netlist::SourceSpec::DcAc { .. }
            | crate::netlist::SourceSpec::Pwl { .. }
            | crate::netlist::SourceSpec::PwlFile { .. }
            | crate::netlist::SourceSpec::TrNoise { .. } => None,
            crate::netlist::SourceSpec::DcTransient { transient, .. }
            | crate::netlist::SourceSpec::DcAcTransient { transient, .. } => {
                Self::source_spec_transient_max_step(transient, tran)
            }
            crate::netlist::SourceSpec::Pulse {
                rise,
                fall,
                width,
                period,
                width_defaults_to_zero,
                ..
            } => {
                let tstep_hint = if tran.step.is_finite() && tran.step > 0.0 {
                    tran.step
                } else {
                    (tran.stop / 1000.0).max(f64::MIN_POSITIVE)
                };
                let (_delay, resolved_rise, resolved_fall, resolved_width, resolved_period) =
                    crate::circuit::VoltageSources::resolve_pulse_timing_with_defaults(
                        0.0,
                        *rise,
                        *fall,
                        *width,
                        *period,
                        *width_defaults_to_zero,
                        tstep_hint,
                        tran.stop.max(f64::MIN_POSITIVE),
                        SpiceDialect::Xyce,
                    );
                [
                    Self::positive_duration_step(
                        resolved_rise,
                        TRAN_ORACLE_STEPS_PER_SOURCE_TRANSITION,
                    ),
                    Self::positive_duration_step(
                        resolved_fall,
                        TRAN_ORACLE_STEPS_PER_SOURCE_TRANSITION,
                    ),
                    Self::positive_duration_step(
                        resolved_width,
                        TRAN_ORACLE_STEPS_PER_SOURCE_PERIOD,
                    ),
                    Self::positive_duration_step(
                        resolved_period,
                        TRAN_ORACLE_STEPS_PER_SOURCE_PERIOD,
                    ),
                ]
                .into_iter()
                .flatten()
                .reduce(Value::min)
            }
            crate::netlist::SourceSpec::Pat {
                rise, fall, sample, ..
            } => [
                Self::positive_duration_step(*rise, TRAN_ORACLE_STEPS_PER_SOURCE_TRANSITION),
                Self::positive_duration_step(*fall, TRAN_ORACLE_STEPS_PER_SOURCE_TRANSITION),
                Self::positive_duration_step(*sample, TRAN_ORACLE_STEPS_PER_SOURCE_PERIOD),
            ]
            .into_iter()
            .flatten()
            .reduce(Value::min),
            crate::netlist::SourceSpec::Exp {
                tau1,
                tau2,
                td1,
                td2,
                ..
            } => [
                Self::positive_duration_step(*tau1, TRAN_ORACLE_STEPS_PER_SOURCE_TRANSITION),
                Self::positive_duration_step(*tau2, TRAN_ORACLE_STEPS_PER_SOURCE_TRANSITION),
                Self::positive_duration_step(*td2 - *td1, TRAN_ORACLE_STEPS_PER_SOURCE_PERIOD),
            ]
            .into_iter()
            .flatten()
            .reduce(Value::min),
            crate::netlist::SourceSpec::Sin { frequency, .. } => {
                Self::positive_frequency_step(Self::resolved_sin_frequency(*frequency, tran.stop))
            }
            crate::netlist::SourceSpec::Sffm {
                carrier_freq,
                signal_freq,
                ..
            } => Self::positive_frequency_step(
                Self::resolved_modulated_frequency(*carrier_freq, 5.0, tran.stop).max(
                    Self::resolved_modulated_frequency(*signal_freq, 500.0, tran.stop),
                ),
            ),
            crate::netlist::SourceSpec::Am {
                modulating_freq,
                carrier_freq,
                ..
            } => Self::positive_frequency_step(
                Self::resolved_modulated_frequency(*carrier_freq, 500.0, tran.stop).max(
                    Self::resolved_modulated_frequency(*modulating_freq, 5.0, tran.stop),
                ),
            ),
        }
    }

    fn positive_duration_step(duration: Value, points_per_duration: Value) -> Option<Value> {
        (duration.is_finite() && duration > 0.0 && points_per_duration > 0.0)
            .then_some(duration / points_per_duration)
    }

    fn positive_frequency_step(frequency: Value) -> Option<Value> {
        (frequency.is_finite() && frequency > 0.0)
            .then_some(1.0 / (frequency * TRAN_ORACLE_STEPS_PER_SOURCE_PERIOD))
    }

    fn resolved_sin_frequency(frequency: Value, tstop: Value) -> Value {
        if frequency.is_finite() && frequency > 0.0 {
            frequency
        } else if tstop.is_finite() && tstop > 0.0 {
            1.0 / tstop
        } else {
            1.0e3
        }
    }

    fn resolved_modulated_frequency(
        frequency: Value,
        default_cycles: Value,
        tstop: Value,
    ) -> Value {
        if frequency.is_finite() && frequency > 0.0 {
            frequency
        } else if tstop.is_finite() && tstop > 0.0 {
            default_cycles / tstop
        } else {
            default_cycles * 1.0e3
        }
    }

    fn reference_min_positive_time_step(reference: &XycePrnTable) -> Result<Option<Value>, String> {
        let time_column = Self::reference_time_column_index(reference)
            .ok_or_else(|| "reference table has no TIME column".to_string())?;
        let mut previous = None;
        let mut min_step: Option<Value> = None;
        for (row_index, row) in reference.rows.iter().enumerate() {
            let time = *row.get(time_column).ok_or_else(|| {
                format!("row {row_index} has no TIME column at index {time_column}")
            })?;
            if !time.is_finite() {
                return Err(format!("row {row_index} has non-finite TIME value {time}"));
            }
            if let Some(previous_time) = previous {
                let step = time - previous_time;
                if step < 0.0 {
                    return Err(format!(
                        "reference TIME column is not monotonic at row {row_index}"
                    ));
                }
                if step > 0.0 {
                    min_step = Some(min_step.map_or(step, |current| current.min(step)));
                }
            }
            previous = Some(time);
        }
        Ok(min_step)
    }

    fn reference_time_grid(reference: &XycePrnTable) -> Result<Vec<Value>, String> {
        let time_column = Self::reference_time_column_index(reference)
            .ok_or_else(|| "reference table has no TIME column".to_string())?;
        let mut previous = None;
        let mut grid = Vec::with_capacity(reference.rows.len());
        for (row_index, row) in reference.rows.iter().enumerate() {
            let time = *row.get(time_column).ok_or_else(|| {
                format!("row {row_index} has no TIME column at index {time_column}")
            })?;
            if !time.is_finite() {
                return Err(format!("row {row_index} has non-finite TIME value {time}"));
            }
            if let Some(previous_time) = previous
                && time < previous_time
            {
                return Err(format!(
                    "reference TIME column is not monotonic at row {row_index}"
                ));
            }
            grid.push(time);
            previous = Some(time);
        }
        Ok(grid)
    }

    fn tran_analysis_for_reference_stop(
        contract: XyceStaticTranContract,
        tran: XyceTranAnalysis,
        reference_time_grid: &[Value],
    ) -> XyceTranAnalysis {
        if !contract.can_use_reference_stop() {
            return tran;
        }
        let Some(reference_stop) = reference_time_grid
            .last()
            .copied()
            .filter(|time| time.is_finite() && *time > tran.stop)
        else {
            return tran;
        };

        XyceTranAnalysis {
            stop: reference_stop,
            ..tran
        }
    }

    fn reference_time_column_index(reference: &XycePrnTable) -> Option<usize> {
        Self::transient_reference_layout(reference)
            .ok()
            .map(|layout| layout.time_column)
    }

    fn transient_reference_layout(
        reference: &XycePrnTable,
    ) -> Result<XyceTransientReferenceLayout, String> {
        if reference.columns.is_empty() {
            return Err("reference table has no columns".to_string());
        }

        let mut cursor = 0usize;
        let stepnum_column = reference
            .columns
            .get(cursor)
            .is_some_and(|column| column.eq_ignore_ascii_case("STEPNUM"))
            .then(|| {
                let column = cursor;
                cursor += 1;
                column
            });
        let index_column = reference
            .columns
            .get(cursor)
            .is_some_and(|column| column.eq_ignore_ascii_case("Index"))
            .then(|| {
                let column = cursor;
                cursor += 1;
                column
            });
        let time_column = cursor;
        if reference
            .columns
            .get(time_column)
            .is_none_or(|column| Self::normalize_probe(column) != "time")
        {
            return Err(format!(
                "expected Xyce transient .prn table to contain optional STEPNUM/Index metadata followed by TIME, got columns {:?}",
                reference.columns
            ));
        }

        Ok(XyceTransientReferenceLayout {
            stepnum_column,
            index_column,
            time_column,
            data_column_offset: time_column + 1,
        })
    }

    fn default_prn_time_quantization_tolerance(time: Value) -> Value {
        if !time.is_finite() || time == 0.0 {
            return 0.0;
        }
        0.5 * 10.0_f64.powf(time.abs().log10().floor() - XYCE_DEFAULT_PRN_FRACTION_DIGITS)
    }

    fn compare_step_res_reference(
        &self,
        path: &Path,
        netlist: &Netlist,
        steps: &[StepCommand],
        step_runs: &[XyceStepRun],
    ) -> Result<(), String> {
        let content = fs::read_to_string(path)
            .map_err(|err| format!("{}: {err}", self.display_path(path)))?;
        let mut nonempty_lines = content
            .lines()
            .enumerate()
            .map(|(index, line)| (index + 1, line.trim()))
            .filter(|(_, line)| !line.is_empty());

        let Some((header_line, header)) = nonempty_lines.next() else {
            return Err(format!("{} is empty", self.display_path(path)));
        };
        let header_fields = header.split_whitespace().collect::<Vec<_>>();
        if !header_fields
            .first()
            .is_some_and(|field| field.eq_ignore_ascii_case("STEP"))
        {
            return Err(format!(
                "{} line {header_line} must start with STEP",
                self.display_path(path)
            ));
        }
        let expected_columns = Self::step_res_expected_columns(netlist, steps, step_runs)?;
        if header_fields.len() != expected_columns.len() + 1 {
            return Err(format!(
                "{} line {header_line} has {} columns; expected STEP plus {} .STEP variable column(s)",
                self.display_path(path),
                header_fields.len(),
                expected_columns.len()
            ));
        }
        for (column_index, (expected_name, _)) in expected_columns.iter().enumerate() {
            let actual_name = header_fields[column_index + 1];
            if !actual_name.eq_ignore_ascii_case(expected_name) {
                return Err(format!(
                    "{} line {header_line} .STEP column {} is '{}', expected '{}'",
                    self.display_path(path),
                    column_index + 1,
                    actual_name,
                    expected_name
                ));
            }
        }

        let mut rows = Vec::new();
        for (line_number, line) in nonempty_lines {
            if line.to_ascii_lowercase().starts_with("end of xyce") {
                break;
            }
            rows.push((line_number, line));
        }

        let expected_row_count = expected_columns
            .first()
            .map(|(_, values)| values.len())
            .unwrap_or(0);
        if rows.len() != expected_row_count {
            return Err(format!(
                "{} has {} step row(s), expected {}",
                self.display_path(path),
                rows.len(),
                expected_row_count
            ));
        }

        for (row_index, (line_number, line)) in rows.iter().copied().enumerate() {
            let fields = line.split_whitespace().collect::<Vec<_>>();
            if fields.len() != expected_columns.len() + 1 {
                return Err(format!(
                    "{} line {line_number} has {} columns, expected STEP index plus {} value column(s)",
                    self.display_path(path),
                    fields.len(),
                    expected_columns.len()
                ));
            }
            let actual_index = fields[0].parse::<usize>().map_err(|err| {
                format!(
                    "{} line {line_number} has invalid STEP index '{}': {err}",
                    self.display_path(path),
                    fields[0]
                )
            })?;
            if actual_index != row_index {
                return Err(format!(
                    "{} line {line_number} has STEP index {actual_index}, expected {row_index}",
                    self.display_path(path)
                ));
            }
            for (column_index, (expected_name, expected_values)) in
                expected_columns.iter().enumerate()
            {
                let actual =
                    Self::parse_xyce_numeric_token(fields[column_index + 1]).map_err(|err| {
                        format!(
                            "{} line {line_number} has invalid STEP value '{}': {err}",
                            self.display_path(path),
                            fields[column_index + 1]
                        )
                    })?;
                let expected = expected_values[row_index];
                let tolerance = XyceComparisonTolerance::from_config(&self.config);
                if let Some(relative_error) = self.value_mismatch(expected, actual, tolerance) {
                    return Err(format!(
                        "{} line {line_number} STEP {} expected {:.8e}, actual {:.8e}, rel {:.3e}",
                        self.display_path(path),
                        expected_name,
                        expected,
                        actual,
                        relative_error
                    ));
                }
            }
        }

        Ok(())
    }

    fn step_res_reference_path(deck_path: &Path, reference_path: &Path) -> Option<PathBuf> {
        let output_res_path = reference_path.with_extension("res");
        if output_res_path.is_file() {
            return Some(output_res_path);
        }
        let deck_res_path = Self::deck_sidecar_path(deck_path, "res");
        if deck_res_path.is_file() {
            return Some(deck_res_path);
        }
        None
    }

    fn deck_sidecar_path(deck_path: &Path, extension: &str) -> PathBuf {
        let mut sidecar = deck_path.as_os_str().to_os_string();
        sidecar.push(".");
        sidecar.push(extension);
        PathBuf::from(sidecar)
    }

    fn step_res_expected_columns(
        netlist: &Netlist,
        steps: &[StepCommand],
        step_runs: &[XyceStepRun],
    ) -> Result<Vec<(String, Vec<Value>)>, String> {
        let mut columns = Vec::new();
        for (step_index, step) in steps.iter().enumerate() {
            if step_runs
                .iter()
                .any(|run| run.step_values.len() <= step_index)
            {
                return Err(format!(
                    ".STEP run metadata is missing value {} for {}",
                    step_index,
                    Self::step_res_variable_name(step)
                ));
            }

            if let StepSweep::Data { table_name } = &step.sweep {
                let table = netlist
                    .data_tables
                    .iter()
                    .find(|table| table.name.eq_ignore_ascii_case(table_name))
                    .ok_or_else(|| format!(".STEP DATA table '{table_name}' not found"))?;
                if table.params.is_empty() {
                    return Err(format!(".STEP DATA table '{}' has no columns", table.name));
                }
                if table.rows.is_empty() {
                    return Err(format!(".STEP DATA table '{}' has no rows", table.name));
                }
                let first_new_column = columns.len();
                columns.extend(
                    table
                        .params
                        .iter()
                        .map(|param| (param.clone(), Vec::with_capacity(step_runs.len()))),
                );
                for run in step_runs {
                    let row_index = run.step_values[step_index];
                    if row_index.fract() != 0.0 || row_index < 0.0 {
                        return Err(format!(
                            ".STEP DATA table '{}' row selector {} is not a non-negative integer",
                            table.name, row_index
                        ));
                    }
                    let row_index = row_index as usize;
                    let row = table.rows.get(row_index).ok_or_else(|| {
                        format!(
                            ".STEP DATA table '{}' row selector {} is outside {} row(s)",
                            table.name,
                            row_index,
                            table.rows.len()
                        )
                    })?;
                    if row.len() != table.params.len() {
                        return Err(format!(
                            ".STEP DATA table '{}' row {} has {} value(s), expected {}",
                            table.name,
                            row_index,
                            row.len(),
                            table.params.len()
                        ));
                    }
                    for (column_index, value) in row.iter().copied().enumerate() {
                        columns[first_new_column + column_index].1.push(value);
                    }
                }
                continue;
            }

            columns.push((
                Self::step_res_variable_name(step),
                step_runs
                    .iter()
                    .map(|run| run.step_values[step_index])
                    .collect(),
            ));
        }

        Ok(columns)
    }

    fn step_res_variable_name(step: &StepCommand) -> String {
        match step.target {
            StepTarget::Temp => "TEMP".to_string(),
            StepTarget::Param => step.name.clone(),
            StepTarget::Device | StepTarget::Model => match &step.param_name {
                Some(param_name) => format!("{}:{param_name}", step.name),
                None => step.name.clone(),
            },
        }
    }

    fn parse_xyce_numeric_token(token: &str) -> Result<f64, std::num::ParseFloatError> {
        let normalized = token.trim_end_matches(',');
        normalized
            .parse::<f64>()
            .or_else(|_| normalized.replace(['D', 'd'], "e").parse::<f64>())
    }

    fn reference_data_columns(
        &self,
        reference: &XycePrnTable,
        print: &XycePrintRequest,
        netlist: &Netlist,
        first_data_column: usize,
        ordered_print_columns: bool,
    ) -> Result<Vec<XyceReferenceColumn>, String> {
        let mut data_columns =
            Vec::with_capacity(reference.columns.len().saturating_sub(first_data_column));
        let mut probe_index = 0usize;
        let mut used_probe_indices = BTreeSet::new();
        for column in reference.columns.iter().skip(first_data_column) {
            if Self::is_primary_dc_sweep_reference_column(column) {
                data_columns.push(XyceReferenceColumn::PrimarySweep {
                    name: column.clone(),
                });
                continue;
            }

            let (matched_index, probe) = if ordered_print_columns {
                let mut skipped_omitted_probes = false;
                let probe = loop {
                    let Some(probe) = print.probes.get(probe_index) else {
                        return Err(format!(
                            "reference column '{}' has no matching .PRINT DC probe",
                            column
                        ));
                    };
                    if Self::reference_column_matches_probe(column, probe) {
                        break probe;
                    }
                    if Self::dc_probe_is_omitted_empty_wildcard(probe, netlist) {
                        probe_index += 1;
                        skipped_omitted_probes = true;
                        continue;
                    }
                    let prefix = if skipped_omitted_probes {
                        "after omitted empty wildcard probe(s), "
                    } else {
                        ""
                    };
                    return Err(format!(
                        "{prefix}reference column '{}' does not match .PRINT probe '{}'",
                        column, probe
                    ));
                };
                if probe_index >= print.probes.len() {
                    return Err(format!(
                        "reference column '{}' has no matching .PRINT DC probe",
                        column
                    ));
                }
                (probe_index, probe)
            } else {
                let Some((index, probe)) =
                    print.probes.iter().enumerate().find(|(index, probe)| {
                        !used_probe_indices.contains(index)
                            && Self::reference_column_matches_probe(column, probe)
                    })
                else {
                    return Err(format!(
                        "compact reference column '{}' has no matching .PRINT DC probe",
                        column
                    ));
                };
                (index, probe)
            };
            used_probe_indices.insert(matched_index);
            data_columns.push(XyceReferenceColumn::Probe {
                name: probe.clone(),
            });
            if ordered_print_columns {
                probe_index += 1;
            }
        }
        if ordered_print_columns {
            while let Some(probe) = print.probes.get(probe_index) {
                if !Self::dc_probe_is_omitted_empty_wildcard(probe, netlist) {
                    break;
                }
                probe_index += 1;
            }
        }
        if ordered_print_columns && probe_index != print.probes.len() {
            return Err(format!(
                "reference table matched {} .PRINT DC probe(s), but deck requested {}",
                probe_index,
                print.probes.len()
            ));
        }
        Ok(data_columns)
    }

    fn is_primary_dc_sweep_reference_column(column: &str) -> bool {
        matches!(Self::normalize_probe(column).as_str(), "v-sweep" | "sweep")
    }

    fn reference_column_probe_for_matching(column: &str) -> &str {
        let trimmed = column.trim();
        trimmed
            .strip_prefix('{')
            .and_then(|body| body.strip_suffix('}'))
            .map(str::trim)
            .unwrap_or(trimmed)
    }

    fn canonical_reference_node_name(node: &str) -> &str {
        if node.eq_ignore_ascii_case("gnd") {
            "0"
        } else {
            node
        }
    }

    fn reference_voltage_column_matches_probe(column: &str, probe: &str) -> bool {
        let Some(column_probe) = Self::parse_tran_voltage_probe(column) else {
            return false;
        };
        let Some(requested_probe) = Self::parse_tran_voltage_probe(probe) else {
            return false;
        };
        column_probe.accessor == requested_probe.accessor
            && Self::canonical_reference_node_name(&column_probe.node_pos)
                == Self::canonical_reference_node_name(&requested_probe.node_pos)
            && column_probe
                .node_neg
                .as_deref()
                .map(Self::canonical_reference_node_name)
                == requested_probe
                    .node_neg
                    .as_deref()
                    .map(Self::canonical_reference_node_name)
    }

    fn reference_column_matches_probe(column: &str, probe: &str) -> bool {
        let normalized_column = Self::normalize_probe(column);
        let normalized_probe = Self::normalize_probe(probe);
        if normalized_column == normalized_probe {
            return true;
        }

        let normalized_column =
            Self::normalize_probe(Self::reference_column_probe_for_matching(column));
        let normalized_probe =
            Self::normalize_probe(Self::reference_column_probe_for_matching(probe));
        if normalized_column == normalized_probe {
            return true;
        }
        if Self::reference_voltage_column_matches_probe(&normalized_column, &normalized_probe) {
            return true;
        }
        if let Some(mapped_probe) = Self::compact_reference_probe_alias(&normalized_column) {
            return mapped_probe == normalized_probe;
        }
        if let Some(source_name) = Self::parse_current_probe(&normalized_probe) {
            return normalized_column == format!("{source_name}_branch")
                || normalized_column == format!("{source_name}#branch");
        }
        false
    }

    fn reference_ac_data_columns(
        reference: &XycePrnTable,
        print: &XycePrintRequest,
        data_column_offset: usize,
    ) -> Result<Vec<XyceAcReferenceColumn>, String> {
        let mut columns = Vec::new();
        for column in reference.columns.iter().skip(data_column_offset) {
            if Self::print_requests_scalar_ac_probe(print, column) {
                columns.push(XyceAcReferenceColumn::Probe {
                    name: column.clone(),
                    component: XyceAcProbeComponent::Scalar,
                });
                continue;
            }

            if let Some((component, probe)) = Self::parse_ac_component_reference_column(column) {
                if !Self::print_requests_complex_ac_probe(print, &probe) {
                    return Err(format!(
                        "AC reference column '{}' is not produced by the deck's .PRINT AC probes",
                        column
                    ));
                }
                columns.push(XyceAcReferenceColumn::Probe {
                    name: probe,
                    component,
                });
                continue;
            }

            return Err(format!(
                "AC reference column '{}' is not produced by the deck's .PRINT AC probes",
                column
            ));
        }
        Ok(columns)
    }

    fn is_ac_frequency_reference_column(column: &str) -> bool {
        matches!(Self::normalize_probe(column).as_str(), "freq" | "frequency")
    }

    fn parse_ac_component_reference_column(column: &str) -> Option<(XyceAcProbeComponent, String)> {
        let normalized = Self::normalize_probe(column);
        let (prefix, component) = if normalized.starts_with("re(") {
            ("re(", XyceAcProbeComponent::Real)
        } else if normalized.starts_with("im(") {
            ("im(", XyceAcProbeComponent::Imaginary)
        } else {
            return None;
        };
        if !normalized.ends_with(')') {
            return None;
        }
        let inner = &normalized[prefix.len()..normalized.len() - 1];
        (!inner.is_empty()).then(|| (component, inner.to_string()))
    }

    fn print_requests_complex_ac_probe(print: &XycePrintRequest, probe: &str) -> bool {
        let normalized_probe = Self::normalize_ac_expression_probe_key(probe);
        print
            .probes
            .iter()
            .any(|requested| Self::normalize_ac_expression_probe_key(requested) == normalized_probe)
    }

    fn print_requests_scalar_ac_probe(print: &XycePrintRequest, column: &str) -> bool {
        let normalized_column = Self::normalize_probe(column);
        let normalized_expression_column = Self::normalize_ac_expression_probe_key(column);
        print.probes.iter().any(|requested| {
            Self::normalize_probe(requested) == normalized_column
                || Self::normalize_ac_expression_probe_key(requested)
                    == normalized_expression_column
        })
    }

    fn normalize_ac_expression_probe_key(probe: &str) -> String {
        let expression = Self::print_expression_inner(probe).unwrap_or(probe);
        Self::normalize_probe(expression)
    }

    fn compact_reference_probe_alias(normalized_column: &str) -> Option<&'static str> {
        match normalized_column {
            "v(g)" => Some("v(g,ga)"),
            "v(d)" => Some("v(d,da)"),
            "v(s)" => Some("v(s,sa)"),
            "v(b)" => Some("v(b,ba)"),
            "i(d)" => Some("i(vdprobe)"),
            "i(g)" => Some("i(vgprobe)"),
            "i(s)" => Some("i(vsprobe)"),
            "i(b)" => Some("i(vbprobe)"),
            _ => None,
        }
    }

    fn comp_tolerances(
        &self,
        source: &str,
        columns: &[XyceReferenceColumn],
    ) -> Result<BTreeMap<String, XyceComparisonTolerance>, String> {
        let mut compared_probes = BTreeSet::new();
        for column in columns {
            let XyceReferenceColumn::Probe { name } = column else {
                continue;
            };
            compared_probes.insert(Self::normalize_probe(name));
        }

        let mut tolerances = BTreeMap::new();
        for line in Self::logical_comp_directives(source) {
            let rest = Self::comp_directive_body(&line)
                .expect("logical COMP collector only returns COMP directives");
            let Some((probe, options)) = Self::split_comp_directive(rest) else {
                continue;
            };
            let normalized_probe = Self::normalize_probe(&probe);
            if !compared_probes.contains(&normalized_probe) {
                continue;
            }
            let default_tolerance = self.default_comparison_tolerance(&normalized_probe);
            let tolerance = Self::parse_comp_tolerance(&options, default_tolerance)?;
            tolerances.insert(normalized_probe, tolerance);
        }
        Ok(tolerances)
    }

    fn xyce_verify_comp_tolerances(
        source: &str,
        columns: &[String],
    ) -> Result<Vec<XyceVerifyTransientTolerance>, String> {
        let normalized_columns = columns
            .iter()
            .map(|column| Self::normalize_probe(column))
            .collect::<Vec<_>>();
        let mut tolerances =
            vec![XyceVerifyTransientTolerance::release_7_10_default(); columns.len()];
        let mut assigned = vec![false; columns.len()];
        let mut saw_comp = false;
        for line in Self::logical_comp_directives(source) {
            let rest = Self::comp_directive_body(&line)
                .expect("logical COMP collector only returns COMP directives");
            saw_comp = true;
            let (probe, options) = Self::split_comp_directive(rest).ok_or_else(|| {
                "Xyce *COMP directive is missing its probe expression".to_string()
            })?;
            let tolerance = Self::parse_xyce_verify_comp_tolerance(&options)?;
            let normalized_probe = Self::normalize_probe(&probe);
            let Some(index) = normalized_columns
                .iter()
                .position(|column| *column == normalized_probe)
            else {
                // Release 7.10 stores unreferenced *COMP entries harmlessly;
                // only printed columns consult the resulting tolerance map.
                continue;
            };
            if assigned[index] {
                return Err(format!(
                    "Xyce *COMP defines duplicate tolerances for printed probe '{}'",
                    columns[index]
                ));
            }
            assigned[index] = true;
            tolerances[index] = tolerance;
        }
        if !saw_comp {
            return Err("Xyce integrated-RMS *COMP contract has no *COMP directive".to_string());
        }
        if !assigned.iter().any(|assigned| *assigned) {
            return Err(XYCE_VERIFY_COMP_NO_PRINTED_PROBE.to_string());
        }
        Ok(tolerances)
    }

    fn parse_xyce_verify_comp_tolerance(
        options: &str,
    ) -> Result<XyceVerifyTransientTolerance, String> {
        let mut tolerance = XyceVerifyTransientTolerance::release_7_10_default();
        let tokens = options.split_whitespace().collect::<Vec<_>>();
        let mut seen = BTreeSet::new();
        let mut index = 0usize;
        while index < tokens.len() {
            let token = tokens[index];
            let (raw_key, raw_value, consumed) = if token.ends_with('=') {
                let key = token.trim_end_matches('=');
                let value = tokens.get(index + 1).copied().unwrap_or_default();
                (key, value, 2usize)
            } else if let Some((key, value)) = token.split_once('=') {
                (key, value, 1usize)
            } else if tokens
                .get(index + 1)
                .is_some_and(|candidate| *candidate == "=")
            {
                let value = tokens.get(index + 2).copied().unwrap_or_default();
                (token, value, 3usize)
            } else {
                return Err(format!(
                    "Xyce *COMP option '{token}' must use KEY=VALUE syntax"
                ));
            };
            let key = raw_key.trim().to_ascii_lowercase();
            let value = raw_value.trim();
            if key.is_empty() || value.is_empty() {
                return Err(format!("Xyce *COMP option '{key}' is missing a value"));
            }
            if !seen.insert(key.clone()) {
                return Err(format!("Xyce *COMP option '{key}' is duplicated"));
            }
            let parsed = Self::parse_comp_float(value)?;
            match key.as_str() {
                "reltol" => tolerance.relative = parsed,
                "abstol" => tolerance.absolute = parsed,
                "zerotol" => tolerance.zero = parsed,
                "absdifftol" => tolerance.absolute_difference = parsed,
                "offset" if parsed == 0.0 => {}
                "numfail" if parsed == 0.0 => {}
                "offset" | "numfail" => {
                    return Err(format!(
                        "Xyce integrated-RMS *COMP option {key}={value} requires a broader comparison contract"
                    ));
                }
                _ => return Err(format!("unrecognized Xyce *COMP option '{key}'")),
            }
            index += consumed;
        }
        tolerance.validate()
    }

    fn default_comparison_tolerance(&self, normalized_probe: &str) -> XyceComparisonTolerance {
        let mut tolerance = XyceComparisonTolerance::from_config(&self.config);
        if Self::probe_uses_voltage_tolerance(normalized_probe) {
            tolerance.absolute = self.config.voltage_absolute_tolerance;
        }
        if Self::probe_uses_current_tolerance(normalized_probe) {
            tolerance.zero = Some(
                tolerance
                    .zero
                    .unwrap_or(2.0 * self.config.absolute_tolerance),
            );
        }
        if Self::probe_uses_power_tolerance(normalized_probe) {
            tolerance.absolute = tolerance.absolute.max(self.config.power_absolute_tolerance);
        }
        tolerance
    }

    fn probe_uses_power_tolerance(normalized_probe: &str) -> bool {
        if Self::parse_power_probe(normalized_probe).is_some() {
            return true;
        }
        Self::print_expression_inner(normalized_probe).is_some_and(|expression| {
            Self::parse_power_probe(&Self::normalize_probe(expression)).is_some()
        })
    }

    fn probe_uses_voltage_tolerance(normalized_probe: &str) -> bool {
        normalized_probe == "v-sweep"
            || Self::parse_ac_voltage_probe(normalized_probe)
                .is_some_and(|probe| probe.accessor.uses_voltage_tolerance())
    }

    fn probe_uses_current_tolerance(normalized_probe: &str) -> bool {
        Self::parse_current_probe(normalized_probe).is_some()
            || Self::parse_ac_current_probe(normalized_probe).is_some()
            || Self::parse_lead_current_probe(normalized_probe).is_some()
    }

    fn split_comp_directive(rest: &str) -> Option<(String, String)> {
        let rest = rest
            .split_once(';')
            .map(|(head, _)| head)
            .unwrap_or(rest)
            .trim();
        if rest.is_empty() {
            return None;
        }

        if rest.starts_with('{') {
            let mut depth = 0usize;
            for (index, ch) in rest.char_indices() {
                match ch {
                    '{' => depth += 1,
                    '}' => {
                        depth = depth.saturating_sub(1);
                        if depth == 0 {
                            let end = index + ch.len_utf8();
                            return Some((
                                rest[..end].trim().to_string(),
                                rest[end..].trim().to_string(),
                            ));
                        }
                    }
                    _ => {}
                }
            }
        }

        let mut split = rest.splitn(2, char::is_whitespace);
        let probe = split.next()?.trim();
        if probe.is_empty() {
            return None;
        }
        Some((
            probe.to_string(),
            split.next().unwrap_or_default().trim().to_string(),
        ))
    }

    fn parse_comp_tolerance(
        options: &str,
        default_tolerance: XyceComparisonTolerance,
    ) -> Result<XyceComparisonTolerance, String> {
        let mut tolerance = default_tolerance;
        let tokens = options.split_whitespace().collect::<Vec<_>>();
        let mut index = 0usize;
        while index < tokens.len() {
            let token = tokens[index];
            let (raw_key, raw_value, consumed) = if let Some((key, value)) = token.split_once('=') {
                (key, value, 1usize)
            } else if token.ends_with('=') {
                let key = token.trim_end_matches('=');
                let value = tokens.get(index + 1).copied().unwrap_or_default();
                (key, value, 2usize)
            } else if tokens
                .get(index + 1)
                .is_some_and(|candidate| *candidate == "=")
            {
                let value = tokens.get(index + 2).copied().unwrap_or_default();
                (token, value, 3usize)
            } else {
                index += 1;
                continue;
            };

            let key = raw_key.trim().to_ascii_lowercase();
            let value = raw_value.trim();
            if value.is_empty() {
                return Err(format!("Xyce *COMP option '{key}' is missing a value"));
            }
            match key.as_str() {
                "reltol" => tolerance = tolerance.with_relative(Self::parse_comp_float(value)?),
                "abstol" | "absdifftol" => {
                    tolerance = tolerance.with_absolute(Self::parse_comp_float(value)?)
                }
                "zerotol" => tolerance = tolerance.with_zero(Self::parse_comp_float(value)?),
                _ => {}
            }
            index += consumed;
        }
        Ok(tolerance)
    }

    fn parse_comp_float(value: &str) -> Result<f64, String> {
        value
            .parse::<f64>()
            .map_err(|err| format!("invalid Xyce *COMP numeric value '{value}': {err}"))
    }

    fn value_mismatch(
        &self,
        expected: f64,
        actual: f64,
        tolerance: XyceComparisonTolerance,
    ) -> Option<f64> {
        if !expected.is_finite() || !actual.is_finite() {
            return Some(f64::INFINITY);
        }
        let abs_error = (expected - actual).abs();
        if let Some(zero_tolerance) = tolerance.zero {
            if expected.abs() <= zero_tolerance && actual.abs() <= zero_tolerance {
                return None;
            }
        }
        if abs_error <= tolerance.absolute {
            return None;
        }
        let scale = expected.abs().max(actual.abs()).max(tolerance.absolute);
        let relative_error = abs_error / scale;
        (relative_error > tolerance.relative).then_some(relative_error)
    }

    fn validate_static_dc_contract(
        netlist: &Netlist,
        dc: &XyceDcSweep,
        print: &XycePrintRequest,
    ) -> Result<(), String> {
        Self::validate_dc_sweep_source(netlist, &dc.source)?;
        if let Some(sweep2) = &dc.sweep2 {
            Self::validate_dc_sweep_source(netlist, &sweep2.source)?;
        }

        for probe in &print.probes {
            Self::validate_dc_probe(probe, netlist)?;
        }

        Self::reject_unsupported_static_dc_model_observables(netlist, print)?;
        Self::reject_unsupported_vbic_nested_current_source_sweeps(netlist, dc, print)?;

        Ok(())
    }

    fn validate_static_dc_data_contract(
        netlist: &Netlist,
        dc_data: &XyceDcDataSweep,
        print: &XycePrintRequest,
    ) -> Result<(), String> {
        if dc_data.rows.is_empty() {
            return Err(".DC DATA sweep produced no table rows".to_string());
        }

        for probe in &print.probes {
            Self::validate_dc_probe(probe, netlist)?;
        }
        Self::reject_unsupported_static_dc_model_observables(netlist, print)?;

        Ok(())
    }

    fn dc_data_sweep_for_source(
        source: &str,
        netlist: &Netlist,
    ) -> Result<Option<XyceDcDataSweep>, String> {
        let table_names = Self::dc_data_table_names(source)?;
        if table_names.is_empty() {
            return Ok(None);
        }

        let mut rows: Option<Vec<XyceDcDataRow>> = None;
        let mut seen_columns = BTreeSet::new();
        for table_name in table_names {
            let table = netlist
                .data_tables
                .iter()
                .find(|table| table.name.eq_ignore_ascii_case(&table_name))
                .ok_or_else(|| format!(".DC DATA references unknown .DATA table '{table_name}'"))?;
            if table.params.is_empty() {
                return Err(format!(
                    ".DC DATA table '{}' has no parameter columns",
                    table.name
                ));
            }
            if table.rows.is_empty() {
                return Err(format!(".DC DATA table '{}' has no rows", table.name));
            }
            for (row_index, row) in table.rows.iter().enumerate() {
                if row.len() != table.params.len() {
                    return Err(format!(
                        ".DC DATA table '{}' row {} has {} value(s), expected {}",
                        table.name,
                        row_index + 1,
                        row.len(),
                        table.params.len()
                    ));
                }
            }

            match rows.as_ref() {
                Some(existing) if existing.len() != table.rows.len() => {
                    return Err(format!(
                        ".DC DATA table '{}' has {} row(s), expected {} to match the other TABLE-style .DC DATA sweeps",
                        table.name,
                        table.rows.len(),
                        existing.len()
                    ));
                }
                None => {
                    rows = Some(
                        (0..table.rows.len())
                            .map(|_| XyceDcDataRow {
                                overrides: Vec::new(),
                            })
                            .collect(),
                    );
                }
                Some(_) => {}
            }

            for (column_index, column_name) in table.params.iter().enumerate() {
                let column_key = Self::normalize_probe(column_name);
                if !seen_columns.insert(column_key) {
                    return Err(format!(
                        ".DC DATA column '{}' is specified more than once across the active data tables",
                        column_name
                    ));
                }

                let rows = rows.as_mut().expect("rows initialized from table length");
                for (row_index, row) in table.rows.iter().enumerate() {
                    let value = row[column_index];
                    if !value.is_finite() {
                        return Err(format!(
                            ".DC DATA table '{}' row {} column '{}' contains non-finite value {}",
                            table.name,
                            row_index + 1,
                            column_name,
                            value
                        ));
                    }
                    rows[row_index]
                        .overrides
                        .push(Self::dc_data_override_for_column(
                            netlist,
                            column_name,
                            value,
                        )?);
                }
            }
        }

        let rows = rows.unwrap_or_default();
        if rows.is_empty() {
            return Err(".DC DATA sweep produced no table rows".to_string());
        }
        Ok(Some(XyceDcDataSweep { rows }))
    }

    fn dc_data_override_for_column(
        netlist: &Netlist,
        column_name: &str,
        value: Value,
    ) -> Result<XyceDcDataOverride, String> {
        if let Some((device_name, param_name)) = Self::parse_device_parameter_probe(column_name)
            && Self::netlist_has_top_level_element_named(netlist, &device_name)
        {
            return Ok(XyceDcDataOverride::Device {
                name: device_name,
                param_name: Some(param_name),
                value,
            });
        }

        if Self::netlist_has_top_level_element_named(netlist, column_name) {
            return Ok(XyceDcDataOverride::Device {
                name: column_name.to_string(),
                param_name: None,
                value,
            });
        }

        if Self::netlist_has_numeric_parameter(netlist, column_name) {
            return Ok(XyceDcDataOverride::Parameter {
                name: column_name.to_string(),
                value,
            });
        }

        Err(format!(
            ".DC DATA column '{}' does not resolve to a top-level device value, device parameter, or numeric parameter",
            column_name
        ))
    }

    fn netlist_has_top_level_element_named(netlist: &Netlist, name: &str) -> bool {
        netlist
            .elements
            .iter()
            .any(|element| element.name.eq_ignore_ascii_case(name))
    }

    fn netlist_has_numeric_parameter(netlist: &Netlist, name: &str) -> bool {
        netlist
            .params
            .all_params()
            .iter()
            .any(|(param_name, _)| param_name.eq_ignore_ascii_case(name))
    }

    fn synthetic_dc_data_sweep(dc_data: &XyceDcDataSweep) -> Result<XyceDcSweep, String> {
        if dc_data.rows.is_empty() {
            return Err(".DC DATA sweep produced no table rows".to_string());
        }
        Ok(XyceDcSweep {
            source: "DATA".to_string(),
            start: 0.0,
            stop: (dc_data.rows.len() - 1) as Value,
            step: 1.0,
            mode: crate::netlist::DcSweepMode::Linear,
            sweep2: None,
        })
    }

    fn dc_data_table_names(source: &str) -> Result<Vec<String>, String> {
        let mut table_names = Vec::new();
        for line in Self::logical_netlist_lines(source) {
            let stripped = Self::strip_netlist_comment(&line);
            let trimmed = stripped.trim();
            let Some(command) = trimmed.split_whitespace().next() else {
                continue;
            };
            if !command.eq_ignore_ascii_case(".dc") {
                continue;
            }
            if let Some(table_name) = Self::assignment_value(trimmed, "data")? {
                table_names.push(table_name);
            }
        }
        Ok(table_names)
    }

    fn assignment_value(line: &str, key: &str) -> Result<Option<String>, String> {
        let normalized = Self::normalize_assignment_spacing(line);
        for field in normalized.split_whitespace().skip(1) {
            let Some((name, value)) = field.split_once('=') else {
                continue;
            };
            if !name.eq_ignore_ascii_case(key) {
                continue;
            }
            if value.is_empty() {
                return Err(format!("assignment '{key}=' has no value"));
            }
            return Ok(Some(value.to_string()));
        }
        Ok(None)
    }

    fn normalize_assignment_spacing(line: &str) -> String {
        let mut out = String::with_capacity(line.len());
        let mut chars = line.chars().peekable();
        while let Some(ch) = chars.next() {
            if ch.is_whitespace() {
                while chars.peek().is_some_and(|next| next.is_whitespace()) {
                    chars.next();
                }
                if chars.peek() == Some(&'=') || out.ends_with('=') {
                    continue;
                }
                out.push(' ');
                continue;
            }
            out.push(ch);
        }
        out
    }

    fn validate_static_tran_analysis_contract(
        netlist: &Netlist,
        tran: &XyceTranAnalysis,
        print: &XycePrintRequest,
    ) -> Result<(), String> {
        if !tran.stop.is_finite() || tran.stop <= 0.0 {
            return Err(format!(
                ".TRAN stop time must be finite and positive, got {}",
                tran.stop
            ));
        }
        if !tran.step.is_finite() || tran.step < 0.0 {
            return Err(format!(
                ".TRAN print step must be finite and non-negative, got {}",
                tran.step
            ));
        }
        if let Some(start) = tran.start
            && (!start.is_finite() || start < 0.0 || start > tran.stop)
        {
            return Err(format!(
                ".TRAN start time must be finite and within [0, stop], got {start}"
            ));
        }
        if let Some(max_step) = tran.max_step
            && (!max_step.is_finite() || max_step <= 0.0)
        {
            return Err(format!(
                ".TRAN maximum step must be finite and positive when specified, got {max_step}"
            ));
        }
        // `run_tran` reads UIC from the parsed netlist; the plan carries it so
        // validation still reflects the complete .TRAN command surface.
        let _engine_reads_uic_from_netlist = tran.uic;

        Self::validate_transient_preflight_execution_envelope(netlist, tran)?;
        for probe in &print.probes {
            Self::validate_tran_probe(probe, netlist)?;
        }

        Ok(())
    }

    fn validate_static_ac_contract(
        netlist: &Netlist,
        ac: &XyceAcAnalysis,
        print: &XycePrintRequest,
    ) -> Result<(), String> {
        let frequencies = ac.frequencies();
        if frequencies.is_empty() {
            return Err(".AC analysis produced no frequency points".to_string());
        }

        for measurement in &netlist.measurements {
            if !measurement.analysis.eq_ignore_ascii_case("AC")
                && !measurement.analysis.eq_ignore_ascii_case("AC_CONT")
            {
                return Err(format!(
                    "native static AC comparison does not cover .MEASURE {} '{}'",
                    measurement.analysis, measurement.name
                ));
            }
        }

        for probe in &print.probes {
            Self::validate_ac_probe(probe, netlist)?;
        }
        Self::validate_native_static_ac_contract(netlist, ac)?;

        Ok(())
    }

    fn validate_native_static_ac_contract(
        netlist: &Netlist,
        ac: &XyceAcAnalysis,
    ) -> Result<(), String> {
        let max_frequency = ac
            .frequencies
            .iter()
            .copied()
            .filter(|frequency| frequency.is_finite())
            .fold(0.0_f64, f64::max);
        if netlist
            .elements
            .iter()
            .any(|element| matches!(element.kind, ElementKind::Subcircuit { .. }))
        {
            return Err(
                "native static .PRINT AC comparison does not support subcircuit flattening yet"
                    .to_string(),
            );
        }

        for element in &netlist.elements {
            match &element.kind {
                ElementKind::VoltageSource(_)
                | ElementKind::CurrentSource(_)
                | ElementKind::Resistor { .. }
                | ElementKind::Capacitor { .. }
                | ElementKind::Inductor { .. } => {}
                ElementKind::Coupling { coefficient, .. } => {
                    if !coefficient.is_finite() {
                        return Err(format!(
                            "native static .PRINT AC comparison does not support coupling '{}' with non-finite coefficient {}",
                            element.name, coefficient
                        ));
                    }
                }
                ElementKind::Vccs {
                    transconductance, ..
                } => {
                    Self::validate_finite_controlled_source_gain(
                        "VCCS",
                        &element.name,
                        "transconductance",
                        *transconductance,
                    )?;
                }
                ElementKind::Vcvs { gain, .. } => {
                    Self::validate_finite_controlled_source_gain(
                        "VCVS",
                        &element.name,
                        "gain",
                        *gain,
                    )?;
                }
                ElementKind::Cccs {
                    gain,
                    control_element,
                    ..
                } => {
                    Self::validate_finite_controlled_source_gain(
                        "CCCS",
                        &element.name,
                        "gain",
                        *gain,
                    )?;
                    Self::validate_current_controlled_source_probe(
                        &netlist.elements,
                        "CCCS",
                        &element.name,
                        control_element,
                    )?;
                }
                ElementKind::Ccvs {
                    transresistance,
                    control_element,
                    ..
                } => {
                    Self::validate_finite_controlled_source_gain(
                        "CCVS",
                        &element.name,
                        "transresistance",
                        *transresistance,
                    )?;
                    Self::validate_current_controlled_source_probe(
                        &netlist.elements,
                        "CCVS",
                        &element.name,
                        control_element,
                    )?;
                }
                ElementKind::BehavioralVoltage {
                    expression,
                    tc1,
                    tc2,
                }
                | ElementKind::BehavioralCurrent {
                    expression,
                    tc1,
                    tc2,
                } if tc1.is_finite() && tc2.is_finite() => {
                    Self::validate_ac_behavioral_expression(
                        &element.name,
                        expression,
                        &netlist.params,
                    )?;
                }
                ElementKind::Mosfet { .. }
                    if Self::netlist_device_is_single_native_ac_supported_bulk_mosfet(
                        netlist,
                        &element.name,
                    ) => {}
                ElementKind::Bjt { .. }
                    if max_frequency <= 100.0
                        && Self::netlist_device_is_native_legacy_bjt(netlist, &element.name) => {}
                _ => {
                    return Err(format!(
                        "native static .PRINT AC comparison currently supports independent sources, static R/L/C passives, mutual inductors, finite-gain linear controlled sources, time-independent behavioral sources, strictly qualified single-device classic MOSFET LEVEL=1/2/3/6, and native legacy BJT sweeps up to 100 Hz; element '{}' requires a broader AC oracle contract",
                        element.name
                    ));
                }
            }
        }

        Ok(())
    }

    fn validate_static_step_tran_contract(netlist: &Netlist) -> Result<(), String> {
        for element in &netlist.elements {
            match &element.kind {
                ElementKind::VoltageSource(spec) | ElementKind::CurrentSource(spec) => {
                    Self::validate_static_step_tran_source_spec(&element.name, spec)?;
                }
                ElementKind::Resistor { .. } => {
                    Self::validate_static_step_resistor_contract(netlist, &element.name)?;
                }
                ElementKind::Capacitor { .. } => {
                    Self::validate_static_step_capacitor_contract(netlist, &element.name)?
                }
                ElementKind::Inductor { .. } => {
                    Self::validate_static_step_inductor_contract(netlist, &element.name)?;
                }
                ElementKind::Coupling {
                    inductors,
                    coefficient,
                } => {
                    Self::validate_static_step_coupling_contract(
                        netlist,
                        &element.name,
                        inductors,
                        *coefficient,
                    )?;
                }
                ElementKind::TransmissionLine {
                    z0,
                    td,
                    freq,
                    nl,
                    model,
                } => Self::validate_lossless_transmission_line_contract(
                    &element.name,
                    element.nodes.len(),
                    *z0,
                    *td,
                    *freq,
                    *nl,
                    model.as_deref(),
                )?,
                ElementKind::BehavioralVoltage { expression, .. }
                | ElementKind::BehavioralCurrent { expression, .. } => {
                    Self::validate_static_step_tran_behavioral_expression(
                        &element.name,
                        expression,
                        &netlist.params,
                    )?;
                }
                _ => {
                    return Err(format!(
                        "native .STEP .PRINT TRAN comparison currently supports static R/L/C passives, coupled inductors, independent DC/PULSE/SIN/PWL/PAT sources, and solution-independent behavioral sources; element '{}' requires a broader stepped transient oracle contract",
                        element.name
                    ));
                }
            }
        }
        Ok(())
    }

    fn validate_static_step_resistor_contract(
        netlist: &Netlist,
        element_name: &str,
    ) -> Result<(), String> {
        let resistance = Self::effective_resistor_value(netlist, element_name).ok_or_else(|| {
            format!(
                "native .STEP .PRINT TRAN comparison could not resolve resistor '{}' to a static resistance",
                element_name
            )
        })?;
        if resistance.is_finite() || (resistance.is_infinite() && resistance.is_sign_positive()) {
            Ok(())
        } else {
            Err(format!(
                "native .STEP .PRINT TRAN comparison does not support resistor '{}' with invalid resistance {}",
                element_name, resistance
            ))
        }
    }

    fn validate_static_step_capacitor_contract(
        netlist: &Netlist,
        element_name: &str,
    ) -> Result<(), String> {
        Self::validate_xyce_capacitor_contract_params(netlist, element_name)?;
        let capacitance = Engine::new(SimulationConfig {
            spice_dialect: SpiceDialect::Xyce,
            ..SimulationConfig::default()
        })
        .resolved_capacitor_value(netlist, element_name)
        .map_err(|err| {
            format!(
                "native .PRINT TRAN comparison could not resolve capacitor '{}' to a static capacitance: {}",
                element_name, err
            )
        })?
        .ok_or_else(|| {
            format!(
                "native .PRINT TRAN comparison could not resolve capacitor '{}' to a static capacitance",
                element_name
            )
        })?;
        if capacitance.is_finite() && capacitance >= 0.0 {
            Ok(())
        } else {
            Err(format!(
                "native .PRINT TRAN comparison does not support capacitor '{}' with invalid capacitance {}",
                element_name, capacitance
            ))
        }
    }

    fn validate_xyce_capacitor_contract_params(
        netlist: &Netlist,
        element_name: &str,
    ) -> Result<(), String> {
        let element = Self::find_capacitor_element(netlist, element_name)
            .ok_or_else(|| format!("capacitor '{}' not found", element_name))?;
        let ElementKind::Capacitor {
            value,
            value_expr,
            model,
            instance_params,
            ..
        } = &element.kind
        else {
            return Err(format!("element '{}' is not a capacitor", element_name));
        };

        if !value.is_finite() {
            if let Some(expression) = value_expr.as_deref() {
                Self::validate_static_transient_passive_value_expression(
                    "capacitor",
                    element_name,
                    expression,
                    &netlist.params,
                )?;
            } else if model.is_none() {
                return Err(format!(
                    "native static .PRINT TRAN comparison could not resolve capacitor value for element '{}'",
                    element_name
                ));
            }
        }

        const INSTANCE_PARAMS: &[&str] = &["L", "W", "M", "TEMP", "DTEMP", "TC1", "TC2"];
        for (name, value) in instance_params {
            if !INSTANCE_PARAMS
                .iter()
                .any(|candidate| name.eq_ignore_ascii_case(candidate))
            {
                return Err(format!(
                    "native static .PRINT TRAN comparison does not yet support Xyce capacitor instance parameter {} on element '{}'",
                    name, element_name
                ));
            }
            if !value.is_finite() {
                return Err(format!(
                    "native static .PRINT TRAN comparison does not support capacitor '{}' with non-finite instance parameter {}={}",
                    element_name, name, value
                ));
            }
        }

        let Some(model_name) = model.as_deref() else {
            return Ok(());
        };
        let model = Self::find_model(&netlist.models, model_name).ok_or_else(|| {
            format!(
                "native static .PRINT TRAN comparison could not find capacitor '{}' model '{}'",
                element_name, model_name
            )
        })?;
        if !matches!(
            model.model_type.to_ascii_uppercase().as_str(),
            "C" | "CAP" | "CAPACITOR"
        ) {
            return Err(format!(
                "native static .PRINT TRAN comparison does not support capacitor '{}' model '{}' of type '{}'",
                element_name, model_name, model.model_type
            ));
        }

        const MODEL_PARAMS: &[&str] = &["C", "CJ", "CJSW", "DEFW", "NARROW", "TC1", "TC2", "TNOM"];
        for (name, value) in &model.params {
            if !MODEL_PARAMS
                .iter()
                .any(|candidate| name.eq_ignore_ascii_case(candidate))
            {
                return Err(format!(
                    "native static .PRINT TRAN comparison does not yet support Xyce capacitor model parameter {} on model '{}'",
                    name, model_name
                ));
            }
            if !value.is_finite() {
                return Err(format!(
                    "native static .PRINT TRAN comparison does not support capacitor model '{}' with non-finite parameter {}={}",
                    model_name, name, value
                ));
            }
        }
        for (name, expression) in &model.expr_params {
            if !MODEL_PARAMS
                .iter()
                .any(|candidate| name.eq_ignore_ascii_case(candidate))
            {
                return Err(format!(
                    "native static .PRINT TRAN comparison does not yet support Xyce capacitor model expression parameter {} on model '{}'",
                    name, model_name
                ));
            }
            Self::validate_static_transient_passive_value_expression(
                "capacitor model parameter",
                name,
                expression,
                &netlist.params,
            )?;
        }
        if !model.string_params.is_empty()
            || !model.string_vector_params.is_empty()
            || !model.real_vector_params.is_empty()
            || !model.real_vector_expr_params.is_empty()
            || !model.integer_vector_params.is_empty()
        {
            return Err(format!(
                "native static .PRINT TRAN comparison does not support non-scalar capacitor model parameters on model '{}'",
                model_name
            ));
        }
        Ok(())
    }

    fn validate_static_step_inductor_contract(
        netlist: &Netlist,
        element_name: &str,
    ) -> Result<(), String> {
        let inductance = Self::effective_inductor_value(netlist, element_name).ok_or_else(|| {
            format!(
                "native .STEP .PRINT TRAN comparison could not resolve inductor '{}' to a static inductance",
                element_name
            )
        })?;
        if inductance.is_finite() && inductance > 0.0 {
            Ok(())
        } else {
            Err(format!(
                "native .STEP .PRINT TRAN comparison does not support inductor '{}' with invalid inductance {}",
                element_name, inductance
            ))
        }
    }

    fn validate_static_step_coupling_contract(
        netlist: &Netlist,
        element_name: &str,
        inductors: &[String],
        coefficient: Value,
    ) -> Result<(), String> {
        if inductors.len() < 2 {
            return Err(format!(
                "native .PRINT TRAN comparison does not support coupling '{}' with fewer than two inductors",
                element_name
            ));
        }
        if !coefficient.is_finite() || !(0.0..=1.0).contains(&coefficient) {
            return Err(format!(
                "native .PRINT TRAN comparison does not support coupling '{}' with invalid coefficient {}",
                element_name, coefficient
            ));
        }

        for inductor_name in inductors {
            Self::validate_static_step_inductor_contract(netlist, inductor_name).map_err(
                |err| {
                    format!(
                        "native .PRINT TRAN comparison does not support coupling '{}' because referenced inductor '{}' is not a supported linear inductor: {}",
                        element_name, inductor_name, err
                    )
                },
            )?;
        }
        Ok(())
    }

    fn validate_static_step_tran_source_spec(
        source_name: &str,
        spec: &crate::netlist::SourceSpec,
    ) -> Result<(), String> {
        match spec {
            crate::netlist::SourceSpec::Dc(_)
            | crate::netlist::SourceSpec::Ac { .. }
            | crate::netlist::SourceSpec::DcAc { .. }
            | crate::netlist::SourceSpec::Pulse { .. }
            | crate::netlist::SourceSpec::Sin { .. }
            | crate::netlist::SourceSpec::Pwl { .. }
            | crate::netlist::SourceSpec::PwlFile { .. }
            | crate::netlist::SourceSpec::Pat { .. } => Ok(()),
            crate::netlist::SourceSpec::DcTransient { transient, .. }
            | crate::netlist::SourceSpec::DcAcTransient { transient, .. } => {
                Self::validate_static_step_tran_source_spec(source_name, transient)
            }
            other => Err(format!(
                "native .STEP .PRINT TRAN comparison currently supports independent DC/PULSE/SIN/PWL/PAT sources; source '{source_name}' uses {other:?}"
            )),
        }
    }

    #[cfg(test)]
    fn validate_native_transient_contract(netlist: &Netlist) -> Result<(), String> {
        Self::validate_native_transient_contract_for_purpose(
            netlist,
            XyceStaticTranPlanPurpose::AbsoluteOracle,
        )
    }

    fn validate_native_relational_transient_contract(netlist: &Netlist) -> Result<(), String> {
        Self::validate_native_transient_contract_for_purpose(
            netlist,
            XyceStaticTranPlanPurpose::RelationalFamily,
        )
    }

    fn validate_native_transient_contract_for_purpose(
        netlist: &Netlist,
        purpose: XyceStaticTranPlanPurpose,
    ) -> Result<(), String> {
        if netlist
            .elements
            .iter()
            .any(|element| matches!(element.kind, ElementKind::Subcircuit { .. }))
        {
            let flattened =
                crate::netlist::flatten_netlist_with_models(netlist).map_err(|err| {
                    format!(
                        "native static .PRINT TRAN comparison could not flatten subcircuits: {err}"
                    )
                })?;
            Self::validate_flattened_subcircuit_instances_resolved(netlist, &flattened.elements)?;
            let mut flat_netlist = netlist.clone();
            flat_netlist.elements = flattened.elements;
            flat_netlist.models.extend(flattened.scoped_models);
            flat_netlist
                .initial_conditions
                .extend(flattened.scoped_initial_conditions);
            flat_netlist.node_sets.extend(flattened.scoped_node_sets);
            flat_netlist.subcircuits.clear();
            return Self::validate_native_transient_contract_for_purpose(&flat_netlist, purpose);
        }

        if purpose == XyceStaticTranPlanPurpose::ScopedModelRelationalFamily {
            return Self::validate_native_scoped_model_relational_transient_contract_flat(netlist);
        }

        let elements = &netlist.elements;
        let params = &netlist.params;
        let has_qualified_bjt = purpose.validates_absolute_device_contract()
            && elements.iter().any(|element| {
                Self::netlist_element_is_native_transient_level1_npn(netlist, element)
            });
        let has_qualified_diode = purpose.validates_absolute_device_contract()
            && elements.iter().any(|element| {
                Self::netlist_element_is_native_absolute_transient_exact_is_diode(netlist, element)
            });
        let has_qualified_level9_bsim3 = purpose.admits_default_level9_bsim3()
            && elements.iter().any(|element| {
                Self::netlist_element_is_native_absolute_transient_level9_bsim3(netlist, element)
            });
        if (has_qualified_bjt || has_qualified_diode || has_qualified_level9_bsim3)
            && !Self::native_transient_uses_standard_startup(netlist)
        {
            return Err(
                "native qualified absolute-device transient comparison requires a single ordinary DC operating-point startup at the default 27 C TEMP and TNOM, without UIC/NOOP, .TEMP analyses, explicit initial conditions, or node-set hints"
                    .to_string(),
            );
        }
        for element in elements {
            match &element.kind {
                ElementKind::VoltageSource(_) | ElementKind::CurrentSource(_) => {}
                ElementKind::Vcvs { gain, .. } => {
                    Self::validate_finite_controlled_source_gain(
                        "VCVS",
                        &element.name,
                        "gain",
                        *gain,
                    )?;
                }
                ElementKind::Vccs {
                    transconductance, ..
                } => {
                    Self::validate_finite_controlled_source_gain(
                        "VCCS",
                        &element.name,
                        "transconductance",
                        *transconductance,
                    )?;
                }
                ElementKind::Cccs {
                    gain,
                    control_element,
                    ..
                } => {
                    Self::validate_finite_controlled_source_gain(
                        "CCCS",
                        &element.name,
                        "gain",
                        *gain,
                    )?;
                    Self::validate_current_controlled_source_probe(
                        elements,
                        "CCCS",
                        &element.name,
                        control_element,
                    )?;
                }
                ElementKind::Ccvs {
                    transresistance,
                    control_element,
                    ..
                } => {
                    Self::validate_finite_controlled_source_gain(
                        "CCVS",
                        &element.name,
                        "transresistance",
                        *transresistance,
                    )?;
                    Self::validate_current_controlled_source_probe(
                        elements,
                        "CCVS",
                        &element.name,
                        control_element,
                    )?;
                }
                ElementKind::BehavioralVoltage { expression, .. }
                | ElementKind::BehavioralCurrent { expression, .. } => {
                    Self::validate_transient_behavioral_expression(
                        &element.name,
                        expression,
                        params,
                    )?;
                }
                ElementKind::Resistor { value_expr, .. } => {
                    if let Some(expression) = value_expr {
                        Self::validate_transient_behavioral_expression(
                            &element.name,
                            expression,
                            params,
                        )?;
                    }
                }
                ElementKind::Capacitor { .. } => {
                    Self::validate_static_step_capacitor_contract(netlist, &element.name)?
                }
                ElementKind::Inductor { .. } => {
                    Self::validate_static_step_inductor_contract(netlist, &element.name)?;
                }
                ElementKind::Coupling {
                    inductors,
                    coefficient,
                } => {
                    Self::validate_static_step_coupling_contract(
                        netlist,
                        &element.name,
                        inductors,
                        *coefficient,
                    )?;
                }
                ElementKind::TransmissionLine {
                    z0,
                    td,
                    freq,
                    nl,
                    model,
                } => Self::validate_lossless_transmission_line_contract(
                    &element.name,
                    element.nodes.len(),
                    *z0,
                    *td,
                    *freq,
                    *nl,
                    model.as_deref(),
                )?,
                ElementKind::VSwitch { .. } => {}
                ElementKind::ISwitch {
                    control_element, ..
                } => {
                    Self::validate_current_controlled_source_probe(
                        elements,
                        "ISWITCH",
                        &element.name,
                        control_element,
                    )?;
                }
                ElementKind::GenericSwitch {
                    model,
                    control_expression,
                    ..
                } => {
                    if Self::netlist_model_is_current_switch(netlist, model) {
                        let control_element =
                            Self::direct_branch_current_control(control_expression).ok_or_else(
                                || {
                                    format!(
                                        "native static .PRINT TRAN comparison does not support generic ISWITCH element '{}' with CONTROL expression '{}' because it is not a direct branch-current probe",
                                        element.name, control_expression
                                    )
                                },
                            )?;
                        Self::validate_current_controlled_source_probe(
                            elements,
                            "generic ISWITCH",
                            &element.name,
                            &control_element,
                        )?;
                    } else {
                        Self::validate_transient_generic_switch_expression(
                            &element.name,
                            control_expression,
                            params,
                        )?;
                    }
                }
                ElementKind::Bjt { .. }
                    if purpose.validates_absolute_device_contract()
                        && Self::netlist_element_is_native_transient_level1_npn(
                            netlist, element,
                        ) => {}
                ElementKind::Mosfet { .. }
                    if purpose.admits_default_level9_bsim3()
                        && Self::netlist_element_is_native_absolute_transient_level9_bsim3(
                            netlist, element,
                        ) => {}
                ElementKind::Mosfet { .. }
                    if Self::netlist_device_is_native_b3soi_mosfet(netlist, &element.name) => {}
                ElementKind::Mosfet { .. }
                    if matches!(
                        purpose,
                        XyceStaticTranPlanPurpose::RelationalFamily
                            | XyceStaticTranPlanPurpose::GeneratedReferenceRelationalFamily
                    ) && Self::netlist_device_is_native_relational_mos3(
                        netlist,
                        &element.name,
                    ) => {}
                ElementKind::Jfet { .. }
                    if Self::netlist_device_is_native_classic_jfet(netlist, &element.name) => {}
                ElementKind::Diode { .. }
                    if purpose.validates_absolute_device_contract()
                        && Self::netlist_element_is_native_absolute_transient_exact_is_diode(
                            netlist, element,
                        ) => {}
                ElementKind::Diode { .. }
                    if matches!(
                        purpose,
                        XyceStaticTranPlanPurpose::RelationalFamily
                            | XyceStaticTranPlanPurpose::GeneratedReferenceRelationalFamily
                    ) && Self::netlist_device_is_native_relational_legacy_diode(
                        netlist,
                        &element.name,
                    ) => {}
                _ => {
                    return Err(match purpose {
                        XyceStaticTranPlanPurpose::AbsoluteOracle
                        | XyceStaticTranPlanPurpose::AnalyticOracle => format!(
                            "native static .PRINT TRAN comparison currently supports independent, behavioral, static R/L/C, switch, controlled-source, validated native Level-1 NPN and exact IS-only diode models, native B3SOI, and native classic JFET transient decks; element '{}' requires a broader transient oracle contract",
                            element.name
                        ),
                        XyceStaticTranPlanPurpose::DefaultLevel9XyceVerifyOracle => format!(
                            "native Release 7.10 integrated-RMS .PRINT TRAN comparison supports the strict bare Xyce LEVEL=9 BSIM3 subset in addition to the ordinary absolute-device envelope; element '{}' requires a broader transient oracle contract",
                            element.name
                        ),
                        XyceStaticTranPlanPurpose::RelationalFamily
                        | XyceStaticTranPlanPurpose::GeneratedReferenceRelationalFamily => format!(
                            "native relational .PRINT TRAN comparison currently supports independent, behavioral, static R/L/C, switch, controlled-source, native B3SOI, native classic JFET, and validated native MOS3 and legacy-diode subsets; element '{}' requires a broader relational runtime contract",
                            element.name
                        ),
                        XyceStaticTranPlanPurpose::ScopedModelRelationalFamily => format!(
                            "native scoped-model relational .PRINT TRAN comparison currently supports finite independent and behavioral sources, static numeric R/C, finite VCCS, exact scalar IS/BF NPN models, and exact scalar IS diode models; element '{}' requires a broader scoped-model runtime contract",
                            element.name
                        ),
                    });
                }
            }
        }
        Ok(())
    }

    fn validate_lossless_transmission_line_contract(
        element_name: &str,
        node_count: usize,
        z0: Option<Value>,
        td: Option<Value>,
        freq: Option<Value>,
        nl: Option<Value>,
        model: Option<&str>,
    ) -> Result<(), String> {
        if node_count != 4 {
            return Err(format!(
                "lossless transmission line '{element_name}' requires four electrical terminals, found {node_count}"
            ));
        }
        if let Some(model) = model {
            return Err(format!(
                "native static .PRINT TRAN comparison does not yet admit model-backed transmission line '{element_name}' using model '{model}'"
            ));
        }
        let z0 = z0.ok_or_else(|| {
            format!("lossless transmission line '{element_name}' requires an explicit Z0")
        })?;
        if !z0.is_finite() || z0 <= 0.0 {
            return Err(format!(
                "lossless transmission line '{element_name}' requires finite positive Z0, got {z0}"
            ));
        }
        let delay = match (td, freq, nl) {
            (Some(delay), None, None) => delay,
            (None, Some(frequency), Some(length))
                if frequency.is_finite()
                    && frequency > 0.0
                    && length.is_finite()
                    && length > 0.0 =>
            {
                length / frequency
            }
            (None, Some(frequency), None) if frequency.is_finite() && frequency > 0.0 => {
                0.25 / frequency
            }
            _ => {
                return Err(format!(
                    "lossless transmission line '{element_name}' requires either TD or a finite positive F/NL pair"
                ));
            }
        };
        if !delay.is_finite() || delay <= 0.0 {
            return Err(format!(
                "lossless transmission line '{element_name}' requires finite positive propagation delay, got {delay}"
            ));
        }
        Ok(())
    }

    fn validate_native_scoped_model_relational_transient_contract_flat(
        netlist: &Netlist,
    ) -> Result<(), String> {
        if !Self::native_transient_uses_standard_startup(netlist) {
            return Err(
                "native scoped-model relational comparison requires ordinary DC operating-point startup at the default 27 C TEMP and TNOM, without UIC/NOOP, .TEMP analyses, explicit initial conditions, or node-set hints"
                    .to_string(),
            );
        }

        for element in &netlist.elements {
            match &element.kind {
                ElementKind::VoltageSource(spec) | ElementKind::CurrentSource(spec) => {
                    Self::validate_scoped_model_relational_source(&element.name, spec)?;
                }
                ElementKind::Resistor {
                    value,
                    value_expr,
                    model,
                    instance_params,
                    deferred_params,
                } if value.is_finite()
                    && *value > 0.0
                    && value_expr.is_none()
                    && model.is_none()
                    && instance_params.is_empty()
                    && deferred_params.is_empty() => {}
                ElementKind::Capacitor {
                    value,
                    value_expr,
                    initial_voltage,
                    model,
                    instance_params,
                    deferred_params,
                } if value.is_finite()
                    && *value > 0.0
                    && value_expr.is_none()
                    && initial_voltage.is_none()
                    && model.is_none()
                    && instance_params.is_empty()
                    && deferred_params.is_empty() => {}
                ElementKind::Vccs {
                    transconductance,
                    transconductance_expr,
                    ..
                } if transconductance_expr.is_none() => {
                    Self::validate_finite_controlled_source_gain(
                        "VCCS",
                        &element.name,
                        "transconductance",
                        *transconductance,
                    )?
                }
                ElementKind::BehavioralVoltage { expression, .. }
                | ElementKind::BehavioralCurrent { expression, .. } => {
                    Self::validate_transient_behavioral_expression(
                        &element.name,
                        expression,
                        &netlist.params,
                    )?;
                }
                ElementKind::Bjt { .. }
                    if Self::netlist_element_is_native_scoped_model_relational_bjt(
                        netlist, element,
                    ) => {}
                ElementKind::Diode { .. }
                    if Self::netlist_element_is_native_exact_is_diode(netlist, element) => {}
                _ => {
                    return Err(format!(
                        "native scoped-model relational comparison does not qualify element '{}'",
                        element.name
                    ));
                }
            }
        }
        Ok(())
    }

    fn source_spec_is_finite_dc_or_pulse(spec: &crate::netlist::SourceSpec) -> bool {
        match spec {
            crate::netlist::SourceSpec::Dc(value) => value.is_finite(),
            crate::netlist::SourceSpec::Pulse {
                v1,
                v2,
                delay,
                rise,
                fall,
                width,
                period,
                phase,
                ..
            } => {
                [*v1, *v2, *delay, *rise, *fall, *width, *period, *phase]
                    .into_iter()
                    .all(Value::is_finite)
                    && *delay >= 0.0
                    && *rise >= 0.0
                    && *fall >= 0.0
                    && *width >= 0.0
                    && *period > 0.0
            }
            _ => false,
        }
    }

    fn validate_scoped_model_relational_source(
        source_name: &str,
        spec: &crate::netlist::SourceSpec,
    ) -> Result<(), String> {
        if Self::source_spec_is_finite_dc_or_pulse(spec) {
            Ok(())
        } else {
            Err(format!(
                "native scoped-model relational source '{source_name}' must be finite DC or PULSE"
            ))
        }
    }

    fn validate_flattened_subcircuit_instances_resolved(
        netlist: &Netlist,
        flattened_elements: &[crate::netlist::Element],
    ) -> Result<(), String> {
        for element in &netlist.elements {
            if !matches!(element.kind, ElementKind::Subcircuit { .. }) {
                continue;
            }
            let prefix = format!("{}.", element.name).to_ascii_lowercase();
            let mut members = flattened_elements
                .iter()
                .filter(|flattened| flattened.name.to_ascii_lowercase().starts_with(&prefix));

            let Some(_member) = members.next() else {
                return Err(format!(
                    "native static .PRINT TRAN comparison could not find flattened members for subcircuit '{}'",
                    element.name
                ));
            };
        }

        Ok(())
    }

    fn validate_finite_controlled_source_gain(
        source_kind: &str,
        element_name: &str,
        value_name: &str,
        value: Value,
    ) -> Result<(), String> {
        if value.is_finite() {
            Ok(())
        } else {
            Err(format!(
                "native static .PRINT TRAN comparison does not support {source_kind} element '{element_name}' with non-finite {value_name} {value}"
            ))
        }
    }

    fn netlist_model_is_current_switch(netlist: &Netlist, model_name: &str) -> bool {
        Self::find_model(&netlist.models, model_name).is_some_and(|model| {
            matches!(
                model.model_type.to_ascii_uppercase().as_str(),
                "ISWITCH" | "ISW" | "CSW"
            )
        })
    }

    fn direct_branch_current_control(expression: &str) -> Option<String> {
        let normalized = Self::normalize_probe(expression);
        Self::parse_current_probe(&normalized)
    }

    fn validate_current_controlled_source_probe(
        elements: &[crate::netlist::Element],
        source_kind: &str,
        element_name: &str,
        control_element: &str,
    ) -> Result<(), String> {
        if Self::elements_have_recorded_branch_current(elements, control_element) {
            Ok(())
        } else {
            Err(format!(
                "native static .PRINT TRAN comparison does not support {source_kind} element '{element_name}' because controlling element '{control_element}' has no recorded branch current"
            ))
        }
    }

    fn validate_static_transient_passive_value_expression(
        device_kind: &str,
        element_name: &str,
        expression: &str,
        params: &crate::netlist::ParamContext,
    ) -> Result<(), String> {
        let prepared = prepare_behavioral_expression(expression, params).map_err(|err| {
            format!(
                "native static .PRINT TRAN comparison could not prepare {device_kind} value expression '{expression}' on element '{element_name}': {err}"
            )
        })?;
        let ast = parse_expression_strict(&prepared).map_err(|err| {
            format!(
                "native static .PRINT TRAN comparison does not yet support {device_kind} value expression '{expression}' on element '{element_name}': {err}"
            )
        })?;
        if Self::passive_value_expression_depends_on_runtime_quantity(&ast) {
            return Err(format!(
                "native static .PRINT TRAN comparison does not yet support runtime-dependent {device_kind} value expression '{expression}' on element '{element_name}'"
            ));
        }
        Ok(())
    }

    fn validate_transient_behavioral_expression(
        element_name: &str,
        expression: &str,
        params: &crate::netlist::ParamContext,
    ) -> Result<(), String> {
        Self::parse_transient_behavioral_expression(element_name, expression, params).map(drop)
    }

    fn validate_static_step_tran_behavioral_expression(
        element_name: &str,
        expression: &str,
        params: &crate::netlist::ParamContext,
    ) -> Result<(), String> {
        // Every parameter-step member is reparsed by
        // `create_perturbed_netlist_multi`, then built by a fresh Engine run.
        // Behavioral programs therefore receive the member's parameter scope
        // and may safely retain ordinary solution probes such as V(...) and
        // I(...), just as they do in an unstepped transient analysis.
        Self::validate_transient_behavioral_expression(element_name, expression, params)
    }

    fn parse_transient_behavioral_expression(
        element_name: &str,
        expression: &str,
        params: &crate::netlist::ParamContext,
    ) -> Result<Expr, String> {
        let prepared = prepare_behavioral_expression(expression, params).map_err(|err| {
            format!(
                "native static .PRINT TRAN comparison could not prepare behavioral expression '{}' on element '{}': {err}",
                expression, element_name
            )
        })?;
        let ast = parse_expression_strict(&prepared).map_err(|err| {
            format!(
                "native static .PRINT TRAN comparison does not yet support behavioral expression '{}' on element '{}': {err}",
                expression, element_name
            )
        })?;
        Ok(ast)
    }

    fn validate_ac_behavioral_expression(
        element_name: &str,
        expression: &str,
        params: &crate::netlist::ParamContext,
    ) -> Result<(), String> {
        let prepared = prepare_behavioral_expression(expression, params).map_err(|err| {
            format!(
                "native static .PRINT AC comparison could not prepare behavioral expression '{}' on element '{}': {err}",
                expression, element_name
            )
        })?;
        let ast = parse_expression_strict(&prepared).map_err(|err| {
            format!(
                "native static .PRINT AC comparison does not yet support behavioral expression '{}' on element '{}': {err}",
                expression, element_name
            )
        })?;
        if Self::expression_depends_on_ac_runtime_quantity(&ast) {
            return Err(format!(
                "native static .PRINT AC comparison does not support behavioral expression '{}' on element '{}' because AC behavioral small-signal linearization has no transient time or frequency-domain expression variable",
                expression, element_name
            ));
        }
        Ok(())
    }

    fn validate_transient_generic_switch_expression(
        element_name: &str,
        expression: &str,
        params: &crate::netlist::ParamContext,
    ) -> Result<(), String> {
        let prepared = prepare_behavioral_expression(expression, params).map_err(|err| {
            format!(
                "native static .PRINT TRAN comparison could not prepare generic switch CONTROL expression '{}' on element '{}': {err}",
                expression, element_name
            )
        })?;
        let ast = parse_expression_strict(&prepared).map_err(|err| {
            format!(
                "native static .PRINT TRAN comparison does not yet support generic switch CONTROL expression '{}' on element '{}': {err}",
                expression, element_name
            )
        })?;
        if Self::expression_depends_on_solution_quantity(&ast) {
            return Err(format!(
                "native static .PRINT TRAN comparison does not yet support generic switch CONTROL expression '{}' on element '{}' because it references circuit nodes or branch currents",
                expression, element_name
            ));
        }
        Ok(())
    }

    fn expression_depends_on_solution_quantity(expression: &Expr) -> bool {
        match expression {
            Expr::NodeVoltage(_) | Expr::BranchCurrent(_) => true,
            Expr::Unary { operand, .. } => Self::expression_depends_on_solution_quantity(operand),
            Expr::Binary { left, right, .. } => {
                Self::expression_depends_on_solution_quantity(left)
                    || Self::expression_depends_on_solution_quantity(right)
            }
            Expr::Function { args, .. } => args
                .iter()
                .any(Self::expression_depends_on_solution_quantity),
            Expr::Const(_)
            | Expr::StringLiteral(_)
            | Expr::LookupTable(_)
            | Expr::Time
            | Expr::Frequency
            | Expr::Temperature => false,
        }
    }

    fn expression_depends_on_ac_runtime_quantity(expression: &Expr) -> bool {
        match expression {
            Expr::Time | Expr::Frequency => true,
            Expr::Unary { operand, .. } => Self::expression_depends_on_ac_runtime_quantity(operand),
            Expr::Binary { left, right, .. } => {
                Self::expression_depends_on_ac_runtime_quantity(left)
                    || Self::expression_depends_on_ac_runtime_quantity(right)
            }
            Expr::Function { args, .. } => args
                .iter()
                .any(Self::expression_depends_on_ac_runtime_quantity),
            Expr::Const(_)
            | Expr::StringLiteral(_)
            | Expr::LookupTable(_)
            | Expr::NodeVoltage(_)
            | Expr::BranchCurrent(_)
            | Expr::Temperature => false,
        }
    }

    fn passive_value_expression_depends_on_runtime_quantity(expression: &Expr) -> bool {
        match expression {
            Expr::Const(_) | Expr::StringLiteral(_) | Expr::Temperature => false,
            Expr::NodeVoltage(_)
            | Expr::BranchCurrent(_)
            | Expr::LookupTable(_)
            | Expr::Time
            | Expr::Frequency => true,
            Expr::Unary { operand, .. } => {
                Self::passive_value_expression_depends_on_runtime_quantity(operand)
            }
            Expr::Binary { left, right, .. } => {
                Self::passive_value_expression_depends_on_runtime_quantity(left)
                    || Self::passive_value_expression_depends_on_runtime_quantity(right)
            }
            Expr::Function { args, .. } => args
                .iter()
                .any(Self::passive_value_expression_depends_on_runtime_quantity),
        }
    }

    fn validate_tran_probe(probe: &str, netlist: &Netlist) -> Result<(), String> {
        if let Some(expression) = Self::print_expression_inner(probe) {
            let normalized_expression = Self::normalize_probe(expression);
            if Self::braced_expression_is_atomic_real_probe(&normalized_expression, netlist) {
                return Self::validate_atomic_tran_probe(
                    &normalized_expression,
                    expression,
                    netlist,
                );
            }
            let expression_upper = expression.to_ascii_uppercase();
            if netlist.measurements.iter().any(|measurement| {
                measurement.analysis.eq_ignore_ascii_case("TRAN")
                    && matches!(
                        measurement.measure_type,
                        crate::analysis::MeasureType::Equation { .. }
                    )
                    && expression_upper.contains(&measurement.name.to_ascii_uppercase())
            }) {
                let context = Self::print_tran_eval_context(netlist, 0.0);
                crate::netlist::expr::eval_expression(expression, &context).map_err(|err| {
                    format!("unsupported .PRINT TRAN expression '{{{expression}}}': {err}")
                })?;
                return Ok(());
            }
            if Self::stateful_tran_print_expression(probe, netlist)?.is_some() {
                return Self::validate_tran_probe_expression(expression, netlist);
            }
            if Self::print_expression_contains_probe_reference(expression) {
                return Self::validate_tran_probe_expression(expression, netlist);
            }
            let context = Self::print_tran_eval_context(netlist, 0.0);
            crate::netlist::expr::eval_expression(expression, &context).map_err(|err| {
                format!("unsupported .PRINT TRAN expression '{{{expression}}}': {err}")
            })?;
            return Ok(());
        }

        let normalized = Self::normalize_probe(probe);
        Self::validate_atomic_tran_probe(&normalized, probe, netlist)
    }

    fn validate_ac_probe(probe: &str, netlist: &Netlist) -> Result<(), String> {
        if Self::probe_names_live_measurement(probe, netlist, "AC", "AC_CONT") {
            return Ok(());
        }
        if let Some(expression) = Self::print_expression_inner(probe) {
            let normalized_expression = Self::normalize_probe(expression);
            if Self::braced_expression_is_atomic_ac_probe(&normalized_expression, netlist) {
                return Self::validate_atomic_ac_probe(&normalized_expression, expression, netlist);
            }
            return Self::validate_ac_expression_probe(expression, netlist);
        }

        let normalized = Self::normalize_probe(probe);
        Self::validate_atomic_ac_probe(&normalized, probe, netlist)
            .or_else(|_| Self::validate_ac_expression_probe(probe, netlist))
    }

    fn validate_atomic_ac_probe(
        normalized: &str,
        original: &str,
        netlist: &Netlist,
    ) -> Result<(), String> {
        if let Some(voltage_probe) = Self::parse_ac_voltage_probe(normalized) {
            if !voltage_probe.node_pos.is_empty()
                && voltage_probe
                    .node_neg
                    .as_deref()
                    .is_none_or(|node| !node.is_empty())
            {
                return Ok(());
            }
        }
        if let Some(current_probe) = Self::parse_ac_current_probe(normalized)
            && Self::netlist_has_recorded_branch_current(netlist, &current_probe.element_name)
        {
            return Ok(());
        }
        if let Some((element_name, parameter)) = Self::parse_device_parameter_probe(normalized) {
            match parameter.as_str() {
                "acmag" | "acphase"
                    if Self::source_is_independent_source(netlist, &element_name) =>
                {
                    return Ok(());
                }
                "r" if Self::find_resistor_element(netlist, &element_name).is_some() => {
                    return Ok(());
                }
                "c" if Self::find_capacitor_element(netlist, &element_name).is_some() => {
                    return Ok(());
                }
                "l" if Self::find_inductor_element(netlist, &element_name).is_some() => {
                    return Ok(());
                }
                _ => {}
            }
        }
        if netlist.measurements.iter().any(|measurement| {
            measurement.analysis.eq_ignore_ascii_case("AC")
                && measurement.name.eq_ignore_ascii_case(original)
        }) {
            return Ok(());
        }
        Err(format!("unsupported .PRINT AC probe '{}'", original))
    }

    fn validate_ac_complex_probe(probe: &str, netlist: &Netlist) -> Result<(), String> {
        let normalized = Self::normalize_probe(probe);
        if let Some(voltage_probe) = Self::parse_ac_voltage_probe(&normalized) {
            if voltage_probe.accessor != XyceVoltageAccessor::Value {
                return Err(format!(
                    ".PRINT AC complex expression expects a complex V(...) argument, got '{}'",
                    probe.trim()
                ));
            }
            return Self::validate_atomic_ac_probe(&normalized, probe, netlist);
        }
        if let Some(current_probe) = Self::parse_ac_current_probe(&normalized) {
            if current_probe.accessor != XyceCurrentAccessor::Value {
                return Err(format!(
                    ".PRINT AC complex expression expects a complex I(...) argument, got '{}'",
                    probe.trim()
                ));
            }
            return Self::validate_atomic_ac_probe(&normalized, probe, netlist);
        }
        Self::validate_ac_expression_probe(probe, netlist)
    }

    fn validate_ac_expression_probe(expression: &str, netlist: &Netlist) -> Result<(), String> {
        let context = Self::print_eval_context(netlist, None, None);
        let mut call_value = |call: &str| {
            Self::validate_ac_expression_call_probe(call, netlist)?;
            Ok(ExprComplexValue::real(1.0))
        };
        let (rewritten, context) =
            Self::rewrite_ac_print_expression_complex(expression, context, &mut call_value)?;
        crate::netlist::expr::eval_expression_complex(&rewritten, &context)
            .map_err(|err| format!("unsupported .PRINT AC expression '{{{expression}}}': {err}"))?;
        Ok(())
    }

    fn validate_ac_expression_call_probe(call: &str, netlist: &Netlist) -> Result<(), String> {
        let normalized = Self::normalize_probe(call);
        if Self::parse_ac_voltage_probe(&normalized).is_some()
            || Self::parse_ac_current_probe(&normalized).is_some()
        {
            return Self::validate_atomic_ac_probe(&normalized, call, netlist);
        }
        Self::validate_ac_complex_probe(call, netlist)
    }

    fn validate_atomic_tran_probe(
        normalized: &str,
        original: &str,
        netlist: &Netlist,
    ) -> Result<(), String> {
        if let Some(voltage_probe) = Self::parse_tran_voltage_probe(normalized) {
            if !voltage_probe.node_pos.is_empty()
                && voltage_probe
                    .node_neg
                    .as_deref()
                    .is_none_or(|node| !node.is_empty())
            {
                return Ok(());
            }
        }
        if let Some(element_name) = Self::parse_current_probe(normalized) {
            if Self::netlist_has_recorded_branch_current(netlist, &element_name) {
                return Ok(());
            }
            if Self::netlist_has_independent_current_source(netlist, &element_name) {
                return Ok(());
            }
            return Err(format!(
                "transient branch-current probe '{}' targets an element without a recorded transient branch current",
                original
            ));
        }
        if let Some(element_name) = Self::parse_power_probe(normalized) {
            if Self::find_recorded_two_terminal_branch_element(netlist, &element_name).is_some() {
                return Ok(());
            }
            return Err(format!(
                "transient power probe '{}' targets an unsupported branch/device",
                original
            ));
        }
        if let Some((element_name, parameter)) = Self::parse_device_parameter_probe(normalized) {
            match parameter.as_str() {
                "r" if Self::find_resistor_element(netlist, &element_name).is_some() => {
                    return Ok(());
                }
                "c" if Self::find_capacitor_element(netlist, &element_name).is_some() => {
                    return Ok(());
                }
                "l" if Self::find_inductor_element(netlist, &element_name).is_some() => {
                    return Ok(());
                }
                "temp" if Self::resistor_temperature_value(netlist, &element_name).is_some() => {
                    return Ok(());
                }
                _ => {}
            }
            return Err(format!(
                "device parameter probe '{}' targets an unsupported transient parameter",
                original
            ));
        }
        if Self::normalize_probe(original) == "time" {
            return Ok(());
        }
        if netlist.measurements.iter().any(|measurement| {
            measurement.analysis.eq_ignore_ascii_case("TRAN")
                && measurement.name.eq_ignore_ascii_case(original)
                && matches!(
                    measurement.measure_type,
                    crate::analysis::MeasureType::Equation { .. }
                )
        }) {
            return Ok(());
        }
        Err(format!("unsupported .PRINT TRAN probe '{}'", original))
    }

    fn validate_tran_probe_expression(expression: &str, netlist: &Netlist) -> Result<(), String> {
        let probe = format!("{{{expression}}}");
        if let Some(runtime) = Self::stateful_tran_print_expression(&probe, netlist)? {
            for branch in runtime.program.branch_map.keys() {
                let probe = format!("i({branch})");
                Self::validate_atomic_tran_probe(&Self::normalize_probe(&probe), &probe, netlist)?;
            }
            return Ok(());
        }
        let mut call_value = |call: &str| {
            let normalized = Self::normalize_probe(call);
            Self::validate_atomic_tran_probe(&normalized, call, netlist)?;
            Ok(1.0)
        };
        let context = Self::print_tran_eval_context(netlist, 0.0);
        Self::evaluate_print_expression_with_probe_calls(expression, context, &mut call_value)
            .map_err(|err| {
                format!("unsupported .PRINT TRAN expression '{{{expression}}}': {err}")
            })?;
        Ok(())
    }

    fn reject_unsupported_vbic_nested_current_source_sweeps(
        netlist: &Netlist,
        dc: &XyceDcSweep,
        print: &XycePrintRequest,
    ) -> Result<(), String> {
        let Some(sweep2) = &dc.sweep2 else {
            return Ok(());
        };
        if !Self::netlist_uses_native_vbic_bjt(netlist) {
            return Ok(());
        }

        let bias_points = dc.primary_spec().points().len() * sweep2.spec().points().len();
        if bias_points <= 1000 {
            return Ok(());
        }

        for probe in &print.probes {
            if Self::dc_probe_references_current_source_current(probe, netlist)? {
                return Err(format!(
                    "native VBIC nested DC sweep with {bias_points} bias points and current-source branch-current probes exceeds the current Xyce harness execution envelope; keep this named unsupported until VBIC nested-sweep continuation/performance is production-ready"
                ));
            }
        }

        Ok(())
    }

    fn is_expected_unsupported_runtime_error(err: &SimulationError) -> bool {
        let (SimulationError::Circuit(message) | SimulationError::Netlist(message)) = err else {
            return false;
        };
        let normalized = message.to_ascii_lowercase();
        normalized.contains("unsupported")
            || normalized.contains("not implemented")
            || normalized.contains("does not support")
            || normalized.contains("currently supports")
            || normalized.contains("no native implementation")
            || normalized.contains("no generated verilog-a builtin")
            || normalized.contains("no generated builtin")
            || normalized.contains("not yet")
            || normalized.contains("refusing")
            || normalized.contains("must not run through")
    }

    fn reject_unsupported_static_dc_model_observables(
        netlist: &Netlist,
        print: &XycePrintRequest,
    ) -> Result<(), String> {
        if !Self::netlist_uses_ekv3_level301_mosfet(netlist) {
            return Ok(());
        }

        let mut has_voltage_source_current_probe = false;
        for probe in &print.probes {
            if Self::dc_probe_references_voltage_source_current(probe, netlist)? {
                has_voltage_source_current_probe = true;
                break;
            }
        }
        if !has_voltage_source_current_probe {
            return Ok(());
        }

        if Self::netlist_uses_unsupported_ekv3_level301_branch_current_model(netlist) {
            return Err(
                "EKV3 LEVEL=301 static .PRINT DC voltage-source branch-current probes require a native validated EKV3 150 nm model; unsupported EKV3 LEVEL=301 cards remain fail-closed"
                    .to_string(),
            );
        }

        Ok(())
    }

    fn netlist_uses_ekv3_level301_mosfet(netlist: &Netlist) -> bool {
        if Self::elements_use_ekv3_level301_mosfet(&netlist.elements, &netlist.models, &[]) {
            return true;
        }

        crate::netlist::flatten_netlist_with_models(netlist).is_ok_and(|flattened| {
            Self::elements_use_ekv3_level301_mosfet(
                &flattened.elements,
                &netlist.models,
                &flattened.scoped_models,
            )
        })
    }

    fn netlist_uses_unsupported_ekv3_level301_branch_current_model(netlist: &Netlist) -> bool {
        if Self::elements_use_unsupported_ekv3_level301_branch_current_model(
            &netlist.elements,
            &netlist.models,
            &[],
        ) {
            return true;
        }

        crate::netlist::flatten_netlist_with_models(netlist).is_ok_and(|flattened| {
            Self::elements_use_unsupported_ekv3_level301_branch_current_model(
                &flattened.elements,
                &netlist.models,
                &flattened.scoped_models,
            )
        })
    }

    fn netlist_uses_native_vbic_bjt(netlist: &Netlist) -> bool {
        if Self::elements_use_native_vbic_bjt(&netlist.elements, &netlist.models, &[]) {
            return true;
        }

        crate::netlist::flatten_netlist_with_models(netlist).is_ok_and(|flattened| {
            Self::elements_use_native_vbic_bjt(
                &flattened.elements,
                &netlist.models,
                &flattened.scoped_models,
            )
        })
    }

    fn elements_use_ekv3_level301_mosfet(
        elements: &[crate::netlist::Element],
        models: &[crate::netlist::ModelDef],
        scoped_models: &[crate::netlist::ModelDef],
    ) -> bool {
        elements.iter().any(|element| {
            let ElementKind::Mosfet {
                model,
                instance_params,
                ..
            } = &element.kind
            else {
                return false;
            };
            Self::find_model_or_binned(scoped_models, model, instance_params)
                .or_else(|| Self::find_model_or_binned(models, model, instance_params))
                .is_some_and(Self::model_is_ekv3_level301)
        })
    }

    fn elements_use_unsupported_ekv3_level301_branch_current_model(
        elements: &[crate::netlist::Element],
        models: &[crate::netlist::ModelDef],
        scoped_models: &[crate::netlist::ModelDef],
    ) -> bool {
        elements.iter().any(|element| {
            let ElementKind::Mosfet {
                model,
                instance_params,
                ..
            } = &element.kind
            else {
                return false;
            };
            Self::find_model_or_binned(scoped_models, model, instance_params)
                .or_else(|| Self::find_model_or_binned(models, model, instance_params))
                .is_some_and(|model| {
                    Self::model_is_ekv3_level301(model)
                        && !Self::model_is_ekv3_level301_native_150nm_branch_current(model)
                })
        })
    }

    fn elements_use_native_vbic_bjt(
        elements: &[crate::netlist::Element],
        models: &[crate::netlist::ModelDef],
        scoped_models: &[crate::netlist::ModelDef],
    ) -> bool {
        elements.iter().any(|element| {
            let ElementKind::Bjt { model, .. } = &element.kind else {
                return false;
            };
            Self::find_model(scoped_models, model)
                .or_else(|| Self::find_model(models, model))
                .is_some_and(Self::model_is_native_vbic_bjt)
        })
    }

    fn find_model<'a>(
        models: &'a [crate::netlist::ModelDef],
        name: &str,
    ) -> Option<&'a crate::netlist::ModelDef> {
        models
            .iter()
            .find(|model| model.name.eq_ignore_ascii_case(name))
    }

    fn find_model_or_binned<'a>(
        models: &'a [crate::netlist::ModelDef],
        name: &str,
        instance_params: &[(String, Value)],
    ) -> Option<&'a crate::netlist::ModelDef> {
        Self::find_model(models, name)
            .or_else(|| Self::find_binned_model(models, name, instance_params))
    }

    fn find_binned_model<'a>(
        models: &'a [crate::netlist::ModelDef],
        name: &str,
        instance_params: &[(String, Value)],
    ) -> Option<&'a crate::netlist::ModelDef> {
        let prefix = format!("{name}.");
        models
            .iter()
            .filter(|model| {
                model.name.len() > prefix.len()
                    && model.name[..prefix.len()].eq_ignore_ascii_case(&prefix)
                    && Self::model_matches_geometry_bin(model, instance_params)
            })
            .min_by(|left, right| {
                Self::model_geometry_bin_range_size(left)
                    .partial_cmp(&Self::model_geometry_bin_range_size(right))
                    .unwrap_or(std::cmp::Ordering::Equal)
            })
    }

    fn model_matches_geometry_bin(
        model: &crate::netlist::ModelDef,
        instance_params: &[(String, Value)],
    ) -> bool {
        let lmin = Self::numeric_param_value(&model.params, "LMIN");
        let lmax = Self::numeric_param_value(&model.params, "LMAX");
        let wmin = Self::numeric_param_value(&model.params, "WMIN");
        let wmax = Self::numeric_param_value(&model.params, "WMAX");
        let nfinmin = Self::numeric_param_value(&model.params, "NFINMIN");
        let nfinmax = Self::numeric_param_value(&model.params, "NFINMAX");

        if lmin.is_none()
            && lmax.is_none()
            && wmin.is_none()
            && wmax.is_none()
            && nfinmin.is_none()
            && nfinmax.is_none()
        {
            return false;
        }

        let length = Self::numeric_param_value(instance_params, "L")
            .or_else(|| Self::numeric_param_value(instance_params, "LENGTH"));
        let width = Self::numeric_param_value(instance_params, "W")
            .or_else(|| Self::numeric_param_value(instance_params, "WIDTH"));
        let nfin = Self::numeric_param_value(instance_params, "NFIN");

        Self::bin_range_contains(length, lmin, lmax)
            && Self::bin_range_contains(width, wmin, wmax)
            && Self::bin_range_contains(nfin, nfinmin, nfinmax)
    }

    fn bin_range_contains(value: Option<Value>, min: Option<Value>, max: Option<Value>) -> bool {
        if min.is_none() && max.is_none() {
            return true;
        }
        let Some(value) = value else {
            return false;
        };
        min.is_none_or(|min| value >= min) && max.is_none_or(|max| value <= max)
    }

    fn model_geometry_bin_range_size(model: &crate::netlist::ModelDef) -> Value {
        Self::bin_range_size(
            Self::numeric_param_value(&model.params, "LMIN"),
            Self::numeric_param_value(&model.params, "LMAX"),
        ) + Self::bin_range_size(
            Self::numeric_param_value(&model.params, "WMIN"),
            Self::numeric_param_value(&model.params, "WMAX"),
        ) + Self::bin_range_size(
            Self::numeric_param_value(&model.params, "NFINMIN"),
            Self::numeric_param_value(&model.params, "NFINMAX"),
        )
    }

    fn bin_range_size(min: Option<Value>, max: Option<Value>) -> Value {
        match (min, max) {
            (Some(min), Some(max)) => max - min,
            (Some(_), None) | (None, Some(_)) => Value::MAX / 4.0,
            (None, None) => 0.0,
        }
    }

    fn model_is_ekv3_level301(model: &crate::netlist::ModelDef) -> bool {
        matches!(
            model.model_type.to_ascii_uppercase().as_str(),
            "NMOS" | "PMOS"
        ) && model
            .params
            .iter()
            .rev()
            .find(|(name, _)| name.eq_ignore_ascii_case("LEVEL"))
            .is_some_and(|(_, value)| (*value - 301.0).abs() <= 1.0e-9)
    }

    fn model_is_ekv3_level301_native_150nm_branch_current(
        model: &crate::netlist::ModelDef,
    ) -> bool {
        matches!(
            model.model_type.to_ascii_uppercase().as_str(),
            "NMOS" | "PMOS"
        ) && Self::model_is_ekv3_level301(model)
    }

    fn model_is_native_vbic_bjt(model: &crate::netlist::ModelDef) -> bool {
        matches!(
            model.model_type.to_ascii_uppercase().as_str(),
            "NPN" | "PNP"
        ) && model
            .params
            .iter()
            .rev()
            .find(|(name, _)| name.eq_ignore_ascii_case("LEVEL"))
            .is_some_and(|(_, value)| {
                [4.0, 9.0, 11.0, 12.0, 13.0]
                    .iter()
                    .any(|level| (*value - *level).abs() <= 1.0e-9)
            })
    }

    fn dc_probe_references_voltage_source_current(
        probe: &str,
        netlist: &Netlist,
    ) -> Result<bool, String> {
        let normalized = Self::normalize_probe(probe);
        if let Some(source_name) = Self::parse_current_probe(&normalized) {
            return Ok(Self::source_is_voltage_source(netlist, &source_name));
        }

        let Some(expression) = Self::print_expression_inner(&normalized) else {
            return Ok(false);
        };
        if !Self::print_expression_contains_probe_call(expression) {
            return Ok(false);
        }

        let mut references_voltage_source_current = false;
        Self::rewrite_print_expression_calls(expression, netlist.params.clone(), |call| {
            if let Some(source_name) = Self::parse_current_probe(call)
                && Self::source_is_voltage_source(netlist, &source_name)
            {
                references_voltage_source_current = true;
            }
            Ok(0.0)
        })?;
        Ok(references_voltage_source_current)
    }

    fn dc_probe_references_current_source_current(
        probe: &str,
        netlist: &Netlist,
    ) -> Result<bool, String> {
        let normalized = Self::normalize_probe(probe);
        if let Some(source_name) = Self::parse_current_probe(&normalized) {
            return Ok(Self::source_is_current_source(netlist, &source_name));
        }

        let Some(expression) = Self::print_expression_inner(&normalized) else {
            return Ok(false);
        };
        if !Self::print_expression_contains_probe_call(expression) {
            return Ok(false);
        }

        let mut references_current_source_current = false;
        Self::rewrite_print_expression_calls(expression, netlist.params.clone(), |call| {
            if let Some(source_name) = Self::parse_current_probe(call)
                && Self::source_is_current_source(netlist, &source_name)
            {
                references_current_source_current = true;
            }
            Ok(0.0)
        })?;
        Ok(references_current_source_current)
    }

    fn validate_dc_sweep_source(netlist: &Netlist, source: &str) -> Result<(), String> {
        if Self::source_is_independent_source(netlist, source)
            || source.eq_ignore_ascii_case("TEMP")
            || source.eq_ignore_ascii_case("TEMPER")
            || Self::scalar_parameter_sweep_source_is_supported(netlist, source)
        {
            return Ok(());
        }
        Err(format!(
            "DC sweep source '{}' is not a supported top-level independent source, scalar parameter, or TEMP sweep",
            source
        ))
    }

    fn dc_sweep_point_netlist(
        netlist: &Netlist,
        dc: &XyceDcSweep,
        sweep_point: XyceDcSweepPoint,
    ) -> Result<Option<Netlist>, String> {
        let mut overrides = Vec::new();
        if Self::scalar_parameter_sweep_source_is_supported(netlist, &dc.source) {
            overrides.push((dc.source.clone(), sweep_point.primary));
        }
        if let Some(sweep2) = &dc.sweep2
            && Self::scalar_parameter_sweep_source_is_supported(netlist, &sweep2.source)
            && let Some(secondary) = sweep_point.secondary
        {
            overrides.push((sweep2.source.clone(), secondary));
        }
        if overrides.is_empty() {
            return Ok(None);
        }

        Engine::create_perturbed_netlist_multi(netlist, &overrides)
            .map(|(netlist, _)| Some(netlist))
            .map_err(|err| {
                format!(
                    "failed to build Xyce DC parameter-sweep netlist for {:?}: {}",
                    overrides, err
                )
            })
    }

    fn reject_unsupported_source_directives(source: &str) -> Result<(), String> {
        for line in Self::logical_netlist_lines(source) {
            let trimmed = Self::strip_netlist_comment(&line)
                .trim()
                .to_ascii_lowercase();
            if trimmed.is_empty() {
                continue;
            }
            if let Some(rest) = trimmed.strip_prefix(".options") {
                let option_tokens = rest
                    .split(|ch: char| ch.is_ascii_whitespace() || ch == ',')
                    .filter(|token| !token.is_empty())
                    .collect::<Vec<_>>();
                if option_tokens.iter().any(|token| *token == "loca")
                    || (option_tokens.iter().any(|token| *token == "nonlin")
                        && option_tokens
                            .iter()
                            .any(|token| token.starts_with("continuation")))
                {
                    return Err(
                        "deck requires Xyce LOCA continuation options; the native Xyce adapter does not yet implement continuation analysis semantics"
                            .to_string(),
                    );
                }
            }
        }
        Ok(())
    }

    fn validate_dc_probe(probe: &str, netlist: &Netlist) -> Result<(), String> {
        if Self::probe_names_live_measurement(probe, netlist, "DC", "DC_CONT") {
            return Ok(());
        }
        if let Some(expression) = Self::print_expression_inner(probe) {
            let normalized_expression = Self::normalize_probe(expression);
            if Self::braced_expression_is_atomic_real_probe(&normalized_expression, netlist) {
                return Self::validate_atomic_dc_probe(&normalized_expression, expression, netlist);
            }
            if Self::print_expression_contains_probe_reference(expression) {
                return Self::validate_dc_probe_expression(expression, netlist);
            }
            let context = Self::print_eval_context(netlist, None, None);
            crate::netlist::expr::eval_expression(expression, &context).map_err(|err| {
                format!("unsupported .PRINT DC expression '{{{expression}}}': {err}")
            })?;
            return Ok(());
        }

        let normalized = Self::normalize_probe(probe);
        Self::validate_atomic_dc_probe(&normalized, probe, netlist)
    }

    fn probe_names_live_measurement(
        probe: &str,
        netlist: &Netlist,
        scalar_analysis: &str,
        continuous_analysis: &str,
    ) -> bool {
        let candidate = Self::print_expression_inner(probe).unwrap_or(probe).trim();
        netlist.measurements.iter().any(|measurement| {
            measurement.name.eq_ignore_ascii_case(candidate)
                && (measurement.analysis.eq_ignore_ascii_case(scalar_analysis)
                    || measurement
                        .analysis
                        .eq_ignore_ascii_case(continuous_analysis))
                && matches!(
                    measurement.measure_type,
                    crate::analysis::MeasureType::Equation { .. }
                        | crate::analysis::MeasureType::Find { .. }
                        | crate::analysis::MeasureType::Derivative { .. }
                        | crate::analysis::MeasureType::When { .. }
                        | crate::analysis::MeasureType::Delay { .. }
                )
        })
    }

    fn validate_atomic_dc_probe(
        normalized: &str,
        original: &str,
        netlist: &Netlist,
    ) -> Result<(), String> {
        if let Some(voltage_probe) = Self::parse_tran_voltage_probe(normalized) {
            if !voltage_probe.node_pos.is_empty()
                && voltage_probe
                    .node_neg
                    .as_deref()
                    .is_none_or(|node| !node.is_empty())
            {
                return Ok(());
            }
        }
        if let Some((element_name, parameter)) =
            Self::parse_device_operating_point_probe(normalized)
        {
            if !Self::netlist_has_device_op_instance(netlist, &element_name) {
                return Err(format!(
                    "device operating-point probe '{}' targets an unknown reported device",
                    original
                ));
            }
            if Self::canonical_device_op_parameter(&parameter).is_some() {
                return Ok(());
            }
            return Err(format!(
                "device operating-point probe '{}' targets an unsupported operating-point parameter",
                original
            ));
        }
        if let Some(lead_current) = Self::parse_lead_current_probe(normalized) {
            if Self::lead_current_probe_is_omitted_empty_wildcard(netlist, &lead_current) {
                return Ok(());
            }
            if lead_current.element_name == "*" {
                return Err(format!(
                    "lead-current wildcard probe '{}' requires terminal expansion support",
                    original
                ));
            }
            if !Self::netlist_has_device_op_instance(netlist, &lead_current.element_name) {
                return Err(format!(
                    "lead-current probe '{}' targets an unknown reported device",
                    original
                ));
            }
            if Self::netlist_supports_lead_current_probe(netlist, &lead_current) {
                return Ok(());
            }
            return Err(format!(
                "lead-current probe '{}' targets unsupported {} terminal current",
                original,
                lead_current.terminal.function_name()
            ));
        }
        if Self::bare_device_parameter_probe_is_supported(netlist, normalized) {
            return Ok(());
        }
        if let Some((element_name, parameter)) = Self::parse_device_parameter_probe(normalized) {
            match parameter.as_str() {
                "dcv0" if Self::source_is_independent_source(netlist, &element_name) => {
                    return Ok(());
                }
                "r" => {
                    if Self::find_resistor_element(netlist, &element_name).is_some() {
                        return Ok(());
                    }
                }
                "c" => {
                    if Self::find_capacitor_element(netlist, &element_name).is_some() {
                        return Ok(());
                    }
                }
                "l" => {
                    if Self::find_inductor_element(netlist, &element_name).is_some() {
                        return Ok(());
                    }
                    if Self::resistor_instance_parameter_probe_is_supported(
                        netlist,
                        &element_name,
                        &parameter,
                    ) {
                        return Ok(());
                    }
                }
                "temp" if Self::resistor_temperature_value(netlist, &element_name).is_some() => {
                    return Ok(());
                }
                _ => {
                    if Self::resistor_instance_parameter_probe_is_supported(
                        netlist,
                        &element_name,
                        &parameter,
                    ) {
                        return Ok(());
                    }
                }
            }
            if Self::model_parameter_probe_is_supported(netlist, &element_name, &parameter) {
                return Ok(());
            }
            return Err(format!(
                "device parameter probe '{}' targets an unsupported parameter",
                original
            ));
        }
        if let Some(parameter_name) = Self::parse_scalar_parameter_probe(normalized)
            && Self::scalar_parameter_probe_is_supported(netlist, &parameter_name)
        {
            return Ok(());
        }
        if let Some(element_name) = Self::parse_current_probe(normalized) {
            if Self::netlist_has_recorded_branch_current(netlist, &element_name) {
                return Ok(());
            }
            if Self::source_is_current_source(netlist, &element_name) {
                return Ok(());
            }
            if let Some(resistance) = Self::effective_resistor_value(netlist, &element_name) {
                if resistance.is_finite()
                    || (resistance.is_infinite() && resistance.is_sign_positive())
                {
                    return Ok(());
                }
                return Err(format!(
                    "current probe '{}' targets a resistor with invalid resistance {}",
                    original, resistance
                ));
            }
            return Err(format!(
                "current probe '{}' targets an unsupported branch/device",
                original
            ));
        }
        if let Some(element_name) = Self::parse_power_probe(normalized) {
            if let Some(resistance) = Self::effective_resistor_value(netlist, &element_name) {
                if resistance.is_finite()
                    || (resistance.is_infinite() && resistance.is_sign_positive())
                {
                    return Ok(());
                }
                return Err(format!(
                    "power probe '{}' targets a resistor with invalid resistance {}",
                    original, resistance
                ));
            }
            return Err(format!(
                "power probe '{}' targets an unsupported branch/device",
                original
            ));
        }
        if netlist.measurements.iter().any(|measurement| {
            measurement.analysis.eq_ignore_ascii_case("DC")
                && measurement.name.eq_ignore_ascii_case(original)
                && matches!(
                    measurement.measure_type,
                    crate::analysis::MeasureType::Avg { .. }
                        | crate::analysis::MeasureType::Rms { .. }
                        | crate::analysis::MeasureType::Equation { .. }
                )
        }) {
            return Ok(());
        }
        Err(format!("unsupported .PRINT DC probe '{}'", original))
    }

    fn resistor_branch_form_tolerance(netlist: &Netlist) -> Value {
        netlist
            .options
            .device_zero_resistance_tol
            .unwrap_or(XYCE_DEFAULT_ZERO_RESISTANCE_TOL)
            .max(0.0)
    }

    fn resistor_uses_branch_form(netlist: &Netlist, resistance: Value) -> bool {
        resistance.is_finite() && resistance.abs() <= Self::resistor_branch_form_tolerance(netlist)
    }

    fn evaluate_dc_probe(
        probe: &str,
        netlist: &Netlist,
        dc: &XyceDcSweep,
        sweep_point: XyceDcSweepPoint,
        result: &crate::SimulationResult,
        op_report: &crate::circuit::DeviceOpReport,
    ) -> Result<f64, String> {
        if let Some(expression) = Self::print_expression_inner(probe) {
            let normalized_expression = Self::normalize_probe(expression);
            if Self::braced_expression_is_atomic_real_probe(&normalized_expression, netlist) {
                return Self::evaluate_atomic_dc_probe(
                    &normalized_expression,
                    netlist,
                    dc,
                    sweep_point,
                    result,
                    op_report,
                );
            }
            if Self::print_expression_contains_probe_reference(expression) {
                return Self::evaluate_dc_probe_expression(
                    expression,
                    netlist,
                    dc,
                    sweep_point,
                    result,
                    op_report,
                );
            }
            let context = Self::print_eval_context(netlist, Some(dc), Some(sweep_point));
            return crate::netlist::expr::eval_expression(expression, &context).map_err(|err| {
                format!("failed to evaluate .PRINT DC expression '{{{expression}}}': {err}")
            });
        }

        let normalized = Self::normalize_probe(probe);
        Self::evaluate_atomic_dc_probe(&normalized, netlist, dc, sweep_point, result, op_report)
    }

    fn evaluate_atomic_dc_probe(
        normalized: &str,
        netlist: &Netlist,
        dc: &XyceDcSweep,
        sweep_point: XyceDcSweepPoint,
        result: &crate::SimulationResult,
        op_report: &crate::circuit::DeviceOpReport,
    ) -> Result<f64, String> {
        if let Some(voltage_probe) = Self::parse_voltage_probe(normalized) {
            let pos = Self::result_voltage_named(result, netlist, &voltage_probe.node_pos)
                .ok_or_else(|| {
                    format!("node '{}' not found in DC result", voltage_probe.node_pos)
                })?;
            let neg = match voltage_probe.node_neg {
                Some(node) => Self::result_voltage_named(result, netlist, &node)
                    .ok_or_else(|| format!("node '{}' not found in DC result", node))?,
                None => 0.0,
            };
            return Ok(voltage_probe.accessor.evaluate_dc(pos - neg));
        }

        if let Some((element_name, parameter)) =
            Self::parse_device_operating_point_probe(normalized)
        {
            return Self::evaluate_device_operating_point_probe(
                op_report,
                &element_name,
                &parameter,
            );
        }

        if let Some(lead_current) = Self::parse_lead_current_probe(normalized) {
            return Self::evaluate_lead_current_probe(op_report, &lead_current);
        }

        if let Some(value) = Self::evaluate_bare_device_parameter_probe(
            netlist,
            dc,
            sweep_point,
            result,
            op_report,
            normalized,
        ) {
            return value;
        }

        if let Some((element_name, parameter)) = Self::parse_device_parameter_probe(normalized) {
            return Self::evaluate_device_parameter_probe(
                netlist,
                dc,
                sweep_point,
                result,
                op_report,
                &element_name,
                &parameter,
            );
        }

        if let Some(parameter_name) = Self::parse_scalar_parameter_probe(normalized) {
            return Self::evaluate_scalar_parameter_probe(
                netlist,
                dc,
                sweep_point,
                &parameter_name,
            );
        }

        if let Some(element_name) = Self::parse_current_probe(normalized) {
            if let Some(current) = Self::result_branch_current_named(result, &element_name) {
                return Ok(current);
            }
            if let Some(current) =
                Self::evaluate_current_source_current(netlist, dc, sweep_point, &element_name)
            {
                return Ok(current);
            }
            if let Some(resistance) = Self::effective_resistor_value(netlist, &element_name) {
                return Self::evaluate_resistor_current(netlist, result, &element_name, resistance);
            }
        }

        if let Some(element_name) = Self::parse_power_probe(normalized)
            && let Some(resistance) = Self::effective_resistor_value(netlist, &element_name)
        {
            return Self::evaluate_resistor_power(netlist, result, &element_name, resistance);
        }

        Err(format!("unsupported DC probe '{}'", normalized))
    }

    fn validate_dc_probe_expression(expression: &str, netlist: &Netlist) -> Result<(), String> {
        let mut call_value = |call: &str| {
            let normalized = Self::normalize_probe(call);
            Self::validate_atomic_dc_probe(&normalized, call, netlist)?;
            Ok(1.0)
        };
        let context = Self::print_eval_context(netlist, None, None);
        Self::evaluate_print_expression_with_probe_calls(expression, context, &mut call_value)
            .map_err(|err| format!("unsupported .PRINT DC expression '{{{expression}}}': {err}"))?;
        Ok(())
    }

    fn evaluate_dc_probe_expression(
        expression: &str,
        netlist: &Netlist,
        dc: &XyceDcSweep,
        sweep_point: XyceDcSweepPoint,
        result: &crate::SimulationResult,
        op_report: &crate::circuit::DeviceOpReport,
    ) -> Result<f64, String> {
        let context = Self::print_eval_context(netlist, Some(dc), Some(sweep_point));
        let mut call_value = |call: &str| {
            let normalized = Self::normalize_probe(call);
            Self::evaluate_atomic_dc_probe(&normalized, netlist, dc, sweep_point, result, op_report)
        };
        Self::evaluate_print_expression_with_probe_calls(expression, context, &mut call_value)
            .map_err(|err| {
                format!("failed to evaluate .PRINT DC expression '{{{expression}}}': {err}")
            })
    }

    fn evaluate_ac_reference_column(
        column: &XyceAcReferenceColumn,
        netlist: &Netlist,
        result: &AcResult,
        phase_output_radians: bool,
    ) -> Result<Value, String> {
        match column {
            XyceAcReferenceColumn::Probe { name, component } => match component {
                XyceAcProbeComponent::Scalar => {
                    Self::evaluate_ac_probe(name, netlist, result, phase_output_radians)
                }
                XyceAcProbeComponent::Real => {
                    Ok(Self::evaluate_ac_complex_probe(name, netlist, result)?.re)
                }
                XyceAcProbeComponent::Imaginary => {
                    Ok(Self::evaluate_ac_complex_probe(name, netlist, result)?.im)
                }
            },
        }
    }

    fn hb_frequency_result_to_prn_table(
        reference: &XycePrnTable,
        print: &XycePrintRequest,
        netlist: &Netlist,
        result: &crate::analysis::HbResult,
    ) -> Result<XycePrnTable, String> {
        if reference.columns.len() < 3
            || reference.columns.first().map(String::as_str) != Some("Index")
            || reference.columns.get(1).map(String::as_str) != Some("FREQ")
        {
            return Err(
                "HB.FD ACComparator table must begin with exact 'Index FREQ' columns".to_string(),
            );
        }
        let data_columns = Self::reference_ac_data_columns(reference, print, 2)?;
        let expected_rows = 2 * result.num_harmonics + 1;
        if reference.rows.len() != expected_rows {
            return Err(format!(
                "HB.FD oracle has {} rows, expected {expected_rows} for {} harmonics",
                reference.rows.len(),
                result.num_harmonics
            ));
        }

        let node_names = result
            .spectral_voltages
            .iter()
            .map(|node| node.node_name.clone())
            .collect::<Vec<_>>();
        let mut rows = Vec::with_capacity(expected_rows);
        for (row_index, signed_harmonic) in
            (-(result.num_harmonics as isize)..=result.num_harmonics as isize).enumerate()
        {
            let harmonic = signed_harmonic.unsigned_abs();
            let voltages = result
                .spectral_voltages
                .iter()
                .map(|node| {
                    let coefficient =
                        node.coefficients.get(harmonic).copied().ok_or_else(|| {
                            format!(
                                "HB node '{}' is missing harmonic {harmonic}",
                                node.node_name
                            )
                        })?;
                    let coefficient = if harmonic == 0 {
                        coefficient
                    } else {
                        coefficient / 2.0
                    };
                    Ok(if signed_harmonic < 0 {
                        coefficient.conj()
                    } else {
                        coefficient
                    })
                })
                .collect::<Result<Vec<_>, String>>()?;
            let frequency = signed_harmonic as Value * result.fundamental_freq;
            let ac_result = AcResult {
                frequency,
                node_names: node_names.clone(),
                branch_names: Vec::new(),
                voltages,
                currents: Vec::new(),
            };
            let mut row = Vec::with_capacity(reference.columns.len());
            row.push(row_index as Value);
            row.push(frequency);
            for column in &data_columns {
                row.push(Self::evaluate_ac_reference_column(
                    column, netlist, &ac_result, false,
                )?);
            }
            rows.push(row);
        }
        Ok(XycePrnTable {
            columns: reference.columns.clone(),
            rows,
        })
    }

    fn hb_result_to_transient_result(result: &crate::analysis::HbResult) -> TransientResult {
        let sample_count = 2 * result.num_harmonics + 1;
        let period = result.fundamental_freq.recip();
        let time = (0..sample_count)
            .map(|sample| sample as Value * period / sample_count as Value)
            .collect::<Vec<_>>();
        let voltages = result
            .spectral_voltages
            .iter()
            .map(|node| {
                time.iter()
                    .map(|time| {
                        let mut value = node
                            .coefficients
                            .first()
                            .map(|value| value.re)
                            .unwrap_or(0.0);
                        for (harmonic, coefficient) in
                            node.coefficients.iter().copied().enumerate().skip(1)
                        {
                            let angle = std::f64::consts::TAU
                                * harmonic as Value
                                * result.fundamental_freq
                                * time;
                            value += (coefficient * Complex64::from_polar(1.0, angle)).re;
                        }
                        value
                    })
                    .collect()
            })
            .collect::<Vec<_>>();
        TransientResult {
            time,
            voltages,
            branch_currents: Vec::new(),
            num_nodes: result.spectral_voltages.len(),
            node_names: result
                .spectral_voltages
                .iter()
                .map(|node| node.node_name.clone())
                .collect(),
            branch_names: Vec::new(),
            digital_traces: Vec::new(),
            real_traces: Vec::new(),
            device_op_traces: Vec::new(),
        }
    }

    fn hb_transient_result_to_prn_table(
        print: &XycePrintRequest,
        netlist: &Netlist,
        result: &TransientResult,
    ) -> Result<XycePrnTable, String> {
        Self::validate_transient_result_time_grid(result)?;
        let columns = Self::transient_prn_header_columns(print, true);
        let mut rows = Vec::with_capacity(result.time.len());
        for (index, time) in result.time.iter().copied().enumerate() {
            let mut row = Vec::with_capacity(columns.len());
            row.push(index as Value);
            row.push(time);
            for probe in &print.probes {
                row.push(Self::evaluate_tran_probe(probe, netlist, result, time)?);
            }
            rows.push(row);
        }
        Ok(XycePrnTable { columns, rows })
    }

    fn compare_ac_comparator_tables(
        &self,
        gold: &XycePrnTable,
        test: &XycePrnTable,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        self.compare_ac_comparator_tables_with_tolerance(
            gold,
            test,
            XyceAcComparatorTolerance::new(1.0e-6, 1.0e-3, 1.0e-10, 1.0e-6)
                .expect("built-in ACComparator tolerance is valid"),
        )
    }

    fn compare_ac_comparator_tables_with_tolerance(
        &self,
        gold: &XycePrnTable,
        test: &XycePrnTable,
        tolerance: XyceAcComparatorTolerance,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        let (absolute_tolerance, relative_tolerance, zero_tolerance, frequency_relative_tolerance) =
            tolerance.values();

        if gold.columns.len() < 2 || test.columns.len() < 2 {
            return Err(format!(
                "ACComparator tables require at least Index and FREQ columns, got gold={:?}, test={:?}",
                gold.columns, test.columns
            ));
        }
        if gold.columns != test.columns {
            return Err(format!(
                "ACComparator headers differ: gold {:?}, test {:?}",
                gold.columns, test.columns
            ));
        }
        if gold.rows.len() != test.rows.len() {
            return Err(format!(
                "ACComparator row counts differ: gold {}, test {}",
                gold.rows.len(),
                test.rows.len()
            ));
        }
        let mut mismatches = Vec::new();
        for (row_index, (gold_row, test_row)) in gold.rows.iter().zip(&test.rows).enumerate() {
            if gold_row.len() != gold.columns.len() || test_row.len() != test.columns.len() {
                return Err(format!(
                    "ACComparator row {row_index} width differs from its header"
                ));
            }
            if gold_row[0] != test_row[0] {
                mismatches.push(XyceValueMismatch {
                    row: row_index,
                    probe: gold.columns[0].clone(),
                    expected: gold_row[0],
                    actual: test_row[0],
                    relative_error: 1.0,
                });
                if mismatches.len() >= self.config.max_mismatches {
                    return Ok(mismatches);
                }
            }
            if gold_row[1] != test_row[1] {
                let difference = (test_row[1] - gold_row[1]).abs();
                let failed = if gold_row[1] == 0.0 {
                    test_row[1] > absolute_tolerance
                } else {
                    difference / gold_row[1] > frequency_relative_tolerance
                };
                if failed {
                    mismatches.push(XyceValueMismatch {
                        row: row_index,
                        probe: gold.columns[1].clone(),
                        expected: gold_row[1],
                        actual: test_row[1],
                        relative_error: difference / gold_row[1].abs().max(absolute_tolerance),
                    });
                    if mismatches.len() >= self.config.max_mismatches {
                        return Ok(mismatches);
                    }
                }
            }
            for column in 2..gold.columns.len() {
                let expected = gold_row[column];
                let actual = test_row[column];
                if expected == actual
                    || (expected.abs() < zero_tolerance && actual.abs() < zero_tolerance)
                {
                    continue;
                }
                let absolute_difference = (actual - expected).abs();
                let relative_difference = absolute_difference / expected.abs();
                if !(absolute_difference < absolute_tolerance
                    && relative_difference < relative_tolerance)
                {
                    mismatches.push(XyceValueMismatch {
                        row: row_index,
                        probe: gold.columns[column].clone(),
                        expected,
                        actual,
                        relative_error: relative_difference,
                    });
                }
                if mismatches.len() >= self.config.max_mismatches {
                    return Ok(mismatches);
                }
            }
            if mismatches.len() >= self.config.max_mismatches {
                return Ok(mismatches);
            }
        }
        Ok(mismatches)
    }

    fn evaluate_ac_probe(
        probe: &str,
        netlist: &Netlist,
        result: &AcResult,
        phase_output_radians: bool,
    ) -> Result<Value, String> {
        if let Some(expression) = Self::print_expression_inner(probe) {
            let normalized_expression = Self::normalize_probe(expression);
            if Self::braced_expression_is_atomic_ac_probe(&normalized_expression, netlist) {
                return Self::evaluate_atomic_ac_probe(
                    &normalized_expression,
                    netlist,
                    result,
                    phase_output_radians,
                );
            }
            return Ok(Self::evaluate_ac_complex_expression(expression, netlist, result)?.re);
        }

        let normalized = Self::normalize_probe(probe);
        Self::evaluate_atomic_ac_probe(&normalized, netlist, result, phase_output_radians)
            .or_else(|_| Ok(Self::evaluate_ac_complex_expression(probe, netlist, result)?.re))
    }

    fn evaluate_atomic_ac_probe(
        normalized: &str,
        netlist: &Netlist,
        result: &AcResult,
        phase_output_radians: bool,
    ) -> Result<Value, String> {
        if let Some(voltage_probe) = Self::parse_ac_voltage_probe(normalized) {
            let value = Self::evaluate_ac_voltage_probe(&voltage_probe, netlist, result)?;
            return voltage_probe
                .accessor
                .evaluate_ac_scalar(value, phase_output_radians)
                .ok_or_else(|| {
                    format!(
                        "AC probe '{}' is complex-valued; compare Re()/Im() columns or use VM/VP/VDB",
                        normalized
                    )
                });
        }

        if let Some(current_probe) = Self::parse_ac_current_probe(normalized) {
            let current = Self::ac_branch_current_named(result, &current_probe.element_name)
                .ok_or_else(|| {
                    format!(
                        "branch '{}' not found in AC result",
                        current_probe.element_name
                    )
                })?;
            return current_probe
                .accessor
                .evaluate_ac_scalar(current, phase_output_radians)
                .ok_or_else(|| {
                    format!(
                        "AC probe '{}' is complex-valued; compare Re()/Im() columns or use IR/II/IM/IP/IDB",
                        normalized
                    )
                });
        }

        if let Some(value) = Self::evaluate_static_ac_device_parameter_probe(netlist, normalized) {
            return value;
        }

        Err(format!("unsupported AC probe '{}'", normalized))
    }

    fn evaluate_ac_complex_probe(
        probe: &str,
        netlist: &Netlist,
        result: &AcResult,
    ) -> Result<Complex64, String> {
        let normalized = Self::normalize_probe(probe);
        if let Some(voltage_probe) = Self::parse_ac_voltage_probe(&normalized) {
            if voltage_probe.accessor != XyceVoltageAccessor::Value {
                return Err(format!(
                    "AC complex probe '{}' must use bare V(...) accessor",
                    probe.trim()
                ));
            }
            return Self::evaluate_ac_voltage_probe(&voltage_probe, netlist, result);
        }
        if let Some(current_probe) = Self::parse_ac_current_probe(&normalized) {
            if current_probe.accessor != XyceCurrentAccessor::Value {
                return Err(format!(
                    "AC complex probe '{}' must use bare I(...) accessor",
                    probe.trim()
                ));
            }
            return Self::ac_branch_current_named(result, &current_probe.element_name).ok_or_else(
                || {
                    format!(
                        "branch '{}' not found in AC result",
                        current_probe.element_name
                    )
                },
            );
        }
        Self::evaluate_ac_complex_expression(probe, netlist, result)
    }

    fn evaluate_ac_complex_expression(
        expression: &str,
        netlist: &Netlist,
        result: &AcResult,
    ) -> Result<Complex64, String> {
        let context = Self::print_eval_context(netlist, None, None);
        let mut call_value =
            |call: &str| Self::evaluate_ac_expression_call_probe(call, netlist, result);
        let (rewritten, context) =
            Self::rewrite_ac_print_expression_complex(expression, context, &mut call_value)?;
        let value =
            crate::netlist::expr::eval_expression_complex(&rewritten, &context).map_err(|err| {
                format!("failed to evaluate .PRINT AC expression '{{{expression}}}': {err}")
            })?;
        Ok(Complex64::new(value.re, value.im))
    }

    fn evaluate_ac_expression_call_probe(
        call: &str,
        netlist: &Netlist,
        result: &AcResult,
    ) -> Result<ExprComplexValue, String> {
        let normalized = Self::normalize_probe(call);
        if let Some(voltage_probe) = Self::parse_ac_voltage_probe(&normalized) {
            let value = Self::evaluate_ac_voltage_probe(&voltage_probe, netlist, result)?;
            return Ok(
                match voltage_probe
                    .accessor
                    .evaluate_ac_scalar(value, false)
                    .map(ExprComplexValue::real)
                {
                    Some(value) => value,
                    None => ExprComplexValue::new(value.re, value.im),
                },
            );
        }
        if let Some(current_probe) = Self::parse_ac_current_probe(&normalized) {
            let current = Self::ac_branch_current_named(result, &current_probe.element_name)
                .ok_or_else(|| {
                    format!(
                        "branch '{}' not found in AC result",
                        current_probe.element_name
                    )
                })?;
            return Ok(
                match current_probe
                    .accessor
                    .evaluate_ac_scalar(current, false)
                    .map(ExprComplexValue::real)
                {
                    Some(value) => value,
                    None => ExprComplexValue::new(current.re, current.im),
                },
            );
        }
        let value = Self::evaluate_ac_complex_probe(call, netlist, result)?;
        Ok(ExprComplexValue::new(value.re, value.im))
    }

    fn evaluate_ac_voltage_probe(
        probe: &XyceVoltageProbe,
        netlist: &Netlist,
        result: &AcResult,
    ) -> Result<Complex64, String> {
        let pos = Self::ac_node_voltage_named(result, netlist, &probe.node_pos)
            .ok_or_else(|| format!("node '{}' not found in AC result", probe.node_pos))?;
        let neg = match probe.node_neg.as_deref() {
            Some(node) => Self::ac_node_voltage_named(result, netlist, node)
                .ok_or_else(|| format!("node '{}' not found in AC result", node))?,
            None => Complex64::new(0.0, 0.0),
        };
        Ok(pos - neg)
    }

    fn evaluate_static_ac_device_parameter_probe(
        netlist: &Netlist,
        normalized: &str,
    ) -> Option<Result<Value, String>> {
        let (element_name, parameter) = Self::parse_device_parameter_probe(normalized)?;
        Some(match parameter.as_str() {
            "acmag" => Self::independent_source_ac_terms(netlist, &element_name)
                .map(|(magnitude, _)| magnitude)
                .ok_or_else(|| {
                    format!(
                        "AC device parameter probe '{element_name}:ACMAG' has no independent source"
                    )
                }),
            "acphase" => Self::independent_source_ac_terms(netlist, &element_name)
                .map(|(_, phase)| phase.to_degrees())
                .ok_or_else(|| {
                    format!(
                        "AC device parameter probe '{element_name}:ACPHASE' has no independent source"
                    )
                }),
            "r" => Self::effective_resistor_value(netlist, &element_name).ok_or_else(|| {
                format!("AC device parameter probe '{element_name}:R' has no finite resistance")
            }),
            "c" => Self::effective_capacitor_value(netlist, &element_name).ok_or_else(|| {
                format!("AC device parameter probe '{element_name}:C' has no finite capacitance")
            }),
            "l" => Self::effective_inductor_value(netlist, &element_name).ok_or_else(|| {
                format!("AC device parameter probe '{element_name}:L' has no finite inductance")
            }),
            _ => Err(format!(
                "AC device parameter probe '{element_name}:{parameter}' is not supported"
            )),
        })
    }

    fn evaluate_tran_probe(
        probe: &str,
        netlist: &Netlist,
        result: &TransientResult,
        time: Value,
    ) -> Result<f64, String> {
        if let Some(expression) = Self::print_expression_inner(probe) {
            let normalized_expression = Self::normalize_probe(expression);
            if Self::braced_expression_is_atomic_real_probe(&normalized_expression, netlist) {
                return Self::evaluate_atomic_tran_probe(
                    &normalized_expression,
                    netlist,
                    result,
                    time,
                );
            }
            if Self::print_expression_contains_probe_reference(expression) {
                return Self::evaluate_tran_probe_expression(expression, netlist, result, time);
            }
            let context = Self::print_tran_eval_context(netlist, time);
            return crate::netlist::expr::eval_expression(expression, &context).map_err(|err| {
                format!("failed to evaluate .PRINT TRAN expression '{{{expression}}}': {err}")
            });
        }

        let normalized = Self::normalize_probe(probe);
        Self::evaluate_atomic_tran_probe(&normalized, netlist, result, time)
    }

    fn stateful_tran_print_expression(
        probe: &str,
        netlist: &Netlist,
    ) -> Result<Option<StatefulTranPrintExpression>, String> {
        let Some(expression) = Self::print_expression_inner(probe) else {
            return Ok(None);
        };
        if !Self::print_expression_contains_stateful_sdt(expression, &netlist.params) {
            return Ok(None);
        }
        let (expression, context, _) = Self::rewrite_print_device_parameter_tokens_maybe(
            expression,
            netlist.params.clone(),
            |token| Self::static_transient_device_parameter_value(netlist, token),
        )?;
        let prepared = prepare_behavioral_expression(&expression, &context).map_err(|err| {
            format!("could not prepare stateful .PRINT TRAN expression '{{{expression}}}': {err}")
        })?;
        let ast = parse_expression_strict(&prepared).map_err(|err| {
            format!("could not parse stateful .PRINT TRAN expression '{{{expression}}}': {err}")
        })?;
        if !Self::expression_contains_sdt(&ast) {
            return Ok(None);
        }
        Ok(Some(StatefulTranPrintExpression {
            program: compile(&ast),
            vm: Vm::new(),
        }))
    }

    fn static_transient_device_parameter_value(
        netlist: &Netlist,
        token: &str,
    ) -> Result<Value, String> {
        let normalized = Self::normalize_probe(token);
        let (element_name, parameter) = Self::parse_device_parameter_probe(&normalized)
            .ok_or_else(|| format!("invalid transient device parameter token '{token}'"))?;
        match parameter.as_str() {
            "r" => Self::effective_resistor_value(netlist, &element_name).ok_or_else(|| {
                format!("resistor parameter probe '{token}' has no finite resistance")
            }),
            "c" => Self::effective_capacitor_value(netlist, &element_name).ok_or_else(|| {
                format!("capacitor parameter probe '{token}' has no finite capacitance")
            }),
            "l" => Self::effective_inductor_value(netlist, &element_name).ok_or_else(|| {
                format!("inductor parameter probe '{token}' has no finite inductance")
            }),
            "temp" => Self::resistor_temperature_value(netlist, &element_name).ok_or_else(|| {
                format!("resistor parameter probe '{token}' has no finite temperature")
            }),
            _ => Err(format!(
                "device parameter probe '{token}' is not supported in stateful transient output"
            )),
        }
    }

    fn stateful_tran_probe_waveform(
        probe: &str,
        netlist: &Netlist,
        result: &TransientResult,
    ) -> Result<Option<Vec<Value>>, String> {
        let Some(mut runtime) = Self::stateful_tran_print_expression(probe, netlist)? else {
            return Ok(None);
        };
        let mut values = Vec::with_capacity(result.time.len());
        for &time in &result.time {
            values.push(Self::evaluate_stateful_tran_print_expression(
                &mut runtime,
                netlist,
                result,
                time,
            )?);
        }
        Ok(Some(values))
    }

    fn derived_tran_probe_waveform(
        probe: &str,
        netlist: &Netlist,
        result: &TransientResult,
    ) -> Result<Option<Vec<Value>>, String> {
        let traces =
            crate::analysis::advanced::evaluate_tran_equation_measurements(netlist, result)?;
        if let Some(trace) = traces
            .iter()
            .find(|trace| trace.name.eq_ignore_ascii_case(probe))
        {
            return Ok(Some(trace.values.clone()));
        }

        if let Some(expression) = Self::print_expression_inner(probe) {
            let upper = expression.to_ascii_uppercase();
            let references_measure = traces.iter().any(|trace| {
                let name = trace.name.to_ascii_uppercase();
                upper.match_indices(&name).any(|(start, _)| {
                    let end = start + name.len();
                    let identifier = |byte: u8| byte.is_ascii_alphanumeric() || byte == b'_';
                    (start == 0 || !identifier(upper.as_bytes()[start - 1]))
                        && (end == upper.len() || !identifier(upper.as_bytes()[end]))
                })
            });
            if references_measure {
                let mut values = Vec::with_capacity(result.time.len());
                for (row, &time) in result.time.iter().enumerate() {
                    let mut context = Self::print_tran_eval_context(netlist, time);
                    for trace in &traces {
                        context.set(&trace.name, trace.values[row]);
                    }
                    let mut call_value = |call: &str| {
                        Self::evaluate_atomic_tran_probe(
                            &Self::normalize_probe(call),
                            netlist,
                            result,
                            time,
                        )
                    };
                    values.push(Self::evaluate_print_expression_with_probe_calls(
                        expression,
                        context,
                        &mut call_value,
                    )?);
                }
                return Ok(Some(values));
            }
        }

        Self::stateful_tran_probe_waveform(probe, netlist, result)
    }

    fn expression_contains_sdt(expression: &Expr) -> bool {
        match expression {
            Expr::Function { func, args } => {
                matches!(func, crate::expr::Function::Sdt)
                    || args.iter().any(Self::expression_contains_sdt)
            }
            Expr::Unary { operand, .. } => Self::expression_contains_sdt(operand),
            Expr::Binary { left, right, .. } => {
                Self::expression_contains_sdt(left) || Self::expression_contains_sdt(right)
            }
            Expr::Const(_)
            | Expr::NodeVoltage(_)
            | Expr::BranchCurrent(_)
            | Expr::StringLiteral(_)
            | Expr::LookupTable(_)
            | Expr::Time
            | Expr::Frequency
            | Expr::Temperature => false,
        }
    }

    fn evaluate_stateful_tran_print_expression(
        runtime: &mut StatefulTranPrintExpression,
        netlist: &Netlist,
        result: &TransientResult,
        time: Value,
    ) -> Result<Value, String> {
        let mut voltages = vec![0.0; runtime.program.node_map.len()];
        for (name, &index) in &runtime.program.node_map {
            voltages[index] = Self::transient_voltage_named(result, netlist, name, time)?;
        }
        let mut currents = vec![0.0; runtime.program.branch_map.len()];
        for (name, &index) in &runtime.program.branch_map {
            currents[index] = Self::transient_branch_current_named(result, name, time)
                .or_else(|| {
                    Self::evaluate_independent_current_source_probe(netlist, result, name, time)
                })
                .ok_or_else(|| format!("branch current '{name}' not found in transient result"))?;
        }
        let context = Context::transient(&voltages, &currents, time)
            .with_expression_dialect(ExpressionDialect::Xyce);
        let value = runtime.vm.execute(&runtime.program, &context);
        runtime.vm.accept_transient_step(time);
        Ok(value)
    }

    fn evaluate_atomic_tran_probe(
        normalized: &str,
        netlist: &Netlist,
        result: &TransientResult,
        time: Value,
    ) -> Result<f64, String> {
        if normalized == "time" {
            return Ok(time);
        }

        if let Some(voltage_probe) = Self::parse_tran_voltage_probe(normalized) {
            let pos =
                Self::transient_voltage_named(result, netlist, &voltage_probe.node_pos, time)?;
            let neg = match voltage_probe.node_neg {
                Some(node) => Self::transient_voltage_named(result, netlist, &node, time)?,
                None => 0.0,
            };
            return Ok(voltage_probe.accessor.evaluate_dc(pos - neg));
        }

        if let Some(element_name) = Self::parse_current_probe(normalized) {
            if let Some(current) = Self::transient_branch_current_named(result, &element_name, time)
            {
                return Ok(current);
            }
            if let Some(value) = Self::evaluate_independent_current_source_probe(
                netlist,
                result,
                &element_name,
                time,
            ) {
                return Ok(value);
            }
            return Err(format!(
                "branch current '{}' not found in transient result",
                element_name
            ));
        }

        if let Some(element_name) = Self::parse_power_probe(normalized) {
            if let Some(element) =
                Self::find_recorded_two_terminal_branch_element(netlist, &element_name)
            {
                return Self::evaluate_transient_two_terminal_branch_power(
                    result,
                    time,
                    "device",
                    &element.name,
                    &element,
                );
            }
            return Err(format!(
                "transient power probe '{}' targets an unsupported branch/device",
                element_name
            ));
        }

        if let Some((element_name, parameter)) = Self::parse_device_parameter_probe(normalized) {
            return Self::evaluate_transient_device_parameter_probe(
                netlist,
                result,
                time,
                &element_name,
                &parameter,
            );
        }

        Err(format!("unsupported TRAN probe '{}'", normalized))
    }

    fn evaluate_tran_probe_expression(
        expression: &str,
        netlist: &Netlist,
        result: &TransientResult,
        time: Value,
    ) -> Result<f64, String> {
        let context = Self::print_tran_eval_context(netlist, time);
        let mut call_value = |call: &str| {
            let normalized = Self::normalize_probe(call);
            Self::evaluate_atomic_tran_probe(&normalized, netlist, result, time)
        };
        Self::evaluate_print_expression_with_probe_calls(expression, context, &mut call_value)
            .map_err(|err| {
                format!("failed to evaluate .PRINT TRAN expression '{{{expression}}}': {err}")
            })
    }

    fn transient_branch_current_named(
        result: &TransientResult,
        branch_name: &str,
        time: Value,
    ) -> Option<Value> {
        Self::transient_branch_current_waveform_named(result, branch_name).and_then(|waveform| {
            Self::interpolate_transient_waveform_at(&result.time, waveform, time).ok()
        })
    }

    fn transient_branch_current_waveform_named<'a>(
        result: &'a TransientResult,
        branch_name: &str,
    ) -> Option<&'a [Value]> {
        result
            .try_branch_current_waveform_named(branch_name)
            .or_else(|| {
                let normalized = Self::normalize_device_instance_name(branch_name);
                (normalized != branch_name)
                    .then(|| result.try_branch_current_waveform_named(&normalized))?
            })
    }

    fn evaluate_transient_two_terminal_branch_power(
        result: &TransientResult,
        time: Value,
        device_kind: &str,
        branch_name: &str,
        element: &crate::netlist::Element,
    ) -> Result<Value, String> {
        let node_pos = element
            .nodes
            .first()
            .ok_or_else(|| format!("{device_kind} '{}' has no positive node", element.name))?;
        let node_neg = element
            .nodes
            .get(1)
            .ok_or_else(|| format!("{device_kind} '{}' has no negative node", element.name))?;
        let pos_index = result
            .node_index_named(node_pos)
            .ok_or_else(|| format!("node '{}' not found in transient result", node_pos))?;
        let neg_index = result
            .node_index_named(node_neg)
            .ok_or_else(|| format!("node '{}' not found in transient result", node_neg))?;
        let current = Self::transient_branch_current_waveform_named(result, branch_name)
            .ok_or_else(|| {
                format!(
                    "branch current '{}' not found in transient result",
                    branch_name
                )
            })?;

        if current.len() != result.time.len() {
            return Err(format!(
                "branch current '{}' has {} sample(s) for {} time point(s)",
                branch_name,
                current.len(),
                result.time.len()
            ));
        }

        let mut power = Vec::with_capacity(result.time.len());
        for index in 0..result.time.len() {
            let v_pos = if pos_index == 0 {
                0.0
            } else {
                result.try_voltage_at(pos_index, index).ok_or_else(|| {
                    format!(
                        "node '{}' sample {} not found in transient result",
                        node_pos, index
                    )
                })?
            };
            let v_neg = if neg_index == 0 {
                0.0
            } else {
                result.try_voltage_at(neg_index, index).ok_or_else(|| {
                    format!(
                        "node '{}' sample {} not found in transient result",
                        node_neg, index
                    )
                })?
            };
            power.push((v_pos - v_neg) * current[index]);
        }

        Self::interpolate_transient_waveform_at(&result.time, &power, time)
    }

    fn transient_voltage_named(
        result: &TransientResult,
        netlist: &Netlist,
        node_name: &str,
        time: Value,
    ) -> Result<Value, String> {
        let node = Self::node_lookup_candidates(netlist, node_name)
            .into_iter()
            .find_map(|candidate| result.node_index_named(&candidate))
            .ok_or_else(|| format!("node '{}' not found in transient result", node_name))?;
        if node == 0 {
            return Ok(0.0);
        }
        let waveform = result
            .try_voltage_waveform(node)
            .ok_or_else(|| format!("node '{}' not found in transient result", node_name))?;
        Self::interpolate_transient_waveform_at(&result.time, waveform, time)
    }

    fn validate_transient_result_time_grid(result: &TransientResult) -> Result<(), String> {
        if result.time.is_empty() {
            return Err("transient result has no time points".to_string());
        }
        for (index, time) in result.time.iter().copied().enumerate() {
            if !time.is_finite() {
                return Err(format!(
                    "transient result time point {index} is non-finite ({time})"
                ));
            }
            if index > 0 && time < result.time[index - 1] {
                return Err(format!(
                    "transient result time grid is not monotonic at point {index}"
                ));
            }
        }
        Ok(())
    }

    fn interpolate_transient_waveform_at(
        times: &[Value],
        values: &[Value],
        time: Value,
    ) -> Result<Value, String> {
        if times.len() != values.len() {
            return Err(format!(
                "transient waveform has {} sample(s) for {} time point(s)",
                values.len(),
                times.len()
            ));
        }
        let Some((&first_time, &last_time)) = times.first().zip(times.last()) else {
            return Err("transient waveform has no samples".to_string());
        };
        let scale = first_time.abs().max(last_time.abs()).max(time.abs());
        let edge_tol = (1.0e-12 * scale)
            .max(64.0 * f64::EPSILON * scale)
            .max(1.0e-30);
        if time < first_time - edge_tol || time > last_time + edge_tol {
            return Err(format!(
                "requested transient sample time {time:e} is outside simulated range [{first_time:e}, {last_time:e}]"
            ));
        }
        if time <= first_time + edge_tol {
            return Ok(values[0]);
        }
        if time >= last_time - edge_tol {
            return Ok(*values.last().expect("non-empty waveform"));
        }

        let upper = times.partition_point(|sample| *sample < time);
        if upper == 0 || upper >= times.len() {
            return Err(format!(
                "requested transient sample time {time:e} is outside interpolation brackets"
            ));
        }
        let lower = upper - 1;
        let t0 = times[lower];
        let t1 = times[upper];
        if (time - t0).abs() <= edge_tol {
            return Ok(values[lower]);
        }
        if (time - t1).abs() <= edge_tol {
            return Ok(values[upper]);
        }
        let dt = t1 - t0;
        if !dt.is_finite() || dt <= 0.0 {
            return Err(format!(
                "invalid transient interpolation interval [{t0:e}, {t1:e}]"
            ));
        }
        let alpha = (time - t0) / dt;
        Ok(values[lower] + alpha * (values[upper] - values[lower]))
    }

    fn evaluate_print_expression_with_probe_calls<F>(
        expression: &str,
        context: crate::netlist::ParamContext,
        call_value: &mut F,
    ) -> Result<Value, String>
    where
        F: FnMut(&str) -> Result<Value, String>,
    {
        Self::evaluate_print_expression_internal(expression, context, call_value, None)
    }

    fn evaluate_print_expression_internal<F>(
        expression: &str,
        context: crate::netlist::ParamContext,
        call_value: &mut F,
        override_probe: Option<(&str, Value)>,
    ) -> Result<Value, String>
    where
        F: FnMut(&str) -> Result<Value, String>,
    {
        let (rewritten, context) =
            Self::rewrite_print_ddx_calls(expression, context, call_value, override_probe)?;
        let (rewritten, context, _) =
            Self::rewrite_print_expression_calls_maybe(&rewritten, context, |call| {
                Self::print_probe_value(call, call_value, override_probe)
            })?;
        let (rewritten, context, _) =
            Self::rewrite_print_device_parameter_tokens_maybe(&rewritten, context, |call| {
                Self::print_probe_value(call, call_value, override_probe)
            })?;
        crate::netlist::expr::eval_expression(&rewritten, &context).map_err(|err| err.to_string())
    }

    fn print_probe_value<F>(
        call: &str,
        call_value: &mut F,
        override_probe: Option<(&str, Value)>,
    ) -> Result<Value, String>
    where
        F: FnMut(&str) -> Result<Value, String>,
    {
        if let Some((override_name, override_value)) = override_probe {
            if Self::normalize_probe(call) == override_name {
                return Ok(override_value);
            }
        }
        call_value(call)
    }

    fn rewrite_print_ddx_calls<F>(
        expression: &str,
        mut context: crate::netlist::ParamContext,
        call_value: &mut F,
        override_probe: Option<(&str, Value)>,
    ) -> Result<(String, crate::netlist::ParamContext), String>
    where
        F: FnMut(&str) -> Result<Value, String>,
    {
        let mut rewritten = String::with_capacity(expression.len());
        let mut index = 0usize;
        let mut placeholder_index = 0usize;

        while index < expression.len() {
            if let Some(open_index) = Self::print_ddx_call_open_index(expression, index) {
                let close_index = Self::matching_parenthesis_index(expression, open_index)?;
                let call = &expression[index..=close_index];
                let placeholder = format!("__rspice_ddx_{placeholder_index}");
                let value =
                    Self::evaluate_print_ddx_call(call, &context, call_value, override_probe)?;
                context.set(&placeholder, value);
                rewritten.push_str(&placeholder);
                placeholder_index += 1;
                index = close_index + 1;
                continue;
            }

            let ch = expression[index..]
                .chars()
                .next()
                .expect("valid char boundary");
            match ch {
                '{' => rewritten.push('('),
                '}' => rewritten.push(')'),
                _ => rewritten.push(ch),
            }
            index += ch.len_utf8();
        }

        Ok((rewritten, context))
    }

    fn evaluate_print_ddx_call<F>(
        call: &str,
        context: &crate::netlist::ParamContext,
        call_value: &mut F,
        override_probe: Option<(&str, Value)>,
    ) -> Result<Value, String>
    where
        F: FnMut(&str) -> Result<Value, String>,
    {
        let open_index = call
            .find('(')
            .ok_or_else(|| format!("malformed DDX call '{call}'"))?;
        let inner = call[open_index + 1..]
            .strip_suffix(')')
            .ok_or_else(|| format!("malformed DDX call '{call}'"))?;
        let args = Self::split_top_level_args(inner)?;
        if args.len() != 2 {
            return Err(format!(
                "DDX expects exactly two arguments, got {} in '{call}'",
                args.len()
            ));
        }

        let expression = args[0].trim();
        let variable = args[1].trim();
        if Self::parse_voltage_probe(variable).is_none()
            && Self::parse_current_probe(variable).is_none()
            && Self::parse_power_probe(variable).is_none()
            && Self::parse_lead_current_probe(variable).is_none()
            && Self::parse_device_operating_point_probe(variable).is_none()
            && Self::parse_device_parameter_probe(variable).is_none()
        {
            return Err(format!(
                "DDX derivative variable '{variable}' is not a supported print probe"
            ));
        }

        let normalized_variable = Self::normalize_probe(variable);
        let center = Self::print_probe_value(variable, call_value, override_probe)?;
        if !center.is_finite() {
            return Err(format!(
                "DDX derivative variable '{variable}' evaluated to non-finite value {center}"
            ));
        }

        Self::central_difference_derivative(center, |point| {
            Self::evaluate_print_expression_internal(
                expression,
                context.clone(),
                call_value,
                Some((&normalized_variable, point)),
            )
        })
    }

    fn central_difference_derivative<F>(center: Value, mut eval_at: F) -> Result<Value, String>
    where
        F: FnMut(Value) -> Result<Value, String>,
    {
        let scale = center.abs().max(1.0);
        let mut last_finite = None;
        for relative_step in [1.0e-4, 3.0e-5, 1.0e-5, 3.0e-6, 1.0e-6] {
            let step = scale * relative_step;
            let hi = eval_at(center + step)?;
            let lo = eval_at(center - step)?;
            let derivative = (hi - lo) / (2.0 * step);
            if derivative.is_finite() {
                last_finite = Some(derivative);
            }
        }
        last_finite.ok_or_else(|| "DDX derivative evaluated to a non-finite value".to_string())
    }

    fn split_top_level_args(input: &str) -> Result<Vec<String>, String> {
        let mut args = Vec::new();
        let mut start = 0usize;
        let mut paren_depth = 0usize;
        let mut brace_depth = 0usize;

        for (index, ch) in input.char_indices() {
            match ch {
                '(' => paren_depth += 1,
                ')' => {
                    paren_depth = paren_depth.checked_sub(1).ok_or_else(|| {
                        format!("unbalanced ')' while parsing function arguments '{input}'")
                    })?;
                }
                '{' => brace_depth += 1,
                '}' => {
                    brace_depth = brace_depth.checked_sub(1).ok_or_else(|| {
                        format!("unbalanced '}}' while parsing function arguments '{input}'")
                    })?;
                }
                ',' if paren_depth == 0 && brace_depth == 0 => {
                    args.push(input[start..index].trim().to_string());
                    start = index + ch.len_utf8();
                }
                _ => {}
            }
        }

        if paren_depth != 0 || brace_depth != 0 {
            return Err(format!(
                "unbalanced delimiters while parsing function arguments '{input}'"
            ));
        }
        args.push(input[start..].trim().to_string());
        if args.iter().any(|arg| arg.is_empty()) {
            return Err(format!("empty function argument in '{input}'"));
        }
        Ok(args)
    }

    fn print_ddx_call_open_index(expression: &str, index: usize) -> Option<usize> {
        if index >= expression.len() || !expression.is_char_boundary(index) {
            return None;
        }
        let tail = &expression[index..];
        if !tail
            .get(..3)
            .is_some_and(|prefix| prefix.eq_ignore_ascii_case("ddx"))
        {
            return None;
        }
        let previous = expression[..index].chars().next_back();
        if previous.is_some_and(Self::print_identifier_char) {
            return None;
        }

        let mut next_index = index + 3;
        while next_index < expression.len() {
            let ch = expression[next_index..].chars().next()?;
            if !ch.is_whitespace() {
                break;
            }
            next_index += ch.len_utf8();
        }
        expression[next_index..]
            .starts_with('(')
            .then_some(next_index)
    }

    fn rewrite_print_expression_calls<F>(
        expression: &str,
        context: crate::netlist::ParamContext,
        call_value: F,
    ) -> Result<(String, crate::netlist::ParamContext), String>
    where
        F: FnMut(&str) -> Result<Value, String>,
    {
        let (rewritten, context, placeholder_index) =
            Self::rewrite_print_expression_calls_maybe(expression, context, call_value)?;

        if placeholder_index == 0 {
            return Err(format!(
                ".PRINT DC expression '{{{expression}}}' does not contain a supported voltage, current, power, or device probe"
            ));
        }

        Ok((rewritten, context))
    }

    fn rewrite_print_expression_calls_maybe<F>(
        expression: &str,
        mut context: crate::netlist::ParamContext,
        mut call_value: F,
    ) -> Result<(String, crate::netlist::ParamContext, usize), String>
    where
        F: FnMut(&str) -> Result<Value, String>,
    {
        let mut rewritten = String::with_capacity(expression.len());
        let mut index = 0usize;
        let mut placeholder_index = 0usize;

        while index < expression.len() {
            if let Some(open_index) = Self::print_probe_call_open_index(expression, index) {
                let close_index = Self::matching_parenthesis_index(expression, open_index)?;
                let call = &expression[index..=close_index];
                let placeholder = format!("__rspice_probe_{placeholder_index}");
                let value = call_value(call)?;
                context.set(&placeholder, value);
                rewritten.push_str(&placeholder);
                placeholder_index += 1;
                index = close_index + 1;
                continue;
            }

            let ch = expression[index..]
                .chars()
                .next()
                .expect("valid char boundary");
            match ch {
                '{' => rewritten.push('('),
                '}' => rewritten.push(')'),
                _ => rewritten.push(ch),
            }
            index += ch.len_utf8();
        }

        Ok((rewritten, context, placeholder_index))
    }

    fn rewrite_ac_print_expression_complex<F>(
        expression: &str,
        mut context: crate::netlist::ParamContext,
        call_value: &mut F,
    ) -> Result<(String, crate::netlist::ParamContext), String>
    where
        F: FnMut(&str) -> Result<ExprComplexValue, String>,
    {
        let expression = Self::print_expression_inner(expression).unwrap_or(expression);
        let mut rewritten = String::with_capacity(expression.len());
        let mut index = 0usize;
        let mut placeholder_index = 0usize;

        while index < expression.len() {
            if let Some(open_index) = Self::print_probe_call_open_index(expression, index) {
                let close_index = Self::matching_parenthesis_index(expression, open_index)?;
                let call = &expression[index..=close_index];
                let placeholder = format!("__rspice_ac_probe_{placeholder_index}");
                let value = call_value(call)?;
                context.set_complex(&placeholder, value);
                rewritten.push_str(&placeholder);
                placeholder_index += 1;
                index = close_index + 1;
                continue;
            }

            let ch = expression[index..]
                .chars()
                .next()
                .expect("valid char boundary");
            match ch {
                '{' => rewritten.push('('),
                '}' => rewritten.push(')'),
                _ => rewritten.push(ch),
            }
            index += ch.len_utf8();
        }

        Ok((rewritten, context))
    }

    fn rewrite_print_device_parameter_tokens_maybe<F>(
        expression: &str,
        mut context: crate::netlist::ParamContext,
        mut call_value: F,
    ) -> Result<(String, crate::netlist::ParamContext, usize), String>
    where
        F: FnMut(&str) -> Result<Value, String>,
    {
        let mut rewritten = String::with_capacity(expression.len());
        let mut index = 0usize;
        let mut placeholder_index = 0usize;

        while index < expression.len() {
            if let Some((end_index, token)) =
                Self::print_device_parameter_token_at(expression, index)
            {
                let placeholder = format!("__rspice_param_{placeholder_index}");
                let value = call_value(token)?;
                context.set(&placeholder, value);
                rewritten.push_str(&placeholder);
                placeholder_index += 1;
                index = end_index;
                continue;
            }

            let ch = expression[index..]
                .chars()
                .next()
                .expect("valid char boundary");
            rewritten.push(ch);
            index += ch.len_utf8();
        }

        Ok((rewritten, context, placeholder_index))
    }

    fn print_expression_inner(probe: &str) -> Option<&str> {
        let trimmed = probe.trim();
        trimmed
            .strip_prefix('{')
            .and_then(|value| value.strip_suffix('}'))
            .map(str::trim)
            .filter(|value| !value.is_empty())
    }

    fn print_expression_contains_probe_call(expression: &str) -> bool {
        let mut index = 0usize;
        while index < expression.len() {
            if Self::print_probe_call_open_index(expression, index).is_some() {
                return true;
            }
            let ch = expression[index..]
                .chars()
                .next()
                .expect("valid char boundary");
            index += ch.len_utf8();
        }
        false
    }

    fn print_expression_contains_named_call(expression: &str, name: &str) -> bool {
        let bytes = expression.as_bytes();
        let mut index = 0usize;
        while index < bytes.len() {
            if matches!(bytes[index], b'\'' | b'"') {
                let quote = bytes[index];
                index += 1;
                while index < bytes.len() && bytes[index] != quote {
                    index += 1;
                }
                index = (index + 1).min(bytes.len());
                continue;
            }
            if bytes[index].is_ascii_alphabetic() || bytes[index] == b'_' {
                let start = index;
                index += 1;
                while index < bytes.len()
                    && (bytes[index].is_ascii_alphanumeric() || bytes[index] == b'_')
                {
                    index += 1;
                }
                let identifier = &expression[start..index];
                while index < bytes.len() && bytes[index].is_ascii_whitespace() {
                    index += 1;
                }
                if identifier.eq_ignore_ascii_case(name)
                    && bytes.get(index).is_some_and(|byte| *byte == b'(')
                {
                    return true;
                }
                continue;
            }
            index += 1;
        }
        false
    }

    fn print_expression_contains_stateful_sdt(
        expression: &str,
        params: &crate::netlist::ParamContext,
    ) -> bool {
        if Self::print_expression_contains_named_call(expression, "sdt") {
            return true;
        }

        let functions = params.all_functions();
        let mut stateful_functions: BTreeSet<String> = BTreeSet::new();
        loop {
            let mut changed = false;
            for function in &functions {
                if stateful_functions.contains(&function.name) {
                    continue;
                }
                let contains_sdt =
                    Self::print_expression_contains_named_call(&function.body, "sdt")
                        || stateful_functions.iter().any(|name| {
                            Self::print_expression_contains_named_call(&function.body, name)
                        });
                if contains_sdt {
                    changed |= stateful_functions.insert(function.name.clone());
                }
            }
            if !changed {
                break;
            }
        }

        stateful_functions
            .iter()
            .any(|name| Self::print_expression_contains_named_call(expression, name))
    }

    fn print_expression_contains_probe_reference(expression: &str) -> bool {
        let mut index = 0usize;
        while index < expression.len() {
            if Self::print_probe_call_open_index(expression, index).is_some()
                || Self::print_device_parameter_token_at(expression, index).is_some()
            {
                return true;
            }
            let ch = expression[index..]
                .chars()
                .next()
                .expect("valid char boundary");
            index += ch.len_utf8();
        }
        false
    }

    fn print_expression_contains_voltage_accessor_call(expression: &str) -> bool {
        let mut index = 0usize;
        while index < expression.len() {
            if let Some(open_index) = Self::print_probe_call_open_index(expression, index) {
                let call = &expression[index..open_index];
                if XyceVoltageAccessor::from_function_name(call)
                    .is_some_and(|accessor| accessor != XyceVoltageAccessor::Value)
                {
                    return true;
                }
            }
            let ch = expression[index..]
                .chars()
                .next()
                .expect("valid char boundary");
            index += ch.len_utf8();
        }
        false
    }

    fn braced_expression_is_atomic_real_probe(
        normalized_expression: &str,
        netlist: &Netlist,
    ) -> bool {
        Self::parse_device_parameter_probe(normalized_expression).is_some()
            || Self::bare_device_parameter_probe_is_atomic_real_probe(
                netlist,
                normalized_expression,
            )
            || Self::parse_device_operating_point_probe(normalized_expression)
                .is_some_and(|_| Self::probe_call_covers_entire_expression(normalized_expression))
            || Self::parse_lead_current_probe(normalized_expression)
                .is_some_and(|_| Self::probe_call_covers_entire_expression(normalized_expression))
            || Self::parse_tran_voltage_probe(normalized_expression)
                .is_some_and(|_| Self::probe_call_covers_entire_expression(normalized_expression))
            || Self::parse_current_probe(normalized_expression)
                .is_some_and(|_| Self::probe_call_covers_entire_expression(normalized_expression))
            || Self::parse_power_probe(normalized_expression)
                .is_some_and(|_| Self::probe_call_covers_entire_expression(normalized_expression))
    }

    fn bare_device_parameter_probe_is_atomic_real_probe(netlist: &Netlist, probe: &str) -> bool {
        let Some(probe_name) = Self::parse_bare_device_parameter_probe(probe) else {
            return false;
        };
        netlist.params.get_complex(&probe_name).is_none()
            && Self::bare_device_parameter_probe_is_supported(netlist, &probe_name)
    }

    fn braced_expression_is_atomic_ac_probe(
        normalized_expression: &str,
        netlist: &Netlist,
    ) -> bool {
        Self::parse_device_parameter_probe(normalized_expression).is_some()
            || Self::bare_device_parameter_probe_is_atomic_ac_probe(netlist, normalized_expression)
            || Self::parse_device_operating_point_probe(normalized_expression)
                .is_some_and(|_| Self::probe_call_covers_entire_expression(normalized_expression))
            || Self::parse_lead_current_probe(normalized_expression)
                .is_some_and(|_| Self::probe_call_covers_entire_expression(normalized_expression))
            || Self::parse_ac_voltage_probe(normalized_expression)
                .is_some_and(|_| Self::probe_call_covers_entire_expression(normalized_expression))
            || Self::parse_ac_current_probe(normalized_expression)
                .is_some_and(|_| Self::probe_call_covers_entire_expression(normalized_expression))
            || Self::parse_power_probe(normalized_expression)
                .is_some_and(|_| Self::probe_call_covers_entire_expression(normalized_expression))
    }

    fn bare_device_parameter_probe_is_atomic_ac_probe(netlist: &Netlist, probe: &str) -> bool {
        let Some(probe_name) = Self::parse_bare_device_parameter_probe(probe) else {
            return false;
        };
        netlist.params.get_complex(&probe_name).is_none()
            && Self::bare_device_parameter_probe_is_supported(netlist, &probe_name)
    }

    fn probe_call_covers_entire_expression(expression: &str) -> bool {
        let Some(open_index) = expression.find('(') else {
            return false;
        };
        if open_index == 0 || !expression.is_char_boundary(open_index) {
            return false;
        }
        Self::matching_parenthesis_index(expression, open_index)
            .is_ok_and(|close_index| close_index + 1 == expression.len())
    }

    fn print_probe_call_open_index(expression: &str, index: usize) -> Option<usize> {
        if index >= expression.len() || !expression.is_char_boundary(index) {
            return None;
        }
        let previous = expression[..index].chars().next_back();
        if previous.is_some_and(Self::print_identifier_char) {
            return None;
        }

        let rest = &expression[index..];
        for prefix in [
            "dno", "dni", "idb", "ir", "ii", "im", "ip", "id", "ig", "is", "ib", "ic", "ie", "vdb",
            "vr", "vi", "vm", "vp", "v", "i", "p", "w", "n",
        ] {
            let next_index = index + prefix.len();
            if rest.len() <= prefix.len()
                || !expression.is_char_boundary(next_index)
                || !rest[..prefix.len()].eq_ignore_ascii_case(prefix)
                || !expression[next_index..].starts_with('(')
            {
                continue;
            }
            return Some(next_index);
        }
        None
    }

    fn print_device_parameter_token_at(expression: &str, index: usize) -> Option<(usize, &str)> {
        if index >= expression.len() || !expression.is_char_boundary(index) {
            return None;
        }
        let previous = expression[..index].chars().next_back();
        if previous.is_some_and(Self::print_device_parameter_token_char) {
            return None;
        }

        let first = expression[index..].chars().next()?;
        if !(first.is_ascii_alphabetic() || first == '_') {
            return None;
        }

        let mut end_index = index;
        let mut has_colon = false;
        while end_index < expression.len() {
            let ch = expression[end_index..].chars().next()?;
            if !Self::print_device_parameter_token_char(ch) {
                break;
            }
            has_colon |= ch == ':';
            end_index += ch.len_utf8();
        }
        if !has_colon {
            return None;
        }

        let token = &expression[index..end_index];
        Self::parse_device_parameter_probe(token).map(|_| (end_index, token))
    }

    fn print_device_parameter_token_char(ch: char) -> bool {
        ch.is_ascii_alphanumeric() || matches!(ch, '_' | '.' | '$' | ':')
    }

    fn print_identifier_char(ch: char) -> bool {
        ch.is_ascii_alphanumeric() || matches!(ch, '_' | '.' | '$')
    }

    fn matching_parenthesis_index(expression: &str, open_index: usize) -> Result<usize, String> {
        if !expression[open_index..].starts_with('(') {
            return Err(format!(
                "internal error: expected '(' in .PRINT expression '{expression}'"
            ));
        }

        let mut depth = 0usize;
        for (relative_index, ch) in expression[open_index..].char_indices() {
            let absolute_index = open_index + relative_index;
            match ch {
                '(' => depth += 1,
                ')' => {
                    depth = depth.saturating_sub(1);
                    if depth == 0 {
                        return Ok(absolute_index);
                    }
                }
                _ => {}
            }
        }

        Err(format!(
            "unterminated probe call in .PRINT expression '{{{expression}}}'"
        ))
    }

    fn evaluate_device_parameter_probe(
        netlist: &Netlist,
        dc: &XyceDcSweep,
        sweep_point: XyceDcSweepPoint,
        result: &crate::SimulationResult,
        op_report: &crate::circuit::DeviceOpReport,
        element_name: &str,
        parameter: &str,
    ) -> Result<f64, String> {
        match parameter {
            "dcv0" => {
                if element_name.eq_ignore_ascii_case(&dc.source) {
                    return Ok(sweep_point.primary);
                }
                if let Some(sweep2) = &dc.sweep2 {
                    if element_name.eq_ignore_ascii_case(&sweep2.source) {
                        return sweep_point.secondary.ok_or_else(|| {
                            format!(
                                "secondary sweep value for '{}' is unavailable",
                                element_name
                            )
                        });
                    }
                }
                Self::independent_source_dc_value(netlist, element_name).ok_or_else(|| {
                    format!(
                        "source parameter probe '{}:DCV0' targets an unknown independent source",
                        element_name
                    )
                })
            }
            "r" => Self::evaluate_resistor_parameter_r_value(
                netlist,
                dc,
                sweep_point,
                result,
                op_report,
                element_name,
            ),
            "c" => {
                Self::evaluate_capacitor_parameter_c_value(netlist, dc, sweep_point, element_name)
            }
            "l" => {
                if Self::find_inductor_element(netlist, element_name).is_some() {
                    return Self::evaluate_inductor_parameter_l_value(
                        netlist,
                        dc,
                        sweep_point,
                        element_name,
                    );
                }
                if Self::resistor_instance_parameter_probe_is_supported(
                    netlist,
                    element_name,
                    parameter,
                ) {
                    return Self::evaluate_resistor_instance_parameter_probe(
                        netlist,
                        element_name,
                        parameter,
                    );
                }
                Self::evaluate_model_parameter_probe(
                    netlist,
                    dc,
                    sweep_point,
                    element_name,
                    parameter,
                )
                .unwrap_or_else(|| {
                    Err(format!(
                        "device parameter probe '{}:{}' is not supported",
                        element_name, parameter
                    ))
                })
            }
            "temp" => Self::resistor_temperature_value(netlist, element_name).ok_or_else(|| {
                format!(
                    "resistor parameter probe '{}:TEMP' targets an unknown resistor",
                    element_name
                )
            }),
            _ => {
                if Self::resistor_instance_parameter_probe_is_supported(
                    netlist,
                    element_name,
                    parameter,
                ) {
                    return Self::evaluate_resistor_instance_parameter_probe(
                        netlist,
                        element_name,
                        parameter,
                    );
                }
                Self::evaluate_model_parameter_probe(
                    netlist,
                    dc,
                    sweep_point,
                    element_name,
                    parameter,
                )
                .unwrap_or_else(|| {
                    Err(format!(
                        "device parameter probe '{}:{}' is not supported",
                        element_name, parameter
                    ))
                })
            }
        }
    }

    fn model_parameter_probe_is_supported(
        netlist: &Netlist,
        model_name: &str,
        parameter: &str,
    ) -> bool {
        Self::models_have_parameter_probe(&netlist.models, model_name, parameter)
            || crate::netlist::flatten_netlist_with_models(netlist).is_ok_and(|flattened| {
                Self::models_have_parameter_probe(&flattened.scoped_models, model_name, parameter)
            })
    }

    fn models_have_parameter_probe(
        models: &[crate::netlist::ModelDef],
        model_name: &str,
        parameter: &str,
    ) -> bool {
        Self::find_model(models, model_name).is_some_and(|model| {
            model
                .params
                .iter()
                .any(|(name, _)| name.eq_ignore_ascii_case(parameter))
                || model
                    .expr_params
                    .iter()
                    .any(|(name, _)| name.eq_ignore_ascii_case(parameter))
        })
    }

    fn evaluate_model_parameter_probe(
        netlist: &Netlist,
        dc: &XyceDcSweep,
        sweep_point: XyceDcSweepPoint,
        model_name: &str,
        parameter: &str,
    ) -> Option<Result<Value, String>> {
        Self::model_parameter_probe_value(
            &netlist.models,
            netlist,
            dc,
            sweep_point,
            model_name,
            parameter,
        )
        .or_else(|| {
            let flattened = crate::netlist::flatten_netlist_with_models(netlist).ok()?;
            Self::model_parameter_probe_value(
                &flattened.scoped_models,
                netlist,
                dc,
                sweep_point,
                model_name,
                parameter,
            )
        })
    }

    fn model_parameter_probe_value(
        models: &[crate::netlist::ModelDef],
        netlist: &Netlist,
        dc: &XyceDcSweep,
        sweep_point: XyceDcSweepPoint,
        model_name: &str,
        parameter: &str,
    ) -> Option<Result<Value, String>> {
        let model = Self::find_model(models, model_name)?;
        if let Some((_, value)) = model
            .params
            .iter()
            .rev()
            .find(|(name, _)| name.eq_ignore_ascii_case(parameter))
        {
            return Some(Ok(*value));
        }

        model
            .expr_params
            .iter()
            .rev()
            .find(|(name, _)| name.eq_ignore_ascii_case(parameter))
            .map(|(_, expression)| {
                let context = Self::print_eval_context(netlist, Some(dc), Some(sweep_point));
                crate::netlist::expr::eval_expression(expression, &context).map_err(|err| {
                    format!(
                        "failed to evaluate model parameter probe '{}:{}': {err}",
                        model_name, parameter
                    )
                })
            })
    }

    fn bare_device_parameter_probe_is_supported(netlist: &Netlist, probe: &str) -> bool {
        Self::find_bare_device_parameter_element(netlist, probe).is_some()
    }

    fn evaluate_bare_device_parameter_probe(
        netlist: &Netlist,
        dc: &XyceDcSweep,
        sweep_point: XyceDcSweepPoint,
        result: &crate::SimulationResult,
        op_report: &crate::circuit::DeviceOpReport,
        probe: &str,
    ) -> Option<Result<f64, String>> {
        let probe_name = Self::parse_bare_device_parameter_probe(probe)?;
        let element = Self::find_bare_device_parameter_element(netlist, &probe_name)?;
        Some(match &element.kind {
            ElementKind::VoltageSource(spec) | ElementKind::CurrentSource(spec) => Ok(
                Self::source_dc_parameter_value(dc, sweep_point, &element.name, spec),
            ),
            ElementKind::Resistor { .. } => Self::evaluate_resistor_parameter_r_value(
                netlist,
                dc,
                sweep_point,
                result,
                op_report,
                &probe_name,
            ),
            ElementKind::Capacitor {
                value,
                value_expr,
                instance_params,
                ..
            } => Self::evaluate_static_passive_parameter_value(
                netlist,
                dc,
                sweep_point,
                "capacitor",
                &probe_name,
                "C",
                *value,
                value_expr.as_deref(),
                instance_params,
            ),
            ElementKind::Inductor {
                value,
                value_expr,
                instance_params,
                ..
            } => Self::evaluate_static_passive_parameter_value(
                netlist,
                dc,
                sweep_point,
                "inductor",
                &probe_name,
                "L",
                *value,
                value_expr.as_deref(),
                instance_params,
            ),
            _ => Err(format!(
                "bare device parameter probe '{}' targets an unsupported element kind",
                probe_name
            )),
        })
    }

    fn source_dc_parameter_value(
        dc: &XyceDcSweep,
        sweep_point: XyceDcSweepPoint,
        element_name: &str,
        spec: &crate::netlist::SourceSpec,
    ) -> Value {
        if Self::device_instance_names_match(element_name, &dc.source) {
            return sweep_point.primary;
        }
        if let Some(sweep2) = &dc.sweep2
            && Self::device_instance_names_match(element_name, &sweep2.source)
            && let Some(value) = sweep_point.secondary
        {
            return value;
        }
        extract_dc_value(spec)
    }

    fn evaluate_static_passive_parameter_value(
        netlist: &Netlist,
        dc: &XyceDcSweep,
        sweep_point: XyceDcSweepPoint,
        device_kind: &str,
        element_name: &str,
        parameter_name: &str,
        value: Value,
        value_expr: Option<&str>,
        instance_params: &[(String, Value)],
    ) -> Result<Value, String> {
        if let Some(instance_value) =
            Self::instance_param(instance_params, &[parameter_name, "VALUE"])
        {
            return Ok(instance_value);
        }
        if value.is_finite() {
            return Ok(value);
        }
        if let Some(expression) = value_expr {
            let context = Self::print_eval_context(netlist, Some(dc), Some(sweep_point));
            return crate::netlist::expr::eval_expression(expression, &context).map_err(|err| {
                format!(
                    "failed to evaluate {device_kind} parameter probe '{element_name}:{parameter_name}': {err}"
                )
            });
        }
        Err(format!(
            "{device_kind} parameter probe '{element_name}:{parameter_name}' could not resolve a value"
        ))
    }

    fn evaluate_capacitor_parameter_c_value(
        netlist: &Netlist,
        dc: &XyceDcSweep,
        sweep_point: XyceDcSweepPoint,
        name: &str,
    ) -> Result<Value, String> {
        let element = Self::find_capacitor_element(netlist, name).ok_or_else(|| {
            format!("capacitor parameter probe '{name}:C' targets an unknown capacitor")
        })?;
        let ElementKind::Capacitor {
            value,
            value_expr,
            model,
            instance_params,
            ..
        } = &element.kind
        else {
            return Err(format!(
                "capacitor parameter probe '{name}:C' targets a non-capacitor element"
            ));
        };
        if (model.is_some()
            || Self::capacitor_instance_params_affect_effective_value(instance_params))
            && let Some(capacitance) = Self::effective_capacitor_value(netlist, name)
        {
            return Ok(capacitance);
        }
        Self::evaluate_static_passive_parameter_value(
            netlist,
            dc,
            sweep_point,
            "capacitor",
            name,
            "C",
            *value,
            value_expr.as_deref(),
            instance_params,
        )
    }

    fn evaluate_inductor_parameter_l_value(
        netlist: &Netlist,
        dc: &XyceDcSweep,
        sweep_point: XyceDcSweepPoint,
        name: &str,
    ) -> Result<Value, String> {
        let element = Self::find_inductor_element(netlist, name).ok_or_else(|| {
            format!("inductor parameter probe '{name}:L' targets an unknown inductor")
        })?;
        let ElementKind::Inductor {
            value,
            value_expr,
            model,
            instance_params,
            ..
        } = &element.kind
        else {
            return Err(format!(
                "inductor parameter probe '{name}:L' targets a non-inductor element"
            ));
        };
        if (model.is_some()
            || Self::inductor_instance_params_affect_effective_value(instance_params))
            && let Some(inductance) = Self::effective_inductor_value(netlist, name)
        {
            return Ok(inductance);
        }
        Self::evaluate_static_passive_parameter_value(
            netlist,
            dc,
            sweep_point,
            "inductor",
            name,
            "L",
            *value,
            value_expr.as_deref(),
            instance_params,
        )
    }

    fn evaluate_transient_device_parameter_probe(
        netlist: &Netlist,
        result: &TransientResult,
        time: Value,
        element_name: &str,
        parameter: &str,
    ) -> Result<f64, String> {
        match parameter {
            "r" => Self::evaluate_transient_resistor_parameter_r_value(
                netlist,
                result,
                time,
                element_name,
            ),
            "c" => Self::evaluate_transient_capacitor_parameter_c_value(
                netlist,
                result,
                time,
                element_name,
            ),
            "l" => Self::evaluate_transient_inductor_parameter_l_value(
                netlist,
                result,
                time,
                element_name,
            ),
            "temp" => Self::resistor_temperature_value(netlist, element_name).ok_or_else(|| {
                format!(
                    "resistor parameter probe '{}:TEMP' targets an unknown resistor",
                    element_name
                )
            }),
            _ => Err(format!(
                "device parameter probe '{}:{}' is not supported in transient output",
                element_name, parameter
            )),
        }
    }

    fn evaluate_transient_static_passive_parameter_value(
        netlist: &Netlist,
        result: &TransientResult,
        time: Value,
        device_kind: &str,
        element_name: &str,
        parameter_name: &str,
        value: Value,
        value_expr: Option<&str>,
        instance_params: &[(String, Value)],
    ) -> Result<Value, String> {
        if let Some(instance_value) =
            Self::instance_param(instance_params, &[parameter_name, "VALUE"])
        {
            return Ok(instance_value);
        }
        if value.is_finite() {
            return Ok(value);
        }
        if let Some(expression) = value_expr {
            let context = Self::print_tran_eval_context(netlist, time);
            let mut call_value = |call: &str| {
                let normalized = Self::normalize_probe(call);
                Self::evaluate_atomic_tran_probe(&normalized, netlist, result, time)
            };
            return Self::evaluate_print_expression_with_probe_calls(
                expression,
                context,
                &mut call_value,
            )
            .map_err(|err| {
                format!(
                    "failed to evaluate transient {device_kind} parameter probe '{element_name}:{parameter_name}': {err}"
                )
            });
        }
        Err(format!(
            "{device_kind} parameter probe '{element_name}:{parameter_name}' could not resolve a value"
        ))
    }

    fn evaluate_transient_resistor_parameter_r_value(
        netlist: &Netlist,
        result: &TransientResult,
        time: Value,
        name: &str,
    ) -> Result<Value, String> {
        let element = Self::find_resistor_element(netlist, name).ok_or_else(|| {
            format!("resistor parameter probe '{name}:R' targets an unknown resistor")
        })?;
        let ElementKind::Resistor {
            value,
            value_expr,
            model,
            instance_params,
            ..
        } = &element.kind
        else {
            return Err(format!(
                "resistor parameter probe '{name}:R' targets a non-resistor element"
            ));
        };

        if Self::resistor_uses_xyce_default_marker(instance_params)
            && let Some(resistance) = Self::effective_resistor_value(netlist, name)
        {
            return Ok(resistance);
        }
        let value = Self::evaluate_transient_static_passive_parameter_value(
            netlist,
            result,
            time,
            "resistor",
            name,
            "R",
            *value,
            value_expr.as_deref(),
            instance_params,
        );
        if value.is_ok() {
            return value;
        }
        if model.is_some()
            && let Some(resistance) = Self::resistor_parameter_r_value(netlist, name)
        {
            return Ok(resistance);
        }
        value
    }

    fn evaluate_transient_capacitor_parameter_c_value(
        netlist: &Netlist,
        result: &TransientResult,
        time: Value,
        name: &str,
    ) -> Result<Value, String> {
        let element = Self::find_capacitor_element(netlist, name).ok_or_else(|| {
            format!("capacitor parameter probe '{name}:C' targets an unknown capacitor")
        })?;
        let ElementKind::Capacitor {
            value,
            value_expr,
            model,
            instance_params,
            ..
        } = &element.kind
        else {
            return Err(format!(
                "capacitor parameter probe '{name}:C' targets a non-capacitor element"
            ));
        };
        if (model.is_some()
            || Self::capacitor_instance_params_affect_effective_value(instance_params))
            && let Some(capacitance) = Self::effective_capacitor_value(netlist, name)
        {
            return Ok(capacitance);
        }
        Self::evaluate_transient_static_passive_parameter_value(
            netlist,
            result,
            time,
            "capacitor",
            name,
            "C",
            *value,
            value_expr.as_deref(),
            instance_params,
        )
    }

    fn evaluate_transient_inductor_parameter_l_value(
        netlist: &Netlist,
        result: &TransientResult,
        time: Value,
        name: &str,
    ) -> Result<Value, String> {
        let element = Self::find_inductor_element(netlist, name).ok_or_else(|| {
            format!("inductor parameter probe '{name}:L' targets an unknown inductor")
        })?;
        let ElementKind::Inductor {
            value,
            value_expr,
            model,
            instance_params,
            ..
        } = &element.kind
        else {
            return Err(format!(
                "inductor parameter probe '{name}:L' targets a non-inductor element"
            ));
        };
        if (model.is_some()
            || Self::inductor_instance_params_affect_effective_value(instance_params))
            && let Some(inductance) = Self::effective_inductor_value(netlist, name)
        {
            return Ok(inductance);
        }
        Self::evaluate_transient_static_passive_parameter_value(
            netlist,
            result,
            time,
            "inductor",
            name,
            "L",
            *value,
            value_expr.as_deref(),
            instance_params,
        )
    }

    fn evaluate_device_operating_point_probe(
        op_report: &crate::circuit::DeviceOpReport,
        element_name: &str,
        parameter: &str,
    ) -> Result<f64, String> {
        let canonical_parameter =
            Self::canonical_device_op_parameter(parameter).ok_or_else(|| {
                format!(
                    "device operating-point probe 'N({element_name}:{parameter})' targets an unsupported operating-point parameter"
                )
            })?;

        for entry in &op_report.entries {
            if !Self::device_instance_names_match(&entry.name, element_name) {
                continue;
            }
            if let Some(value) = Self::xyce_device_operating_point_value(entry, canonical_parameter)
            {
                return Ok(value);
            }
            return Err(format!(
                "device operating-point probe 'N({element_name}:{parameter})' targets parameter '{}' that is not reported for {} '{}'",
                canonical_parameter, entry.device_kind, entry.name
            ));
        }

        Err(format!(
            "device operating-point probe 'N({element_name}:{parameter})' targets a device with no operating-point report"
        ))
    }

    fn evaluate_lead_current_probe(
        op_report: &crate::circuit::DeviceOpReport,
        probe: &XyceLeadCurrentProbe,
    ) -> Result<f64, String> {
        let parameter = probe.terminal.op_parameter().ok_or_else(|| {
            format!(
                "lead-current probe '{}({})' targets unsupported terminal current",
                probe.terminal.function_name(),
                probe.element_name
            )
        })?;

        for entry in &op_report.entries {
            if !Self::device_instance_names_match(&entry.name, &probe.element_name) {
                continue;
            }
            if let Some(value) = Self::xyce_device_operating_point_value(entry, parameter) {
                return Ok(value);
            }
            return Err(format!(
                "lead-current probe '{}({})' targets parameter '{}' that is not reported for {} '{}'",
                probe.terminal.function_name(),
                probe.element_name,
                parameter,
                entry.device_kind,
                entry.name
            ));
        }

        Err(format!(
            "lead-current probe '{}({})' targets a device with no operating-point report",
            probe.terminal.function_name(),
            probe.element_name
        ))
    }

    fn xyce_device_operating_point_value(
        entry: &crate::circuit::DeviceOpEntry,
        parameter: &str,
    ) -> Option<Value> {
        if matches!(entry.device_kind, "BSIM3" | "BSIM4") {
            return Self::xyce_bsim_device_store_value(entry, parameter);
        }

        Self::device_op_entry_param(entry, parameter)
    }

    fn xyce_bsim_device_store_value(
        entry: &crate::circuit::DeviceOpEntry,
        parameter: &str,
    ) -> Option<Value> {
        let raw = if parameter == "vdsat" && entry.device_kind == "BSIM4" {
            Self::device_op_entry_param(entry, "output_vdsat")
                .or_else(|| Self::device_op_entry_param(entry, parameter))?
        } else {
            Self::device_op_entry_param(entry, parameter)?
        };
        let vds = Self::device_op_entry_param(entry, "vds").unwrap_or(0.0);
        if vds >= 0.0 {
            return Some(raw);
        }

        match parameter {
            // Xyce stores BSIM3/BSIM4 gm after the same inverse-mode sign
            // swap it applies to the MNA stamp.
            "gm" => Some(-raw),
            // Xyce's Vds/Vgs/Vbs store nodes are the mode-frame branch
            // voltages: Vds, Vgs, Vbs in normal mode; -Vds, Vgd, Vbd in
            // inverse mode.
            "vds" => Some(-vds),
            "vgs" => Some(raw - vds),
            "vbs" => Some(raw - vds),
            _ => Some(raw),
        }
    }

    fn device_op_entry_param(
        entry: &crate::circuit::DeviceOpEntry,
        parameter: &str,
    ) -> Option<Value> {
        entry
            .params
            .iter()
            .find(|(name, _)| name.eq_ignore_ascii_case(parameter))
            .map(|(_, value)| *value)
    }

    fn canonical_device_op_parameter(parameter: &str) -> Option<&'static str> {
        match parameter.trim().to_ascii_lowercase().as_str() {
            "id" | "ids" => Some("id"),
            "vgs" => Some("vgs"),
            "vds" => Some("vds"),
            "vbs" => Some("vbs"),
            "vth" | "vto" => Some("vth"),
            "vdsat" | "vdssat" => Some("vdsat"),
            "gm" => Some("gm"),
            "gds" => Some("gds"),
            "gmb" | "gmbs" => Some("gmb"),
            "cd" => Some("cd"),
            _ => None,
        }
    }

    fn netlist_has_device_op_instance(netlist: &Netlist, instance_name: &str) -> bool {
        if netlist.elements.iter().any(|element| {
            Self::netlist_element_exports_device_op(element)
                && Self::device_instance_names_match(&element.name, instance_name)
        }) {
            return true;
        }

        crate::netlist::flatten_netlist_with_models(netlist).is_ok_and(|flattened| {
            flattened.elements.iter().any(|element| {
                Self::netlist_element_exports_device_op(element)
                    && Self::device_instance_names_match(&element.name, instance_name)
            })
        })
    }

    fn netlist_supports_lead_current_probe(
        netlist: &Netlist,
        probe: &XyceLeadCurrentProbe,
    ) -> bool {
        match probe.terminal {
            XyceLeadCurrentTerminal::Drain => true,
            XyceLeadCurrentTerminal::Source => {
                Self::netlist_device_is_native_b3soi_mosfet(netlist, &probe.element_name)
            }
            XyceLeadCurrentTerminal::Gate
            | XyceLeadCurrentTerminal::Bulk
            | XyceLeadCurrentTerminal::Collector
            | XyceLeadCurrentTerminal::Emitter => false,
        }
    }

    fn dc_probe_is_omitted_empty_wildcard(probe: &str, netlist: &Netlist) -> bool {
        Self::parse_lead_current_probe(probe).is_some_and(|probe| {
            Self::lead_current_probe_is_omitted_empty_wildcard(netlist, &probe)
        })
    }

    fn lead_current_probe_is_omitted_empty_wildcard(
        netlist: &Netlist,
        probe: &XyceLeadCurrentProbe,
    ) -> bool {
        probe.element_name == "*"
            && !Self::netlist_has_lead_current_wildcard_match(netlist, probe.terminal)
    }

    fn netlist_has_lead_current_wildcard_match(
        netlist: &Netlist,
        terminal: XyceLeadCurrentTerminal,
    ) -> bool {
        if netlist
            .elements
            .iter()
            .any(|element| Self::element_matches_lead_current_wildcard(element, terminal))
        {
            return true;
        }

        crate::netlist::flatten_netlist_with_models(netlist).is_ok_and(|flattened| {
            flattened
                .elements
                .iter()
                .any(|element| Self::element_matches_lead_current_wildcard(element, terminal))
        })
    }

    fn element_matches_lead_current_wildcard(
        element: &crate::netlist::Element,
        terminal: XyceLeadCurrentTerminal,
    ) -> bool {
        match terminal {
            XyceLeadCurrentTerminal::Drain | XyceLeadCurrentTerminal::Gate => matches!(
                element.kind,
                ElementKind::Mosfet { .. } | ElementKind::Jfet { .. } | ElementKind::Mesfet { .. }
            ),
            XyceLeadCurrentTerminal::Source => matches!(
                element.kind,
                ElementKind::Mosfet { .. }
                    | ElementKind::Jfet { .. }
                    | ElementKind::Mesfet { .. }
                    | ElementKind::Bjt { .. }
            ),
            XyceLeadCurrentTerminal::Bulk => matches!(
                element.kind,
                ElementKind::Mosfet { .. } | ElementKind::Bjt { .. }
            ),
            XyceLeadCurrentTerminal::Collector | XyceLeadCurrentTerminal::Emitter => {
                matches!(element.kind, ElementKind::Bjt { .. })
            }
        }
    }

    fn netlist_device_is_native_b3soi_mosfet(netlist: &Netlist, instance_name: &str) -> bool {
        if Self::elements_device_is_native_b3soi_mosfet(
            &netlist.elements,
            &netlist.models,
            &[],
            instance_name,
        ) {
            return true;
        }

        crate::netlist::flatten_netlist_with_models(netlist).is_ok_and(|flattened| {
            Self::elements_device_is_native_b3soi_mosfet(
                &flattened.elements,
                &netlist.models,
                &flattened.scoped_models,
                instance_name,
            )
        })
    }

    fn netlist_device_is_native_classic_jfet(netlist: &Netlist, instance_name: &str) -> bool {
        if Self::elements_device_is_native_classic_jfet(
            &netlist.elements,
            &netlist.models,
            &[],
            instance_name,
        ) {
            return true;
        }

        crate::netlist::flatten_netlist_with_models(netlist).is_ok_and(|flattened| {
            Self::elements_device_is_native_classic_jfet(
                &flattened.elements,
                &netlist.models,
                &flattened.scoped_models,
                instance_name,
            )
        })
    }

    fn netlist_device_is_native_relational_legacy_diode(
        netlist: &Netlist,
        instance_name: &str,
    ) -> bool {
        netlist.elements.iter().any(|element| {
            if !Self::device_instance_names_match(&element.name, instance_name) {
                return false;
            }
            let ElementKind::Diode {
                model,
                instance_params,
                deferred_params,
            } = &element.kind
            else {
                return false;
            };
            deferred_params.is_empty()
                && instance_params
                    .iter()
                    .all(|(name, value)| Self::native_relational_diode_instance_param(name, *value))
                && Self::find_model(&netlist.models, model)
                    .is_some_and(Self::model_is_native_relational_legacy_diode)
        })
    }

    fn native_relational_diode_instance_param(name: &str, value: Value) -> bool {
        value.is_finite()
            && match name.to_ascii_uppercase().as_str() {
                "AREA" | "M" => value > 0.0,
                "TEMP" => value > -273.15,
                _ => false,
            }
    }

    fn model_is_native_relational_legacy_diode(model: &crate::netlist::ModelDef) -> bool {
        Self::model_is_native_legacy_diode(model)
            && model.expr_params.is_empty()
            && model.string_params.is_empty()
            && model.string_vector_params.is_empty()
            && model.real_vector_params.is_empty()
            && model.real_vector_expr_params.is_empty()
            && model.integer_vector_params.is_empty()
            && model
                .params
                .iter()
                .all(|(name, value)| Self::native_relational_diode_model_param(name, *value))
    }

    fn native_relational_diode_model_param(name: &str, value: Value) -> bool {
        if !value.is_finite() || !Self::xyce_level2_native_diode_param(name) {
            return false;
        }
        match name.to_ascii_uppercase().as_str() {
            "LEVEL" => {
                (value - 0.0).abs() <= 1.0e-9
                    || (value - 1.0).abs() <= 1.0e-9
                    || (value - 2.0).abs() <= 1.0e-9
            }
            "IS" | "JS" | "RS" | "KF" | "IKF" | "IK" | "IKR" | "CJO" | "CJ0" | "CJ" | "TT"
            | "JSW" | "CJSW" | "CJP" | "ISR" => value >= 0.0,
            "N" | "AF" | "IBV" | "NR" | "NS" | "VJ" | "PHP" | "VJSW" | "EG" | "BV" | "VB"
            | "NBV" => value > 0.0,
            "M" | "MJSW" => (0.0..=1.0).contains(&value),
            "FC" | "FCS" => (0.0..1.0).contains(&value),
            "XTI" => true,
            "TNOM" => value > -273.15,
            _ => false,
        }
    }

    fn netlist_device_is_native_relational_mos3(netlist: &Netlist, instance_name: &str) -> bool {
        netlist.elements.iter().any(|element| {
            if !Self::device_instance_names_match(&element.name, instance_name) {
                return false;
            }
            let ElementKind::Mosfet {
                model,
                compact_syntax,
                instance_params,
                deferred_params,
                ..
            } = &element.kind
            else {
                return false;
            };
            if *compact_syntax
                || !deferred_params.is_empty()
                || !instance_params
                    .iter()
                    .all(|(name, value)| Self::native_relational_mos3_instance_param(name, *value))
            {
                return false;
            }
            let Some(model) = Self::find_model(&netlist.models, model) else {
                return false;
            };
            Self::model_is_native_relational_mos3(model)
                && Self::native_relational_mos3_effective_geometry_is_valid(model, instance_params)
        })
    }

    fn native_relational_mos3_instance_param(name: &str, value: Value) -> bool {
        value.is_finite()
            && value > 0.0
            && matches!(name.to_ascii_uppercase().as_str(), "L" | "W" | "M" | "NF")
    }

    fn native_relational_mos3_effective_geometry_is_valid(
        model: &crate::netlist::ModelDef,
        instance_params: &[(String, Value)],
    ) -> bool {
        let Some(length) = Self::numeric_param_value(instance_params, "L")
            .or_else(|| Self::numeric_param_value(&model.params, "L"))
        else {
            return false;
        };
        let Some(width) = Self::numeric_param_value(instance_params, "W")
            .or_else(|| Self::numeric_param_value(&model.params, "W"))
        else {
            return false;
        };
        let lateral_diffusion = Self::numeric_param_value(&model.params, "LD").unwrap_or(0.0);
        let length_adjust = Self::numeric_param_value(&model.params, "XL").unwrap_or(0.0);
        let width_narrow = Self::numeric_param_value(&model.params, "WD").unwrap_or(0.0);
        let width_adjust = Self::numeric_param_value(&model.params, "XW").unwrap_or(0.0);
        let effective_length = length - 2.0 * lateral_diffusion + length_adjust;
        let effective_width = width - 2.0 * width_narrow + width_adjust;
        effective_length.is_finite()
            && effective_length > 0.0
            && effective_width.is_finite()
            && effective_width > 0.0
    }

    fn model_is_native_relational_mos3(model: &crate::netlist::ModelDef) -> bool {
        if !matches!(
            model.model_type.to_ascii_uppercase().as_str(),
            "NMOS" | "PMOS"
        ) || Self::numeric_param_value(&model.params, "LEVEL")
            .is_none_or(|level| !level.is_finite() || (level - 3.0).abs() > 1.0e-9)
        {
            return false;
        }
        model.expr_params.is_empty()
            && model.string_params.is_empty()
            && model.string_vector_params.is_empty()
            && model.real_vector_params.is_empty()
            && model.real_vector_expr_params.is_empty()
            && model.integer_vector_params.is_empty()
            && model
                .params
                .iter()
                .all(|(name, value)| Self::native_relational_mos3_model_param(name, *value))
    }

    fn native_relational_mos3_model_param(name: &str, value: Value) -> bool {
        if !value.is_finite() {
            return false;
        }
        match name.to_ascii_uppercase().as_str() {
            "LEVEL" => (value - 3.0).abs() <= 1.0e-9,
            "VTO" | "VT0" | "ETA" | "XL" | "XW" => true,
            "TPG" => matches!(value, -1.0 | 0.0 | 1.0),
            "KP" | "PHI" | "U0" | "UO" | "TOX" | "NSUB" | "L" | "W" | "PB" | "KAPPA" | "AF" => {
                value > 0.0
            }
            "GAMMA" | "LAMBDA" | "NSS" | "IS" | "JS" | "LD" | "RD" | "RS" | "CBD" | "CBS"
            | "CJ" | "CJ0" | "CJSW" | "CGSO" | "CGDO" | "CGBO" | "DELTA" | "THETA" | "NFS"
            | "VMAX" | "XJ" | "WD" | "KF" => value >= 0.0,
            // The classic MOS builder currently has two RSH lowering paths;
            // zero is semantically inert and therefore the only qualified
            // relational value until nonzero topology is single-stamped.
            "RSH" => value == 0.0,
            "MJ" | "MJSW" => (0.0..=1.0).contains(&value),
            "FC" => (0.0..1.0).contains(&value),
            "TNOM" => value > -273.15,
            _ => false,
        }
    }

    fn native_transient_uses_standard_startup(netlist: &Netlist) -> bool {
        !Self::tran_uses_uic(netlist)
            && !netlist
                .analyses
                .iter()
                .any(|analysis| matches!(analysis, AnalysisCommand::Temp { .. }))
            && netlist.initial_conditions.is_empty()
            && netlist.node_sets.is_empty()
            && netlist
                .options
                .temp
                .is_none_or(|temp| temp.is_finite() && (temp - 27.0).abs() <= 1.0e-9)
            && netlist
                .options
                .tnom
                .is_none_or(|tnom| tnom.is_finite() && (tnom - 27.0).abs() <= 1.0e-9)
            && netlist.elements.iter().all(|element| match &element.kind {
                ElementKind::Capacitor {
                    initial_voltage, ..
                } => initial_voltage.is_none(),
                ElementKind::Inductor {
                    initial_current, ..
                } => initial_current.is_none(),
                ElementKind::VSwitch { initial_state, .. }
                | ElementKind::ISwitch { initial_state, .. }
                | ElementKind::GenericSwitch { initial_state, .. } => initial_state.is_none(),
                _ => true,
            })
    }

    fn find_unique_model_in<'a>(
        models: impl IntoIterator<Item = &'a crate::netlist::ModelDef>,
        name: &str,
    ) -> Option<&'a crate::netlist::ModelDef> {
        let mut matches = models
            .into_iter()
            .filter(|model| model.name.eq_ignore_ascii_case(name));
        let model = matches.next()?;
        matches.next().is_none().then_some(model)
    }

    fn netlist_element_is_native_absolute_transient_level9_bsim3(
        netlist: &Netlist,
        element: &crate::netlist::Element,
    ) -> bool {
        let ElementKind::Mosfet {
            model,
            compact_syntax,
            instance_params,
            deferred_params,
            ..
        } = &element.kind
        else {
            return false;
        };
        element.nodes.len() == 4
            && !compact_syntax
            && deferred_params.is_empty()
            && Self::native_absolute_transient_level9_bsim3_instance_params(instance_params)
            && Self::find_unique_model_in(&netlist.models, model)
                .is_some_and(Self::model_is_native_absolute_transient_level9_bsim3)
    }

    fn netlist_element_is_native_level9_xyce_verify_supported(
        element: &crate::netlist::Element,
    ) -> bool {
        match &element.kind {
            ElementKind::Mosfet { .. } => true,
            ElementKind::VoltageSource(spec) | ElementKind::CurrentSource(spec) => {
                element.nodes.len() == 2 && Self::source_spec_is_finite_dc_or_pulse(spec)
            }
            ElementKind::Resistor {
                value,
                value_expr,
                model,
                instance_params,
                deferred_params,
            } => {
                element.nodes.len() == 2
                    && value.is_finite()
                    && *value > 0.0
                    && value_expr.is_none()
                    && model.is_none()
                    && instance_params.is_empty()
                    && deferred_params.is_empty()
            }
            ElementKind::Capacitor {
                value,
                value_expr,
                initial_voltage,
                model,
                instance_params,
                deferred_params,
            } => {
                element.nodes.len() == 2
                    && value.is_finite()
                    && *value > 0.0
                    && value_expr.is_none()
                    && initial_voltage.is_none()
                    && model.is_none()
                    && instance_params.is_empty()
                    && deferred_params.is_empty()
            }
            ElementKind::Inductor {
                value,
                value_expr,
                initial_current,
                model,
                instance_params,
                deferred_params,
            } => {
                element.nodes.len() == 2
                    && value.is_finite()
                    && *value > 0.0
                    && value_expr.is_none()
                    && initial_current.is_none()
                    && model.is_none()
                    && instance_params.is_empty()
                    && deferred_params.is_empty()
            }
            _ => false,
        }
    }

    fn native_absolute_transient_level9_bsim3_instance_params(params: &[(String, Value)]) -> bool {
        if params.len() != 2
            || !params.iter().all(|(name, value)| {
                value.is_finite()
                    && *value > 0.0
                    && matches!(name.to_ascii_uppercase().as_str(), "W" | "L")
            })
        {
            return false;
        }
        params
            .iter()
            .filter(|(name, _)| name.eq_ignore_ascii_case("W"))
            .count()
            == 1
            && params
                .iter()
                .filter(|(name, _)| name.eq_ignore_ascii_case("L"))
                .count()
                == 1
    }

    fn model_is_native_absolute_transient_level9_bsim3(model: &crate::netlist::ModelDef) -> bool {
        matches!(
            model.model_type.to_ascii_uppercase().as_str(),
            "NMOS" | "PMOS"
        ) && model.expr_params.is_empty()
            && model.string_params.is_empty()
            && model.string_vector_params.is_empty()
            && model.real_vector_params.is_empty()
            && model.real_vector_expr_params.is_empty()
            && model.integer_vector_params.is_empty()
            && matches!(model.params.as_slice(), [(name, level)]
                if name.eq_ignore_ascii_case("LEVEL")
                    && level.is_finite()
                    && level.to_bits() == 9.0f64.to_bits())
    }

    fn netlist_element_is_native_scoped_model_relational_bjt(
        netlist: &Netlist,
        element: &crate::netlist::Element,
    ) -> bool {
        let ElementKind::Bjt {
            model,
            instance_params,
            deferred_params,
            ..
        } = &element.kind
        else {
            return false;
        };
        element.nodes.len() == 3
            && instance_params.is_empty()
            && deferred_params.is_empty()
            && Self::find_unique_model_in(&netlist.models, model)
                .is_some_and(Self::model_is_native_scoped_model_relational_bjt)
    }

    fn model_is_native_scoped_model_relational_bjt(model: &crate::netlist::ModelDef) -> bool {
        if !model.model_type.eq_ignore_ascii_case("NPN")
            || !model.expr_params.is_empty()
            || !model.string_params.is_empty()
            || !model.string_vector_params.is_empty()
            || !model.real_vector_params.is_empty()
            || !model.real_vector_expr_params.is_empty()
            || !model.integer_vector_params.is_empty()
            || model.params.len() != 2
        {
            return false;
        }
        let bf_count = model
            .params
            .iter()
            .filter(|(name, _)| name.eq_ignore_ascii_case("BF"))
            .count();
        let is_count = model
            .params
            .iter()
            .filter(|(name, _)| name.eq_ignore_ascii_case("IS"))
            .count();
        bf_count == 1
            && is_count == 1
            && model.params.iter().all(|(name, value)| {
                value.is_finite()
                    && *value > 0.0
                    && matches!(name.to_ascii_uppercase().as_str(), "BF" | "IS")
            })
    }

    fn netlist_element_is_native_exact_is_diode(
        netlist: &Netlist,
        element: &crate::netlist::Element,
    ) -> bool {
        let ElementKind::Diode {
            model,
            instance_params,
            deferred_params,
        } = &element.kind
        else {
            return false;
        };
        element.nodes.len() == 2
            && instance_params.is_empty()
            && deferred_params.is_empty()
            && Self::find_unique_model_in(&netlist.models, model)
                .is_some_and(Self::model_is_native_exact_is_diode)
    }

    fn netlist_element_is_native_absolute_transient_exact_is_diode(
        netlist: &Netlist,
        element: &crate::netlist::Element,
    ) -> bool {
        netlist.options.gmin.is_none()
            && Self::netlist_element_is_native_exact_is_diode(netlist, element)
    }

    fn netlist_is_native_exact_is_diode_xyce_verify_envelope(netlist: &Netlist) -> bool {
        let diodes = netlist
            .elements
            .iter()
            .filter(|element| matches!(element.kind, ElementKind::Diode { .. }))
            .collect::<Vec<_>>();
        if diodes.is_empty()
            || diodes.iter().any(|element| {
                !Self::netlist_element_is_native_absolute_transient_exact_is_diode(netlist, element)
            })
            || netlist.elements.iter().any(|element| {
                matches!(
                    element.kind,
                    ElementKind::Bjt { .. } | ElementKind::Mosfet { .. } | ElementKind::Jfet { .. }
                )
            })
        {
            return false;
        }

        let referenced_models = diodes
            .iter()
            .filter_map(|element| match &element.kind {
                ElementKind::Diode { model, .. } => Some(model.to_ascii_lowercase()),
                _ => None,
            })
            .collect::<BTreeSet<_>>();
        netlist.models.len() == referenced_models.len()
            && netlist.models.iter().all(|model| {
                referenced_models.contains(&model.name.to_ascii_lowercase())
                    && Self::model_is_native_exact_is_diode(model)
            })
    }

    fn model_is_native_exact_is_diode(model: &crate::netlist::ModelDef) -> bool {
        matches!(
            model.model_type.to_ascii_uppercase().as_str(),
            "D" | "DIODE"
        ) && model.expr_params.is_empty()
            && model.string_params.is_empty()
            && model.string_vector_params.is_empty()
            && model.real_vector_params.is_empty()
            && model.real_vector_expr_params.is_empty()
            && model.integer_vector_params.is_empty()
            && model.params.len() == 1
            && model.params[0].0.eq_ignore_ascii_case("IS")
            && model.params[0].1.is_finite()
            && model.params[0].1 > 0.0
    }

    fn netlist_element_is_native_transient_level1_npn(
        netlist: &Netlist,
        element: &crate::netlist::Element,
    ) -> bool {
        let ElementKind::Bjt {
            model,
            instance_params,
            deferred_params,
            ..
        } = &element.kind
        else {
            return false;
        };
        let topology_is_qualified = match element.nodes.as_slice() {
            [_, _, _] => true,
            [_, _, _, substrate] => Self::node_name_is_ground(substrate),
            _ => false,
        };
        topology_is_qualified
            && instance_params.is_empty()
            && deferred_params.is_empty()
            && Self::find_model(&netlist.models, model)
                .is_some_and(Self::model_is_native_transient_level1_npn)
    }

    fn model_is_native_transient_level1_npn(model: &crate::netlist::ModelDef) -> bool {
        if !model.model_type.eq_ignore_ascii_case("NPN")
            || Self::numeric_param_value(&model.params, "LEVEL")
                .is_some_and(|level| !level.is_finite() || (level - 1.0).abs() > 1.0e-9)
        {
            return false;
        }
        model.expr_params.is_empty()
            && model.string_params.is_empty()
            && model.string_vector_params.is_empty()
            && model.real_vector_params.is_empty()
            && model.real_vector_expr_params.is_empty()
            && model.integer_vector_params.is_empty()
            && model
                .params
                .iter()
                .all(|(name, value)| Self::native_transient_level1_npn_model_param(name, *value))
    }

    fn native_transient_level1_npn_model_param(name: &str, value: Value) -> bool {
        if !value.is_finite() {
            return false;
        }
        match name.to_ascii_uppercase().as_str() {
            "LEVEL" => (value - 1.0).abs() <= 1.0e-9,
            "BF" | "BR" | "IS" | "NE" | "NC" | "VJE" | "VJC" | "VAF" | "EG" => value > 0.0,
            "RB" | "RC" | "RE" | "CJS" | "CJE" | "CJC" | "TF" | "TR" => value >= 0.0,
            "MJE" | "MJC" => (0.0..1.0).contains(&value),
            _ => false,
        }
    }

    fn netlist_device_is_native_legacy_bjt(netlist: &Netlist, instance_name: &str) -> bool {
        if Self::elements_device_is_native_legacy_bjt(
            &netlist.elements,
            &netlist.models,
            &[],
            instance_name,
        ) {
            return true;
        }

        crate::netlist::flatten_netlist_with_models(netlist).is_ok_and(|flattened| {
            Self::elements_device_is_native_legacy_bjt(
                &flattened.elements,
                &netlist.models,
                &flattened.scoped_models,
                instance_name,
            )
        })
    }

    fn elements_device_is_native_legacy_bjt(
        elements: &[crate::netlist::Element],
        models: &[crate::netlist::ModelDef],
        scoped_models: &[crate::netlist::ModelDef],
        instance_name: &str,
    ) -> bool {
        elements.iter().any(|element| {
            if !Self::device_instance_names_match(&element.name, instance_name) {
                return false;
            }
            let ElementKind::Bjt { model, .. } = &element.kind else {
                return false;
            };
            Self::find_model(scoped_models, model)
                .or_else(|| Self::find_model(models, model))
                .is_some_and(Self::model_is_native_legacy_bjt)
        })
    }

    fn model_is_native_legacy_bjt(model: &crate::netlist::ModelDef) -> bool {
        if !matches!(
            model.model_type.to_ascii_uppercase().as_str(),
            "NPN" | "PNP" | "LPNP"
        ) {
            return false;
        }
        Self::numeric_param_value(&model.params, "LEVEL")
            .is_none_or(|level| level.is_finite() && (level - 1.0).abs() <= 1.0e-9)
    }

    fn model_is_native_legacy_diode(model: &crate::netlist::ModelDef) -> bool {
        if !matches!(
            model.model_type.to_ascii_uppercase().as_str(),
            "D" | "DIODE"
        ) {
            return false;
        }
        let Some(level) = Self::numeric_param_value(&model.params, "LEVEL") else {
            return true;
        };
        if !level.is_finite() {
            return false;
        }
        if (level - 0.0).abs() <= 1.0e-9 || (level - 1.0).abs() <= 1.0e-9 {
            return true;
        }
        (level - 2.0).abs() <= 1.0e-9 && Self::model_is_native_xyce_level2_diode_subset(model)
    }

    fn model_is_native_xyce_level2_diode_subset(model: &crate::netlist::ModelDef) -> bool {
        model.expr_params.is_empty()
            && model.string_params.is_empty()
            && model.string_vector_params.is_empty()
            && model.real_vector_params.is_empty()
            && model.real_vector_expr_params.is_empty()
            && model.integer_vector_params.is_empty()
            && model.params.iter().all(|(name, value)| {
                value.is_finite() && Self::xyce_level2_native_diode_param(name)
            })
    }

    fn xyce_level2_native_diode_param(name: &str) -> bool {
        matches!(
            name.to_ascii_uppercase().as_str(),
            "LEVEL"
                | "IS"
                | "JS"
                | "N"
                | "RS"
                | "KF"
                | "AF"
                | "BV"
                | "VB"
                | "IBV"
                | "IKF"
                | "IK"
                | "IKR"
                | "ISR"
                | "NR"
                | "CJO"
                | "CJ0"
                | "CJ"
                | "VJ"
                | "M"
                | "TT"
                | "FC"
                | "JSW"
                | "NS"
                | "CJSW"
                | "CJP"
                | "PHP"
                | "VJSW"
                | "MJSW"
                | "FCS"
                | "NBV"
                | "XTI"
                | "EG"
                | "TNOM"
        )
    }

    fn netlist_device_is_single_native_ac_supported_bulk_mosfet(
        netlist: &Netlist,
        instance_name: &str,
    ) -> bool {
        let mut matched = false;
        let mut count = 0usize;
        for element in &netlist.elements {
            if !matches!(element.kind, ElementKind::Mosfet { .. }) {
                continue;
            }
            if !Self::netlist_element_is_native_ac_supported_bulk_mosfet(netlist, element) {
                return false;
            }
            count += 1;
            matched |= Self::device_instance_names_match(&element.name, instance_name);
        }
        matched && count == 1
    }

    fn netlist_element_is_native_ac_supported_bulk_mosfet(
        netlist: &Netlist,
        element: &crate::netlist::Element,
    ) -> bool {
        let ElementKind::Mosfet {
            model,
            compact_syntax,
            instance_params,
            deferred_params,
            ..
        } = &element.kind
        else {
            return false;
        };
        if element.nodes.len() != 4
            || *compact_syntax
            || !deferred_params.is_empty()
            || !Self::native_ac_classic_mos_instance_params_are_valid(instance_params)
        {
            return false;
        }
        Self::find_unique_model_in(&netlist.models, model)
            .is_some_and(Self::model_is_native_ac_supported_bulk_mosfet)
    }

    fn native_ac_classic_mos_instance_params_are_valid(params: &[(String, Value)]) -> bool {
        let mut names = BTreeSet::new();
        params.iter().all(|(name, value)| {
            value.is_finite()
                && *value > 0.0
                && matches!(name.to_ascii_uppercase().as_str(), "L" | "W")
                && names.insert(name.to_ascii_uppercase())
        }) && names.contains("L")
            && names.contains("W")
    }

    fn model_is_native_ac_supported_bulk_mosfet(model: &crate::netlist::ModelDef) -> bool {
        if !matches!(
            model.model_type.to_ascii_uppercase().as_str(),
            "NMOS" | "PMOS"
        ) || !model.expr_params.is_empty()
            || !model.string_params.is_empty()
            || !model.string_vector_params.is_empty()
            || !model.real_vector_params.is_empty()
            || !model.real_vector_expr_params.is_empty()
            || !model.integer_vector_params.is_empty()
        {
            return false;
        }
        let mut names = BTreeSet::new();
        model.params.iter().all(|(name, value)| {
            value.is_finite()
                && match name.to_ascii_uppercase().as_str() {
                    "LEVEL" => {
                        [1.0, 2.0, 3.0, 6.0].contains(value) && names.insert("LEVEL".to_string())
                    }
                    "TOX" => *value > 0.0 && names.insert("TOX".to_string()),
                    _ => false,
                }
        }) && names.contains("LEVEL")
    }

