    fn find_bare_device_parameter_element(
        netlist: &Netlist,
        probe: &str,
    ) -> Option<crate::netlist::Element> {
        let probe_name = Self::parse_bare_device_parameter_probe(probe)?;
        if let Some(element) = netlist.elements.iter().find(|element| {
            Self::device_instance_names_match(&element.name, &probe_name)
                && Self::element_has_bare_device_parameter(&element.kind)
        }) {
            return Some(element.clone());
        }

        crate::netlist::flatten_netlist_with_models(netlist)
            .ok()?
            .elements
            .into_iter()
            .find(|element| {
                Self::device_instance_names_match(&element.name, &probe_name)
                    && Self::element_has_bare_device_parameter(&element.kind)
            })
    }

    fn element_has_bare_device_parameter(kind: &ElementKind) -> bool {
        matches!(
            kind,
            ElementKind::VoltageSource(_)
                | ElementKind::CurrentSource(_)
                | ElementKind::Resistor { .. }
                | ElementKind::Capacitor { .. }
                | ElementKind::Inductor { .. }
        )
    }

    fn instance_param(params: &[(String, Value)], names: &[&str]) -> Option<Value> {
        names.iter().find_map(|candidate| {
            params
                .iter()
                .find(|(name, _)| name.eq_ignore_ascii_case(candidate))
                .map(|(_, value)| *value)
        })
    }

    fn normalize_temperature_param_to_celsius(value: Value) -> Value {
        value
    }

    fn step_commands(netlist: &Netlist) -> Result<Vec<StepCommand>, String> {
        let step_commands = netlist
            .analyses
            .iter()
            .filter_map(|analysis| match analysis {
                AnalysisCommand::Step(step) => Some(step),
                _ => None,
            })
            .cloned()
            .collect::<Vec<_>>();

        for step in &step_commands {
            match &step.sweep {
                StepSweep::Data { table_name } => {
                    let table = netlist
                        .data_tables
                        .iter()
                        .find(|table| table.name.eq_ignore_ascii_case(table_name))
                        .ok_or_else(|| format!(".STEP DATA table '{table_name}' not found"))?;
                    if table.params.is_empty() {
                        return Err(format!(".STEP DATA table '{}' has no columns", table.name));
                    }
                    if table.rows.is_empty() {
                        return Err(format!(".STEP DATA table '{}' has no rows", table.name));
                    }
                    for (row_index, row) in table.rows.iter().enumerate() {
                        if row.len() != table.params.len() {
                            return Err(format!(
                                ".STEP DATA table '{}' row {} has {} value(s), expected {}",
                                table.name,
                                row_index,
                                row.len(),
                                table.params.len()
                            ));
                        }
                    }
                }
                _ if step.sweep.values().is_empty() => {
                    return Err("deck has invalid .STEP sweep bounds".to_string());
                }
                _ => {}
            }
        }

        Ok(step_commands)
    }

    fn single_tran_analysis(netlist: &Netlist) -> Result<XyceTranAnalysis, String> {
        let analyses = netlist
            .analyses
            .iter()
            .filter_map(|analysis| match analysis {
                AnalysisCommand::Tran {
                    step,
                    stop,
                    start,
                    max_step,
                    uic,
                } => Some(XyceTranAnalysis {
                    step: *step,
                    stop: *stop,
                    start: *start,
                    max_step: *max_step,
                    uic: *uic,
                }),
                _ => None,
            })
            .collect::<Vec<_>>();

        match analyses.len() {
            0 => Err("deck has no .TRAN analysis for static .PRINT TRAN output".to_string()),
            1 => Ok(analyses[0]),
            _ => Err(
                "deck has multiple .TRAN analyses; multi-analysis transient comparison is not implemented yet"
                    .to_string(),
            ),
        }
    }

    fn single_ac_analysis(netlist: &Netlist) -> Result<XyceAcAnalysis, String> {
        let mut analyses = Vec::new();
        for analysis in &netlist.analyses {
            match analysis {
                AnalysisCommand::Ac {
                    variation,
                    points,
                    start_freq,
                    stop_freq,
                } => analyses.push(XyceAcAnalysis {
                    frequencies: ac_sweep_frequencies(*variation, *points, *start_freq, *stop_freq),
                    data_points: None,
                }),
                AnalysisCommand::AcData { table_name } => {
                    let data_points = Self::ac_data_table_points(netlist, table_name)?;
                    analyses.push(XyceAcAnalysis {
                        frequencies: data_points
                            .iter()
                            .map(|point| point.frequency)
                            .collect::<Vec<_>>(),
                        data_points: Some(data_points),
                    });
                }
                _ => {}
            }
        }

        match analyses.len() {
            0 => Err("deck has no .AC analysis for static .PRINT AC output".to_string()),
            1 => Ok(analyses[0].clone()),
            _ => Err(
                "deck has multiple .AC analyses; multi-analysis AC comparison is not implemented yet"
                    .to_string(),
            ),
        }
    }

    fn ac_data_table_points(
        netlist: &Netlist,
        table_name: &str,
    ) -> Result<Vec<XyceAcDataPoint>, String> {
        let table = netlist
            .data_tables
            .iter()
            .find(|table| table.name.eq_ignore_ascii_case(table_name))
            .ok_or_else(|| format!(".AC DATA references unknown .DATA table '{table_name}'"))?;
        if table.params.is_empty() {
            return Err(format!(".AC DATA table '{}' has no columns", table.name));
        }
        if table.rows.is_empty() {
            return Err(format!(".AC DATA table '{}' has no rows", table.name));
        }
        let mut unique_params = BTreeSet::new();
        for param in &table.params {
            if !unique_params.insert(param.to_ascii_uppercase()) {
                return Err(format!(
                    ".AC DATA table '{}' has duplicate column '{}'",
                    table.name, param
                ));
            }
        }
        let freq_column = table
            .params
            .iter()
            .position(|param| param.eq_ignore_ascii_case("FREQ"))
            .ok_or_else(|| format!(".AC DATA table '{}' has no FREQ column", table.name))?;
        let points = table
            .rows
            .iter()
            .enumerate()
            .map(|(row_index, row)| {
                if row.len() != table.params.len() {
                    return Err(format!(
                        ".AC DATA table '{}' row {} has {} value(s), expected {}",
                        table.name,
                        row_index + 1,
                        row.len(),
                        table.params.len()
                    ));
                }
                if let Some((column_index, value)) =
                    row.iter().enumerate().find(|(_, value)| !value.is_finite())
                {
                    return Err(format!(
                        ".AC DATA table '{}' row {} column '{}' must be finite, got {}",
                        table.name,
                        row_index + 1,
                        table.params[column_index],
                        value
                    ));
                }
                let frequency = row.get(freq_column).copied().ok_or_else(|| {
                    format!(
                        ".AC DATA table '{}' row {} does not contain FREQ column {}",
                        table.name,
                        row_index + 1,
                        freq_column + 1
                    )
                })?;
                let overrides = table
                    .params
                    .iter()
                    .cloned()
                    .zip(row.iter().copied())
                    .collect::<Vec<_>>();
                Ok(XyceAcDataPoint {
                    frequency,
                    overrides,
                })
            })
            .collect::<Result<Vec<_>, _>>()?;
        Ok(points)
    }

    fn single_dc_sweep(netlist: &Netlist) -> Result<XyceDcSweep, String> {
        let mut dimensions = Vec::new();
        for analysis in &netlist.analyses {
            let AnalysisCommand::Dc {
                source,
                start,
                stop,
                step,
                mode,
                sweep2,
            } = analysis
            else {
                continue;
            };

            dimensions.push(XyceDcSweepDimension {
                source: source.clone(),
                start: *start,
                stop: *stop,
                step: *step,
                mode: mode.clone(),
            });
            if let Some(sweep2) = sweep2 {
                dimensions.push(XyceDcSweepDimension {
                    source: sweep2.source.clone(),
                    start: sweep2.start,
                    stop: sweep2.stop,
                    step: sweep2.step,
                    mode: sweep2.mode.clone(),
                });
            }
        }

        if dimensions.is_empty() {
            if netlist
                .analyses
                .iter()
                .any(|analysis| matches!(analysis, AnalysisCommand::Op))
            {
                return Self::synthetic_op_dc_sweep(netlist);
            }
            return Err("deck has no .DC or .OP analysis for static .PRINT DC output".to_string());
        }
        if dimensions.len() > 2 {
            return Err(format!(
                "deck has {} .DC sweep dimensions; native Xyce static adapter currently supports one or two",
                dimensions.len()
            ));
        }

        for (index, dimension) in dimensions.iter().enumerate() {
            if dimension.spec().points().is_empty() {
                if index == 0 {
                    return Err("deck has invalid .DC sweep bounds".to_string());
                }
                return Err("deck has invalid secondary .DC sweep bounds".to_string());
            }
        }

        let primary = dimensions.remove(0);
        let sweep2 = dimensions
            .pop()
            .map(XyceDcSweepDimension::into_second_sweep);
        Ok(XyceDcSweep {
            source: primary.source,
            start: primary.start,
            stop: primary.stop,
            step: primary.step,
            mode: primary.mode,
            sweep2,
        })
    }

    fn synthetic_op_dc_sweep(netlist: &Netlist) -> Result<XyceDcSweep, String> {
        for element in &netlist.elements {
            let dc_value = match &element.kind {
                ElementKind::VoltageSource(spec) | ElementKind::CurrentSource(spec) => {
                    extract_dc_value(spec)
                }
                _ => continue,
            };
            if !dc_value.is_finite() {
                return Err(format!(
                    ".OP source '{}' has non-finite DC value {}",
                    element.name, dc_value
                ));
            }
            return Ok(XyceDcSweep {
                source: element.name.clone(),
                start: dc_value,
                stop: dc_value,
                step: 1.0,
                mode: crate::netlist::DcSweepMode::Linear,
                sweep2: None,
            });
        }

        Err(".OP static .PRINT DC output requires at least one independent source for the native one-point adapter".to_string())
    }

    fn single_dc_print_request(source: &str) -> Result<XycePrintRequest, String> {
        let request = Self::single_dc_print_output_request(source)?;
        Ok(XycePrintRequest {
            probes: request.probes,
        })
    }

    fn single_dc_print_output_request(source: &str) -> Result<XycePrintOutputRequest, String> {
        let requests = Self::print_output_requests(source, "DC")?
            .into_iter()
            .filter(|request| request.file.is_none())
            .collect::<Vec<_>>();

        match requests.len() {
            0 => Err("deck has no .PRINT DC statement with static columns".to_string()),
            1 => Ok(requests.into_iter().next().expect("one request")),
            _ => Err("deck has multiple .PRINT DC statements; multi-table comparison is not implemented yet".to_string()),
        }
    }

    fn single_dc_or_file_output_request(source: &str) -> Result<XycePrintOutputRequest, String> {
        match Self::single_dc_print_output_request(source) {
            Ok(request) => Ok(request),
            Err(primary_error) => {
                let mut side_outputs = Self::prn_compatible_side_output_requests(source)?
                    .into_iter()
                    .collect::<Vec<_>>();
                if side_outputs.is_empty() {
                    return Err(primary_error);
                }
                side_outputs.sort_by(|left, right| left.file.cmp(&right.file));
                Ok(side_outputs.remove(0))
            }
        }
    }

    fn single_tran_print_output_request(source: &str) -> Result<XycePrintOutputRequest, String> {
        let requests = Self::print_output_requests(source, "TRAN")?
            .into_iter()
            .filter(|request| request.file.is_none())
            .collect::<Vec<_>>();

        match requests.len() {
            0 => Err("deck has no .PRINT TRAN statement with static columns".to_string()),
            1 => Ok(requests.into_iter().next().expect("one request")),
            _ => Err("deck has multiple .PRINT TRAN statements; multi-table comparison is not implemented yet".to_string()),
        }
    }

    #[cfg(test)]
    fn single_ac_print_request(source: &str) -> Result<XycePrintRequest, String> {
        let request = Self::single_ac_print_output_request(source)?;
        Ok(XycePrintRequest {
            probes: request.probes,
        })
    }

    #[cfg(test)]
    fn single_ac_print_output_request(source: &str) -> Result<XycePrintOutputRequest, String> {
        match Self::primary_print_output_request(source, "AC")? {
            Some(request) => Ok(request),
            None => Err("deck has no .PRINT AC statement with static columns".to_string()),
        }
    }

    #[cfg(test)]
    fn primary_print_output_request(
        source: &str,
        analysis: &str,
    ) -> Result<Option<XycePrintOutputRequest>, String> {
        Self::canonical_print_output_request(source, analysis, false)
    }

    fn canonical_print_output_request(
        source: &str,
        analysis: &str,
        allow_single_file_output: bool,
    ) -> Result<Option<XycePrintOutputRequest>, String> {
        let requests = Self::aggregate_print_output_requests(
            Self::print_output_requests(source, analysis)?,
            analysis,
        )?;
        let primary_requests = requests
            .iter()
            .filter(|request| request.file.is_none())
            .cloned()
            .collect::<Vec<_>>();

        match primary_requests.len() {
            0 => Ok(None),
            1 => Ok(Some(
                primary_requests.into_iter().next().expect("one request"),
            )),
            _ => Err(format!(
                "deck has multiple primary .PRINT {analysis} output destinations after aggregation"
            )),
        }
        .and_then(|primary| {
            if primary.is_some() || !allow_single_file_output {
                return Ok(primary);
            }
            let file_requests = requests
                .into_iter()
                .filter(|request| request.file.is_some())
                .collect::<Vec<_>>();
            match file_requests.len() {
                0 => Ok(None),
                1 => Ok(file_requests.into_iter().next()),
                _ => Err(format!(
                    "deck has multiple .PRINT {analysis} FILE= outputs and no primary output"
                )),
            }
        })
    }

    fn output_override_print_output_request(
        source: &str,
        analysis: &str,
    ) -> Result<Option<XycePrintOutputRequest>, String> {
        let mut probes = Vec::new();
        for request in Self::print_output_requests(source, analysis)? {
            probes.extend(request.probes);
        }
        if probes.is_empty() {
            return Ok(None);
        }
        Ok(Some(XycePrintOutputRequest {
            format: None,
            file: None,
            probes,
        }))
    }

    fn aggregate_print_output_requests(
        requests: Vec<XycePrintOutputRequest>,
        analysis: &str,
    ) -> Result<Vec<XycePrintOutputRequest>, String> {
        let mut aggregated: Vec<XycePrintOutputRequest> = Vec::new();
        for request in requests {
            if let Some(existing) = aggregated
                .iter_mut()
                .find(|existing| existing.file == request.file)
            {
                Self::validate_print_output_format_compatible(
                    existing.format.as_deref(),
                    request.format.as_deref(),
                    analysis,
                    request.file.as_deref(),
                )?;
                existing.probes.extend(request.probes);
                if existing.format.is_none() {
                    existing.format = request.format;
                }
            } else {
                aggregated.push(request);
            }
        }
        Ok(aggregated)
    }

    fn validate_print_output_format_compatible(
        existing: Option<&str>,
        incoming: Option<&str>,
        analysis: &str,
        file: Option<&str>,
    ) -> Result<(), String> {
        let existing_key = Self::print_format_key(existing);
        let incoming_key = Self::print_format_key(incoming);
        if existing_key == incoming_key {
            return Ok(());
        }
        let destination = file
            .map(|file| format!("FILE={file}"))
            .unwrap_or_else(|| "primary output".to_string());
        Err(format!(
            "multiple .PRINT {analysis} statements for {destination} use different FORMAT values ({existing_key} and {incoming_key})"
        ))
    }

    fn print_format_key(format: Option<&str>) -> String {
        format.unwrap_or("STD").trim().to_ascii_lowercase()
    }

    fn dc_print_output_requests(source: &str) -> Result<Vec<XycePrintOutputRequest>, String> {
        Self::print_output_requests(source, "DC")
    }

    fn deck_has_print_analysis(&self, deck: &XyceDeck, analysis: &str) -> bool {
        fs::read_to_string(&deck.path).is_ok_and(|source| {
            Self::print_output_requests(&source, analysis).is_ok_and(|requests| {
                requests
                    .into_iter()
                    .any(|request| request.file.is_none() && !request.probes.is_empty())
            })
        })
    }

    fn print_output_requests(
        source: &str,
        expected_analysis: &str,
    ) -> Result<Vec<XycePrintOutputRequest>, String> {
        let mut requests = Vec::new();
        for line in Self::logical_netlist_lines(source) {
            let trimmed = Self::strip_netlist_comment(&line).trim().to_string();
            if trimmed.is_empty() {
                continue;
            }
            let Some(command) = trimmed.split_whitespace().next() else {
                continue;
            };
            if !command.eq_ignore_ascii_case(".print") {
                continue;
            }
            let tokens = Self::split_print_fields(&trimmed)?;
            let token_refs = tokens.iter().map(String::as_str).collect::<Vec<_>>();
            let Some(analysis) = token_refs.get(1).copied() else {
                return Err(".PRINT statement has no analysis type".to_string());
            };
            if !analysis.eq_ignore_ascii_case(expected_analysis) {
                continue;
            }

            let mut format = None;
            let mut file = None;
            let mut probes = Vec::new();
            let mut index = 2usize;
            while index < tokens.len() {
                if let Some((raw_key, raw_value, consumed)) =
                    Self::print_option_assignment(&token_refs, index)
                {
                    let key = raw_key.trim().to_ascii_lowercase();
                    let value = raw_value.trim().trim_matches(['"', '\'']).to_string();
                    match key.as_str() {
                        "format" => format = Some(value),
                        "file" => file = Some(value),
                        _ => {}
                    }
                    index += consumed;
                    continue;
                }

                let normalized = token_refs[index].to_ascii_lowercase();
                if Self::is_print_option_token(&normalized) {
                    index += 1;
                    continue;
                }
                probes.push(Self::canonicalize_single_quoted_print_probe(
                    &tokens[index],
                )?);
                index += 1;
            }

            if probes.is_empty() {
                continue;
            }
            requests.push(XycePrintOutputRequest {
                format,
                file,
                probes,
            });
        }

        Ok(requests)
    }

    fn split_print_fields(line: &str) -> Result<Vec<String>, String> {
        Self::split_grouped_whitespace_fields(line, ".PRINT statement")
    }

    fn canonicalize_single_quoted_print_probe(probe: &str) -> Result<String, String> {
        let trimmed = probe.trim();
        let starts_quote = trimmed.starts_with('\'');
        let ends_quote = trimmed.ends_with('\'');
        if !starts_quote && !ends_quote {
            return Ok(probe.to_string());
        }
        if !starts_quote || !ends_quote || trimmed.len() < 2 {
            return Err(format!(
                "malformed single-quoted .PRINT expression '{probe}'"
            ));
        }
        let inner = trimmed[1..trimmed.len() - 1].trim();
        if inner.is_empty() || inner.contains('\'') || inner.contains('{') || inner.contains('}') {
            return Err(format!(
                "single-quoted .PRINT expression must be nonempty and must not mix expression delimiters: '{probe}'"
            ));
        }
        Ok(format!("{{{inner}}}"))
    }

    fn split_prn_header_fields(line: &str) -> Result<Vec<String>, String> {
        Self::split_grouped_whitespace_fields(line, "Xyce .prn header")
    }

    fn split_grouped_whitespace_fields(
        line: &str,
        source_label: &str,
    ) -> Result<Vec<String>, String> {
        let mut fields = Vec::new();
        let mut current = String::new();
        let mut single_quote = false;
        let mut double_quote = false;
        let mut escaped = false;
        let mut brace_depth = 0usize;
        let mut paren_depth = 0usize;

        for ch in line.chars() {
            if escaped {
                current.push(ch);
                escaped = false;
                continue;
            }

            match ch {
                '\\' if single_quote || double_quote => {
                    current.push(ch);
                    escaped = true;
                }
                '\'' if !double_quote => {
                    single_quote = !single_quote;
                    current.push(ch);
                }
                '"' if !single_quote => {
                    double_quote = !double_quote;
                    current.push(ch);
                }
                '{' if !single_quote && !double_quote => {
                    brace_depth += 1;
                    current.push(ch);
                }
                '}' if !single_quote && !double_quote => {
                    brace_depth = brace_depth.checked_sub(1).ok_or_else(|| {
                        format!("unmatched closing brace in {source_label}: {line}")
                    })?;
                    current.push(ch);
                }
                '(' if !single_quote && !double_quote => {
                    paren_depth += 1;
                    current.push(ch);
                }
                ')' if !single_quote && !double_quote => {
                    paren_depth = paren_depth.checked_sub(1).ok_or_else(|| {
                        format!("unmatched closing parenthesis in {source_label}: {line}")
                    })?;
                    current.push(ch);
                }
                ch if ch.is_whitespace()
                    && !single_quote
                    && !double_quote
                    && brace_depth == 0
                    && paren_depth == 0 =>
                {
                    if !current.is_empty() {
                        fields.push(std::mem::take(&mut current));
                    }
                }
                _ => current.push(ch),
            }
        }

        if single_quote || double_quote {
            return Err(format!("unterminated quote in {source_label}: {line}"));
        }
        if brace_depth != 0 {
            return Err(format!(
                "unterminated brace expression in {source_label}: {line}"
            ));
        }
        if paren_depth != 0 {
            return Err(format!(
                "unterminated parenthesized probe in {source_label}: {line}"
            ));
        }
        if !current.is_empty() {
            fields.push(current);
        }

        Ok(fields)
    }

    fn gnuplot_splot_print_pair(
        source: &str,
    ) -> Result<(XycePrintOutputRequest, XycePrintOutputRequest), String> {
        let requests = Self::dc_print_output_requests(source)?;
        let mut primary = None;
        let mut side = None;
        for request in requests {
            let format = request.format.as_deref().unwrap_or("STD");
            if request.file.is_none() && format.eq_ignore_ascii_case("GNUPLOT") {
                if primary.replace(request).is_some() {
                    return Err(
                        "GNUPLOT/SPLOT contract requires exactly one primary GNUPLOT .PRINT DC"
                            .to_string(),
                    );
                }
                continue;
            }
            if request.file.is_some() && format.eq_ignore_ascii_case("SPLOT") {
                if side.replace(request).is_some() {
                    return Err(
                        "GNUPLOT/SPLOT contract requires exactly one named SPLOT .PRINT DC"
                            .to_string(),
                    );
                }
                continue;
            }
            return Err(format!(
                "GNUPLOT/SPLOT contract does not cover .PRINT DC FORMAT={format} FILE={}",
                request.file.as_deref().unwrap_or("<default>")
            ));
        }

        match (primary, side) {
            (Some(primary), Some(side)) => Ok((primary, side)),
            _ => Err(
                "GNUPLOT/SPLOT contract requires one primary GNUPLOT and one named SPLOT .PRINT DC"
                    .to_string(),
            ),
        }
    }

    fn is_print_option_token(token: &str) -> bool {
        token.starts_with("format=")
            || token.starts_with("width=")
            || token.starts_with("precision=")
            || token.starts_with("delimiter=")
            || token.starts_with("noindex")
            || token.starts_with("index=")
    }

    fn parse_measurement_reference_file(
        path: &Path,
    ) -> Result<Vec<XyceMeasurementReference>, String> {
        let content =
            fs::read_to_string(path).map_err(|err| format!("{}: {err}", path.display()))?;
        let mut references = Vec::new();
        let mut names = BTreeSet::new();
        for (line_index, raw_line) in content.lines().enumerate() {
            let line = raw_line.trim();
            if line.is_empty() || line.starts_with('*') {
                continue;
            }
            let (raw_name, raw_value) = line.split_once('=').ok_or_else(|| {
                format!(
                    "{}:{}: expected '<measurement> = <value|FAILED>'",
                    path.display(),
                    line_index + 1
                )
            })?;
            let name = raw_name.trim();
            if name.is_empty() {
                return Err(format!(
                    "{}:{}: measurement name is empty",
                    path.display(),
                    line_index + 1
                ));
            }
            let normalized_name = name.to_ascii_uppercase();
            if !names.insert(normalized_name) {
                return Err(format!(
                    "{}:{}: duplicate measurement '{}'",
                    path.display(),
                    line_index + 1,
                    name
                ));
            }
            let raw_value = raw_value.trim();
            if raw_value.split_whitespace().count() != 1 {
                return Err(format!(
                    "{}:{}: measurement result must be one token",
                    path.display(),
                    line_index + 1
                ));
            }
            let value = if raw_value == "FAILED" {
                XyceMeasurementReferenceValue::Failed
            } else {
                let value = crate::netlist::lexer::parse_spice_value(raw_value).map_err(|err| {
                    format!(
                        "{}:{}: invalid measurement value '{}': {err}",
                        path.display(),
                        line_index + 1,
                        raw_value
                    )
                })?;
                if !value.is_finite() {
                    return Err(format!(
                        "{}:{}: measurement value must be finite",
                        path.display(),
                        line_index + 1
                    ));
                }
                XyceMeasurementReferenceValue::Numeric {
                    value,
                    quantization: Self::measurement_literal_quantization(raw_value),
                }
            };
            references.push(XyceMeasurementReference {
                name: name.to_string(),
                value,
            });
        }
        if references.is_empty() {
            return Err(format!("{} has no measurement results", path.display()));
        }
        Ok(references)
    }

    fn parse_continuous_measurement_reference_file(
        path: &Path,
    ) -> Result<XyceContinuousMeasurementReference, String> {
        let content =
            fs::read_to_string(path).map_err(|err| format!("{}: {err}", path.display()))?;
        let mut name: Option<String> = None;
        let mut records = Vec::new();
        for (line_index, raw_line) in content.lines().enumerate() {
            let line_number = line_index + 1;
            let line = raw_line.trim();
            if line.is_empty() || line.starts_with('*') {
                continue;
            }
            let (raw_name, raw_fields) = line.split_once('=').ok_or_else(|| {
                format!(
                    "{}:{line_number}: expected '<measurement> = <value|FAILED>'",
                    path.display()
                )
            })?;
            let row_name = raw_name.trim();
            if row_name.is_empty() {
                return Err(format!(
                    "{}:{line_number}: measurement name is empty",
                    path.display()
                ));
            }
            if let Some(expected_name) = name.as_deref() {
                if !row_name.eq_ignore_ascii_case(expected_name) {
                    return Err(format!(
                        "{}:{line_number}: measurement '{}' does not match first row '{}'",
                        path.display(),
                        row_name,
                        expected_name
                    ));
                }
            } else {
                name = Some(row_name.to_string());
            }

            let fields = raw_fields.split_whitespace().collect::<Vec<_>>();
            if fields.is_empty() {
                return Err(format!(
                    "{}:{line_number}: measurement result is empty",
                    path.display()
                ));
            }
            let value = Self::parse_measurement_reference_token(path, line_number, fields[0])?;
            let mut trigger_axis = None;
            let mut target_axis = None;
            let mut field_index = 1usize;
            while field_index < fields.len() {
                if field_index + 2 >= fields.len() || fields[field_index + 1] != "=" {
                    return Err(format!(
                        "{}:{line_number}: expected '<targ|trig> = <value>' after measurement value",
                        path.display()
                    ));
                }
                let label = fields[field_index];
                let parsed = Self::parse_measurement_reference_token(
                    path,
                    line_number,
                    fields[field_index + 2],
                )?;
                if matches!(parsed, XyceMeasurementReferenceValue::Failed) {
                    return Err(format!(
                        "{}:{line_number}: {label} metadata cannot be FAILED",
                        path.display()
                    ));
                }
                let slot = if label.eq_ignore_ascii_case("trig") {
                    &mut trigger_axis
                } else if label.eq_ignore_ascii_case("targ") {
                    &mut target_axis
                } else {
                    return Err(format!(
                        "{}:{line_number}: unknown continuous measurement metadata '{label}'",
                        path.display()
                    ));
                };
                if slot.replace(parsed).is_some() {
                    return Err(format!(
                        "{}:{line_number}: duplicate {label} metadata",
                        path.display()
                    ));
                }
                field_index += 3;
            }
            if matches!(value, XyceMeasurementReferenceValue::Failed)
                && (trigger_axis.is_some() || target_axis.is_some())
            {
                return Err(format!(
                    "{}:{line_number}: FAILED result cannot carry trigger or target metadata",
                    path.display()
                ));
            }
            if trigger_axis.is_some() != target_axis.is_some() {
                return Err(format!(
                    "{}:{line_number}: trigger/target metadata must be present as a pair",
                    path.display()
                ));
            }
            records.push(XyceContinuousMeasurementReferenceRecord {
                value,
                trigger_axis,
                target_axis,
            });
        }
        let name = name.ok_or_else(|| format!("{} has no measurement results", path.display()))?;
        Ok(XyceContinuousMeasurementReference { name, records })
    }

    fn parse_measurement_reference_token(
        path: &Path,
        line_number: usize,
        raw_value: &str,
    ) -> Result<XyceMeasurementReferenceValue, String> {
        if raw_value == "FAILED" {
            return Ok(XyceMeasurementReferenceValue::Failed);
        }
        let value = crate::netlist::lexer::parse_spice_value(raw_value).map_err(|err| {
            format!(
                "{}:{line_number}: invalid measurement value '{}': {err}",
                path.display(),
                raw_value
            )
        })?;
        if !value.is_finite() {
            return Err(format!(
                "{}:{line_number}: measurement value must be finite",
                path.display()
            ));
        }
        Ok(XyceMeasurementReferenceValue::Numeric {
            value,
            quantization: Self::measurement_literal_quantization(raw_value),
        })
    }

    fn parse_mixed_measurement_reference_file(
        path: &Path,
    ) -> Result<Vec<XyceMixedMeasurementReferenceRow>, String> {
        let content =
            fs::read_to_string(path).map_err(|err| format!("{}: {err}", path.display()))?;
        let mut rows = Vec::new();
        for (line_index, raw_line) in content.lines().enumerate() {
            let line_number = line_index + 1;
            let line = raw_line.trim();
            if line.is_empty() || line.starts_with('*') {
                continue;
            }
            let (raw_name, raw_fields) = line.split_once('=').ok_or_else(|| {
                format!(
                    "{}:{line_number}: expected '<measurement> = <value|FAILED>'",
                    path.display()
                )
            })?;
            let name = raw_name.trim();
            if name.is_empty() {
                return Err(format!(
                    "{}:{line_number}: measurement name is empty",
                    path.display()
                ));
            }
            let fields = raw_fields.split_whitespace().collect::<Vec<_>>();
            if fields.is_empty() {
                return Err(format!(
                    "{}:{line_number}: measurement result is empty",
                    path.display()
                ));
            }
            let value = Self::parse_measurement_reference_token(path, line_number, fields[0])?;
            let mut trigger_axis = None;
            let mut target_axis = None;
            let mut field_index = 1usize;
            while field_index < fields.len() {
                if field_index + 2 >= fields.len() || fields[field_index + 1] != "=" {
                    return Err(format!(
                        "{}:{line_number}: expected '<targ|trig> = <value|not found>' after measurement value",
                        path.display()
                    ));
                }
                let label = fields[field_index];
                let (parsed, consumed) = if fields[field_index + 2].eq_ignore_ascii_case("not") {
                    if fields
                        .get(field_index + 3)
                        .is_none_or(|field| !field.eq_ignore_ascii_case("found"))
                    {
                        return Err(format!(
                            "{}:{line_number}: expected 'not found' after {label} =",
                            path.display()
                        ));
                    }
                    (XyceMeasurementReferenceValue::Failed, 4)
                } else {
                    (
                        Self::parse_measurement_reference_token(
                            path,
                            line_number,
                            fields[field_index + 2],
                        )?,
                        3,
                    )
                };
                let slot = if label.eq_ignore_ascii_case("trig") {
                    &mut trigger_axis
                } else if label.eq_ignore_ascii_case("targ") {
                    &mut target_axis
                } else {
                    return Err(format!(
                        "{}:{line_number}: unknown mixed measurement metadata '{label}'",
                        path.display()
                    ));
                };
                if slot.replace(parsed).is_some() {
                    return Err(format!(
                        "{}:{line_number}: duplicate {label} metadata",
                        path.display()
                    ));
                }
                field_index += consumed;
            }
            if trigger_axis.is_some() != target_axis.is_some() {
                return Err(format!(
                    "{}:{line_number}: trigger/target metadata must be present as a pair",
                    path.display()
                ));
            }
            rows.push(XyceMixedMeasurementReferenceRow {
                name: name.to_string(),
                value,
                trigger_axis,
                target_axis,
            });
        }
        if rows.is_empty() {
            return Err(format!("{} has no measurement results", path.display()));
        }
        Ok(rows)
    }

    fn compare_measurement_references(
        &self,
        paths: &[PathBuf],
        actual: &[crate::analysis::MeasureResult],
        tolerance: XyceFileCompareTolerance,
        measure_fail_output: Option<bool>,
        measure_default_value: Option<Value>,
        analysis: &str,
        declarations: &[crate::analysis::MeasureStatement],
    ) -> Result<Vec<XyceValueMismatch>, String> {
        if paths.len() != 1 {
            return Err(format!(
                "unstepped measurement comparison requires exactly one artifact, found {}",
                paths.len()
            ));
        }
        let expected = Self::parse_measurement_reference_file(&paths[0])?;
        if expected.len() != actual.len() {
            return Err(format!(
                "measurement artifact contains {} results but the netlist evaluated {} statements",
                expected.len(),
                actual.len()
            ));
        }
        let mut mismatches = Vec::new();
        for (row, (reference, result)) in expected.iter().zip(actual).enumerate() {
            if reference.name != result.name {
                return Err(format!(
                    "measurement {} is '{}' in the artifact but '{}' in declaration order",
                    row, reference.name, result.name
                ));
            }
            match reference.value {
                XyceMeasurementReferenceValue::Failed if result.value.is_none() => {}
                XyceMeasurementReferenceValue::Failed => {
                    return Err(format!(
                        "measurement '{}' was expected to be FAILED but evaluated to {}",
                        reference.name,
                        result.value.expect("matched nonempty measurement result")
                    ));
                }
                XyceMeasurementReferenceValue::Numeric {
                    value: expected_value,
                    quantization,
                } => {
                    let actual_value = match result.value {
                        Some(value) => value,
                        None if measure_fail_output == Some(false) => {
                            let local_default = declarations
                                .iter()
                                .find(|statement| {
                                    statement.name.eq_ignore_ascii_case(&reference.name)
                                        && statement.analysis.eq_ignore_ascii_case(analysis)
                                })
                                .and_then(|statement| statement.default_value);
                            measure_default_value.or(local_default).unwrap_or(0.0)
                        }
                        None => {
                            return Err(format!(
                                "measurement '{}' was expected to evaluate to {} but FAILED: {}",
                                reference.name,
                                expected_value,
                                result.error.as_deref().unwrap_or("no failure reason")
                            ));
                        }
                    };
                    let absolute_error = (expected_value - actual_value).abs();
                    let relative_error = if expected_value == 0.0 {
                        f64::INFINITY
                    } else {
                        absolute_error / expected_value.abs()
                    };
                    let matches = Self::measurement_value_matches(
                        expected_value,
                        actual_value,
                        quantization,
                        tolerance,
                    );
                    if !matches {
                        mismatches.push(XyceValueMismatch {
                            row,
                            probe: reference.name.clone(),
                            expected: expected_value,
                            actual: actual_value,
                            relative_error,
                        });
                    }
                }
            }
        }
        Ok(mismatches)
    }

    fn compare_continuous_measurement_references(
        &self,
        paths: &[PathBuf],
        actual: &[crate::analysis::ContinuousMeasureResult],
        tolerance: XyceFileCompareTolerance,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        if paths.len() != actual.len() {
            return Err(format!(
                "continuous measurement oracle contains {} artifact(s) but the netlist evaluated {} statement(s)",
                paths.len(),
                actual.len()
            ));
        }
        let mut mismatches = Vec::new();
        let mut global_row = 0usize;
        for (path, result) in paths.iter().zip(actual) {
            let reference = Self::parse_continuous_measurement_reference_file(path)?;
            if !reference.name.eq_ignore_ascii_case(&result.name) {
                return Err(format!(
                    "continuous artifact '{}' contains '{}' but declaration order requires '{}'",
                    path.display(),
                    reference.name,
                    result.name
                ));
            }
            if reference.records.len() == 1
                && matches!(
                    reference.records[0].value,
                    XyceMeasurementReferenceValue::Failed
                )
            {
                if result.failure.is_none() {
                    return Err(format!(
                        "continuous measurement '{}' was expected to be FAILED but produced {} record(s)",
                        result.name,
                        result.records.len()
                    ));
                }
                global_row += 1;
                continue;
            }
            if let Some(failure) = result.failure.as_deref() {
                return Err(format!(
                    "continuous measurement '{}' was expected to produce {} record(s) but FAILED: {failure}",
                    result.name,
                    reference.records.len()
                ));
            }
            if reference.records.len() != result.records.len() {
                return Err(format!(
                    "continuous measurement '{}' artifact contains {} record(s) but evaluation produced {}",
                    result.name,
                    reference.records.len(),
                    result.records.len()
                ));
            }
            for (reference_record, actual_record) in reference.records.iter().zip(&result.records) {
                Self::compare_continuous_measurement_value(
                    &mut mismatches,
                    global_row,
                    &result.name,
                    reference_record.value,
                    Some(actual_record.value),
                    tolerance,
                )?;
                Self::compare_continuous_measurement_value(
                    &mut mismatches,
                    global_row,
                    &format!("{}:trig", result.name),
                    reference_record
                        .trigger_axis
                        .unwrap_or(XyceMeasurementReferenceValue::Failed),
                    actual_record.trigger_axis,
                    tolerance,
                )?;
                Self::compare_continuous_measurement_value(
                    &mut mismatches,
                    global_row,
                    &format!("{}:targ", result.name),
                    reference_record
                        .target_axis
                        .unwrap_or(XyceMeasurementReferenceValue::Failed),
                    actual_record.target_axis,
                    tolerance,
                )?;
                global_row += 1;
            }
        }
        Ok(mismatches)
    }

    #[allow(clippy::too_many_arguments)]
    fn compare_analysis_measurement_outputs(
        &self,
        scalar_paths: &[PathBuf],
        continuous_paths: &[PathBuf],
        scalar: &[crate::analysis::MeasureResult],
        continuous: &[crate::analysis::ContinuousMeasureResult],
        tolerance: XyceFileCompareTolerance,
        measure_fail_output: Option<bool>,
        measure_default_value: Option<Value>,
        use_continuous_files: bool,
        declarations: &[crate::analysis::MeasureStatement],
        base_analysis: &str,
        continuous_analysis: &str,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        if !use_continuous_files {
            return self.compare_mixed_measurement_references(
                scalar_paths,
                scalar,
                continuous,
                tolerance,
                declarations,
                base_analysis,
                continuous_analysis,
            );
        }

        let mut mismatches = if scalar_paths.is_empty() {
            Vec::new()
        } else {
            self.compare_measurement_references(
                scalar_paths,
                scalar,
                tolerance,
                measure_fail_output,
                measure_default_value,
                base_analysis,
                declarations,
            )?
        };
        let continuous_declarations = declarations
            .iter()
            .filter(|declaration| {
                declaration
                    .analysis
                    .eq_ignore_ascii_case(continuous_analysis)
            })
            .collect::<Vec<_>>();
        if continuous_declarations.len() != continuous.len() {
            return Err(format!(
                "{continuous_analysis} evaluator returned {} result(s) for {} declaration(s)",
                continuous.len(),
                continuous_declarations.len()
            ));
        }
        let mut visible_continuous = Vec::new();
        for (declaration, result) in continuous_declarations.into_iter().zip(continuous) {
            if !declaration.name.eq_ignore_ascii_case(&result.name) {
                return Err(format!(
                    "{continuous_analysis} evaluator returned '{}' for declaration '{}'",
                    result.name, declaration.name
                ));
            }
            if declaration.print_policy == crate::analysis::MeasurePrintPolicy::All {
                visible_continuous.push(result.clone());
            }
        }
        mismatches.extend(self.compare_continuous_measurement_references(
            continuous_paths,
            &visible_continuous,
            tolerance,
        )?);
        Ok(mismatches)
    }

    fn compare_mixed_measurement_references(
        &self,
        paths: &[PathBuf],
        scalar: &[crate::analysis::MeasureResult],
        continuous: &[crate::analysis::ContinuousMeasureResult],
        tolerance: XyceFileCompareTolerance,
        declarations: &[crate::analysis::MeasureStatement],
        base_analysis: &str,
        continuous_analysis: &str,
    ) -> Result<Vec<XyceValueMismatch>, String> {
        if paths.len() != 1 {
            return Err(format!(
                "one mixed measurement run requires exactly one aggregate artifact, found {}",
                paths.len()
            ));
        }
        let expected = Self::parse_mixed_measurement_reference_file(&paths[0])?;
        let mut actual = Vec::new();
        let mut scalar_index = 0usize;
        let mut continuous_index = 0usize;
        for declaration in declarations.iter().filter(|declaration| {
            declaration.analysis.eq_ignore_ascii_case(base_analysis)
                || declaration
                    .analysis
                    .eq_ignore_ascii_case(continuous_analysis)
        }) {
            if declaration.analysis.eq_ignore_ascii_case(base_analysis) {
                let result = scalar.get(scalar_index).ok_or_else(|| {
                    format!(
                        "scalar {base_analysis} evaluator omitted declaration {} ('{}')",
                        scalar_index, declaration.name
                    )
                })?;
                scalar_index += 1;
                if !result.name.eq_ignore_ascii_case(&declaration.name) {
                    return Err(format!(
                        "scalar {base_analysis} evaluator returned '{}' for declaration '{}'",
                        result.name, declaration.name
                    ));
                }
                if declaration.print_policy == crate::analysis::MeasurePrintPolicy::All {
                    actual.push(XyceMixedMeasurementReferenceRow {
                        name: result.name.clone(),
                        value: result.value.map_or(
                            XyceMeasurementReferenceValue::Failed,
                            |value| XyceMeasurementReferenceValue::Numeric {
                                value,
                                quantization: None,
                            },
                        ),
                        trigger_axis: None,
                        target_axis: None,
                    });
                }
            } else {
                let result = continuous.get(continuous_index).ok_or_else(|| {
                    format!(
                        "continuous {continuous_analysis} evaluator omitted declaration {} ('{}')",
                        continuous_index, declaration.name
                    )
                })?;
                continuous_index += 1;
                if !result.name.eq_ignore_ascii_case(&declaration.name) {
                    return Err(format!(
                        "continuous {continuous_analysis} evaluator returned '{}' for declaration '{}'",
                        result.name, declaration.name
                    ));
                }
                if declaration.print_policy != crate::analysis::MeasurePrintPolicy::All {
                    continue;
                }
                if result.failure.is_some() {
                    actual.push(XyceMixedMeasurementReferenceRow {
                        name: result.name.clone(),
                        value: XyceMeasurementReferenceValue::Failed,
                        trigger_axis: None,
                        target_axis: None,
                    });
                } else {
                    actual.extend(result.records.iter().map(|record| {
                        XyceMixedMeasurementReferenceRow {
                            name: result.name.clone(),
                            value: XyceMeasurementReferenceValue::Numeric {
                                value: record.value,
                                quantization: None,
                            },
                            trigger_axis: record.trigger_axis.map(|value| {
                                XyceMeasurementReferenceValue::Numeric {
                                    value,
                                    quantization: None,
                                }
                            }),
                            target_axis: record.target_axis.map(|value| {
                                XyceMeasurementReferenceValue::Numeric {
                                    value,
                                    quantization: None,
                                }
                            }),
                        }
                    }));
                }
            }
        }
        if scalar_index != scalar.len() || continuous_index != continuous.len() {
            return Err(format!(
                "measurement evaluators returned unclaimed results (scalar {scalar_index}/{}, continuous {continuous_index}/{})",
                scalar.len(),
                continuous.len()
            ));
        }
        if expected.len() != actual.len() {
            return Err(format!(
                "mixed measurement artifact contains {} row(s) but evaluation emitted {} row(s)",
                expected.len(),
                actual.len()
            ));
        }

        let mut mismatches = Vec::new();
        for (row, (reference, result)) in expected.iter().zip(&actual).enumerate() {
            if !reference.name.eq_ignore_ascii_case(&result.name) {
                return Err(format!(
                    "mixed measurement row {row} is '{}' in the artifact but '{}' in declaration-ordered evaluation",
                    reference.name, result.name
                ));
            }
            Self::compare_mixed_measurement_value(
                &mut mismatches,
                row,
                &reference.name,
                reference.value,
                result.value,
                tolerance,
            )?;
            // A FAILED TRIG/TARG row may include Xyce's partial diagnostic
            // event locations. ContinuousMeasureResult intentionally models
            // failure atomically, so the primary FAILED contract is compared
            // while those non-result diagnostics are not synthesized.
            if !matches!(reference.value, XyceMeasurementReferenceValue::Failed) {
                Self::compare_mixed_measurement_metadata(
                    &mut mismatches,
                    row,
                    &format!("{}:trig", reference.name),
                    reference.trigger_axis,
                    result.trigger_axis,
                    tolerance,
                )?;
                Self::compare_mixed_measurement_metadata(
                    &mut mismatches,
                    row,
                    &format!("{}:targ", reference.name),
                    reference.target_axis,
                    result.target_axis,
                    tolerance,
                )?;
            }
        }
        Ok(mismatches)
    }

    fn compare_mixed_measurement_value(
        mismatches: &mut Vec<XyceValueMismatch>,
        row: usize,
        probe: &str,
        expected: XyceMeasurementReferenceValue,
        actual: XyceMeasurementReferenceValue,
        tolerance: XyceFileCompareTolerance,
    ) -> Result<(), String> {
        match (expected, actual) {
            (XyceMeasurementReferenceValue::Failed, XyceMeasurementReferenceValue::Failed) => {
                Ok(())
            }
            (
                XyceMeasurementReferenceValue::Failed,
                XyceMeasurementReferenceValue::Numeric { value, .. },
            ) => Err(format!(
                "mixed measurement '{probe}' row {row} was expected to be FAILED but evaluated to {value}"
            )),
            (
                XyceMeasurementReferenceValue::Numeric { value, .. },
                XyceMeasurementReferenceValue::Failed,
            ) => Err(format!(
                "mixed measurement '{probe}' row {row} was expected to evaluate to {value} but FAILED"
            )),
            (
                XyceMeasurementReferenceValue::Numeric {
                    value: expected,
                    quantization,
                },
                XyceMeasurementReferenceValue::Numeric { value: actual, .. },
            ) => {
                if !Self::measurement_value_matches(expected, actual, quantization, tolerance) {
                    let absolute_error = (expected - actual).abs();
                    mismatches.push(XyceValueMismatch {
                        row,
                        probe: probe.to_string(),
                        expected,
                        actual,
                        relative_error: if expected == 0.0 {
                            f64::INFINITY
                        } else {
                            absolute_error / expected.abs()
                        },
                    });
                }
                Ok(())
            }
        }
    }

    fn compare_mixed_measurement_metadata(
        mismatches: &mut Vec<XyceValueMismatch>,
        row: usize,
        probe: &str,
        expected: Option<XyceMeasurementReferenceValue>,
        actual: Option<XyceMeasurementReferenceValue>,
        tolerance: XyceFileCompareTolerance,
    ) -> Result<(), String> {
        match (expected, actual) {
            (None, None) | (Some(XyceMeasurementReferenceValue::Failed), None) => Ok(()),
            (None, Some(XyceMeasurementReferenceValue::Numeric { value, .. })) => Err(format!(
                "mixed measurement artifact has no {probe} metadata at row {row}, but evaluation produced {value}"
            )),
            (
                Some(XyceMeasurementReferenceValue::Failed),
                Some(XyceMeasurementReferenceValue::Numeric { value, .. }),
            ) => Err(format!(
                "mixed measurement artifact marks {probe} not found at row {row}, but evaluation produced {value}"
            )),
            (
                Some(XyceMeasurementReferenceValue::Numeric { value, .. }),
                None | Some(XyceMeasurementReferenceValue::Failed),
            ) => Err(format!(
                "mixed measurement artifact expects {probe}={value} at row {row}, but evaluation omitted it"
            )),
            (Some(expected), Some(actual)) => Self::compare_mixed_measurement_value(
                mismatches, row, probe, expected, actual, tolerance,
            ),
            (None, Some(XyceMeasurementReferenceValue::Failed)) => Ok(()),
        }
    }

    fn compare_continuous_measurement_value(
        mismatches: &mut Vec<XyceValueMismatch>,
        row: usize,
        probe: &str,
        expected: XyceMeasurementReferenceValue,
        actual: Option<Value>,
        tolerance: XyceFileCompareTolerance,
    ) -> Result<(), String> {
        match (expected, actual) {
            (XyceMeasurementReferenceValue::Failed, None) => Ok(()),
            (XyceMeasurementReferenceValue::Failed, Some(actual)) => Err(format!(
                "continuous artifact has no {probe} metadata at row {row}, but evaluation produced {actual}"
            )),
            (
                XyceMeasurementReferenceValue::Numeric {
                    value,
                    quantization,
                },
                Some(actual),
            ) => {
                if !Self::measurement_value_matches(value, actual, quantization, tolerance) {
                    let absolute_error = (value - actual).abs();
                    mismatches.push(XyceValueMismatch {
                        row,
                        probe: probe.to_string(),
                        expected: value,
                        actual,
                        relative_error: if value == 0.0 {
                            f64::INFINITY
                        } else {
                            absolute_error / value.abs()
                        },
                    });
                }
                Ok(())
            }
            (XyceMeasurementReferenceValue::Numeric { value, .. }, None) => Err(format!(
                "continuous artifact expects {probe}={value} at row {row}, but evaluation omitted it"
            )),
        }
    }

    fn measurement_value_matches(
        expected: Value,
        actual: Value,
        quantization: Option<Value>,
        tolerance: XyceFileCompareTolerance,
    ) -> bool {
        if !expected.is_finite() || !actual.is_finite() {
            return false;
        }
        let absolute_error = (expected - actual).abs();
        let both_zero = expected.abs() <= tolerance.zero && actual.abs() <= tolerance.zero;
        let relative_error = if expected == 0.0 {
            f64::INFINITY
        } else {
            absolute_error / expected.abs()
        };
        let within_printed_quantization =
            quantization.is_some_and(|unit| absolute_error <= unit * 0.5);
        expected == actual
            || both_zero
            || within_printed_quantization
            || (absolute_error < tolerance.absolute && relative_error < tolerance.relative)
    }

    fn measurement_literal_quantization(raw: &str) -> Option<Value> {
        let raw = raw.trim();
        let exponent_index = raw.find(['e', 'E']);
        let (mantissa, exponent) = if let Some(index) = exponent_index {
            let exponent = raw.get(index + 1..)?.parse::<i32>().ok()?;
            (raw.get(..index)?, exponent)
        } else {
            (raw, 0)
        };
        let unsigned = mantissa.strip_prefix(['+', '-']).unwrap_or(mantissa);
        let (integer, fraction) = unsigned.split_once('.')?;
        if integer.is_empty()
            || !integer.bytes().all(|byte| byte.is_ascii_digit())
            || !fraction.bytes().all(|byte| byte.is_ascii_digit())
        {
            return None;
        }
        let fractional_digits = i32::try_from(fraction.len()).ok()?;
        let decimal_exponent = exponent.checked_sub(fractional_digits)?;
        let quantization = 10.0_f64.powi(decimal_exponent);
        (quantization.is_finite() && quantization > 0.0).then_some(quantization)
    }

    fn parse_prn_file(path: &Path) -> Result<XycePrnTable, String> {
        let content =
            fs::read_to_string(path).map_err(|err| format!("{}: {err}", path.display()))?;
        Self::parse_prn_table(&content)
    }

    fn parse_ac_comparator_prn_file(path: &Path) -> Result<XycePrnTable, String> {
        let content =
            fs::read_to_string(path).map_err(|err| format!("{}: {err}", path.display()))?;
        if content.is_empty() {
            return Err(format!("{} is empty", path.display()));
        }
        let last_nonempty = content.lines().rev().find(|line| !line.trim().is_empty());
        if last_nonempty.map(str::trim) != Some("End of Xyce(TM) Simulation") {
            return Err(format!(
                "{} has no exact ACComparator footer 'End of Xyce(TM) Simulation'",
                path.display()
            ));
        }
        Self::parse_prn_table(&content)
    }

    fn parse_dc_reference_file(
        contract: XyceStaticDcContract,
        path: &Path,
    ) -> Result<XycePrnTable, String> {
        match contract {
            XyceStaticDcContract::WrapperRaw => Self::parse_raw_file(path),
            XyceStaticDcContract::PlainCsv | XyceStaticDcContract::WrapperCsv => {
                Self::parse_csv_file(path)
            }
            XyceStaticDcContract::PlainCsd | XyceStaticDcContract::WrapperCsd => {
                Self::parse_csd_file(path)
            }
            _ => Self::parse_prn_file(path),
        }
    }

    fn parse_ac_reference_file(
        contract: XyceStaticAcContract,
        path: &Path,
    ) -> Result<XycePrnTable, String> {
        match contract {
            XyceStaticAcContract::PlainCsd | XyceStaticAcContract::WrapperCsd => {
                Self::parse_ac_csd_file(path)
            }
            _ => Self::parse_prn_file(path),
        }
    }

    fn parse_tran_reference_file(
        contract: XyceStaticTranContract,
        path: &Path,
    ) -> Result<XycePrnTable, String> {
        match contract {
            XyceStaticTranContract::PlainCsv | XyceStaticTranContract::WrapperCsv => {
                Self::parse_csv_file(path)
            }
            XyceStaticTranContract::PlainCsd | XyceStaticTranContract::WrapperCsd => {
                Self::parse_tran_csd_file(path)
            }
            _ => Self::parse_tran_prn_or_legacy_probe_file(path),
        }
    }

    fn parse_xyce_verify_tran_reference_file(path: &Path) -> Result<XycePrnTable, String> {
        let content =
            fs::read_to_string(path).map_err(|err| format!("{}: {err}", path.display()))?;
        Self::parse_xyce_verify_tran_reference_table(&content)
    }

    fn parse_xyce_verify_tran_reference_table(content: &str) -> Result<XycePrnTable, String> {
        let first_classified_line = content
            .lines()
            .find(|line| !line.is_empty())
            .ok_or_else(|| "empty Release 7.10 xyce_verify transient input".to_string())?;
        let first_header = first_classified_line.trim();
        if Self::prn_header_delimiter(first_header) != Some(XycePrnDelimiter::Whitespace) {
            return Err(
                "Release 7.10 xyce_verify transient input must begin with an indexed STD PRN header"
                    .to_string(),
            );
        }
        let first_columns = Self::parse_prn_columns(first_header, XycePrnDelimiter::Whitespace)?;
        if first_columns.first().map(String::as_str) != Some("Index") {
            return Err(
                "Release 7.10 xyce_verify transient input must begin with an indexed STD PRN header"
                    .to_string(),
            );
        }
        let table = Self::parse_prn_table(content)?;
        let header_index = content
            .lines()
            .position(|line| Self::is_prn_header_line(line.trim()))
            .expect("a parsed PRN table has a header");
        if !content
            .lines()
            .skip(header_index + 1)
            .any(|line| line.contains("End of Xyce"))
        {
            return Err(
                "Release 7.10 xyce_verify transient input has no normal 'End of Xyce' completion footer"
                    .to_string(),
            );
        }
        Ok(table)
    }

    fn parse_tran_prn_or_legacy_probe_file(path: &Path) -> Result<XycePrnTable, String> {
        let content =
            fs::read_to_string(path).map_err(|err| format!("{}: {err}", path.display()))?;
        Self::parse_tran_prn_or_legacy_probe_table(&content)
    }

    fn parse_tran_prn_or_legacy_probe_table(content: &str) -> Result<XycePrnTable, String> {
        let first_nonempty = content.lines().map(str::trim).find(|line| !line.is_empty());
        if first_nonempty.is_some_and(|line| line.eq_ignore_ascii_case("#H")) {
            return Self::parse_tran_csd_table(content);
        }
        Self::parse_prn_table(content)
    }

